const a="https://www.churchofjesuschrist.org/study/scriptures",n=JSON.parse('[{"id":"doctrine-and-covenants","title":"Doktrina ug mga Pakigsaad","englishTitle":"Doctrine and Covenants","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga katawhan sa akong simbahan, nag-ingon ang tingog niya nga nagpuyo sa kahitas-an, ug kansang mga mata nagtan-aw sa tanang tawo; oo, sa pagkatinuod ako moingon: Patalinghog kamo nga katawhan gikan sa layo; ug kamo nga anaa sa mga isla sa kadagatan, paminaw kamong tanan."},{"verse":2,"text":"Kay sa pagkatinuod ang tingog sa Ginoo modangat ngadto sa tanang tawo, ug walay tawo nga makalingkawas; ug walay mata nga dili makakita, ni dunggan nga dili makadungog, ni kasingkasing nga dili matandog."},{"verse":3,"text":"Ug ang mga masupilon hasolon sa tuman nga kagul-anan; kay ang ilang mga pagkadaotan ipamulong sa ibabaw sa mga atop sa kabalayan, ug ang ilang tinago nga mga buhat ipadayag."},{"verse":4,"text":"Ug ang tingog sa pagpasidaan modangat ngadto sa tanang katawhan, pinaagi sa mga ba-ba sa akong mga tinun-an, kinsa akong gipili niining kataposang mga adlaw."},{"verse":5,"text":"Ug molakaw sila ug walay makapugong kanila, kay ako ang Ginoo nagmando kanila."},{"verse":6,"text":"Tan-awa, kini akong awtoridad, ug awtoridad sa akong mga sulugoon, ug akong pasiunang mga pulong ngadto sa basahon sa mga sugo, nga akong gihatag kanila aron imantala alang kaninyo, O mga lumulupyo sa yuta."},{"verse":7,"text":"Mao nga, kahadloki ug pangurog, O kamo nga katawhan, kay kon unsa ang akong gimando, kini matuman."},{"verse":8,"text":"Ug sa pagkatinuod sultihan ko kamo, nga sila kinsa nagsangyaw, nga nagdala niining mga balita ngadto sa mga lumulupyo sa yuta, sila gihatagan sa gahom sa pagselyo dinhi sa yuta ug didto sa langit, ngadto sa mga dili matuohon ug sa mga masupilon;"},{"verse":9,"text":"Oo, sa pagkatinuod, sa pagselyo kanila ngadto sa adlaw nga ang kapungot sa Dios mabu-bo ngadto sa mga daotan sa walay sukod—"},{"verse":10,"text":"Alang sa adlaw kon moanhi na ang Ginoo aron moganti sa matag tawo sumala sa iyang binuhatan, ug mosukod sa matag tawo sumala sa iyang gihimo nga pagsukod ngadto sa iyang isigkatawo."},{"verse":11,"text":"Mao nga ang tingog sa Ginoo modangat ngadto sa kinatumyan sa yuta, aron ang tanan nga maminaw makadungog:"},{"verse":12,"text":"Pangandam kamo, pangandam kamo alang niana nga moabot, kay ang Ginoo duol na;"},{"verse":13,"text":"Ug ang kasuko sa Ginoo midilaab, ug ang iyang espada giandam didto sa langit, ug kini mahulog ngadto sa mga lumulupyo sa yuta."},{"verse":14,"text":"Ug ang kamot sa Ginoo ipadayag; ug moabot ang adlaw nga sila kinsa dili maminaw sa tingog sa Ginoo, ni sa tingog sa iyang mga sulugoon, ni mopatalinghog sa mga pulong sa mga propeta ug apostoles, ipahimulag gikan sa katawhan;"},{"verse":15,"text":"Kay nahisalaag sila gikan sa akong mga ordinansa, ug gilapas ang akong walay kataposang pakigsaad;"},{"verse":16,"text":"Wala sila mangita sa Ginoo aron ipatuman ang iyang pagkamatarong, apan ang matag tawo naglakaw sa iyang kaugalingong pamaagi, ug sumala sa hulagway sa iyang kaugalingong dios kansang hulagway kaparehas sa kalibotan, ug kansang kinaiyahan sama sa dios-dios, nga mag-anam og katigulang ug mamatay sa Babilonia, gani ang gamhanan nga Babilonia, mapukan."},{"verse":17,"text":"Mao nga, ako ang Ginoo, kay nahibalo sa katalagman nga moabot sa mga lumulupyo sa yuta, mitawag sa akong sulugoon nga si Joseph Smith, Jun., ug namulong ngadto kaniya gikan sa langit, ug mihatag kaniya og mga sugo;"},{"verse":18,"text":"Ug usab mihatag og mga sugo ngadto sa uban, nga sila mosangyaw gayod niini nga mga butang ngadto sa kalibotan; ug aron matuman kining tanan, nga gisulat sa mga propeta—"},{"verse":19,"text":"Ang huyang nga mga butang sa kalibotan moabot ug mopukan sa mga gamhanan ug mga malig-on, aron ang tawo dili motambag sa iyang isigkatawo, ni mosalig sa gahom sa unod—"},{"verse":20,"text":"Apan nga ang matag tawo makapamulong sa ngalan sa Dios ang Ginoo, gani ang Manluluwas sa kalibotan;"},{"verse":21,"text":"Aron ang pagtuo usab madugangan dinhi sa yuta;"},{"verse":22,"text":"Aron ang akong walay kataposan nga pakigsaad unta mapatuman;"},{"verse":23,"text":"Aron ang kinatibuk-an sa akong ebanghelyo mapahayag pinaagi sa huyang ug sa yano ngadto sa kinatumyan sa kalibotan, ug sa atubangan sa mga hari ug mga magmamando."},{"verse":24,"text":"Tan-awa, ako ang Dios ug namulong niini; kini nga mga sugo gikan kanako, ug gihatag ngadto sa akong mga sulugoon diha sa ilang kahuyang, sumala sa ilang pinulongan, aron sila makasabot."},{"verse":25,"text":"Ug maingon nga sila nasayop kini ipahibalo;"},{"verse":26,"text":"Ug maingon nga nagtinguha sila og kaalam sila pagatudloan;"},{"verse":27,"text":"Ug maingon nga nakasala sila pagapantonon sila, aron sila maghinulsol;"},{"verse":28,"text":"Ug maingon nga nagpaubos sila himoon sila nga lig-on, ug panalanginan sa kahitas-an, ug makadawat og kahibalo sa matag karon ug unya."},{"verse":29,"text":"Ug human makadawat sa talaan sa mga Nephita, oo, gani ang akong sulugoon nga si Joseph Smith, Jun., makabaton og gahom sa paghubad pinaagi sa kaluoy sa Dios, pinaagi sa gahom sa Dios, sa Basahon ni Mormon."},{"verse":30,"text":"Ug usab kadtong gihatagan niini nga mga sugo, makaangkon og gahom sa pagpahiluna sa katukoran niini nga simbahan, ug sa pagdala niini gikan sa kangiob ug gikan sa kangitngit, ang nag-inusara nga tinuod ug buhi nga simbahan sa ibabaw sa tibuok yuta, nga ako, ang Ginoo, nahimuot kaayo, namulong ngadto sa tibuok simbahan ug dili sa tinagsa-tagsa—"},{"verse":31,"text":"Kay ako ang Ginoo dili makatan-aw sa sala bisan sa labing gamay lamang nga pagtugot;"},{"verse":32,"text":"Bisan pa niana, siya nga maghinulsol ug magatuman sa mga sugo sa Ginoo mapasaylo;"},{"verse":33,"text":"Ug siya nga dili maghinulsol, gikan kaniya pagakuhaon bisan ang kahayag nga iyang nadawat; kay ang akong Espiritu dili sa kanunay makig-uban sa tawo, nag-ingon ang Ginoo sa mga Panon."},{"verse":34,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, O mga lumulupyo sa yuta: ako ang Ginoo andam sa paghimo niini nga mga butang aron mahibaloan sa tanan nga katawhan;"},{"verse":35,"text":"Kay ako walay gipalabi sa mga tawo, ug nagtinguha nga ang tanang tawo masayod nga ang adlaw moabot sa labing madali; ang takna wala pa moabot, apan duol na, nga ang kalinaw pagakuhaon gikan sa yuta, ug ang yawa makabaton og gahom ibabaw sa iyang kaugalingong kamandoan."},{"verse":36,"text":"Ug usab ang Ginoo makabaton og gahom sa iyang mga santos, ug magmando sa ilang taliwala, ug manaog sa paghukom sa Idumea, o sa kalibotan."},{"verse":37,"text":"Tun-i kini nga mga sugo, kay tinuod kini ug matinud-anon, ug ang mga panagna ug mga saad nga anaa niini ang tanan matuman."},{"verse":38,"text":"Ako nga Ginoo, kon unsa man ang akong gipamulong, gipamulong ko na, ug dili ako mangayo og pasaylo sa akong gipamulong; ug bisan pa ang kalangitan ug ang yuta mahanaw, ang akong pulong dili mahanaw, apan ang tanan matuman, bisan pinaagi man sa akong kaugalingong tingog o pinaagi sa tingog sa akong mga sulugoon, managsama ra kini."},{"verse":39,"text":"Kay tan-awa, ug sud-onga, ang Ginoo mao ang Dios, ug ang Espiritu nagpamatuod, ug ang pagpamatuod tinuod, ug ang kamatuoran magpabilin hangtod sa kahangtoran. Amen."}]},{"chapter":2,"verses":[{"verse":1,"text":"Tan-awa, ako mopadayag kaninyo sa Pagkapari, pinaagi sa kamot ni Elijah ang propeta, sa dili pa moabot ang mahinungdanon ug makalilisang nga adlaw sa Ginoo."},{"verse":2,"text":"Ug iyang itanom diha sa mga kasingkasing sa mga anak ang mga saad nga gihimo ngadto sa mga amahan, ug ang mga kasingkasing sa mga anak mobalik ngadto sa ilang mga amahan."},{"verse":3,"text":"Kon dili pa tungod niini, ang tibuok kalibotan hingpit nga malaglag sa iyang pag-abot."}]},{"chapter":3,"verses":[{"verse":1,"text":"Ang mga buhat, ug mga laraw, ug ang mga katuyoan sa Dios dili gayod mapakyas, ni kini makawang."},{"verse":2,"text":"Kay ang Dios dili molakaw sa hiwi nga mga dalan, ni siya moliko padulong sa tuo ni sa wala, ni siya mosimang gikan sa iyang nasulti, busa ang iyang mga dalan tul-id ug ang iyang katuyoan nagsubay sa usa ka mahangtorong agianan nga walay pagkausab."},{"verse":3,"text":"Hinumdomi, hinumdomi nga dili ang buhat sa Dios ang mapakyas, apan ang buhat sa mga tawo;"},{"verse":4,"text":"Kay bisan pa kon ang tawo adunay daghang pagpadayag, ug adunay gahom sa pagbuhat sa daghang gamhanan nga mga buhat, apan kon siya manghambog sa iyang kaugalingong kusog, ug mobaliwala sa mga tambag sa Dios, ug mosunod sa mga mando sa iyang kaugalingong kabubut-on ug sa lawasnong mga tinguha, siya mapukan gayod ug mahiagom sa panimalos sa makiangayon nga Dios nganha kaniya."},{"verse":5,"text":"Tan-awa, gitugyanan ikaw niini nga mga butang, apan pagkahigpit sa imong mga sugo; ug hinumdomi usab ang mga saad nga gihimo nganha kanimo, kon ikaw wala makalapas niini."},{"verse":6,"text":"Ug tan-awa, pagkadaghang higayon nga ikaw nakalapas sa mga sugo ug sa mga balaod sa Dios, ug nadala sa mga pagdani sa mga tawo."},{"verse":7,"text":"Kay, tan-awa, wala unta nimo kahadloki ang tawo kay sa Dios. Bisan pa kon ang mga tawo mibaliwala sa mga tambag sa Dios, ug mitamay sa iyang mga pulong—"},{"verse":8,"text":"Bisan pa, angay unta nga ikaw nagmatinud-anon; ug siya unta mitunol sa iyang bukton ug mitabang kanimo batok sa tanang nagdilaab nga mga pana sa kaaway; ug nakig-uban unta siya kanimo sa matag panahon sa kasamok."},{"verse":9,"text":"Tan-awa, ikaw si Joseph, ug ikaw gipili sa pagbuhat sa buluhaton sa Ginoo, apan tungod sa kalapasan, kon dili ikaw magmabinantayon ikaw mapukan."},{"verse":10,"text":"Apan hinumdomi, maluluy-on ang Dios; busa, hinulsoli kana nga imong nabuhat nga supak sa sugo nga akong gihatag kanimo, ug ikaw pinili sa gihapon, ug sa makausa pa tawagon ikaw ngadto sa buhat;"},{"verse":11,"text":"Gawas kon imo kining buhaton, ikaw pagabiyaan ug mahimo nga sama sa ubang mga tawo, ug dili na makabaton og gasa."},{"verse":12,"text":"Ug kon itugyan nimo sa uban kini nga butang nga gipakita kanimo sa Dios ug gihatagan ka og gahom sa paghubad, imong gitugyan kanang butang nga sagrado ngadto sa mga kamot sa tawo nga daotan,"},{"verse":13,"text":"Kinsa nagbaliwala sa mga tambag sa Dios, ug nakalapas sa labing sagrado nga mga saad nga gihimo sa atubangan sa Dios, ug misalig sa iyang kaugalingong paghukom ug nagpasigarbo sa iyang kaugalingong kaalam."},{"verse":14,"text":"Ug kini ang hinungdan nga ikaw nawad-an sa imong mga kahigayonan sulod sa usa ka panahon—"},{"verse":15,"text":"Kay imong gitugotan ang tambag sa imong magmamando nga pagatunob-tunoban gikan sa sinugdanan."},{"verse":16,"text":"Bisan pa niana, ang akong buhat magpadayon, kay sama nga ang kahibalo sa Manluluwas miabot sa kalibotan, pinaagi sa pagpamatuod sa mga Judeo, sa samang paagi ang kahibalo mahitungod sa Manluluwas moabot sa akong katawhan—"},{"verse":17,"text":"Ug ngadto sa mga Nephita, ug sa mga Jacobita, ug sa mga Josephita, ug sa mga Zoramita, pinaagi sa pagpamatuod sa ilang mga amahan—"},{"verse":18,"text":"Ug kini nga pagpamatuod mahibaloan sa mga Lamanita, ug sa mga Lemuelita, ug sa mga Ishmaelita, kinsa mikunhod sa pagkawalay pagtuo tungod sa pagkadaotan sa ilang mga amahan, kinsa gitugotan sa Ginoo nga molaglag sa kaigsoonan nilang mga Nephita, tungod sa ilang mga pagkadaotan ug sa ilang mga pagkasalawayon."},{"verse":19,"text":"Ug tungod niining piho nga katuyoan kining mga palid gitipigan, nga naglangkob niining mga talaan—nga ang mga saad sa Ginoo matuman, nga iyang gihimo ngadto sa iyang katawhan;"},{"verse":20,"text":"Ug nga ang mga Lamanita unta makaangkon og kasayoran mahitungod sa ilang mga amahan, ug nga sila mahibalo sa mga saad sa Ginoo, ug nga sila motuo sa ebanghelyo ug mosalig sa mga kamaayo ni Jesukristo, ug pagahimayaon pinaagi sa pagtuo sa iyang ngalan, ug nga pinaagi sa ilang paghinulsol maluwas sila. Amen."}]},{"chapter":4,"verses":[{"verse":1,"text":"Karon tan-awa, ang katingalahan nga buhat hapit na moabot ngadto sa mga anak sa mga tawo."},{"verse":2,"text":"Busa, O kamo nga magsugod sa pag-alagad sa Dios, tan-awa nga kamo moalagad kaniya sa tibuok ninyong kasingkasing, gahom, hunahuna ug kusog, nga kamo magbarog nga walay kasaypanan sa atubangan sa Dios sa kataposang adlaw."},{"verse":3,"text":"Busa, kon kamo adunay tinguha sa pag-alagad sa Dios, kamo gitawag ngadto sa buhat;"},{"verse":4,"text":"Kay tan-awa ang umahan puti ug andam na nga anihon; ug tan-awa, siya nga mogalab sa iyang sanggot nga makusganon, sama ra nga nagtipig siya aron dili siya malaglag, apan magdala og kaluwasan ngadto sa iyang kalag;"},{"verse":5,"text":"Ug ang pagtuo, paglaom, gugmang putli ug gugma, inubanan sa panan-aw nga nakatutok sa himaya sa Dios, mohimo kaniya nga takos alang sa buhat."},{"verse":6,"text":"Hinumdomi ang pagtuo, hiyas, kahibalo, pagpugong sa kaugalingon, pailob, inigsoon nga pagkamabination, pagkadiosnon, gugmang putli, pagkamapainubsanon, kakugi."},{"verse":7,"text":"Pangayo, ug makadawat kamo; panuktok, ug kini pagaablihan nganha kaninyo. Amen."}]},{"chapter":5,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko ikaw, nga sanglit ang akong sulugoon nga si Martin Harris nagtinguha og panghimatuod gikan kanako, nga ikaw, akong sulugoong Joseph Smith, Jun., naghupot sa mga palid nga imong gipanghimatuod ug gipahayag nga imong nadawat gikan kanako;"},{"verse":2,"text":"Ug karon, tan-awa, kini ang imong isulti ngadto kaniya—siya kinsa namulong nganha kanimo, misulti kanimo: Ako, ang Ginoo, mao ang Dios, ug naghatag niini nga mga butang nganha kanimo, akong sulugoong Joseph Smith, Jun., ug nagsugo kanimo nga ikaw mobarog nga saksi niini nga mga butang;"},{"verse":3,"text":"Ug akong gihimo nga ikaw mosulod og pakigsaad ngari kanako, nga dili nimo kini ipakita gawas niadto nga mga tawo kinsa akong gimando kanimo; ug ikaw walay gahom ibabaw niini gawas kon kini akong ihatag kanimo."},{"verse":4,"text":"Ug ikaw adunay gasa sa paghubad sa mga palid; ug mao kini ang unang gasa nga akong gitugyan diha kanimo; ug ako misugo nga ikaw dili na mangangkon og laing gasa hangtod nga ang akong katuyoan matuman dinhi niini; kay ako dili motugyan kanimo og laing gasa hangtod nga matapos kini."},{"verse":5,"text":"Sa pagkatinuod, sultihan ko ikaw, nga ang kaalaot moabot nganha sa mga lumulupyo sa yuta kon sila dili mopatalinghog sa akong mga pulong;"},{"verse":6,"text":"Kay human niini ikaw ordinahan ug molakaw ug mosangyaw sa akong mga pulong ngadto sa mga anak sa katawhan."},{"verse":7,"text":"Tan-awa, kon dili sila motuo sa akong mga pulong, dili sila motuo kanimo, akong sulugoong Joseph, kon posible man nga ikaw mopakita kanila sa tanan niining mga butanga nga akong gitugyan diha kanimo."},{"verse":8,"text":"O, kini nga dili matuohon ug tikig og liog nga henerasyon—ang akong kasuko nagdilaab batok kanila."},{"verse":9,"text":"Tan-awa, sa pagkatinuod sultihan ko ikaw, akong gigahin kadtong mga butang nga akong gisalig kanimo, akong sulugoong Joseph, alang sa maalamon nga katuyoan ngari kanako, ug ipahibalo kini ngadto sa umaabot nga mga henerasyon;"},{"verse":10,"text":"Apan kini nga henerasyon makadawat sa akong pulong pinaagi kanimo;"},{"verse":11,"text":"Ug dugang pa sa imong pagpamatuod, ang pagpamatuod sa tulo sa akong mga sulugoon, kinsa akong tawagon ug i-orden, ngadto kanila kinsa akong pakit-on niining mga butanga, ug molakaw sila nga magdala sa akong mga pulong nga gihatag pinaagi kanimo."},{"verse":12,"text":"Oo, seguradong masayod sila nga kining mga butanga tinuod, kay gikan sa langit akong ipahayag kini ngadto kanila."},{"verse":13,"text":"Hatagan ko sila og gahom nga sila makakita ug makasud-ong niini nga mga butang kon unsa gayod kini;"},{"verse":14,"text":"Ug walay laing tawo nga akong tugyanan niini nga gahom, sa pagdawat niining sama nga pagpamatuod taliwala niini nga henerasyon, niini nga sinugdanan sa pagtubo ug sa pagtungha sa akong simbahan gikan sa kamingawan—tin-aw sama sa bulan, ug matahom sama sa adlaw, ug makalilisang sama sa kasundalohan nga nagdala og mga bandila."},{"verse":15,"text":"Ug ang pagpamatuod sa tulo ka saksi sa akong pulong akong ipahibalo."},{"verse":16,"text":"Ug tan-awa, kinsa kadtong motuo sa akong mga pulong, sila akong duawon pinaagi sa pagpadayag sa akong Espiritu; ug matawo sila kanako, gani sa tubig ug sa Espiritu—"},{"verse":17,"text":"Ug ikaw kinahanglan maghulat una sa makadiyot, kay ikaw wala pa maordinahi—"},{"verse":18,"text":"Ug ang ilang pagpamatuod mosangpot usab ngadto sa pagpanghimaraot niini nga henerasyon kon sila magpatig-a sa ilang mga kasingkasing batok kanila;"},{"verse":19,"text":"Kay ang makalaglag nga silot modangat ngadto sa mga lumulupyo sa yuta, ug magpadayon nga ibu-bo sa matag karon ug unya, kon dili sila maghinulsol, hangtod ang yuta mahaw-ang, ug ang mga lumulupyo niini mahanaw ug malaglag sa hingpit pinaagi sa kahayag sa akong pag-anhi."},{"verse":20,"text":"Tan-awa, sultihan ko ikaw niining mga butanga, sama usab sa akong gisulti sa katawhan mahitungod sa pagkalaglag sa Jerusalem; ug ang akong pulong mapamatud-an niini nga panahon sama nga kini napamatud-an sukad pa kaniadto."},{"verse":21,"text":"Ug karon ako magsugo kanimo, akong sulugoong Joseph, sa paghinulsol ug sa paglakaw nga mas matarong sa akong atubangan, ug dili magpadala sa mga pagdani sa mga tawo;"},{"verse":22,"text":"Ug nga ikaw magmalig-on sa paghupot sa mga sugo nga akong gisugo kanimo; ug kon imo kining buhaton, tan-awa ako mohatag kanimo og kinabuhing dayon, bisan kon ikaw patyon."},{"verse":23,"text":"Ug karon, usab, sultihan ko ikaw, akong sulugoong Joseph, kabahin sa tawo nga nagtinguha sa pagpamatuod—"},{"verse":24,"text":"Tan-awa, sultihan ko siya, gihimaya niya ang iyang kaugalingon ug wala siya magpaubos sa iyang kaugalingon sa tukmang paagi sa akong atubangan; apan kon moyukbo siya sa akong atubangan, ug magpaubos sa iyang kaugalingon pinaagi sa kinasingkasing nga pag-ampo ug pagtuo, sa pagkamatinud-anon sa iyang kasingkasing, niana siya akong tugotan nga makakita sa mga butang nga iyang gitinguha nga makita."},{"verse":25,"text":"Ug unya mosulti siya ngadto sa katawhan niini nga henerasyon: Tan-awa, akong nakita ang mga butang nga gipakita sa Ginoo ngadto ni Joseph Smith, Jun., ug ako nasayod ug nakaseguro gayod nga kini tinuod, kay ako nakakita niini, kay kini gipakita ngari kanako pinaagi sa gahom sa Dios ug dili pinaagi sa tawo."},{"verse":26,"text":"Ug ako ang Ginoo mosugo kaniya, akong sulugoon nga si Martin Harris, nga siya dili na mosulti ngadto kanila kabahin niini nga mga butang, gawas kon siya mosulti: Ako nakakita niini, ug kini gipakita ngari kanako pinaagi sa gahom sa Dios; ug kini ang mga pulong nga iyang isulti."},{"verse":27,"text":"Apan kon molimod siya niini makalapas siya sa pakigsaad nga kanhi iyang gipakigsaad ngari kanako, ug tan-awa, ipanghimaraot siya."},{"verse":28,"text":"Ug karon, gawas kon magpaubos siya sa iyang kaugalingon ug motug-an kanako sa mga butang nga iyang nabuhat nga mga sayop, ug makigsaad kanako nga siya maghupot sa akong mga sugo, ug magpakita og pagtuo ngari kanako, tan-awa, sultihan ko siya nga dili siya makakita niini, kay ako dili mohatag kaniya og pagtugot nga makakita sa mga butang nga akong gipamulong."},{"verse":29,"text":"Ug kon mao man kini ang mahitabo, ako mosugo kanimo, akong sulugoong Joseph, nga ikaw mosulti ngadto kaniya, nga siya dili na magpadayon sa pagbuhat, ni magsamok kanako pag-usab niini nga butang."},{"verse":30,"text":"Ug kon mao man kini ang mahitabo, tan-awa, sultihan ko ikaw Joseph, human ikaw makahubad og pipila pa ka pahina mohunong ka sa mubo nga panahon, hangtod nga ako mosugo na usab kanimo; human niana ikaw mahimo na usab nga mohubad."},{"verse":31,"text":"Ug gawas kon buhaton nimo kini, tan-awa, mawad-an ka og gasa, ug akong kuhaon ang mga butang nga akong gitugyan diha kanimo."},{"verse":32,"text":"Ug karon, tungod kay ako nakapanglantaw na nga adunay naghulat sa tago aron sa paglaglag kanimo, oo, akong nalantaw nga kon ang akong sulugoon nga si Martin Harris dili magpaubos sa iyang kaugalingon ug modawat og pagpamatuod gikan sa akong kamot, nga siya mahulog sa kalapasan;"},{"verse":33,"text":"Ug adunay daghan nga naghulat sa tago aron sa paglaglag kanimo gikan sa ibabaw sa yuta; ug tungod niini nga hinungdan, nga ang imong mga adlaw malugwayan, ako mihatag kanimo niining mga sugo."},{"verse":34,"text":"Oo, kay tungod niini nga hinungdan misulti ako: Hunong, ug ayaw paglihok hangtod nga ako mosugo kanimo, ug mohatag ako og mga paagi diin ikaw makatuman sa butang nga akong gisugo kanimo."},{"verse":35,"text":"Ug kon ikaw matinud-anon sa paghupot sa akong mga sugo, ikaw pagabayawon sa kataposan nga adlaw. Amen."}]},{"chapter":6,"verses":[{"verse":1,"text":"Ang usa ka mahinungdanon ug katingalahan nga buhat hapit na moabot ngadto sa mga anak sa katawhan."},{"verse":2,"text":"Tan-awa, ako ang Dios; paminaw sa akong pulong nga abtik ug gamhanan, mas hait pa kay sa espada nga duhay suwab, nga mopahimulag sa mga kalutahan ug kauyokan; busa paminaw sa akong mga pulong."},{"verse":3,"text":"Tan-awa, ang umahan puti ug andam na nga anihon; busa, kinsa kadtong nagtinguha sa pag-ani, tugoti nga siya mogalab sa iyang sanggot nga makusganon, ug mag-ani samtang adlawan pa, nga siya motipig alang sa iyang kalag sa walay kataposang kaluwasan didto sa gingharian sa Dios."},{"verse":4,"text":"Oo, kinsa kadtong mogalab sa iyang sanggot ug moani, siya gitawag sa Dios."},{"verse":5,"text":"Busa, kon kamo mangayo kanako kamo makadawat; kon kamo motuktok kini pagaablihan alang kaninyo."},{"verse":6,"text":"Karon, kay ikaw nangayo, tan-awa, sultihan ko ikaw, hupti ang akong mga sugo, ug tinguhaa ang pagpahitabo ug pagpalig-on sa katuyoan sa Zion;"},{"verse":7,"text":"Ayaw pangita sa mga katigayonan apan sa kaalam, ug tan-awa, ang mga misteryo sa Dios pagaablihan diha kanimo, ug unya ikaw himoon nga adunahan. Tan-awa, siya nga adunay kinabuhing dayon adunahan."},{"verse":8,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, sama sa imong gitinguha gikan kanako kini mahitabo diha kanimo; ug kon ikaw magtinguha, mamahimo ikaw nga paagi sa pagbuhat og daghan nga kaayohan niini nga henerasyon."},{"verse":9,"text":"Ayaw pagsulti og lain gawas sa paghinulsol ngadto niini nga henerasyon; huptitumana ang akong mga sugo, ug motabang sa pagpahitabo sa akong buhat, sumala sa akong mga sugo, ug ikaw panalanginan."},{"verse":10,"text":"Tan-awa ikaw adunay gasa, ug bulahan ka tungod sa imong gasa. Hinumdomi nga sagrado kini ug naggikan sa kahitas-an—"},{"verse":11,"text":"Ug kon ikaw mangutana, ikaw masayod sa mga misteryo nga mahinungdanon ug katingalahan; busa gamita ang imong gasa, nga ikaw makakaplag og mga misteryo, nga ikaw makadala og daghan ngadto sa kasayoran sa kamatuoran, oo, mokombinsir kanila sa ilang sayop nga pamaagi."},{"verse":12,"text":"Ayaw ipahibalo ang imong gasa ngadto ni bisan kinsa gawas lang ngadto sa parehas kanimo og pagtuo. Ayaw pagtiaw-tiaw sa sagradong mga butang."},{"verse":13,"text":"Kon ikaw magbuhat og maayo, oo, ug magpabilin nga matinud-anon hangtod sa kataposan, ikaw pagaluwason ngadto sa gingharian sa Dios; nga mao ang labing mahinungdanon sa tanang gasa sa Dios; kay walay gasa nga labaw pa kay sa gasa sa kaluwasan."},{"verse":14,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, bulahan ka tungod sa imong nabuhat; kay ikaw nagpakisayod gikan kanako, ug tan-awa, sa makadaghan nga ikaw nagpakisayod ikaw nakadawat og panudlo gikan sa akong Espiritu. Kon dili pa tungod niana, wala unta ikaw moabot sa dapit diin ikaw anaa niining panahona."},{"verse":15,"text":"Tan-awa, nasayod ka nga ikaw nagpakisayod kanako ug ako milamdag sa imong hunahuna; ug karon sultihan ko ikaw niining mga butanga nga unta ikaw mahibalo nga nalamdagan ka pinaagi sa Espiritu sa kamatuoran;"},{"verse":16,"text":"Oo, sultihan ko ikaw, aron ikaw mahibalo nga walay lain gawas sa Dios nga nasayod sa imong mga hunahuna ug sa mga katuyoan sa imong kasingkasing."},{"verse":17,"text":"Gisultihan ko ikaw niining mga butanga isip pagpamatuod nganha kanimo—nga ang mga pulong o ang buhat nga imong gisulat tinuod."},{"verse":18,"text":"Busa pagmakugihon; barog uban sa akong sulugoon nga si Joseph, nga matinud-anon, sa bisan unsang malisod nga mga kahimtang nga moabot kaniya tungod ug alang sa pulong."},{"verse":19,"text":"Pahimangnoi siya sa iyang mga sayop, ug usab dawata ang pahimangno gikan kaniya. Pagmapailobon; pagmaligdong; pagmapugnganon sa kaugalingon; pagbaton og pailob, pagtuo, paglaom ug gugmang putli."},{"verse":20,"text":"Tan-awa, ikaw si Oliver, ug ako nakapamulong nganha kanimo tungod sa imong mga tinguha; busa tipigi sama sa bahandi kini nga mga pulong diha sa imong kasingkasing. Pagmatinud-anon ug pagmakugihon sa pagtuman sa mga sugo sa Dios, ug gakson ko ikaw sa mga bukton sa akong gugma."},{"verse":21,"text":"Tan-awa, ako si Jesukristo, ang Anak sa Dios. Ako ang mianhi sa akong kaugalingong katawhan, ug ang akong kaugalingong katawhan wala modawat kanako. Ako ang kahayag nga nagdan-ag sa kangitngit, ug ang kangitngit wala makasabot niini."},{"verse":22,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, kon ikaw nagtinguha og dugang pa nga pagpamatuod, hinumdomi ang gabii nga ikaw misangpit ngari kanako sa kinasingkasing, aron ikaw mahibalo mahitungod sa kamatuoran niini nga mga butang."},{"verse":23,"text":"Wala ba ako mamulong og kalinaw sa imong hunahuna mahitungod niini nga butang? Unsa ang labaw pa nga pagpamatuod nga imong maangkon kay sa gikan sa Dios?"},{"verse":24,"text":"Ug karon, tan-awa, nakadawat ikaw og pagpamatuod; kay kon gisultihan ko ikaw og mga butang nga walay tawo nga nasayod wala ba ikaw makadawat og pagpamatuod?"},{"verse":25,"text":"Ug, tan-awa, hatagan ko ikaw og gasa, kon ikaw magtinguha gikan kanako, sa paghubad, gani sama sa akong sulugoon nga si Joseph."},{"verse":26,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, nga adunay mga talaan nga naglangkob sa kadaghanan sa akong ebanghelyo, nga gitagoan sa dugay nang panahon tungod sa pagkadaotan sa katawhan;"},{"verse":27,"text":"Ug karon sugoon ko ikaw, nga kon ikaw adunay maayong mga tinguha—ang tinguha sa pagtipig og mga bahandi alang sa imong kaugalingon didto sa langit—kon mao motabang ka sa pagdala ngadto sa kahayag, pinaagi sa imong gasa, niadtong mga bahin sa akong mga kasulatan nga gitagoan tungod sa pagkadaotan."},{"verse":28,"text":"Ug karon, tan-awa, hatagan ko ikaw, ug usab ang akong sulugoon nga si Joseph, sa mga yawe niini nga gasa, nga mao ang modala niini nga pangalagad ngadto sa kahayag; ug pinaagi sa ba-ba sa duha o tulo ka saksi ang matag pulong mapamatud-an."},{"verse":29,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, kon isalikway nila ang akong mga pulong, ug kini nga bahin sa akong ebanghelyo ug pangalagad, bulahan ka, kay sila dili na makabuhat pa og labaw nganha kanimo kay sa ilang nabuhat ngari kanako."},{"verse":30,"text":"Ug bisan kon ilang buhaton nganha kanimo gani ang sama sa ilang gibuhat ngari kanako, bulahan ikaw, kay ikaw magpuyo uban kanako ngadto sa himaya."},{"verse":31,"text":"Apan kon dili nila isalikway ang akong mga pulong, nga itukod pinaagi sa pagpamatuod nga ihatag, bulahan sila, ug unya ikaw makaangkon og hingpit nga kalipay sa bunga sa imong mga paghago."},{"verse":32,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, sama sa akong gisulti sa akong mga tinun-an, kon adunay duha o tulo nga nagpundok nga naghiusa sa paghisgot sa akong ngalan, nga naghisgot sa usa ka butang, tan-awa, ako anaa sa ilang taliwala—gani sama nga ako anaa sa inyong taliwala."},{"verse":33,"text":"Ayaw kahadlok sa pagbuhat og maayo, akong mga anak nga lalaki, kay bisan unsa ang inyong ipugas, kana usab ang inyong maani; busa, kon magpugas kamo og maayo kamo usab moani og maayo alang sa inyong ganti."},{"verse":34,"text":"Busa, ayaw kahadlok, gamay nga pundok; pagbuhat og maayo; tugoti nga ang yuta ug impyerno maghiusa batok kaninyo, kay kon kamo gitukod diha sa akong bato, dili sila magmadaogon."},{"verse":35,"text":"Tan-awa, wala ko kamo ipanghimaraot; padayon sa inyong inadlaw-adlaw nga panginabuhi ug ayaw na pagpakasala; buhata sa kaligdong ang buhat nga akong gisugo kaninyo."},{"verse":36,"text":"Tan-aw ngari kanako sa matag hunahuna; ayaw pagduhaduha, ayaw kahadlok."},{"verse":37,"text":"Tan-awa ang mga samad nga milapos sa akong kilid, ug usab ang mga marka sa mga lansang sa akong mga kamot ug mga tiil; pagmatinud-anon, tumana ang akong mga sugo, ug kamo makapanunod sa gingharian sa langit. Amen."}]},{"chapter":7,"verses":[{"verse":1,"text":"Ug ang Ginoo misulti ngari kanako: Juan, akong hinigugma, unsa ang imong gitinguha? Kay kon ikaw mangayo sa imong gusto, kini ihatag kanimo."},{"verse":2,"text":"Ug misulti ako kaniya: Ginoo, ihatag ngari kanako ang gahom batok sa kamatayon, aron ako mabuhi ug modala og mga kalag nganha kanimo."},{"verse":3,"text":"Ug ang Ginoo misulti kanako: Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, tungod kay ikaw nagtinguha niini ikaw magpabilin hangtod ako moabot sa akong himaya, ug managna sa atubangan sa kanasoran, kaliwatan, mga pinulongan ug katawhan."},{"verse":4,"text":"Ug tungod niini nga hinungdan gisultihan sa Ginoo si Pedro: Kon maoy akong pagbuot nga magpabilin siya hangtod sa akong pag-anhi, unsa may imong labot? Kay mihangyo siya kanako nga makadala unta siya og mga kalag ngari kanako, apan ikaw nagtinguha nga makaabot ikaw sa labing madali ngari kanako sa akong gingharian."},{"verse":5,"text":"Sultihan ko ikaw, Pedro, maayo kini nga tinguha; apan ang akong hinigugma nagtinguha nga makahimo pa siya og dugang, o mas mahinungdanon nga buhat ngadto sa mga tawo kay sa unsay iyang nabuhat sa una."},{"verse":6,"text":"Oo, nagtinguha siya og mas mahinungdanon nga buhat; busa himoon ko siyang sama sa nagdilaab nga kalayo ug tigpangalagad nga anghel; mangalagad siya alang niadtong mamahimong manununod sa kaluwasan kinsa nagpuyo sa yuta."},{"verse":7,"text":"Ug himoon ko ikaw nga mangalagad kaniya ug sa imong igsoon nga si Santiago; ug nganha kaninyong tulo akong ihatag kini nga gahom ug ang mga yawe niini nga pagpangalagad hangtod nga ako moabot."},{"verse":8,"text":"Sa pagkatinuod sultihan ko kamo, kamong duha makaangkon sumala sa inyong mga tinguha, kay kamong duha nalipay niana nga inyong gitinguha."}]},{"chapter":8,"verses":[{"verse":1,"text":"Oliver Cowdery, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, nga sama sa walay pagduhaduha nga ang Ginoo buhi, kinsa mao ang imong Dios ug ang imong Manunubos, gani sa walay pagduhaduha ikaw makadawat og kahibalo sa bisan unsang mga butang nga imong pangayoon pinaagi sa pagtuo, uban sa matinuoron nga kasingkasing, magatuo nga ikaw makadawat og kahibalo mahitungod sa mga kinulit sa daang mga talaan, nga mga karaan, nga naglakip niadtong mga bahin sa akong kasulatan nga gipamulong pinaagi sa pagpadayag sa akong Espiritu."},{"verse":2,"text":"Oo, tan-awa, ako mosulti kanimo diha sa imong hunahuna ug sa imong kasingkasing, pinaagi sa Espiritu Santo, nga moabot diha kanimo ug nga mopuyo diha sa imong kasingkasing."},{"verse":3,"text":"Karon, tan-awa, kini mao ang espiritu sa pagpadayag; tan-awa, kini mao ang espiritu diin si Moises midala sa mga anak sa Israel agi sa Pulang Dagat sa uga nga yuta."},{"verse":4,"text":"Busa, mao kini ang imong gasa; gamita kini, ug bulahan ikaw, kay moluwas kini kanimo gikan sa mga kamot sa imong mga kaaway, samtang, kon dili nimo kini gamiton, mopatay sila kanimo ug modala sa imong kalag ngadto sa kalaglagan."},{"verse":5,"text":"O, hinumdomi kining mga pulong, ug tumana ang akong mga sugo. Hinumdomi, kini mao ang imong gasa."},{"verse":6,"text":"Karon dili pa kini ang tanan nga imong gasa; kay ikaw aduna pay laing gasa, nga mao ang gasa ni Aaron; tan-awa, nakasulti kini kanimo og daghang butang;"},{"verse":7,"text":"Tan-awa, walay laing gahom, gawas sa gahom sa Dios, nga makapahimo niining gasa ni Aaron nga mag-uban kanimo."},{"verse":8,"text":"Busa, ayaw pagduhaduha, kay mao kini ang gasa sa Dios; ug ikaw makagunit niini sa imong mga kamot, ug makahimo og katingalahan nga mga buhat; ug walay gahom nga makakuha niini gikan sa imong mga kamot, kay mao kini ang buhat sa Dios."},{"verse":9,"text":"Ug, busa, bisan unsa ang imong pangayoon kanako nga isulti kanimo pinaagi niana, kana akong ihatag kanimo, ug ikaw makabaton og kahibalo mahitungod niini."},{"verse":10,"text":"Hinumdomi nga kon wala ang pagtuo ikaw walay mahimo; busa pangayo pinaagi sa pagtuo. Ayaw pagtiaw-tiaw niining mga butanga; ayaw pangayo niana nga wala nimo kinahanglana."},{"verse":11,"text":"Pangayo aron ikaw makahibalo sa mga misteryo sa Dios, ug nga ikaw makahubad ug makadawat og kahibalo gikan niadtong karaang mga talaan nga gitago, nga sagrado; ug sumala sa imong pagtuo kini pagabuhaton diha kanimo."},{"verse":12,"text":"Tan-awa, ako ang namulong niini; ug ako ang namulong nganha kanimo sukad sa sinugdanan. Amen."}]},{"chapter":9,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko ikaw, akong anak, tungod kay ikaw wala mohubad sumala sa imong gihangyo kanako, ug misugod na usab sa pagsulat alang sa akong sulugoon nga si Joseph Smith, Jun., bisan pa niana naglaom ako nga imong padayonon hangtod nga imong mahuman kining talaan nga akong gisalig kaniya."},{"verse":2,"text":"Ug human niana, tan-awa, adunay uban pang mga talaan, nga ania kanako, nga ikaw hatagan ko og gahom sa paagi nga makatabang ikaw sa paghubad."},{"verse":3,"text":"Pagmapailobon, akong anak, kay sumala kini sa akong kaalam, ug dili pa angay nga ikaw mohubad niini nga panahon."},{"verse":4,"text":"Tan-awa, ang buhat diin ikaw gitawag sa pagbuhat mao ang pagsulat alang sa akong sulugoon nga si Joseph."},{"verse":5,"text":"Ug, tan-awa, tungod kay ikaw wala mopadayon sumala sa imong nasugdan, dihang nagsugod ka sa paghubad, nga akong gikuha kini nga kahigayonan gikan kanimo."},{"verse":6,"text":"Ayaw pagbagulbol, akong anak, kay sumala kini sa akong kaalam nga ikaw gitratar nako sa ingon niini nga paagi."},{"verse":7,"text":"Tan-awa, wala ikaw makasabot; nagdahom ka nga kini akong ihatag kanimo, samtang ikaw wala maghunahuna gawas sa pagpangayo kanako."},{"verse":8,"text":"Apan, tan-awa, sultihan ko ikaw, nga kinahanglan gayod nga imo kining tun-an og maayo sa imong hunahuna; dayon ikaw kinahanglan nga mangutana kanako kon husto ba kini, ug kon husto kini akong ipabati ang kainit sulod sa imong dughan; busa, imong mabati nga husto kini."},{"verse":9,"text":"Apan kon dili kini husto ikaw dili makabaton niana nga mga pagbati, apan makabaton ka og kasamok sa hunahuna nga makapahimo kanimo nga makalimot sa butang nga sayop; busa, ikaw dili makasulat niana nga sagrado gawas kon kini ihatag kanimo gikan kanako."},{"verse":10,"text":"Karon, kon ikaw nakahibalo pa unta niini ikaw nakahubad unta; bisan pa niana, dili tukma nga ikaw maghubad karon."},{"verse":11,"text":"Tan-awa, tukma kadto sa diha nga ikaw nagsugod; apan ikaw nahadlok, ug ang panahon milabay na, ug dili na tukma karon;"},{"verse":12,"text":"Kay, wala ba nimo makita nga ako naghatag ngadto sa akong sulugoon nga si Joseph og igong kalig-on, mao nga nahimo kini? Ug walay usa kaninyo nga akong gipanghimaraot."},{"verse":13,"text":"Buhata kini nga butang nga akong gisugo kanimo, ug ikaw mouswag. Pagmatinud-anon, ug ayaw pagpadala sa bisan unsa nga tentasyon."},{"verse":14,"text":"Pagpabiling matinud-anon sa buhat diin ikaw akong gitawag, ug bisan usa ka buhok sa imong ulo dili mawala, ug ikaw pagabayawon sa kataposang adlaw. Amen."}]},{"chapter":10,"verses":[{"verse":1,"text":"Karon, tan-awa, sultihan ko ikaw, tungod kay gitugyan man nimo kadtong mga sinulat diin ikaw gihatagan og gahom aron hubaron pinaagi sa Urim ug Thummim, ngadto sa mga kamot sa tawo nga daotan, kini nawala kanimo."},{"verse":2,"text":"Ug ikaw nawad-an usab sa imong gasa sa samang higayon, ug ang imong panghunahuna nawad-an sa panabot."},{"verse":3,"text":"Bisan pa niana, karon nabalik na usab kini nganha kanimo; busa seguroha nga ikaw magmatinud-anon ug magpadayon sa pagtapos sa nahibilin nga buluhaton sa paghubad sama sa imong nasugdan."},{"verse":4,"text":"Ayaw pagdagan og mas paspas o pagbuhat og mas labaw pa kay sa imong kusog ug sa mga pamaagi nga gihatag kanimo aron makahubad; apan pagmakugihon hangtod sa kataposan."},{"verse":5,"text":"Pag-ampo kanunay, aron ikaw magmadaogon; oo, nga imong mabuntog si Satanas ug nga makalingkawas ka sa mga kamot sa mga sulugoon ni Satanas nga nagpatunhay sa iyang buhat."},{"verse":6,"text":"Tan-awa, nagtinguha sila sa paglaglag kanimo; oo, gani ang tawo nga imong gisaligan nagtinguha sa paglaglag kanimo."},{"verse":7,"text":"Ug tungod niini nga hinungdan miingon ako nga siya tawo nga daotan, kay nagtinguha siya nga kuhaon ang mga butang nga gisalig kanimo; ug nagtinguha usab siya nga mawala ang imong gasa."},{"verse":8,"text":"Ug tungod kay gitugyan nimo ang mga sinulat ngadto sa iyang mga kamot, tan-awa, gikuha kini sa mga tawo nga daotan gikan kanimo."},{"verse":9,"text":"Busa, gitugyan nimo kini, oo, kana nga sagrado, ngadto sa pagkadaotan."},{"verse":10,"text":"Ug, tan-awa, si Satanas mibutang niini diha sa ilang mga kasingkasing nga usbon ang mga pulong nga imong gisulat, o kadtong imong gihubad, nga nawala gikan sa imong mga kamot."},{"verse":11,"text":"Ug tan-awa, sultihan ko ikaw, nga tungod kay giusab nila ang mga pulong, mabasa kini nga sukwahi nianang imong gihubad ug gisulat;"},{"verse":12,"text":"Ug, sa ingon niini nga paagi, ang yawa nagtinguha sa pagbutang og malipoton nga plano, aron malaglag niya kini nga buhat;"},{"verse":13,"text":"Kay gitisok niya sa ilang mga kasingkasing nga himoon kini, nga pinaagi sa pagpamakak makaingon sila nga sila nakasakop kanimo diha sa mga pulong nga ikaw nagpakaaron-ingnon nga imong gihubad."},{"verse":14,"text":"Sa pagkatinuod, sultihan ko ikaw, nga ako dili makatugot nga molampos si Satanas sa iyang daotan nga plano niini nga butang."},{"verse":15,"text":"Kay tan-awa, gitisok niya kini sa ilang mga kasingkasing aron agnihon nimo ang Ginoo nga imong Dios, pinaagi sa paghangyo nga hubaron kini og usab."},{"verse":16,"text":"Ug unya, tan-awa, moingon sila ug maghunahuna sa ilang mga kasingkasing—Atong tan-awon kon ang Dios naghatag ba kaniya og gahom sa paghubad; kon mao, siya mohatag na usab kaniya og gahom;"},{"verse":17,"text":"Ug kon ang Dios mohatag na usab kaniya og gahom, o kon mohubad siya og usab, o, sa laing pagkasulti, kon siya modala sa mao gihapong mga pulong, tan-awa, kita adunay gihuptan nga sama niini, ug gipang-usab na nato kini;"},{"verse":18,"text":"Busa dili kini magkaparehas, ug moingon kita nga siya namakak sa iyang mga pulong, ug nga siya walay gasa, ug nga siya walay gahom;"},{"verse":19,"text":"Busa kita molaglag kaniya, ug sa buhat usab; ug buhaton nato kini aron dili kita maulawan sa kataposan, ug nga kita makaangkon sa himaya sa kalibotan."},{"verse":20,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, nga si Satanas may dako nga impluwensya sa ilang mga kasingkasing; siya mihulhog kanila ngadto sa pagkadaotan batok niana nga maayo;"},{"verse":21,"text":"Ug ang ilang mga kasingkasing limbongan, ug puno sa pagkadaotan ug mga pagkasalawayon; ug gihigugma nila ang kangitngit kay sa kahayag, tungod kay ang ilang mga buhat daotan; busa sila dili mangayo kanako."},{"verse":22,"text":"Si Satanas mihulhog kanila, aron iyang madala ang ilang mga kalag ngadto sa kalaglagan."},{"verse":23,"text":"Ug sa ingon niana naghimo siya og malipoton nga plano, naghunahuna sa paglaglag sa buhat sa Dios; apan maningil ako niini gikan kanila, ug kini mosumbalik ngadto sa ilang kaulaw ug panghimaraot sa adlaw sa paghukom."},{"verse":24,"text":"Oo, gihulhogan niya ang ilang mga kasingkasing aron masuko batok niini nga buhat."},{"verse":25,"text":"Oo, miingon siya kanila: Panglimbong ug pamakak aron makapanglingla, aron ikaw makalaglag; tan-awa, dili kini makadaot. Ug sa ingon niana siya miulog-ulog kanila, ug misulti kanila nga dili sala ang pagpamakak aron makapanglingla sila sa tawo pinaagi sa pagpamakak, aron makalaglag sila kaniya."},{"verse":26,"text":"Ug sa ingon niana siya miulog-ulog kanila, ug midala kanila hangtod nga miguyod siya sa ilang mga kalag ngadto sa impyerno; ug sa ingon niana mipahitabo siya nga mabitik sila sa kaugalingon nila nga lit-ag."},{"verse":27,"text":"Ug sa ingon niana milakaw siya pataas ug paubos, ngadto ug nganhi sa yuta, nagtinguha sa paglaglag sa mga kalag sa katawhan."},{"verse":28,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, alaot siya nga mamakak aron makapanglimbong tungod kay nagdahom siya nga ang uban namakak aron makapanglimbong, kay ang ingon niana dili makalingkawas gikan sa kaangayan sa Dios."},{"verse":29,"text":"Karon, tan-awa, ilang giusab kini nga mga pulong, tungod kay si Satanas misulti kanila: Siya milimbong kaninyo—ug sa ingon niana siya miulog-ulog kanila sa pagbuhat og pagkadaotan, sa pag-agni kanimo sa pagtental sa Ginoo nga imong Dios."},{"verse":30,"text":"Tan-awa, sultihan ko ikaw, nga ayaw na hubara pag-usab kadtong mga pulong nga nawala gikan sa imong mga kamot;"},{"verse":31,"text":"Kay, tan-awa, dili sila molampos sa daotan nilang mga plano pinaagi sa pagpamakak batok niadto nga mga pulong. Kay, tan-awa, kon maghubad ka og sama gihapon nga mga pulong moingon sila nga ikaw namakak ug nga ikaw nagpakaaron-ingnon nga naghubad, apan gisukwahi nimo ang imong kaugalingon."},{"verse":32,"text":"Ug, tan-awa, imantala nila kini, ug si Satanas mopatig-a sa mga kasingkasing sa katawhan sa paghulhog kanila aron masuko batok kanimo, aron dili sila motuo sa akong mga pulong."},{"verse":33,"text":"Sa ingon niana si Satanas naghunahuna sa paglupig sa imong pagpamatuod niini nga henerasyon, aron ang buhat dili magpadayon niini nga henerasyon."},{"verse":34,"text":"Apan tan-awa, ania ang kaalam, ug tungod kay gipakitaan ko ikaw og kaalam, ug mihatag kanimo og mga sugo mahitungod niini nga mga butang, sa unsay imong buhaton, ayaw kini ipakita sa kalibotan hangtod nga imong matuman ang buhat sa paghubad."},{"verse":35,"text":"Ayaw kahibulong nga gisultihan ko ikaw nga: Aniay kaalam, ayaw kini ipakita sa kalibotan—kay misulti ako nga ayaw kini ipakita sa kalibotan, aron ikaw mapanalipdan."},{"verse":36,"text":"Tan-awa, wala ako mosulti nga dili nimo kini ipakita sa mga matarong;"},{"verse":37,"text":"Apan kay ikaw dili man makahukom kanunay sa matarong, o kay ikaw dili man kanunay makaila sa daotan gikan sa matarong, busa sultihan ko ikaw, pagpakahilom hangtod nga akong makita nga angay nang ipahibalo ang tanang butang dinhi sa kalibotan kalabot niana."},{"verse":38,"text":"Ug karon, sa pagkatinuod sultihan ko ikaw, nga ang asoy niadto nga mga butang nga imong gisulat, nga nawala gikan sa imong mga kamot, gikulit diha sa mga palid ni Nephi;"},{"verse":39,"text":"Oo, ug ikaw nahinumdom nga giingon niadtong mga sinulat nga daghan pang piho nga asoy ang gihatag bahin niini nga mga butang diha sa mga palid ni Nephi."},{"verse":40,"text":"Ug karon, tungod kay ang asoy nga nakulit diha sa mga palid ni Nephi mas piho man kabahin sa mga butang nga, pinaagi sa akong kaalam, akong ipahibalo sa katawhan niini nga asoy—"},{"verse":41,"text":"Busa, hubaron nimo ang mga kinulit nga anaa sa mga palid ni Nephi, gani hangtod nga moabot ka ngadto sa paghari ni hari Benjamin, o hangtod nga moabot ka ngadto nianang imong gihubad, nga anaa kanimo;"},{"verse":42,"text":"Ug tan-awa, imantala nimo kini isip ang talaan ni Nephi; ug sa ingon niana libogon nako kadtong miusab sa akong mga pulong."},{"verse":43,"text":"Dili ako motugot nga sila molaglag sa akong buhat; oo, ipakita nako ngadto kanila nga ang akong kaalam labaw pa ka gamhanan kaysa kaigmat sa yawa."},{"verse":44,"text":"Tan-awa, nakakuha lamang sila og tipik, o usa ka minubo nga asoy ni Nephi."},{"verse":45,"text":"Tan-awa, adunay daghang butang nga nakulit sa mga palid ni Nephi nga naghatag og dako nga katin-awan sa akong ebanghelyo; busa, kini kaalam ngari kanako nga imong hubaron kining unang bahin sa mga kinulit ni Nephi, ug ipakita dinhi niini nga buhat."},{"verse":46,"text":"Ug, tan-awa, ang tanan nga nahibilin niini nga buhat naglakip sa tanan niadtong mga bahin sa akong ebanghelyo nga gitinguha sa akong balaan nga mga propeta, oo, ug usab sa akong mga disipulo, diha sa ilang mga pag-ampo nga kinahanglan nga moabot niini nga katawhan."},{"verse":47,"text":"Ug gisultihan nako sila, nga kini ihatag kanila sumala sa ilang pagtuo diha sa ilang mga pag-ampo;"},{"verse":48,"text":"Oo, ug mao kini ang ilang pagtuo—nga ang akong ebanghelyo, nga gihatag nako kanila nga ilang isangyaw sa ilang mga adlaw, moabot unta ngadto sa ilang kaigsoonan nga mga Lamanita, ug usab sa tanan nga nahimong mga Lamanita, tungod sa ilang mga panagsumpaki."},{"verse":49,"text":"Karon, dili lamang kini mao ang tanan—ang ilang pagtuo sa ilang mga pag-ampo mao nga kini nga ebanghelyo mahibaloan usab, kon mahimo kini nga ang ubang kanasoran makapanag-iya niini nga yuta;"},{"verse":50,"text":"Ug sa ingon niana nagbilin sila og panalangin niini nga yuta sa ilang mga pag-ampo, nga kinsa kadtong motuo niini nga ebanghelyo dinhi niini nga yuta makabaton og kinabuhing dayon;"},{"verse":51,"text":"Oo, nga kini mahimong libre ngadto sa tanan sa bisan unsa nga nasod, kaliwatan, pinulongan, o katawhan."},{"verse":52,"text":"Ug karon, tan-awa, sumala sa ilang pagtuo sa ilang mga pag-ampo akong ipahibalo kini nga bahin sa akong ebanghelyo ngadto sa akong katawhan. Tan-awa, ako dili mopahitabo niini aron sa paglaglag nianang ilang nadawat, apan aron sa pagpalig-on niini."},{"verse":53,"text":"Ug tungod niini nga hinungdan misulti ako: Kon kini nga kaliwatan dili magpatig-a sa ilang mga kasingkasing, akong tukoron ang akong simbahan taliwala kanila."},{"verse":54,"text":"Karon wala ako mosulti niini aron sa paglaglag sa akong simbahan, apan gisulti ko kini aron sa pagpalig-on sa akong simbahan;"},{"verse":55,"text":"Busa, kinsa kadtong nahisakop sa akong simbahan dili angay nga mahadlok, kay ang ingon makapanunod sa gingharian sa langit."},{"verse":56,"text":"Apan sila nga dili mahadlok kanako, ni maghupot sa akong mga sugo apan nagtukod og mga simbahan alang sa ilang kaugalingon aron makaangkon og bahandi, oo, ug kadtong tanan nga nagpakadaotan ug nagtukod sa gingharian sa yawa—oo, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, kana sila mao ang akong samokon, ug pakurogon ug uyogon hangtod sa kahiladman."},{"verse":57,"text":"Tan-awa, ako mao si Jesukristo, ang Anak sa Dios. Mianhi ako sa akong katawhan, ug ang akong katawhan wala modawat kanako."},{"verse":58,"text":"Ako mao ang kahayag nga nagdan-ag sa kangitngit, ug ang kangitngit wala makasabot niini."},{"verse":59,"text":"Ako mao ang miingon nga—Ako adunay uban nga karnero nga wala niini nga panon—ngadto sa akong mga disipulo, ug daghan kanila wala makasabot kanako."},{"verse":60,"text":"Ug akong ipadayag niini nga katawhan nga ako adunay uban nga karnero, ug nga sila usa ka sanga sa balay ni Jacob;"},{"verse":61,"text":"Ug akong ipadayag ang ilang kahibulongan nga mga buhat, nga ilang gibuhat pinaagi sa akong ngalan;"},{"verse":62,"text":"Oo, ug akong ipadayag usab ang akong ebanghelyo nga gipangalagad kanila, ug, tan-awa, dili sila molimod nianang imong nadawat, apan palig-onon nila kini, ug mopakita sa tinuod nga mga punto sa akong doktrina, oo, ug ang bugtong nga doktrina nga ania kanako."},{"verse":63,"text":"Ug kini akong gibuhat aron akong matukod ang akong ebanghelyo, nga wala na untay daghan nga panagbingkil; oo, si Satanas mohulhog sa mga kasingkasing sa katawhan ngadto sa panagbingkil bahin sa mga punto sa akong doktrina; ug diha niini nga mga butang sila nahisalaag, kay sila mituis sa mga kasulatan ug wala makasabot niini."},{"verse":64,"text":"Busa, akong ipahibalo kanila kining mahinungdanon nga misteryo;"},{"verse":65,"text":"Kay, tan-awa, pundokon nako sila sama sa himungaan nga nagpundok sa iyang mga piso sa ilawom sa iyang mga pako, kon dili sila magpatig-a sa ilang mga kasingkasing;"},{"verse":66,"text":"Oo, kon moabot sila, gawasnon silang mobuhat, ug moambit sa mga tubig sa kinabuhi."},{"verse":67,"text":"Tan-awa, mao kini ang akong doktrina—kinsa kadtong maghinulsol ug moduol kanako, ang ingon mao ang akong simbahan."},{"verse":68,"text":"Kinsa kadtong mopahayag og mas labaw o mas kulang kaysa niini, kini sila wala mahisakop kanako, apan nakigbatok kanako; busa dili siya sakop sa akong simbahan."},{"verse":69,"text":"Ug karon, tan-awa, kinsa kadtong nahisakop sa akong simbahan, ug molahutay sa akong simbahan hangtod sa kataposan, ipahimutang nako siya diha sa akong lig-on nga bato, ug ang mga ganghaan sa impyerno dili makabuntog kaniya."},{"verse":70,"text":"Ug karon, hinumdomi ang iyang mga pulong kinsa mao ang kinabuhi ug kahayag sa kalibotan, imong Manunubos, imong Ginoo ug imong Dios. Amen."}]},{"chapter":11,"verses":[{"verse":1,"text":"Usa ka mahinungdanon ug katingalahan nga buhat hapit na moabot taliwala sa katawhan."},{"verse":2,"text":"Tan-awa, ako ang Dios; paminaw sa akong pulong, nga buhi ug gamhanan, hait pa kaysa espada nga duhay suwab, ngadto sa pagbahin sa mga lutahan ug kauyokan; busa paminaw sa akong pulong."},{"verse":3,"text":"Tan-awa, ang umahan puti ug andam na aron anihon; busa, kadtong nagtinguha sa pag-ani, tugoti nga mohapos siya siya gamit ang iyang galab pinaagi sa iyang kusog, ug mag-ani samtang aduna pay panahon, nga siya motipig alang sa iyang kalag og walay kataposan nga kaluwasan sa gingharian sa Dios."},{"verse":4,"text":"Oo, kinsa kadtong mohapos gamit ang iyang galab ug moani, ang maong tawo gitawag sa Dios."},{"verse":5,"text":"Busa, kon ikaw mangayo kanako ikaw makadawat; kon ikaw motuktok ikaw pagaablihan."},{"verse":6,"text":"Karon, kay ikaw nangayo man, tan-awa, sultihan ko ikaw, sunda ang akong mga sugo, ug tinguhaa ang pagdala ug pagtukod sa kawsa sa Zion."},{"verse":7,"text":"Ayaw pagtinguha sa mga katigayonan apan sa kaalam; ug, tan-awa, ang misteryo sa Dios ipadayag kanimo, ug unya ikaw mahimo nga adunahan. Tan-awa, siya nga adunay kinabuhing dayon adunahan."},{"verse":8,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, bisan unsa nga imong tinguhaon ngari kanako kini ihatag kanimo; ug, kon ikaw magtinguha, ikaw mahimong instrumento sa pagbuhat og daghang kaayohan niini nga henerasyon."},{"verse":9,"text":"Ayaw pagsulti og lain gawas sa paghinulsol ngadto niini nga henerasyon. Sunda ang akong mga sugo, ug motabang aron molambo ang akong buhat, sumala sa akong mga sugo, ug ikaw mapanalanginan."},{"verse":10,"text":"Tan-awa, ikaw adunay gasa, o ikaw makabaton og gasa kon ikaw magtinguha kanako pinaagi sa pagtuo, uban sa matinud-anon nga kasingkasing, nagtuo sa gahom ni Jesukristo, o sa akong gahom nga gipamulong nganha kanimo;"},{"verse":11,"text":"Kay, tan-awa, ako kini ang namulong; tan-awa, ako ang kahayag nga nagdan-ag sa kangitngit, ug pinaagi sa akong gahom ihatag ko kining mga pulong nganha kanimo."},{"verse":12,"text":"Ug karon, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, itugyan ang imong pagsalig niana nga Espiritu nga naggiya sa pagbuhat og maayo—oo, sa pagbuhat sa makiangayon, sa paglakaw nga mapainubsanon, sa paghukom nga matinud-anon; ug kini ang akong Espiritu."},{"verse":13,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, hatagan ko ikaw sa akong Espiritu, nga molamdag sa imong hunahuna, nga mopuno og kamaya sa imong kalag;"},{"verse":14,"text":"Ug unya imong masayran, o pinaagi niini imong masayran, ang tanang bisan unsa nga mga butang nga imong gitinguha kanako, nga may kalabotan sa mga butang sa pagkamatarong, pinaagi sa pagtuo magatuo kanako nga ikaw makadawat."},{"verse":15,"text":"Tan-awa, sugoon ko ikaw nga dili ka magdahom nga gitawag ka sa pagsangyaw kon ikaw wala pa matawag."},{"verse":16,"text":"Paghulat pa og mubo nga panahon, hangtod nga imong mabatonan ang akong pulong, ang akong lig-ong bato, akong simbahan, ug akong ebanghelyo, nga imong masayran ang pagkatinuod sa akong doktrina."},{"verse":17,"text":"Ug unya, tan-awa, sumala sa imong mga tinguha, oo, gani sumala sa imong pagtuo ihatag kini kanimo."},{"verse":18,"text":"Sunda ang akong mga sugo; pagmalinawon; pangaliya sa akong Espiritu;"},{"verse":19,"text":"Oo, pagmatinud-anon ngari kanako sa imong tibuok kasingkasing, nga ikaw makatabang aron ipahibalo kadtong mga butang nga gipamulong na—oo, sa paghubad sa akong buhat; pagmapailobon hangtod nga ikaw makatuman niini."},{"verse":20,"text":"Tan-awa, kini mao ang imong buhat, ang pagsunod sa akong mga sugo, oo, sa imong tibuok gahom, hunahuna ug kusog."},{"verse":21,"text":"Ayaw tinguhaa ang pagpahayag sa akong pulong, apan unaha sa pagtinguha ang pagbaton sa akong pulong, ug unya ang imong dila makasulti; unya, kon ikaw magtinguha, ikaw makabaton sa akong Espiritu ug sa akong pulong, oo, ang gahom sa Dios ngadto sa pagkabig sa mga tawo."},{"verse":22,"text":"Apan sa pagkakaron pagmalinawon; tun-i ang akong pulong nga gipadayag taliwala sa katawhan, ug tun-i usab ang akong pulong nga ipadayag taliwala sa katawhan, o nianang gihubad pa sa pagkakaron, oo, hangtod nga imong mabatonan ang tanan nga akong ihatag sa katawhan niini nga henerasyon, ug unya ang tanang butang idugang diha niana."},{"verse":23,"text":"Tan-awa ikaw si Hyrum, akong anak; tinguhaa ang gingharian sa Dios, ug ang tanang butang idugang sumala nianang unsay makiangayon."},{"verse":24,"text":"Pagtukod ibabaw sa akong bato, nga mao ang akong ebanghelyo;"},{"verse":25,"text":"Ayaw ilimod ang espiritu sa pagpadayag, ni ang espiritu sa pagpanagna, kay alaot siya nga molimod niini nga mga butang;"},{"verse":26,"text":"Busa, ibahandi kini diha sa imong kasingkasing hangtod sa panahon nga sa akong kaalam ikaw moadto."},{"verse":27,"text":"Tan-awa, namulong ako ngadto sa tanan nga adunay maayong mga tinguha, ug mohapos gamit ang ilang galab sa pag-ani."},{"verse":28,"text":"Tan-awa, ako si Jesukristo, ang Anak sa Dios. Ako ang kinabuhi ug ang kahayag sa kalibotan."},{"verse":29,"text":"Ako gihapon kadtong mianhi sa akong katawhan ug ang akong katawhan wala modawat kanako;"},{"verse":30,"text":"Apan sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga kutob sa modawat kanako, ngadto kanila ako mohatag og gahom aron mahimong mga anak sa Dios, gani ngadto kanila nga motuo sa akong ngalan. Amen."}]},{"chapter":12,"verses":[{"verse":1,"text":"Usa ka mahinungdanon ug katingalahan nga buhat hapit na moabot taliwala sa katawhan."},{"verse":2,"text":"Tan-awa, ako ang Dios; paminaw sa akong pulong, nga buhi ug gamhanan, hait pa kaysa espada nga duhay suwab, ngadto sa pagbahin sa mga lutahan ug kauyokan; busa paminaw sa akong pulong."},{"verse":3,"text":"Tan-awa, ang umahan puti na ug andam na aron anihon; busa, kadtong nagtinguha sa pag-ani, tugoti nga siya mohapos gamit ang iyang galab pinaagi sa iyang kusog, ug mag-ani samtang aduna pay panahon, aron siya makatipig alang sa iyang kalag og walay kataposan nga kaluwasan sa gingharian sa Dios."},{"verse":4,"text":"Oo, kinsa kadtong mohapos gamit ang iyang galab ug moani, ang maong tawo gitawag sa Dios."},{"verse":5,"text":"Busa, kon ikaw mangayo kanako ikaw makadawat; kon ikaw motuktok ikaw pagaablihan."},{"verse":6,"text":"Karon, kay ikaw nangayo man, tan-awa, sultihan ko ikaw, sunda ang akong mga sugo, ug tinguhaa ang pagpatungha ug pagtukod sa kawsa sa Zion."},{"verse":7,"text":"Tan-awa, sultihan ko ikaw, ug usab ang tanan nga adunay mga tinguha sa pagdala ug pagtukod niini nga buhat;"},{"verse":8,"text":"Ug walay tawo nga makatabang niini nga buhat gawas kon siya magmapainubsanon ug puno sa gugma, adunay pagtuo, paglaom, ug gugmang putli, mapinugnganon sa kaugalingon sa tanan nga butang, ngadto sa bisan unsa nga isalig kaniya."},{"verse":9,"text":"Tan-awa, ako ang kahayag ug ang kinabuhi sa kalibotan, nga namulong niini nga mga pulong, busa paminaw kutob sa imong mahimo, ug unya ikaw pagatawgon. Amen."}]},{"chapter":13,"verses":[{"verse":1,"text":"Diha kaninyo akong kauban nga mga sulugoon, sa ngalan sa Mesiyas akong itugyan ang Pagkapari ni Aaron, nga naghupot sa mga yawe sa pagpangalagad sa mga anghel, ug sa ebanghelyo sa paghinulsol, ug sa bunyag pinaagi sa pagpaunlod alang sa kapasayloan sa mga sala; ug kini dili na pagakuhaon pag-usab gikan sa yuta, hangtod nga ang mga anak ni Levi maghalad pag-usab og halad ngadto sa Ginoo diha sa pagkamatarong."}]},{"chapter":14,"verses":[{"verse":1,"text":"Usa ka mahinungdanon ug katingalahan nga buhat hapit na moabot taliwala sa mga anak sa katawhan."},{"verse":2,"text":"Tan-awa, ako ang Dios; paminaw sa akong pulong, nga buhi ug gamhanan, hait pa kaysa espada nga duhay suwab, ngadto sa pagbahin sa mga lutahan ug kauyokan; busa paminaw sa akong pulong."},{"verse":3,"text":"Tan-awa, ang umahan puti na ug andam na aron anihon; busa, kadtong nagtinguha sa pag-ani, tugoti nga siya mohapos gamit ang iyang galab pinaagi sa iyang kusog, ug mag-ani samtang aduna pay panahon, nga siya motipig alang sa iyang kalag og walay kataposan nga kaluwasan sa gingharian sa Dios."},{"verse":4,"text":"Oo, kinsa kadtong mohapos gamit ang iyang galab ug moani, ang maong tawo gitawag sa Dios."},{"verse":5,"text":"Busa, kon ikaw mangayo kanako ikaw makadawat; kon ikaw motuktok ikaw pagaablihan."},{"verse":6,"text":"Tinguhaa ang pagpatungha ug pagtukod sa akong Zion. Sunda ang akong mga sugo sa tanang butang."},{"verse":7,"text":"Ug, kon sundon nimo ang akong mga sugo ug molahutay sa kataposan mabatonan nimo ang kinabuhing dayon, ang gasa nga labing mahinungdanon sa tanang gasa sa Dios."},{"verse":8,"text":"Ug mahitabo, nga kon ikaw mangayo sa Amahan pinaagi sa akong ngalan, inubanan sa pagtuo, imong madawat ang Espiritu Santo, nga maoy modasig, aron ikaw mobarog isip saksi sa mga butang nga imong madungog ug makita, ug aron ikaw makapamahayag usab og paghinulsol ngadto niini nga henerasyon."},{"verse":9,"text":"Tan-awa, ako si Jesukristo, ang Anak sa buhi nga Dios, nga naglalang sa kalangitan ug sa yuta, usa ka kahayag nga dili matago sa kangitngit;"},{"verse":10,"text":"Mao nga, kinahanglan nga akong dad-on ang kahingpitan sa akong ebanghelyo gikan sa mga Hentil ngadto sa balay ni Israel."},{"verse":11,"text":"Ug tan-awa, ikaw si David, ug gitawag ikaw sa pagtabang; sa butang nga kon imong buhaton, ug magmatinud-anon, ikaw panalanginan sa espirituhanon ug temporal nga paagi, ug dako ang imong ganti. Amen."}]},{"chapter":15,"verses":[{"verse":1,"text":"Patalinghog, akong sulugoon nga John, ug paminaw sa mga pulong ni Jesukristo, nga imong Ginoo ug imong Manunubos."},{"verse":2,"text":"Kay tan-awa, namulong ako kanimo uban sa kahait ug sa gahom, kay ang akong gahom anaa sa tibuok yuta."},{"verse":3,"text":"Ug sultihan ko ikaw og butang nga walay tawo nga nasayod gawas kanako ug kanimo lamang—"},{"verse":4,"text":"Kay sa makadaghang higayon nagtinguha ka gikan kanako nga masayod nianang labing bililhon kanimo."},{"verse":5,"text":"Tan-awa, bulahan ka tungod niini nga butang, ug tungod sa pagpahayag sa akong mga pulong nga akong gihatag kanimo sumala sa akong mga sugo."},{"verse":6,"text":"Ug karon, tan-awa, sultihan ko ikaw, nga ang butang nga labing bililhon kanimo mao ang pagpahayag og paghinulsol niini nga katawhan, nga imong madala ang mga kalag ngari kanako, nga ikaw makapahulay uban kanila sa gingharian sa akong Amahan. Amen."}]},{"chapter":16,"verses":[{"verse":1,"text":"Patalinghog, akong sulugoon nga Peter, ug paminaw sa mga pulong ni Jesukristo, ang imong Ginoo ug imong Manunubos."},{"verse":2,"text":"Kay tan-awa, ako mamulong kanimo uban sa kahait ug uban sa gahom, kay ang akong gahom anaa sa tibuok yuta."},{"verse":3,"text":"Ug sultihan ko ikaw og butang nga walay laing tawo nga nasayod gawas kanako ug kanimo lamang—"},{"verse":4,"text":"Kay sa makadaghang higayon nagtinguha ka gikan kanako nga masayod nianang labing bililhon kanimo."},{"verse":5,"text":"Tan-awa, bulahan ka tungod niini nga butang, ug tungod sa pagpahayag sa akong mga pulong nga akong gihatag kanimo sumala sa akong mga sugo."},{"verse":6,"text":"Ug karon, tan-awa, sultihan ko ikaw, nga ang butang nga labing bililhon kanimo mao ang pagpahayag og paghinulsol niini nga katawhan, nga makadala ka og mga kalag ngari kanako, nga ikaw makapahulay uban kanila sa gingharian sa akong Amahan. Amen."}]},{"chapter":17,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko kamo, nga kinahanglan kamong mosalig sa akong pulong, nga kon inyong buhaton pinaagi sa hingpit nga katuyoan sa kasingkasing, makatan-aw kamo sa mga palid, ug usab sa panagang sa dughan, sa espada ni Laban, sa Urim ug Thummim, nga gihatag ngadto sa igsoon ni Jared didto sa bukid, sa dihang nakigsulti siya sa Ginoo nawong sa nawong, ug sa milagroso nga tigtultol nga gihatag ngadto ni Lehi samtang anaa sa kamingawan, sa mga utlanan sa Pulang Dagat."},{"verse":2,"text":"Ug pinaagi sa inyong pagtuo nga kini inyong makita, gani pinaagi niana nga pagtuo nga nabatonan sa karaang mga propeta."},{"verse":3,"text":"Ug human nga nakabaton kamo og pagtuo, ug nakita kini sa inyong mga mata, kamo mopamatuod kabahin niini, pinaagi sa gahom sa Dios;"},{"verse":4,"text":"Ug buhaton ninyo kini aron ang akong sulugoon nga si Joseph Smith, Jun., dili malaglag, nga akong mapahitabo ang akong matarong nga katuyoan ngadto sa mga anak sa katawhan niini nga buhat."},{"verse":5,"text":"Ug inyong pamatud-an nga kamo nakakita niini, sama sa akong sulugoon nga si Joseph Smith, Jun., nga nakakita niiini; kay pinaagi sa akong gahom siya nakakita niini, ug tungod kini kay siya adunay pagtuo."},{"verse":6,"text":"Ug iyang gihubad ang basahon, bisan kana nga bahin nga akong gisugo kaniya, ug samtang ang imong Ginoo ug ang imong Dios buhi kini tinuod."},{"verse":7,"text":"Mao nga, nakadawat kamo sa samang gahom, ug sa samang pagtuo, ug sa samang gasa nga anaa kaniya;"},{"verse":8,"text":"Ug kon buhaton ninyo kining akong kataposang mga sugo, nga akong gihatag kaninyo, ang mga ganghaan sa impyerno dili magmadaogon batok kaninyo; kay ang akong grasya igo alang kaninyo, ug kamo pagabayawon sa kataposang adlaw."},{"verse":9,"text":"Ug ako, si Jesukristo, ang inyong Ginoo ug inyong Dios, namulong niini nganha kaninyo, nga akong mapahitabo ang matarong nga mga katuyoan ngadto sa mga anak sa katawhan. Amen."}]},{"chapter":18,"verses":[{"verse":1,"text":"Karon, tan-awa, tungod sa butang nga imong gitinguha, akong sulugoong Oliver Cowdery, nga mahibaloan gikan kanako, hatagan ko ikaw niini nga mga pulong:"},{"verse":2,"text":"Tan-awa, akong gipadayag kanimo pinaagi sa akong Espiritu sa daghang higayon, nga ang mga butang nga imong gisulat tinuod; mao nga imong nahibaloan nga kini tinuod."},{"verse":3,"text":"Ug kon imong mahibaloan nga kini tinuod, tan-awa, hatagan ko ikaw og sugo, nga ikaw mosalig sa mga butang nga nahisulat;"},{"verse":4,"text":"Kay diha niini ang tanang butang nahisulat nga may kalabotan sa pundasyon sa akong simbahan, akong ebanghelyo, ug akong bato."},{"verse":5,"text":"Mao nga, kon imong tukoron ang akong simbahan, diha sa pundasyon sa akong ebanghelyo ug sa akong bato, ang mga ganghaan sa impyerno dili magmadaogon batok kanimo."},{"verse":6,"text":"Tan-awa, ang kalibotan nagkahinog sa pagkadaotan; ug kinahanglan gayod nga ang mga anak sa katawhan awhagon sa paghinulsol, ang mga Hentil ug usab ang balay ni Israel."},{"verse":7,"text":"Mao nga, kay ikaw nabunyagan na pinaagi sa mga kamot sa akong sulugoon nga si Joseph Smith, Jun., sumala nianang akong gisugo kaniya, iyang natuman ang butang nga akong gisugo kaniya."},{"verse":8,"text":"Ug karon, ayaw kahibulong nga ako mitawag kaniya alang sa akong kaugalingong katuyoan, diin nga katuyoan nahibaloan ngari kanako; mao nga, kon magmakugihon siya sa pagsunod sa akong mga sugo mapanalanginan siya og kinabuhing dayon; ug ang iyang ngalan mao si Joseph."},{"verse":9,"text":"Ug karon, Oliver Cowdery, sultihan ko ikaw, ug usab si David Whitmer, pinaagi sa sugo; kay, tan-awa, ako nagsugo sa tanang tawo sa tanang dapit nga maghinulsol, ug sultihan ko ikaw, gani sama kang Pablo nga akong apostol, kay ikaw gitawag gani sa sama niana nga katungdanan diin siya gitawag."},{"verse":10,"text":"Hinumdomi ang bili sa mga kalag mahinungdanon sa panan-aw sa Dios;"},{"verse":11,"text":"Kay, tan-awa, ang Ginoo nga inyong Manunubos nag-antos sa kamatayon diha sa unod; mao nga nag-antos siya sa kasakit sa tanang tawo, aron ang tanang tawo maghinulsol ug moduol kaniya."},{"verse":12,"text":"Ug nabuhi siya pag-usab gikan sa mga patay, nga iyang madala ang tanang tawo ngadto kaniya, sa mga kondisyon sa paghinulsol."},{"verse":13,"text":"Ug pagkadako sa iyang kamaya sa kalag nga naghinulsol!"},{"verse":14,"text":"Mao nga, gitawag kamo aron isangyaw ang paghinulsol ngadto niini nga katawhan."},{"verse":15,"text":"Ug kon maningkamot kamo sa tanan ninyong mga adlaw sa pagsangyaw og paghinulsol ngadto niini nga katawhan, ug makadala, og bisan usa ka kalag ngari kanako, pagkadako sa inyong kamaya uban kaniya didto sa gingharian sa akong Amahan!"},{"verse":16,"text":"Ug karon, kon dako ang inyong kamaya tungod sa usa ka kalag nga inyong nadala ngari kanako didto sa gingharian sa akong Amahan, pagkadako sa inyong kamaya kon kamo makadala og daghang kalag ngari kanako!"},{"verse":17,"text":"Tan-awa, anaa kaninyo ang akong ebanghelyo, ug ang akong bato, ug ang akong kaluwasan."},{"verse":18,"text":"Pangayo sa Amahan pinaagi sa akong ngalan inubanan sa pagtuo, magatuo nga kamo makadawat, ug makabaton kamo sa Espiritu Santo, nga mopakita sa tanang butang nga gikinahanglan sa mga anak sa katawhan."},{"verse":19,"text":"Ug kon kamo walay pagtuo, paglaom, ug gugmang putli, kamo walay mahimo."},{"verse":20,"text":"Ayaw pakigbatok sa ubang simbahan, gawas sa simbahan sa yawa."},{"verse":21,"text":"Dad-a diha kaninyo ang ngalan ni Kristo, ug isulti ang kamatuoran pinaagi sa kaligdong."},{"verse":22,"text":"Ug kutob sa maghinulsol ug magpabunyag pinaagi sa akong ngalan, nga mao si Jesukristo, ug molahutay sa kataposan, ang maong tawo maluwas."},{"verse":23,"text":"Tan-awa, si Jesukristo mao ang ngalan nga gihatag sa Amahan, ug wala nay laing ngalan nga gihatag diin ang tawo mahimong maluwas;"},{"verse":24,"text":"Mao nga, ang tanang tawo kinahanglan nga modala diha kanila sa ngalan nga gihatag sa Amahan, kay niana nga ngalan sila pagatawgon sa kataposang adlaw;"},{"verse":25,"text":"Mao nga, kon wala sila masayod sa ngalan diin sila pagatawgon, sila walay luna sa gingharian sa akong Amahan."},{"verse":26,"text":"Ug karon, tan-awa, adunay uban nga gitawag sa pagpahayag sa akong ebanghelyo, ngadto sa Hentil ug sa Judeo;"},{"verse":27,"text":"Oo, bisan ang napulog duha; ug ang Napulog Duha mahimo nga akong mga disipulo, ug modala sila diha kanila sa akong ngalan; ug ang Napulog Duha mao sila ang magtinguha sa pagdala sa akong ngalan uban sa hingpit nga katuyoan sa kasingkasing."},{"verse":28,"text":"Ug kon magtinguha sila sa pagdala diha kanila sa akong ngalan uban sa hingpit nga katuyoan sa kasingkasing, tawagon sila sa pagpanglakaw ngadto sa tibuok kalibotan sa pagsangyaw sa akong ebanghelyo ngadto sa matag nilalang."},{"verse":29,"text":"Ug mao kana sila ang akong giorden nga mobunyag pinaagi sa akong ngalan, sumala nianang nahisulat;"},{"verse":30,"text":"Ug kamo aduna nianang nahisulat; mao nga, kinahanglan ipahigayon ninyo kini sumala sa mga pulong nga nahisulat."},{"verse":31,"text":"Ug mamulong ako kaninyo, nga Napulog Duha—Tan-awa, ang akong grasya igo alang kaninyo; kinahanglan kamo nga maglakaw nga matarong sa akong atubangan ug dili na magpakasala."},{"verse":32,"text":"Ug, tan-awa, kamo ang akong giorden aron mag-orden og mga pari ug mga magtutudlo; sa pagpahayag sa akong ebanghelyo, sumala sa gahom sa Espiritu Santo nga anaa kaninyo, ug sumala sa mga katungdanan ug mga gasa sa Dios ngadto sa mga tawo;"},{"verse":33,"text":"Ug ako, si Jesukristo, ang inyong Ginoo ug inyong Dios, ang namulong niini."},{"verse":34,"text":"Kini nga mga pulong dili gikan sa mga tawo ni gikan sa tawo, apan gikan kanako; mao nga, kamo magpamatuod nga kini gikan kanako ug dili sa tawo;"},{"verse":35,"text":"Kay ang akong tingog mao ang namulong niini nganha kaninyo; kay gihatag kini pinaagi sa akong Espiritu nganha kaninyo, ug pinaagi sa akong gahom kamo makabasa niini sa usag usa; ug kon dili pa tungod sa akong gahom dili kamo makabaton niini;"},{"verse":36,"text":"Mao nga, makapamatuod kamo nga kamo nakadungog sa akong tingog, ug nahibalo sa akong mga pulong."},{"verse":37,"text":"Ug karon, tan-awa, ako mosugo kanimo, Oliver Cowdery, ug usab ni David Whitmer, nga kamo ang mangita sa Napulog Duha, kinsa adunay mga tinguha nianang akong gipamulong;"},{"verse":38,"text":"Ug pinaagi sa ilang mga tinguha ug sa ilang mga binuhatan mailhan ninyo sila."},{"verse":39,"text":"Ug kon makit-an ninyo sila ipakita ninyo kini nga mga butang ngadto kanila."},{"verse":40,"text":"Ug mangluhod kamo ug mosimba sa Amahan pinaagi sa akong ngalan."},{"verse":41,"text":"Ug kinahanglan mosangyaw kamo ngadto sa kalibotan, nga mag-ingon: Kamo kinahanglan nga maghinulsol ug magpabunyag, pinaagi sa ngalan ni Jesukristo;"},{"verse":42,"text":"Kay ang tanang tawo kinahanglan nga maghinulsol ug magpabunyag, ug dili lamang ang mga lalaki, apan ang mga babaye, ug ang mga bata kinsa miabot na sa edad sa pagkamay-tulubagon."},{"verse":43,"text":"Ug karon, human kamo makadawat niini, kinahanglan nga sundon ninyo ang akong mga sugo sa tanang butang;"},{"verse":44,"text":"Ug pinaagi sa inyong mga kamot magbuhat ako og katingalahan nga buhat taliwala sa mga anak sa katawhan, ngadto sa pagkabig sa ilang daghan nga mga sala, aron sila maghinulsol, ug aron sila makaadto sa gingharian sa akong Amahan."},{"verse":45,"text":"Mao nga, ang mga panalangin nga ihatag nako kaninyo labaw pa sa tanang butang."},{"verse":46,"text":"Ug human nga kamo makadawat niini, kon kamo dili mosunod sa akong mga sugo dili kamo maluwas sa gingharian sa akong Amahan."},{"verse":47,"text":"Tan-awa, ako, si Jesukristo, inyong Ginoo ug inyong Dios, ug inyong Manunubos, pinaagi sa gahom sa akong Espiritu namulong niini. Amen."}]},{"chapter":19,"verses":[{"verse":1,"text":"Ako ang Alpha ug ang Omega, si Kristo ang Ginoo; gani ako mao siya, ang sinugdanan ug ang kataposan, ang Manunubos sa kalibotan."},{"verse":2,"text":"Ako, human nga nakahimo ug nakatapos sa iyang kabubut-on kang kinsa ako nahilakip, gani sa Amahan, mahitungod kanako—ug gihimo ko kini nga ako unta makabuntog sa tanang butang sa akong kaugalingon—"},{"verse":3,"text":"Naghupot sa tanang gahom, gani ngadto sa paglaglag ni Satanas ug sa iyang buhat sa kataposan sa kalibotan, ug sa kataposan nga mahinungdanong adlaw sa paghukom, nga akong ipakanaog nganha sa mga lumulupyo niana, sa paghukom sa matag tawo sumala sa iyang mga gibuhat ug sa binuhatan nga iyang gihimo."},{"verse":4,"text":"Ug sa pagkatinuod ang matag tawo kinahanglan nga maghinulsol o mag-antos, kay ako, ang Dios, walay kataposan."},{"verse":5,"text":"Mao nga, dili ako mobakwi sa mga paghukom nga akong ipakanaog, apan modangat ang mga kaalaotan, pagdangoyngoy, pag-agulo ug pagpangagot sa mga ngipon, oo, ngadto kanila nga anaa dapit sa akong wala nga kamot."},{"verse":6,"text":"Bisan pa niana, wala mahisulat nga dili matapos kini nga kasakit, apan nahisulat nga kini walay kataposang pagsakit."},{"verse":7,"text":"Usab, nahisulat nga kini walay kataposang panghimaraot; mao nga mas klaro kini kaysa ubang kasulatan, aron kini motandog sa mga kasingkasing sa mga anak sa katawhan, tanan maghiusa alang sa himaya sa akong ngalan."},{"verse":8,"text":"Mao nga, akong ipasabot kanimo kini nga misteryo, kay angay nimo kining mahibaloan gani sama sa akong apostoles."},{"verse":9,"text":"Sultihan ko kamong mga pinili niining mga butanga, sama nga kamo usa ra, aron kamo makasulod sa akong kapahulayan."},{"verse":10,"text":"Kay, tan-awa, ang misteryo sa pagka-diosnon, pagkamahinungdanon niini! Kay, tan-awa, ako walay kataposan, ug ang silot nga ihatag gikan sa akong kamot walay kataposan nga silot, kay Walay Kataposan mao ang akong ngalan. Mao nga—"},{"verse":11,"text":"Walay kataposan nga silot ang silot sa Dios."},{"verse":12,"text":"Ang walay kataposan nga silot mao ang silot sa Dios."},{"verse":13,"text":"Mao nga, mandoan ko ikaw sa paghinulsol, ug sa pagsunod sa mga sugo nga imong nadawat pinaagi sa kamot sa akong sulugoon nga si Joseph Smith, Jun., pinaagi sa akong ngalan;"},{"verse":14,"text":"Ug pinaagi sa akong walay kinutoban nga gahom nga ikaw nakadawat niini;"},{"verse":15,"text":"Busa mandoan ko ikaw sa paghinulsol—paghinulsol, tingali unya og hampakon ko ikaw pinaagi sa pulong sa akong ba-ba, ug pinaagi sa akong kaligutgot ug pinaagi sa akong kasuko, ang imong mga pag-antos hilabihan ka sakit—kon unsa ka sakit ikaw wala masayod, kon unsa ka grabe ikaw wala masayod, oo, kon unsa ka lisod nga antoson ikaw wala masayod."},{"verse":16,"text":"Kay tan-awa, ako, ang Dios, nag-antos niining mga butanga alang sa tanan, aron dili sila mag-antos kon sila maghinulsol;"},{"verse":17,"text":"Apan kon dili sila maghinulsol sila mag-antos gayod sama kanako;"},{"verse":18,"text":"Kansang pag-antos mihimo sa akong kaugalingon, gani ang Dios, nga labing halangdon sa tanan, sa pagkurog tungod sa kasakit, ug sa pag-agas sa dugo sa matag lungag sa panit, ug sa pag-antos sa lawas ug sa espiritu—ug nanghinaot nga ako dili moinom sa mapait nga kopa, ug dili na mopadayon—"},{"verse":19,"text":"Bisan pa niana, himaya ngadto sa Amahan, ug ako nakaambit ug mihuman sa akong mga pagpangandam alang sa mga anak sa katawhan."},{"verse":20,"text":"Mao nga, ako mosugo na usab kanimo sa paghinulsol, kay kon dili, ikaw akong pantonon pinaagi sa akong walay kinutoban nga gahom; ug nga ikaw mokompisal sa imong mga sala, tingali unya og ikaw mag-antos niining mga silot nga akong gipamulong, diin ang pinakagamay, oo, gani ang labing ubos nga matang imong natilawan sa diha nga akong gipalayo ang akong Espiritu."},{"verse":21,"text":"Ug sugoon ko ikaw sa dili pagsangyaw og walay hinungdan gawas sa paghinulsol, ug ayaw ipakita kini nga mga butang ngadto sa kalibotan hangtod nga kini maalamon ngari kanako."},{"verse":22,"text":"Kay dili pa sila mahimong mokaon og karne karon, apan gatas ang ilang kinahanglan nga madawat; mao nga, kinahanglan nga dili sila masayod niini nga mga butang, tingali unya og mangawala sila."},{"verse":23,"text":"Pagkat-on kanako, ug paminaw sa akong mga pulong; lakaw nga magbaton og kaaghop sa akong Espiritu, ug makabaton ikaw og kalinaw ngari kanako."},{"verse":24,"text":"Ako mao si Jesukristo; mianhi ako pinaagi sa kabubut-on sa Amahan, ug ako nagbuhat sa iyang kabubut-on."},{"verse":25,"text":"Ug usab, sugoon ko ikaw nga ayaw kaibog sa asawa sa imong silingan; ni magtinguha sa kinabuhi sa imong silingan."},{"verse":26,"text":"Ug usab, sugoon ko ikaw nga ayaw kaibog sa imong kaugalingon nga kabtangan, apan ihatag kini nga walay pagdumili ngadto sa pag-imprinta sa Basahon ni Mormon, nga naglangkob sa kamatuoran ug pulong sa Dios—"},{"verse":27,"text":"Nga mao ang akong pulong ngadto sa Hentil, nga sa dili madugay moabot ngadto sa mga Judeo, kang kinsa ang mga Lamanita mga salin, nga sila unta motuo sa ebanghelyo, ug dili magpaabot sa usa ka Mesiyas kinsa miabot na."},{"verse":28,"text":"Ug usab, sugoon ko ikaw nga mag-ampo ka sa makusog nga tingog ingon man usab diha sa imong kasingkasing; oo, sa atubangan sa kalibotan ingon man usab sa tago, diha sa kadaghanan ug ingon man usab sa pag-inusara."},{"verse":29,"text":"Ug imong ipahayag ang maayong mga balita, oo, imantala kini sa kabukiran, ug sa matag taas nga dapit, ug taliwala sa katawhan kutob sa imong makita."},{"verse":30,"text":"Ug buhaton nimo kini uban sa tanang pagpaubos, mosalig ngari kanako, dili mobiaybiay batok sa mga mabiaybiayon."},{"verse":31,"text":"Ug mahitungod sa mga doktrina dili ka maghisgot, apan ikaw mopahayag og paghinulsol ug pagtuo diha sa Manluluwas, ug kapasayloan sa mga sala pinaagi sa bunyag, ug pinaagi sa kalayo, oo, gani sa Espiritu Santo."},{"verse":32,"text":"Tan-awa, mao kini ang mahinungdanon ug ang kataposan nga sugo nga akong ihatag kanimo bahin niini nga butang; kay igo na kini alang sa imong inadlaw-adlaw nga paglakaw, gani hangtod sa kataposan sa imong kinabuhi."},{"verse":33,"text":"Ug pag-antos ang imong madawat kon imong ibaliwala kining mga tambag, oo, gani ang kalaglagan sa imong kaugalingon ug kabtangan."},{"verse":34,"text":"Panghatag og tipik sa imong kabtangan, oo, bisan gamayng luna sa imong mga yuta, ug sa tanan gawas sa kabuhian sa imong pamilya."},{"verse":35,"text":"Bayari ang utang nga inyong gikasabotan sa tig-imprinta. Himoang gawasnon ang imong kaugalingon gikan sa pagkaulipon."},{"verse":36,"text":"Biyai ang imong balay ug pinuy-anan, gawas kon magtinguha ka nga makigkita sa imong pamilya;"},{"verse":37,"text":"Ug gawasnong mamulong sa tanan; oo, isangyaw, iawhag, ipahayag ang kamatuoran, gani pinaagi sa kusog nga tingog, pinaagi sa tingog sa pagmaya, pagsinggit—Hosanna, hosanna, bulahan ang ngalan sa Ginoong Dios!"},{"verse":38,"text":"Pag-ampo kanunay, ug akong ibu-bo ang akong Espiritu nganha kanimo, ug daghan kaayo ang imong panalangin—oo, gani labaw pa kay sa kon makaangkon ka og mga bahandi sa yuta ug sa kadaotan nga katugbang sa kantidad niini."},{"verse":39,"text":"Tan-awa, makabasa ba ikaw niini nga dili magmaya ug mabayaw sa imong kasingkasing tungod sa kalipay?"},{"verse":40,"text":"O mahimo ba nga ikaw mopadayon pa isip tiggiya sa buta?"},{"verse":41,"text":"O mahimo ba nga magmapaubsanon ka ug magmaaghop, ug magpakita og kinaiya nga maalamon sa akong atubangan? Oo, duol ngari kanako nga imong Manluluwas. Amen."}]},{"chapter":20,"verses":[{"verse":1,"text":"Ang pagsugod sa Simbahan ni Kristo niining kataposan nga mga adlaw, nga usa ka libo walo ka gatos ug katloan ka tuig sukad sa pag-anhi sa atong Ginoo ug Manluluwas nga si Jesukristo sa mortal nga lawas, kini ingon nga sumala sa pagkaorganisar ug pagkatukod pinasubay sa mga balaod sa atong nasod, pinaagi sa kabubut-on ug mga sugo sa Dios, sa ikaupat nga bulan, ug sa ikaunom nga adlaw sa bulan nga gitawag og Abril—"},{"verse":2,"text":"Diin nga mga sugo gihatag ngadto ni Joseph Smith, Jun., kinsa gitawag sa Dios, ug gi-orden nga apostol ni Jesukristo, nga nahimo nga unang elder niini nga simbahan;"},{"verse":3,"text":"Ug ngadto ni Oliver Cowdery, kinsa gitawag usab sa Dios, nga apostol ni Jesukristo, nga nahimo nga ikaduhang elder niini nga simbahan, ug gi-orden pinaagi sa iyang kamot;"},{"verse":4,"text":"Ug sumala kini sa grasya sa atong Ginoo ug Manluluwas nga si Jesukristo, kinsa nag-angkon sa tanan nga himaya, karon ug sa kahangtoran. Amen."},{"verse":5,"text":"Human nga tinuod nang gipakita ngadto niining una nga elder nga siya nakadawat og kapasayloan sa iyang mga sala, nalambigit siya pag-usab sa mga kahilayan sa kalibotan;"},{"verse":6,"text":"Apan human sa paghinulsol, ug pagpaubos sa iyang kaugalingon sa kinasingkasing, pinaagi sa pagtuo, ang Ginoo nangalagad ngadto kaniya pinaagi sa balaan nga anghel, kansang dagway sama sa kilat, ug kansang mga sapot putli ug puti labaw sa tanan nga maputi;"},{"verse":7,"text":"Ug mihatag ngadto kaniya og mga sugo nga nakapadasig kaniya;"},{"verse":8,"text":"Ug mihatag kaniya og gahom gikan sa kahitas-an, sa mga paagi nga giandam kaniadto, sa paghubad sa Basahon ni Mormon;"},{"verse":9,"text":"Nga naglakip sa rekord sa napukan nga katawhan, ug sa kahingpitan sa ebanghelyo ni Jesukristo ngadto sa mga Hentil ug ngadto sa mga Judeo usab;"},{"verse":10,"text":"Nga gihatag pinaagi sa pagdasig, ug napamatud-an ngadto sa uban pinaagi sa pagpangalagad sa mga anghel, ug gipahayag ngadto sa kalibotan pinaagi kanila—"},{"verse":11,"text":"Nagpamatuod ngadto sa kalibotan nga ang balaan nga mga kasulatan tinuod, ug nga ang Dios nagdasig sa mga tawo ug nagtawag kanila ngadto sa iyang balaan nga buhat niini nga panahon ug henerasyon, ug ingon man usab sa karaang mga henerasyon;"},{"verse":12,"text":"Niana nagpakita nga siya mao gihapon ang Dios kagahapon, karon, ug sa kahangtoran. Amen."},{"verse":13,"text":"Busa, kay nakaangkon og hilabihan ka mahinungdanong mga saksi, pinaagi kanila ang kalibotan pagahukman, gani kutob sa makaangkon og kahibalo niini nga buhat."},{"verse":14,"text":"Ug kadtong modawat niini pinaagi sa pagtuo, ug magbuhat og pagkamatarong, makadawat og korona sa kinabuhing dayon;"},{"verse":15,"text":"Apan kadtong nagpatig-a sa ilang mga kasingkasing pinaagi sa pagkawalay pagtuo, ug mosalikway niini, kini mosumbalik ngadto sa ilang kaugalingon nga panghimaraot—"},{"verse":16,"text":"Kay ang Ginoong Dios namulong niini; ug kami, nga mga elder sa simbahan, nakadungog ug nagpamatuod sa mga pulong sa Halangdon nga hari sa kahitas-an, nga maanaa kaniya ang himaya hangtod sa kahangtoran. Amen."},{"verse":17,"text":"Pinaagi niining mga butanga kami nasayod nga adunay Dios sa langit, kinsa walay kinutoban ug mahangtoron, gikan sa kahangtoran hangtod sa kahangtoran mao gihapon ang walay pagkausab nga Dios, ang magbubuhat sa langit ug sa yuta, ug sa tanan nga butang nga anaa niini;"},{"verse":18,"text":"Ug nga siya milalang sa tawo, lalaki ug babaye, sumala sa iyang kaugalingon nga panagway ug sa iyang kaugalingon nga hitsura, siya milalang kanila;"},{"verse":19,"text":"Ug mihatag kanila og mga sugo nga sila mohigugma ug moserbisyo kaniya, ang bugtong buhi ug tinuod nga Dios, ug nga siya lamang ang bugtong binuhat nga angay nilang simbahon."},{"verse":20,"text":"Apan pinaagi sa paglapas niining mga balaod nga balaan ang tawo nahimong kalibotanon ug yawan-on, ug nahimong tawo nga masalaypon."},{"verse":21,"text":"Mao nga, ang Labaw nga Makagagahom nga Dios mihatag sa iyang Bugtong Anak, sumala sa nahisulat sa mga kasulatan nga gihatag mahitungod kaniya."},{"verse":22,"text":"Siya nag-antos sa mga pagtental apan wala manumbaling niini."},{"verse":23,"text":"Siya gilansang sa krus, namatay, ug mibangon pag-usab sa ikatulong adlaw;"},{"verse":24,"text":"Ug mikayab ngadto sa langit, aron molingkod diha sa tuong kamot sa Amahan, aron maghari uban sa gahom sa labing makagagahom sumala sa kabubut-on sa Amahan;"},{"verse":25,"text":"Nga kutob sa motuo ug magpabunyag pinaagi sa iyang balaan nga ngalan, ug molahutay pinaagi sa pagtuo hangtod sa kataposan, maluwas—"},{"verse":26,"text":"Dili lamang kadtong mituo human siya moanhi sa kinatung-an sa panahon, diha sa mortal nga lawas, apan kadtong tanan nga gikan sa sinugdanan, gani kutob sa gidaghanon sa wala pa siya moanhi, kinsa mituo sa mga pulong sa balaang mga propeta, kinsa namulong kay sila gidasig pinaagi sa gasa sa Espiritu Santo, kinsa sa pagkatinuod mipamatuod kaniya sa tanan nga butang, makaangkon sa kinabuhing dayon,"},{"verse":27,"text":"Ug ingon usab kadtong moabot pagkahuman, kinsa motuo sa mga gasa ug sa balaang mga tawag gikan sa Dios pinaagi sa Espiritu Santo, kinsa nagpamatuod sa Amahan ug sa Anak;"},{"verse":28,"text":"Kansang Amahan, Anak, ug Espiritu Santo usa ka Dios, walay kinutoban ug mahangtoron, walay kataposan. Amen."},{"verse":29,"text":"Ug nahibalo kami nga ang tanang tawo kinahanglang maghinulsol ug motuo sa ngalan ni Jesukristo, ug magsimba sa Amahan sa iyang ngalan ug molahutay sa pagtuo sa iyang ngalan hangtod sa kataposan, o dili sila maluwas sa gingharian sa Dios."},{"verse":30,"text":"Ug nahibalo kami nga ang kapaangayan pinaagi sa grasya sa atong Ginoo ug Manluluwas nga si Jesukristo makiangayon ug tinuod;"},{"verse":31,"text":"Ug nahibalo usab kami, nga ang pagkabalaan pinaagi sa grasya sa atong Ginoo ug Manluluwas nga si Jesukristo makiangayon ug tinuod, ngadto sa tanan kinsa nahigugma ug nagserbisyo sa Dios sa ilang tibuok nga gahom, hunahuna, ug kusog."},{"verse":32,"text":"Apan adunay kalagmitan nga ang tawo mawad-an sa grasya ug mobiya gikan sa buhi nga Dios;"},{"verse":33,"text":"Busa himoa nga ang simbahan mopatalinghog ug mag-ampo kanunay, tingali unya og mahulog sila sa tentasyon;"},{"verse":34,"text":"Oo, ug bisan gani himoa nga kadtong kinsa gibalaan mopatalinghog usab."},{"verse":35,"text":"Ug nahibalo kami nga kining mga butanga tinuod ug sumala sa mga pagpadayag ni Juan, wala kini magdugang, ni magtangtang gikan sa panagna mahitungod sa iyang basahon, ang balaan nga mga kasulatan, o mga pagpadayag sa Dios nga moabot sa dili madugay pinaagi sa gasa ug gahom sa Espiritu Santo, sa tingog sa Dios, o sa pagpangalagad sa mga anghel."},{"verse":36,"text":"Ug ang Ginoong Dios namulong niini; ug ang dungog, gahom ug himaya ihatag ngadto sa iyang balaan nga ngalan, karon ug sa kahangtoran. Amen."},{"verse":37,"text":"Ug usab, pinaagi sa sugo ngadto sa simbahan kabahin sa paagi sa bunyag—Ang tanan nga magpaubos sa ilang mga kaugalingon sa atubangan sa Dios, ug magtinguha nga magpabunyag, ug moduol uban ang masulob-on nga mga kasingkasing ug mahinulsolon nga mga espiritu, ug magpamatuod sa atubangan sa simbahan nga sila tinud-anay nga naghinulsol sa tanan nilang sala, ug andam sila sa pagdala diha kanila sa ngalan ni Jesukristo, nga adunay determinasyon sa pagserbisyo kaniya hangtod sa kataposan, ug sa pagkatinuod magpakita pinaagi sa ilang mga buhat nga sila nakadawat sa Espiritu ni Kristo ngadto sa kapasayloan sa ilang mga sala, pagadawaton pinaagi sa bunyag ngadto sa iyang simbahan."},{"verse":38,"text":"Ang katungdanan sa mga elder, mga pari, mga magtutudlo, mga deakono, ug mga sakop sa simbahan ni Kristo—Ang usa ka apostol usa ka elder, ug iyang balaan nga tawag ang pagbunyag;"},{"verse":39,"text":"Ug ang pag-orden sa uban nga mga elder, mga pari, mga magtutudlo, ug mga deakono;"},{"verse":40,"text":"Ug ang pagpanalangin sa pan ug bino—ang mga simbolo sa lawas ug dugo ni Kristo—"},{"verse":41,"text":"Ug ang pagkompirma niadtong kinsa nabunyagan sa simbahan, pinaagi sa pagpandong sa mga kamot alang sa bunyag sa kalayo ug sa Espiritu Santo, sumala sa mga kasulatan;"},{"verse":42,"text":"Ug ang pagtudlo, pagpatin-aw, pag-awhag, pagbunyag, ug pagbantay sa simbahan;"},{"verse":43,"text":"Ug ang pagkompirma diha sa simbahan pinaagi sa pagpandong sa mga kamot, ug ang paghatag sa Espiritu Santo;"},{"verse":44,"text":"Ug sa pagpangulo sa tanang miting."},{"verse":45,"text":"Ang mga elder kinahanglan mopahigayon sa mga miting samtang sila gigiyahan sa Espiritu Santo, sumala sa mga sugo ug mga pagpadayag sa Dios."},{"verse":46,"text":"Ang katungdanan sa pari mao ang pagsangyaw, pagtudlo, pagpatin-aw, pag-awhag, ug pagbunyag, ug pagpanalangin sa sakramento,"},{"verse":47,"text":"Ug moduaw sa balay sa matag miyembro, ug moawhag kanila sa pag-ampo sa dayag ug sa tago, ug pagbuhat sa tanang katungdanan sa pamilya."},{"verse":48,"text":"Ug siya usab mahimong mo-orden sa uban nga mga pari, mga magtutudlo, ug mga deakono."},{"verse":49,"text":"Ug siya ang mangulo sa mga miting kon walay elder nga motambong;"},{"verse":50,"text":"Apan kon adunay elder nga motambong, siya igo lamang sa pagsangyaw, pagtudlo, pagpatin-aw, pag-awhag, ug pagbunyag,"},{"verse":51,"text":"Ug moduaw sa balay sa matag miyembro, mag-awhag kanila sa pag-ampo sa dayag ug sa tago ug pagbuhat sa tanang katungdanan sa pamilya."},{"verse":52,"text":"Sa tanan niining katungdanan ang pari mao ang moabag sa elder kon gikinahanglan sa kahigayonan."},{"verse":53,"text":"Ang katungdanan sa magtutudlo mao ang pagbantay sa simbahan kanunay, ug makig-uban ug molig-on kanila;"},{"verse":54,"text":"Ug sa pagtan-aw nga walay pagkadaotan sa simbahan, ni dili maayong pagbati sa usag usa, ni pamakak, paglibak, ni pagsulti og daotan;"},{"verse":55,"text":"Ug moseguro nga ang simbahan magkatigom sa kanunay, ug usab sa pagseguro nga ang tanang miyembro mohimo sa ilang katungdanan."},{"verse":56,"text":"Ug siya mangulo sa mga miting kon walay motambong nga elder o pari—"},{"verse":57,"text":"Ug pagatabangan kanunay, sa iyang tanan nga katungdanan sa simbahan, sa mga deakono, kon gikinahanglan sa kahigayonan."},{"verse":58,"text":"Apan ang mga magtutudlo ni ang mga deakono walay katungod sa pagbunyag, pagpanalangin sa sakramento, o pagpandong sa mga kamot;"},{"verse":59,"text":"Apan sila, hinuon, mopasidaan, mopatin-aw, moawhag, ug motudlo, ug modapit sa tanan sa pagduol ngadto ni Kristo."},{"verse":60,"text":"Ang matag elder, pari, magtutudlo, o deakono i-orden sumala sa mga gasa ug sa balaang mga tawag sa Dios ngadto kaniya; ug siya i-orden pinaagi sa gahom sa Espiritu Santo, nga mao ang anaa sa tawo nga nag-orden kaniya."},{"verse":61,"text":"Ang pipila ka elder nga naglangkob niini nga simbahan ni Kristo kinahanglan nga magtigom sa komperensiya makausa sa tulo ka bulan, o matag karon ug unya sumala sa gihisgotan sa maong mga komperensiya nga gikinahanglan ug gihatag;"},{"verse":62,"text":"Ug ang gihisgotan nga mga komperensiya mobuhat sa bisan unsa nga buluhaton sa simbahan nga gikinahanglan nga pagabuhaton niana nga panahon."},{"verse":63,"text":"Ang mga elder modawat sa ilang mga lisensya gikan sa ubang mga elder, pinaagi sa pagbotar sa simbahan diin sila nahisakop, o gikan sa mga komperensiya."},{"verse":64,"text":"Matag pari, magtutudlo, o deakono, kinsa gi-orden pinaagi sa usa ka pari, mahimong mokuha sa sertipiko gikan kaniya sa panahon, diin nga sertipiko, kon ipresentar ngadto sa usa elder, makahatag kaniya og lisensya, nga mohatag kaniya og pagtugot sa pagpahigayon sa mga katungdanan sa iyang balaan nga tawag, o siya mahimong modawat niini diha sa usa ka komperensiya."},{"verse":65,"text":"Walay tawo nga i-orden ngadto sa bisan unsa nga katungdanan niini nga simbahan, diin adunay tukma nga natukod nga branch, kon walay pagbotar niana nga simbahan;"},{"verse":66,"text":"Apan ang tigdumala nga mga elder, nagpanaw nga mga bishop, mga high councilor, mga high priest, ug mga elder, tingali adunay pribilihiyo sa pag-orden, sa dapit nga walay branch sa simbahan nga mahimong pagahimoon ang pagboto."},{"verse":67,"text":"Ang matag presidente sa labaw nga pagkapari (o nagdumala nga elder), bishop, high councilor, ug high priest, i-orden pinaagi sa giya sa labaw nga konseho, o sa kinatibuk-an nga komperensiya."},{"verse":68,"text":"Ang katungdanan sa mga miyembro human sila madawat pinaagi sa bunyag—Ang mga elder o mga pari kinahanglan nga adunay igong panahon sa pagpatin-aw sa tanang butang mahitungod sa simbahan ni Kristo ngadto sa ilang pagsabot, sa dili pa sila moambit sa sakramento ug gikompirmahan pinaagi sa pagpandong sa mga kamot sa mga elder, aron ang tanan nga butang mahimo sa husto nga paagi."},{"verse":69,"text":"Ug ang mga miyembro mopakita ngadto sa simbahan, ug usab sa mga elder, pinaagi sa matarong nga kinabuhi ug sa pagpanulti, nga sila takos niini, aron adunay mga buhat ug pagtuo nga mahiuyon sa balaang mga kasulatan—naglakaw nga balaan sa atubangan sa Ginoo."},{"verse":70,"text":"Ang matag miyembro sa simbahan ni Kristo nga adunay mga anak modala kanila ngadto sa mga elder sa simbahan, kinsa mopandong sa ilang mga kamot diha kanila sa ngalan ni Jesukristo, ug mopanalangin kanila pinaagi sa iyang ngalan."},{"verse":71,"text":"Walay usa nga madawat sa simbahan ni Kristo gawas kon siya moabot sa panuigon sa pagkamay-tulubagon sa atubangan sa Dios, ug makahimo sa paghinulsol."},{"verse":72,"text":"Ang bunyag kinahanglan pagabuhaton sa mosunod nga paagi ngadto sa tanang maghinulsol—"},{"verse":73,"text":"Ang tawo kinsa gitawag sa Dios ug adunay awtoridad gikan ni Jesukristo sa pagbunyag, mokanaog ngadto sa tubig uban sa tawo kinsa mitugyan sa iyang kaugalingon aron magpabunyag, ug mosulti, motawag sa iyang ngalan: Ingon nga sinugo ni Jesukristo, ako mobunyag kanimo sa ngalan sa Amahan, ug sa Anak, ug sa Espiritu Santo. Amen."},{"verse":74,"text":"Dayon iyang ipaunlod siya sa tubig, ug ihaw-as usab gikan sa tubig."},{"verse":75,"text":"Gikinahanglan nga ang simbahan magpundok kanunay aron sa pag-ambit sa pan ug bino agi og handomanan ni Ginoong Jesus;"},{"verse":76,"text":"Ug ang elder o ang pari manalangin niini; ug niini nga paagi siya manalangin niini—siya moluhod uban sa simbahan ug motawag sa Amahan sa maligdong nga pag-ampo, nga mag-ingon:"},{"verse":77,"text":"O Dios, ang Amahan sa Kahangtoran, kami mohangyo kanimo pinaagi sa ngalan sa imong Anak nga si Jesukristo, sa pagpanalangin ug pagbalaan niining pan alang sa mga kalag sa tanan nga moambit niini, nga sila mokaon isip paghinumdom sa lawas sa imong Anak, ug mosaksi nganha kanimo, O Dios, ang Amahan sa Kahangtoran, nga sila andam nga modala diha kanila sa ngalan sa imong Anak, ug sa kanunay mohinumdom kaniya ug mosunod sa iyang mga sugo nga iyang gihatag kanila; aron sila sa kanunay makabaton sa iyang Espiritu uban kanila. Amen."},{"verse":78,"text":"Ang paagi sa pagpanalangin sa bino—kuhaon usab niya ang kopa, ug moingon:"},{"verse":79,"text":"O Dios, ang Amahan sa Kahangtoran, kami mohangyo kanimo pinaagi sa ngalan sa imong Anak nga si Jesukristo, sa pagpanalangin ug pagbalaan niining bino alang sa mga kalag sa tanan nga moinom niini, nga sila mohimo niini isip paghinumdom sa dugo sa imong Anak, nga gipaagas alang kanila; nga sila mosaksi nganha kanimo, O Dios, ang Amahan sa Kahangtoran, nga sila sa kanunay mohinumdom kaniya, aron sila makabaton sa iyang Espiritu uban kanila. Amen."},{"verse":80,"text":"Bisan kinsa nga miyembro sa simbahan ni Kristo nga nakalapas, o nakahimo og usa ka sayop, tagdon sumala sa nasulat sa mga kasulatan."},{"verse":81,"text":"Katungdanan sa daghang simbahan, nga nalakip sa simbahan ni Kristo, sa pagpadala og usa o daghan pa sa ilang mga teacher aron sa pagtambong sa pipila ka komperensiya nga gihimo sa mga elder sa simbahan,"},{"verse":82,"text":"Gamit ang usa ka lista sa mga ngalan sa pipila ka miyembro nga nakighiusa sa ilang kaugalingon uban sa simbahan sukad sa miaging komperensiya; o ipadala pinaagi sa pipila ka pari; aron ang regular nga lista sa tanang ngalan sa tibuok simbahan matipigan diha sa basahon sa usa sa mga elder, bisan kinsa man nga itudlo sa uban nga elder matag karon ug unya;"},{"verse":83,"text":"Ug usab, si bisan kinsa nga gitangtang sa pagkamiyembro sa simbahan, niana ang ilang mga ngalan papason gikan sa kinatibuk-an nga rekord sa mga ngalan sa simbahan."},{"verse":84,"text":"Ang tanang miyembro nga mobalhin gikan sa simbahan diin sila nagpuyo, kon motambong sa simbahan diin sila wala mailhi, mahimo nga magdala og sulat nga magpamatuod nga sila masulundon nga mga miyembro ug maayo ang dungog, diin nga pagpamatuod mahimong pirmahan ni bisan kinsa nga elder o pari kon ang miyembro nga modawat sa sulat sa iyang kaugalingon nakaila sa elder o pari, o kini mahimong pirmahan sa mga teacher o mga deacon sa simbahan."}]},{"chapter":21,"verses":[{"verse":1,"text":"Tan-awa, adunay rekord nga inyong tipigan; ug nasulat diha niini nga ikaw pagatawgon nga manalagna, tighubad, propeta, apostol ni Jesukristo, elder sa simbahan pinaagi sa kabubut-on sa Dios nga Amahan, ug sa grasya sa inyong Ginoong Jesukristo,"},{"verse":2,"text":"Ingon nga gidasig sa Espiritu Santo sa pagpahimutang sa pundasyon niini, ug sa pagtukod niini ngadto sa labing balaan nga pagtuo."},{"verse":3,"text":"Diin nga simbahan natukod ug naestablisar sa tuig sa inyong Ginoo napulo ug walo ka gatos ug katloan, sa ikaupat nga bulan, ug sa ikaunom nga adlaw sa bulan nga gitawag og Abril."},{"verse":4,"text":"Mao nga, buot ipasabot ang simbahan, ikaw maminaw sa iyang tanan nga pulong ug sugo nga iyang gihatag kanimo sama sa iyang pagdawat niini, maglakaw sa tanan nga pagkabalaan sa akong atubangan;"},{"verse":5,"text":"Kay ang iyang pulong imong madawat, sama og gikan sa akong kaugalingon nga ba-ba, sa tumang pagpailob ug pagtuo."},{"verse":6,"text":"Kay pinaagi sa pagbuhat niining mga butanga ang mga ganghaan sa impyerno dili makabuntog batok kanimo; oo, ug ang Ginoong Dios mopatibulaag sa mga gahom sa kangitngit gikan sa imong atubangan, ug mohimo sa mga langit sa pagkurog alang sa imong kaayohan, ug himaya sa iyang ngalan."},{"verse":7,"text":"Kay sa ingon niana miingon ang Ginoong Dios: Kaniya ako nagdasig sa pagbuhat sa kawsa sa Zion sa labing gamhanan nga gahom alang sa kaayohan, ug nasayod ako sa iyang kakugi, ug nakadungog ako sa iyang mga pag-ampo."},{"verse":8,"text":"Oo, akong nakita ang iyang pagbakho alang sa Zion, ug akong himoon nga siya dili na magsubo alang kaniya; kay ang mga adlaw sa iyang kalipay miabot ngadto sa kapasayloan sa iyang mga sala, ug sa mga pagpaila sa akong mga panalangin diha sa iyang mga buhat."},{"verse":9,"text":"Kay, tan-awa, ako mopanalangin niadtong tanan kinsa naghago sa akong ubasan uban sa daghang panalangin, ug motuo sila sa iyang mga pulong, nga gihatag ngadto kaniya pinaagi kanako pinaagi sa Maghuhupay, kinsa nagpadayag nga si Jesus gilansang sa krus sa mga tawo nga makasasala alang sa mga sala sa kalibotan, oo, alang sa kapasayloan sa mga sala ngadto sa mahinulsolon nga kasingkasing."},{"verse":10,"text":"Mao nga nagtinguha ako nga siya i-orden pinaagi kanimo, Oliver Cowdery akong apostol;"},{"verse":11,"text":"Kini isip usa ka ordinansa nganha kanimo, nga ikaw usa ka elder ubos sa iyang awtoridad, siya isip nahiuna kanimo, nga ikaw mahimong usa ka elder niini nga simbahan ni Kristo, nga magdala sa akong ngalan—"},{"verse":12,"text":"Ug ang unang tigsangyaw niini nga simbahan ngadto sa mga miyembro, ug ngadto sa kalibotan, oo, ngadto sa mga Hentil; oo, ug sa ingon niana miingon ang Ginoong Dios, tan-awa, tan-awa! usab ang mga Judeo. Amen."}]},{"chapter":22,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko kamo nga ang tanang karaan nga pakigsaad akong gimando nga wagtangon niining butanga; ug kini ang bag-o ug walay kataposan nga pakigsaad, gani kana nga gikan pa sa sinugdanan."},{"verse":2,"text":"Mao nga, bisan og ang usa ka tawo bunyagan og usa ka gatos ka higayon kini dili makatabang kaniya, kay kamo dili makasulod sa higpit nga ganghaan pinaagi sa balaod ni Moises, ni pinaagi sa inyong mga buhat nga walay hinungdan."},{"verse":3,"text":"Kay tungod sa inyong mga buhat nga walay hinungdan akong gimando nga kining kataposan nga pakigsaad ug kini nga simbahan pagatukoron ngari kanako, gani sama sa karaang mga adlaw."},{"verse":4,"text":"Mao nga, sulod kamo sa ganghaan, sumala sa akong gisugo, ug ayaw tinguhaa ang pagtambag sa inyong Dios. Amen."}]},{"chapter":23,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko ikaw, Oliver, og pipila ka pulong. Tan-awa, ikaw bulahan, ug ikaw dili ubos sa panghimaraot. Apan pagbantay sa garbo, tingali unya og ikaw matental."},{"verse":2,"text":"Himoa nga mahibaloan ang imong balaan nga tawag ngadto sa simbahan, ug usab sa atubangan sa kalibotan, ug ang imong kasingkasing maablihan sa pagsangyaw sa kamatuoran gikan karon ug sa kahangtoran. Amen."},{"verse":3,"text":"Tan-awa, sultihan ko ikaw, Hyrum, sa pipila ka pulong; kay ikaw usab dili ubos sa panghimaraot, ug ang imong kasingkasing nagmaluluy-on, ug ang imong dila larinong makasulti; ug ang imong balaan nga tawag mao ang pag-awhag, ug pagpalig-on sa simbahan kanunay. Mao nga ang imong katungdanan alang sa simbahan sa kahangtoran, ug kini tungod sa imong pamilya. Amen."},{"verse":4,"text":"Tan-awa, sultihan ko ikaw og pipila ka pulong, Samuel; ikaw usab dili ubos sa panghimaraot, ug ang imong balaan nga tawag mao ang pag-awhag, ug pagpalig-on sa simbahan; ug ikaw wala pa matawag sa pagsangyaw ngadto sa kalibotan. Amen."},{"verse":5,"text":"Tan-awa, sultihan ko ikaw og pipila ka pulong, Joseph; kay ikaw usab dili ubos sa panghimaraot, ug ang imong balaan nga tawag usab mao ang pag-awhag, ug pagpalig-on sa simbahan; ug kini mao ang imong katungdanan gikan karon ug sa kahangtoran. Amen."},{"verse":6,"text":"Tan-awa, ipaila nako kanimo, Joseph Knight, pinaagi niini nga mga pulong, nga ikaw gayod mopas-an sa imong krus, nga ikaw kinahanglan nga mag-ampo sa dayag sa atubangan sa kalibotan ug usab sa tago, ug sa imong pamilya, ug sa imong mga higala, ug sa tanang dapit."},{"verse":7,"text":"Ug, tan-awa, kini mao ang imong katungdanan sa pagpakighiusa sa tinuod nga simbahan, ug ihatag ang imong pag-awhag kanunay, nga ikaw unta makadawat sa ganti sa mamumuo. Amen."}]},{"chapter":24,"verses":[{"verse":1,"text":"Tan-awa, ikaw gitawag ug gipili sa pagsulat sa Basahon ni Mormon, ug sa akong pangalagad; ug ikaw akong gibayaw gikan sa imong mga kasakit, ug mitambag kanimo, nga ikaw giluwas gikan sa imong tanan nga kaaway, ug ikaw giluwas gikan sa mga gahom ni Satanas ug gikan sa kangitngit!"},{"verse":2,"text":"Bisan pa niana, ikaw dili mapasaylo sa imong mga kalapasan; bisan pa niana, padayon ug ayaw na pagpakasala."},{"verse":3,"text":"Palamboa ang imong katungdanan; ug human ikaw makapugas sa imong umahan ug makanalipod niini, lakaw dayon ngadto sa simbahan sa Colesville, Fayette, ug Manchester, ug sila mosuporta kanimo; ug ako mopanalangin kanila sa espirituwal ug sa temporal nga paagi;"},{"verse":4,"text":"Apan kon sila dili modawat kanimo, akong ipadala ngadto kanila ang tunglo imbes panalangin."},{"verse":5,"text":"Ug ikaw mopadayon sa pagtawag sa Dios pinaagi sa akong ngalan, ug mosulat sa mga butang nga ihatag kanimo pinaagi sa Maghuhupay, ug mopasabot sa tanang kasulatan ngadto sa simbahan."},{"verse":6,"text":"Ug ihatag diha kanimo niana gayod nga higayon unsay imong ipamulong ug isulat, ug maminaw sila niini, o ako mopadala ngadto kanila og tunglo imbes panalangin."},{"verse":7,"text":"Kay ikaw mohalad sa imong tanan nga pagserbisyo diha sa Zion; ug tungod niini ikaw makabaton og kusog."},{"verse":8,"text":"Pagpailob sa mga kasakit, kay ikaw makasinati og daghan; apan antosa kini, kay, tan-awa, magauban ako kanimo, gani hangtod sa kataposan sa imong mga adlaw."},{"verse":9,"text":"Ug sa temporal nga mga paghago ikaw dili makabaton og kusog, kay kini dili imong balaan nga tawag. Buhata ang imong balaan nga tawag ug maangkon nimo unsay imong gikinahanglan sa imong katungdanan, ug sa pagpasabot sa tanang kasulatan, ug pagpadayon sa pagpandong sa mga kamot ug pagpalig-on sa mga simbahan."},{"verse":10,"text":"Ug ang imong igsoon nga si Oliver mopadayon sa pagpamatuod sa akong ngalan sa atubangan sa kalibotan, ug usab sa simbahan. Ug dili siya magdahom nga makasulti siya og daghan mahitungod sa akong kawsa; ug tan-awa, magauban ako kaniya hangtod sa kataposan."},{"verse":11,"text":"Ngari kanako siya makabaton og himaya, ug dili sa iyang kaugalingon, bisan sa kahuyang o sa kalig-on, bisan sa pagkaulipon o pagkagawasnon;"},{"verse":12,"text":"Ug sa tanang panahon, ug sa tanang dapit, siya mobuka sa iyang ba-ba ug mopahayag sa akong ebanghelyo sama sa tingog sa usa ka trumpeta, sa adlaw ug gabii. Ug hatagan ko siya og kusog nga wala pa mahibaloi taliwala sa katawhan."},{"verse":13,"text":"Ayaw pangayo og mga milagro, gawas kon ako mosugo kaninyo, gawas sa paghingilin sa mga yawa, pagpang-ayo sa mga masakiton, ug batok sa makahilo nga mga bitin, ug batok sa makapatay nga mga hilo;"},{"verse":14,"text":"Ug kining mga butanga dili ninyo buhaton, gawas kon kini gikinahanglan gikan kaninyo sa mga tawo nga nagtinguha niini, nga ang mga kasulatan matuman; kay kamo magbuhat sumala niana nga nahisulat."},{"verse":15,"text":"Ug bisan asa nga dapit kamo mosulod, ug sila dili modawat kaninyo sa akong ngalan, kamo mobilin og tunglo imbes panalangin, pinaagi sa pagtaktak sa mga abog sa inyong mga tiil batok kanila isip usa ka pagpamatuod, ug paglimpyo sa inyong mga tiil diha sa daplin sa agianan."},{"verse":16,"text":"Ug mahitabo nga si bisan kinsa ang mobakyaw sa ilang mga kamot diha kaninyo pinaagi sa kapintas, kamo momando nga pagahampakon pinaagi sa akong ngalan; ug, tan-awa, ako mosilot kanila sumala sa inyong mga pulong, sa akong kaugalingong tukma nga panahon."},{"verse":17,"text":"Ug si bisan kinsa nga modangop sa balaod uban kaninyo pagatunglohon pinaagi sa balaod."},{"verse":18,"text":"Ug kamo dili modala og puntil ni putos sa pagkaon, ni mga sungkod, ni duha ka kupo, kay ang simbahan mohatag kaninyo niana gayod nga takna unsa ang inyong gikinahanglan nga pagkaon ug sapot, ug mga sapatos ug kwarta, ug balon."},{"verse":19,"text":"Kay kamo gitawag sa pagpul-ong sa akong ubasan uban sa gamhanan nga pagpul-ong, oo, gani alang sa kataposan nga higayon; oo, ug usab ngadto sa tanan nga inyong i-orden, ug sila mohimo sumala niini nga paagi. Amen."}]},{"chapter":25,"verses":[{"verse":1,"text":"Patalinghogi ang tingog sa Ginoo nga imong Dios, samtang ako mosulti kanimo, Emma Smith, akong anak; kay sa pagkatinuod sultihan ko ikaw, ang tanan nga nakadawat sa akong ebanghelyo sila mga anak nga lalaki ug mga anak nga babaye sa akong gingharian."},{"verse":2,"text":"Usa ka pagpadayag nga akong ihatag kanimo kabahin sa akong kabubut-on; ug kon ikaw magmatinud-anon ug maglakaw sa dalan nga mahiyason sa akong atubangan, akong luwason ang imong kinabuhi, ug ikaw makadawat og kabilin sa Zion."},{"verse":3,"text":"Tan-awa, ang imong mga sala gipasaylo na, ug ikaw ang pinili nga babaye, nga akong gitawag."},{"verse":4,"text":"Ayaw pagbagulbol tungod sa mga butang nga wala nimo makita, kay kini gitago gikan kanimo ug gikan sa kalibotan, sumala sa akong paghukom sa panahon nga moabot."},{"verse":5,"text":"Ug ang katungdanan sa imong balaan nga tawag mao ang paghupay sa akong sulugoon, si Joseph Smith, Jun., nga imong bana, sa iyang mga kasakit, gamit ang makahupay nga mga pulong, diha sa espiritu sa kaaghop."},{"verse":6,"text":"Ug ikaw mouban kaniya sa oras sa iyang paglakaw, ug mahimong iyang tigsulat, samtang wala pay usa ka tigsulat alang kaniya, aron akong mapadala ang akong sulugoon, si Oliver Cowdery, bisan asa nako gusto."},{"verse":7,"text":"Ug ikaw ordinahan pinaagi sa pagpandong sa iyang mga kamot sa pagpasabot sa mga kasulatan, ug pag-awhag sa simbahan, sumala sa ihatag kanimo sa akong Espiritu."},{"verse":8,"text":"Kay siya mopandong sa iyang mga kamot diha kanimo, ug ikaw makadawat sa Espiritu Santo, ug ang imong panahon igahin sa pagsulat, ug sa daghan nga pagtuon."},{"verse":9,"text":"Ug ikaw dili angay nga mahadlok, kay ang imong bana mosuporta kanimo sa simbahan; kay ngadto kanila mao ang iyang balaan nga tawag, aron ang tanan nga butang ikapadayag ngadto kanila, bisan unsa ang akong gusto, sumala sa ilang pagtuo."},{"verse":10,"text":"Ug sa pagkatinuod sultihan ko ikaw nga imong isalikway ang mga butang niini nga kalibotan, ug tinguhaa ang mga butang nga maayo."},{"verse":11,"text":"Ug ihatag kanimo, usab, ang pagpili sa sagrado nga mga himno, kay ihatag kini nganha kanimo, nga makapahimuot kanako, nga maanaa sa akong simbahan."},{"verse":12,"text":"Kay ang akong kalag mahimuot sa awit sa kasingkasing; oo, ang awit sa mga matarong mao ang usa ka pag-ampo ngari kanako, ug pagatubagon kini sa usa ka panalangin diha sa ilang mga ulo."},{"verse":13,"text":"Mao nga, lipaya ang imong kasingkasing ug pagmaya, ug tumana ang mga pakigsaad nga imong gihimo."},{"verse":14,"text":"Ipadayon ang espiritu sa kaaghop, ug pagmatngon sa garbo. Himoa nga ang imong kalag mahimuot sa imong bana, ug sa himaya nga moabot kaniya."},{"verse":15,"text":"Sunda ang akong mga sugo kanunay, ug ang korona sa pagkamatarong imong madawat. Ug gawas kon ikaw mobuhat niini, kon hain ako ikaw dili makaadto."},{"verse":16,"text":"Ug sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, nga kini ang akong tingog ngadto sa tanan. Amen."}]},{"chapter":26,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko kamo nga kinahanglan ninyong ihalad ang inyong panahon sa pagtuon sa mga kasulatan, ug sa pagsangyaw, ug sa paglig-on sa simbahan sa Colesville, ug sa pagbuhat sa inyong mga buluhaton sa pag-ugmad sa yuta, nga mao ang gikinahanglan, hangtod human kamo moadto sa kasadpan sa paghimo sa sunod nga komperensiya; ug dayon ipahibalo unsay inyong buhaton."},{"verse":2,"text":"Ug ang tanan nga butang pagabuhaton pinaagi sa pag-uyon sa tanang miyembro diha sa simbahan, pinaagi sa daghan nga pag-ampo ug pagtuo, kay ang tanan nga butang inyong madawat pinaagi sa pagtuo. Amen."}]},{"chapter":27,"verses":[{"verse":1,"text":"Paminawa ang tingog ni Jesukristo, imong Ginoo, imong Dios, ug imong Manunubos, kansang mga pulong buhi ug gamhanan."},{"verse":2,"text":"Kay, tan-awa, sultihan ko kamo, nga dili importante unsay inyong kan-on o unsay inyong imnon kon ikaw moambit sa sakramento, kon kamo mobuhat niini uban sa bug-os nga tinguha ngadto sa akong himaya—maghinumdom sa Amahan sa akong lawas nga gitugyan alang kaninyo, ug sa akong dugo nga gipaagas alang sa kapasayloan sa inyong mga sala."},{"verse":3,"text":"Mao nga, usa ka sugo akong ihatag kaninyo, nga kamo dili mopalit og bino ni maisog nga ilimnon gikan sa inyong mga kaaway;"},{"verse":4,"text":"Mao nga, dili kamo moambit gawas kon kini gihimo nga bag-o diha kaninyo; oo, ug niini ang gingharian sa akong Amahan pagatukoron dinhi sa yuta."},{"verse":5,"text":"Tan-awa, kini kaalam ngari kanako; mao nga, ayaw kahibulong, kay ang takna moabot nga ako moinom sa bunga sa ubas uban kaninyo ibabaw sa yuta, ug uban ni Moroni, nga akong gipadala nganha kaninyo sa pagpadayag sa Basahon ni Mormon, nga naglakip sa kahingpitan sa akong walay kataposan nga ebanghelyo, nga akong gitugyanan sa mga yawe sa rekord sa sungkod ni Ephraim;"},{"verse":6,"text":"Ug usab uban ni Elias, nga akong gitugyanan sa mga yawe sa pagpahitabo sa pagpahiuli sa tanan nga butang nga gipamulong sa ba-ba sa tanang balaan nga mga propeta sukad sa sinugdanan sa kalibotan, mahitungod sa kataposang mga adlaw;"},{"verse":7,"text":"Ug usab ni Juan ang anak nga lalaki ni Zacarias, kinsang Zacarias nga iyang (si Elias) giduaw ug gisaaran nga makabaton og usa ka anak nga lalaki, ug ang iyang ngalan mao si Juan, ug siya mapuno sa espiritu ni Elias;"},{"verse":8,"text":"Diin nga Juan gipadala nako nganha kaninyo, akong mga sulugoon, Joseph Smith, Jun., ug Oliver Cowdery, sa pag-orden kaninyo ngadto sa unang pagkapari nga inyong nadawat, nga kamo pagatawagon ug ordinahan sama ni Aaron;"},{"verse":9,"text":"Ug usab ni Elijah, nga akong gitugyanan sa mga yawe sa gahom sa pagpabalik sa mga kasingkasing sa mga amahan ngadto sa mga anak, ug sa mga kasingkasing sa mga anak ngadto sa ilang mga amahan, aron ang tibuok kalibotan dili unta hampakon sa usa ka tunglo;"},{"verse":10,"text":"Ug usab uban ni Jose ug Jacob, ug Isaac, ug Abraham, ang inyong mga amahan, diin ang mga saad nagpabilin;"},{"verse":11,"text":"Ug usab uban ni Miguel, o Adan, ang amahan sa tanan, ang prinsipe sa tanan, ang labing tigulang sa tanan;"},{"verse":12,"text":"Ug usab uban ni Pedro, ug Santiago, ug Juan, nga akong gipadala nganha kaninyo, nga pinaagi kanila ako mi-orden kaninyo ug mikompirma kaninyo nga mahimong apostoles, ug talagsaong mga saksi sa akong ngalan, ug naggunit sa mga yawe sa inyong pangalagad ug sa samang mga butang nga akong gipadayag ngadto kanila;"},{"verse":13,"text":"Ngadto kanila nga akong gitugyanan sa mga yawe sa akong gingharian, ug sa dispensasyon sa ebanghelyo sa kataposang higayon; ug alang sa kahingpitan sa mga panahon, niana akong pundokon sa usa ka dapit ang tanan nga butang, nga anaa sa langit, ug anaa sa yuta;"},{"verse":14,"text":"Ug usab uban niadtong tanan nga gihatag sa akong Amahan kanako gikan sa kalibotan."},{"verse":15,"text":"Mao nga, lipaya ang inyong mga kasingkasing ug pagmaya, ug baksi ang inyong mga bat-ang, ug isul-ob ninyo ang akong tibuok nga taming, aron kamo makasugakod sa daotan nga adlaw, human makabuhat sa tanan, nga kamo makahimo sa pagbarog."},{"verse":16,"text":"Busa, barog, nga binaksan ang inyong mga bat-ang sa kamatuoran, nga gisul-oban sa taming sa pagkamatarong, ug ang inyong mga tiil hinapinan pinaagi sa pagpangandam sa ebanghelyo sa kalinaw, nga akong gipadala sa akong mga anghel aron isalig diha kaninyo;"},{"verse":17,"text":"Magdala sa panagang sa pagtuo diin inyong mabuntog ang tanang nagdilaab nga mga pana sa daotan;"},{"verse":18,"text":"Ug dad-a ang helmet sa kaluwasan, ug ang espada sa akong Espiritu, nga akong ibu-bo kaninyo, ug ang akong pulong nga akong ipadayag kaninyo, ug pagauyonan kabahin sa tanang bisan unsa nga butang nga inyong pangayoon kanako, ug pagmatinud-anon hangtod nga ako moanhi, ug kamo pagadad-on, nga kon hain ako kamo atua usab. Amen."}]},{"chapter":28,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko ikaw, Oliver, nga kini ihatag nganha kanimo aron ikaw patalinghogan sa simbahan sa tanang butang bisan unsa ang imong itudlo kanila pinaagi sa Maghuhupay, kabahin sa mga pagpadayag ug mga sugo nga akong gihatag."},{"verse":2,"text":"Apan, tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, walay lain nga pagapilion nga makadawat og mga sugo ug mga pagpadayag niini nga simbahan gawas sa akong sulugoon nga si Joseph Smith, Jun., kay siya makadawat niini sama ni Moises."},{"verse":3,"text":"Ug ikaw magmasulundon sa mga butang nga akong ihatag ngadto kaniya, bisan sama ni Aaron, sa pagpahayag nga matinud-anon sa mga sugo ug mga pagpadayag, uban ang gahom ug awtoridad ngadto sa simbahan."},{"verse":4,"text":"Ug kon ikaw giyahan sa bisan unsa nga panahon sa Maghuhupay sa pagpamulong o pagtudlo, o sa tanang higayon pinaagi sa sugo ngadto sa simbahan, ikaw magbuhat niini."},{"verse":5,"text":"Apan ikaw dili mosulat nga ipaagi sa usa ka sugo, apan pinaagi sa kaalam;"},{"verse":6,"text":"Ug ikaw dili mosugo kaniya kinsa imong pangulo, ug ang pangulo sa simbahan;"},{"verse":7,"text":"Kay gihatag nako kaniya ang mga yawe sa mga misteryo, ug mga pagpadayag nga giselyohan, hangtod nga ako motudlo ngadto kanila og lain puli sa iyang dapit."},{"verse":8,"text":"Ug karon, tan-awa, sultihan ko ikaw nga moadto ka sa mga Lamanita ug mosangyaw sa akong ebanghelyo ngadto kanila; ug kon sila modawat sa imong mga pagtudlo imong tukoron ang akong simbahan didto kanila; ug ikaw makadawat og mga pagpadayag, apan ayaw kini isulat nga ipaagi sa usa ka sugo."},{"verse":9,"text":"Ug karon, tan-awa, sultihan ko ikaw nga kini wala ipadayag, ug walay tawo nga nasayod asa tukoron ang siyudad sa Zion, apan ihatag kini sa dili madugay. Tan-awa, sultihan ko ikaw nga kini anaa sa mga utlanan sa mga Lamanita."},{"verse":10,"text":"Kinahanglan nga dili ka mobiya niini nga dapit hangtod human sa komperensiya; ug ang akong sulugoon nga si Joseph matudlo nga mao ang modumala sa komperensiya pinaagi sa tingog niini, ug unsa ang iyang isulti kanimo mao ang imong isulti."},{"verse":11,"text":"Ug usab, ikaw modala sa imong igsoon, si Hiram Page, tali kaniya ug kanimo lamang, ug sultihi siya nga kadtong mga butang nga iyang gisulat gikan niana nga bato dili gikan kanako ug nga si Satanas milingla kaniya;"},{"verse":12,"text":"Kay, tan-awa, kini nga mga butang wala pa ihatag ngadto kaniya, ni bisan unsa nga butang ihatag ngadto ni bisan kinsa niini nga simbahan nga supak sa mga pakigsaad sa simbahan."},{"verse":13,"text":"Kay ang tanan nga butang kinahanglan gayod himoon sa kahusay, ug pinaagi sa pag-uyon sa tanan diha sa simbahan, pinaagi sa pag-ampo sa pagtuo."},{"verse":14,"text":"Ug ikaw motabang sa paghusay niniing tanan nga butang, sumala sa mga pakigsaad sa simbahan, sa dili pa ikaw mobiyahe ngadto sa mga Lamanita."},{"verse":15,"text":"Ug kini ihatag kanimo gikan sa higayon nga ikaw molakaw, hangtod sa higayon nga ikaw mobalik, unsa ang imong buhaton."},{"verse":16,"text":"Ug ikaw kinahanglan nga moabli sa imong ba-ba sa tanan nga higayon, mopahayag sa akong ebanghelyo uban sa tingog sa pagmaya. Amen."}]},{"chapter":29,"verses":[{"verse":1,"text":"Paminawa ang tingog ni Jesukristo, nga inyong Manunubos, ang Halangdon nga Ako Mao, kansang bukton sa kaluoy mitubos sa inyong mga sala;"},{"verse":2,"text":"Kinsa mopundok sa iyang katawhan sama sa usa ka himongaan nga mopundok sa iyang mga piso sa ilawom sa iyang mga pako, gani kutob sa mopatalinghog sa akong tingog ug mopaubos sa ilang mga kaugalingon sa akong atubangan, ug motawag kanako pinaagi sa gamhanan nga pag-ampo."},{"verse":3,"text":"Tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga niini nga higayon ang inyong mga sala gipasaylo na, busa madawat ninyo kining mga butanga; apan hinumdomi nga dili na magpakasala, basin unya og ang mga katalagman moabot kaninyo."},{"verse":4,"text":"Sa pagkatinuod, sultihan ko kamo nga kamo gipili gikan sa kalibotan aron sa pagpahayag sa akong ebanghelyo uban sa tingog sa pagmaya, sama sa tingog sa trumpeta."},{"verse":5,"text":"Lipaya ang inyong mga kasingkasing ug pagmaya, kay ako anaa sa inyong taliwala, ug ako ang inyong manlalaban ngadto sa Amahan; ug kini ang iyang matarong nga tinguha sa paghatag kaninyo sa gingharian."},{"verse":6,"text":"Ug, sumala sa nahisulat—Bisan unsa ang inyong pangayoon pinaagi sa pagtuo, nga nagkahiusa sa pag-ampo sumala sa akong sugo, kamo makadawat."},{"verse":7,"text":"Ug kamo gitawag sa pagpahitabo sa pagpundok sa akong pinili; kay ang akong pinili makadungog sa akong tingog ug dili magpatig-a sa ilang mga kasingkasing;"},{"verse":8,"text":"Mao nga ang sugo gipahayag gikan sa Amahan nga sila pagapundokon ngadto sa usa ka dapit sa ibabaw niini nga yuta, aron pag-andam sa ilang mga kasingkasing ug makapangandam sa tanang butang batok sa adlaw diin ang kalisdanan ug katalagman ipadala diha sa mga daotan."},{"verse":9,"text":"Kay ang takna duol na ug ang adlaw hapit na moabot diin ang yuta mahinog na; ug ang tanang mapasigarbohon ug sila nga nagbuhat og daotan mahimong sama sa dagami; ug sunogon nako sila, miingon ang Ginoo sa mga Panon, aron ang pagkadaotan mawala na sa ibabaw sa yuta;"},{"verse":10,"text":"Kay ang takna duol na, ug kana nga gipamulong na sa akong apostoles kinahanglan nga matuman; kay sumala sa ilang gipamulong kini mahitabo;"},{"verse":11,"text":"Kay ipadayag nako ang akong kaugalingon gikan sa langit uban sa gahom ug dakong himaya, uban sa tanang panon niini, ug magpuyo sa pagkamatarong uban sa mga tawo diha sa yuta sa liboan ka tuig, ug ang mga daotan dili makalahutay."},{"verse":12,"text":"Ug usab, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, ug kini gipahayag pinaagi sa hugot nga mando, pinaagi sa kabubut-on sa Amahan, nga ang akong mga apostol, ang Napulog Duha nga uban kanako sa akong pagpangalagad sa Jerusalem, mobarog sa dapit sa akong tuong kamot sa adlaw sa akong pag-anhi sa usa ka dakong haligi sa kalayo, sinul-oban sa kupo sa pagkamatarong, uban sa mga korona diha sa ibabaw sa ilang mga ulo, diha sa himaya gani sama kanako, sa paghukom sa tibuok balay ni Israel, kutob sa nahigugma kanako ug nagtuman sa akong mga sugo, ug wala nay lain."},{"verse":13,"text":"Kay usa ka trumpeta ang motingog og dugay ug lanog, gani sa ibabaw sa Bukid sa Sinai, ug ang tibuok yuta mauyog, ug sila mobangon—oo, gani ang mga patay nga namatay tungod kanako, sa pagdawat sa korona sa pagkamatarong, ug pagasul-oban, bisan sama kanako, aron makig-uban kanako, aron kami magkahiusa."},{"verse":14,"text":"Apan, tan-awa, sultihan ko kamo nga sa dili pa moabot kining mahinungdanon nga adlaw ang adlaw mongitngit, ug ang bulan mahimong dugo, ug ang mga bitoon mahulog gikan sa langit, ug adunay labaw nga talagsaong mga timailhan sa ibabaw sa langit ug sa ubos sa yuta;"},{"verse":15,"text":"Ug adunay mga pagdanguyngoy ug pag-agulo diha sa pundok sa katawhan;"},{"verse":16,"text":"Ug adunay dakong unos nga may mga bugon sa yelo nga ipadala aron sa paglaglag sa mga tanom sa yuta."},{"verse":17,"text":"Ug mahitabo, tungod sa pagkadaotan sa kalibotan, nga ako manimalos sa mga daotan, kay dili sila maghinulsol; kay ang kopa sa akong kapungot napuno na; kay tan-awa, ang akong dugo dili makalimpyo kanila kon sila dili maminaw kanako."},{"verse":18,"text":"Mao nga, ako ang Ginoong Dios mopadala og mga langaw sa ibabaw sa yuta, nga mao ang mohugpa sa tanang lumulupyo niini, ug mokaon sa ilang mga unod, ug mohimo sa mga ulod nga modagsang diha kanila;"},{"verse":19,"text":"Ug ang ilang mga dila moungot nga sila dili na makasulti batok kanako; ug ang ilang mga unod mangahulog gikan sa ilang mga bukog, ug ang ilang mga mata gikan sa ilang nahimutangan;"},{"verse":20,"text":"Ug mahitabo nga ang mga hayop sa kalasangan ug ang mga mananap sa kahanginan mokaon kanila."},{"verse":21,"text":"Ug ang gamhanan ug salawayon nga simbahan, nga mao ang nagbaligya sa iyang dungog sa tibuok yuta, itambog ngadto sa nagdilaab nga kalayo, sumala sa gipamulong sa ba-ba ni Ezequiel ang propeta, kinsa namulong niining mga butanga, nga wala pa mahitabo apan sa pagkatinuod mahitabo gayod, samtang ako buhi, kay ang pagkasalawayon dili magmando."},{"verse":22,"text":"Ug usab, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo nga kon ang usa ka libo ka tuig matapos na, ug ang mga tawo mosugod na usab paglimod sa ilang Ginoo, niana luwason nako ang yuta apan sa mubo nga panahon;"},{"verse":23,"text":"Ug ang kataposan moabot, ug ang langit ug ang yuta pagaugdawon ug mahanaw, ug adunay bag-o nga langit ug bag-o nga yuta."},{"verse":24,"text":"Kay ang tanan nga daang butang mahanaw, ug ang tanang butang mahimong bag-o, bisan ang langit ug ang yuta, ug ang tanan nga kahingpitan niini, mga tawo ug mga hayop, ug mga langgam sa kahanginan, ug mga isda sa kadagatan;"},{"verse":25,"text":"Ug walay usa ka buhok, ni muta, nga mawala, kay kini binuhat sa akong kamot."},{"verse":26,"text":"Apan, tan-awa, sa pagkatinuod sultihan ko kamo, sa dili pa mahanaw ang yuta, si Miguel, ang akong arkanghel, mopatingog sa iyang trumpeta, ug unya ang tanang patay mahigmata, kay ang ilang mga lubnganan maabli, ug sila mobangon—oo, gani ang tanan."},{"verse":27,"text":"Ug ang matarong pagapundokon sa dapit sa akong tuong kamot ngadto sa kinabuhing dayon; ug ang mga daotan dapit sa akong walang kamot nga maulaw ako nga moangkon sa atubangan sa akong Amahan;"},{"verse":28,"text":"Mao nga sultihan ko sila—Biya gikan kanako, kamo nga gitunglo, ngadto sa walay kataposan nga kalayo, nga giandam alang sa yawa ug sa iyang mga anghel."},{"verse":29,"text":"Ug karon, tan-awa, sultihan ko kamo, wala sukad sa bisan unsa nga higayon nga ako nagpahayag gikan sa akong kaugalingong ba-ba nga sila mobalik, kay kon asa ako sila dili makaadto, kay sila walay gahom."},{"verse":30,"text":"Apan hinumdomi nga ang akong tanan nga paghukom dili ihatag ngadto sa mga tawo; ug kay ang akong mga pulong migula gikan sa akong ba-ba gani diha niana kini matuman, nga ang nag-una mao ang maulahi, ug nga ang naulahi mao ang mag-una sa tanan nga butang bisan unsa nga akong gilalang pinaagi sa pulong sa akong gahom, nga mao ang gahom sa akong Espiritu."},{"verse":31,"text":"Kay pinaagi sa gahom sa akong Espiritu ako milalang niini; oo, ang tanan nga butang nga espirituwal ug temporal—"},{"verse":32,"text":"Ang una espirituwal, ug ang ikaduha temporal, nga mao ang sinugdanan sa akong buhat; ug usab, una ang temporal ug ang ikaduha espirituwal, diin mao ang kataposan sa akong buluhaton—"},{"verse":33,"text":"Namulong kaninyo aron makasabot kamo sa yanong paagi; apan ngari sa akong kaugalingon ang akong mga buhat walay kataposan, ni sinugdanan; apan gihatag kini kaninyo aron kamo makasabot, tungod kay kamo nangutana niini kanako ug nagkahiusa."},{"verse":34,"text":"Mao nga, sa pagkatinuod sultihan ko kamo nga ang tanang butang ngari kanako espirituwal, ug wala mahitabo sa bisan unsang panahon nga mihatag ko kaninyo og balaod nga temporal; ni bisan kinsa nga tawo, ni sa katawhan, ni si Adan, nga inyong amahan, kinsa akong gilalang."},{"verse":35,"text":"Tan-awa, gihatag nako kaniya nga siya kinahanglan nga molihok alang sa iyang kaugalingon; ug mihatag ako kaniya og sugo, apan walay temporal nga sugo nga akong gihatag kaniya, kay ang akong mga sugo espirituwal; kini dili kinaiyanhon ni temporal, ni kalibotanon ni mahilayon."},{"verse":36,"text":"Ug nahitabo nga si Adan, samtang gitental sa yawa—kay, tan-awa, ang yawa nag-una ni Adan, kay siya mirebelde batok kanako, nag-ingon, Ihatag kanako ang imong dungog, nga mao ang akong gahom; ug usab ang ikatulo nga bahin sa mga panon sa langit iyang gipabiya gikan kanako tungod sa ilang kabubut-on;"},{"verse":37,"text":"Ug gipapahawa sila gikan sa langit, ug sa ingon nahimo ang yawa ug ang iyang mga anghel;"},{"verse":38,"text":"Ug, tan-awa, adunay dapit nga giandam alang kanila gikan sa sinugdanan, diin kana nga dapit mao ang impyerno."},{"verse":39,"text":"Ug kinahanglan nga ang yawa motental sa katawhan, o sila dili mahimong tinugyanan alang sa ilang mga kaugalingon; kay kon sila dili makatilaw og kapaitan sila dili makahibalo sa katam-is—"},{"verse":40,"text":"Mao nga, nahitabo nga ang yawa mitental kang Adan, ug siya miambit sa bunga nga gidili ug nakalapas sa sugo, diin siya nahimo nga ulipon sa kabubut-on sa yawa, tungod kay siya nagpatental."},{"verse":41,"text":"Mao nga, ako, ang Ginoong Dios, misugo nga siya kinahanglan nga hinginlan gikan sa Tanaman sa Eden, gikan sa akong atubangan, tungod sa iyang kalapasan, nga namatay sa espirituwal nga paagi, nga mao ang unang kamatayon, nga kanang sama nga kamatayon nga mao ang kataposan nga kamatayon, nga mao ang espirituhanon, nga ipahamtang sa daotan sa panahon nga ako mosulti: Biya, kamong mga tinunglo."},{"verse":42,"text":"Apan, tan-awa, sultihan ko kamo nga ako, ang Ginoong Dios, mihatag kang Adan ug ngadto sa iyang binhi, nga sila dili mamatay sa temporal nga kamatayon, hangtod nga ako, ang Ginoong Dios, mopadala sa mga anghel aron sa pagpahayag ngadto kanila sa paghinulsol ug katubsanan, pinaagi sa pagtuo sa ngalan sa akong Bugtong Anak."},{"verse":43,"text":"Ug sa ingon niana ako, ang Ginoong Dios, nagtudlo ngadto sa tawo sa mga adlaw sa iyang pagsulay—nga pinaagi sa iyang kinaiyanhon nga kamatayon siya mabanhaw ngadto sa pagka-imortal ngadto sa kinabuhing dayon, gani kutob sa motuo;"},{"verse":44,"text":"Ug sila nga dili motuo padulong sa walay kataposan nga panghimaraot; kay sila dili matubos gikan sa ilang espirituwal nga pagkapukan, tungod kay sila wala maghinulsol;"},{"verse":45,"text":"Kay sila nahigugma sa kangitngit kay sa kahayag, ug ang ilang mga binuhatan daotan, ug sila nakadawat sa ilang mga suhol gikan niadtong kinsa ilang gipili nga sundon."},{"verse":46,"text":"Apan tan-awa, sultihan ko kamo, nga ang gagmayng mga bata natubos gikan sa sinugdanan sa kalibotan pinaagi sa akong Bugtong Anak;"},{"verse":47,"text":"Mao nga, sila dili makasala, kay ang gahom wala ihatag ngadto ni Satanas sa pagtental sa gagmayng mga bata, hangtod nga sila magsugod nga mahimong may tulubagon sa akong atubangan;"},{"verse":48,"text":"Kay gihatag ngadto kanila bisan sa akong pagbuot, sumala sa akong kaugalingon nga kahimuot, nga ang mahinungdanong mga butang gikinahanglan gikan sa ilang mga amahan."},{"verse":49,"text":"Ug, usab, sultihan ko kamo, nga kinsa kadtong adunay kahibalo, wala ba ako magsugo sa paghinulsol?"},{"verse":50,"text":"Ug siya nga dili makasabot, nagpabilin ngari kanako ang pagbuhat sumala sa nahisulat. Ug karon dili na ako mopahayag nganha kaninyo niini nga panahon. Amen."}]},{"chapter":30,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko ikaw, David, nga ikaw nahadlok sa tawo ug wala mosalig kanako alang sa kalig-on nga imong gitinguha."},{"verse":2,"text":"Apan ang imong hunahuna anaa sa mga butang sa kalibotan labaw sa mga butang nga anaa kanako, ang imong Magbubuhat, ug sa pagpangalagad diin ikaw gitawag; ug ikaw wala maminaw sa akong Espiritu, ug niadtong gipahimutang labaw kanimo, apan nakabig niadtong kinsa wala nako sugoa."},{"verse":3,"text":"Mao nga, ikaw magpabilin nga mangutana alang sa imong kaugalingon gikan kanako, ug mamalandong sa mga butang nga imong nadawat."},{"verse":4,"text":"Ug ang imong pinuy-anan anha sa balay sa imong amahan, hangtod ako mohatag kanimo og dugang pa nga mga sugo. Ug ikaw moatiman sa pagpangalagad sa simbahan, ug sa kalibotan, ug sa palibot nga mga rehiyon. Amen."},{"verse":5,"text":"Tan-awa, sultihan ko ikaw, Peter, nga ikaw mobiyahe kauban sa imong igsoon nga si Oliver; kay ang panahon miabot na nga angay na ngari kanako nga ikaw moabli sa imong ba-ba sa pagpahayag sa akong ebanghelyo; busa, ayaw kahadlok, apan paminawa ang mga pulong ug tambag sa imong igsoon, nga iyang ihatag kanimo."},{"verse":6,"text":"Ug ikaw mag-antos sa iyang tanang kasakitan, kanunay nga itumong ang imong kasingkasing ngari kanako pinaagi sa pag-ampo ug sa pagtuo, alang kaniya ug sa imong kaluwasan; kay gihatag nako kaniya ang gahom sa pagtukod sa akong simbahan taliwala sa mga Lamanita;"},{"verse":7,"text":"Ug walay usa nga akong gitudlo nga mahimo nga iyang magtatambag labaw kaniya sa simbahan, mahitungod sa mga butang sa simbahan, gawas sa iyang igsoon, si Joseph Smith, Jun."},{"verse":8,"text":"Mao nga, paminawa kining mga butanga ug pagmakugihon sa pagtuman sa akong mga sugo, ug ikaw panalanginan og kinabuhing dayon. Amen."},{"verse":9,"text":"Tan-awa, sultihan ko ikaw, akong sulugoon nga John, nga mosugod ikaw gikan niini nga panahon sa pagpahayag sa akong ebanghelyo, uban sa tingog sa trumpeta."},{"verse":10,"text":"Ug ang imong paghago anha sa imong igsoon nga si Philip Burroughs, ug sa palibot niana nga rehiyon, oo, bisan asa ikaw nga madunggan, hangtod nga ako momando kanimo sa paglakaw gikan dinha."},{"verse":11,"text":"Ug ang imong tibuok nga kahago anaa sa Zion, uban sa imong tibuok nga kalag, gikan karon; oo, ikaw gayod mobuka sa imong ba-ba alang kanako, nga walay kahadlok kon unsay buhaton sa tawo, kay ako mag-uban kanimo. Amen."}]},{"chapter":31,"verses":[{"verse":1,"text":"Thomas, akong anak, bulahan ka tungod sa imong pagtuo sa akong buhat."},{"verse":2,"text":"Tan-awa, daghan ka og naagian nga pag-antos tungod sa imong pamilya; bisan pa niana, panalanginan ka nako og ang imong pamilya, oo, ang imong gagmayng anak; ug moabot ang adlaw nga motuo ug masayod sila sa kamatuoran ug mahiusa uban kanimo sa akong simbahan."},{"verse":3,"text":"Ibayaw ang imong kasingkasing ug pagmaya, kay ang takna sa imong misyon miabot na; ug ang imong dila makasulti, ug mopahayag ka sa makalipay nga mga balita sa dako nga kamaya niini nga kaliwatan."},{"verse":4,"text":"Imong ipahayag ang mga butang nga gipadayag ngadto sa akong sulugoon, nga si Joseph Smith, Jun. Magsugod ka sa pagsangyaw gikan karon, oo sa pag-ani sa umahan nga puti na ug andam nang sunogon."},{"verse":5,"text":"Busa, igalab ang imong sanggot sa tibuok nimo nga kalag, ug ang imong mga sala mapasaylo, ug magpas-an ka og mga binugkos sa imong likod, kay ang mamumuo angayan sa iyang suhol. Mao nga, ang imong pamilya mabuhi."},{"verse":6,"text":"Tan-awa, sa pagkatinuod sultihan ko ikaw, biyai sila sa mubo lamang nga panahon, ug ipahayag ang akong pulong, ug mag-andam ako og dapit alang kanila."},{"verse":7,"text":"Oo, akong ablihan ang mga kasingkasing sa katawhan, ug sila modawat kanimo. Ug magtukod ako og simbahan pinaagi sa imong kamot;"},{"verse":8,"text":"Ug ikaw molig-on kanila ug moandam kanila alang sa panahon nga sila pagapundokon."},{"verse":9,"text":"Pagmapailobon sa mga kasakit, ayaw pagbiaybiay batok niadtong nagbiaybiay. Dumalaha ang imong balay pinaagi sa kaaghop, ug pagmalig-on."},{"verse":10,"text":"Tan-awa, sultihan ka nako nga mamahimo ka nga mananambal sa simbahan, apan dili sa kalibotan, kay dili sila modawat kanimo."},{"verse":11,"text":"Padayon sa pag-adto bisan asa nga akong gusto, ug ipadayag kini kanimo pinaagi sa Maghuhupay kon unsa ang imong buhaton ug kon asa ka moadto."},{"verse":12,"text":"Pag-ampo sa kanunay, tingali unya og madala ka sa tentasyon ug mawala ang imong ganti."},{"verse":13,"text":"Pagmatinud-anon hangtod sa kataposan, ug tan-awa, ako magauban kanimo. Kini nga mga pulong dili gikan sa tawo ni gikan sa mga tawo, apan gikan kanako, gani si Jesukristo, nga imong Manunubos, pinaagi sa kabubut-on sa Amahan. Amen."}]},{"chapter":32,"verses":[{"verse":1,"text":"Ug karon, mahitungod sa akong sulugoon nga si Parley P. Pratt, tan-awa, sultihan ko siya nga sama nga ako buhi mao usab ang akong kabubut-on nga siya mopahayag sa akong ebanghelyo ug magkat-on mahitungod kanako, ug magmaaghop ug magpaubos sa kasingkasing."},{"verse":2,"text":"Ug kana ang akong ipabuhat kaniya nga siya molakaw uban sa akong mga sulugoon, si Oliver Cowdery ug Peter Whitmer, Jun., ngadto sa kamingawan kauban sa mga Lamanita."},{"verse":3,"text":"Ug si Ziba Peterson mouban usab kanila; ug ako mismo mouban kanila ug maanaa sa ilang taliwala; ug ako ang ilang manlalaban ngadto sa Amahan, ug walay makabuntog batok kanila."},{"verse":4,"text":"Ug patalinghogan nila kana nga nahisulat, ug dili mangangkon og laing pagpadayag; ug mag-ampo sila kanunay nga ikapadayag ko kini aron ilang masabtan."},{"verse":5,"text":"Ug patalinghogan nila kini nga mga pulong ug dili magbugalbugal, ug ako mopanalangin kanila. Amen."}]},{"chapter":33,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko kamo, akong mga sulugoong Ezra ug Northrop, ablihi ang inyong mga dalunggan ug patalinghogi ang tingog sa Ginoo nga inyong Dios, kansang pulong buhi ug makagagahom, mas hait pa kay sa duhay suwab nga espada, ngadto sa pagkabulagbulag sa lain-laing bahin sa mga lutahan ug uyok sa bukog, sa kalag ug espiritu; ug tigpasabot sa mga hunahuna ug mga tinguha sa kasingkasing."},{"verse":2,"text":"Kay sa pagkatinuod, sa pagkatinuod, sultihan ko kamo nga kamo gitawag aron ipalanog ang inyong mga tingog sama sa tingog sa trumpeta, sa pagpahayag sa akong ebanghelyo ngadto sa hiwi ug masinupakon nga kaliwatan."},{"verse":3,"text":"Kay tan-awa, puti na ang umahan ug andam na nga anihon; ug kini ang ikanapulo og usa nga takna, ug ang kataposang higayon nga ako motawag og mga mamumuo sa akong ubasan."},{"verse":4,"text":"Ug ang akong ubasan nahimong dili maayo sa tanang bahin; ug walay nahibilin nga nagbuhat og maayo gawas sa pipila lamang; ug nasayop sila sa daghang higayon tungod sa mga panapi sa mga kaparian, ang tanan adunay daotang mga hunahuna."},{"verse":5,"text":"Ug sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga kini nga simbahan akong gitukod ug gitawag gikan sa kamingawan."},{"verse":6,"text":"Ug bisan pa niana akong pundokon ang akong mga pinili gikan sa upat ka suok sa yuta, gani kutob sa motuo kanako, ug mopatalinghog sa akong tingog."},{"verse":7,"text":"Oo, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga puti na ang umahan ug andam na nga anihon; mao nga, igalab ang inyong mga sanggot, ug mag-ani sa tibuok ninyong gahom, hunahuna ug kusog."},{"verse":8,"text":"Bukha ang inyong mga ba-ba ug kini mapuno, ug kamo mahisama kang Nephi sa karaan, kinsa mipanaw gikan sa Jerusalem ngadto sa kamingawan."},{"verse":9,"text":"Oo, bukha ang inyong mga ba-ba ug ayaw pagpanagana, ug kamo magpas-an og mga binugkos sa inyong mga likod, kay tan-awa, ubanan ko kamo."},{"verse":10,"text":"Oo, bukha ang inyong mga ba-ba ug kini mapuno, nga mag-ingon: Paghinulsol, paghinulsol, ug andama ninyo ang agianan sa Ginoo, ug himoa nga tul-id ang iyang mga agianan; kay ang gingharian sa langit haduol na;"},{"verse":11,"text":"Oo, paghinulsol ug pagpabunyag, matag usa kaninyo, alang sa kapasayloan sa inyong mga sala; oo, pagpabunyag gani sa tubig, ug unya moabot ang pagbunyag sa kalayo ug sa Espiritu Santo."},{"verse":12,"text":"Tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, kini ang akong ebanghelyo; ug hinumdomi nga sila kinahanglan adunay pagtuo kanako o dili gayod sila maluwas sa laing paagi;"},{"verse":13,"text":"Ug sa ibabaw niini nga bato akong itukod ang akong simbahan; oo, sa ibabaw niini nga bato kamo gitukod, ug kon magpadayon kamo, ang mga ganghaan sa impyerno dili makabuntog batok kaninyo."},{"verse":14,"text":"Ug kinahanglan hinumdoman ninyo ang mga artikulo ug mga pakigsaad sa simbahan aron sundon kini."},{"verse":15,"text":"Ug kinsa kadtong adunay pagtuo inyong kompirmahan sa akong simbahan, pinaagi sa pagpandong sa mga kamot, ug akong itugyan ang gasa sa Espiritu Santo diha kanila."},{"verse":16,"text":"Ug ang Basahon ni Mormon ug ang balaang mga kasulatan akong gihatag alang sa inyong instruksiyon; ug ang gahom sa akong Espiritu mopalihok sa tanan nga butang."},{"verse":17,"text":"Mao nga, pagmatinud-anon, pag-ampo kanunay, nga ang inyong mga lampara maandam ug magsiga, ug may dala kamo nga lana, nga kamo andam sa pag-anhi sa Pamanhonon—"},{"verse":18,"text":"Kay tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga ako moabot sa kalit lang. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":34,"verses":[{"verse":1,"text":"Orson akong anak, patalinghogi ug paminawa ako nga Ginoong Dios, ug tan-awa unsay akong isulti kanimo, gani si Jesukristo nga imong Manunubos;"},{"verse":2,"text":"Ang kahayag ug ang kinabuhi sa kalibotan, ang kahayag nga nagdan-ag sa kangitngit ug ang kangitngit wala makasabot niini;"},{"verse":3,"text":"Kinsa nahigugma kaayo sa kalibotan nga iyang gihatag ang iyang kaugalingong kinabuhi, nga kutob sa motuo mahimo nga mga anak sa Dios. Mao nga ikaw akong anak;"},{"verse":4,"text":"Ug bulahan ka tungod kay ikaw mituo;"},{"verse":5,"text":"Ug mas bulahan ka tungod kay ikaw akong gitawag sa pagsangyaw sa akong ebanghelyo—"},{"verse":6,"text":"Sa pagpalanog sa imong tingog sama sa tingog sa trumpeta, nga hataas ug lanog, ug mosangyaw og paghinulsol ngadto sa hiwi ug masinupakon nga kaliwatan, mag-andam sa agianan sa Ginoo alang sa iyang ikaduhang pag-anhi."},{"verse":7,"text":"Kay tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, ang panahon nagkaduol na nga ako moabot sa usa ka panganod uban sa gahom ug dako nga himaya."},{"verse":8,"text":"Ug mahimo kining mahinungdanon nga adlaw sa panahon sa akong pag-abot, kay ang tanang kanasoran mokurog."},{"verse":9,"text":"Apan sa dili pa moabot kanang mahinungdanon nga adlaw, ang adlaw mongitngit, ug ang bulan mahimong dugo; ug ang mga bitoon magdumili sa pagpakita sa ilang kahayag, ug ang uban mangahulog, ug dagko nga kalaglagan ang nagpaabot sa daotan."},{"verse":10,"text":"Mao nga, ipalanog ang imong tingog ug ayaw pagpanagana, kay ang Ginoong Dios ang namulong; busa panagna, ug kini ihatag pinaagi sa gahom sa Espiritu Santo."},{"verse":11,"text":"Ug kon ikaw magmatinud-anon, tan-awa, ako magauban kanimo hangtod sa akong pag-abot—"},{"verse":12,"text":"Ug sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, moabot ako sa kalit lang. Ako ang imong Ginoo ug imong Manunubos. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":35,"verses":[{"verse":1,"text":"Paminaw sa tingog sa Ginoo nga inyong Dios, gani ang Alpha ug ang Omega, ang sinugdanan ug ang kataposan, kansang katuyoan nagsubay sa usa ka mahangtorong agianan nga walay pagkausab, ang karon sama ra sa kagahapon, ug sa kahangtoran."},{"verse":2,"text":"Ako si Jesukristo, ang Anak sa Dios, kinsa gilansang sa krus alang sa mga sala sa kalibotan, gani kutob sa motuo sa akong ngalan, nga sila mamahimong mga anak nga lalaki sa Dios, gani mahiusa ngari kanako sama nga Ako nahiusa sa Amahan, ingon nga ang Amahan nahiusa ngari kanako, nga kita mahiusa."},{"verse":3,"text":"Tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko ang akong sulugoon nga si Sidney, ako nagtan-aw kanimo ug sa imong mga buhat. Nakadungog ko sa imong mga pag-ampo, ug nag-andam kanimo alang sa mas mahinungdanon nga buhat."},{"verse":4,"text":"Bulahan ka, kay ikaw mobuhat og mahinungdanong mga butang. Tan-awa ikaw gipadala, gani sama ni Juan, aron moandam sa agianan sa dili pa ako, ug sa dili pa si Elijah moabot, ug wala ikaw mahibalo niana."},{"verse":5,"text":"Ikaw nagbunyag pinaagi sa tubig ngadto sa paghinulsol, apan sila wala makadawat sa Espiritu Santo;"},{"verse":6,"text":"Apan karon mohatag ko kanimo og sugo nga ikaw mobunyag pinaagi sa tubig, ug madawat nila ang Espiritu Santo pinaagi sa pagpandong sa mga kamot, gani sama sa mga apostol sa karaan."},{"verse":7,"text":"Ug mahitabo nga adunay mahinungdanon nga buhat dinhi sa yuta, gani taliwala sa mga Hentil, kay ang ilang kabuang ug ang ilang mga pagkasalawayon ipakita sa mga mata sa tanang katawhan."},{"verse":8,"text":"Kay ako ang Dios, ug ang akong bukton wala mapamubo; ug magpakita ako og mga milagro, mga timailhan, ug mga kahibulongan, ngadto sa tanan nga motuo sa akong ngalan."},{"verse":9,"text":"Ug kadtong mangayo niini sa akong ngalan pinaagi sa pagtuo, makapapahawa sila og mga yawa; makaayo sila sa masakiton; mahimo nila ang mga buta nga makakita, ug ang bungol makadungog, ug ang amang makasulti, ug ang bakol makalakaw."},{"verse":10,"text":"Ug ang panahon sa dili madugay moabot nga ang mahinungdanong mga butang ipakita ngadto sa katawhan;"},{"verse":11,"text":"Apan kon walay pagtuo walay bisan unsang butang nga makita gawas sa mga kalaglagan sa Babilonia, ang maong nasod nga nakapainom sa mga nasod sa bino sa kapungot sa iyang pakighilawas."},{"verse":12,"text":"Ug walay bisan usa nga nagbuhat og matarong gawas kanila nga andam sa pagdawat sa kahingpitan sa akong ebanghelyo, nga akong gipadala ngadto niini nga henerasyon."},{"verse":13,"text":"Mao nga, ako nagtawag sa huyang nga mga butang sa kalibotan, kanila nga mga walay alamag ug dinaog-daog, sa pag-ayag sa kanasoran pinaagi sa gahom sa akong Espiritu;"},{"verse":14,"text":"Ug ang ilang bukton mao ang akong bukton, ug ako ang ilang taming ug ang ilang panagang sa bukton; ug ako mobakos sa ilang mga bat-ang, ug sila makig-away nga maisogon alang kanako; ug ang ilang mga kaaway pagatumban sa ilang mga tiil; ug akong itugot nga mahulog ang espada alang sa ilang kaayohan, ug pinaagi sa kalayo sa akong kasuko panalipdan ko sila."},{"verse":15,"text":"Ug ang kabos ug ang maaghop masangyawan sila sa ebanghelyo, ug magpaabot sila sa panahon sa akong pag-anhi, kay kini haduol na—"},{"verse":16,"text":"Ug makat-onan nila ang sambingay sa kahoy nga igos, kay gani karon hapit na moabot ang ting-init."},{"verse":17,"text":"Ug napadala na nako ang kahingpitan sa akong ebanghelyo pinaagi sa kamot sa akong sulugoon nga si Joseph; ug diha sa kahuyang gipanalanginan ko siya;"},{"verse":18,"text":"Ug gihatag ko na kaniya ang mga yawe sa misteryo niadtong mga butang nga naselyohan na, bisan ang mga butang sukad pa sa katukoran sa kalibotan, ug ang mga butang nga moabot sukad karon nga panahon hangtod sa panahon sa akong pag-anhi, kon siya magpabilin kanako, ug kon dili, adunay lain nga akong ibutang sa iyang dapit."},{"verse":19,"text":"Mao nga, bantayi siya nga ang iyang pagtuo dili mawala, ug igahatag kini sa Maghuhupay, ang Espiritu Santo, nga nasayod sa tanang butang."},{"verse":20,"text":"Ug hatagan ko ikaw og usa ka sugo—nga ikaw mosulat alang kaniya; ug ang mga kasulatan ihatag, sama nga kini anaa sa akong kaugalingong dughan, ngadto sa kaluwasan sa akong kaugalingong pinili;"},{"verse":21,"text":"Kay maminaw sila sa akong tingog, ug makakita kanako, ug dili makatulog, ug makalahutay sila sa adlaw sa akong pag-anhi; kay himoon sila nga putli, sama nga ako putli."},{"verse":22,"text":"Ug karon, sultihan ko ikaw, magpabilin ka uban kaniya, ug siya mopanaw uban kanimo; ayaw siya og isalikway, ug sa pagkatinuod kining mga butanga matuman."},{"verse":23,"text":"Ug sa panahon nga dili kamo magsulat, tan-awa, hatagan siya og katakos sa pagpanagna; ug imong isangyaw ang akong ebanghelyo ug gamiton ang mga pulong sa balaang mga propeta aron sa pagpamatuod sa iyang mga pulong, kay kini ihatag kaniya."},{"verse":24,"text":"Tumana ang tanang sugo ug mga pakigsaad nga kinahanglan nimong sundon; ug akong himoon nga ang kalangitan mouyog alang sa imong kaayohan, ug si Satanas mokurog ug ang Zion magmaya sa ibabaw sa kabungtoran ug mouswag;"},{"verse":25,"text":"Ug ang Israel pagaluwason sa akong gitakda nga panahon; ug pinaagi sa mga yawe nga akong gihatag sila pagagiyahan, ug dili na gayod malibog pa."},{"verse":26,"text":"Ibayaw ang inyong mga kasingkasing ug pagmaya, ang inyong katubsanan nagsingabot na."},{"verse":27,"text":"Ayaw kahadlok, gamay nga pundok, inyo ang gingharian hangtod sa akong pag-abot. Tan-awa, ako moabot sa kalit lang. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":36,"verses":[{"verse":1,"text":"Sa ingon niana miingon ang Ginoong Dios, ang Usa nga Gamhanan sa Israel: Tan-awa, sultihan ko ikaw, akong sulugoong Edward, nga bulahan ka, ug ang imong mga sala gipasaylo, ug ikaw gitawag sa pagsangyaw sa akong ebanghelyo sama sa tingog sa trumpeta;"},{"verse":2,"text":"Ug akong ipandong ang akong kamot diha kanimo pinaagi sa kamot sa akong sulugoon nga si Sidney Rigdon, ug ikaw makadawat sa akong Espiritu, ang Espiritu Santo, gani ang Maghuhupay, nga magtudlo kanimo sa mga butang nga maghatag og kalinaw sa gingharian;"},{"verse":3,"text":"Ug ipahayag nimo kini sa makusog nga tingog, nga mag-ingon: Hosanna, bulahan ang ngalan sa labing halangdon nga Dios."},{"verse":4,"text":"Ug karon kini nga katungdanan ug sugo akong ihatag kanimo mahitungod sa tanang tawo—"},{"verse":5,"text":"Nga kutob sa moduol ngadto sa akong mga sulugoon nga si Sidney Rigdon ug ni Joseph Smith, Jun. nga modawat niini nga katungdanan ug sugo, ordinahan ug ipadala aron magsangyaw sa walay kataposang ebanghelyo ngadto sa mga nasod—"},{"verse":6,"text":"Mag-awhag sa paghinulsol, nga mag-ingon: Luwasa ang inyong kaugalingon gikan niining hiwi nga henerasyon, ug biya gikan sa kalayo, nga masilag bisan sa mga sapot nga nabulingan sa unod."},{"verse":7,"text":"Ug kini nga sugo ihatag ngadto sa mga elder sa akong simbahan, nga matag tawo nga maghupot niini nga adunay tim-os nga katuyoan sa kasingkasing mahimo nga iorden ug ipadala, gani sama sa akong gipamulong."},{"verse":8,"text":"Ako mao si Jesukristo, ang Anak sa Dios; mao nga, pagbakos sa inyong mga bat-ang ug ako sa kalit moabot sa akong templo. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":37,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko kamo nga dili mahinungdanon alang kanako nga maghubad pa kamo hangtod nga kamo moadto sa Ohio, ug tungod kini sa kaaway ug sa inyong kaayohan."},{"verse":2,"text":"Ug usab, sultihan ko kamo nga dili kamo moadto hangtod nga masangyaw ninyo ang akong ebanghelyo niana nga mga dapit, ug mapalig-on ang simbahan bisan asa kini mahimutang, ug ilabi na sa Colesville; kay, tan-awa, nag-ampo sila ngari kanako sa hilabihan nga pagtuo."},{"verse":3,"text":"Ug usab, adunay sugo nga akong ihatag sa simbahan, nga mahinungdanon alang kanako nga sila magpundok nga maghiusa didto sa Ohio, alang sa panahon nga ang akong sulugoon nga si Oliver Cowdery mobalik ngadto kanila."},{"verse":4,"text":"Tan-awa, ania ang kaalam, ug tugoti ang matag tawo nga mopili alang sa iyang kaugalingon hangtod sa akong pag-abot. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":38,"verses":[{"verse":1,"text":"Sa ingon niana misulti ang Ginoo nga inyong Dios, gani si Jesukristo, ang Halangdon nga Ako, ang Alpha ug ang Omega, ang sinugdanan ug ang kataposan, siya nga nagtan-aw sa kahalapad sa kahangtoran, ug sa tanang panon sa serapin sa langit, sa wala pa mamugna ang kalibotan;"},{"verse":2,"text":"Siya nga nahibalo sa tanan nga butang, kay ang tanan nga butang anaa sa atubangan sa akong mga mata;"},{"verse":3,"text":"Ako mao gihapon ang namulong, ug ang kalibotan namugna, ug ang tanan nga butang nalalang pinaagi kanako."},{"verse":4,"text":"Ako mao gihapon ang misakwat sa Zion ni Enoch ngari sa akong dughan; ug sa pagkatinuod, ako moingon, kutob sa nagatuo sa akong ngalan, kay ako si Kristo, ug sa akong kaugalingong ngalan, pinaagi sa dugo nga akong gipaagas, nangamuyo ako sa atubangan sa Amahan alang kanila."},{"verse":5,"text":"Apan tan-awa, ang nahibilin sa mga daotan akong gigaid sa mga kadena sa kangitngit hangtod sa mahinungdanon nga adlaw sa paghukom, nga moabot sa kataposan sa kalibotan;"},{"verse":6,"text":"Ug sa mao gihapon nga paagi akong gipagaid ang mga daotan, nga wala maminaw sa akong tingog apan nagpatig-a sa ilang mga kasingkasing, ug ang kaalaotan, kaalaotan, kaalaotan, maoy ilang padulngan."},{"verse":7,"text":"Apan tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo nga ang akong mga mata nagtan-aw kaninyo. Anaa ako sa inyong taliwala ug dili kamo makakita kanako;"},{"verse":8,"text":"Apan ang adlaw hapit na moabot nga makakita kamo kanako, ug masayod nga Ako anaa; kay ang tabil sa kangitngit sa dili madugay magisi, ug siya nga dili putli dili makalahutay nianang adlawa."},{"verse":9,"text":"Mao nga, baksi ang inyong mga bat-ang ug pangandam. Tan-awa, inyo ang gingharian, ug ang kaaway dili makabuntog."},{"verse":10,"text":"Sa pagkatinuod sultihan ko kamo, kamo mga limpyo, apan dili tanan; ug wala nay lain nga akong gikahimut-an;"},{"verse":11,"text":"Kay ang tanan nga unod makasasala sa akong atubangan; ug ang mga gahom sa kangitngit nagpatigbabaw sa yuta, taliwala sa mga anak sa katawhan, sa atubangan sa tanang panon sa langit—"},{"verse":12,"text":"Diin maoy hinungdan nga naghari ang kahilom, ug ang tanang kahangtoran gisakit, ug ang mga anghel nagpaabot sa mahinungdanon nga sugo sa pag-ani sa yuta, sa pagpundok sa mga sagbot aron kini pagasunogon; ug, tan-awa, ang kaaway naghiusa."},{"verse":13,"text":"Ug karon ako mopakita kaninyo og misteryo, butang nga anaa sa tinago nga mga lawak, sa pagpahitabo gani sa inyong kalaglagan sa paglabay sa panahon, ug wala kamo masayod niini;"},{"verse":14,"text":"Apan karon sultihan ko kamo, ug bulahan kamo, dili tungod sa inyong pagkadaotan, ni sa inyong mga kasingkasing nga walay pagtuo; kay sa pagkatinuod ang uban kaninyo nakasala sa akong atubangan, apan magmaluluy-on ako sa inyong kahuyang."},{"verse":15,"text":"Busa, pagmalig-on kamo gikan karon; ayaw kahadlok, kay inyo ang gingharian."},{"verse":16,"text":"Ug alang sa inyong kaluwasan hatagan ko kamo og sugo, kay akong nadungog ang inyong mga pag-ampo, ug ang mga kabos nagbagulbol sa akong atubangan, ug ang mga adunahan ako ang naglalang, ug ako ang tag-iya sa tanang unod, ug Ako walay pinalabi sa mga tawo."},{"verse":17,"text":"Ug akong gihimo nga buhong ang yuta, ug tan-awa kini ang akong tumbanan, mao nga, sa makausa pa ako mobarog diha niini."},{"verse":18,"text":"Ug ako motunol ug mopaubos sa paghatag kaninyo og mas daghang katigayonan, gani usa ka yutang saad, yuta nga tugob sa gatas ug dugos, nga diha niana walay tunglo nga ipahamtang kon ang Ginoo moabot;"},{"verse":19,"text":"Ug ihatag ko kini kaninyo aron mahimong yuta nga inyong panulundon, kon kamo mangita niini sa tibuok ninyong kasingkasing."},{"verse":20,"text":"Ug mao kini ang akong pakigsaad diha kaninyo, oo maangkon ninyo kini aron mahimong yuta nga inyong panulundon, ug aron mahimong panulundon alang sa inyong mga anak sa kahangtoran, samtang ang kalibotan magbarog, ug maangkon ninyo kini pag-usab ngadto sa kahangtoran, nga dili na gayod mahanaw."},{"verse":21,"text":"Apan, sa pagkatinuod sultihan ko kamo nga sa umaabot nga panahon kamo wala nay hari ni magmamando, kay ako ang mahimo ninyong hari ug magbantay kaninyo."},{"verse":22,"text":"Mao nga, paminaw sa akong tingog ug sunod kanako, ug kamo mahimong gawasnon nga katawhan, ug kamo walay mga balaod gawas sa akong mga balaod kon ako moabot, kay ako ang inyong magbabalaod, ug unsa ang makapugong sa akong kamot?"},{"verse":23,"text":"Apan, sa pagkatinuod sultihan ko kamo, pagtinudloay kamo sa usag usa sumala sa katungdanan nga akong gihatag kaninyo;"},{"verse":24,"text":"Ug tugoti ang matag tawo nga motamod sa iyang igsoon sama sa iyang kaugalingon, ug mag-ugmad og hiyas ug pagkabalaanon sa akong atubangan."},{"verse":25,"text":"Ug usab sultihan ko kamo, tugoti ang matag tawo nga motamod sa iyang igsoon sama sa iyang kaugalingon."},{"verse":26,"text":"Kay unsa nga matang sa tawo taliwala kaninyo nga adunay napulog duha ka anak, ug walay pinalabi kanila, ug nangalagad sila kaniya nga masinugtanon, ug iyang gisultihan ang usa: Pagsul-ob og mga kupo ug lingkod dinhi; ug ngadto sa ikaduha: Pagsul-ob og nuog ug lingkod didto—ug motan-aw sa iyang mga anak ug moingon nga makiangayon ako?"},{"verse":27,"text":"Tan-awa, gihatag ko kini kaninyo isip usa ka sambingay, ug gani sama kini kanako. Sultihan ko kamo, paghiusa; ug kon dili kamo maghiusa dili kamo akoa."},{"verse":28,"text":"Ug usab, sultihan ko kamo nga ang kaaway nga anaa sa tinago nga mga lawak nagtinguha sa inyong kinabuhi."},{"verse":29,"text":"Kamo makadungog og mga gubat sa layo nga mga nasod, ug moingon kamo nga sa dili madugay adunay moabot nga dagko nga mga gubat sa layo nga mga nasod, apan wala kamo masayod sa mga kasingkasing sa mga tawo sa inyong kaugalingong yuta."},{"verse":30,"text":"Gisultihan ko kamo niining mga butanga tungod sa inyong mga pag-ampo; mao nga, pagbahandi og kaalam diha sa inyong mga dughan, tingali unya og ang pagkadaotan sa mga tawo mopadayag niini nga mga butang nganha kaninyo pinaagi sa ilang pagkadaotan, sa paagi nga mamulong diha sa inyong mga dunggan pinaagi sa tingog nga kusog pa kay sa nianang makapakurog sa yuta; apan kon andam kamo, dili kamo mahadlok."},{"verse":31,"text":"Ug nga kamo unta makalingkawas sa gahom sa kaaway, ug magpundok ngari kanako isip matarong nga katawhan, nga walay mansa ug walay sala—"},{"verse":32,"text":"Mao nga, tungod niini nga hinungdan gihatagan ko kamo og sugo nga moadto kamo sa Ohio; ug didto akong ihatag kaninyo ang akong balaod; ug didto pagatugahan kamo og gahom gikan sa kahitas-an;"},{"verse":33,"text":"Ug gikan didto, kon si kinsa man ang akong tugotan moadto sa tanang kanasoran, ug sultihan sila kon unsay ilang buhaton; kay ako adunay dakong buhat nga giandam, kay ang Israel pagaluwason, ug giyahan ko sila bisan asa nga akong gusto, ug walay gahom nga makapugong sa akong kamot."},{"verse":34,"text":"Ug karon, mohatag ako og sugo sa simbahan niini nga mga dapit, nga pipila sa mga tawo uban kanila itudlo ngadto sa katungdanan, ug sila itudlo sa katungdanan pinaagi sa tingog sa simbahan;"},{"verse":35,"text":"Ug moatiman sila sa mga kabos ug sa timawa, ug mangalagad alang sa ilang kahupayan aron dili sila mag-antos; ug ipadala sila ngadto sa dapit nga akong gisugo kanila;"},{"verse":36,"text":"Ug mao kini ang ilang buhat, ang pagdumala sa mga kalihokan sa kabtangan niini nga simbahan."},{"verse":37,"text":"Ug sila nga adunay mga umahan nga dili mabaligya, ipabilin o paabangan kana sumala sa makaayo kanila."},{"verse":38,"text":"Tan-awa nga ang tanang butang matipigan; ug kon ang mga tawo matugahan og gahom gikan sa kahitas-an ug mapadala, kining tanan nga mga butang pagapundokon ngadto sa dughan sa simbahan."},{"verse":39,"text":"Ug kon magtinguha kamo sa mga bahandi nga mao ang kabubut-on sa Amahan nga ihatag kaninyo, mahimo kamong labing adunahan sa tanan nga katawhan, kay mainyo ang mga katigayonan sa kahangtoran; ug gikinahanglan nga ang mga katigayonan sa yuta akong ihatag; apan paglikay sa garbo, tingali unya og mahisama kamo sa mga Nephita sa karaan."},{"verse":40,"text":"Ug usab, sultihan ko kamo, ako mohatag kaninyo og sugo, nga ang matag tawo, elder, pari, magtutudlo, ug usab mga sakop, moadto sa tibuok niyang gahom, pinaagi sa paghago sa ilang mga kamot; sa pag-andam ug pagtuman sa mga butang nga akong gisugo."},{"verse":41,"text":"Ug himoa nga ang inyong pagsangyaw mahimo nga tingog sa pagpasidaan, sa matag tawo ngadto sa iyang silingan, pinaagi sa kalumo ug kaaghop."},{"verse":42,"text":"Ug pagpalayo kamo gikan sa daotan. Luwasa ang inyong kaugalingon. Pagmalimpyo kamo nga mga sinaligan sa Ginoo. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":39,"verses":[{"verse":1,"text":"Patalinghog, ug paminaw sa tingog kaniya nga nagagikan sa tanang kahangtoran ngadto sa tanang kahangtoran, ang Halangdon nga Ako Mao, gani si Jesukristo—"},{"verse":2,"text":"Ang kahayag ug ang kinabuhi sa kalibotan; kahayag nga nagdan-ag sa kangitngit ug ang kangitngit wala makasabot niini;"},{"verse":3,"text":"Ang mao gihapon nga miabot sa kinatung-an sa panahon ngadto sa akong katawhan, ug ang akong katawhan wala modawat kanako;"},{"verse":4,"text":"Apan kutob sa midawat kanako, Akong gihatagan og gahom nga mahimong akong mga anak; ug bisan pa niana Ako mohatag kutob sa modawat kanako, og gahom nga mahimong akong mga anak."},{"verse":5,"text":"Ug sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, siya nga modawat sa akong ebanghelyo modawat kanako; ug siya nga wala modawat sa akong ebanghelyo wala modawat kanako."},{"verse":6,"text":"Ug mao kini ang akong ebanghelyo—paghinulsol ug bunyag pinaagi sa tubig, ug dayon moabot ang bunyag sa kalayo ug sa Espiritu Santo, gani ang Maghuhupay, nga nagpakita sa tanang butang, ug nagtudlo sa malinawong mga butang sa gingharian."},{"verse":7,"text":"Ug karon, tan-awa, sultihan ko kamo, akong sulugoong James, nagtan-aw ako sa imong mga buhat ug nakaila ako kanimo."},{"verse":8,"text":"Ug sa pagkatinuod sultihan ko ikaw, ang imong kasingkasing karon matarong sa akong atubangan niini nga panahon; ug, tan-awa, nagtugyan ako og dagkong mga panalangin diha sa imong ulo;"},{"verse":9,"text":"Bisan pa niana, ikaw nakakita og dagko nga kagul-anan, kay imo akong gisalikway sa daghang higayon tungod sa garbo ug kabalaka sa kalibotan."},{"verse":10,"text":"Apan, tan-awa, ang adlaw sa imong kaluwasan moabot, kon ikaw mopatalinghog sa akong tingog, nga nag-ingon nganha kanimo: Bangon ug pagpabunyag, ug hugasi ang imong mga sala, motawag sa akong ngalan, ug ikaw makadawat sa akong Espiritu, ug sa panalangin nga hilabihan ka mahinungdanon nga wala pa nimo mahibaloi sukad."},{"verse":11,"text":"Ug kon imo kining buhaton, giandam ko ikaw alang sa mas mahinungdanon nga buhat. Ikaw mosangyaw sa kahingpitan sa akong ebanghelyo, nga akong gipadala niining kataposang mga adlaw, ang pakigsaad nga akong gipadala aron sa pagpahibalik sa akong katawhan, nga naggikan sa balay ni Israel."},{"verse":12,"text":"Ug mahitabo nga ang gahom maanaa kanimo; ikaw makaangkon og talagsaong pagtuo, ug ako mag-uban kanimo ug mag-una sa imong atubangan."},{"verse":13,"text":"Ikaw gitawag sa paghago sa akong ubasan, ug sa pagpalig-on sa akong simbahan, ug sa pag-ugmad sa Zion, nga kini magmaya sa ibabaw sa mga bungtod ug molambo."},{"verse":14,"text":"Tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, ikaw wala tawaga sa pag-adto sa silangan nga mga nasod, apan ikaw gitawag sa pag-adto sa Ohio."},{"verse":15,"text":"Ug tungod kay ang akong katawhan magpundok didto sa Ohio, nag-andam ako og panalangin nga labaw pa kay sa nahibaloan sa mga anak sa katawhan, ug ibu-bo kini diha sa ilang mga ulo. Ug gikan diha ang mga tawo moadto sa tanang kanasoran."},{"verse":16,"text":"Tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga ang katawhan sa Ohio nagtawag kanako uban sa hilabihang pagtuo, naghunahuna nga akong pugngan ang akong kamot sa paghukom diha sa mga nasod, apan dili ako makalimod sa akong pulong."},{"verse":17,"text":"Mao nga sugdi ang buluhaton gamit ang imong gahom ug pagtawag og matinud-anong mga mamumuo ngadto sa akong ubasan, nga kini mapul-ongan sa kataposang higayon."},{"verse":18,"text":"Ug tungod kay naghinulsol sila ug modawat sa kahingpitan sa akong ebanghelyo, ug mahimong balaan, Akong pugngan ang akong kamot sa pagpahamtang og silot."},{"verse":19,"text":"Mao nga, lakaw, magsangyaw pinaagi sa kusog nga tingog, nga mag-ingon: Ang gingharian sa langit haduol na; magsinggit og: Hosanna! bulahan ang ngalan sa Labing Halangdon nga Dios."},{"verse":20,"text":"Padayon sa pagpamunyag pinaagi sa tubig, mag-andam sa dalan alang kanako alang sa takna sa akong pag-abot;"},{"verse":21,"text":"Kay ang panahon haduol na; ang adlaw o ang takna nga walay tawo nga nasayod; apan moabot gayod kini."},{"verse":22,"text":"Ug siya nga modawat niining mga butanga modawat kanako; ug pagapundokon sila ngari kanako karon ug sa kahangtoran."},{"verse":23,"text":"Ug sa gihapon, mahitabo nga kutob sa inyong mabunyagan pinaagi sa tubig, inyong pandongan sa inyong mga kamot, ug madawat nila ang gasa sa Espiritu Santo, ug maghulat sa mga timailhan sa akong pag-anhi, ug makaila kanako."},{"verse":24,"text":"Tan-awa, ako kalit lang nga moabot. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":40,"verses":[{"verse":1,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, nga ang kasingkasing sa akong sulugoon nga si James Covel matarong sa akong atubangan, kay mipakigsaad siya kanako nga mosunod siya sa akong pulong."},{"verse":2,"text":"Ug malipayon siya nga midawat sa pulong, apan diha-diha dayon gitental siya ni Satanas; ug ang kahadlok sa pagpanglutos ug ang mga kabalaka sa kalibotan mao ang hinungdan sa iyang pagsalikway sa pulong."},{"verse":3,"text":"Mao nga gilapas niya ang akong pakigsaad, ug anaa ra kanako kon unsay buhaton ngadto kaniya nga akong gilantaw nga maayo. Amen."}]},{"chapter":41,"verses":[{"verse":1,"text":"Patalinghog ug paminaw, O kamo akong katawhan, nag-ingon ang Ginoo ug inyong Dios, kamo nga gikahimut-an nako nga panalanginan sa labing mahinungdanon sa tanang panalangin, kamo nga naminaw kanako; ug kamo nga wala maminaw kanako, nga nangangkon sa akong ngalan, akong tunglohon sa labing bug-at sa tanang pagtunglo."},{"verse":2,"text":"Patalinghog, O kamong mga elder sa akong simbahan kinsa akong gitawag, tan-awa hatagan ko kamo og usa ka sugo, nga kamo magpundok aron magkauyon mahitungod sa akong pulong;"},{"verse":3,"text":"Ug pinaagi sa inyong matuohon nga pag-ampo makadawat kamo sa akong balaod, aron masayod kamo kon unsaon sa pagdumala ang akong simbahan ug sa pagbuhat sa tanang butang sa tukmang paagi sa akong atubangan."},{"verse":4,"text":"Ug Ako ang inyong magmamando kon ako moabot na; ug tan-awa, moabot ako sa kalit lang, ug makita ninyo nga ang inyong balaod pagatumanon."},{"verse":5,"text":"Siya nga nakadawat sa akong balaod ug nagbuhat niini, siya akong disipulo; ug siya nga moingon nga nakadawat siya niini ug wala magbuhat niini, dili siya akong disipulo, ug kinahanglang ipalayo gikan kaninyo;"},{"verse":6,"text":"Kay dili angay nga ang mga butang nga gipanag-iya sa mga anak sa gingharian ihatag ngadto kanila nga dili takos, o ngadto sa mga iro, o ang mga perlas aron isabwag sa atubangan sa baboy."},{"verse":7,"text":"Ug usab, angay nga ang akong sulugon nga si Joseph Smith, Jun., patukoran og balay, diin didto magpuyo ug maghubad."},{"verse":8,"text":"Ug usab, angay nga ang akong sulugoon nga si Sidney Rigdon magpuyo sumala sa iyang gilantaw nga makaayo kaniya, kutob sa panahon nga siya magtuman sa akong mga sugo."},{"verse":9,"text":"Ug usab, akong gitawag ang akong sulugoon nga si Edward Partridge; ug mohatag ako og sugo, nga kinahanglan siyang ibutang sa katungdanan pinaagi sa tingog sa simbahan, ug iorden nga obispo sa simbahan, sa pagbiya sa iyang pagpamaligya ug igahin ang iyang tanang panahon sa mga buluhaton sa simbahan;"},{"verse":10,"text":"Sa pag-atiman sa tanang butang sumala sa ihatag kaniya nga katungdanan sa akong mga balaod sa panahon nga Ako mohatag niini."},{"verse":11,"text":"Ug tungod kini kay ang iyang kasingkasing putli sa akong atubangan, kay sama siya ni Nathanael sa karaan, kinsa walay pagpanglimbong."},{"verse":12,"text":"Kini nga mga pulong gihatag nganha kaninyo, ug putli kini sa akong atubangan; mao nga, pagbantay unsaon ninyo kini sa paggamit, kay ang inyong mga kalag mao ang manubag niini sa adlaw sa paghukom. Ug ingon niana ang mahitabo. Amen."}]},{"chapter":42,"verses":[{"verse":1,"text":"Patalinghog, O kamong mga elder sa akong simbahan, kinsa naghiusa sa pagpundok sa akong ngalan, gani si Jesukristo ang Anak sa buhi nga Dios, ang Manluluwas sa kalibotan; tungod kay kamo nagatuo sa akong ngalan ug nagtuman sa akong mga sugo."},{"verse":2,"text":"Ug sa makausa pa sultihan ko kamo, patalinghog ug paminaw ug sunda ang balaod nga akong ihatag kaninyo."},{"verse":3,"text":"Kay sa pagkatinuod ako moingon, kay kamo naghiusa sa pagpundok sumala sa sugo nga akong gisugo kaninyo, ug gikauyonan kalabot niining usa ka butang, ug nangayo sa Amahan pinaagi sa akong ngalan, kamo usab makadawat."},{"verse":4,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, ihatag ko kaninyo kining una nga sugo, nga manglakaw kamo pinaagi sa akong ngalan, matag usa kaninyo, gawas lamang sa akong mga sulugoon nga sila si Joseph Smith, Jun., ug Sidney Rigdon."},{"verse":5,"text":"Ug hatagan ko sila og sugo nga molakaw sila sa mubong panahon, ug ihatag kanila pinaagi sa gahom sa Espiritu kon kanus-a sila mobalik."},{"verse":6,"text":"Ug manglakaw kamo pinaagi sa gahom sa akong Espiritu, magsangyaw sa akong ebanghelyo, sa tinagurha, pinaagi sa akong ngalan, mopalanog sa inyong mga tingog sama sa tingog sa trumpeta, magpahayag sa akong pulong nga sama sa mga anghel sa Dios."},{"verse":7,"text":"Ug manglakaw kamo nga magbunyag pinaagi sa tubig, nga mag-ingon: Paghinulsol kamo, paghinulsol kamo, kay ang gingharian sa langit haduol na."},{"verse":8,"text":"Ug gikan niini nga dapit manglakaw kamo ngadto sa mga rehiyon sa kasadpan nga bahin; ug kutob sa inyong makaplagan nga modawat kaninyo itukod ninyo kanila ang akong simbahan sa matag rehiyon—"},{"verse":9,"text":"Hangtod ang panahon moabot nga kini ipadayag nganha kaninyo gikan sa kahitas-an, diin ang siyudad sa Bag-ong Jerusalem andamon, nga kamo mapundok nga usa, nga kamo mahimo nga akong katawhan ug ako ang inyong mahimong Dios."},{"verse":10,"text":"Ug usab, sultihan ko kamo, nga ang akong sulugoon nga si Edward Partridge mobarog sa katungdanan diin siya akong gitudlo. Ug mahitabo, nga kon makahimo siya og kalapasan laing tawo ang ipuli sa iyang dapit. Ug ingon niana ang mahitabo. Amen."},{"verse":11,"text":"Usab sultihan ko kamo, nga dili ikahatag ngadto ni bisan kinsa ang pag-adto aron mosangyaw sa akong ebanghelyo o mopalambo sa akong simbahan, gawas kon maorden siya pinaagi sa tawo nga adunay awtoridad, ug nahibaloan sa simbahan nga siya adunay pagtugot ug naorden pinaagi sa mga pangulo sa simbahan."},{"verse":12,"text":"Ug usab, ang mga elder, mga pari ug mga magtutudlo niini nga simbahan kinahanglang motudlo sa mga baroganan sa akong ebanghelyo, nga anaa sa Biblia ug sa Basahon ni Mormon, diin anaa ang kahingpitan sa ebanghelyo."},{"verse":13,"text":"Ug magsunod sila sa mga pakigsaad ug sa mga artikulo sa simbahan sa pagbuhat niini, ug mao kini ang ilang ipangtudlo, kay sila pagagiyahan sa Espiritu."},{"verse":14,"text":"Ug ang Espiritu ihatag nganha kaninyo pinaagi sa matuohon nga pag-ampo; ug kon dili ninyo madawat ang Espiritu kinahanglang dili kamo motudlo."},{"verse":15,"text":"Ug kining tanan buhaton ninyo sumala sa akong gisugo mahitungod sa unsay inyong itudlo, hangtod nga ang kahingpitan sa akong mga kasulatan ihatag."},{"verse":16,"text":"Ug samtang inyong ipalanog ang inyong mga tingog pinaagi sa Maghuhupay, mamulong ug managna kamo sumala sa akong gilantaw nga maayo;"},{"verse":17,"text":"Kay, tan-awa, ang Maghuhupay nasayod sa tanang butang, ug nagpamatuod sa Amahan ug sa Anak."},{"verse":18,"text":"Ug karon, tan-awa, Ako mamulong ngadto sa simbahan. Ayaw kamo pagpatay; ug siya nga nagpatay dili makaangkon og kapasayloan niini nga kalibotan, o sa kalibotan nga moabot."},{"verse":19,"text":"Ug usab, mosulti ako, ayaw kamo pagpatay; apan siya nga nagpatay kay mamatay."},{"verse":20,"text":"Ayaw kamo pagpangawat; ug siya nga nangawat ug dili maghinulsol isalikway."},{"verse":21,"text":"Ayaw kamo pagpamakak; siya nga namakak ug dili maghinulsol isalikway."},{"verse":22,"text":"Higugmaa ang imong asawa sa tibuok nimong kasingkasing, ug mounong kaniya ug wala nay lain."},{"verse":23,"text":"Ug siya nga motan-aw sa usa ka babaye inubanan sa daotang tinguha nagsalikway sa iyang pagtuo, ug dili makabaton sa Espiritu; ug kon dili siya maghinulsol isalikway siya."},{"verse":24,"text":"Ayaw kamo pagpanapaw; ug siya nga nanapaw, ug dili maghinulsol, isalikway siya."},{"verse":25,"text":"Apan siya nga nanapaw ug maghinulsol sa iyang tibuok nga kasingkasing, ug mibiya niini, ug wala na magbuhat niini, inyong pasayloon;"},{"verse":26,"text":"Apan kon mobuhat siya niini pag-usab, dili siya pasayloon, apan isalikway."},{"verse":27,"text":"Ayaw kamo pagsulti og datoan sa inyong silingan, o magpasakit kaniya."},{"verse":28,"text":"Nasayod kamo sa akong mga balaod kabahin niining mga butanga nga gihatag diha sa akong mga kasulatan; siya nga nakasala ug dili maghinulsol isalikway."},{"verse":29,"text":"Kon nahigugma kamo kanako serbisyohi ninyo ako ug tumana ang akong tanang sugo."},{"verse":30,"text":"Ug tan-awa, hinumdomi ninyo ang kabos, ug ipahinungod ang inyong mga kabtangan aron itabang kanila kanang angay ninyong ipakigbahin kanila, inubanan sa pakigsaad ug sulat sa kasabotan nga dili malapas."},{"verse":31,"text":"Ug kay kamo mopakigbahin sa inyong mga butang ngadto sa mga kabos, magabuhat kamo niini alang kanako; ug ihatag kini sa atubangan sa obispo sa akong simbahan ug sa iyang mga magtatambag, duha ka elder, o halangdong mga pari, nga iyang itudlo o gitudlo ug gigahin alang niana nga katuyoan."},{"verse":32,"text":"Ug mahitabo, human nga kini mahatag sa atubangan sa obispo sa akong simbahan, ug human niya madawat kini nga mga pagpamatuod mahitungod sa pagpahinungod sa mga kabtangan sa akong simbahan, nga kini dili na makuha gikan sa simbahan, sumala sa akong mga sugo, ang matag tawo adunay tulubagon ngari kanako, usa ka tinugyanan sa iyang kaugalingong kabtangan, o nianang iyang nadawat pinaagi sa pagpahinungod, kutob sa unsay igo alang kaniya ug sa iyang pamilya."},{"verse":33,"text":"Ug usab, kon adunay kabtangan nga anaa sa mga kamot sa simbahan, o ni bisan kinsang tawo niini, nga labaw kay sa ilang kinahanglanon alang sa ilang panginahanglan human niining una nga pagpahinungod, nga mao ang nahibilin nga ipahinungod ngadto sa obispo, pagatipigan kini aron ipangalagad niadtong nagkalisod, sa matag karon ug unya, aron ang matag tawo nga nagkinahanglan mahatagan og igo ug makadawat sumala sa iyang panginahanglan."},{"verse":34,"text":"Busa, ang nahibilin tipigan diha sa akong balay tipiganan, aron ipangalagad ngadto sa mga kabos ug timawa, nga ilhon pinaagi sa halangdon nga konseho sa simbahan, ug sa obispo ug sa iyang konseho;"},{"verse":35,"text":"Ug alang sa katuyoan sa pagpamalit og mga yuta alang sa kaayohan sa kadaghanan sa simbahan, ug sa pagtukod og mga balay alampoanan, ug sa pagtukod sa Bag-ong Jerusalem nga sa dili madugay ipadayag—"},{"verse":36,"text":"Nga ang akong katawhan sa pakigsaad matigom sa usa ka pundok niana nga adlaw nga ako moabot sa akong templo. Ug buhaton ko kini alang sa kaluwasan sa akong katawhan."},{"verse":37,"text":"Ug mahitabo, nga siya nga nakasala ug dili maghinulsol isalikway sa simbahan, ug dili na mabalik kaniya kadtong iyang gipahinungod ngadto sa kabos ug timawa sa akong simbahan, o sa lain nga pagkasulti, ngari kanako—"},{"verse":38,"text":"Tungod kay kamo nagbuhat niini ngadto sa labing ubos kanila, kamo nagbuhat niini ngari kanako."},{"verse":39,"text":"Kay mahitabo, nga kana nga akong gipamulong pinaagi sa mga ba-ba sa akong mga propeta matuman; kay akong ipahinungod ang mga katigayonan niadtong kinsa midawat sa akong ebanghelyo taliwala sa mga Hentil ngadto sa mga kabos sa akong katawhan nga sakop sa balay ni Israel."},{"verse":40,"text":"Ug usab, ayaw kamo pagpamapagarbohon sa inyong kasingkasing; himoa nga yano ang inyong tanan nga sapot ug ang katahom niini mao ang katahom sa buhat sa inyong kaugalingong mga kamot;"},{"verse":41,"text":"Ug himoa nga ang tanang butang buhaton sa kalimpyo sa akong atubangan."},{"verse":42,"text":"Ayaw kamo pagtinapolan; kay siya nga tapolan dili makakaon sa pan ni makasul-ob sa mga sapot sa mamumuo."},{"verse":43,"text":"Ug bisan kinsa nga anaa taliwala kaninyo nga masakiton, ug walay pagtuo nga mamaayo, apan nagatuo, pagaalimahan pinaagi sa tanan nga kalumo, gamit ang mga hilba ug humok nga pagkaon, ug dili pinaagi sa kamot sa kaaway."},{"verse":44,"text":"Ug ang mga elder sa simbahan, duha o labaw pa, pagatawgon, ug mag-ampo ug magpandong sa ilang mga kamot nganha kanila pinaagi sa akong ngalan; ug kon sila mamatay sila mamatay ngari kanako, ug kon sila mabuhi sila mabuhi ngari kanako."},{"verse":45,"text":"Kamo magpuyo nga maghiusa sa gugma, nga niana kamo maghilak tungod sa pagkawala kanila nga namatay, ug ilabi na gayod niadtong walay paglaom sa usa ka mahimayaon nga pagkabanhaw."},{"verse":46,"text":"Ug mahitabo nga kadtong namatay tungod kanako dili makatilaw og kamatayon, kay kini matam-is ngadto kanila;"},{"verse":47,"text":"Ug sila nga namatay nga wala ngari kanako, alaot sila, kay mapait ang ilang kamatayon."},{"verse":48,"text":"Ug usab, mahitabo nga siya nga adunay pagtuo kanako nga mamaayo, ug wala itakda sa kamatayon, pagaayohon."},{"verse":49,"text":"Siya nga adunay pagtuo nga makakita kay makakita."},{"verse":50,"text":"Siya nga adunay pagtuo nga makadungog kay makadungog."},{"verse":51,"text":"Ang bakol nga adunay pagtuo nga makalukso kay makalukso."},{"verse":52,"text":"Ug sila nga walay pagtuo sa pagbuhat niining mga butanga, apan nagatuo kanako, adunay gahom nga mahimong akong mga anak; ug kay sila wala makalapas sa akong mga balaod antoson ninyo ang ilang mga kahuyang."},{"verse":53,"text":"Mobarog kamo sa dapit sa inyong pagkatinugyanan."},{"verse":54,"text":"Ayaw ninyo kuhaa ang sapot sa inyong igsoon; magbayad kamo alang niana nga inyong madawat gikan sa inyong igsoon."},{"verse":55,"text":"Ug kon kamo makaangkon og labaw pa kay sa nianang inyong panginahanglan, ihatag ninyo kini ngadto sa akong balay tipiganan, aron ang tanang butang mahimo sumala niana nga akong gipamulong."},{"verse":56,"text":"Pangayo kamo, ug ang akong mga kasulatan igahatag sumala sa akong gitakda, ug tipigan kini nga luwas;"},{"verse":57,"text":"Ug gikinahanglan nga magpakahilom kamo mahitungod niini, ug dili kini itudlo hangtod nga inyo kining madawat sa hingpit."},{"verse":58,"text":"Ug mohatag ako kaninyo og usa ka sugo nga itudlo unya ninyo sa tanang tawo; kay kinahanglang itudlo kini ngadto sa tanang kanasoran, kaliwatan, mga pinulongan ug mga katawhan."},{"verse":59,"text":"Hunahunaa ninyo ang mga butang nga inyong nadawat, nga gihatag nganha kaninyo diha sa akong mga kasulatan aron mahimong balaod, isip akong balaod sa pagdumala sa akong simbahan;"},{"verse":60,"text":"Ug siya nga nagabuhat sumala niining mga butanga pagaluwason, ug siya nga wala magabuhat niini pagasilotan kon magpadayon siya niini."},{"verse":61,"text":"Kon kamo mangayo, kamo makadawat og pagpadayag human sa usa ka pagpadayag, kahibalo human sa usa ka kahibalo, nga kamo masayod sa mga misteryo ug sa malinawon nga mga butang—kana nga makahatag og kamaya, kana nga makahatag og kinabuhing dayon."},{"verse":62,"text":"Pangayo kamo, ug kini ipadayag nganha kaninyo sa akong kaugalingong tukma nga panahon kon asa ang Bag-ong Jerusalem pagatukoron."},{"verse":63,"text":"Ug tan-awa, mahitabo nga ang akong mga sulugoon ipadala ngadto sa silangan, ug ngadto sa kasadpan, ngadto sa amihanan ug ngadto sa habagatan."},{"verse":64,"text":"Ug bisan karon, sugoa siya nga moadto sa silangan sa pagtudlo kanila nga makabig sa pag-adto sa kasadpan, ug kini agi og sangpotanan niana nga moabot dinhi sa yuta, ug sa mga tinago nga mga kalihokan."},{"verse":65,"text":"Tan-awa, sunda ninyo kining tanan nga butang, ug dako ang inyong ganti; kay nganha kaninyo gihatag kini aron mahibalo sa mga misteryo sa gingharian, apan ngadto sa kalibotan wala itugot ang pagkahibalo niini."},{"verse":66,"text":"Sunda ninyo ang mga balaod nga inyong nadawat ug pagmatinud-anon."},{"verse":67,"text":"Ug sa dili madugay makadawat kamo og mga pakigsaad sa simbahan, nga kana paigo na aron mapahimutang kamo, dinhi ug sa Bag-ong Jerusalem."},{"verse":68,"text":"Busa, siya nga nagkulang sa kaalam, papangayoa siya kanako, ug ako mohatag kaniya nga madagayaon ug walay pagpamuyboy."},{"verse":69,"text":"Ibayaw ang inyong mga kasingkasing ug pagmaya, kay nganha kaninyo ang gingharian, o sa laing pagkasulti, ang mga yawe sa simbahan gikahatag na. Ug ingon niana ang mahitabo. Amen."},{"verse":70,"text":"Ang mga pari ug mga magtutudlo makaangkon sa ilang mga pagkatinugyanan, sama sa mga miyembro."},{"verse":71,"text":"Ug ang mga elder ug ang halangdon nga mga pari nga natudlo sa pagtabang sa obispo isip mga magtatambag sa tanan nga butang, ang ilang mga pamilya tabangan gikan sa mga kabtangan nga gipahinungod ngadto sa obispo, alang sa kaayohan sa mga kabos, ug sa uban pang katuyoan, nga nahisgotan na;"},{"verse":72,"text":"O sila makadawat sa makiangayon nga bayad sa ilang tanang serbisyo, sa pagkatinugyanan o kondili man gani, segun sa mahunahunaan nga maayo o gikauyonan sa mga magtatambag ug sa obispo."},{"verse":73,"text":"Ug ang obispo, usab, makadawat sa iyang hinabang, o makiangayon nga bayad alang sa iyang tanan nga pagserbisyo sa simbahan."},{"verse":74,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, nga bisan kinsa nga mga tawo diha kaninyo, nga maghingilin sa ilang mga kapikas tungod sa hinungdan sa pakighilawas sa dili kapikas, o sa laing pagkasulti, kon sila magpamatuod sa inyong atubangan sa tanang pagpaubos sa kasingkasing nga mao kini ang nahitabo, dili ninyo sila isalikway gikan kaninyo;"},{"verse":75,"text":"Apan kon kamo makakita nga bisan kinsa nga mga tawo mibiya sa ilang mga kapikas tungod sa pagpanapaw, ug sila mismo mao ang nakasala, ug ang ilang mga kapikas buhi pa, isalikway sila gikan kaninyo."},{"verse":76,"text":"Ug usab, sultihan ko kamo, nga pagmabinantayon ug pagmainampingon kamo, pinaagi sa masuhiron nga mga pagpangutana, nga kamo dili modawat sa ingon diha kaninyo, kon sila minyo;"},{"verse":77,"text":"Ug kon sila dili minyo, kinahanglang maghinulsol sila sa tanan nilang mga sala o kamo dili modawat kanila."},{"verse":78,"text":"Ug usab, ang matag tawo kinsa nahisakop niini nga simbahan ni Kristo, kinahanglan maningkamot sa pagtuman sa tanang sugo ug sa mga pakigsaad sa simbahan."},{"verse":79,"text":"Ug mahitabo, nga kon dunay bisan kinsa nga mga tawo diha kaninyo ang magpatay itugyan sila ug pahamtangan sumala sa mga balaod sa yuta; kay hinumdomi nga siya walay kapasayloan; ug kini pamatud-an sumala sa mga balaod sa yuta."},{"verse":80,"text":"Ug kon bisan kinsa nga lalaki o babaye ang makapanapaw, siya pagahusayon sa atubangan sa duha ka elder sa simbahan, o labaw pa, ug matag pulong ipahamtang batok kaniya pinaagi sa duha ka saksi sa simbahan, ug dili sa kaaway; apan kon adunay labaw pa sa duha ka saksi labing maayo."},{"verse":81,"text":"Apan siya pagahukman pinaagi sa ba-ba sa duha ka saksi; ug ang mga elder ang mopahimutang sa kaso sa atubangan sa simbahan, ug ang simbahan mopataas sa ilang mga kamot batok kaniya, nga sila pahamtangan sumala sa balaod sa Dios."},{"verse":82,"text":"Ug kon mahimo, gikinahanglan nga ang obispo anaa usab."},{"verse":83,"text":"Ug sa ingon niini kamo magbuhat sa tanang kaso nga moabot sa inyong atubangan."},{"verse":84,"text":"Ug kon ang lalaki o babaye manulis, itugyan siya ngadto sa balaod sa yuta."},{"verse":85,"text":"Ug kon siya mangawat, itugyan siya sa balaod sa yuta."},{"verse":86,"text":"Ug kon siya mamakak, itugyan siya sa balaod sa yuta."},{"verse":87,"text":"Ug kon siya magbuhat og bisan unsa nga matang sa pagkadaotan, itugyan siya ngadto sa balaod, gani bisan niana nga balaod sa Dios."},{"verse":88,"text":"Ug kon ang imong igsoon nga lalaki o babaye makapahiubos kanimo, dad-on nimo siya nga kamong duha lamang; ug kon siya mokompisal magpasig-uli kamo."},{"verse":89,"text":"Ug kon dili siya mokompisal itugyan nimo siya ngadto sa simbahan, dili ngadto sa mga miyembro, apan ngadto sa mga elder. Ug kini pagahimoon sa katigoman, ug nga dili sa atubangan sa kalibotan."},{"verse":90,"text":"Ug kon ang imong igsoon nakapasakit sa kadaghanan, siya pagapantonon sa atubangan sa kadaghanan."},{"verse":91,"text":"Ug kon bisan kinsa ang nakapasakit sa dayag, siya pagabadlongon sa dayag, nga siya maulawan. Ug kon dili siya mokompisal, itugyan siya ngadto sa balaod sa Dios."},{"verse":92,"text":"Kon bisan kinsa ang makapasakit sa tago, siya pagabadlongon sa tago, nga siya adunay kahigayonan sa pagkompisal sa tago ngadto kaniya nga iyang gipasakitan, ug ngadto sa Dios, nga ang simbahan dili mamulong og makapaulaw kaniya."},{"verse":93,"text":"Ug sa ingon niini kamo modumala sa tanang butang."}]},{"chapter":43,"verses":[{"verse":1,"text":"O patalinghog, kamo nga mga elder sa akong simbahan, ug paminawa ang mga pulong nga akong ipamulong kaninyo."},{"verse":2,"text":"Kay tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga kamo nakadawat og sugo nga himoong balaod sa akong simbahan, pinaagi kaniya nga akong itudlo kaninyo sa pagdawat sa mga sugo ug mga pagpadayag gikan sa akong kamot."},{"verse":3,"text":"Ug kini segurado ninyong masayran—nga walay lain diha kaninyo ang gipili nga modawat og mga sugo ug mga pagpadayag hangtod siya pagakuhaon, kon siya magmatinud-anon kanako."},{"verse":4,"text":"Apan sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga walay lain nga pagapilion alang niini nga gasa gawas kon pinaagi kaniya; kay kon kini kuhaon gikan kaniya siya wala nay gahom gawas sa pagpili og lain puli sa iyang dapit."},{"verse":5,"text":"Ug mao kini ang balaod nganha kaninyo, nga ayaw ninyo dawata ang mga pagtulon-an ni bisan kinsa nga moabot kaninyo isip mga pagpadayag o mga sugo;"},{"verse":6,"text":"Ug kini akong ihatag kaninyo nga kamo dili mailad, aron kamo masayod nga kini dili gikan kanako."},{"verse":7,"text":"Kay sa pagkatinuod sultihan ko kamo, nga siya nga giorden ngari kanako mosulod sa ganghaan ug i-orden sama sa akong gisulti kaninyo kaniadto, sa pagtudlo niadtong mga pagpadayag nga inyong nadawat ug madawat pinaagi kaniya nga akong gipili."},{"verse":8,"text":"Ug karon, tan-awa, akong ihatag kaninyo ang usa ka sugo, nga kon kamo magpundok kamo motudlo ug mopalig-on sa usag usa, aron kamo masayod kon unsaon sa paglihok ug sa pagdumala sa akong simbahan, unsaon sa paglihok sa mga katuyoan sa akong balaod ug mga sugo, nga akong gihatag."},{"verse":9,"text":"Ug sa ingon niana kamo matudloan sa balaod sa akong simbahan, ug pagabalaanon pinaagi nianang inyong nadawat, ug kamo adunay obligasyon sa paglihok sa tumang pagkabalaan sa akong atubangan—"},{"verse":10,"text":"Kon buhaton ninyo kini, ang himaya idugang ngadto sa gingharian nga inyong nadawat. Kon dili ninyo kini buhaton, kini pagakuhaon, bisan kanang nadawat na ninyo."},{"verse":11,"text":"Tangtanga ang inyong pagkadaotan nga anaa kaninyo; balaana ang inyong mga kaugalingon sa akong atubangan;"},{"verse":12,"text":"Ug kon magtinguha kamo sa mga kahimayaan sa gingharian, pilia ninyo ang akong sulugoon nga si Joseph Smith, Jun., ug tabangi siya sa akong atubangan pinaagi sa pag-ampo uban sa pagtuo."},{"verse":13,"text":"Ug usab, sultihan ko kamo, nga kon magtinguha kamo sa mga misteryo sa gingharian, hatagi siya og pagkaon ug sinina, ug bisan unsang butang nga iyang gikinahanglan sa pagtuman sa buluhaton nga akong gisugo kaniya;"},{"verse":14,"text":"Ug kon dili ninyo kini buhaton magpabilin siya ngadto kanila nga midawat kaniya, aron akong itagana sa akong kaugalingon ang putli nga katawhan sa akong atubangan."},{"verse":15,"text":"Ug usab mosulti ako, patalinghog kamong mga elder sa akong simbahan, nga akong gipili: Wala kamo ipadala aron tudloan, apan aron sa pagtudlo sa katawhan sa mga butang nga akong gitugyan sa inyong mga kamot pinaagi sa gahom sa akong Espiritu;"},{"verse":16,"text":"Ug pagatudloan kamo gikan sa kahitas-an. Balaana ang inyong kaugalingon ug kamo pagatugahan sa gahom, nga kamo mohatag sama sa akong gipamulong."},{"verse":17,"text":"Patalinghog kamo, kay, tan-awa, ang mahinungdanon nga adlaw sa Ginoo hapit na moabot."},{"verse":18,"text":"Kay ang adlaw moabot nga ang Ginoo mopalanog sa iyang tingog gikan sa langit; ang kalangitan matay-og ug ang yuta mokurog, ug ang trumpeta sa Dios motingog og dugay ug lanog, ug mosulti ngadto sa natulog nga mga nasod: Kamong mga santos bangon ug magpakabuhi; kamo nga mga makasasala pabilin ug katulog hangtod ako motawag pag-usab."},{"verse":19,"text":"Mao nga baksi ang inyong mga bat-ang basin pa unya og kamo makit-an taliwala sa mga daotan."},{"verse":20,"text":"Ipabati ang inyong mga tingog ug walay pagpugong. Tawaga ang mga nasod sa paghinulsol, tigulang ug batan-on, ulipon ug gawasnon, nga mag-ingon: Andama ang inyong kaugalingon alang sa mahinungdanon nga adlaw sa Ginoo;"},{"verse":21,"text":"Kay kon ako, nga usa ka tawo lang, mipabati sa akong tingog ug mitawag kaninyo sa paghinulsol, ug kamo nagdumot kanako, unsa ang inyong ikasulti kon ang adlaw moabot nga ang mga dugdog mopagawas sa ilang mga tingog gikan sa mga kinatumyan sa yuta, mamulong diha sa mga dunggan sa tanang buhi; nga mag-ingon—Paghinulsol, ug pangandam alang sa mahinungdanon nga adlaw sa Ginoo?"},{"verse":22,"text":"Oo, ug usab, kon ang mga kilat mokilab gikan sa silangan ngadto sa kasadpan, ug mamulong ngadto sa tanang buhi, ug mopagimok sa mga dunggan sa tanan nga maminaw, mosulti niini nga mga pulong—Paghinulsol kamo, kay ang mahinungdanon nga adlaw sa Ginoo moabot?"},{"verse":23,"text":"Ug usab, ang Ginoo mamulong gikan sa langit, nga mag-ingon: Patalinghog, O kamong mga nasod sa yuta, ug paminaw sa mga pulong sa Dios nga nagbuhat kaninyo."},{"verse":24,"text":"O, kamong mga nasod sa yuta, hangtod kapila ako mopundok kaninyo sama sa himungaan nga mopundok sa iyang mga piso sa ilawom sa iyang mga pako, apan kamo nagdumili!"},{"verse":25,"text":"Kapila ako nagtawag kaninyo pinaagi sa ba-ba sa akong mga sulugoon, ug pinaagi sa pagpangalagad sa akong mga anghel, ug pinaagi sa akong kaugalingon nga tingog, ug pinaagi sa tingog sa mga dalugdog, ug pinaagi sa tingog sa mga kilat, ug pinaagi sa tingog sa mga unos, ug pinaagi sa tingog sa mga linog, ug unos sa dagko nga yelo, ug pinaagi sa tingog sa mga kagutom ug mga kamatay sa matag matang, ug pinaagi sa lanog kaayo nga tingog sa trumpeta, ug pinaagi sa tingog sa paghukom, ug pinaagi sa tingog sa kaluoy sa tibuok adlaw, ug pinaagi sa tingog sa himaya ug dungog ug sa mga katigayonan sa kinabuhing dayon, ug unta makaluwas kaninyo sa walay kataposan nga kaluwasan, apan kamo nagdumili!"},{"verse":26,"text":"Tan-awa, ang adlaw miabot na, nga ang kopa sa kaligutgot sa akong kasuko napuno."},{"verse":27,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, nga kini mao ang mga pulong sa Ginoo nga inyong Dios."},{"verse":28,"text":"Busa, pagtrabaho kamo, pagtrabaho kamo sa akong ubasan sa kataposan nga higayon—kay sa kataposan nga higayon motawag sa mga lumulupyo sa yuta."},{"verse":29,"text":"Kay sa akong kaugalingong tukma nga panahon ako moabot sa yuta aron sa paghukom, ug ang akong katawhan pagatubson ug maghari uban kanako sa yuta."},{"verse":30,"text":"Kay ang mahinungdanon nga Milenyum, nga akong gipamulong pinaagi sa ba-ba sa akong mga sulugoon, moabot."},{"verse":31,"text":"Kay si Satanas pagagaposon ug kon siya buhian na usab siya maghari lamang sulod sa mubo nga higayon, ug unya moabot ang kataposan sa yuta."},{"verse":32,"text":"Ug siya nga nagpuyo sa pagkamatarong mausab sa usa ka pagpamilok sa mata, ug ang yuta mahanaw pinaagi sa kalayo."},{"verse":33,"text":"Ug ang daotan moadto ngadto sa dili mapalong nga kalayo, ug walay tawo sa yuta nga makahibalo sa ilang kataposan, ni bisan kanus-a masayod, hangtod nga sila moabot sa akong atubangan aron hukman."},{"verse":34,"text":"Patalinghogi ninyo kini nga mga pulong. Tan-awa, ako si Jesukristo, ang Manluluwas sa kalibotan. Tipigi kini nga mga butang sa inyong mga kasingkasing, ug tugoti ang mga kaligdong sa kahangtoran nga mosulod sa inyong mga hunahuna."},{"verse":35,"text":"Pagmaligdong. Tumana ang akong tanang sugo. Ug mao gayod kana. Amen."}]},{"chapter":44,"verses":[{"verse":1,"text":"Tan-awa, sa ingon niana misulti ang Ginoo kaninyo akong mga sulugoon, maayo alang kanako nga kinahangalan ang mga elder sa akong simbahan tawagon ang tanan, gikan sa silangan ug gikan sa kasadpan, ug gikan sa amihanan ug gikan sa habagatan, pinaagi sa sulat o sa uban pa nga paagi."},{"verse":2,"text":"Ug mahitabo, nga kon sila magmatinud-anon, ug magpakita og hugot nga pagtuo ngari kanako, ibu-bo nako ang akong Espiritu diha kanila sa adlaw nga maghiusa sila sa pagpundok sa ilang mga kaugalingon."},{"verse":3,"text":"Ug mahitabo nga adtoon nila ang mga rehiyon sa palibot, ug mosangyaw og paghinulsol ngadto sa katawhan."},{"verse":4,"text":"Ug daghan ang makabig, hangtod nga kamo makabaton og gahom sa paghan-ay sa inyong mga kaugalingon sumala sa mga balaod sa tawo;"},{"verse":5,"text":"Aron ang inyong mga kaaway walay gahom batok kaninyo; aron kamo luwas gikan sa kadaot sa tanang butang; aron kamo makatuman sa akong mga balaod; nga ang matag higot mabugto nga gitinguha sa kaaway aron laglagon ang akong katawhan."},{"verse":6,"text":"Tan-awa, sultihan ko kamo, nga kinahanglan gayod nga moduaw kamo sa mga kabos ug sa mga timawa ug motabang kanila aron mahupay sila, aron matunhay sila hangtod nga ang tanang butang mahimo sumala sa akong balaod nga inyong nadawat. Amen."}]},{"chapter":45,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga katawhan sa akong simbahan, nga gihatagan sa gingharian; patalinghog kamo ug paminaw kaniya nga mipahimutang sa katukoran sa yuta, nga mibuhat sa mga langit ug sa tanang panon niana, ug pinaagi kaniya nabuhat ang tanang buhi nga butang, ug molihok, ug adunay kinabuhi."},{"verse":2,"text":"Ug usab mosulti ako, patalinghogi ang akong tingog, tingali unya og ang kamatayon moabot kaninyo; sa oras nga wala ninyo damha nga ang ting-init molabay, ug ang ting-ani natapos na, ug ang inyong mga kalag wala maluwas."},{"verse":3,"text":"Paminaw kaniya kinsa mao ang manlalaban sa Amahan, kinsa nangamuyo alang kaninyo sa iyang atubangan—"},{"verse":4,"text":"Nag-ingon: Amahan, tan-awa ang mga pag-antos ug ang kamatayon kaniya nga wala makasala, nga imong gikahimut-an pag-ayo; tan-awa ang dugo sa imong Anak nga gipaagas, ang iyang dugo nga imong gihatag aron ang imong kaugalingon pagahimayaon;"},{"verse":5,"text":"Mao nga, Amahan, luwasa kining akong kaigsoonan nga nagatuo sa akong ngalan, aron moduol sila kanako ug makabaton sa walay kataposan nga kinabuhi."},{"verse":6,"text":"Patalinghog, O kamong katawhan sa akong simbahan, ug kamong mga elder paminaw kamong tanan, ug paminawa ang akong tingog samtang gitawag pa kini karong adlawa, ug ayaw pagpatig-a sa inyong mga kasingkasing;"},{"verse":7,"text":"Kay sa pagkatinuod sultihan ko kamo nga ako ang Alpha ug Omega, ang sinugdanan ug ang kataposan, ang kahayag ug ang kinabuhi sa kalibotan—ang kahayag nga nagdan-ag sa kangitngit ug ang kangitngit wala makasabot niini."},{"verse":8,"text":"Mianhi ako sa akong katawhan, ug ang akong katawhan wala modawat kanako; apan kutob sa midawat kanako gihatagan nako og gahom sa pagbuhat ug daghan nga milagro, ug aron mahimong mga anak sa Dios; ug gani ngadto kanila nga mituo sa akong ngalan gihatagan nako og gahom aron makaangkon og kinabuhing dayon."},{"verse":9,"text":"Ug mao gayod nga akong gipadala ang akong walay kataposan nga pakigsaad ngadto sa kalibotan, aron mahimong kahayag sa kalibotan, ug mahimong sumbanan alang sa akong katawhan, ug alang sa mga Hentil sa pagpangita niini, ug mahimo nga sinugo sa akong atubangan sa pag-andam sa agianan sa dili pa ako moabot."},{"verse":10,"text":"Mao nga, adtoa ninyo kini, ug ngadto kaniya nga moabot ako mangatarongan ingon sa mga tawo sa karaan nga panahon, ug akong ipakita kaninyo ang akong makaagni nga pangatarongan."},{"verse":11,"text":"Mao nga, paminaw kamong tanan ug tugoti nga ipakita ko kaninyo gani ang akong kaalam—ang kaalam niya nga inyong gisulti nga mao ang Dios ni Enoch, ug sa iyang kaigsoonan,"},{"verse":12,"text":"Kinsa nahimulag gikan sa kalibotan, ug gidawat sa akong kaugalingon—ang siyudad nga gitagana hangtod sa pag-abot sa adlaw sa pagkamatarong—ang adlaw nga gipangita sa tanang tawo nga balaan, ug wala sila makakita niini tungod sa pagkadaotan ug sa pagkasalawayon;"},{"verse":13,"text":"Ug miangkon nga sila mga dayo ug mga magpapanaw sa yuta;"},{"verse":14,"text":"Apan nakadawat og saad nga sila makakaplag niini ug makakita niini unya sa ilang nabanhaw nga lawas."},{"verse":15,"text":"Mao nga, patalinghog ug ako mangatarongan kaninyo, ug ako mamulong kaninyo ug managna, sama sa mga tawo sa karaan nga mga adlaw."},{"verse":16,"text":"Ug ipakita nako kini sa yano nga paagi sama nga ako mipakita niini ngadto sa akong mga disipulo samtang ako nagbarog sa ilang atubangan diha sa unod, ug namulong ngadto kanila, nga nag-ingon: Tungod kay kamo nangutana kanako mahitungod sa mga timailhan sa akong pag-anhi, sa adlaw nga ako moabot sa akong himaya sa mga panganod sa langit, aron sa pagtuman sa mga saad nga akong gihimo ngadto sa inyong mga amahan,"},{"verse":17,"text":"Kay inyong giisip nga ang dugay nga pagkawala sa inyong mga espiritu gikan sa inyong mga lawas nga usa ka pagkaulipon, ipakita nako kaninyo sa unsang paagi moabot ang adlaw sa katubsanan, ug usab ang pagpahiuli sa nagkatibulaag nga Israel."},{"verse":18,"text":"Ug karon nakita ninyo kini nga templo nga anaa sa Jerusalem, nga inyong gitawag nga balay sa Dios, ug ang inyong mga kaaway nag-ingon nga kini nga balay dili gayod matumpag."},{"verse":19,"text":"Apan, sa pagkatinuod sultihan ko kamo, nga ang kalaglagan moabot niini nga henerasyon sama sa kawatan sa kagabhion, ug kini nga katawhan pagalaglagon ug pagatibulaagon uban sa tanang nasod."},{"verse":20,"text":"Ug kini nga templo nga inyong nakita karon mapukan nga walay mahibilin bisan usa ka bato nga pinatong sa bato."},{"verse":21,"text":"Ug mahitabo, nga kini nga henerasyon sa mga Judeo dili mahanaw hangtod ang matag kalaglagan nga akong gisulti kaninyo mahitungod kanila mahitabo."},{"verse":22,"text":"Kamo nag-ingon nga nasayod kamo nga ang kataposan sa kalibotan moabot; kamo nag-ingon usab nga nasayod kamo nga ang kalangitan ug ang yuta mahanaw;"},{"verse":23,"text":"Ug niini kamo nag-ingon sa pagkatinuod, kay mao man kini; apan kining mga butanga nga akong gisulti kaninyo dili molabay hangtod matuman ang tanan."},{"verse":24,"text":"Ug kini akong gisulti kaninyo mahitungod sa Jerusalem; ug kon moabot na kana nga adlaw, ang salin pagatibulaagon taliwala sa tanang nasod;"},{"verse":25,"text":"Apan pagapundokon sila pag-usab; apan dili sila mapundok hangtod ang mga panahon sa mga Hentil matuman."},{"verse":26,"text":"Ug niana nga adlaw madungog ang mga gubat ug mga hungihong sa mga gubat, ug ang tibuok yuta magkaguliyang, ug ang mga kasingkasing sa mga tawo dili na mobati, ug moingon sila nga si Kristo milangay sa iyang pag-anhi hangtod sa kataposan sa kalibotan."},{"verse":27,"text":"Ug ang gugma sa tawo magkabugnaw, ug ang pagkadaotan modagsang."},{"verse":28,"text":"Ug kon ang mga panahon sa mga Hentil moabot, usa ka kahayag motungha taliwala kanila nga naglingkod sa kangitngit, ug mao kini ang kahingpitan sa akong ebanghelyo;"},{"verse":29,"text":"Apan wala kini dawata; kay sila wala makakita sa kahayag, ug ang ilang mga kasingkasing gipahilayo gikan kanako tungod sa mga lagda sa mga tawo."},{"verse":30,"text":"Ug niana nga henerasyon ang mga panahon sa mga Hentil matuman."},{"verse":31,"text":"Ug adunay mga tawo nga magbarog niana nga henerasyon, nga sila dili mamatay hangtod nga makita nila ang hilabihan nga kastigo; kay ang makamatay nga sakit motabon sa yuta."},{"verse":32,"text":"Apan ang akong mga disipulo magbarog sa balaan nga mga dapit, ug dili mabalhin; apan taliwala sa mga daotan, ang mga tawo mopataas sa ilang mga tingog ug motunglo sa Dios ug mamatay."},{"verse":33,"text":"Ug adunay mga linog usab sa nagkalain-laing mga dapit, ug daghan nga kalaglagan; apan ang mga tawo magpatig-a sa ilang mga kasingkasing batok kanako, ug mogamit sila sa espada, batok sa usag usa, ug sila mopatay sa usag usa."},{"verse":34,"text":"Ug karon, sa dihang nakasulti ako niini nga mga pulong ngadto sa akong mga disipulo, nabalaka sila."},{"verse":35,"text":"Ug gisultihan nako sila: Ayaw kabalaka, kay, kon kining tanan nga butang mahitabo, inyong masayran nga ang mga saad nga gihimo nganha kaninyo matuman."},{"verse":36,"text":"Ug kon ang kahayag mosugod sa pagbusilak, kini mao usab ngadto kanila sama sa sambingay nga akong ipakita kaninyo—"},{"verse":37,"text":"Tan-awa ug sud-onga ang mga kahoy nga igos, ug makita ninyo kini sa inyong mga mata, ug kamo moingon nga kon kini mosugod sa pagpanalingsing, ug ang mga dahon niini linghod pa, nga ang ting-init hapit na moabot;"},{"verse":38,"text":"Mao gayod kana ang mahitabo sa adlaw nga sila makakita niining tanang butang, dayon makahibalo sila nga ang oras duol na."},{"verse":39,"text":"Ug mahitabo nga siya nga nahadlok kanako magpaabot nianang mahinungdanon nga adlaw sa Ginoo nga moabot, gani sa mga timailhan sa pag-anhi sa Anak sa Tawo."},{"verse":40,"text":"Ug makakita sila og mga timailhan ug mga kahibulongan, kay kini ipakita sa kalangitan sa ibabaw, ug sa ubos sa kalibotan."},{"verse":41,"text":"Ug makakita sila og dugo, ug kalayo, ug mga inalisngaw sa aso."},{"verse":42,"text":"Ug sa dili pa moabot ang adlaw sa Ginoo, ang adlaw mongitngit, ug ang bulan mahimong dugo, ug ang mga bitoon mahulog gikan sa langit."},{"verse":43,"text":"Ug ang nahibilin pagapundokon ngadto niini nga dapit;"},{"verse":44,"text":"Ug unya mangita sila kanako, ug, tan-awa, moabot ako; ug ila akong makita sa mga panganod sa langit, gisul-oban sa gahom ug dako nga himaya; uban sa tanang balaan nga anghel; ug siya nga dili magpaabot kanako isalikway."},{"verse":45,"text":"Apan sa dili pa itigbas sa Ginoo ang hinagiban, ang anghel mopatingog sa iyang trumpeta, ug ang mga santos nga nakatulog mobangon ug mosugat kanako didto sa panganod."},{"verse":46,"text":"Mao nga, kon kamo nakatulog sa kalinaw bulahan kamo; kay sama nga kamo karon nakakita kanako ug nasayod nga ako mao, sa samang paagi moduol kamo kanako ug ang inyong mga kalag mabuhi, ug ang inyong katubsanan pagahingpiton; ug ang mga santos moabot gikan sa upat ka suok sa yuta."},{"verse":47,"text":"Unya ang hinagiban sa Ginoo itigbas diha sa mga nasod."},{"verse":48,"text":"Ug unya ang Ginoo mopahimutang sa iyang tiil sa ibabaw niini nga bungtod, ug kini mabuak ngadto sa duha, ug ang yuta mokurog, ug moligid ngadto ug ngari ug ang kalangitan usab mauyog."},{"verse":49,"text":"Ug ang Ginoo mamulong, ug ang tanang lumulupyo sa yuta makadungog niini; ug ang mga nasod sa yuta magbangotan, ug sila nga nagbiaybiay makakita sa ilang kabuang."},{"verse":50,"text":"Ug ang katalagman moabot gayod sa mabiaybiayon, ug ang tigtamay pagapuohon; ug sila nga nagbuhat sa pagkadaotan pamutlon ug itambog ngadto sa kalayo."},{"verse":51,"text":"Ug unya ang mga Judeo motan-aw kanako ug moingon: Unsa man kining mga samad sa imong mga kamot ug sa imong mga tiil?"},{"verse":52,"text":"Unya sila makahibalo nga ako ang Ginoo; kay sultihan ko sila: Kini nga mga samad mao ang mga samad nga gisamad kanako sa balay sa akong mga higala. Ako mao siya kinsa gibayaw. Ako si Jesus nga gilansang sa krus. Ako ang Anak sa Dios."},{"verse":53,"text":"Ug unya manghilak sila tungod sa ilang pagkadaotan; dayon magbangotan sila tungod kay ilang gidaogdaog ang ilang hari."},{"verse":54,"text":"Ug dayon ang nasod nga pagano matubos, ug sila nga wala masayod sa balaod adunay bahin sa unang pagkabanhaw; ug kini makiangayon alang kanila."},{"verse":55,"text":"Ug si Satanas gaposon, aron siya wala nay dapit sa mga kasingkasing sa katawhan."},{"verse":56,"text":"Ug nianang adlawa, kon ako moanhi sa akong himaya, ang sambingay nga akong gipamulong matuman mahitungod sa napulo ka birhen."},{"verse":57,"text":"Kay sila nga maalamon ug nakadawat sa kamatuoran, ug nakadawat sa Balaan nga Espiritu nga mahimo nilang giya, ug wala malimbongi—sa pagkatinuod sultihan ko kamo, dili sila pagaputlon ug itambog sa kalayo, apan molahutay niana nga adlaw."},{"verse":58,"text":"Ug ang yuta ihatag ngadto kanila alang sa ilang kabilin; ug mosanay sila ug magkalig-on, ug ang ilang mga anak motubo nga walay sala ngadto sa kaluwasan."},{"verse":59,"text":"Kay ang Ginoo anaa sa ilang taliwala, ug ang iyang himaya anaa kanila, ug siya ang ilang hari ug ang ilang magbabalaod."},{"verse":60,"text":"Ug karon, tan-awa, sultihan ko kamo, dili na kamo tugotan nga makahibalo pa og dugang mahitungod niini nga kapitulo, hangtod nga ang Bag-ong Tugon mahubad, ug diha niini ang tanang butang mahibaloan;"},{"verse":61,"text":"Mao nga ako motugot na karon nga kamo mohubad niini, aron maandam kamo sa mga butang nga moabot."},{"verse":62,"text":"Kay sa pagkatinuod sultihan ko kamo, nga ang mahinungdanon nga mga butang nagpaabot kaninyo;"},{"verse":63,"text":"Nakadungog kamo og mga gubat sa laing mga yuta; apan, tan-awa, sultihan ko kamo, haduol na kini, gani anaa na sa inyong mga pultahan, ug dili dangtan og daghang tuig gikan karon makadungog kamo og mga gubat sa kaugalingon ninyong mga yuta."},{"verse":64,"text":"Mao nga ako, ang Ginoo, miingon, pagpundok kamo gikan sa silangan nga bahin sa mga yuta, pundoka ninyo ang inyong kaugalingon kamong mga elder sa akong simbahan; panglakaw kamo ngadto sa kasadpan nga mga nasod, magtawag sa mga lumulupyo sa paghinulsol, ug kon maghinulsol sila, pagtukod og mga simbahan ngari kanako."},{"verse":65,"text":"Ug uban sa nagkahiusa nga kasingkasing ug nagkahiusa nga hunahuna, pundoka ang inyong mga katigayonan aron makapamalit kamo og kabilin nga sa dili madugay ihatag nganha kaninyo."},{"verse":66,"text":"Ug pagatawgon kini og Bag-ong Jerusalem, usa ka yuta sa kalinaw, usa ka siyudad nga dangpanan, usa ka dapit sa kasegurohan alang sa mga santos sa Labing Halangdon nga Dios;"},{"verse":67,"text":"Ug ang himaya sa Ginoo anaa didto, ug ang kaisog sa Ginoo anaa usab didto, tungod niini ang mga daotan dili moadto niini, ug tawagon kini og Zion."},{"verse":68,"text":"Ug mahitabo diha sa mga daotan, nga matag tawo nga dili mobakyaw sa iyang espada batok sa iyang silingan kinahanglan molayas ngadto sa Zion alang sa kasegurohan."},{"verse":69,"text":"Ug adunay pagapundokon ngadto niini gikan sa matag nasod sa ubos sa langit; ug mao ra gayod kini ang katawhan nga dili magkagubat sa usag usa."},{"verse":70,"text":"Ug kini ang isulti sa mga daotan: Dili kita makiggubat batok sa Zion, kay ang mga lumulupyo sa Zion makahahadlok; mao nga dili kita makasugakod."},{"verse":71,"text":"Ug mahitabo nga ang mga matarong pagapundokon gikan sa tanang nasod, ug moadto sa Zion, mag-awit sa mga awit sa walay kataposan nga kamaya."},{"verse":72,"text":"Ug karon sultihan ko kamo, itago kining mga butanga gikan sa kalibotan hangtod nga kini tukma na ngari kanako, nga kamo makatuman niini nga buhat diha sa mga mata sa katawhan, ug sa mga mata sa inyong mga kaaway, aron dili nila masayran ang inyong mga buhat hangtod kamo makahuman sa butang nga akong gisugo kaninyo;"},{"verse":73,"text":"Nga kon mahibaloan na nila kini, ilang mahunahuna kining mga butanga."},{"verse":74,"text":"Kay kon magpakita ang Ginoo, siya ilang kahadlokan, nga sila mapuno sa kahadlok, ug magbarog sila didto sa layo ug mangurog."},{"verse":75,"text":"Ug ang tanan nga nasod mahadlok tungod sa kalisang sa Ginoo, ug sa gahom sa iyang kusog. Ug mao gayod kana. Amen."}]},{"chapter":46,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga katawhan sa akong simbahan; kay sa pagkatinuod sultihan ko kamo nga kining mga butanga gipamulong nganha kaninyo alang sa inyong kaayohan ug pagkat-on."},{"verse":2,"text":"Apan bisan pa sa mga butang nga nahisulat, gihatag kini kanunay ngadto sa mga elder sa akong simbahan gikan sa sinugdanan, ug sa tanan nga panahon, sa pagpahigayon sa tanang miting sumala sa direksyon ug giya sa Balaang Espiritu."},{"verse":3,"text":"Bisan pa niana gisugo kamo sa dili pagsalikway ni bisan kinsa gikan sa inyong mga miting sa publiko, nga gihimo alang sa tanang katawhan."},{"verse":4,"text":"Gisugo usab kamo nga dili mosalikway ni bisan kinsa nga sakop sa simbahan gikan sa inyong mga panagtigom alang sa sakramento; bisan pa niana, kon si bisan kinsa nga nakalapas, ayaw siya tugoti nga moambit hangtod siya mohimo og pakig-uli."},{"verse":5,"text":"Ug usab sultihan ko kamo, ayaw ninyo isalikway si bisan kinsa gikan sa inyong mga panagtigom alang sa sakramento ang sinsero nga nangita sa gingharian—naghisgot ako niini mahitungod niadtong dili miyembro sa simbahan."},{"verse":6,"text":"Ug usab sultihan ko kamo, mahitungod sa inyong mga miting sa pagkompirma, nga kon adunay bisan kinsa nga dili sakop sa simbahan, nga sinserong nagtinguha sa gingharian, ayaw ninyo sila isalikway."},{"verse":7,"text":"Apan gimandoan kamo sa tanan nga butang sa pagpangayo sa Dios, kinsa naghatag nga walay pagpugong; ug kana nga gipamatuod sa Espiritu diha kaninyo bisan pa niana ako nanghinaot nga kamo magbuhat uban sa tanan nga pagkabalaan sa kasingkasing, maglakaw nga matarong diha sa akong atubangan, mamalandong sa sangpotanan sa inyong kaluwasan, magbuhat sa tanang butang uban sa pag-ampo ug pagpasalamat, nga kamo dili matental sa daotang mga espiritu, o sa mga doktrina sa mga yawa, o sa mga sugo sa mga tawo; kay ang uban naggikan sa mga tawo, ug ang uban naggikan sa mga yawa."},{"verse":8,"text":"Mao nga, pagbantay kay tingali unya og kamo malimbongan; ug aron kamo dili malimbongan pangitaa sa matinguhaon nga paagi ang labing maayo nga mga gasa, ug kanunay nga maghinumdom kon alang sa unsa ang gihatag;"},{"verse":9,"text":"Kay sa pagkatinuod sultihan ko kamo, gihatag kini alang sa kaayohan niadtong nahigugma kanako ug nagtuman sa tanan nakong mga sugo, ug siya nga nagtinguha sa pagbuhat; aron ang tanan makaangkon og kaayohan nga nangita o nangayo gikan kanako, nga nangayo ug dili alang sa timailhan aron sila mogamit niini alang sa ilang mga hinakog nga pagpangibog."},{"verse":10,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, manghinaot ko nga kamo sa kanunay mahinumdom, ug ipabilin kanunay sa inyong mga hunahuna unsa kadto nga mga gasa, ang gihatag ngadto sa simbahan."},{"verse":11,"text":"Kay dili tanan ang aduna sa matag gasa nga ihatag ngadto kanila; kay adunay daghan nga gasa, ug ngadto sa matag tawo gihatag ang usa ka gasa pinaagi sa Espiritu sa Dios."},{"verse":12,"text":"Ngadto sa uban gihatag ang usa, ug ngadto sa uban gihatag ang lain, aron ang tanan makaangkon og kaayohan pinaagi niana."},{"verse":13,"text":"Ngadto sa uban gihatag kini pinaagi sa Espiritu Santo aron makahibalo nga si Jesukristo mao ang Anak sa Dios, ug nga siya gilansang sa krus alang sa mga sala sa kalibotan."},{"verse":14,"text":"Ngadto sa uban gihatag kini aron motuo sa ilang mga pulong, aron usab makabaton sila og kinabuhing dayon kon sila padayon nga matinud-anon."},{"verse":15,"text":"Ug usab, ngadto sa uban gihatag kini pinaagi sa Espiritu Santo sa pagkahibalo sa mga kalainan sa pagdumala, nga kini makapahimuot sa sama nga Ginoo, sumala sa kabubut-on sa Ginoo, nga nagpahiangay sa iyang mga kaluoy sumala sa mga kahimtang sa katawhan."},{"verse":16,"text":"Ug usab, gihatag kini pinaagi sa Espiritu Santo ngadto sa uban aron makahibalo sa nagkalain-laing mga paagi, kon kini gikan ba sa Dios, nga ang mga pagpakita sa Espiritu mahimong ihatag ngadto sa matag tawo sa iyang kaayohan."},{"verse":17,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ngadto sa uban gihatag, pinaagi sa Espiritu sa Dios, ang pulong sa kaalam."},{"verse":18,"text":"Ngadto sa uban gihatag ang pulong sa kahibalo, nga ang tanan matudloan nga magmaalamon ug magbaton og kahibalo."},{"verse":19,"text":"Ug usab, ngadto sa uban gihatag kini aron makabaton og pagtuo nga mamaayo;"},{"verse":20,"text":"Ug ngadto sa uban gihatag kini sa pagbaton og pagtuo aron makaayo."},{"verse":21,"text":"Ug usab, ngadto sa uban gihatag ang pagbuhat og mga milagro;"},{"verse":22,"text":"Ug ngadto sa uban kini gihatag aron makapanagna;"},{"verse":23,"text":"Ug ngadto sa uban ang pag-ila sa mga espiritu."},{"verse":24,"text":"Ug usab, gihatag kini ngadto sa uban aron makasulti og laing mga pinulongan;"},{"verse":25,"text":"Ug ngadto sa lain gihatag ang paghubad og mga pinulongan."},{"verse":26,"text":"Ug kining tanang gasa naggikan sa Dios, alang sa kaayohan sa mga anak sa Dios."},{"verse":27,"text":"Ug ngadto sa bishop sa simbahan, ug siya nga pilion sa Dios ug i-orden sa pagbantay sa simbahan ug himoong mga elder sa simbahan, ihatag ngadto kanila ang pag-ila sa tanang gasa basin unya og adunay uban diha kaninyo nga nagpakaaron-ingnon apan dili gikan sa Dios."},{"verse":28,"text":"Ug mahitabo nga siya nga mangayo pinaagi sa Espiritu makadawat pinaagi sa Espiritu;"},{"verse":29,"text":"Nga ngadto sa uban kini ikahatag aron maangkon kadtong tanan nga gasa, aron adunay usa ka pangulo, aron ang matag miyembro mahatagan og kaayohan pinaagi niana."},{"verse":30,"text":"Siya nga nangayo pinaagi sa Espiritu nangayo sumala sa kabubut-on sa Dios; mao nga mahitabo kon unsa man ang iyang gipangayo."},{"verse":31,"text":"Ug usab, sultihan ko kamo, ang tanang butang kinahanglan himoon pinaagi sa ngalan ni Kristo, bisan unsa ang inyong buhaton pinaagi sa Espiritu;"},{"verse":32,"text":"Ug kamo kinahanglan nga magpasalamat ngadto sa Dios pinaagi sa Espiritu alang sa bisan unsa nga panalangin nga gipanalanginan kaninyo."},{"verse":33,"text":"Ug kinahanglan mopalambo kamo og kaligdong ug pagkabalaan sa akong atubangan kanunay. Mao gayod kana. Amen."}]},{"chapter":47,"verses":[{"verse":1,"text":"Tan-awa, gikinahanglan nga ang akong sulugoon nga si John mosulat ug motipig kanunay og kasaysayan, ug motabang kanimo, akong sulugoong Joseph, sa pagsulat sa tanang butang nga ihatag kanimo, hangtod nga siya tawgon sa uban nga mga katungdanan."},{"verse":2,"text":"Usab, sa pagkatinuod sultihan ko ikaw nga ipakusog usab niya ang iyang tingog diha sa mga miting, bisan kanus-a kon gikinahanglan."},{"verse":3,"text":"Ug usab, sultihan ko ikaw nga padayon siyang pilion nga motipig sa rekord ug sa kasaysayan sa simbahan; kay si Oliver Cowdery akong gipili ngadto sa laing katungdanan."},{"verse":4,"text":"Mao nga, ihatag kini ngadto kaniya, kon siya magmatinud-anon, pinaagi sa Maghuhupay, sa pagsulat niini nga mga butang. Ug mao gayod kana. Amen."}]},{"chapter":48,"verses":[{"verse":1,"text":"Gikinahanglan nga kamo magpabilin sa inyong mga dapit nga gipuy-an karon, kay nahiangay kini sa inyong mga kahimtang."},{"verse":2,"text":"Ug kon kamo adunay mga yuta, kamo mohatag ngadto sa inyong kaigsoonan sa silangan;"},{"verse":3,"text":"Ug kon kamo walay mga yuta, papalita sila karon didto sa mga rehiyon sa palibot, nga makaayo kanila, kay kinahanglan gayod nga sila adunay mga dapit nga kapuy-an karon."},{"verse":4,"text":"Kinahanglan gayod nga inyong tigomon ang tanang kwarta kutob sa inyong mahimo, ug nga inyong maangkon ang tanan kutob sa inyong mahimo pinaagi sa pagkamatarong, aron moabot ang panahon nga makahimo kamo sa pagpalit og yuta alang sa usa ka kabilin, gani ang siyudad."},{"verse":5,"text":"Ang dapit dili pa ikapadayag; apan human ang inyong kaigsoonan moabot gikan sa silangan adunay mga tawo nga pilion, ug ngadto kanila kini ihatag aron mahibalo sa dapit, o ngadto kanila kini ipadayag."},{"verse":6,"text":"Ug pagapilion sila aron mopalit sa mga yuta, ug aron makasugod sa pagpahimutang sa pundasyon sa siyudad; ug dayon kamo magsugod nga mapundok uban sa inyong mga pamilya, matag tawo sumala sa iyang pamilya, sumala sa ilang mga kahimtang, ug sa gitudlo ngadto kaniya pinaagi sa kapangulohan ug sa bishop sa simbahan, sumala sa mga balaod ug sa mga sugo nga inyong nadawat, ug nga inyong madawat sa umaabot. Mao gayod kana. Amen."}]},{"chapter":49,"verses":[{"verse":1,"text":"Patalinghogi ang akong pulong, mga sulugoon ko nga Sidney, ug Parley, ug Leman; kay tan-awa, sa pagkatinuod sultihan ko kamo, nga ihatag ko kaninyo ang usa ka sugo nga kamo molakaw ug mosangyaw sa akong ebanghelyo nga inyong nadawat, gani sama sa inyong pagdawat niini, ngadto sa mga Shaker."},{"verse":2,"text":"Tan-awa, sultihan ko kamo, nga nagtinguha sila nga masayod og tipik sa kamatuoran, apan dili ang tanan, kay sila dili matarong sa akong atubangan ug kinahanglan gayod nga maghinulsol."},{"verse":3,"text":"Mao nga, ipadala ko kamo, akong mga sulugoon nga Sidney ug Parley, sa pagsangyaw sa ebanghelyo ngadto kanila."},{"verse":4,"text":"Ug ang akong sulugoon nga si Leman i-orden ngadto niini nga buhat, aron siya makapasabot kanila, dili sama nianang iyang nadawat gikan kanila, apan sumala sa unsay itudlo kaniya pinaagi kaninyo akong mga sulugoon; ug pinaagi sa pagbuhat niini panalanginan nako siya, kay kon dili, siya dili molambo."},{"verse":5,"text":"Sa ingon niana miingon ang Ginoo; kay ako mao ang Dios, ug mipadala sa akong Bugtong Anak ngadto sa kalibotan alang sa katubsanan sa kalibotan, ug nagsugo nga siya nga midawat kaniya pagaluwason, ug siya nga dili modawat kaniya panghimaraoton—"},{"verse":6,"text":"Ug nabuhat nila ngadto sa Anak sa Tawo sumala sa unsay ilang gusto; ug naangkon niya ang gahom gikan sa tuong kamot sa iyang himaya, ug karon naghari sa kalangitan, ug maghari hangtod nga siya mokunsad dinhi sa yuta, aron ang tanang kaaway iyang yatakan, diin nga panahon hapit na moabot—"},{"verse":7,"text":"Ako, ang Ginoong Dios, nakapamulong niini; apan ang takna ug ang adlaw walay tawo nga nasayod, bisan ang mga anghel sa langit, wala sila masayod hangtod nga siya moabot."},{"verse":8,"text":"Mao nga, gusto nako nga ang tanang tawo maghinulsol, kay ang tanan makasala, gawas niadtong akong gitagana alang sa akong kaugalingon, nga balaang mga tawo nga wala ninyo mailhi."},{"verse":9,"text":"Mao nga, sultihan ko kamo nga akong gipadala nganha kaninyo ang akong walay kataposan nga pakigsaad, gani kana nga diha na gikan pa sa sinugdanan."},{"verse":10,"text":"Ug kanang akong gisaad akong tumanon, ug ang mga nasod sa yuta moyukbo niini; ug, kon dili man sa ilang kaugalingon, sila ipaubos, tungod kay kanang gihimaya karon ipaubos pinaagi sa gahom."},{"verse":11,"text":"Mao nga, hatagan ko kamo og sugo nga kamo moadto niini nga katawhan, ug mosulti kanila, sama sa akong apostol sa karaan nga panahon, kansang ngalan mao si Pedro:"},{"verse":12,"text":"Motuo sa ngalan ni Ginoong Jesus, nga dinhi sa yuta, ug moabot, ang sinugdanan ug ang kataposan;"},{"verse":13,"text":"Maghinulsol ug magpabunyag sa ngalan ni Jesukristo, sumala sa balaan nga sugo, alang sa kapasayloan sa mga sala;"},{"verse":14,"text":"Ug kadtong mobuhat niini makadawat sa gasa sa Espiritu Santo, pinaagi sa pagpandong sa mga kamot sa mga elder sa simbahan."},{"verse":15,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, nga kadtong nagdili sa mga tawo sa pagminyo wala itugot sa Dios, kay ang kaminyoon gi-orden sa Dios ngadto sa tawo."},{"verse":16,"text":"Mao nga, subay sa balaod nga siya adunay usa ra ka asawa, ug silang duha mahimo nga usa, ug kining tanan aron ang yuta makatuman sa katuyoan sa iyang pagkalalang;"},{"verse":17,"text":"Ug aron kini mapuno sa mga tawo, sumala sa iyang pagkalalang sa wala pa mabuhat ang kalibotan."},{"verse":18,"text":"Ug kadtong nagdili sa pagkaon og mga karne, nga ang tawo dili angay nga mokaon niini, wala i-orden sa Dios;"},{"verse":19,"text":"Kay, tan-awa, ang kahayopan sa umahan ug kalanggaman sa kahanginan, ug kanang gikan sa yuta, gi-orden nga gamiton sa tawo alang sa pagkaon ug alang sa panapot, ug aron siya makaangkon og kabuhong."},{"verse":20,"text":"Apan wala itugot nga ang usa ka tawo makaangkon niana nga labaw pa kay sa uban, mao nga ang kalibotan anaa sa kahimtang sa pagpakasala."},{"verse":21,"text":"Ug alaot ang tawo nga nagpaagas og dugo o nag-usik-usik sa unod ug wala magkinahanglan niini."},{"verse":22,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, nga ang Anak sa Tawo moabot dili sa panagway sa usa ka babaye, ni sa usa ka lalaki nga nagbiyahe sa ibabaw sa yuta."},{"verse":23,"text":"Mao nga, ayaw pagpalimbong, apan padayon sa pagkamakanunayon, magtan-aw sa kalangitan nga mouyog, ug sa yuta nga mokurog ug moligid ngadto ug ngari sama sa usa ka tawo nga hubog, ug sa mga walog nga abunohan, ug sa kabukiran nga mapatag, ug sa mga libaongon nga mga dapit nga mahimong hamis—ug kining tanan mahitabo kon ang anghel mopatingog sa iyang trumpeta."},{"verse":24,"text":"Apan sa dili pa moabot ang mahinungdanon nga adlaw sa Ginoo, si Jacob mouswag diha sa kamingawan, ug ang mga Lamanita mamulak sama sa rosas."},{"verse":25,"text":"Ang Zion mouswag diha sa kabungtoran ug magmaya sa kabukiran, ug pagapundokon ngadto sa dapit nga akong itudlo."},{"verse":26,"text":"Tan-awa, sultihan ko kamo, panglakaw kamo sumala sa akong gisugo kaninyo; paghinulsol sa inyong tanang sala; pangayo ug kamo makadawat; tuktok ug kini pagaablihan nganha kaninyo."},{"verse":27,"text":"Tan-awa, anaa ako sa inyong atubangan ug anaa sa inyong luyo; ug anaa ako sa inyong taliwala, ug kamo dili na pagalibogon."},{"verse":28,"text":"Tan-awa, ako si Jesukristo, ug ako moabot dayon. Ug mao gayod kana. Amen."}]},{"chapter":50,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga mga elder sa akong simbahan, ug paminawa ang tingog sa buhi nga Dios; ug paminawa ang pulong sa kaalam nga ihatag kaninyo, sumala sa inyong gipangayo ug gikauyonan nga naglakip sa simbahan, ug sa mga espiritu nga nangadto sa nagkalain-lain nga dapit sa ibabaw sa yuta."},{"verse":2,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, nga adunay daghang espiritu nga mini nga mga espiritu, nga nangadto sa nagkalain-laing dapit sa yuta, ug naglimbong sa kalibotan."},{"verse":3,"text":"Ug usab si Satanas nagtinguha sa paglimbong kaninyo, aron siya makabuntog kaninyo."},{"verse":4,"text":"Tan-awa, ako, ang Ginoo, nagtan-aw kaninyo, ug nakakita og mga salawayon diha sa simbahan nga nagsangyaw sa akong ngalan."},{"verse":5,"text":"Apan bulahan sila kinsa mga matinud-anon ug molahutay, sa kinabuhi man o sa kamatayon, kay ilang mapanunod ang kinabuhing dayon."},{"verse":6,"text":"Apan alaot sila nga mga limbongan ug mga tigpakaaron-ingnon, kay, niini nag-ingon ang Ginoo, dad-on ko sila ngadto sa hukmanan."},{"verse":7,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, adunay mga tigpakaaron-ingnon taliwala kaninyo, nga milimbong sa uban, nga nakahatag sa kaaway og gahom; apan tan-awa sila mabalik ra;"},{"verse":8,"text":"Apan ang mga tigpakaaron-ingnon mahibaloan ug isalikway, bisan sa kinabuhi o sa kamatayon, bisan sumala sa akong kabubut-on; ug alaot sila nga gisalikway gikan sa akong simbahan, kay gibuntog sila sa kalibotan."},{"verse":9,"text":"Mao nga, kinahanglang magmatngon ang matag tawo basin iyang buhaton kana nga dili subay sa kamatuoran ug sa pagkamatarong sa akong atubangan."},{"verse":10,"text":"Ug karon duol, miingon ang Ginoo, pinaagi sa Espiritu, ngadto sa mga elder sa iyang simbahan, ug maghusay kita aron inyong masabtan;"},{"verse":11,"text":"Maghusay kita sama sa usa ka tawo nga makighusay sa laing tawo nga mag-atubangay."},{"verse":12,"text":"Karon, kon ang usa ka tawo mangatarongan masabtan siya sa tawo, tungod kay nangatarongan siya isip usa ka tawo; sa samang paagi ako, ang Ginoo, makighusay kaninyo aron kamo makasabot."},{"verse":13,"text":"Mao nga, ako ang Ginoo mangutana kaninyo niini—sa unsa ba nga buluhaton kamo gi-orden?"},{"verse":14,"text":"Sa pagsangyaw sa akong ebanghelyo pinaagi sa Espiritu, gani ang Maghuhupay nga gipadala aron sa pagtudlo sa kamatuoran."},{"verse":15,"text":"Ug unya inyong dawaton ang mga espiritu nga dili ninyo masabtan, ug midawat niini nga gikan sa Dios; ug niini kamo nahatagan ba og kaangayan?"},{"verse":16,"text":"Tan-awa tubagon ninyo kini nga pangutana sa inyong mga kaugalingon; bisan pa, ako magmaluluy-on kaninyo; siya nga huyang diha kaninyo human niini himoon nga lig-on."},{"verse":17,"text":"Sa pagkatinuod sultihan ko kamo, siya nga gi-orden ngari kanako ug gipadala aron sa pagsangyaw sa pulong sa kamatuoran pinaagi sa Maghuhupay, diha sa Espiritu sa kamatuoran, siya ba magsangyaw niini pinaagi sa Espiritu sa kamatuoran o sa lain nga paagi?"},{"verse":18,"text":"Ug kon gibuhat kini sa lahi nga paagi dili kini gikan sa Dios."},{"verse":19,"text":"Ug usab, siya nga midawat sa pulong sa kamatuoran, siya midawat ba niini pinaagi sa Espiritu sa kamatuoran o sa lain nga paagi?"},{"verse":20,"text":"Kon sa lain nga paagi dili kini gikan sa Dios."},{"verse":21,"text":"Busa, nganong dili kamo makasabot ug makahibalo, nga siya nga midawat sa pulong pinaagi sa Espiritu sa kamatuoran midawat niini ingon nga kini gisangyaw pinaagi sa Espiritu sa kamatuoran?"},{"verse":22,"text":"Mao nga, siya nga nagsangyaw ug siya nga midawat, nakasabot sa usag usa, ug ang duha malig-on ug dungan nga maglipay."},{"verse":23,"text":"Ug kana nga dili makahatag og kalig-on dili gikan sa Dios, ug iya sa kangitngit."},{"verse":24,"text":"Kana nga gikan sa Dios mao ang kahayag; ug siya nga midawat sa kahayag, ug magpadayon diha sa Dios, makadawat og dugang nga kahayag; ug kana nga kahayag mag-anam og labaw kahayag ug labaw kahayag hangtod sa hingpit nga adlaw."},{"verse":25,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ug isulti ko kini aron inyong mahibaloan ang kamatuoran, aron inyong mahinginlan ang kangitngit gikan kaninyo;"},{"verse":26,"text":"Siya nga gi-orden sa Dios ug gipadala, ang mao gitudlo nga labing gamhanan, bisan og siya mao ang labing ubos ug ang sulugoon sa tanan."},{"verse":27,"text":"Mao nga, siya ang tag-iya sa tanang butang; kay ang tanang butang ubos sa iyang pagdumala, ang anaa sa langit ug sa yuta, ang kinabuhi ug ang kahayag, ang Espiritu ug ang gahom, gipadala pinaagi sa kabubut-on sa Amahan pinaagi ni Jesukristo, ang iyang Anak."},{"verse":28,"text":"Apan walay tawo nga makapanag-iya sa tanang butang gawas kon siya mahimong putli ug malimpyohan gikan sa tanang sala."},{"verse":29,"text":"Ug kon nahimo kamong putli ug nalimpyohan gikan sa tanang sala, kamo makapangayo og bisan unsa nga inyong gusto pinaagi sa ngalan ni Jesus ug kini matuman."},{"verse":30,"text":"Apan hibaloi kini, ihatag kaninyo unsa ang inyong pangayoon; ug kay kamo gitudlo nga mangulo, ang mga espiritu ubos sa inyong pagdumala."},{"verse":31,"text":"Mao nga, mahitabo, nga kon makakita kamo og espiritu nga nagpakita nga dili ninyo masabtan, ug wala ninyo dawata kana nga espiritu, pangutan-a ninyo ang Amahan pinaagi sa ngalan ni Jesus; ug kon siya dili mohatag nganha kaninyo niana nga espiritu, niana kamo masayod nga kini dili iya sa Dios."},{"verse":32,"text":"Ug ihatag kaninyo ang gahom batok niana nga espiritu; ug kamo mopahayag batok niana nga espiritu sa makusog nga tingog nga kini dili iya sa Dios—"},{"verse":33,"text":"Dili pinaagi sa mopasipala nga paghukom, aron kamo dili mabuntog, ni uban sa panghambog ni pagmaya, basin pa unya og kamo mabuntog pinaagi niana."},{"verse":34,"text":"Siya nga nakadawat gikan sa Dios, siya moisip niini nga gikan sa Dios; ug himoa nga siya magmaya aron siya pagaisipon sa Dios nga takos nga modawat."},{"verse":35,"text":"Ug pinaagi sa pagpaminaw ug pagbuhat niining mga butang nga inyong nadawat, ug inyong madawat human niini—ug ang gingharian ihatag kaninyo gikan sa Amahan, ug ang gahom sa pagbuntog sa tanang butang nga wala niya itugot—"},{"verse":36,"text":"Ug tan-awa, sa pagkatinuod sultihan ko kamo, bulahan kamo nga naminaw karon niining akong mga pulong gikan sa ba-ba sa akong sulugoon, kay ang inyong mga sala gipasaylo."},{"verse":37,"text":"Tugoti nga ang akong sulugoon nga si Joseph Wakefield, nga nakapahimuot kanako pag-ayo, ug ang akong sulugoon nga si Parley P. Pratt sa pag-adto ngadto sa mga simbahan ug maglig-on kanila pinaagi sa pulong sa pag-awhag;"},{"verse":38,"text":"Ug usab ang akong sulugoon nga si John Corrill, o sama kadaghan sa akong mga sulugoon nga gi-orden ngadto niini nga katungdanan, ug tugoti sila nga motrabaho sa ubasan; ug ayaw itugot nga adunay tawo nga mobabag kanila sa pagbuhat nianang akong gitudlo kanila—"},{"verse":39,"text":"Mao nga, niini nga butang ang akong sulugoon nga si Edward Partridge dili mahimo nga mapawalay sala; bisan pa niana pahinulsola siya ug siya pasayloon."},{"verse":40,"text":"Tan-awa, kamo kulang pa sa kahibalo ug dili pa ninyo masabtan ang tanang butang karon; kinahanglan motubo kamo pinaagi sa grasya ug pinaagi sa pagkahibalo sa kamatuoran."},{"verse":41,"text":"Ayaw kahadlok, gagmayng panon, kay kamo akoa, ug nabuntog ko na ang kalibotan, ug kamo kabahin kanila nga gihatag sa Amahan kanako;"},{"verse":42,"text":"Ug walay usa kanila nga gihatag sa akong Amahan kanako nga mawala."},{"verse":43,"text":"Ug ang Amahan ug ako usa ra. Ako anaa sa Amahan ug ang Amahan ania kanako; ug kon kamo modawat kanako, kamo ania kanako ug ako anaa kaninyo."},{"verse":44,"text":"Mao nga, ako anaa sa inyong taliwala, ug ako ang maayong magbalantay, ug ang bato sa Israel. Siya nga nagtukod sa ibabaw niining lig-on nga sukaranan dili gayod mapukan."},{"verse":45,"text":"Ug ang adlaw moabot nga ikaw maminaw sa akong tingog ug makakita kanako, ug makaila nga ako mao."},{"verse":46,"text":"Busa, pagbantay, aron kamo makaandam. Ug mao gayod kana. Amen."}]},{"chapter":51,"verses":[{"verse":1,"text":"Patalinghog ngari kanako, miingon ang Ginoo nga inyong Dios, ug ako mamulong ngadto sa akong sulugoon nga si Edward Partridge, ug mohatag ngadto kaniya og mga direksyon; kay gikinahanglan gayod nga makadawat siya og mga direksyon unsaon sa pag-organisar kini nga katawhan."},{"verse":2,"text":"Kay gikinahanglan gayod nga maorganisar sila sumala sa akong mga balaod; kay kon dili, sila pagalaglagon."},{"verse":3,"text":"Mao nga, tugoti nga ang akong sulugoon nga si Edward Partridge, ug kadtong iyang napili, kinsa akong gikahimuot kaayo, mohatag niini nga katawhan sa ilang mga bahin, matag tawo patas mag-agad sa gidak-on sa iyang pamilya, ug sumala sa iyang mga kahimtang ug sa mga tinguha ug sa panginahanglan."},{"verse":4,"text":"Ug itugot nga ang akong sulugoon nga si Edward Partridge, kon siya mohatag ngadto sa tawo sa iyang bahin, mohatag kaniya og kasulatan nga maghatag kaniya og kasegurohan sa iyang bahin, nga siya motipig niini, gani niini nga katungod ug niini nga kabilin diha sa simbahan, gawas kon siya makalapas ug dili na pagaisipon nga takos pinaagi sa tingog sa simbahan, sumala sa mga balaod ug mga pakigsaad sa simbahan, nga mahimong sakop sa simbahan."},{"verse":5,"text":"Ug kon siya makalapas, ug dili na maisip nga takos nga mahisakop sa simbahan, siya wala nay katungod sa pag-angkon niana nga bahin nga iyang gipahinungod ngadto sa bishop alang sa kabos ug sa timawa sa akong simbahan; busa, dili siya makaangkon sa gasa, apan makapangangkon lamang niana nga bahin nga gihatag kaniya sumala sa balaod."},{"verse":6,"text":"Ug sa ingon niana ang tanang butang himoon nga segurado, sumala sa mga balaod sa yuta."},{"verse":7,"text":"Ug himoa nga kanang gipanag-iya niini nga katawhan ihatag niana nga katawhan."},{"verse":8,"text":"Ug ang kwarta nga nahibilin niini nga katawhan—tugoti nga adunay tinugyanan nga pilion ngadto niini nga katawhan, sa pagkuha sa kwarta aron isangkap og pagkaon ug sinina, sumala sa mga tinguha niini nga katawhan."},{"verse":9,"text":"Ug itugot nga ang matag tawo magmatinuoron, ug makigsama niini nga katawhan, ug pareha nga makadawat, aron kamo magkahiusa, gani sumala sa akong gisugo kaninyo."},{"verse":10,"text":"Ug tugoti nga kana nga gipanag-iya niini nga katawhan dili kuhaon ug ihatag sa laing simbahan."},{"verse":11,"text":"Mao nga, kon ang laing simbahan makadawat og kwarta gikan niini nga simbahan, pabayra sila ngadto niini nga simbahan pag-usab sumala sa ilang gikauyonan;"},{"verse":12,"text":"Ug kini pagahimoon pinaagi sa bishop o sa tinugyanan, nga itudlo pinaagi sa tingog sa simbahan."},{"verse":13,"text":"Ug usab, itugot nga ang bishop maghimo og usa ka balay tipiganan niini nga simbahan; ug itugot nga ang tanang butang kwarta man ug karne, nga mas daghan kay sa gikinahanglan nga gitinguha niini nga katawhan, tipigan diha sa mga kamot sa bishop."},{"verse":14,"text":"Ug itugot nga siya usab mag-andam alang sa iyang kaugalingon nga panginahanglan, ug alang sa mga panginahanglan sa iyang pamilya, samtang siya apil niini nga patigayon."},{"verse":15,"text":"Ug sa ingon niana ihatag nako niini nga katawhan ang pribilihiyo sa pag-organisar sa ilang mga kaugalingon sumala sa akong mga balaod."},{"verse":16,"text":"Ug akong ipahinungod kanila kini nga yuta sulod sa mubo nga panahon, hangtod nga ako, ang Ginoo, mosangkap kanila sa lain nga paagi, ug mosugo kanila sa paglakaw gikan dinhi;"},{"verse":17,"text":"Ug ang oras ug ang adlaw dili ipahibalo ngadto kanila, mao nga himoa nga sila magbinuotan niini nga yuta sa tanang katuigan, ug makahatag kini kanila og kaayohan."},{"verse":18,"text":"Tan-awa, mahimo kining panig-ingnan ngadto sa akong sulugoon nga si Edward Partridge, sa laing mga dapit, sa tanang simbahan."},{"verse":19,"text":"Ug kadtong makita nga matinud-anon, makiangayon, ug maalamon nga tinugyanan makasulod ngadto sa kamaya sa iyang Ginoo, ug makadawat og kinabuhing dayon."},{"verse":20,"text":"Sa pagkatinuod, sultihan ko kamo, ako si Jesukristo, nga moabot dayon, sa oras nga wala ninyo hunahunaa. Ug mao gayod kana. Amen."}]},{"chapter":52,"verses":[{"verse":1,"text":"Tan-awa, miingon ang Ginoo ngadto sa mga elder nga iyang gitawag ug gipili niining kataposang mga adlaw, pinaagi sa tingog sa iyang Espiritu—"},{"verse":2,"text":"Nag-ingon: Ako, ang Ginoo, mopahibalo kaninyo unsay akong gusto nga inyong buhaton gikan niini nga panahon hangtod sa sunod nga komperensiya, nga ipahigayon didto sa Missouri, sa yuta nga akong ipahinungod sa akong katawhan, nga mga salin ni Jacob, ug niadtong mga manununod sumala sa pakigsaad."},{"verse":3,"text":"Mao nga, sa pagkatinuod sultihan ko kamo, kinahanglan nga ang akong mga sulugoon nga si Joseph Smith, Jun., ug si Sidney Rigdon magsugod dayon sa ilang panaw dihadiha dayon kon mahimo na ang mga pagpangandam aron mobiya sa ilang mga panimalay, ug mopanaw ngadto sa yuta sa Missouri."},{"verse":4,"text":"Ug kon magmatinud-anon sila kanako, ipahibalo kini ngadto kanila kon unsa ang kinahanglan nilang buhaton;"},{"verse":5,"text":"Ug usab, kon magmatinud-anon sila, ipahibalo ngadto kanila ang yuta nga inyong kabilin."},{"verse":6,"text":"Ug kon dili sila magmatinud-anon, isalikway sila, sumala sa akong kabubut-on, nga ingon og maayo alang kanako."},{"verse":7,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kinahanglan nga ang akong sulugoon nga si Lyman Wight ug ang akong sulugoon nga si John Corrill mosugod sa ilang panaw sa labing madali;"},{"verse":8,"text":"Ug usab ang akong sulugoon nga si John Murdock, ug ang akong sulugoon nga si Hyrum Smith, mosugod sa ilang panaw ngadto sa sama nga dapit subay sa agianan sa Detroit."},{"verse":9,"text":"Ug kinahanglan nga mopanaw sila gikan didto nga magsangyaw sa pulong subay sa agianan, walay laing butang nga isulti gawas nianang gisulat sa mga propeta ug apostoles, ug nianang gitudlo kanila pinaagi sa Maghuhupay pinaagi sa matuohon nga pag-ampo."},{"verse":10,"text":"Kinahanglan nga manglakaw sila nga tagduha, ug sa ingon niana kinahanglan nga magsangyaw subay sa agianan sa matag kongregasyon, sa pagbunyag pinaagi sa tubig, ug sa pagpandong sa mga kamot dapit sa daplin sa tubig."},{"verse":11,"text":"Kay miingon ang Ginoo, taposon ko og dali ang akong buluhaton sa pagkamatarong, kay ang mga adlaw moabot nga akong ipadala ang paghukom ngadto sa kadaogan."},{"verse":12,"text":"Ug kinahanglan nga ang akong sulugoon nga si Lyman Wight magbantay, kay si Satanas nagtinguha sa pag-ayag kaniya sama sa tahop."},{"verse":13,"text":"Ug tan-awa, siya nga matinud-anon pagahimoon nga magmamando sa daghang butang."},{"verse":14,"text":"Ug usab, hatagan ko kamo og sundanan sa tanang butang, aron kamo dili malimbongan; kay si Satanas anaa sa tanang bahin niini nga yuta, ug naglihok siya aron sa paglimbong sa mga nasod—"},{"verse":15,"text":"Mao nga siya nga nag-ampo, kansang espiritu mahinulsolon, siya akong dawaton kon siya mosunod sa akong mga ordinansa."},{"verse":16,"text":"Siya nga namulong, kansang espiritu mahinulsolon, kansang pinulongan maaghop ug makahatag og kaayohan, siya iya sa Dios kon siya mosunod sa akong mga ordinansa."},{"verse":17,"text":"Ug usab, siya nga nangurog ubos sa akong gahom pagalig-onon, ug magdala og mga bunga sa pagdayeg ug kaalam, sumala sa mga pagpadayag ug mga kamatuoran nga akong gihatag kaninyo."},{"verse":18,"text":"Ug usab, siya nga nabuntog ug wala magdala og mga bunga, gani sumala niini nga sumbanan, dili ako."},{"verse":19,"text":"Mao nga, pinaagi niini nga sundanan kamo makaila sa mga espiritu sa tanan nga nahitabo ubos sa tibuok kalangitan."},{"verse":20,"text":"Ug ang mga adlaw miabot; sumala sa pagtuo sa mga tawo kini mahitabo kanila."},{"verse":21,"text":"Tan-awa, kini nga sugo gihatag ngadto sa tanang elder nga akong gipili."},{"verse":22,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kinahanglan nga ang akong sulugoon nga si Thomas B. Marsh ug ang akong sulugoon nga si Ezra Thyre magsugod usab sa ilang panaw, magsangyaw sa pulong subay sa agianan padulong niining mao nga yuta."},{"verse":23,"text":"Ug usab, kinahanglan nga ang akong sulugoon nga si Isaac Morley ug ang akong sulugoon nga si Ezra Booth magsugod sa ilang panaw, magsangyaw usab sa pulong subay sa agianan paingon niining mao nga yuta."},{"verse":24,"text":"Ug usab, kinahanglan nga ang akong mga sulugoon nga si Edward Partridge ug si Martin Harris magsugod sa ilang panaw uban sa akong mga sulugoon nga si Sidney Rigdon ug si Joseph Smith, Jun."},{"verse":25,"text":"Kinahanglan nga ang akong mga sulugoon nga si David Whitmer ug si Harvey Whitlock magsugod usab sa ilang panaw, ug magsangyaw subay sa agianan paingon niining mao nga yuta."},{"verse":26,"text":"Ug kinahanglan nga ang akong mga sulugoon nga si Parley P. Pratt ug si Orson Pratt magsugod sa ilang panaw, ug magsangyaw subay sa agianan, gani paingon niining mao nga yuta."},{"verse":27,"text":"Ug kinahanglan nga ang akong mga sulugoon nga si Solomon Hancock ug si Simeon Carter magsugod usab sa ilang panaw paingon niining mao nga yuta, ug magsangyaw subay sa agianan."},{"verse":28,"text":"Kinahanglan nga ang akong mga sulugoon nga si Edson Fuller ug si Jacob Scott magsugod usab sa ilang panaw."},{"verse":29,"text":"Kinahanglan nga ang akong mga sulugoon nga si Levi W. Hancock ug si Zebedee Coltrin magsugod usab sa ilang panaw."},{"verse":30,"text":"Kinahanglan nga ang akong mga sulugoon nga si Reynolds Cahoon ug si Samuel H. Smith magsugod usab sa ilang panaw."},{"verse":31,"text":"Kinahanglan nga ang akong mga sulugoon nga si Wheeler Baldwin ug si William Carter magsugod usab sa ilang panaw."},{"verse":32,"text":"Ug kinahanglan nga ang akong mga sulugoon nga si Newel Knight ug si Selah J. Griffin ma-orden, ug magsugod usab sa ilang panaw."},{"verse":33,"text":"Oo, sa pagkatinuod ako moingon, kinahanglan nga kining tanan magsugod sa ilang panaw paingon sa usa ka dapit, subay sa ilang lainlaing mga agianan, ug ang usa ka tawo dili magtukod og tukoranan, diha sa lain, ni mopanaw subay sa agianan sa lain."},{"verse":34,"text":"Siya nga matinud-anon, panalipdan ug panalanginan og daghang bunga."},{"verse":35,"text":"Ug usab, sultihan ko kamo, kinahanglan nga ang akong mga sulugoon nga si Joseph Wakefield ug si Solomon Humphrey magsugod sa ilang panaw paingon sa mga yuta sa silangan;"},{"verse":36,"text":"Kinahanglan nga sila maghago uban sa ilang mga pamilya, walay laing butang nga ipahayag gawas sa mga propeta ug apostoles, kana nga ilang nakita ug nadungog ug labing segurado nga gituohan, nga ang mga panagna matuman."},{"verse":37,"text":"Agi og sangpotanan sa sala, kinahanglan nga kana nga gitugyan diha kang Heman Basset kuhaon gikan kaniya, ug ihatag ngadto ni Simonds Ryder."},{"verse":38,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kinahanglan nga si Jared Carter ma-orden nga usa ka priest, ug usab si George James ma-orden nga usa ka pari."},{"verse":39,"text":"Kinahanglan nga ang nahibilin nga mga elder magbantay sa mga simbahan, ug mopahayag sa pulong sa mga rehiyon nga naglibot kanila; ug kinahanglan nga sila maghago pinaagi sa ilang kaugalingong mga kamot nga walay pagsimba og dios-dios ni pagkadaotan nga gihimo."},{"verse":40,"text":"Ug sa tanang butang hinumdomi ang mga kabos ug ang mga timawa, ang mga masakiton ug ang mga gisakit, kay siya nga wala magbuhat niini nga mga butang, ang mao dili akong disipulo."},{"verse":41,"text":"Ug usab, kinahanglan nga ang akong mga sulugoon nga sila si Joseph Smith, Jun., ug Sidney Rigdon ug Edward Partridge magdala og rekomend gikan sa simbahan. Ug kinahanglan nga adunay usa nga makuha usab alang sa akong sulugoon nga si Oliver Cowdery."},{"verse":42,"text":"Ug sa ingon niana, sama sa akong gisulti, kon kamo matinud-anon maghiusa kamo sa pagpundok aron maglipay diha sa yuta sa Missouri, nga mao ang yuta nga inyong panulundon, nga mao karon ang yuta sa inyong mga kaaway."},{"verse":43,"text":"Apan, tan-awa, ako, ang Ginoo, mopadali sa pagtukod sa siyudad niana nga panahon, ug mokorona sa matinud-anon uban sa kamaya ug uban sa kalipay."},{"verse":44,"text":"Tan-awa, ako si Jesukristo, ang Anak sa Dios, ug ako mobayaw kanila sa kataposang adlaw. Ug mao gayod kana. Amen."}]},{"chapter":53,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko ikaw, akong sulugoong Sidney Gilbert, nga nakadungog ako sa imong mga pag-ampo; ug ikaw nagtawag kanako nga ipahibalo kini nganha kanimo, sa Ginoo nga imong Dios, ang mahitungod sa imong balaan nga tawag ug pagkapili sa simbahan, diin ako, ang Ginoo, mao ang nagtukod niining kataposang mga adlaw."},{"verse":2,"text":"Tan-awa, ako, ang Ginoo, nga gilansang sa krus alang sa mga sala sa kalibotan, naghatag kanimo og sugo nga imong isalikway ang kalibotan."},{"verse":3,"text":"Dawata ang akong pag-orden, gani niana nga pagka-elder, sa pagsangyaw og pagtuo ug paghinulsol ug kapasayloan sa mga sala, sumala sa akong pulong, ug sa pagdawat sa Balaang Espiritu pinaagi sa pagpandong sa mga kamot;"},{"verse":4,"text":"Ug usab sa pagkahimong tinugyanan niini nga simbahan sa dapit nga pilion sa bishop, sumala sa mga sugo nga ihatag human niini."},{"verse":5,"text":"Ug usab, sa pagkatinuod sultihan ko ikaw, magsugod ka sa imong panaw uban sa akong mga sulugoon nga si Joseph Smith, Jun., ug si Sidney Rigdon."},{"verse":6,"text":"Tan-awa, mao kini ang unang mga ordinansa nga imong madawat; ug ang nahibilin ipahibalo sa usa ka panahon nga moabot, sumala sa imong paghago sa akong ubasan."},{"verse":7,"text":"Ug usab, gusto ko nga imong mahibaloan nga ang maluwas siya lamang nga molahutay ngadto sa kataposan. Ug mao gayod kana. Amen."}]},{"chapter":54,"verses":[{"verse":1,"text":"Tan-awa, miingon ang Ginoo, gani ang Alpha ug ang Omega, ang sinugdanan ug ang kataposan, gani siya kinsa gilansang sa krus alang sa mga sala sa kalibotan—"},{"verse":2,"text":"Tan-awa, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, akong sulugoon nga Newel Knight, ikaw kinahanglan nga lig-ong mobarog diha sa katungdanan nga akong gipili alang kanimo."},{"verse":3,"text":"Ug kon ang imong mga igsoon nagtinguha sa pag-ikyas gikan sa ilang mga kaaway, pahinulsola sila sa ilang tanang sala, ug mahimong tinuod nga mapaubsanon sa akong atubangan ug mahinulsolon."},{"verse":4,"text":"Ug kay ang pakigsaad nga ilang gihimo ngari kanako nalapas, mao nga nahimo kining walay kapuslanan ug walay sangpotanan."},{"verse":5,"text":"Ug alaot siya nga nakahimo niini nga kalapasan, kay mas maayo pa kaniya nga malumos na lang sa kinahiladman sa dagat."},{"verse":6,"text":"Apan bulahan sila nga nagtuman sa pakigsaad ug nagsunod sa sugo, kay makaangkon sila og kaluoy."},{"verse":7,"text":"Mao nga, lakaw na ug biya sa yuta, basin pa unya og ang inyong mga kaaway mosulong kaninyo; ug sugdi ang inyong panaw, ug pagpili kinsa ang inyong gusto nga himoon ninyong pangulo, ug mobayad og mga salapi alang kaninyo."},{"verse":8,"text":"Ug sa ingon niana magsugod kamo sa inyong panaw, ngadto sa mga rehiyon sa kasadpan nga bahin, ngadto sa yuta sa Missouri, ngadto sa mga utlanan sa mga Lamanita."},{"verse":9,"text":"Ug pagkahuman sa inyong pagpanaw, tan-awa, sultihan ko kamo, pangita kamo og panginabuhian sama sa mga tawo, hangtod nga ako makaandam og dapit alang kaninyo."},{"verse":10,"text":"Ug usab, pagmapailobon diha sa kalisdanan hangtod nga ako moabot; ug, tan-awa, moabot ako sa labing madali, ug ang akong ganti ania kanako, ug sila kinsa sayo nga mangita kanako makakaplag og kapahulayan sa ilang mga kalag. Ug mao gayod kana. Amen."}]},{"chapter":55,"verses":[{"verse":1,"text":"Tan-awa, miingon ang Ginoo kanimo, akong sulugoon nga William, oo, gani ang Ginoo sa tibuok yuta, ikaw gitawag ug gipili; ug human nga ikaw nabunyagan pinaagi sa tubig, nga kon imong buhaton uban sa panan-aw nga nakatutok sa akong himaya, ikaw makabaton og kapasayloan sa imong mga sala ug makadawat sa Balaang Espiritu pinaagi sa pagpandong sa mga kamot;"},{"verse":2,"text":"Ug unya ikaw i-orden pinaagi sa kamot sa akong sulugoon nga si Joseph Smith, Jun., nga mahimong elder niini nga simbahan, sa pagsangyaw og paghinulsol ug kapasayloan sa mga sala pinaagi sa bunyag sa ngalan ni Jesukristo, ang Anak sa buhi nga Dios."},{"verse":3,"text":"Ug si bisan kinsa nga imong pandongan sa imong mga kamot, kon mahinulsolon sila sa akong atubangan, ikaw makabaton og gahom sa paghatag sa Balaang Espiritu."},{"verse":4,"text":"Ug usab, ikaw i-orden sa pagtabang sa akong sulugoon nga si Oliver Cowdery sa paghimo sa buluhaton sa pag-imprinta, ug sa pagpili ug pagsulat og mga basahon alang sa mga tulunghaan niini nga simbahan, nga ang gagmay nga mga bata usab makadawat og mga panudlo sa akong atubangan nga makapahimuot kanako."},{"verse":5,"text":"Ug usab, sa pagkatinuod sultihan ko ikaw, alang niini nga hinungdan ikaw magsugod sa imong panaw uban sa akong mga sulugoon nga sila si Joseph Smith, Jun., ug Sidney Rigdon, nga ikaw makapahiluna sa yuta nga imong panulundon sa paghimo niini nga buhat."},{"verse":6,"text":"Ug usab, tugoti nga ang akong sulugoon nga si Joseph Coe mopanaw usab uban kanila. Ang nahibilin ipahibalo human niini, gani sa akong kabubut-on. Amen."}]},{"chapter":56,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga mga tawo nga nangangkon sa akong ngalan, miingon ang Ginoo nga inyong Dios; kay tan-awa, ang akong kasuko napukaw batok sa mga masinupakon, ug mahibalo sila sa akong gahom ug sa akong kaligutgot, sa adlaw sa pagsilot ug sa kasuko nganha sa mga nasod."},{"verse":2,"text":"Ug siya nga dili mopas-an sa iyang krus ug mosunod kanako, ug motuman sa akong mga sugo, siya dili maluwas."},{"verse":3,"text":"Tan-awa, ako, ang Ginoo, nagsugo; ug siya nga dili mosunod isalikway sa akong kaugalingong tukma nga panahon, human sa akong pagsugo ug gilapas ang sugo."},{"verse":4,"text":"Mao nga ako, ang Ginoo, mosugo ug mobakwi, nga ingon og maayo kini alang kanako; ug kining tanan mahimong tulubagon diha sa mga ulo sa mga masinupakon, miingon ang Ginoo."},{"verse":5,"text":"Mao nga, ako mobakwi sa sugo nga gihatag ngadto sa akong mga sulugoon nga sila si Thomas B. Marsh ug Ezra Thayre, ug mohatag og bag-ong sugo ngadto sa akong sulugoon nga si Thomas, nga magsugod siya sa iyang panaw sa labing madali ngadto sa yuta sa Missouri, ug ang akong sulugoon nga si Selah J. Griffin mokuyog usab kaniya."},{"verse":6,"text":"Kay tan-awa, akong bakwion ang sugo nga akong gihatag ngadto sa akong mga sulugoon nga sila si Selah J. Griffin ug Newel Knight, agi og sangpotanan sa pagkagahi og ulo sa akong katawhan nga anaa sa Thompson, ug sa ilang pagkamasinupakon."},{"verse":7,"text":"Mao nga, tugoti nga ang akong sulugoon nga si Newel Knight magpabilin uban kanila; ug kutob sa moadto makaadto, nga nagmahinulsolon sa akong atubangan, ug giyahan niya ngadto sa yuta nga akong gipili."},{"verse":8,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, nga ang akong sulugoon nga si Ezra Thayre kinahanglan nga maghinulsol sa iyang garbo, ug sa iyang pagkadawo, ug mosunod sa miaging sugo nga akong gihatag kaniya mahitungod sa dapit diin siya mopuyo."},{"verse":9,"text":"Ug kon buhaton niya kini, kay walay himoong pagkabahin diha sa yuta, siya gihapon ang pilion nga moadto sa yuta sa Missouri;"},{"verse":10,"text":"Kon dili kinahanglang dawaton niya ang salapi nga iyang gibayad, ug mobiya sa dapit, ug isalikway gikan sa akong simbahan, miingon ang Ginoo sa mga panon;"},{"verse":11,"text":"Ug bisan kon ang langit ug ang yuta mahanaw, kini nga mga pulong dili mahanaw, apan matuman."},{"verse":12,"text":"Ug kon ang akong sulugoon nga si Joseph Smith Jun., kinahanglan gayod nga mobayad sa salapi, tan-awa, ako, ang Ginoo, mobayad niini ngadto kaniya pag-usab diha sa yuta sa Missouri, aron nga kadtong iyang dawaton magantihan pag-usab sumala nianang ilang gibuhat;"},{"verse":13,"text":"Kay sumala nianang ilang gibuhat sila makadawat, gani sa mga yuta nga mahimo nilang panulundon."},{"verse":14,"text":"Tan-awa, misulti ang Ginoo ngadto sa akong katawhan—kamo adunay daghang butang nga pagabuhaton ug pagahinulsolan; kay tan-awa, ang inyong mga sala miabot ngari kanako, ug wala mapasaylo, tungod kay kamo nagtinguha sa pagtambag sa inyong kaugalingon nga mga paagi."},{"verse":15,"text":"Ug ang inyong mga kasingkasing wala matagbaw. Ug kamo wala mosunod sa kamatuoran, apan nahimuot sa pagkadili matarong."},{"verse":16,"text":"Alaot kamong mga tawo nga adunahan, nga dili mohatag sa inyong kabtangan ngadto sa mga kabos, kay ang inyong mga katigayonan mokutkot sa inyong mga kalag; ug kini mao ang inyong mga pagdanguyngoy sa adlaw sa pagsilot, ug paghukom, ug kaligutgot: Ang pag-ani milabay na, ang ting-init nahuman na, ug ang akong kalag wala maluwas!"},{"verse":17,"text":"Alaot kamong mga tawo nga kabos kansang mga kasingkasing dili masulub-on, kansang mga espiritu dili mahinulsolon, kansang mga tiyan wala matagbaw, ug kansang mga kamot wala mobuhi sa pagkupot sa mga butang sa laing mga tawo, kansang mga mata puno sa kahakog, ug dili maghago pinaagi sa inyong kaugalingong mga kamot!"},{"verse":18,"text":"Apan bulahan ang mga kabos nga putli og kasingkasing, kansang mga kasingkasing masulub-on, ug kansang mga espiritu mahinulsolon, kay makakita sila sa gingharian sa Dios nga moabot diha sa gahom ug dakong himaya ngadto sa ilang kaluwasan; kay ang kabuhong sa yuta maila."},{"verse":19,"text":"Kay tan-awa, ang Ginoo moabot, ug ang iyang ganti anaa kaniya, ug siya moganti sa matag tawo, ug ang mga kabos magmaya;"},{"verse":20,"text":"Ug ang ilang mga henerasyon makapanunod sa yuta gikan sa henerasyon ngadto sa laing henerasyon, hangtod sa kahangtoran. Ug karon akong taposon ang pagpamulong nganha kaninyo. Ug mao gayod kana. Amen."}]},{"chapter":57,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga mga elder sa akong simbahan, miingon ang Ginoo nga inyong Dios, nga naghiusa sa pagpundok, sumala sa akong mga sugo, dinhi niini nga yuta, nga mao ang yuta sa Missouri, nga mao ang yuta nga akong gipili ug gipahinungod alang sa pagpundok sa mga santos."},{"verse":2,"text":"Mao nga, kini mao ang yuta sa saad, ug ang dapit alang sa siyudad sa Zion."},{"verse":3,"text":"Ug miingon ang Ginoo nga inyong Dios, kon kamo modawat og kaalam ania ang kaalam. Tan-awa, ang dapit nga karon gitawag og Independence mao ang sentro nga dapit; ug ang luna alang sa templo anaa nahimutang sa kasadpan nga bahin, sa usa ka lote nga dili layo gikan sa balay hukmanan."},{"verse":4,"text":"Mao nga, maalamon nga ang yuta kinahanglang paliton sa mga santos, ug ang matag luna usab nga nahimutang sa kasadpan nga bahin, gani sa utlanan nga direktang nagsubay tali sa Judeo ug sa Hentil;"},{"verse":5,"text":"Ug ang matag luna usab nga maoy utlanan sa mga tugwayanan, kon akong mga tinun-an tugotan sa pagpalit sa mga yuta. Tan-awa, maalamon ang paghimo niini, nga maangkon nila kini alang sa mahangtorong panulundon."},{"verse":6,"text":"Ug tugoti nga ang akong sulugoon nga si Sidney Gilbert mobarog sa katungdanan diin siya akong gipili, nga modawat og mga salapi, nga mahimong tinugyanan sa simbahan, sa pagpalit og yuta sa tanang rehiyon nga anaa sa palibot, kon pagahimoon sa pagkamatarong, ug sumala sa maalamon nga paggiya."},{"verse":7,"text":"Ug tugoti nga ang akong sulugoon nga si Edward Partridge mobarog sa katungdanan nga akong gisangon kaniya, ug mobahin ngadto sa mga santos sa ilang panulundon, sumala sa akong gisugo; ug usab niadtong iyang gisangonan nga motabang kaniya."},{"verse":8,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, tugoti nga ang akong sulugoon nga si Sidney Gilbert mopahiluna sa iyang kaugalingon niini nga dapit, ug magtukod og tindahan, aron makabaligya siya og mga butang sa walay pagpanglimbong, aron makatigom siya og salapi nga ipalit og mga yuta alang sa kaayohan sa mga santos, ug nga makabaton siya sa bisan unsa nga mga butang nga kinahanglanon sa mga disipulo aron mapahiluna sila diha sa ilang panulundon."},{"verse":9,"text":"Ug usab tugoti nga ang akong sulugoon nga si Sidney Gilbert mokuha og lisensiya—tan-awa ania ang kaalam, ug kinsa kadtong mobasa niini kinahanglang makasabot—aron siya mopadala usab og mga butang ngadto sa katawhan, gani ngadto kang bisan kinsa nga iyang gusto nga mga kawani sama sa mga klerk nga nagtrabaho ubos sa iyang pangalagad;"},{"verse":10,"text":"Ug sa ingon niana mosangkap alang sa akong mga santos, aron ang akong ebanghelyo masangyaw ngadto niadtong naglingkod sa kangitngit ug diha sa rehiyon ug anaa sa kahimtang sa makahahadlok nga kamatayon."},{"verse":11,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, tugoti ang akong sulugoon nga si William W. Phelps nga mapahiluna dinhi niini nga dapit, ug himoong tig-imprinta sa simbahan."},{"verse":12,"text":"Ug tan-awa, kon ang kalibotan modawat sa iyang mga sinulat—tan-awa ania ang kaalam—tugoti nga siya makabaton sa bisan unsa nga iyang mabatonan pinaagi sa pagkamatarong, alang sa kaayohan sa mga santos."},{"verse":13,"text":"Ug tugoti nga ang akong sulugoon nga si Oliver Cowdery motabang kaniya, gani sama sa akong gisugo, sa bisan asa nga dapit nga akong ihatag kaniya, sa pagkopya, ug sa pagkorehir, ug sa pagpili, nga ang tanang butang mahimong sakto sa akong atubangan, ingon nga kini pagapamatud-an sa Espiritu pinaagi kaniya."},{"verse":14,"text":"Ug sa ingon niana tugoti nga kadto sila nga akong gipamulong mapahiluna diha sa yuta sa Zion, sa labing dali kutob sa mahimo, uban sa ilang mga pamilya, sa pagbuhat niadtong mga butang sigon sa akong gipamulong."},{"verse":15,"text":"Ug karon mahitungod sa pagpundok—Tugoti nga angbishop ug ang tinugyanan maghimo og mga pagpangandam alang niadtong mga pamilya nga akong gisugo nga moanhi dinhi niini nga yuta, sa labing dali kutob sa mahimo, ug ipahiluna sila diha sa ilang kabilin nga yuta."},{"verse":16,"text":"Ug ngadto sa nahibilin nga mga elder ug mga miyembro ang dugang nga mga pahimangno ihatag human niini. Ug mao gayod kana. Amen."}]},{"chapter":58,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga mga elder sa akong simbahan, ug paminaw sa akong pulong, ug pagkat-on kanako unsa ang akong kabubut-on mahitungod kaninyo, ug usab mahitungod niining yuta diin kamo akong gipadala."},{"verse":2,"text":"Kay sa pagkatinuod sultihan ko kamo, bulahan siya nga nagsunod sa akong mga sugo, niini man nga kinabuhi o sa kamatayon; ug siya nga matinud-anon sa kalisdanan, ang iyang ganti mas dako didto sa gingharian sa langit."},{"verse":3,"text":"Dili kamo makakita pinaagi sa inyong kinaiyanhon nga mga mata, sa pagkakaron, sa plano sa inyong Dios mahitungod niadtong mga butang nga moabot sa umaabot, ug sa himaya nga mosunod human sa daghang kalisdanan."},{"verse":4,"text":"Kay human sa daghang kalisdanan moabot ang mga panalangin. Mao nga moabot ang adlaw nga kamo pagakoronahan og daghang himaya; ang takna wala pa moabot, apan haduol na."},{"verse":5,"text":"Hinumdomi kini, nga akong gisulti kaninyo kaniadto, nga kamo mobutang niini sa inyong kasingkasing, ug modawat nianang unsay mosunod."},{"verse":6,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, alang niini nga hinungdan ako mipadala kaninyo—nga kamo magmasulundon, ug ang inyong mga kasingkasing maandam sa pagpamatuod sa mga butang nga moabot;"},{"verse":7,"text":"Ug usab nga kamo mapasidunggan sa pagpahimutang sa sukaranan, ug sa pagpamatuod bahin sa yuta diin ang Zion sa Dios mobarog;"},{"verse":8,"text":"Ug usab nga ang usa ka bangkete sa pinili nga lamian nga mga pagkaon maandam alang sa mga kabos; oo, usa ka bangkete sa pinili nga lamian nga mga pagkaon, sa pinalugdang nga labing maayong bino, nga ang yuta mahibalo nga ang mga ba-ba sa mga propeta dili mamakak;"},{"verse":9,"text":"Oo, usa ka panihapon sa balay sa Ginoo, maayong pagkaandam, diin ang tanang nasod pagadapiton."},{"verse":10,"text":"Una, ang adunahan ug ang makinaadmanon, ang maalamon ug ang halangdon;"},{"verse":11,"text":"Ug human niana moabot ang adlaw sa akong gahom; unya ang kabos, ang bakol, ug ang buta, ug ang bungol, mosulod ngadto sa kasal sa Kordero, ug moambit sa panihapon sa Ginoo, nga giandam alang sa mahinungdanon nga adlaw nga moabot."},{"verse":12,"text":"Tan-awa, ako, ang Ginoo, namulong niini."},{"verse":13,"text":"Ug nga ang pagpamatuod moabot gikan sa Zion, oo, gikan sa ba-ba sa siyudad nga kabilin gikan sa Dios—"},{"verse":14,"text":"Oo, alang niini nga katuyoan gipadala ko kamo dinhi, ug mipili sa akong sulugoon nga si Edward Partridge, ug mihatag kaniya sa iyang misyon dinhi niini nga yuta."},{"verse":15,"text":"Apan kon dili siya maghinulsol sa iyang mga sala, nga mao ang pagkawalay pagtuo ug pagkawalay pagbati sa kasingkasing, tugoti siya nga mopatalinghog basin pa unya og siya mapukan."},{"verse":16,"text":"Tan-awa ang iyang misyon gihatag ngadto kaniya, ug dili na kini ihatag pag-usab."},{"verse":17,"text":"Ug kinsa kadtong gisangonan niini nga misyon gipili nga mahimong maghuhukom sa Israel, sama sa karaang mga adlaw, sa pagbahin sa mga yuta nga kabilin sa Dios ngadto sa iyang mga anak;"},{"verse":18,"text":"Ug sa paghukom sa iyang katawhan pinaagi sa pagpamatuod sa mga matarong, ug pinaagi sa tabang sa iyang mga magtatambag, sumala sa mga balaod sa gingharian nga gihatag pinaagi sa mga propeta sa Dios."},{"verse":19,"text":"Kay sa pagkatinuod sultihan ko kamo, ang akong balaod kinahanglang pagasundon dinhi niini nga yuta."},{"verse":20,"text":"Ayaw itugot nga adunay tawo nga maghunahuna nga siya magmamando; apan tugoti ang Dios nga momando kaniya nga naghukom, sumala sa tambag sa iyang kaugalingong kabubut-on, o, sa laing pagkasulti, kaniya nga nagtambag o naglingkod sa hukmanan."},{"verse":21,"text":"Ayaw itugot nga adunay tawo nga molapas sa mga balaod sa yuta, kay siya nga nagsunod sa mga balaod sa Dios wala kinahanglana nga molapas sa mga balaod sa yuta."},{"verse":22,"text":"Mao nga, magmasulundon sa mga gahom nga anaa karon, hangtod nga siya mohari kansang katungod mao ang paghari, ug mopukan sa tanang kaaway sa ilawom sa iyang mga tiil."},{"verse":23,"text":"Tan-awa, ang mga balaod nga inyong nadawat gikan sa akong mga kamot mao ang mga balaod sa simbahan, ug pinaagi niini nga kahayag nga kamo modawat niini. Tan-awa, ania ang kaalam."},{"verse":24,"text":"Ug karon, samtang namulong ako mahitungod sa akong sulugoon nga si Edward Partridge, kini nga yuta mao ang yuta nga iyang pinuy-anan, ug niadtong iyang gipili nga iyang mga magtatambag; ug usab mao ang yuta nga pinuy-anan kaniya nga akong gipili sa pagbantay sa akong balay tipiganan;"},{"verse":25,"text":"Mao nga, ipadala nila ang ilang mga pamilya dinhi niini nga yuta, sama sa ilang gikauyonan tali sa ilang mga kaugalingon ug kanako."},{"verse":26,"text":"Kay tan-awa, dili maayo nga ako momando sa tanang butang; kay siya nga kinahanglan nga pugson sa tanang butang, tapolan ug dili maalamon nga sulugoon; mao nga dili siya makadawat og ganti."},{"verse":27,"text":"Sa pagkatinuod moingon ko, ang mga tawo kinahanglang matinguhaon nga moapil sa maayo nga katuyoan, ug mobuhat og daghang butang pinaagi sa ilang kaugalingong gawasnon nga kabubut-on, ug mopahitabo sa daghang pagkamatarong;"},{"verse":28,"text":"Kay ang gahom anaa kanila, diin sila mao ang mga tinugyanan sa ilang mga kaugalingon. Ug kon ang mga tawo nagbuhat og maayo sila dili mawad-an sa ilang ganti."},{"verse":29,"text":"Apan siya nga dili mobuhat sa bisan unsang butang gawas kon siya mandoan, ug modawat sa mando nga maduhaduhaon ang kasingkasing, ug mosunod niini uban ang pagkatapolan, ang mao panghimaraoton."},{"verse":30,"text":"Kinsa ako nga nagbuhat sa tawo, miingon ang Ginoo, nga moisip kaniya nga walay sala kon wala siya magsunod sa akong mga sugo?"},{"verse":31,"text":"Kinsa ako, miingon ang Ginoo, nga nagsaad ug wala motuman?"},{"verse":32,"text":"Ako nagsugo ug ang mga tawo wala mosunod; ako mobakwi ug dili sila makadawat sa panalangin."},{"verse":33,"text":"Unya moingon sila sa ilang mga kasingkasing: Dili kini buhat sa Ginoo, kay ang iyang mga saad wala matuman. Apan alaot ang mga sama kanila, kay ang ilang ganti nagtago sa kahiladman, ug dili gikan sa kahitas-an."},{"verse":34,"text":"Ug karon hatagan ko kamo og dugang mga panudlo mahitungod niini nga yuta."},{"verse":35,"text":"Maalamon alang kanako nga ang akong sulugoon nga si Martin Harris mamahimong panig-ingnan ngadto sa simbahan, sa paghatag sa iyang mga salapi sa atubangan sa bishop sa simbahan."},{"verse":36,"text":"Ug usab, usa kini ka balaod ngadto sa matag tawo nga moabot niini nga yuta aron makadawat sa panulundon; ug gamiton niya ang iyang mga salapi sumala sa kamandoan sa balaod."},{"verse":37,"text":"Ug maalamon usab nga adunay mga yuta nga paliton didto sa Independence, aron mahimong dapit sa balay tipiganan, ug usab alang sa balay imprintahanan."},{"verse":38,"text":"Ug ang ubang mga panudlo mahitungod sa akong sulugoon nga si Martin Harris ihatag ngadto kaniya pinaagi sa Espiritu, aron makadawat siya sa iyang panulundon nga giisip niya nga makaayo kaniya;"},{"verse":39,"text":"Ug pahinulsola siya sa iyang mga sala, kay siya nagtinguha sa pagdayeg sa kalibotan."},{"verse":40,"text":"Ug tugoti usab ang akong sulugoon nga si William W. Phelps nga mobarog diha sa katungdanan nga akong gisangon kaniya, ug modawat sa iyang panulundon diha sa yuta;"},{"verse":41,"text":"Ug kinahanglan usab siya nga maghinulsol, kay ako, ang Ginoo, wala mahimuot kaniya, kay siya nagtinguha nga molabaw, ug dili igo ang iyang pagkamapainubsanon sa akong atubangan."},{"verse":42,"text":"Tan-awa, siya nga naghinulsol sa iyang mga sala, siya pasayloon, ug ako, ang Ginoo, dili na mahinumdom pa niini."},{"verse":43,"text":"Pinaagi niini kamo mahimong masayod kon ang tawo naghinulsol sa iyang mga sala—tan-awa, siya mokompisal niini ug mosalikway niini."},{"verse":44,"text":"Ug karon, sa pagkatinuod, ako mosulti mahitungod sa nahibilin nga mga elder sa akong simbahan, ang panahon wala pa moabot, sulod sa daghang katuigan, aron madawat nila ang ilang panulundon dinhi niini nga yuta, gawas kon sila magtinguha niini pinaagi sa matinud-anon nga pag-ampo, niana lamang nga kini ihatag ngadto kanila sa Ginoo."},{"verse":45,"text":"Kay, tan-awa, sila mopundok sa katawhan gikan sa mga kinatumyan sa yuta."},{"verse":46,"text":"Mao nga, maghiusa kamo sa pagpundok; ug sila nga wala matudlo sa pagpabilin niini nga yuta, tugoti sila nga mosangyaw sa ebanghelyo diha sa mga rehiyon nga naglibot; ug human niana tugoti sila nga mobalik sa ilang mga panimalay."},{"verse":47,"text":"Tugoti sila sa pagsangyaw subay sa agianan, ug sa pagpamatuod sa kamatuoran diha sa tanang dapit, ug sa pagtawag sa adunahan, sa hamili ug sa yano, ug sa kabos aron maghinulsol."},{"verse":48,"text":"Ug tugoti nga sila maghimo og mga simbahan, sa ingon nga ang mga lumulupyo sa yuta maghinulsol."},{"verse":49,"text":"Ug tugoti nga adunay tinugyanan nga sangonan pinaagi sa tingog sa simbahan, ngadto sa simbahan sa Ohio, aron modawat sa mga salapi nga ipalit og mga yuta diha sa Zion."},{"verse":50,"text":"Ug ako mohatag og sugo sa akong sulugoon nga si Sidney Rigdon, nga siya mosulat og usa ka paghulagway sa yuta sa Zion, ug usa ka pahayag sa kabubut-on sa Dios, ingon nga kini ipahibalo sa Espiritu ngadto kaniya;"},{"verse":51,"text":"Ug usa ka epistola ug dokumento nga naghatag og pag-uyon, nga ipakita ngadto sa tanang simbahan aron makabaton og mga salapi, nga ihatag ngadto sa mga kamot sa bishop, kaniya mismo o sa tinugyanan, nga giisip niya nga maayo alang kaniya o kon kinsa ang iyang sangonan, nga mopalit og mga yuta nga panulundon alang sa mga anak sa Dios."},{"verse":52,"text":"Kay, tan-awa, sa pagkatinuod sultihan ko kamo, ang Ginoo buot nga ang mga disipulo ug ang katawhan kinahanglang moabli sa ilang mga kasingkasing, gani sa pagpalit niining tibuok nga rehiyon sa nasod, kutob sa itugot sa panahon."},{"verse":53,"text":"Tan-awa, ania ang kaalam. Tugoti nga sila mohimo niini basin pa unya og sila walay madawat nga panulundon, gawas kon pinaagi sa pagpaagas og dugo."},{"verse":54,"text":"Ug usab, kutob sa mabatonan nga yuta, tugoti nga adunay mga trabahante sa tanang matang nga ipadala ngadto niini nga yuta, aron sa paghago alang sa mga santos sa Dios."},{"verse":55,"text":"Tugoti nga ang tanan niini nga mga butang buhaton sa kahapsay; ug tugoti nga ang mga kahigayonan sa mga yuta ipahibalo matag karon ug unya, pinaagi sa bishop o sa tinugyanan sa simbahan."},{"verse":56,"text":"Ug tugoti nga ang buhat sa pagpundok dili dalidalion, ni pinaagi sa kasamok; apan tugoti nga kini buhaton sama sa gikasabotan sa mga elder sa simbahan diha sa mga komperensiya, sumala sa kahibalo nga ilang madawat matag karon ug unya."},{"verse":57,"text":"Ug tugoti nga ang akong sulugoon nga si Sidney Rigdon mopahinungod ug mohalad niini nga yuta, ug sa luna alang sa templo, ngadto sa Ginoo."},{"verse":58,"text":"Ug tugoti nga magpatawag og komperensiya sa panagtigom; ug human niana tugoti nga ang akong mga sulugoon nga si Sidney Rigdon ug si Joseph Smith, Jun., mobalik, ug usab si Oliver Cowdery mokuyog nila, sa pagtapos sa nahibilin nga buluhaton nga akong gihatag kanila diha sa ilang kaugalingon nga yuta, ug ang nahibilin pagamandoan pinaagi sa mga komperensiya."},{"verse":59,"text":"Ug ayaw tugoti nga adunay tawo nga mobalik gikan niini nga yuta gawas kon siya mopamatuod samtang nagpadayon, nianang iyang nahibaloan ug gituohan nga labing tinuod."},{"verse":60,"text":"Tugoti nga kanang gitugyan kang Ziba Peterson bawion gikan kaniya; ug tugoti nga mobarog siya isip miyembro sa simbahan, ug maghago sa iyang kaugalingong mga kamot, uban sa kaigsoonan, hangtod nga siya igong mapanton alang sa iyang tanang sala; kay wala niya kini ikompisal, ug naghunahuna siya sa pagtago niini."},{"verse":61,"text":"Tugoti nga ang nahibilin nga mga elder niini nga simbahan, nga moanhi niini nga yuta, ang uban kanila hilabihan ka bulahan gani dili masukod, nga mopahigayon usab og usa ka komperensiya dinhi niini nga yuta."},{"verse":62,"text":"Ug tugoti nga ang akong sulugoon nga si Edward Partridge modumala sa komperensiya nga ilang ipahigayon."},{"verse":63,"text":"Ug tugoti nga sila usab mobalik, magsangyaw sa ebanghelyo samtang magpadayon, magpamatuod sa mga butang nga gipadayag ngadto kanila."},{"verse":64,"text":"Kay, sa pagkatinuod, ang tingog kinahanglang mogawas gikan niini nga dapit ngadto sa tibuok kalibotan, ug ngadto sa labing hilit nga mga bahin sa yuta—ang ebanghelyo kinahanglan gayod nga isangyaw ngadto sa matag nilalang, inubanan sa mga timailhan nga magsunod kanila nga mituo."},{"verse":65,"text":"Ug tan-awa ang Anak sa Tawo moabot. Amen."}]},{"chapter":59,"verses":[{"verse":1,"text":"Tan-awa, bulahan, miingon ang Ginoo, sila nga mianhi niini nga yuta uban sa bug-os nga tumong sa akong himaya, sumala sa akong mga sugo."},{"verse":2,"text":"Kay kadtong mga mabuhi makapanunod sa yuta, ug kadtong mga mamatay makapahulay gikan sa ilang tanang kahago, ug ang ilang mga buhat mosunod kanila; ug makadawat sila og korona didto sa mga mansyon sa akong Amahan, nga akong giandam alang kanila."},{"verse":3,"text":"Oo, bulahan sila kansang mga tiil nagbarog ibabaw sa yuta sa Zion, kinsa nagsunod sa akong ebanghelyo; kay makadawat sila sa ilang ganti sa maayong mga butang sa yuta, ug kini mamunga sa hilabihan."},{"verse":4,"text":"Ug sila pagakoronahan usab og mga panalangin nga gikan sa kahitas-an, oo, ug sa daghang sugo, ug uban sa mga pagpadayag diha sa ilang panahon—sila nga mga matinud-anon ug makugihon sa akong atubangan."},{"verse":5,"text":"Mao nga, hatagan ko sila og usa ka sugo, nga mag-ingon: Higugmaa ang Ginoo nga inyong Dios uban sa inyong tibuok nga kasingkasing, uban sa inyong tibuok nga gahom, hunahuna, ug kusog; ug sa ngalan ni Jesukristo kamo moserbisyo kaniya."},{"verse":6,"text":"Higugmaa ang inyong silingan sama sa inyong kaugalingon. Dili kamo mangawat; ni manapaw, ni magpatay, ni magbuhat og bisan unsa nga butang sama niini."},{"verse":7,"text":"Pasalamati ninyo ang Ginoo nga inyong Dios sa tanang butang."},{"verse":8,"text":"Paghalad kamo og usa ka sakripisyo ngadto sa Ginoo nga inyong Dios pinaagi sa pagkamatarong, gani nianang usa ka masulub-on nga kasingkasing ug usa ka mahinulsolon nga espiritu."},{"verse":9,"text":"Ug nga kamo mas mag-amping sa inyong mga kaugalingon nga dili mahugawan sa kalibotan, kamo moadto sa balay nga ampoanan ug mohalad sa inyong mga sakramento sa akong balaan nga adlaw;"},{"verse":10,"text":"Kay sa pagkatinuod mao kini ang adlaw nga gitudlo nganha kaninyo sa pagpahulay gikan sa inyong mga paghago, ug mohatag sa inyong mga pag-ampo ngadto sa Labing Halangdon;"},{"verse":11,"text":"Bisan pa niana ang inyong ligdong nga mga panaad ihalad diha sa pagkamatarong sa tanang adlaw ug sa tanang panahon;"},{"verse":12,"text":"Apan hinumdomi nga dinhi niini, nga adlaw sa Ginoo, kamo mohatag sa inyong mga halad ug sa inyong mga sakramento ngadto sa Labing Halangdon, mokompisal sa inyong mga sala ngadto sa inyong kaigsoonan, ug sa atubangan sa Ginoo."},{"verse":13,"text":"Ug niini nga adlaw ayaw kamo pagbuhat og bisan unsa nga butang, himoa lamang nga ang inyong pagkaon andamon uban sa usa ka katuyoan sa kasingkasing aron ang inyong pagpuasa mahimong hingpit, o, sa laing pagkasulti, aron ang inyong kamaya mapuno."},{"verse":14,"text":"Sa pagkatinuod, mao kini ang puasa ug pag-ampo, o sa laing pagkasulti, paglipay ug pag-ampo."},{"verse":15,"text":"Ug kon kamo mohimo niini nga mga butang uban sa pasalamat, uban sa malipayon nga mga kasingkasing ug mga panagway, dili uban sa sobra nga katawa, kay sala kini, apan uban sa kamaya sa kasingkasing ug malipayon nga panagway—"},{"verse":16,"text":"Sa pagkatinuod moingon ako, nga kon kamo nagbuhat niini, ang kahingpitan sa yuta mainyo, ang mga kahayopan sa umahan ug ang mga kalanggaman sa kahanginan, ug kanang mokatkat sa mga kahoy ug molakaw sa yuta;"},{"verse":17,"text":"Oo, ug ang hilba, ug ang maayo nga mga butang nga gikan sa yuta, alang sa pagkaon man o alang sa panapot, o alang sa mga balay, o alang sa mga kamalig, o alang sa mga prutasan, o alang sa mga tanaman, o alang sa mga ubasan;"},{"verse":18,"text":"Oo, ang tanang butang nga gikan sa yuta, sa panahon niana, gihimo alang sa kaayohan ug sa paggamit sa tawo, aron makapahimuot sa mata ug makapamaya sa kasingkasing;"},{"verse":19,"text":"Oo, alang sa pagkaon ug alang sa panapot, alang sa pagtilaw ug alang sa pagsimhot, sa paglig-on sa lawas ug sa pagpabuhi sa kalag."},{"verse":20,"text":"Ug makapahimuot kini sa Dios nga iyang gihatag ang tanan niini nga mga butang ngadto sa tawo; kay tungod niini nga katuyoan gibuhat kini aron gamiton, uban sa paghukom, nga dili magpalabi, ni pinaagi sa pagpugos."},{"verse":21,"text":"Ug walay butang nga ang tawo makapasilo sa Dios, o ang iyang kasuko mapukaw batok ni bisan kinsa, gawas niadtong dili mokompisal sa iyang sayop diha sa tanang butang, ug dili mosunod sa iyang mga sugo."},{"verse":22,"text":"Tan-awa, pinasubay kini sa balaod ug sa mga propeta; mao nga, ayaw na ako pangutan-a mahitungod niini nga butang."},{"verse":23,"text":"Apan hibaloi nga siya nga nagbuhat og mga buluhaton sa pagkamatarong makadawat sa iyang ganti, gani kalinaw niini nga kalibotan, ug kinabuhing dayon sa kalibotan nga moabot."},{"verse":24,"text":"Ako, ang Ginoo, namulong niini, ug ang Espiritu nagpamatuod. Amen."}]},{"chapter":60,"verses":[{"verse":1,"text":"Tan-awa, misulti ang Ginoo ngadto sa mga elder sa iyang simbahan, kinsa kinahanglang mobalik sa labing madali ngadto sa yuta diin sila naggikan: Tan-awa, nakapahimuot kini kanako, nga kamo mianhi dinhi;"},{"verse":2,"text":"Apan sa uban ako wala gayod mahimuot, kay sila dili mobuka sa ilang mga ba-ba, apan ilang gitago ang talento nga akong gihatag kanila, tungod sa kahadlok sa tawo. Alaot sila, kay ang akong kasuko napukaw batok kanila."},{"verse":3,"text":"Ug mahitabo, kon dili sila mahimong mas matinud-anon ngari kanako, pagabawion kini, bisan kanang anaa kanila."},{"verse":4,"text":"Kay ako, ang Ginoo, nagmando sa ibabaw sa kalangitan, ug taliwala sa mga kasundalohan sa yuta; ug sa adlaw nga ako mopili sa akong mga bahandi, ang tanang tawo masayod unsa kanang nagpahayag sa gahom sa Dios."},{"verse":5,"text":"Apan, sa pagkatinuod, mamulong ako kaninyo mahitungod sa inyong panaw ngadto sa yuta nga inyong gigikanan. Tugoti nga adunay sakyanan sa dagat, o pagpalit, kon gihunahuna ninyo nga makaayo, dili igsapayan ngari kanako, ug sugdi ang inyong panaw sa labing daling panahon ngadto sa dapit nga gitawag og St. Louis."},{"verse":6,"text":"Ug gikan didto tugoti nga ang akong mga sulugoon, nga sila si Sidney Rigdon, Joseph Smith, Jun., ug Oliver Cowdery magsugod na sa ilang panaw ngadto sa Cincinnati;"},{"verse":7,"text":"Ug niini nga dapit ipalanog nila ang ilang tingog ug mopahayag sa akong pulong pinaagi sa kusog nga mga tingog, nga walay kasuko o pagduhaduha, mopataas sa balaang mga kamot ngadto kanila. Kay ako makahimo kaninyo nga balaan, ug ang inyong mga sala mapasaylo."},{"verse":8,"text":"Ug tugoti nga ang nahibilin magsugod sa ilang panaw gikan sa St. Louis, nga magtinagurha, ug magsangyaw sa pulong, nga dili magdali, taliwala sa kongregasyon sa mga daotan, hangtod nga makabalik sila ngadto sa mga simbahan diin sila gikan."},{"verse":9,"text":"Ug kining tanan alang sa kaayohan sa mga simbahan; alang niini nga katuyoan nga ako mipadala kanila."},{"verse":10,"text":"Ug tugoti ang akong sulugoon nga si Edward Partridge sa pagpakigbahin sa salapi nga akong gihatag kaniya, ngadto sa akong mga elder nga gisugo sa pagbalik;"},{"verse":11,"text":"Ug siya nga makahimo, tugoti nga iuli niya kini pinaagi sa usa ka tinugyanan; ug siya nga dili makahimo, wala na kinahanglana nga mobayad."},{"verse":12,"text":"Ug karon mamulong ako bahin sa uban pa nga moabot niini nga yuta."},{"verse":13,"text":"Tan-awa, gipadala sila aron sa pagsangyaw sa akong ebanghelyo taliwala sa kongregasyon sa mga daotan; mao nga, mohatag ako kanila og sugo, nga mag-ingon: Dili ninyo usikan ang inyong panahon, ni inyong tagoan ang inyong talento nga kini dili mahibaloan."},{"verse":14,"text":"Ug human sa inyong pag-abot sa yuta sa Zion, ug nakapahayag sa akong pulong, balik kamo sa labing dali, magpahayag sa akong pulong diha sa mga kongregasyon sa mga daotan, dili sa dinalidali, ni sa kasuko ni sa pakigbangi."},{"verse":15,"text":"Ug itaktak ang mga abog sa inyong mga tiil batok niadtong dili modawat kaninyo, dili diha sa ilang atubangan, tingali unya og kamo makapasuko kanila, apan sa tago; ug hugasi ang inyong mga tiil, isip pagpamatuod batok kanila sa adlaw sa paghukom."},{"verse":16,"text":"Tan-awa, igo na kini alang kaninyo, ug sa kabubut-on niya nga nagpadala kaninyo."},{"verse":17,"text":"Ug pinaagi sa ba-ba sa akong sulugoon nga si Joseph Smith, Jun., ipahibalo ang mahitungod ni Sidney Rigdon ug ni Oliver Cowdery. Ang nahibilin human niini. Ug mao gayod kana. Amen."}]},{"chapter":61,"verses":[{"verse":1,"text":"Tan-awa, ug patalinghogi ang tingog kaniya nga aduna sa tanang gahom, kinsa gikan sa walay kataposan ngadto sa walay kataposan, gani ang Alpha ug ang Omega, ang sinugdanan ug ang kataposan."},{"verse":2,"text":"Tan-awa, sa pagkatinuod misulti ang Ginoo kaninyo, O kamo nga mga elder sa akong simbahan, nga nanagtigom niini nga dapit, kansang mga sala karon napasaylo na, kay ako, ang Ginoo, mopasaylo sa mga sala, ug maluluy-on ngadto niadtong mokompisal sa ilang mga sala uban sa mapainubsanon nga mga kasingkasing;"},{"verse":3,"text":"Apan sa pagkatinuod sultihan ko kamo, nga dili na kinahanglan nga kining tibuok nga pundok sa akong mga elder mopanaw sa paspas nga paagi sa katubigan, tingali unya og ang mga lumulupyo sa isigka daplin malaglag tungod sa pagkawalay pagtuo."},{"verse":4,"text":"Bisan pa niana, mitugot ako nga kamo mopamatuod; tan-awa, adunay daghang katalagman diha sa katubigan, ug mas labaw na sa umaabot;"},{"verse":5,"text":"Kay ako, ang Ginoo, tungod sa akong kasuko nakatakda og daghang kalaglagan diha sa katubigan; oo, ug ilabi na dinhi niini nga katubigan."},{"verse":6,"text":"Bisan pa niana, ang tanang tawo ania sa akong kamot, ug siya nga matinud-anon taliwala kaninyo dili malaglag diha sa katubigan."},{"verse":7,"text":"Mao nga, angay nga ang akong sulugoon nga si Sidney Gilbert ug ang akong sulugoon nga si William W. Phelps magdali sa ilang buluhaton ug misyon."},{"verse":8,"text":"Bisan pa niana, ako dili motugot nga mobiya kamo hangtod nga kamo mapanton sa inyong tanang sala, nga kamo mahimong usa, nga kamo dili malaglag diha sa pagkadaotan;"},{"verse":9,"text":"Apan karon, sa pagkatinuod mosulti ako, mahinungdanon alang kanako nga magbulag kamo. Mao nga tugoti nga ang akong mga sulugoon nga si Sidney Gilbert ug si William W. Phelps modala sa ilang nahauna nga pundok, ug tugoti nga sugdan nila ang ilang panaw sa madali aron makatuman sila sa ilang misyon, ug pinaagi sa pagtuo sila makabuntog;"},{"verse":10,"text":"Ug kon magmatinud-anon sila, panalipdan sila, ug ako, ang Ginoo, magauban kanila."},{"verse":11,"text":"Ug tugoti nga ang nahibilin modala nianang gikinahanglan alang sa ilang panapot."},{"verse":12,"text":"Tugoti nga ang akong sulugoon nga si Sidney Gilbert modala nianang wala niya kinahanglana, sigon sa inyong pag-uyon."},{"verse":13,"text":"Ug karon, tan-awa, alang sa inyong kaayohan gihatagan ko kamo og usa ka sugo mahitungod niini nga mga butang; ug ako, ang Ginoo, mopasabot kaninyo sama sa mga tawo sa karaang mga adlaw."},{"verse":14,"text":"Tan-awa, ako, ang Ginoo, sa sinugdanan mipanalangin sa mga katubigan; apan sa kataposang mga adlaw, pinaagi sa ba-ba sa akong sulugoon nga si Juan, akong gitunglo ang katubigan."},{"verse":15,"text":"Mao nga, moabot ang adlaw nga walay tawo nga maluwas diha sa katubigan."},{"verse":16,"text":"Ug mahisgotan kini sa moabot nga mga adlaw nga walay makaadto sa yuta sa Zion nga moagi sa katubigan, apan siya nga matarong og kasingkasing."},{"verse":17,"text":"Ug, ako, ang Ginoo, sa sinugdanan mitunglo sa yuta, bisan pa man sa kataposang mga adlaw ako mopanalangin niini, sa tukmang panahon, aron magamit sa akong mga santos, aron makaambit sila sa kabuhong niini."},{"verse":18,"text":"Ug karon hatagan ko kamo og usa ka sugo nga kon unsay akong isulti ngadto sa usa isulti ko sa tanan, nga kamo mopasidaan sa inyong kaigsoonan mahitungod niini nga katubigan, nga sila dili mopanaw diha niini, tingali unya og ang ilang pagtuo mapakyas ug mangabitik sa mga laang;"},{"verse":19,"text":"Ako, ang Ginoo, mipahayag, ug ang tiglaglag naglakaw sa ibabaw niini, ug ako dili mobakwi sa gipahayag."},{"verse":20,"text":"Ako, ang Ginoo, nasuko kaninyo kagahapon, apan karon ang akong kasuko wala na."},{"verse":21,"text":"Mao nga, tugoti nga kadtong nahitungdan sa akong gipamulong, kinahanglang magdali sa ilang panaw—sa makausa pa sultihan ko kamo, tugoti nga magdali sila sa ilang panaw."},{"verse":22,"text":"Ug dili ko igsapayan, sa dili madugay, basta matuman nila ang ilang misyon, kon moagi man sila sa tubig o agi sa yuta; pasagdi lang kini tungod kay gipahibalo na kini ngadto kanila sumala sa ilang mga paghukom human niini."},{"verse":23,"text":"Ug karon, mahitungod sa akong mga sulugoon, nga sila si Sidney Rigdon, Joseph Smith, Jun., ug Oliver Cowdery, tugoti nga dili sila moagi pag-usab sa katubigan, kondili pinaagi sa kanal, samtang magpanaw ngadto sa ilang mga panimalay; o sa laing pagkasulti dili sila moagi sa katubigan sa pagpanaw, kondili pinaagi sa kanal."},{"verse":24,"text":"Tan-awa, ako, ang Ginoo, nagtudlo og agianan alang sa panaw sa akong mga santos; ug tan-awa, mao kini ang agianan—nga human sila mobiya sa kanal mopanaw sila agi sa yuta, tungod kay gisugo sila sa pagpanaw ug moadto sa yuta sa Zion;"},{"verse":25,"text":"Ug buhaton nila ang sama sa gibuhat sa mga anak ni Israel, nag-ugbok sa ilang mga tolda dapit sa agianan."},{"verse":26,"text":"Ug, tan-awa, kini nga sugo inyong ihatag ngadto sa inyong tanang kaigsoonan."},{"verse":27,"text":"Bisan pa niana, siya nga gihatagan og gahom sa pagmando sa katubigan, kaniya kini gihatag pinaagi sa Espiritu aron mahibalo sa iyang tanang pamaagi;"},{"verse":28,"text":"Mao nga, tugoti nga siya mobuhat sigon sa gisugo kaniya sa Espiritu sa buhi nga Dios, diha man sa yuta o sa katubigan, kay kini magpabilin ngari kanako nga buhaton sa umaabot."},{"verse":29,"text":"Ug nganha kaninyo gihatag ang dalan alang sa mga santos, o ang agianan alang sa mga santos sa kampo sa Ginoo, sa pagpanaw."},{"verse":30,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, akong mga sulugoon, nga sila si Sidney Rigdon, Joseph Smith, Jun., ug Oliver Cowdery, dili mobuka sa ilang mga ba-ba diha sa kongregasyon sa mga daotan hangtod nga sila moabot sa Cincinnati;"},{"verse":31,"text":"Ug niana nga dapit ilang ipalanog ang ilang mga tingog ngadto sa Dios batok niana nga katawhan, oo, ngadto kaniya kansang kasuko napukaw batok sa ilang pagkadaotan, nga usa ka katawhan nga hapit na mahinog alang sa kalaglagan."},{"verse":32,"text":"Ug gikan diha itugot nga mopanaw sila alang sa mga kongregasyon sa ilang kaigsoonan, kay ang ilang mga kahago bisan karon mas gikinahanglan kaayo taliwala kanila kay sa kongregasyon sa mga daotan."},{"verse":33,"text":"Ug karon, mahitungod sa mga nahibilin, tugoti nga mopanaw sila ug mopahayag sa pulong taliwala sa kongregasyon sa mga daotan, kon kini gihatag;"},{"verse":34,"text":"Ug kon buhaton nila kini malimpyo ang ilang mga sapot, ug mahimo sila nga walay lama sa akong atubangan."},{"verse":35,"text":"Ug himoa nga magkuyog sila sa pagpanaw, o magtinagurha, kon gihunahuna nila nga makaayo, tugoti lamang ang akong sulugoon nga si Reynolds Cahoon, ug ang akong sulugoon nga si Samuel H. Smith, nga akong gikahimuot kaayo, nga dili ibulag hangtod nga makabalik sila sa ilang mga panimalay, ug alang kini sa maalamon nga katuyoan ngari kanako."},{"verse":36,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, kon unsa ang akong isulti ngadto sa usa mao ang akong isulti ngadto sa tanan, pagmalipayon, gagmayg mga bata; kay anaa ako sa inyong taliwala, ug wala ako mobiya kaninyo;"},{"verse":37,"text":"Ug tungod kay nagpaubos kamo sa inyong mga kaugalingon sa akong atubangan, ang mga panalangin sa gingharian inyong mapanag-iya."},{"verse":38,"text":"Baksi ang inyong mga bat-ang ug magmabinantayon ug magmaligdong, magpaabot sa pag-anhi sa Anak sa Tawo, kay siya moanhi sa takna nga wala sa inyong hunahuna."},{"verse":39,"text":"Pag-ampo sa kanunay aron dili kamo masulod ngadto sa tentasyon, nga kamo magpabilin sa adlaw sa iyang pag-anhi, bisan sa kinabuhi o sa kamatayon. Ug mao gayod kana. Amen."}]},{"chapter":62,"verses":[{"verse":1,"text":"Tan-awa, ug patalinghog, O kamo nga mga elder sa akong simbahan, miingon ang Ginoo nga inyong Dios, gani si Jesukristo, ang inyong manlalaban, kinsa nasayod sa kahuyang sa tawo ug kon unsaon sa pagtabang kanila nga natental."},{"verse":2,"text":"Ug sa pagkatinuod ang akong mga mata nagtan-aw niadtong wala pa moadto sa yuta sa Zion; mao nga ang inyong misyon wala pa mahingpit."},{"verse":3,"text":"Bisan pa niana, bulahan kamo, kay ang pagpamatuod nga inyong gipamulong natala didto sa langit aron tan-awon sa mga anghel; ug nagmaya sila kaninyo, ug ang inyong mga sala napasaylo na."},{"verse":4,"text":"Ug karon padayon sa inyong pagpanaw. Magpundok kamo diha sa yuta sa Zion; ug magpahigayon og usa ka panagtigom ug magkahiusa sa pagmaya, ug paghalad og sakramento ngadto sa Labing Halangdon."},{"verse":5,"text":"Ug unya mobalik kamo aron sa pagpamatuod, oo, gani dungan ang tanan, o magtinagurha, ingon nga maayo alang kaninyo, dili igsapayan ngari kanako; pagmatinud-anon lamang, ug ipahayag ang maayong mga balita ngadto sa lumulupyo sa yuta, o taliwala sa kongregasyon sa mga daotan."},{"verse":6,"text":"Tan-awa, ako, ang Ginoo, mihiusa sa pagdala kaninyo aron ang saad matuman, nga ang matinud-anon taliwala kaninyo mapanalipdan ug maghiusa sa pagmaya sa yuta sa Missouri. Ako, ang Ginoo, nagsaad ngadto sa matinud-anon ug dili mamakak."},{"verse":7,"text":"Ako, ang Ginoo, andam, kon aduna kaninyo ang magtinguha sa pagsakay sa mga kabayo, o sa mga asno, o sa mga karwahe, siya makadawat niini nga panalangin, kon modawat siya niini gikan sa kamot sa Ginoo, uban sa mapasalamaton nga kasingkasing diha sa tanang butang."},{"verse":8,"text":"Kini nga mga butang magpabilin nga inyong buhaton sumala sa paghukom ug sa mga pagmando sa Espiritu."},{"verse":9,"text":"Tan-awa, ang gingharian inyong mapanag-iya. Ug tan-awa, ug tan-awa, ako magauban kanunay sa mga matinud-anon. Ug mao gayod kana. Amen."}]},{"chapter":63,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga katawhan, ug ablihi ang inyong mga kasingkasing ug pamati kamo nga anaa sa layo; ug paminaw, kamo nga mga nagtawag sa inyong kaugalingon nga katawhan sa Ginoo, ug paminaw sa pulong sa Ginoo ug sa iyang kabubut-on mahitungod kaninyo."},{"verse":2,"text":"Oo, sa pagkatinuod, mosulti ko, paminaw sa pulong niya kansang kasuko napukaw batok sa daotan ug sa mga masupilon;"},{"verse":3,"text":"Kinsa magbuot sa pagkuha kon kinsa ang iyang kuhaon, ug mopanalipod sa kinabuhi niadto nga iyang panalipdan;"},{"verse":4,"text":"Kinsa motukod sumala sa iyang kaugalingon nga kabubut-on ug kahimuot; ug molaglag kon gusto niya, ug makahimo sa pagtambog sa kalag ngadto sa impyerno."},{"verse":5,"text":"Tan-awa, ako, ang Ginoo, mopahayag sa akong tingog, ug kini pagasundon."},{"verse":6,"text":"Mao nga, sa pagkatinuod ako moingon, himoa nga ang mga daotan magbantay, ug himoa nga ang mga masupilon mahadlok ug mangurog; ug himoa nga ang dili matuohon motak-om sa ilang mga ba-ba, kay ang adlaw sa kasuko moabot diha kanila ingon sa usa ka alimpulos, ug ang tanang tawo masayod nga ako ang Dios."},{"verse":7,"text":"Ug siya nga nangita og mga timailhan makakita og mga timailhan, apan dili ngadto sa kaluwasan."},{"verse":8,"text":"Sa pagkatinuod, sultihan ko kamo, aduna diha kaninyo ang nangita og mga timailhan, ug adunay ingon niana gani gikan pa sa sinugdanan;"},{"verse":9,"text":"Apan, tan-awa, ang pagtuo moabot dili pinaagi sa mga timailhan, apan ang mga timailhan mosunod niadtong motuo."},{"verse":10,"text":"Oo, ang mga timailhan moabot pinaagi sa pagtuo, dili pinaagi sa kabubut-on sa mga tawo, ni sa ilang pagbuot, apan pinaagi sa kabubut-on sa Dios."},{"verse":11,"text":"Oo, ang mga timailhan moabot pinaagi sa pagtuo, ngadto sa gamhanan nga mga buhat, kay kon walay pagtuo walay tawo nga makapahimuot sa Dios; ug kinsa kadtong kasuk-an sa Ginoo dili niya kahimut-an; mao nga, ngadto sa maong tawo walay ipakita nga mga timailhan, gawas lang sa kapungot ngadto sa ilang kahimaraotan."},{"verse":12,"text":"Mao nga, ako, ang Ginoo, wala mahimuot niadtong inyong kauban nga nangita og mga timailhan ug mga kahibulongan alang sa pagtuo, ug dili alang sa kaayohan sa mga tawo ngadto sa akong himaya."},{"verse":13,"text":"Bisan pa niana, mohatag ako og mga sugo, ug daghan ang wala mopadayon sa pagsunod sa akong mga sugo ug wala motuman niini."},{"verse":14,"text":"Kamo adunay kauban nga mga mananapaw ug mga babaye nga mananapaw; ang uban kanila mibiya gikan kaninyo, ug ang uban nagpabilin uban kaninyo nga human niini ipahibalo."},{"verse":15,"text":"Pabantaya ug pahinulsola sila sa labing madali, basin pa unya ang paghukom moabot kanila ingon sa usa ka lit-ag, ug ang ilang kabuang ikapadayag, ug ang ilang mga binuhatan magpabilin diha sa mga hunahuna sa katawhan."},{"verse":16,"text":"Ug sa pagkatinuod sultihan ko kamo, sama sa akong gisulti kaniadto, siya nga motan-aw sa usa ka babaye nga may sekswal nga tinguha kaniya, o kon adunay makapanapaw diha sa ilang mga kasingkasing, sila dili makaangkon sa Espiritu, apan naglimod sa pagtuo ug mahadlok."},{"verse":17,"text":"Mao nga, ako, ang Ginoo, miingon nga ang mahadlokon, ug ang dili matuohon, ug ang tanan nga bakakon, ug kadtong nahigugma ug naghimo og usa ka bakak, ug ang nagbaligya sa dungog, ug ang barangan, adunay ilang bahin diha nianang linaw nga nagdilaab nga kalayo ug asupre, nga mao ang ikaduha nga kamatayon."},{"verse":18,"text":"Sa pagkatinuod moingon ako, nga sila walay bahin diha sa unang pagkabanhaw."},{"verse":19,"text":"Ug karon tan-awa, ako, ang Ginoo, mosulti kaninyo nga kamo dili mahatagan og kaangayan, tungod kay kining mga butanga anaa diha kaninyo."},{"verse":20,"text":"Bisan pa niana, siya nga molahutay pinaagi sa pagtuo ug mobuhat sa akong kabubut-on, ang mao makabuntog, ug makadawat og kabilin dinhi sa yuta kon moabot na ang adlaw sa transpigurasyon;"},{"verse":21,"text":"Sa panahon nga ang yuta mahimaya, gani sumala sa sundanan nga gipakita sa akong apostoles didto sa bukid; diin niana nga asoy ang kahingpitan wala pa ninyo madawat."},{"verse":22,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, nga sama sa akong gisulti nga ipahibalo nako ang akong kabubut-on nganha kaninyo, tan-awa ako mopahibalo niini nganha kaninyo, dili pinaagi sa sugo, kay adunay daghan nga wala motuman sa akong mga sugo."},{"verse":23,"text":"Apan siya nga nagtuman sa akong mga sugo ihatag nako ang mga misteryo sa akong gingharian, ug ang mao maanaa kaniya ang usa ka atabay sa buhi nga tubig, nga magtubod ngadto sa walay kataposan nga kinabuhi."},{"verse":24,"text":"Ug karon, tan-awa, kini mao ang kabubut-on sa Ginoo nga inyong Dios kabahin sa iyang mga santos, nga kinahanglan silang maghiusa sa pagpundok sa ilang mga kaugalingon didto sa yuta sa Zion, dili magdali, aron malikayan ang kalibog, nga magdala og mga kasakit."},{"verse":25,"text":"Tan-awa, ang yuta sa Zion—ako, ang Ginoo, mokupot niini sa akong kaugalingon nga mga kamot;"},{"verse":26,"text":"Bisan pa niana, ako, ang Ginoo, mohatag ngadto ni Cesar sa mga butang nga iya ni Cesar."},{"verse":27,"text":"Mao nga, ako ang Ginoo gusto nga inyong paliton ang mga yuta, aron kamo mahimong bililhon sa kalibotan, aron kamo adunay katungod nga ilhon sa kalibotan, aron dili sila mahagit ngadto sa kasuko."},{"verse":28,"text":"Kay si Satanas miimpluwensya niini diha sa ilang mga kasingkasing sa pagkasuko batok kaninyo, ug sa pagpaagas sa dugo."},{"verse":29,"text":"Mao nga, ang yuta sa Zion dili mapanag-iya gawas lang pinaagi sa pagpalit o pinaagi sa dugo, kondili walay kabilin alang kaninyo."},{"verse":30,"text":"Ug kon mapalit, tan-awa kamo bulahan;"},{"verse":31,"text":"Ug kon pinaagi sa dugo, kay kamo gidid-an sa pagpaagas og dugo, tan-awa, ang inyong mga kaaway anaa diha kaninyo, ug kamo kastigohon gikan sa usa ka siyudad ngadto sa laing siyudad, ug gikan sa usa ka sinagoga ngadto sa laing sinagoga, ug pipila lamang ang mahibilin sa pagdawat sa kabilin."},{"verse":32,"text":"Ako, ang Ginoo, nasuko sa mga daotan; akong gipugngan ang akong Espiritu gikan sa mga lumulupyo sa yuta."},{"verse":33,"text":"Ako nakapanumpa tungod sa akong kasuko, ug nagtakda og mga gubat sa ibabaw sa yuta, ug ang daotan mopatay sa daotan, ug ang kahadlok moabot sa matag tawo;"},{"verse":34,"text":"Ug ang mga santos usab maglisod sa pag-ikyas; bisan pa niana, ako, ang Ginoo, magauban kanila, ug manaog sa langit gikan sa atubangan sa akong Amahan ug molaglag sa mga daotan uban sa dili mapalong nga kalayo."},{"verse":35,"text":"Ug tan-awa, kini wala pa sa karon, apan sa dili madugay."},{"verse":36,"text":"Mao nga, kay nakita nga ako, ang Ginoo, mitakda niining tanan nga butang sa ibabaw sa yuta, buot ako nga ang akong mga santos magpundok diha sa yuta sa Zion;"},{"verse":37,"text":"Ug nga ang matag tawo kinahangan nga magmatarong sa iyang mga kamot ug magmatinud-anon sa iyang mga bat-ang, ug mopataas sa tingog sa pagpasidaan sa mga lumulupyo sa yuta; ug mopahayag pinaagi sa pulong ug pinaagi sa pagpanaw nga ang pagkapukan moabot diha sa mga daotan."},{"verse":38,"text":"Mao nga, ipahan-ay sa akong mga disipulo sa Kirtland ang ilang temporal nga mga kabalaka, kinsa mopuyo niini nga umahan."},{"verse":39,"text":"Ipabaligya sa akong sulugoon nga si Titus Billings ang yuta, nga mao ang nag-amuma niini, aron maandam siya sa umaabot nga tingpamulak sa paghimo sa iyang panaw ngadto sa yuta sa Zion, kauban niadtong mga nagpuyo niana nga yuta, gawas niadtong akong giingon nga magpabilin, sa dili gayod paglakaw hangtod nga ako mosugo kanila."},{"verse":40,"text":"Ug ipadala ang tanang kwarta nga matigom, dili igsapayan kanako kon gamay o daghan, ngadto sa yuta sa Zion, ngadto kanila nga akong gipili nga modawat."},{"verse":41,"text":"Tan-awa, ako, ang Ginoo, mohatag og gahom ngadto sa akong sulugoon nga si Joseph Smith, Jun., nga siya makahimo sa pag-ila pinaagi sa Espiritu niadtong moadto sa yuta sa Zion, ug niadtong akong mga disipulo kinsa magpabilin."},{"verse":42,"text":"Ipapadayon sa akong sulugoon nga si Newel K. Whitney ang iyang tindahan, o sa lain nga mga pulong, ang tindahan, sa mubo pang panahon."},{"verse":43,"text":"Bisan pa niana, ipahatag niya ang tanang kwarta nga iyang mahatag, nga ipadala ngadto sa yuta sa Zion."},{"verse":44,"text":"Tan-awa, kining mga butanga anaa sa iyang kaugalingong mga kamot, ipahimo niya pinaagi sa kaalam."},{"verse":45,"text":"Sa pagkatinuod ako moingon, i-orden siya nga usa ka tinugyanan ngadto sa mga disipulo nga magpabilin, ug i-orden siya ngadto niini nga gahom;"},{"verse":46,"text":"Ug karon bisitaha dayon ang mga simbahan, mopasabot niining mga butanga ngadto kanila, uban sa akong sulugoon nga si Oliver Cowdery. Tan-awa, mao kini ang akong kabubut-on, mangita og mga kwarta bisan sumala sa akong gimando."},{"verse":47,"text":"Siya nga matinud-anon ug molahutay makabuntog sa kalibotan."},{"verse":48,"text":"Siya nga nagpadala og mga bahandi sa yuta sa Zion makadawat og kabilin niini nga kalibotan, ug ang iyang mga binuhatan mosunod kaniya, ug usab usa ka ganti sa kalibotan nga moabot."},{"verse":49,"text":"Oo, ug bulahan ang mga patay nga namatay diha sa Ginoo, gikan karon, kon ang Ginoo moabot, ug ang daan nga mga butang molabay, ug ang tanang butang mahimong bag-o, sila mobangon gikan sa mga patay ug dili na mamatay pag-usab, ug makadawat og kabilin sa atubangan sa Ginoo, sa balaan nga siyudad."},{"verse":50,"text":"Ug siya nga buhi kon ang Ginoo moabot, ug nagbaton og pagtuo, bulahan siya; bisan pa niana, gikatakda ngadto kaniya nga mamatay sa kasagaran nga pangedaron sa tawo."},{"verse":51,"text":"Mao nga, ang mga bata kinahanglan nga motubo hangtod nga matigulang sila; ang tigulang nga mga tawo mamatay; apan dili sila matulog diha sa abog, apan sila mausab sa usa ka pagpamilok sa mata."},{"verse":52,"text":"Mao nga, tungod niini nga hinungdan nagsangyaw ang mga apostol ngadto sa kalibotan sa pagkabanhaw sa mga patay."},{"verse":53,"text":"Kining mga butanga mao ang mga butang nga kinahanglan inyong pangitaon; ug, sa pagpamulong subay sa paagi sa Ginoo, sila karon hapit na moabot, ug sa panahon nga moabot, gani sa adlaw sa pag-anhi sa Anak sa Tawo."},{"verse":54,"text":"Ug hangtod nianang taknaa adunay dili maalamon nga mga birhen taliwala sa maalamon; ug nianang taknaa moabot ang tibuok nga panagbulag sa mga matarong ug sa mga daotan; ug nianang adlawa akong ipadala ang akong mga anghel sa pagbulag sa mga daotan ug pagtambog kanila ngadto sa dili mapalong nga kalayo."},{"verse":55,"text":"Ug karon tan-awa, sa pagkatinuod sultihan ko kamo, Ako, ang Ginoo, wala mahimuot sa akong sulugoon nga si Sidney Rigdon; iyang gihimaya ang iyang kaugalingon diha sa iyang kasingkasing, ug dili modawat og tambag, apan nakapaguol sa Espiritu;"},{"verse":56,"text":"Mao nga, ang iyang sinulat dili madawat sa Ginoo, ug kinahanglan siya nga mobuhat og lain; ug kon ang Ginoo dili modawat niini, tan-awa siya dili na mobarog sa katungdanan nga akong gitugyan kaniya."},{"verse":57,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, nga kadtong nagtinguha diha sa ilang kasingkasing, uban sa kaaghop, sa pagpasidaan sa mga makasasala sa paghinulsol, himoa nga sila i-orden diha niini nga gahom."},{"verse":58,"text":"Kay mao kini ang adlaw sa pagpasidaan, ug dili usa ka adlaw sa daghang pulong. Kay ako, ang Ginoo, dili matamay sa kataposang mga adlaw."},{"verse":59,"text":"Tan-awa, gikan ako sa kahitas-an, ug ang akong gahom anaa sa ubos. Ako ang gamhanan sa tanan, ug diha sa tanan, ug ngadto sa tanan, ug magasiksik sa tanang butang, ug ang adlaw moabot nga ang tanang butang mapaubos sa akong pagdumala."},{"verse":60,"text":"Tan-awa, ako ang Alpha ug Omega, gani si Jesukristo."},{"verse":61,"text":"Mao nga, pasidan-i ang tanang tawo giunsa nila paggamit ang akong ngalan sa ilang mga ngabil—"},{"verse":62,"text":"Kay, tan-awa, sa pagkatinuod ako moingon, nga adunay daghan diha kinsa ubos niini nga panghimaraot, kinsa naggamit sa ngalan sa Ginoo, ug migamit niini sa kawang, nga walay katungod."},{"verse":63,"text":"Mao nga, pahinulsola ang simbahan sa ilang mga sala, ug ako, ang Ginoo, moangkon kanila; kondili sila isalikway."},{"verse":64,"text":"Hinumdomi nga kana nga moabot gikan sa kahitas-an sagrado, ug kinahanglan gayod nga ipamulong uban sa pag-amping, ug pagtugot sa Espiritu; ug diha niini walay panghimaraot, ug kamo makadawat sa Espiritu pinaagi sa pag-ampo; mao nga, kon wala kini, magpabilin ang panghimaraot."},{"verse":65,"text":"Himoa nga ang akong mga sulugoon nga si Joseph Smith, Jun., ug Sidney Rigdon, makakita og panimalay, sama sa gitudlo kanila nga mag-ampo pinaagi sa Espiritu."},{"verse":66,"text":"Kining mga butanga nagpabilin nga mabuntog pinaagi sa pagpailob, aron makadawat sila og labaw pa ug mahangtorong kabuhong sa himaya, kondili, makadawat sila og mas labi pa nga panghimaraot. Amen."}]},{"chapter":64,"verses":[{"verse":1,"text":"Tan-awa, sa ingon niana misulti ang Ginoo nga inyong Dios nganha kaninyo, O kamo nga mga elder sa akong simbahan, patalinghogi ug paminawa ninyo, ug dawata ang akong kabubut-on mahitungod kaninyo."},{"verse":2,"text":"Kay sa pagkatinuod sultihan ko kamo, buot nako nga inyong buntogon ang kalibotan; mao nga ako adunay kaluoy kaninyo."},{"verse":3,"text":"Adunay inyong mga kauban nga nakasala; apan sa pagkatinuod mosulti ko nga, sa makausa, alang sa akong kaugalingon nga himaya, ug alang sa kaluwasan sa mga kalag, gipasaylo na nako ang inyong mga sala."},{"verse":4,"text":"Magmaluluy-on ako nganha kaninyo, kay akong gihatag kaninyo ang gingharian."},{"verse":5,"text":"Ug ang mga yawe sa mga misteryo sa gingharian dili pagakuhaon gikan sa akong sulugoon nga si Joseph Smith, Jun., pinaagi sa mga paagi nga akong gitudlo, samtang siya buhi, kon ugaling sundon niya ang akong mga ordinansa."},{"verse":6,"text":"Adunay mga tawo nga nangita og sayop batok kaniya nga walay hinungdan;"},{"verse":7,"text":"Bisan pa niana, siya nakasala; apan sa pagkatinuod sultihan ko kamo, ako, ang Ginoo, mopasaylo sa mga sala niadtong mokompisal sa ilang mga sala sa akong atubangan ug mangayo og pasaylo, sa sala nga wala magdala og silot nga espirituhanong kamatayon."},{"verse":8,"text":"Ang akong mga disipulo, sa karaang mga adlaw, nangita og higayon batok sa usag usa ug dili mopasaylo sa usag usa diha sa ilang mga kasingkasing; ug tungod niini nga kadaotan gisakit sila ug gipanton sa hilabihan."},{"verse":9,"text":"Mao nga, sultihan ko kamo, nga kinahanglan kamong mopasaylo sa usag usa; kay siya nga dili mopasaylo sa iyang igsoon ang iyang mga kalapasan segurado nga panghimaraoton sa atubangan sa Ginoo; kay magpabilin diha kaniya ang mas dakong sala."},{"verse":10,"text":"Ako, ang Ginoo, mopasaylo kaniya nga akong pasayloon, apan alang kaninyo kinahanglan nga mopasaylo sa tanang tawo."},{"verse":11,"text":"Ug angay ninyong isulti sa inyong mga kasingkasing—tugoti nga ang Dios mohukom tali kanako ug kaninyo, ug moganti kaninyo sumala sa inyong mga binuhatan."},{"verse":12,"text":"Ug siya nga dili maghinulsol sa iyang mga sala, ug dili mokompisal niini, dad-on ninyo sa atubangan sa simbahan, ug, buhaton ngadto kaniya sumala sa gipamulong sa kasulatan kaninyo, pinaagi sa sugo o pinaagi sa pagpadayag."},{"verse":13,"text":"Ug buhaton ninyo kini aron ang Dios pagahimayaon—dili tungod kay kamo wala mopasaylo, nga walay kaluoy, apan aron kamo mahatagan og kaangayan sa mga mata sa balaod, aron kamo dili makapasilo kaniya kinsa mao ang inyong magbabalaod—"},{"verse":14,"text":"Sa pagkatinuod mosulti ko nga, tungod niini nga hinungdan buhaton ninyo kining mga butanga."},{"verse":15,"text":"Tan-awa, ako, ang Ginoo, nasuko sa akong sulugoon nga si Ezra Booth, ug usab sa akong sulugoon nga si Isaac Morley, kay wala sila motuman sa akong balaod, ni sa sugo;"},{"verse":16,"text":"Nagtinguha sila og daotan sa ilang mga kasingkasing, ug ako, ang Ginoo, mipugong sa akong Espiritu. Gihukman nila nga daotan ang butang nga dili daotan; bisan pa niana gipasaylo nako ang akong sulugoon nga si Isaac Morley."},{"verse":17,"text":"Ug usab ang akong sulugoon nga si Edward Partridge, tan-awa, siya nakasala, ug si Satanas nagtinguha sa paglaglag sa iyang kalag; apan sa diha nga kining mga butanga gipahibalo ngadto kanila, ug gihinulsolan nila ang daotan, sila pasayloon."},{"verse":18,"text":"Ug karon, sa pagkatinuod mosulti ko nga angay ngari kanako nga ang akong sulugoon nga si Sidney Gilbert, human sa pipila ka semana, mobalik sa iyang buluhaton, ug ngadto sa iyang dapit sa yuta sa Zion;"},{"verse":19,"text":"Ug kanang iyang nakita ug nadungog mahibaloan sa akong mga disipulo, aron sila dili mag-antos. Ug tungod niini nga hinungdan ako nakapamulong niining mga butanga."},{"verse":20,"text":"Ug usab, sultihan ko kamo, nga ang akong sulugoon nga si Isaac Morley dili mahimong tentalon labaw nianang mahimo niyang antoson, ug motambag sa sayop nga paagi nga makadaot kaninyo, mihatag ako og sugo nga kinahanglang ibaligya ang iyang umahan."},{"verse":21,"text":"Dili ko motugot nga ibaligya ni Frederick G. Williams ang iyang umahan, kay ako, ang Ginoo, gusto nga magbaton og lig-on nga kadangpan sa yuta sa Kirtland, sulod sa lima ka tuig, diin dili nako buntogon ang daotan, aron akong maluwas ang uban."},{"verse":22,"text":"Ug human nianang adlawa, ako, ang Ginoo, dili mobasol ni bisan kinsa nga adunay bukas nga kasingkasing ngadto sa yuta sa Zion; kay ako, ang Ginoo, nagkinahanglan sa mga kasingkasing sa katawhan."},{"verse":23,"text":"Tan-awa, kining adlawa gitawag og karon hangtod sa pag-anhi sa Anak sa Tawo, ug sa pagkatinuod kini mao ang adlaw sa pagsakripisyo, ug ang adlaw alang sa ikapulo sa akong katawhan; kay siya nga nagbayad og ikapulo dili masunog sa iyang pag-anhi."},{"verse":24,"text":"Kay human niining adlawa moabot ang pagsunog—kini gipahayag subay sa pamaagi sa Ginoo—kay sa pagkatinuod mosulti ko nga, ugma ang tanang mapagarbohon ug sila nga nagbuhat og daotan mahisama sa dagami; ug ako mosunog kanila, kay ako ang Ginoo sa mga Panon; ug dili ako moluwas ni bisan kinsa nga magpabilin diha sa Babilonia."},{"verse":25,"text":"Mao nga, kon kamo motuo kanako, kamo maghago samtang kini gitawag karon."},{"verse":26,"text":"Ug dili angay sa akong mga sulugoon, si Newel K. Whitney ug si Sidney Gilbert, nga mobaligya sa ilang tindahan ug sa ilang mga kabtangan dinhi; kay dili kini maalamon hangtod ang nahibilin sa simbahan, nga nagpabilin niining dapita, moadto sa yuta sa Zion."},{"verse":27,"text":"Tan-awa, gipahayag kini sa akong mga balaod, o gidili, nga mangutang sa inyong mga kaaway;"},{"verse":28,"text":"Apan tan-awa, wala isulti nga ang Ginoo dili mokuha kon siya gusto, ug mobayad sa ingon og makaayo kaniya."},{"verse":29,"text":"Mao nga, tungod kay kamo mga tinugyanan, kamo anaa sa buluhaton sa Ginoo; ug bisan unsa ang inyong buhaton sumala sa kabubut-on sa Ginoo mao ang buluhaton sa Ginoo."},{"verse":30,"text":"Ug siya nagpahimutang kaninyo sa pag-andam alang sa iyang mga santos niining kataposang mga adlaw, aron makaangkon sila og kabilin sa yuta sa Zion."},{"verse":31,"text":"Ug tan-awa, ako, ang Ginoo, nagpahayag kaninyo, ug ang akong mga pulong tinuod ug dili gayod makawang, aron sila makaangkon niini."},{"verse":32,"text":"Apan ang tanang butang kinahanglan gayod nga mahitabo sa angay nga panahon."},{"verse":33,"text":"Mao nga, ayaw kakapoy sa maayong buhat, kay kamo nagpahimutang sa pundasyon sa usa ka mahinungdanon nga buhat. Ug gikan sa gagmay nga mga butang magagikan ang dagko."},{"verse":34,"text":"Tan-awa, ang Ginoo nagkinahanglan sa kasingkasing ug sa usa ka andam nga hunahuna; ug ang andam ug ang masulundon mokaon sa maayong mga butang sa yuta sa Zion niining kataposang mga adlaw."},{"verse":35,"text":"Ug ang mga masupilom isalikway gikan sa yuta sa Zion, ug ipahilayo, ug dili na makapanunod sa yuta."},{"verse":36,"text":"Kay, sa pagkatinuod mosulti ko nga ang mga masupilon dili kaliwat ni Ephraim, mao nga sila pagahinginlan."},{"verse":37,"text":"Tan-awa, ako, ang Ginoo, mihimo sa akong simbahan niining kataposang mga adlaw sama sa usa ka maghuhukom nga naglingkod ibabaw sa usa ka bungtod, o sa taas nga dapit, sa paghukom sa mga nasod."},{"verse":38,"text":"Kay mahitabo nga ang mga lumulupyo sa Zion mohukom sa tanang butang kalabot sa Zion."},{"verse":39,"text":"Ug ang mga bakakon ug ang mga tigpakaaron-ingnon ilang pagailhon, ug sila kinsa dili apostoles ug mga propeta mailhan."},{"verse":40,"text":"Ug bisan ang bishop, kinsa usa ka maghuhukom, ug ang iyang mga magtatambag, kon dili sila matinud-anon sa ilang pagkatinugyanan, pagahukman, ug ang uban ipuli diha sa ilang mga dapit."},{"verse":41,"text":"Kay, tan-awa, sultihan ko kamo nga ang Zion molambo, ug ang himaya sa Ginoo anaa kaniya;"},{"verse":42,"text":"Ug siya mahimo nga bandila ngadto sa katawhan, ug adunay moduol kaniya gikan sa matag nasod ubos sa langit."},{"verse":43,"text":"Ug ang adlaw moabot nga ang mga nasod sa yuta mangurog tungod kaniya, ug mahadlok tungod sa iyang makalilisang nga katawhan. Ang Ginoo nakapamulong niini. Amen."}]},{"chapter":65,"verses":[{"verse":1,"text":"Patalinghog, ug tan-awa, ang tingog sama sa usa nga gipadala gikan sa kahitas-an, kinsa makagagahom ug gamhanan, kansang paglakaw ngadto sa mga kinatumyan sa yuta, oo, kansang tingog alang sa mga tawo—Andama ninyo ang agianan sa Ginoo, himoa nga ang iyang mga dalan tul-id."},{"verse":2,"text":"Ang mga yawe sa gingharian sa Dios gitugyan ngadto sa tawo sa yuta, ug gikan dinhi ang ebanghelyo mokaylap ngadto sa mga kinatumyan sa yuta, sama sa bato nga gipikas mokaylap gikan sa bukid nga walay gigamit nga mga kamot, hangtod nga mopuno kini sa tibuok yuta."},{"verse":3,"text":"Oo, usa ka tingog nga nagsinggit—Andama ninyo ang agianan sa Ginoo, andama ninyo ang panihapon sa Kordero, pangandam alang sa Pamanhonon."},{"verse":4,"text":"Pag-ampo ngadto sa Ginoo, tawaga ang iyang balaan nga ngalan, ipahibalo ang iyang kahibulongang mga buhat ngadto sa katawhan."},{"verse":5,"text":"Tawga ang Ginoo, aron ang iyang gingharian mokatap sa yuta, nga ang mga lumulupyo modawat niini, ug maandam alang sa mga adlaw nga moabot, diin ang Anak sa Tawo manaog gikan sa langit, mapalibotan sa kahayag sa iyang himaya, aron sa pag-ipon sa gingharian sa Dios nga gipahimutang sa ibabaw sa yuta."},{"verse":6,"text":"Mao nga, hinaot nga ang gingharian sa Dios mokatap, nga ang gingharian sa langit moabot, nga ikaw, O Dios, mahimaya sa langit ingon man usab sa yuta, nga ang imong mga kaaway mabuntog; kay imo ang dungog, gahom ug himaya, hangtod sa kahangtoran. Amen."}]},{"chapter":66,"verses":[{"verse":1,"text":"Tan-awa, sa ingon niini miingon ang Ginoo ngadto sa akong sulugoon nga si William E. McLellin—Bulahan ikaw, kon ssugaling biyaan nimo ang imong mga pagkadaotan, ug nakadawat sa akong mga kamatuoran, miingon ang Ginoo nga imong Manunubos, ang Manluluwas sa kalibotan, gani kutob sa motuo sa akong ngalan."},{"verse":2,"text":"Sa pagkatinuod sultihan ko ikaw, bulahan ka nga midawat sa akong walay kataposan nga pakigsaad, gani sa kahingpitan sa akong ebanghelyo, nga gipadala ngadto sa katawhan, aron makaangkon sila og kinabuhi ug mahimong mga mag-aambit sa mga himaya nga ipadayag sa kataposang mga adlaw, sumala sa nahisulat pinaagi sa mga propeta ug sa apostoles sa karaang mga adlaw."},{"verse":3,"text":"Sa pagkatinuod sultihan ko ikaw, akong sulugoon nga William, nga ikaw limpyo, apan dili sa tanan; busa, paghinulsol, niadtong mga butang nga wala makapahimuot sa akong panan-aw, miingon ang Ginoo, kay ang Ginoo mopakita niini nganha kanimo."},{"verse":4,"text":"Ug karon, sa pagkatinuod, ako, ang Ginoo, mopakita nganha kanimo unsa ang akong tinguha kabahin kanimo, o unsa ang akong kabubut-on kabahin kanimo."},{"verse":5,"text":"Tan-awa, sa pagkatinuod sultihan ko ikaw, nga kini mao ang akong kabubut-on nga ikaw kinahanglan nga mopahayag sa akong ebanghelyo gikan sa usa ka yuta ngadto sa laing yuta, ug gikan sa usa ka siyudad ngadto sa laing siyudad, oo, niadtong palibot nga mga rehiyon diin wala pa kini ikapahayag."},{"verse":6,"text":"Ayaw dugaya ang imong mga adlaw niining dapita; ug ayaw una pag-adto sa yuta sa Zion; apan kon ugaling ikaw makapadala, pagpadala; kondili, ayaw hunahunaa ang imong kabtangan."},{"verse":7,"text":"Adtoa ang mga silangan nga bahin sa yuta, magpamatuod sa matag dapit, ngadto sa matag tawo ug sa ilang mga sinagoga, mangatarongan uban sa katawhan."},{"verse":8,"text":"Ang akong sulugoon nga si Samuel H. Smith imong iuban, ug ayaw siya biya-i, ug hatagi siya sa imong mga pahimangno; ug siya nga matinud-anon pagahimoon nga lig-on sa matag dapit; ug ako, ang Ginoo, magauban kaninyo."},{"verse":9,"text":"Ipandong ang inyong mga kamot sa nagmasakiton, ug mamaayo sila. Ayaw pagpauli hangtod ako, ang Ginoo, mosugo kaninyo. Pagmapailobon sa kasakitan. Pangayo, ug kamo makadawat; panuktok, ug kini pagaablihan nganha kaninyo."},{"verse":10,"text":"Ayaw pagtinguha nga mahasol. Biya-i ang tanan nga dili matarong. Ayaw pagpanapaw—usa ka tentasyon nga nakasamok kanimo."},{"verse":11,"text":"Sunda kining mga panultihon, kay kini tinuod ug kasaligan; ug ikaw kinahanglan nga mopalambo sa imong buhatan, ug moawhag sa daghang katawhan ngadto sa Zion pinaagi sa mga awit sa walay kataposang kamaya sa ilang ulohan."},{"verse":12,"text":"Padayon diha niini nga mga butang gani hangtod sa kataposan, ug makaangkon ikaw og korona sa kinabuhing dayon sa tuong kamot sa akong Amahan, kinsa puno sa grasya ug kamatuoran."},{"verse":13,"text":"Sa pagkatinuod, mao kini ang gisulti sa Ginoo nga imong Dios, imong Manunubos, gani si Jesukristo. Amen."}]},{"chapter":67,"verses":[{"verse":1,"text":"Tan-awa ug patalinghog, O kamo nga mga elder sa akong simbahan, nga nagpundok sa inyong mga kaugalingon, kansang mga pag-ampo akong nadungog, ug kansang mga kasingkasing ako nasayod, ug kansang mga tinguha miabot sa akong atubangan."},{"verse":2,"text":"Tan-awa ug sud-onga, ang akong mga mata anaa diha kaninyo, ug ang kalangitan ug ang yuta anaa sa akong mga kamot ug ang mga katigayonan sa kahangtoran akoa aron ihatag."},{"verse":3,"text":"Nagtinguha kamo nga motuo nga kamo makadawat og panalangin nga gitanyag kaninyo; apan tan-awa, sa pagkatinuod sultihan ko kamo nga adunay mga kahadlok sa inyong mga kasingkasing, ug sa pagkatinuod mao kini ang hinungdan nga kamo wala makadawat."},{"verse":4,"text":"Ug karon ako, ang Ginoo, mohatag kaninyo og usa ka pagpamatuod sa kamatuoran niini nga mga sugo nga anaa sa inyong atubangan."},{"verse":5,"text":"Ang inyong mga mata nagtan-aw sa akong sulugoon nga si Joseph Smith, Jun., ug sa iyang pinulongan nga inyong nahibaloan, ug sa iyang mga pagkadili hingpit nga inyong nahibaloan; ug nagtinguha kamo sa inyong mga kasingkasing og kahibalo nga kamo makapahayag og labaw sa iyang pinulongan; nasayod usab kamo niini."},{"verse":6,"text":"Karon, pangitaa ninyo gikan sa Basahon sa mga Sugo, bisan ang labing ubos niini, ug siya nga labing maalamon diha kaninyo ang pilia;"},{"verse":7,"text":"O, kon adunay bisan kinsa kaninyo ang makahimo og usa nga sama niini, nan makiangayon ang inyong pag-ingon nga kamo wala masayod nga kini tinuod;"},{"verse":8,"text":"Apan kon dili kamo makahimo og usa nga sama niini, ubos kamo sa panghimaraot kon dili kamo mopamatuod nga kini tinuod."},{"verse":9,"text":"Kay nasayod kamo nga walay dili matarong diha niini, ug kana nga matarong naggikan sa kahitas-an, gikan sa Amahan sa mga kahayag."},{"verse":10,"text":"Ug usab, sa pagkatinuod sultihan ko kamo nga inyo kini nga pribilihiyo, ug usa ka saad ang akong ihatag kaninyo nga giorden na ngadto niini nga pangalagad, nga kon ugaling inyong isalikway ang mga kasina ug mga kahadlok gikan sa inyong kaugalingon, ug magpaubos kamo sa akong atubangan, kay kamo dili pa kaayo mapainubsanon, ang tabil pagagision ug kamo makakita kanako ug makaila nga ako ania—dili sa kalibotanon ni kinaiyanhon nga hunahuna, apan sa espirituwal."},{"verse":11,"text":"Kay walay tawo nga nakakita sa Dios sa bisan unsa nga panahon dinhi sa unod, gawas kon anaa sa impluwensya sa Espiritu sa Dios."},{"verse":12,"text":"Ni walay bisan kinsa nga kinaiyanhon nga tawo ang makaharong sa atubangan sa Dios, ni sa kalibotanon nga hunahuna."},{"verse":13,"text":"Dili kamo makaharong sa atubangan sa Dios karon, ni sa pagpangalagad sa mga anghel; mao nga, padayon sa pagpailob hangtod nga kamo mahingpit."},{"verse":14,"text":"Ayaw usba ang inyong mga hunahuna; ug kon takos kamo, sa akong kaugalingong tukma nga panahon, makita ug masayran ninyo kana nga gitugyan kaninyo pinaagi sa mga kamot sa akong sulugoon nga si Joseph Smith, Jun. Amen."}]},{"chapter":68,"verses":[{"verse":1,"text":"Ang akong sulugoon, nga si Orson Hyde, gitawag pinaagi sa iyang ordinasyon sa pagsangyaw sa walay kataposan nga ebanghelyo, pinaagi sa Espiritu sa buhi nga Dios, gikan sa usa ka katawhan ngadto sa laing katawhan, ug gikan sa usa ka yuta ngadto sa laing yuta, diha sa mga kongregasyon sa mga daotan, sa ilang mga sinagoga, mangatarongan ug magpatin-aw sa tanang kasulatan ngadto kanila."},{"verse":2,"text":"Ug, tan-awa, ug sud-onga, mao kini ang sumbanan ngadto sa tanan niadtong gi-orden ngadto niini nga pagkapari, kansang misyon gipili kon asa sila magsangyaw—"},{"verse":3,"text":"Ug mao kini ang sumbanan ngadto kanila, nga ilang ipamulong kon gidasig sila sa Espiritu Santo."},{"verse":4,"text":"Ug bisan unsa ang ilang ipamulong kon gidasig sa Espiritu Santo mahimong kasulatan, mahimong kabubut-on sa Ginoo, mahimong hunahuna sa Ginoo, mahimong pulong sa Ginoo, mahimong tingog sa Ginoo, ug ang gahom sa Dios ngadto sa kaluwasan."},{"verse":5,"text":"Tan-awa, mao kini ang saad sa Ginoo nganha kaninyo, O kamo nga akong mga sulugoon."},{"verse":6,"text":"Mao nga, paglipay, ug ayaw kahadlok, kay ako ang Ginoo anaa uban kaninyo, ug mobarog uban kaninyo; ug kamo magpamatuod kanako, gani si Jesukristo, nga ako ang Anak sa buhi nga Dios, nga ako mao kaniadto, nga ako mao karon, ug nga ako mao ang moabot."},{"verse":7,"text":"Mao kini ang pulong sa Ginoo nganha kaninyo, akong sulugoon nga Orson Hyde, ug usab sa akong sulugoon nga Luke Johnson, ug ngadto sa akong sulugoon nga Lyman Johnson, ug ngadto sa akong sulugoon nga si William E. McLellin, ug ngadto sa tanang matinud-anon nga mga elder sa akong simbahan—"},{"verse":8,"text":"Panglakaw kamo sa tibuok kalibotan, isangyaw ang ebanghelyo ngadto sa matag nilalang, maglihok pinaagi sa awtoridad nga akong gihatag kaninyo, magbunyag pinaagi sa ngalan sa Amahan, ug sa Anak, ug sa Espiritu Santo."},{"verse":9,"text":"Ug siya nga motuo ug mabunyagan maluwas, ug siya nga dili motuo panghimaraoton."},{"verse":10,"text":"Ug siya nga motuo mapanalanginan sa mga timailhan nga mosunod, bisan sumala sa nahisulat."},{"verse":11,"text":"Ug kini ihatag kaninyo aron makahibalo sa mga timailhan sa mga panahon, ug sa mga timailhan sa pag-anhi sa Anak sa Tawo;"},{"verse":12,"text":"Ug kutob sa ipamatuod sa Amahan, nganha kaninyo ihatag ang gahom sa pagselyo kanila ngadto sa kinabuhing dayon. Amen."},{"verse":13,"text":"Ug karon, mahitungod sa mga butang nga idugang sa mga pakigsaad ug mga sugo, mao kini—"},{"verse":14,"text":"Adunay magpabilin human niini, sa tukma nga panahon sa Ginoo, nga ang ubang mga bishop sangonan og buluhaton sa simbahan, sa pagpangalagad bisan sumala sa nahauna;"},{"verse":15,"text":"Mao nga mahimo silang mga high priest nga mga takos, ug pilion sila sa Unang Kapangulohan sa Melchizedek nga Pagkapari, gawas kon tinuod silang mga kaliwat ni Aaron."},{"verse":16,"text":"Ug kon tinuod silang mga kaliwat ni Aaron sila adunay legal nga katungod sa bishopric, kon mga unang natawo sila sa mga anak ni Aaron;"},{"verse":17,"text":"Kay ang unang natawo naghupot sa katungod sa kapangulohan niini nga pagkapari, ug ang mga yawe o sa awtoridad niini."},{"verse":18,"text":"Walay tawo nga adunay legal nga katungod niini nga buhatan, sa paghupot sa mga yawe niini nga pagkapari, gawas kon siya usa ka tinuod nga kaliwat ug ang unang natawo nga anak ni Aaron."},{"verse":19,"text":"Apan, isip usa ka high priest sa Melchizedek nga Pagkapari anaa ang awtoridad sa pagdumala sa tanang mas ubos nga mga buhatan aron mahimo siyang modumala sa buhatan sa bishop kon walay tinuod nga kaliwat ni Aaron nga makita, gawas kon gitawag siya ug gigahin ug gi-orden ngadto niini nga gahom, ubos sa mga kamot sa Unang Kapangulohan sa Melchizedek nga Pagkapari."},{"verse":20,"text":"Ug ang usa ka tinuod nga kaliwat ni Aaron, usab, kinahanglan nga tawagon niini nga Kapangulohan, ug makita nga takos, ug dinihogan, ug i-orden ubos sa mga kamot niini nga Kapangulohan, kondili sila walay legal nga awtoridad sa pagpahigayon sa ilang pagkapari."},{"verse":21,"text":"Apan, pinaagi sa gahom nga gitakda sa balaod mahitungod sa ilang katungod sa pagkapari nga gipasa gikan sa amahan ngadto sa anak nga lalaki, magtinguha sila sa ilang pagdihog sa bisan unsang panahon nga mapamatud-an nila ang ilang kaliwatan, o kon matino kini pinaagi sa pagpadayag gikan sa Ginoo ubos sa mga kamot sa gihisgotan sa ibabaw nga Kapangulohan."},{"verse":22,"text":"Ug usab, walay bishop o labaw nga pari ang igahin alang niini nga pangalagad ang pagahusayon o silotan alang sa bisan unsa nga krimen, gawas lang kon kini adto sa atubangan sa Unang Kapangulohan sa simbahan;"},{"verse":23,"text":"Ug kon ugaling makita siya nga sad-an sa atubangan niini nga Kapangulohan, pinaagi sa pagpamatuod nga dili ikapanghimakak, siya pagasilotan;"},{"verse":24,"text":"Ug kon maghinulsol siya mapasaylo siya sumala sa mga pakigsaad ug mga sugo sa simbahan."},{"verse":25,"text":"Ug usab, kon ugaling ang mga ginikanan adunay mga anak sa Zion, o sa bisan asa sa iyang mga stake nga natukod, nga wala magtudlo kanila sa pagsabot sa doktrina sa paghinulsol, pagtuo diha ni Kristo ang Anak sa buhi nga Dios, ug sa bunyag ug sa gasa sa Espiritu Santo pinaagi sa pagpandong sa mga kamot, kon nag-edad na og otso anyos, ang sala anaa sa mga ulo sa mga ginikanan."},{"verse":26,"text":"Kay mao kini ang balaod ngadto sa mga lumulupyo sa Zion, o sa bisan asa sa iyang mga stake nga natukod."},{"verse":27,"text":"Ug ang ilang mga anak pagabunyagan alang sa kapasayloan sa ilang mga sala kon nag-edad na og otso anyos, ug makadawat sa pagpandong sa mga kamot."},{"verse":28,"text":"Ug tudloan usab nila ang ilang mga anak sa pag-ampo, ug sa paglakaw nga matarong atubangan sa Ginoo."},{"verse":29,"text":"Ug ang mga lumulupyo sa Zion usab motahod sa adlaw nga Igpapahulay sa pagbalaan niini."},{"verse":30,"text":"Ug ang mga lumulupyo sa Zion usab mahinumdom sa ilang mga buluhaton, kon ugaling pilion sila alang sa buluhaton, sa tumang pagkamatinud-anon; kay ang tapolan hinumdoman sa atubangan sa Ginoo."},{"verse":31,"text":"Karon, ako, ang Ginoo, wala mahimuot sa mga lumulupyo sa Zion, kay adunay mga tapolan diha kanila; ug ang ilang mga anak usab nagtubo sa pagkadaotan; sila usab wala magtinguha nga ampingan ang mga katigayonan sa kahangtoran, apan ang ilang mga mata napuno sa kahakog."},{"verse":32,"text":"Kining mga butanga kinahanglan nga dili mao ang mahitabo, ug kinahanglan gayod nga hunongon diha kanila; mao nga, himoa nga ang akong sulugoon nga si Oliver Cowdery modala niini nga mga pulong ngadto sa yuta sa Zion."},{"verse":33,"text":"Ug usa ka sugo ang akong ihatag kanila—nga siya nga wala mohimo sa iyang mga pag-ampo sa atubangan sa Ginoo nianang panahona, himoa nga siya mahinumdoman sa atubangan sa maghuhukom sa akong katawhan."},{"verse":34,"text":"Kini nga mga pulong tinuod ug matinud-anon; mao nga, ayaw kini supaka, ni kuhaa gikan niini nga pulong."},{"verse":35,"text":"Tan-awa, ako ang Alpha ug Omega, ug ako moabot sa dili madugay. Amen."}]},{"chapter":69,"verses":[{"verse":1,"text":"Patalinghog kanako, miingon ang Ginoo nga imong Dios, alang sa kaayohan sa akong sulugoon nga si Oliver Cowdery. Dili angay ngari kanako nga siya saligan sa mga sugo ug sa mga kwarta nga iyang dad-on ngadto sa yuta sa Zion, gawas nga adunay usa nga mouban kaniya nga matinuoron ug matinud-anon."},{"verse":2,"text":"Mao nga, ako, ang Ginoo, nagtinguha nga ang akong sulugoon, nga si John Whitmer, mouban sa akong sulugoon nga si Oliver Cowdery;"},{"verse":3,"text":"Ug usab nga siya mopadayon sa pagsulat ug paghimo og kasaysayan sa tanang importante nga butang nga iyang mapanid-an ug masayran mahitungod sa akong simbahan;"},{"verse":4,"text":"Ug usab nga siya modawat og tambag ug tabang gikan sa akong sulugoon nga si Oliver Cowdery ug sa uban."},{"verse":5,"text":"Ug usab, ang akong mga sulugoon nga atua sa layo nga kayutaan kinahanglan mopadala sa mga pamahayag sa ilang mga pagkatinugyanan ngadto sa yuta sa Zion;"},{"verse":6,"text":"Kay ang yuta sa Zion mao ang mahimong sentro ug usa ka dapit sa pagdawat ug pagbuhat niining tanang butang."},{"verse":7,"text":"Bisan pa niana, himoa nga ang akong sulugoon nga si John Whitmer mobiyahe sa daghang higayon gikan sa usa ka dapit ngadto sa laing dapit, ug gikan sa usa ka simbahan ngadto sa laing simbahan, aron mas sayon siyang makaangkon og kahibalo—"},{"verse":8,"text":"Magsangyaw ug magpasabot, magsulat, magkopya, magpili, ug magbaton sa tanang butang nga alang sa kaayohan sa simbahan, ug alang sa nagtubo nga mga henerasyon nga motubo sa yuta sa Zion, sa pag-angkon niini gikan sa usa ka henerasyon ngadto sa laing henerasyon, hangtod sa kahangtoran. Amen."}]},{"chapter":70,"verses":[{"verse":1,"text":"Tan-awa, ug patalinghog, O kamong mga lumulupyo sa Zion, ug kamong tanan nga katawhan sa akong simbahan kinsa anaa sa layo, ug paminaw sa pulong sa Ginoo nga akong ihatag sa akong sulugoon nga si Joseph Smith, Jun., ug usab sa akong sulugoon nga si Martin Harris, ug usab sa akong sulugoon nga si Oliver Cowdery, ug usab sa akong sulugoon nga si John Whitmer, ug usab sa akong sulugoon nga si Sidney Rigdon, ug usab sa akong sulugoon nga si William W. Phelps, isip sugo ngadto kanila."},{"verse":2,"text":"Kay ihatag nako ang sugo ngadto kanila; mao nga patalinghog ug paminaw, kay sa ingon niana miingon ang Ginoo ngadto kanila—"},{"verse":3,"text":"Ako, ang Ginoo, mitudlo kanila, ug mi-orden kanila nga mahimong mga tinugyanan sa mga pagpadayag ug sa mga sugo nga akong gihatag kanila, ug nga sa umaabot akong ihatag kanila;"},{"verse":4,"text":"Ug akong kinahanglanon gikan kanila ang asoy niini nga pagkatinugyanan sa adlaw sa paghukom."},{"verse":5,"text":"Mao nga, ako ang nagpili alang kanila, ug mao kini ang ilang buluhaton sa simbahan sa Dios, sa pagdumala niini ug sa mga butang nga kalabot sa mga pagpadayag, oo, sa mga kaayohan niana."},{"verse":6,"text":"Mao nga, usa ka sugo akong ihatag kanila, nga dili nila ihatag kini nga mga butang ngadto sa simbahan, ni sa kalibotan;"},{"verse":7,"text":"Bisan pa niana, kon ugaling nakadawat man sila og mas daghan kay sa ilang gikinahanglan, ihatag kini ngadto sa akong balay tipiganan;"},{"verse":8,"text":"Ug ang mga kaayohan ipahinungod ngadto sa mga lumulupyo sa Zion, ug ngadto sa ilang mga henerasyon, kon ugaling mahimo man silang mga manununod sumala sa mga balaod sa gingharian."},{"verse":9,"text":"Tan-awa, mao kini ang gikinahanglan sa Ginoo sa matag tawo sa iyang pagkatinugyanan, gani sama nga ako, ang Ginoo, mipili o sa pagkahuman niini mopili pa ni bisan kinsa."},{"verse":10,"text":"Ug tan-awa, walay tawo nga makalikay niini nga balaod nga sakop sa simbahan sa buhi nga Dios;"},{"verse":11,"text":"Oo, ni ang bishop, ni ang tinugyanan kinsa nagbantay sa balay tipiganan sa Ginoo, ni siya nga natudlo sa pagkatinugyanan sa temporal nga mga butang."},{"verse":12,"text":"Siya nga gipili sa pagpangalagad sa mga butang nga espirituwal, siya usab takos sa iyang suhol, sama niadtong gipili sa pagkatinugyanan aron mangalagad sa mga butang nga temporal;"},{"verse":13,"text":"Oo, gani mas buhong pa, nga ang maong kabuhong gipilo-pilo alang ngadto kanila pinaagi sa mga pagpakita sa Espiritu."},{"verse":14,"text":"Bisan pa niana, sa inyong mga butang nga temporal managsama ra kamo, ug buhata kini sa walay pagpanuko, kay kondili ang kabuhong sa mga pagpakita sa Espiritu dili mahatag."},{"verse":15,"text":"Karon, kini nga sugo akong ihatag sa akong mga sulugoon alang sa ilang kaayohan samtang sila magpabilin, alang sa pagpakita sa akong mga panalangin sa ilang mga ulo, ug alang sa ganti sa ilang kakugi ug alang sa ilang seguridad;"},{"verse":16,"text":"Alang sa pagkaon ug alang sa sinina; alang sa kabilin; alang sa mga balay ug alang sa mga yuta, sa bisan unsang mga sitwasyon nga ako, ang Ginoo, mobutang kanila, ug bisan asa nga ako, ang Ginoo, mopadala kanila."},{"verse":17,"text":"Kay nagmatinud-anon sila sa daghang butang, ug nakabuhat og maayo kon ugaling wala sila makasala."},{"verse":18,"text":"Tan-awa, ako, ang Ginoo, magmaluluy-on ug manalangin kanila, ug makasulod sila sa hingpit nga kalipay niining mga butanga. Ingon gayod niana. Amen."}]},{"chapter":71,"verses":[{"verse":1,"text":"Tan-awa, ingon niini ang giingon sa Ginoo kaninyo akong mga sulugoon Joseph Smith, Jun., ug Sidney Rigdon, nga sa pagkatinuod ang panahon miabot na nga gikinahanglan ug angay ngari kanako nga inyong ablihan ang inyong mga ba-ba sa pagpahayag sa akong ebanghelyo, sa mga butang sa gingharian, mopasabot sa mga misteryo niini gikan sa mga kasulatan, sumala niana nga bahin sa Espiritu ug gahom nga ihatag kaninyo, gani sumala sa akong kabubut-on."},{"verse":2,"text":"Sa pagkatinuod sultihan ko kamo, ipahayag ngadto sa kalibotan sa palibot nga mga rehiyon, ug sa simbahan usab, sulod sa usa ka panahon, gani hangtod nga kini ipahibalo kaninyo."},{"verse":3,"text":"Sa pagkatinuod usa kini ka misyon sulod sa usa ka panahon, nga akong ihatag kaninyo."},{"verse":4,"text":"Mao nga, trabaho kamo sa akong ubasan. Tawaga ang mga lumulupyo sa yuta, ug magpamatuod, ug andama ang agianan alang sa mga sugo ug sa mga pagpadayag nga moabot."},{"verse":5,"text":"Karon, tan-awa mao kini ang kaalam; kinsa kadtong mobasa, himoa nga siya makasabot ug modawat usab;"},{"verse":6,"text":"Kay ngadto kaniya nga nakadawat hatagan og mas labaw pa nga kabuhong, gani sa gahom."},{"verse":7,"text":"Mao nga, liboga ang inyong mga kaaway; dapita sila sa pagpakigkita kaninyo diha sa dayag ug sa pribado; ug kon ugaling kamo magmatinud-anon, ang ilang kaulaw dayag nga makita sa tanan."},{"verse":8,"text":"Mao nga, hagita sila sa pagdala sa ilang labing lig-on nga mga pangatarongan batok sa Ginoo."},{"verse":9,"text":"Sa pagkatinuod, ingon niini ang giingon sa Ginoo kaninyo—walay hinagiban nga gihimo nga molampos batok kaninyo;"},{"verse":10,"text":"Ug kon adunay tawo nga mosupak batok kaninyo mahingpit ang iyang kapildihan sa akong kaugalingong tukma nga panahon."},{"verse":11,"text":"Mao nga, tumana ang akong mga sugo; kini tinuod ug matinud-anon. Ingon gayod niana. Amen."}]},{"chapter":72,"verses":[{"verse":1,"text":"Patalinghog, ug paminaw sa tingog sa Ginoo, O kamo nga nagpundok sa inyong kaugalingon, nga mga high priest sa akong simbahan, ngadto kinsa ang gingharian ug gahom gihatag."},{"verse":2,"text":"Kay sa pagkatinuod sa ingon niana miingon ang Ginoo, angay ngari kanako nga adunay bishop nga pilion nganha kaninyo, o gikan kaninyo, diha sa simbahan niini nga bahin sa ubasan sa Ginoo."},{"verse":3,"text":"Ug sa pagkatinuod kabahin niining butanga maayo ang inyong gihimo nga paghukom, kay gikinahanglan sa Ginoo, sa kamot sa matag tinugyanan, ang paghatag og asoy sa iyang pagkatinugyanan, karon ug sa kahangtoran."},{"verse":4,"text":"Kay siya nga matinud-anon ug maalamon niana nga panahon pagaisipon nga takos sa pagpanunod sa mga mansyon nga giandam alang kaniya sa akong Amahan."},{"verse":5,"text":"Sa pagkatinuod sultihan ko kamo, ang mga elder sa simbahan niini nga bahin sa akong ubasan mohatag og asoy sa ilang pagkatinugyanan ngadto sa bishop, nga akong gipili niini nga bahin sa akong ubasan."},{"verse":6,"text":"Kining mga butanga kinahanglang irekord, aron ihatag ngadto sa bishop sa Zion."},{"verse":7,"text":"Ug ang katungdanan sa bishop mahibaloan pinaagi sa mga sugo nga gihatag na, ug sa tingog sa komperensiya."},{"verse":8,"text":"Ug karon, sa pagkatinuod sultihan ko ikaw, ang akong sulugoon nga si Newel K. Whitney mao ang tawo nga pilion ug i-orden niini nga katungdanan. Mao kini ang kabubut-on sa Ginoo nga inyong Dios, nga inyong Manunubos. Ingon gayod niana. Amen."},{"verse":9,"text":"Ang pulong sa Ginoo, agi og dugang sa balaod nga gihatag, nga nagpahibalo sa katungdanan sa bishop nga gi-orden ngadto sa simbahan niini nga bahin sa ubasan, nga sa pagkatinuod mao kini—"},{"verse":10,"text":"Sa pagdumala sa balay tipiganan sa Ginoo; sa pagdawat sa mga pundo sa simbahan niini nga bahin sa ubasan;"},{"verse":11,"text":"Sa pagdawat og report gikan sa mga elder nga gisugo kaniadto; ug sa pagpangalagad sa ilang mga gikinahanglan, kinsa mobayad alang niana nga ilang nadawat, kon ugaling sila adunay ikabayad;"},{"verse":12,"text":"Nga kini usab mahimong ipahinungod alang sa kaayohan sa simbahan, ngadto sa kabos ug sa timawa."},{"verse":13,"text":"Ug siya kinsa walay ikahatag nga bayad, ang bayranan pagakuhaon ug ihatag ngadto sa bishop sa Zion, kinsa mobayad sa utang gikan nianang gibutang sa Ginoo sa iyang mga kamot."},{"verse":14,"text":"Ug sa mga buluhaton sa matinud-anon nga nagbuhat sa espirituwal nga mga butang, sa pagpangalagad sa ebanghelyo ug sa mga butang sa gingharian sa simbahan, ug sa kalibotan, mobayad sa mga utang ngadto sa bishop sa Zion;"},{"verse":15,"text":"Sa ingon niana magagikan sa simbahan, kay sumala sa balaod ang matag tawo nga moabot ngadto sa Zion kinahanglan mohalad sa tanang butang sa atubangan sa bishop sa Zion."},{"verse":16,"text":"Ug karon, sa pagkatinuod sultihan ko ikaw, nga samtang ang matag elder niini nga bahin sa ubasan kinahanglan nga mohatag og asoy sa iyang pagkatinugyanan ngadto sa bishop niini nga bahin sa ubasan—"},{"verse":17,"text":"Ang usa ka sertipiko gikan sa maghuhukom o sa bishop niini nga bahin sa ubasan, ngadto sa bishop sa Zion, maghimo sa matag tawo nga takos dawaton, ug mohimo sa tanang butang, alang sa usa ka kabilin, ug pagadawaton isip maalamon nga tinugyanan ug matinud-anon nga mamumuo;"},{"verse":18,"text":"Kay kondili man dili siya dawaton sa bishop sa Zion."},{"verse":19,"text":"Ug karon, sa pagkatinuod sultihan ko ikaw, himoa nga ang matag elder nga mohatag og subay ngadto sa bishop sa simbahan niini nga bahin sa ubasan irekomendar sa simbahan o mga simbahan, diin siya nagtrabaho, aron iyang mahatag ang iyang kaugalingon ug ang iyang mga asoy nga madawat sa matag paagi."},{"verse":20,"text":"Ug usab, himoa nga ang akong mga sulugoon nga gipili nga mahimong tinugyanan sa mga sinulat sa akong simbahan makapangayo og tabang sa bishop o mga bishop sa tanang butang—"},{"verse":21,"text":"Nga ang mga pagpadayag mamantala, ug mapadala ngadto sa tanang lumulupyo sa yuta; aron usab sila makakuha og mga pundo nga makahatag og kaayohan sa simbahan sa tanang butang;"},{"verse":22,"text":"Nga sila usab mohatag sa ilang mga kaugalingon nga mohimo sa tanang butang, ug pagaisipon nga maalamong mga tinugyanan."},{"verse":23,"text":"Ug karon, tan-awa, mahimo kining sumbanan alang sa tanang nagkalainlaing mga branch sa akong simbahan, sa bisan asa nga yuta nga kini natukod. Ug karon akong taposon ang akong pagpamulong. Amen."},{"verse":24,"text":"Pipila ka pulong agi og dugang sa mga balaod sa gingharian, mahitungod sa mga miyembro sa simbahan—sila nga gipili pinaagi sa Balaan nga Espiritu sa pag-adto sa Zion, ug sila nga may kahigayonan nga makaadto sa Zion—"},{"verse":25,"text":"Padad-a sila og usa ka sertipiko ngadto sa bishop gikan sa tulo ka elder sa simbahan, o usa ka sertipiko gikan sa bishop;"},{"verse":26,"text":"Kay kondili, siya nga moadto sa yuta sa Zion dili pagaisipon nga usa ka maalamon nga tinugyanan. Kini usa usab ka sumbanan. Amen."}]},{"chapter":73,"verses":[{"verse":1,"text":"Kay sa pagkatinuod, ingon niini ang gisulti sa Ginoo, mahinungdanon kanako nga sila mopadayon sa pagsangyaw sa ebanghelyo, ug sa pag-awhag sa mga simbahan sa palibot nga mga rehiyon, hangtod sa komperensiya;"},{"verse":2,"text":"Ug unya, tan-awa, ipahibalo kini ngadto kanila, pinaagi sa tingog sa komperensiya, sa ilang pipila ka misyon."},{"verse":3,"text":"Karon, sa pagkatinuod sultihan ko kamo akong mga sulugoon, Joseph Smith, Jun., ug Sidney Rigdon, miingon ang Ginoo, nga kinahanglan nga ipadayon ang paghubad;"},{"verse":4,"text":"Ug, kon ugaling mahimo man, nga mosangyaw sa palibot nga mga rehiyon hangtod sa komperensiya; ug human niana kinahanglan ipadayon ang buluhaton sa paghubad hangtod nga mahuman kini."},{"verse":5,"text":"Ug himoa kini nga sundanan sa mga elder hangtod adunay dugang nga kahibalo, bisan sumala sa nahisulat."},{"verse":6,"text":"Karon ako dili na mohatag kaninyo niini nga panahon. Baksi ang inyong mga bat-ang ug pagmaligdong. Ingon gayod niana. Amen."}]},{"chapter":74,"verses":[{"verse":1,"text":"Kay ang walay pagtuo nga bana pagasantoson pinaagi sa asawa, ug ang walay pagtuo nga asawa pagasantoson pinaagi sa bana; bisan ang inyong mga anak mahugaw, apan karon sila balaan."},{"verse":2,"text":"Karon, sa mga adlaw sa mga apostol ang balaod sa pagtuli anaa sa tanang Judeo nga wala motuo sa ebanghelyo ni Jesukristo."},{"verse":3,"text":"Ug nahitabo nga dihay miabot nga dakong panagbingkil taliwala sa katawhan mahitungod sa balaod sa pagtuli, kay ang walay pagtuo nga bana matinguhaon nga ang iyang mga anak kinahanglang matuli ug mapaubos sa balaod ni Moises, diin ang balaod natuman na."},{"verse":4,"text":"Ug nahitabo nga ang mga anak, nga nagdako ubos sa balaod ni Moises, misunod sa mga tradisyon sa ilang mga amahan ug wala motuo sa ebanghelyo ni Kristo, diin nahimo sila nga dili balaan."},{"verse":5,"text":"Mao nga, tungod niini nga hinungdan ang apostol misulat ngadto sa simbahan, mihatag nila og sugo, nga dili sa Ginoo, apan sa iyang kaugalingon, nga ang matuohon kinahanglang dili itipon ngadto sa dili matuohon; gawas kon ang balaod ni Moises mawala na diha kanila,"},{"verse":6,"text":"Nga ang ilang mga anak magpabilin nga dili matuli; ug nga ang tradisyon mawala, nga nag-ingon nga ang gagmay nga mga bata dili balaan; kay mao kini ang gituohan sa mga Judeo;"},{"verse":7,"text":"Apan ang gagmayng mga bata balaan, kay gibalaan pinaagi sa pag-ula ni Jesukristo; ug mao kini ang gipasabot sa mga kasulatan."}]},{"chapter":75,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, namulong ako gani pinaagi sa tingog sa akong Espiritu, gani ang Alpha ug Omega, ang inyong Ginoo ug inyong Dios—"},{"verse":2,"text":"Paminaw, O kamo nga mihatag sa inyong mga ngalan aron molakaw sa pagsangyaw sa akong ebanghelyo, ug sa pagpung-ol sa akong ubasan."},{"verse":3,"text":"Tan-awa, sultihan ko kamo nga mao kini ang akong kabubut-on nga kamo manglakaw ug dili magpabilin, ni magtinapolan apan maghago sa tibuok ninyong gahom—"},{"verse":4,"text":"Mopalanog sa inyong mga tingog sama sa tingog sa trumpeta, mosangyaw sa kamatuoran sumala sa mga pagpadayag ug mga sugo nga akong gihatag kaninyo."},{"verse":5,"text":"Ug sa ingon niana, kon magmatinud-anon kamo magapas-an kamo og daghang binugkos, ug koronahan og dungog, ug himaya, ug pagka-imortal, ug kinabuhing dayon."},{"verse":6,"text":"Busa, sa pagkatinuod sultihan ko ang akong sulugoon nga si William E. McLellin, akong bakwion ang katungdanan nga akong gihatag kaniya nga moadto sa kanasoran sa silangang bahin;"},{"verse":7,"text":"Ug hatagan ko siya og bag-ong katungdanan ug bag-ong sugo, diin ako, ang Ginoo, mipanton kaniya tungod sa mga pagbagulbol sa iyang kasingkasing;"},{"verse":8,"text":"Ug nakasala siya; bisan pa man niana, ako mopasaylo kaniya ug sultihan siya pag-usab, Lakaw ngadto sa kanasoran sa kasadpang bahin."},{"verse":9,"text":"Ug tugoti nga ang akong sulugoon nga si Luke Johnson mouban kaniya, ug mopahayag sa mga butang nga akong gisugo kanila—"},{"verse":10,"text":"Motawag sa ngalan sa Ginoo alang sa Maghuhupay, nga motudlo kanila sa tanang butang nga angay alang nila—"},{"verse":11,"text":"Mag-ampo kanunay nga sila dili mawad-an sa paglaom; ug kon buhaton nila kini, ako magauban kanila gani hangtod sa kataposan."},{"verse":12,"text":"Tan-awa, mao kini ang kabubut-on sa Ginoo nga inyong Dios mahitungod kaninyo. Ug mao gayod kana. Amen."},{"verse":13,"text":"Ug usab, sa pagkatinuod miingon ang Ginoo, tugoti nga ang akong sulugoon nga si Orson Hyde ug ang akong sulugoon nga si Samuel H. Smith mohimo sa ilang panaw ngadto sa kanasoran sa silangang bahin, ug mosangyaw sa mga butang nga akong gisugo nila; ug kon sila magmatinud-anon, tan-awa, ako magauban kanila gani hangtod sa kataposan."},{"verse":14,"text":"Ug usab, sa pagkatinuod sultihan ko ang akong sulugoon nga si Lyman Johnson, ug ang akong sulugoon nga si Orson Pratt, nga mohimo usab sila sa ilang panaw ngadto sa kanasoran sa silangang bahin; ug tan-awa, ug sud-onga, magauban usab ako kanila, gani hangtod sa kataposan."},{"verse":15,"text":"Ug usab, sultihan ko ang akong sulugoon nga si Asa Dodds, ug ang akong sulugoon nga si Calves Wilson, nga sila usab mohimo sa ilang panaw ngadto sa kanasoran sa kasadpang bahin, ug mosangyaw sa akong ebanghelyo, gani sama sa akong gisugo nila."},{"verse":16,"text":"Ug siya nga nagmatinud-anon makabuntog sa tanang butang, ug pagabayawon sa kataposang adlaw."},{"verse":17,"text":"Ug usab, sultihan ko ang akong sulugoon nga si Major N. Ashley, ug ang akong sulugoon nga si Burr Riggs, tugoti nga sila usab mohimo sa ilang panaw ngadto sa nasod sa habagatang bahin."},{"verse":18,"text":"Oo, tugoti nga silang tanan mohimo sa ilang panaw, sama sa akong gisugo kanila, molakaw gikan sa usa ka balay ngadto sa laing balay, ug gikan sa usa ka balangay ngadto sa laing balangay, ug gikan sa usa ka siyudad ngadto sa laing siyudad."},{"verse":19,"text":"Ug sa bisan unsa nga balay kamo mosulod, ug sila modawat kaninyo, ibilin ang inyong panalangin niana nga balay."},{"verse":20,"text":"Ug sa bisan unsa nga balay kamo mosulod, ug sila dili modawat kaninyo, kamo mobiya sa labing madali gikan niana nga balay, ug motaktak sa abog sa inyong mga tiil isip pagpamatuod batok kanila."},{"verse":21,"text":"Ug kamo mapuno sa kamaya ug kalipay; ug hibaloi kini, nga sa adlaw sa paghukom mahimo kamong mga maghuhukom niana nga balay, ug mohukom kanila;"},{"verse":22,"text":"Ug mas mapasaylo pa ang pagano sa adlaw sa paghukom, kay sa niana nga balay; busa, baksi ang inyong mga hawak ug pagmatinud-anon, ug inyong mabuntog ang tanan nga butang, ug pagabayawon sa kataposang adlaw. Sa ingon mahitabo kana. Amen."},{"verse":23,"text":"Ug usab, misulti ang Ginoo kaninyo, O kamo nga mga elder sa akong simbahan, nga mihatag sa inyong mga ngalan nga kamo masayod sa iyang kabubut-on mahitungod kaninyo—"},{"verse":24,"text":"Tan-awa, sultihan ko kamo, nga katungdanan sa simbahan ang pagtabang sa pagsuporta sa mga pamilya, ug usab sa pagsuporta sa mga pamilya niadtong gitawag ug kinahanglan nga ipadala ngadto sa kalibotan sa pagsangyaw sa ebanghelyo ngadto sa kalibotan."},{"verse":25,"text":"Mao nga, ako, ang Ginoo, naghatag kaninyo niini nga sugo, nga kamo makaangkon og mga dapit alang sa inyong mga pamilya, kon ang inyong kaigsoonan andam nga moabli sa ilang mga kasingkasing."},{"verse":26,"text":"Ug tugoti kadtong tanan nga makaangkon og mga dapit alang sa ilang mga pamilya, ug suporta sa simbahan alang kanila, dili mapakyas sa paglakaw ngadto sa kalibotan, gani ngadto sa silangan o ngadto sa kasadpan, o ngadto sa amihanan, o ngadto sa habagatan."},{"verse":27,"text":"Papangayoa sila ug makadawat sila, patuktoka ug kini pagaablihan ngadto kanila, ug ipahibalo ra gikan sa kahitas-an, gani pinaagi sa Maghuhupay, kon asa sila moadto."},{"verse":28,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, nga ang matag tawo nga adunay katungdanan sa pagsangkap alang sa iyang kaugalingong pamilya, tugoti nga siya makasangkap, ug dili siya mawad-an sa iyang korona; ug tugoti nga maghago siya diha sa simbahan."},{"verse":29,"text":"Tugoti nga ang matag tawo magmakugihon sa tanang butang. Ug ang tapolan walay dapit sa simbahan, gawas kon maghinulsol siya ug mag-usab sa iyang mga paagi."},{"verse":30,"text":"Mao nga, tugoti ang akong sulugoon nga si Simeon Carter ug ang akong sulugoon nga si Emer Harris nga magkahiusa sa ilang pangalagad;"},{"verse":31,"text":"Ug usab ang akong sulugoon nga si Ezra Thayre ug ang akong sulugoon nga si Thomas B. Marsh;"},{"verse":32,"text":"Usab ang akong sulugoon nga si Hyrum Smith ug ang akong sulugoon nga si Reynolds Cahoon;"},{"verse":33,"text":"Ug usab ang akong sulugoon nga si Daniel Stanton ug ang akong sulugoon nga si Seymour Bronson;"},{"verse":34,"text":"Ug usab ang akong sulugoon nga si Sylvester Smith ug ang akong sulugoon nga si Gideon Carter;"},{"verse":35,"text":"Ug usab ang akong sulugoon nga si Ruggles Eames ug ang akong sulugoon nga si Stephen Burnett;"},{"verse":36,"text":"Ug usab ang akong sulugoon nga si Micah B. Welton ug usab ang akong sulugoon nga si Eden Smith. Sa ingon mahitabo kana. Amen."}]},{"chapter":76,"verses":[{"verse":1,"text":"Paminaw, O kamong kalangitan, ug paminaw, O yuta, ug paglipay kamong mga lumulupyo niana, kay ang Ginoo mao ang Dios, ug gawas kaniya wala nay Manluluwas."},{"verse":2,"text":"Dako ang iyang kaalam, katingalahan ang iyang mga paagi, ug ang kadako sa iyang mga buhat walay nasayod."},{"verse":3,"text":"Ang iyang mga katuyoan dili mapakyas, ni adunay bisan kinsa nga makapugong sa iyang kamot."},{"verse":4,"text":"Gikan sa kahangtoran ngadto sa kahangtoran siya mao gihapon, ug ang iyang katuigan dili gayod matapos."},{"verse":5,"text":"Kay misulti ang Ginoo—ako, ang Ginoo, maluluy-on ug mabination niadtong mahadlok kanako, ug mahimuot sa pagpasidungog niadtong moserbisyo kanako sa pagkamatarong ug sa kamatuoran ngadto sa kataposan."},{"verse":6,"text":"Dako ang ilang ganti ug walay kataposan ang ilang himaya."},{"verse":7,"text":"Ug ngadto kanila ako mopadayag sa tanang misteryo, oo, tanang tinagoan nga misteryo sa akong gingharian gikan sa dugay nang panahon, ug alang sa panahon nga moabot, akong ipahibalo kanila ang kanindot sa akong kabubut-on mahitungod sa tanang butang kabahin sa akong gingharian."},{"verse":8,"text":"Oo, gani ang mga kahibulongan bahin sa kahangtoran ilang mahibaloan, ug ang mga butang nga moabot akong ipakita kanila, bisan ang mga butang sa daghang henerasyon."},{"verse":9,"text":"Ug ang ilang kaalam molapad, ug ang ilang panabot moabot sa langit; ug sa ilang atubangan ang kaalam sa makinaadmanon mahanaw, ug ang panabot sa maalamon mawalay kapuslanan."},{"verse":10,"text":"Kay pinaagi sa akong Espiritu ako molamdag kanila, ug pinaagi sa akong gahom akong ipahibalo kanila ang mga tinago sa akong kabubut-on—oo, gani kadtong mga butang nga wala pay mata nga nakakita, ni dalunggan nga nakadungog, ni nakasulod sa kasingkasing sa tawo."},{"verse":11,"text":"Kami, si Joseph Smith, Jun., ug si Sidney Rigdon, samtang anaa sa Espiritu sa ikanapulo ug unom ka adlaw sa Pebrero, sa tuig sa atong Ginoo nga usa ka libo walo ka gatos ug katloan ug duha—"},{"verse":12,"text":"Pinaagi sa gahom sa Espiritu nabuka ang among mga mata ug ang among mga panabot nalamdagan, aron makakita ug makasabot sa mga butang sa Dios—"},{"verse":13,"text":"Bisan kadtong mga butang nga anaa na gikan sa sinugdanan sa wala pa ang kalibotan, nga gi-orden sa Amahan, pinaagi sa iyang Bugtong Anak, kinsa anaa sa dughan sa Amahan, gani gikan sa sinugdanan;"},{"verse":14,"text":"Kang kinsa kami nagpamatuod; ug ang talaan nga among gipamatud-an mao ang kahingpitan sa ebanghelyo ni Jesukristo, nga mao ang Anak, nga among nakita ug among gikasulti pinaagi sa langitnong panan-awon."},{"verse":15,"text":"Kay samtang naghimo kami sa buhat sa paghubad, nga gisangon sa Ginoo ngari kanamo, miabot kami sa ika-kawhaan ug siyam nga bersikulo sa ikalima nga kapitulo sa Juan, nga gihatag ngari kanamo ingon sa mosunod—"},{"verse":16,"text":"Naghisgot bahin sa pagkabanhaw sa mga patay, mahitungod niadtong mga namati sa tingog sa Anak sa Tawo:"},{"verse":17,"text":"Ug mamangon; sila nga nagbuhat og maayo, diha sa pagkabanhaw sa makiangayon; ug sila nga naghimo og daotan, diha sa pagkabanhaw sa mga makiangayon."},{"verse":18,"text":"Karon nakapahibulong kini kanamo, kay kini gihatag ngari kanamo sa Espiritu."},{"verse":19,"text":"Ug samtang namalandong kami niini nga mga butang, ang Ginoo mihikap sa mga mata sa among mga panabot ug nabuksan kini ug ang himaya sa Ginoo midan-ag sa palibot."},{"verse":20,"text":"Ug among nakita ang himaya sa Anak, sa tuo nga kamot sa Amahan, ug nakadawat sa iyang kahingpitan;"},{"verse":21,"text":"Ug nakita ang balaang mga anghel, ug sila nga nabalaan sa atubangan sa iyang trono, nagsimba sa Dios, ug sa Kordero, kinsa nagsimba kaniya hangtod sa kahangtoran."},{"verse":22,"text":"Ug karon, human sa daghang pagpamatuod nga gihatag mahitungod kaniya, kini ang pagpamatuod, ang kataposan sa tanan, nga among ihatag mahitungod kaniya: Nga siya buhi!"},{"verse":23,"text":"Kay kami nakakita kaniya, gani sa tuo nga kamot sa Dios; ug kami nakadungog sa tingog nga nagpamatuod nga siya mao ang Bugtong Anak sa Amahan—"},{"verse":24,"text":"Nga pinaagi kaniya, ug diha kaniya, ug tungod kaniya, ang mga kalibotan nalalang, ug ang mga lumulupyo niana mga anak nga lalaki ug mga anak nga babaye sa Dios."},{"verse":25,"text":"Ug nakita usab namo kini, ug magpamatuod, nga ang anghel sa Dios kinsa adunay katungod diha sa atubangan sa Dios, nga misupak batok sa Bugtong Anak nga gihigugma sa Amahan ug anaa sa dughan sa Amahan, gisalikway gikan sa atubangan sa Dios ug sa Anak,"},{"verse":26,"text":"Ug gitawag nga Kapildihan, kay ang mga langit naghilak tungod kaniya—siya si Lucifer, ang anak sa kabuntagon."},{"verse":27,"text":"Ug among nakita, ug tan-awa, nahulog siya! nahulog, gani ang anak sa kabuntagon!"},{"verse":28,"text":"Ug samtang anaa pa kami ubos sa gahom sa Espiritu, gisugo kami sa Ginoo nga among isulat ang panan-awon; kay nakita namo si Satanas, kanang karaan nga bitin, gani ang yawa, kinsa misupak batok sa Dios, ug nagtinguha sa pag-ilog sa gingharian sa among Dios ug sa iyang Kristo—"},{"verse":29,"text":"Mao nga, mipasiugda siya og gubat batok sa mga santos sa Dios, ug miliyok palibot kanila."},{"verse":30,"text":"Ug nakakita kami og panan-awon bahin sa mga pag-antos niadtong iyang gipasiugdahan og gubat ug nabuntog, kay niini miabot ang tingog sa Ginoo ngari kanamo:"},{"verse":31,"text":"Sa ingon niana miingon ang Ginoo mahitungod sa tanan niadtong nasayod sa akong gahom, ug nakaambit niana, ug mitugot sa ilang kaugalingon pinaagi sa gahom sa yawa nga mabuntog, ug molimod sa kamatuoran ug mosukol sa akong gahom—"},{"verse":32,"text":"Sila mao kadtong mga anak sa kapildihan, kang kinsa moingon ako nga mas maayo pa kon wala na lang gayod unta sila matawo;"},{"verse":33,"text":"Kay sila mga sudlanan sa mga kaligutgot, gitakda nga mag-antos sa kapungot sa Dios, uban sa yawa ug sa iyang mga anghel diha sa kahangtoran;"},{"verse":34,"text":"Mahitungod kanila ako nag-ingon nga walay kapasayloan niini nga kalibotan ni sa kalibotan nga moabot—"},{"verse":35,"text":"Kay milimod sa Balaang Espiritu human makadawat niini, ug milimod sa Bugtong Anak sa Amahan, milansang sa krus kaniya diha sa ilang mga hunahuna ug mga kasingkasing ug mipakaulaw kaniya."},{"verse":36,"text":"Kini sila mao kadtong itambog ngadto sa lim-aw sa kalayo ug asupre, uban sa yawa ug sa iyang mga anghel—"},{"verse":37,"text":"Ug sila lamang ang adunay gahom sa ikaduhang kamatayon;"},{"verse":38,"text":"Oo, sa pagkatinuod, sila lamang ang dili matubos sa tukma nga panahon sa Ginoo, human sa mga pag-antos sa iyang kapungot."},{"verse":39,"text":"Kay ang tanan nga nahibilin pagabangonon pinaagi sa pagkabanhaw sa mga patay, pinaagi sa kadaogan ug himaya sa Kordero, kinsa gipatay, kinsa anaa sa dughan sa Amahan sa wala pa mabuhat ang mga kalibotan."},{"verse":40,"text":"Ug mao kini ang ebanghelyo, ang maayong balita, diin ang tingog sa kalangitan nagpamatuod ngari kanamo—"},{"verse":41,"text":"Nga siya mianhi sa kalibotan, gani si Jesus, aron ilansang sa krus alang sa kalibotan, ug aron mag-antos sa mga sala sa kalibotan, ug aron balaanon ang kalibotan, ug aron limpyohan kini gikan sa tanang dili matarong;"},{"verse":42,"text":"Nga pinaagi kaniya ang tanan unta maluwas kadtong mga gihatagan sa Amahan sa iyang gahom ug gilalang pinaagi kaniya;"},{"verse":43,"text":"Kinsa naghimaya sa Amahan, ug nagluwas sa tanang binuhat sa iyang mga kamot, gawas niadtong mga anak sa kapildihan nga milimod sa Anak human nga ang Amahan mipadayag kaniya."},{"verse":44,"text":"Mao nga, luwason niya ang tanan gawas kanila—itambog sila ngadto sa walay kataposan nga silot, nga mao ang walay kinutoban nga silot, nga mao ang mahangtoron nga silot, nga magpuyo uban sa yawa ug sa iyang mga anghel didto sa kahangtoran, diin ang ilang mga ulod dili mamatay, ug ang kalayo dili mapalong, nga mao ang ilang kasakit—"},{"verse":45,"text":"Ug ang kataposan niana, ni ang dapit niana, ni ang kasakit, walay tawo nga nasayod;"},{"verse":46,"text":"Ni kini napadayag, ni gipadayag, ni ipadayag ngadto sa tawo, gawas ngadto kanila nga makaambit niana;"},{"verse":47,"text":"Bisan pa niana, ako, ang Ginoo, mopakita niini pinaagi sa panan-awon ngadto sa kadaghanan, apan dihadiha motak-op niini pag-usab;"},{"verse":48,"text":"Mao nga, ang kataposan, ang gilapdon, ang gitas-on, ang giladmon, ug ang kaalaotan niana, dili nila masabtan, ni si bisan kinsa nga tawo gawas niadtong gitakda ngadto niini nga panghimaraot."},{"verse":49,"text":"Ug nakadungog kami sa tingog nga nag-ingon: Isulat ang panan-awon, kay tan-awa, mao kini ang kataposan sa panan-awon sa mga pag-antos sa mga makasasala."},{"verse":50,"text":"Ug usab magpamatuod kami—kay kami nakakita ug nakadungog, ug kini mao ang pagpamatuod sa ebanghelyo ni Kristo mahitungod kanila nga mobangon sa pagkabanhaw sa mga makiangayon—"},{"verse":51,"text":"Sila mao kadtong nakadawat sa pagpamatuod ni Jesus, ug mituo sa iyang ngalan ug nabunyagan subay sa paagi sa iyang paglubong, ingon nga gilubong diha sa tubig pinaagi sa iyang ngalan, ug sumala sa sugo nga iyang gihatag—"},{"verse":52,"text":"Nga pinaagi sa pagsunod sa mga sugo mahimo silang mahugasan ug malimpyohan gikan sa ilang tanang sala, ug makadawat sa Balaang Espiritu pinaagi sa pagpandong sa mga kamot gikan kaniya kinsa na-orden ug naselyo niini nga gahom;"},{"verse":53,"text":"Ug nagmadaogon pinaagi sa pagtuo, ug naselyo pinaagi sa Balaan nga Espiritu sa saad, nga gipadala sa Amahan ngadto sa tanang makiangayon ug matinuoron."},{"verse":54,"text":"Mao kadto sila ang simbahan sa Unang Natawo."},{"verse":55,"text":"Mao kadto sila kansang mga kamot gihatagan sa Amahan sa tanang butang—"},{"verse":56,"text":"Mao kadto sila ang mga pari ug mga hari, kinsa nakadawat sa iyang kahingpitan, ug sa iyang himaya;"},{"verse":57,"text":"Ug mga pari sa Labing Halangdon, subay sa kapunongan ni Melchizedek, nga subay sa kapunongan ni Enoch, nga subay sa kapunongan sa Bugtong Anak."},{"verse":58,"text":"Mao nga, ingon nga kini nahisulat, sila mga dios, gani mga anak sa Dios—"},{"verse":59,"text":"Mao nga, ang tanang butang ila, sa kinabuhi man o sa kamatayon, o mga butang karon, o mga butang nga moabot, ang tanan ila ug sila kang Kristo, ug si Kristo sa Dios."},{"verse":60,"text":"Ug mabuntog nila ang tanang butang."},{"verse":61,"text":"Mao nga, ayaw tugoti ang tawo nga mohimaya sa tawo, apan tugoti nga siya mohimaya sa Dios, kinsa mobuntog sa tanang kaaway ubos sa iyang mga tiil."},{"verse":62,"text":"Kini sila mopuyo diha sa atubangan sa Dios ug sa iyang Kristo hangtod sa kahangtoran."},{"verse":63,"text":"Kini sila mao kadtong iyang dad-on uban kaniya, kon siya moabot diha sa mga panganod sa langit aron mohari sa yuta ibabaw sa iyang katawhan."},{"verse":64,"text":"Kini sila mao kadtong adunay bahin sa unang pagkabanhaw."},{"verse":65,"text":"Kini sila mao kadtong mobangon sa pagkabanhaw sa mga matarong."},{"verse":66,"text":"Kini sila mao kadtong moadto sa Bukid sa Zion, ug sa siyudad sa buhing Dios, ang langitnong dapit, ang labing balaan sa tanan."},{"verse":67,"text":"Kini sila mao kadtong moadto sa dili maihap nga panon sa mga anghel, ngadto sa kinatibuk-ang panagtigom sa simbahan ni Enoch, ug sa Unang Natawo."},{"verse":68,"text":"Kini sila mao kadtong kansang mga ngalan nahisulat sa langit, diin ang Dios ug si Kristo mao ang maghuhukom sa tanan."},{"verse":69,"text":"Kini sila mao kadtong mga tawo nga matarong nga nahimong hingpit pinaagi ni Jesus ang tigpataliwala sa bag-ong pakigsaad, kinsa nagbuhat niining hingpit nga pag-ula pinaagi sa pagpaagas sa iyang kaugalingong dugo."},{"verse":70,"text":"Kini sila mao kadtong kansang mga lawas mga celestial, kansang himaya sama nianang sa adlaw, gani ang himaya sa Dios, ang labing halangdon sa tanan, kansang himaya ang adlaw sa kawanangan gisulat isip panig-ingnan."},{"verse":71,"text":"Ug usab, nakita namo ang kalibotan sa terrestrial, ug tan-awa ug sud-onga, kini sila mao kadtong anaa sa terrestrial, kansang himaya lahi kay sa nianang anaa sa simbahan sa Unang Natawo nga nakadawat sa kahingpitan sa Amahan, gani ingon nga ang bulan lahi kay sa adlaw diha sa kawanangan."},{"verse":72,"text":"Tan-awa, kini sila mao kadtong namatay nga wala masayod sa balaod;"},{"verse":73,"text":"Ug sila mao usab ang mga espiritu sa mga tawo nga gibutang sa bilanggoan, kang kinsa ang Anak mibisita, ug misangyaw sa ebanghelyo ngadto kanila, aron sila mahukman sumala sa mga tawo diha sa unod;"},{"verse":74,"text":"Kinsa wala modawat sa pagpamatuod ni Jesus diha sa unod, apan pagkahuman midawat ra niini."},{"verse":75,"text":"Kini sila mao kadtong halangdon nga mga tawo sa yuta, nga nabutaan sa pagkamalimbongon sa mga tawo."},{"verse":76,"text":"Kini sila mao kadtong nakadawat sa iyang himaya, apan dili sa iyang kahingpitan."},{"verse":77,"text":"Kini sila mao kadtong nakadawat sa pagduaw sa Anak, apan dili sa kahingpitan sa Amahan."},{"verse":78,"text":"Mao nga, mga lawas sila nga terrestrial, ug dili mga lawas nga celestial, ug lahi sa himaya sama nga ang bulan lahi kay sa adlaw."},{"verse":79,"text":"Kini sila mao kadtong dili maisogon sa pagpamatuod ni Jesus; mao nga, dili sila makaangkon og korona didto sa gingharian sa atong Dios."},{"verse":80,"text":"Ug karon mao kini ang kataposan sa panan-awon nga among nakita bahin sa terrestrial, nga gisugo sa Ginoo namo nga isulat samtang anaa pa kami ubos sa gahom sa Espiritu."},{"verse":81,"text":"Ug usab, nakita namo ang himaya sa telestial, kansang himaya sama nianang sa mas ubos, gani ingon nga ang himaya sa mga bituon lahi kay sa himaya sa bulan diha sa kawanangan."},{"verse":82,"text":"Kini sila mao kadtong wala modawat sa ebanghelyo ni Kristo, ni sa pagpamatuod ni Jesus."},{"verse":83,"text":"Kini sila mao kadtong wala molimod sa Balaan nga Espiritu."},{"verse":84,"text":"Kini sila mao kadtong gitambog sa impyerno."},{"verse":85,"text":"Kini sila mao kadtong dili matubos gikan sa yawa hangtod sa kataposan, hangtod nga ang Ginoo, gani si Kristo ang Kordero, mahuman sa iyang buluhaton."},{"verse":86,"text":"Kini sila mao kadtong dili makadawat sa iyang kahingpitan sa mahangtoron nga kalibotan, apan sa Balaang Espiritu pinaagi sa pagpangalagad sa terrestrial;"},{"verse":87,"text":"Ug ang terrestrial pinaagi sa pagpangalagad sa celestial."},{"verse":88,"text":"Ug usab ang telestial makadawat niini gikan sa pagpangalagad sa mga anghel kinsa gitudlo sa pagpangalagad alang kanila, o kinsa gipili nga mahimong tigpangalagad nga mga espiritu alang kanila; kay mahimo silang mga manununod sa kaluwasan."},{"verse":89,"text":"Ug sa ingon niana nakita namo, pinaagi sa langitnong panan-awon, ang himaya sa telestial, nga dili gayod matugkad sa panabot sa tawo;"},{"verse":90,"text":"Ug walay tawo nga nasayod niini gawas kaniya kang kinsa ang Dios mipadayag niini."},{"verse":91,"text":"Ug sa ingon niana nakita namo ang himaya sa terrestrial nga milabaw sa tanang butang sa himaya sa telestial, bisan sa himaya, ug sa gahom, ug sa kusog, ug sa kamandoan."},{"verse":92,"text":"Ug sa ingon niana nakita namo ang himaya sa celestial, nga milabaw sa tanang butang—diin ang Dios, gani ang Amahan, naghari sa iyang trono hangtod sa kahangtoran;"},{"verse":93,"text":"Sa atubangan kansang trono ang tanang butang nagyukbo sa mapainubsanong balaang pagtahod, ug naghimaya kaniya hangtod sa kahangtoran."},{"verse":94,"text":"Sila kinsa magpuyo sa iyang atubangan mao ang simbahan sa Unang Natawo; ug nakakita sila, ug nakahibalo sa tanan nga butang, nga nakadawat sa iyang kahingpitan ug sa iyang grasya;"},{"verse":95,"text":"Ug siya mihimo kanilang managsama sa gahom, ug sa kusog, ug sa kamandoan."},{"verse":96,"text":"Ug ang himaya sa celestial usa, gani sama nga ang himaya sa adlaw usa ra."},{"verse":97,"text":"Ug ang himaya sa terrestrial usa, gani sama nga ang himaya sa bulan usa ra."},{"verse":98,"text":"Ug ang himaya sa telestial usa, gani sama nga ang himaya sa mga bituon usa ra; kay sama nga ang usa ka bituon lahi ang himaya kay sa laing bituon, mao usab ang pagkalahi sa himaya sa kalibotan nga telestial;"},{"verse":99,"text":"Kay kini sila mao kadtong kang Pablo, ug kang Apollos, ug kang Cefas."},{"verse":100,"text":"Kini sila mao kadtong moingon nga ang pipila nila mga sumusunod sa usa ug ang pipila sa lain—ang pipila kang Kristo ug ang pipila kang Juan, ug ang pipila kang Moises, ug ang pipila kang Elias, ug ang pipila kang Esaias, ug ang pipila kang Isaias ug ang pipila kang Enoch;"},{"verse":101,"text":"Apan wala modawat sa ebanghelyo, ni sa pagpamatuod ni Jesus, ni sa pagpamatuod sa mga propeta, ni sa walay kataposang pakigsaad."},{"verse":102,"text":"Ug sa kataposan, kining tanan mao sila kadtong dili itipon uban sa mga santos, sa pagbayaw ngadto sa langit aron itipon sa simbahan sa Unang Natawo, ug dawaton ngadto sa panganod."},{"verse":103,"text":"Kini sila mao kadtong mga bakakon, ug mga barangan, ug mga mananapaw, ug nagbaligya sa dungog, ug kinsa nahigugma ug naghimo og bakak."},{"verse":104,"text":"Kini sila mao kadtong mag-antos sa kapungot sa Dios dinhi sa yuta."},{"verse":105,"text":"Kini sila mao ang mag-antos sa panimalos sa mahangtoron nga kalayo."},{"verse":106,"text":"Kini sila mao kadtong itambog sa impyerno ug mag-antos sa kapungot sa Labawng Makagagahom nga Dios, hangtod sa kahingpitan sa mga panahon, sa higayon nga si Kristo makabuntog sa tanang kaaway ubos sa iyang mga tiil, ug makahingpit sa iyang buluhaton;"},{"verse":107,"text":"Kon iya nang itugyan ang gingharian, ug ibalik kini ngadto sa Amahan, nga walay lama, mag-ingon: Nabuntog ko na ang kalibotan ug natunob-tunoban ang intosan sa bino nga nag-inusara, gani ang intosan sa bino sa kabangis sa kapungot sa Labawng Makagagahom nga Dios."},{"verse":108,"text":"Dayon purong-purongan siya og korona sa iyang himaya, aron molingkod sa trono sa iyang gahom sa paghari hangtod sa kahangtoran."},{"verse":109,"text":"Apan tan-awa, ug sud-onga, nakita namo ang himaya ug ang mga lumulupyo sa kalibotan sa telestial, nga sila sama ka daghan sa mga bituon nga dili maihap diha sa kawanangan sa langit, o sama sa balas sa kabaybayonan;"},{"verse":110,"text":"Ug nakadungog sa tingog sa Ginoo nga nag-ingon: Kining tanan moluhod, ug ang matag dila mokompisal ngadto kaniya kinsa naglingkod sa trono hangtod sa kahangtoran;"},{"verse":111,"text":"Kay pagahukman sila sumala sa ilang binuhatan, ug ang matag tawo makadawat sumala sa iyang kaugalingong binuhatan, sa iyang kaugalingong kamandoan, sa mga mansyon nga giandam;"},{"verse":112,"text":"Ug mahimo silang mga sulugoon sa Labing Halangdon; apan kon asa ang Dios ug si Kristo nagpuyo sila dili makaadto, sa mga kalibotan nga walay kataposan."},{"verse":113,"text":"Mao kini ang kataposan sa panan-awon nga among nakita, diin kami gisugo sa pagsulat samtang anaa pa kami ubos sa impluwensya sa Espiritu."},{"verse":114,"text":"Apan mahinungdanon ug kahibulongan ang mga buhat sa Ginoo, ug ang mga misteryo sa iyang gingharian nga iyang gipakita ngari kanamo, mahitungod sa himaya, ug sa kusog, ug sa kamandoan nga dili gayod masabtan sa tawo;"},{"verse":115,"text":"Diin siya misugo kanamo nga dili namo isulat samtang anaa pa kami ubos sa impluwensya sa Espiritu, ug wala itugot nga litokon kini sa tawo;"},{"verse":116,"text":"Ni ang tawo angay nga mahibalo niini, kay kini makita ug masabtan lamang pinaagi sa gahom sa Balaang Espiritu, nga ihatag sa Dios niadtong nahigugma kaniya, ug nagputli sa ilang mga kaugalingon sa iyang atubangan;"},{"verse":117,"text":"Ngadto kang kinsa siya mohatag niini nga kahigayonan sa pagtan-aw ug pagkahibalo alang sa ilang mga kaugalingon;"},{"verse":118,"text":"Nga pinaagi sa gahom ug pagpakita sa Espiritu, samtang anaa sa unod, makasugakod sila sa iyang atubangan diha sa kalibotan sa himaya."},{"verse":119,"text":"Ug maanaa sa Dios ug sa Kordero ang himaya, ug dungog, ug kamandoan hangtod sa kahangtoran. Amen."}]},{"chapter":77,"verses":[{"verse":1,"text":"P. Unsa ang dagat nga bildo nga gipamulong ni Juan, sa ika-4 nga kapitulo, ug ika-6 nga bersikulo sa Pinadayag?T. Kini mao ang yuta, sa balaan, imortal, ug mahangtoron nga kahimtang."},{"verse":2,"text":"P. Unsay angay natong masabtan bahin sa upat ka mananap, nga gipamulong diha nianang mao gihapon nga bersikulo?T. Mga mahulagwayon kana nga mga pulong, nga gigamit sa Tigpadayag, nga si Juan, sa paghulagway sa langit, sa paraiso sa Dios, sa kalipay sa tawo, ug sa mga mananap, ug sa mga butang nga nagkamang, ug sa mga langgam sa kahanginan; kanang espirituhanon nga binuhat nga susama nianang temporal; ug nianang temporal nga susama nianang espirituhanon; ang espiritu sa tawo susama sa iyang pagkatawo, mao usab ang espiritu sa mananap, ug ang matag lain nga nilalang nga gilalang sa Dios."},{"verse":3,"text":"P. Ang upat ba ka mananap nagpasabot lamang sa piho nga mga mananap, o nagsimbolo kini sa mga pundok o mga kaliwat?T. Nagpasabot lamang kini sa upat ka piho nga mga mananap, nga gipakita kang Juan, nga nagsimbolo sa himaya sa mga pundok sa mga binuhat diha sa gidestino kanila nga kaliwat o kahimtang sa paglalang, sa pagtagamtam sa ilang walay kataposang kalipay."},{"verse":4,"text":"P. Unsay angay natong masabtan bahin sa mga mata ug mga pako, nga anaa sa mga mananap?T. Ang ilang mga mata nagsimbolo sa kahayag ug kahibalo, nga mao, nga puno sila sa kahibalo; ug ang ilang mga pako nagsimbolo sa gahom, sa paglihok, sa pagbuhat, ug uban pa."},{"verse":5,"text":"P. Unsay angay natong masabtan bahin sa upat ug kawhaan ka elder, nga gipamulong ni Juan?T. Kinahanglan natong masabtan nga kining mga elder nga nakita ni Juan, mao ang mga elder nga matinud-anon sa buhat sa pagpangalagad ug patay na; kinsa nahisakop sa pito ka simbahan, ug anaa na sa paraiso sa Dios."},{"verse":6,"text":"P. Unsay angay natong masabtan bahin sa basahon nga nakita ni Juan, nga giselyohan sa luyo og pito ka selyo?T. Kinahanglan nga atong masabtan nga naglangkob kini sa gipadayag nga kabubut-on, sa mga misteryo, ug sa mga buhat sa Dios; sa tinago nga mga butang bahin sa iyang pagdumala kalabot niini nga yuta atol sa pito ka libo ka tuig nga gidugayon niini, o temporal nga pagkaanaa niini."},{"verse":7,"text":"P. Unsay angay natong masabtan bahin sa pito ka selyo diin kini giselyo?T. Kinahanglan nga atong masabtan nga ang unang selyo naglakip sa mga butang sa nag-unang usa ka libo ka tuig, ug ang ikaduha usab sa ikaduha ka libo ka tuig, ug padayon hangtod sa ikapito."},{"verse":8,"text":"P. Unsay angay natong masabtan bahin sa upat ka anghel, nga gipamulong diha sa ika-7 nga kapitulo ug unang bersikulo sa Pinadayag?T. Kinahanglan nga atong masabtan nga sila ang upat ka anghel nga gipadala gikan sa Dios, nga gihatagan og gahom sa ibabaw sa upat ka bahin sa yuta, sa pagluwas sa kinabuhi ug sa paglaglag; kanila gisalig ang walay kataposang ebanghelyo nga itugyan ngadto sa matag nasod, kaliwatan, pinulongan, ug katawhan; naghupot sa gahom sa pagtak-op sa kalangitan, sa pagselyo sa katawhan ngadto sa kinabuhing dayon, o sa pagtambog ngadto sa mga dapit sa kangitngit."},{"verse":9,"text":"P. Unsay angay natong masabtan bahin sa anghel nga misaka gikan sa silangan, sa Pinadayag ika-7 nga kapitulo ug ika-2 nga bersikulo?T. Kinahanglan nga atong masabtan nga ang anghel nga misaka gikan sa silangan mao siya kinsa gihatagan sa selyo sa buhi nga Dios ngadto sa napulog duha ka tribo sa Israel; mao nga, gipahayag niya ngadto sa upat ka anghel nga naghupot sa walay kataposang ebanghelyo, sa pag-ingon: Ayaw pasakiti ang yuta, ni ang dagat, ni ang mga kahoy, hangtod nga atong maselyohan ang mga sulugoon sa atong Dios diha sa ilang mga agtang. Ug, kon inyo kining dawaton, mao kini si Elias nga moanhi aron sa pagpundok sa mga tribo sa Israel ug sa pagpahiuli sa tanang butang."},{"verse":10,"text":"P. Kanus-a ang mga butang nga gihisgotan dinhi niini nga kapitulo matuman?T. Matuman kini sa ikaunom ka libo nga tuig, o sa pagbukas sa ikaunom nga selyo."},{"verse":11,"text":"P. Unsay angay natong masabtan bahin sa pagselyo sa usa ka gatos ug kap-atan ug upat ka libo, gikan sa tanang tribo sa Israel—nga napulog duha ka libo gikan sa matag tribo?T. Kinahanglan nga atong masabtan nga kadtong mga naselyohan mao ang high priest, nga gi-orden ngadto sa balaan nga kapunongan sa Dios, sa pagpangalagad sa walay kataposang ebanghelyo; kay sila mao kadtong gi-orden gikan sa matag nasod, kaliwatan, pinulongan, ug katawhan, pinaagi sa mga anghel nga gihatagan og gahom ibabaw sa kanasoran sa yuta, sa pagdala kutob sa moadto sa simbahan sa Unang Natawo."},{"verse":12,"text":"P. Unsay angay natong masabtan bahin sa pagpatingog sa mga trumpeta, nga gihisgotan diha sa ika-8 nga kapitulo sa Pinadayag?T. Kinahanglan nga atong masabtan nga kay ang Dios mihimo sa kalibotan sulod sa unom ka adlaw, ug sa ikapito ka adlaw iyang gitapos ang iyang buhat, ug mibalaan niini, ug usab mihulma sa tawo gikan sa abog sa yuta, mao usab, sa sinugdanan sa ikapito ka libo ka tuig nga ang Ginoong Dios mobalaan sa yuta, ug mohuman sa kaluwasan sa tawo, ug mohukom sa tanang butang, ug motubos sa tanang butang, gawas niadtong wala niya ibutang ubos sa iyang gahom, sa higayon nga selyohan niya ang tanang butang, ngadto sa kataposan sa tanang butang; ug ang pagtingog sa mga trumpeta sa pito ka anghel mao ang pag-andam ug pagtapos sa iyang buhat, sa pagsugod sa ikapito ka libo ka tuig—nga pag-andam sa agianan sa dili pa moabot ang panahon sa iyang pag-anhi."},{"verse":13,"text":"P. Kanus-a ang mga butang matuman, nga nahisulat diha sa ika-9 nga kapitulo sa Pinadayag?T. Matuman kini human mabuksan ang ikapito nga selyo, sa dili pa moanhi si Kristo."},{"verse":14,"text":"P. Unsay angay natong masabtan bahin sa gamay nga basahon nga gikaon ni Juan, sama sa gihisgotan diha sa ika-10 nga kapitulo sa Pinadayag?T. Kinahanglan natong masabtan nga usa kadto ka misyon, ug usa ka ordinansa, alang kaniya ang pagpundok sa mga tribo sa Israel; tan-awa, kini si Elias, kinsa, sumala sa nahisulat, kinahanglang moanhi ug mopahiuli sa tanang butang."},{"verse":15,"text":"P. Unsay angay natong masabtan bahin sa duha ka saksi, diha sa ikanapulog usa nga kapitulo sa Pinadayag?T. Sila mao ang duha ka propeta nga ipahimutang ngadto sa nasod sa mga Judeo sa kataposang mga adlaw, sa panahon sa pagpahiuli, ug sa pagpanagna ngadto sa mga Judeo human sila mapundok ug makatukod sa siyudad sa Jerusalem sa yuta sa ilang mga amahan."}]},{"chapter":78,"verses":[{"verse":1,"text":"Namulong ang Ginoo kang Joseph Smith, Jun., nga nag-ingon: Patalinghog kanako, miingon ang Ginoo nga inyong Dios, kinsa na-orden ngadto sa halangdon nga pagkapari sa akong simbahan, kinsa nagpundok sa inyong kaugalingon;"},{"verse":2,"text":"Ug paminawa ang iyang tambag kinsa mi-orden kaninyo gikan sa kahitas-an, nga mamulong diha sa inyong mga dalunggan og mga pulong sa kaalam, aron maluwas kamo niana nga butang nga inyong gipakita sa akong atubangan, miingon ang Ginoong Dios."},{"verse":3,"text":"Sa pagkatinuod sultihan ko kamo, nga miabot na ang panahon, ug karon haduol na; ug tan-awa, ug sud-onga, kinahanglan nga adunay organisasyon sa akong katawhan, sa pagpatuman ug sa pagpahimutang sa mga kalihokan sa balay tipiganan alang sa mga kabos sa akong katawhan, dinhi niini nga dapit ug diha sa yuta sa Zion—"},{"verse":4,"text":"Alang sa permanente ug walay kataposang katukoran ug kapunongan sa akong simbahan, sa pagpadayon sa katuyoan, nga inyong gilambigit, sa kaluwasan sa tawo, ug sa himaya sa inyong Amahan nga anaa sa langit;"},{"verse":5,"text":"Nga kamo mahimong patas sa mga gipondo nga langitnong mga butang, oo, ug sa yutan-ong mga butang usab, aron makabaton sa langitnong mga butang."},{"verse":6,"text":"Kay kon kamo dili patas sa yutan-ong mga butang dili kamo mahimong patas sa pagbaton sa langitnong mga butang;"},{"verse":7,"text":"Kay kon gusto ninyo nga hatagan ko kamo og usa ka dapit diha sa celestial nga kalibotan, kinahanglan nga andamon ninyo ang inyong kaugalingon pinaagi sa pagbuhat sa mga butang nga akong gisugo ug gikinahanglan gikan kaninyo."},{"verse":8,"text":"Ug karon, sa pagkatinuod miingon ang Ginoo, angay nga kining tanan nga butang pagahimoon alang sa akong himaya, pinaagi kaninyo nga nagkahiusa dinhi niini nga kapunongan;"},{"verse":9,"text":"O, sa laing pagkasulti, tugoti nga si Newel K. Whitney ug ang akong sulugoon nga si Joseph Smith, Jun., ug ang akong sulugoon nga si Sidney Rigdon molingkod diha sa konseho uban sa mga santos nga anaa sa Zion;"},{"verse":10,"text":"Kay kondili, maninguha si Satanas nga malayo ang ilang mga kasingkasing gikan sa kamatuoran, aron mabutaan sila ug dili makasabot sa mga butang nga giandam alang nila."},{"verse":11,"text":"Mao nga, usa ka sugo ang ihatag nako kaninyo, nga pangandam ug han-aya ang inyong mga kaugalingon pinaagi sa kasabotan o walay kataposang pakigsaad nga dili mahimong lapason."},{"verse":12,"text":"Ug siya nga nakalapas niini mawad-an sa iyang katungdanan ug nahimutangan diha sa simbahan, ug itugyan ngadto sa mga pagkuso-kuso ni Satanas hangtod sa adlaw sa katubsanan."},{"verse":13,"text":"Tan-awa, mao kini ang pagpangandam nga akong giandam kaninyo, ug ang katukoran, ug ang panig-ingnan nga akong ihatag kaninyo, nga niana inyong matuman ang mga sugo nga gihatag kaninyo;"},{"verse":14,"text":"Nga pinaagi sa akong pag-amuma, bisan pa sa kalisdanan nga moabot kaninyo, nga ang simbahan mobarog nga labaw kay sa tanang linalang ubos sa celestial nga kalibotan;"},{"verse":15,"text":"Nga makaangkon kamo sa korona nga giandam alang kaninyo, ug pagahimoong mga magmamando sa daghang gingharian, miingon ang Ginoong Dios, ang Usa nga Balaan sa Zion, nga mipahimutang sa mga katukoran sa Adam-ondi-Ahman;"},{"verse":16,"text":"Kinsa mipili ni Miguel ang inyong prinsipe, ug nagpahimutang sa iyang mga tiil, ug nagbutang kaniya sa itaas, ug gihatag ngadto kaniya ang mga yawe sa kaluwasan ubos sa tambag ug mando sa Usa nga Balaan, kinsa walay sinugdanan sa mga adlaw o kataposan sa kinabuhi."},{"verse":17,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga kamo gagmay pang mga bata, ug wala pa kamo makasabot kon unsa ka dako ang mga panalangin sa Amahan nga anaa sa iyang kaugalingong mga kamot ug giandam alang kaninyo;"},{"verse":18,"text":"Ug dili kamo makaagwanta sa tanang butang karon; bisan pa man, paglipay, kay giyahan ko kamo. Ang gingharian mainyo ug ang mga panalangin niana mainyo, ug ang mga katigayonan sa kahangtoran mainyo."},{"verse":19,"text":"Ug siya nga modawat sa tanang butang uban sa kamapasalamaton himoong mahimayaon; ug ang mga butang niini nga yuta idugang ngadto kaniya, gani sa gatosan ka pilo-pilo, oo, labaw pa."},{"verse":20,"text":"Mao nga, buhata ang mga butang nga akong gisugo kaninyo, miingon ang inyong Manunubos, gani ang Anak nga si Ahman, nga magaandam sa tanang butang sa dili pa siya mokuha kaninyo;"},{"verse":21,"text":"Kay kamo mao ang simbahan sa Unang Natawo, ug siya modala kaninyo sa taas sa panganod, ug mohatag sa matag tawo sa iyang bahin."},{"verse":22,"text":"Ug siya nga matinud-anon ug maalamon nga tinugyanan makapanunod sa tanang butang. Amen."}]},{"chapter":79,"verses":[{"verse":1,"text":"Sa pagkatinuod sultihan ko kamo, nga kabubut-on ko kini nga ang akong sulugoon nga si Jared Carter molakaw pag-usab ngadto sa mga nasod sa silangan nga bahin, gikan sa usa ka dapit ngadto sa laing dapit, ug gikan sa usa ka siyudad ngadto sa laing siyudad, pinaagi sa gahom sa pag-orden diin siya gi-orden, magsangyaw og maayong mga balita sa dako nga kalipay, gani sa walay kataposang ebanghelyo."},{"verse":2,"text":"Ug ipadala nako kaniya ang Maghuhupay, nga motudlo kaniya sa kamatuoran ug sa agianan kon asa siya moadto;"},{"verse":3,"text":"Ug kon magmatinud-anon siya, koronahan ko na usab siya og mga binugkos."},{"verse":4,"text":"Mao nga, tugoti nga ang imong kasingkasing magmaya, akong sulugoong Jared Carter, ug ayaw kahadlok, miingon ang imong Ginoo, gani si Jesukristo. Amen."}]},{"chapter":80,"verses":[{"verse":1,"text":"Sa pagkatinuod, miingon ang Ginoo nganha kanimo akong sulugoong Stephen Burnett: Lakaw, lakaw ngadto sa kalibotan ug isangyaw ang ebanghelyo ngadto sa matag nilalang kutob sa makadungog sa imong tingog."},{"verse":2,"text":"Ug kon nagtinguha ka og kauban, ihatag nako kanimo ang akong sulugoon nga si Eden Smith."},{"verse":3,"text":"Mao nga, panglakaw kamo ug isangyaw ang akong ebanghelyo, ngadto sa amihanan o ngadto sa habagatan, ngadto man sa silangan o ngadto sa kasadpan, dili kana igsapayan, kay dili kamo mangasaag."},{"verse":4,"text":"Busa, ipahayag ang mga butang nga inyong nadungog, ug sa pagkatinuod tuohi, ug hibaloi nga kini tinuod."},{"verse":5,"text":"Tan-awa, kabubut-on niya kini kinsa nagtawag kaninyo, ang inyong Manunubos, gani si Jesukristo. Amen."}]},{"chapter":81,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw akong sulugoon nga Frederick G. Williams: Paminaw sa iyang tingog nga namulong, sa pulong sa Ginoo nga imong Dios, ug patalinghog ngadto sa katungdanan diin ikaw gitawag, gani sa pagkahimong high priest sa akong simbahan, ug magtatambag sa akong sulugoon nga si Joseph Smith, Jun.;"},{"verse":2,"text":"Kinsa gihatagan nako sa mga yawe sa gingharian, nga anaa kanunay sa Unang Kapangulohan sa Halangdon nga Pagkapari:"},{"verse":3,"text":"Busa, sa pagkatinuod giila nako siya ug mopanalangin kaniya, ug usab kanimo, kon ikaw magmatinud-anon sa tambag, sa katungdanan nga akong gisangon kanimo, sa pag-ampo kanunay, sa dayag ug sa imong kasingkasing, diha sa kadaghanan ug sa kinaugalingon, usab sa imong pagpangalagad sa pagsangyaw sa ebanghelyo sa yuta sa mga buhi, ug taliwala sa imong kaigsoonan."},{"verse":4,"text":"Ug sa pagbuhat niining mga butanga gibuhat nimo ang labing dako nga kaayohan ngadto sa imong mga isigkatawo, ug nagpalambo sa himaya kaniya nga imong Ginoo."},{"verse":5,"text":"Mao nga, pagmatinud-anon; barogi ang katungdanan nga gisangon nako kanimo; tabangi ang maluyahon, ipataas ang mga kamot sa nawad-an og paglaom, ug lig-ona ang nahuyang nga mga tuhod."},{"verse":6,"text":"Ug kon magmatinud-anon ka hangtod sa kataposan makaangkon ka og korona sa imortalidad, ug kinabuhing dayon sa mga mansyon nga giandam nako sa balay sa akong Amahan."},{"verse":7,"text":"Tan-awa, ug sud-onga, mao kini ang mga pulong sa Alpha ug Omega, gani si Jesukristo. Amen."}]},{"chapter":82,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, akong mga sulugoon, nga kon kamo nagpasaylo sa usag usa sa inyong mga kalapasan, ingon man usab ako, ang Ginoo, mopasaylo kaninyo."},{"verse":2,"text":"Bisan pa man, aduna kaninyo ang nakasala sa hilabihan; oo, gani ang tanan kaninyo nakasala; apan sa pagkatinuod sultihan ko kamo, pagbantay gikan karon, ug ayaw na pagpakasala, basin pa unya og ang kahapdos sa mga paghukom ipahamtang sa inyong mga ulo."},{"verse":3,"text":"Kay siya nga gihatagan og daghan kaniya daghan ang gikinahanglan; ug siya nga nakasala batok sa mas dako nga kahayag makadawat og mas dako nga panghimaraot."},{"verse":4,"text":"Motawag kamo sa akong ngalan alang sa mga pagpadayag, ug ihatag ko kini kaninyo; ug kon dili kamo mosunod sa akong mga pulong, nga akong gihatag kaninyo, mahimo kamong mga malapason; ug ang hustisya ug ang paghukom mao ang silot nga gitakda sa akong balaod."},{"verse":5,"text":"Busa, kon unsay akong gisulti sa usa, akong isulti ngadto sa tanan: Pagbantay, kay ang kaaway nagpakatap sa iyang mga kamandoan, ug ang kangitngit naghari;"},{"verse":6,"text":"Ug ang kasuko sa Dios napukaw batok sa mga lumulopyo sa yuta; ug walay usa nga naghimo og katarong, kay ang tanan nawala sa dalan."},{"verse":7,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, ako, ang Ginoo, dili mobutang kaninyo nga sad-an sa bisan unsa nga sala; padayon sa inyong kinabuhi ug ayaw na pagpakasala; apan ngadto nianang kalag nga nagpakasala ang kanhi nga mga sala mobalik, miingon ang Ginoo nga inyong Dios."},{"verse":8,"text":"Ug usab, sultihan ko kamo, hatagan ko kamo og bag-o nga sugo, aron inyong masabtan ang akong kabubut-on mahitungod kaninyo;"},{"verse":9,"text":"O, sa laing pagkasulti, hatagan ko kamo og mga panudlo kon unsaon ninyo sa paglihok diha sa akong atubangan, aron kini makatabang kaninyo alang sa inyong kaluwasan."},{"verse":10,"text":"Ako, ang Ginoo, motuman gayod kon mobuhat kamo sa unsay akong gisulti; apan kon kamo dili mobuhat sa unsay akong isulti, dili kamo makaangkon sa saad."},{"verse":11,"text":"Busa, sa pagkatinuod sultihan ko kamo, nga angay nga ang akong mga sulugoon nga si Edward Partridge ug si Newel K. Whitney, si A. Sidney Gilbert ug si Sidney Rigdon, ug ang akong sulugoon nga si Joseph Smith, ug si John Whitmer ug si Oliver Cowdery, ug si W. W. Phelps ug si Martin Harris pagabugkoson nga maghiusa pinaagi sa kasabotan ug pakigsaad nga dili mabungkag pinaagi sa kalapasan, gawas kon ang paghukom mosunod dihadiha dayon, sa lain-laing buluhaton nga gitugyanan kaninyo—"},{"verse":12,"text":"Sa pagdumala sa mga kalihokan sa mga kabos, ug sa tanang butang kalabot sa bishopric sa yuta man sa Zion ug sa yuta sa Kirtland;"},{"verse":13,"text":"Kay akong napahinungod ang yuta sa Kirtland sa akong kaugalingong tukma nga panahon alang sa kaayohan sa mga santos sa Labing Halangdon, ug alang sa stake sa Zion."},{"verse":14,"text":"Kay ang Zion kinahanglan nga motubo sa katahom, ug sa pagkabalaan; ang iyang mga utlanan kinahanglan nga padak-an; ang iyang mga stake kinahanglan nga lig-onon; oo, sa pagkatinuod sultihan ko kamo, ang Zion kinahanglan nga mobangon ug mosul-ob sa iyang mga sapot nga matahom."},{"verse":15,"text":"Busa, hatagan ko kamo niini nga sugo, nga bugkoson ninyo ang inyong mga kaugalingon pinaagi niini nga pakigsaad, ug pagahimoon kini sumala sa mga balaod sa Ginoo."},{"verse":16,"text":"Tan-awa, ania ang kaalam usab ngari kanako alang sa inyong kaayohan."},{"verse":17,"text":"Ug kinahanglan nga kamo patas, o sa laing pagkasulti, patas ang inyong pag-angkon sa mga kabtangan, alang sa kaayohan sa pagdumala sa mga butang nga may kalabotan sa inyong pagkatinugyanan, matag tawo sumala sa iyang tinguha ug sa iyang panginahanglan, kon ang iyang mga tinguha makiangayon—"},{"verse":18,"text":"Ug kining tanan alang sa kaayohan sa simbahan sa buhi nga Dios, nga ang matag tawo mouswag sa iyang talento, nga ang matag tawo makabaton og laing mga talento, oo, gani sa gatosan ka pilo, nga ibutang ngadto sa balay tipiganan sa Ginoo, aron mahimong kabtangan sa tanan sa tibuok simbahan—"},{"verse":19,"text":"Matag tawo magtinguha sa kaayohan sa iyang silingan, ug nagbuhat sa tanang butang uban sa bug-os nga tinguha ngadto sa himaya sa Dios."},{"verse":20,"text":"Kini nga kapunongan akong gihatag kaninyo nga mahimong walay kataposan nga kapunongan, ug sa inyong mga sumusunod, kon kamo dili magpakasala."},{"verse":21,"text":"Ug ang kalag nga nakasala batok niini nga pakigsaad, ug nagpatig-a sa iyang kasingkasing batok niini, pagasilotan sumala sa mga balaod sa akong simbahan, ug itugyan ngadto sa mga pagkuso-kuso ni Satanas hangtod sa adlaw sa katubsanan."},{"verse":22,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, ug mao kini ang kaalam, pakighigala kamo gamit ang inyong katigayonan, ug sila dili molaglag kaninyo."},{"verse":23,"text":"Itugyan ang paghukom ngari kanako, kay kini akoa ug ako ang mobugti. Ang kalinaw magauban kaninyo; ang akong mga panalangin magpadayon uban kaninyo."},{"verse":24,"text":"Kay mainyo ang gingharian karon, ug hangtod sa kahangtoran, kon kamo dili mapukan gikan sa inyong pagkamakanunayon. Ug mao gayod kana. Amen."}]},{"chapter":83,"verses":[{"verse":1,"text":"Sa pagkatinuod, miingon ang Ginoo, agi og dugang sa mga balaod sa simbahan mahitungod sa kababayen-an ug kabataan, niadtong mga nahisakop sa simbahan, nga nawad-an sa ilang mga bana o mga amahan:"},{"verse":2,"text":"Ang kababayen-an may katungod nga makapangayo sa ilang mga bana alang sa ilang kabuhian, hangtod nga ang ilang mga bana wala na; ug kon mapamatud-an nga dili sila mga malapason, makabaton sila og pakigdait sa simbahan."},{"verse":3,"text":"Ug kon dili sila matinud-anon dili sila makabaton og pakigdait sa simbahan; apan maangkon gihapon nila ang ilang mga kabilin sumala sa mga balaod sa yuta."},{"verse":4,"text":"Ang tanang kabataan may katungod nga makapangayo sa ilang mga ginikanan alang sa ilang kabuhian hangtod sila anaa na sa hustong panuigon."},{"verse":5,"text":"Ug human niana, makapangayo sila sa simbahan, o sa laing pagkasulti, sa balay tipiganan sa Ginoo, kon ang ilang mga ginikanan walay ikahatag kanila nga kabilin."},{"verse":6,"text":"Ug ang balay tipiganan pagadumalahon pinaagi sa mga halad sa mga sakop sa simbahan; ug ang mga biyuda ug ang mga ilo pagahatagan, ingon man usab ang mga kabos. Amen."}]},{"chapter":84,"verses":[{"verse":1,"text":"Usa ka pagpadayag ni Jesukristo ngadto sa iyang sulugoon nga si Joseph Smith, Jun., ug sa unom ka elder, samtang nagkahiusa sila sa ilang mga kasingkasing ug mipalanog sa pag-ampo ngadto sa Dios."},{"verse":2,"text":"Oo, ang pulong sa Ginoo mahitungod sa iyang simbahan, nga natukod sa kataposang mga adlaw alang sa pagpahiuli sa iyang katawhan, sumala sa iyang gipamulong pinaagi sa ba-ba sa iyang mga propeta, ug alang sa panagpundok sa iyang mga santos nga mobarog sa Bukid sa Zion, nga mahimong siyudad sa Bag-ong Jerusalem."},{"verse":3,"text":"Nga ang maong siyudad pagatukoron, magsugod sa lote sa templo, nga gipili sa Ginoo Mismo, sa kasadpan nga mga utlanan sa Estado sa Missouri, ug ipahinungod pinaagi sa kamot ni Joseph Smith, Jun., ug sa uban nga gikahimut-an sa Ginoo."},{"verse":4,"text":"Sa pagkatinuod mao kini ang pulong sa Ginoo, nga ang siyudad nga Bag-ong Jerusalem pagatukoron pinaagi sa panagpundok sa mga santos, nga magsugod niining dapita gani ang dapit sa templo, diin nga templo pagatukoron niini nga henerasyon."},{"verse":5,"text":"Kay sa pagkatinuod kini nga henerasyon dili molabay hangtod nga ang usa ka balay matukod ngadto sa Ginoo, ug ang usa ka panganod motabon niini, nga ang maong panganod mao ang himaya sa Ginoo, nga mopuno sa balay."},{"verse":6,"text":"Ug ang mga anak ni Moises, sumala sa Balaan nga Pagkapari nga iyang nadawat, pinaagi sa pagpandong sa mga kamot sa iyang ugangan nga lalaki, nga si Jetro;"},{"verse":7,"text":"Ug nadawat kini ni Jetro pinaagi sa pagpandong sa mga kamot ni Caleb;"},{"verse":8,"text":"Ug nadawat kini ni Caleb pinaagi sa pagpandong sa mga kamot ni Eliu;"},{"verse":9,"text":"Ug si Eliu pinaagi sa pagpandong sa mga kamot ni Jeremy;"},{"verse":10,"text":"Ug si Jeremy pinaagi sa pagpandong sa mga kamot ni Gad;"},{"verse":11,"text":"Ug si Gad pinaagi sa pagpandong sa mga kamot ni Esaias;"},{"verse":12,"text":"Ug si Esaias nakadawat niini pinaagi sa pagpandong sa mga kamot sa Dios."},{"verse":13,"text":"Si Esaias nagpuyo usab sa mga adlaw ni Abraham, ug iyang napanalanginan—"},{"verse":14,"text":"Kana si Abraham nga nakadawat sa pagkapari gikan ni Melchizedek, kinsa nakadawat niini pinaagi sa kaliwatan sa iyang mga amahan, gani hangtod ni Noe;"},{"verse":15,"text":"Ug gikan ni Noe hangtod ni Enoch, pinaagi sa kaliwatan sa ilang mga amahan;"},{"verse":16,"text":"Ug gikan ni Enoch ngadto ni Abel, nga gipatay pinaagi sa tinago nga plano sa iyang igsoon nga lalaki, nga nakadawat sa pagkapari pinaagi sa mga sugo sa Dios, pinaagi sa kamot sa iyang amahan nga si Adan, nga mao ang unang tawo—"},{"verse":17,"text":"Kana nga pagkapari nagpadayon sa simbahan sa Dios sa tanang henerasyon, ug walay sinugdanan sa mga adlaw o kataposan sa mga tuig."},{"verse":18,"text":"Ug ang Ginoo mitugyan usab sa pagkapari diha ni Aaron ug sa iyang binhi, sa panahon sa ilang tanang henerasyon, diin nga pagkapari usab nagpadayon ug nagpabilin sa kahangtoran uban sa pagkapari nga subay sa labing balaan nga kapunongan sa Dios."},{"verse":19,"text":"Ug kining labaw nga pagkapari nangalagad sa ebanghelyo ug naghupot sa yawe sa mga misteryo sa gingharian, gani ang yawe sa kahibalo sa Dios."},{"verse":20,"text":"Busa, diha sa mga ordinansa niana, ang gahom sa pagka-diosnon gipakita."},{"verse":21,"text":"Ug kon walay mga ordinansa niana, ug ang awtoridad sa pagkapari, ang gahom sa pagka-diosnon dili mapakita ngadto sa mga tawo diha sa unod;"},{"verse":22,"text":"Kay kon wala kini walay tawo nga makakita sa nawong sa Dios, bisan sa Amahan, ug mabuhi."},{"verse":23,"text":"Karon kini si Moises yanong nagtudlo sa mga anak ni Israel didto sa kamingawan, ug makugihong nagtinguha sa pagbalaan sa iyang katawhan nga sila makakita sa nawong sa Dios;"},{"verse":24,"text":"Apan gipatig-a nila ang ilang mga kasingkasing ug dili makalahutay sa iyang atubangan; busa, ang Ginoo sa iyang kasuko, kay ang iyang kasuko nagdilaab batok kanila, nanumpa nga dili gayod sila makasulod ngadto sa iyang kapahulayan samtang anaa sa kamingawan, nga ang maong kapahulayan mao ang kahingpitan sa iyang himaya."},{"verse":25,"text":"Busa, gikuha niya si Moises gikan sa ilang taliwala, ug ang Balaan nga Pagkapari usab;"},{"verse":26,"text":"Ug ang mas ubos nga pagkapari nagpadayon, nga ang maong pagkapari naghupot sa yawe sa pagpangalagad sa mga anghel ug sa ebanghelyo sa pagpangandam;"},{"verse":27,"text":"Kana nga ebanghelyo mao ang ebanghelyo sa paghinulsol ug sa bunyag, ug sa kapasayloan sa mga sala, ug ang balaod sa kalibotanon nga mga sugo, diin ang Ginoo sa iyang kasuko mihimo nga magpadayon sa balay ni Aaron taliwala sa mga anak ni Israel hangtod ni Juan, nga gibayaw sa Dios, nga napuno sa Espiritu Santo gikan sa sabakan sa iyang inahan."},{"verse":28,"text":"Kay nabunyagan siya samtang bata pa siya, ug na-orden pinaagi sa anghel sa Dios niadtong nag-edad pa siya og walo ka adlaw ngadto niini nga gahom, aron sa pagbuntog sa gingharian sa mga Judeo, ug sa paghimo nga matul-id ang agianan sa Ginoo sa atubangan sa iyang katawhan, sa pag-andam kanila alang sa pag-anhi sa Ginoo, kansang kamot gihatagan sa tanang gahom."},{"verse":29,"text":"Ug usab, ang mga katungdanan sa elder ug bishop mao ang kinahanglanong mga sumpay ngadto sa halangdon nga pagkapari."},{"verse":30,"text":"Ug usab, ang mga katungdanan sa teacher ug deacon mao ang kinahanglanong mga sumpay nga nahisakop sa mas ubos nga pagkapari, nga ang maong pagkapari gitugyan kang Aaron ug sa iyang mga anak nga lalaki."},{"verse":31,"text":"Busa, sumala sa akong gisulti mahitungod sa mga anak ni Moises—kay ang mga anak nga lalaki ni Moises ug usab ang mga anak nga lalaki ni Aaron mohalad og madawat nga halad ug sakripisyo diha sa balay sa Ginoo, nga ang mao nga balay pagatukuron ngadto sa Ginoo niini nga henerasyon, diha sa gipahinungod nga luna sama sa akong gimando—"},{"verse":32,"text":"Ug ang mga anak nga lalaki ni Moises ug ni Aaron mapuno sa himaya sa Ginoo, diha sa Bukid sa Zion diha sa balay sa Ginoo, kansang mga anak nga lalaki mao kamo; ug usab daghan ang akong gitawag ug gipadala aron sa pagtukod sa akong simbahan."},{"verse":33,"text":"Kay kinsa kadtong matinud-anon sa pag-angkon niining duha ka pagkapari nga akong gipamulong, ug sa pagpalambo sa ilang balaan nga tawag, pagabalaanon pinaagi sa Espiritu ngadto sa pagbag-o sa ilang mga lawas."},{"verse":34,"text":"Mahimo silang mga anak ni Moises ug ni Aaron ug kaliwatni Abraham, ug sa simbahan ug gingharian, ug mga pinili sa Dios."},{"verse":35,"text":"Ug usab silang tanan nga modawat niini nga pagkapari modawat kanako, miingon ang Ginoo;"},{"verse":36,"text":"Kay siya nga modawat sa akong mga sulugoon modawat kanako;"},{"verse":37,"text":"Ug siya nga modawat kanako modawat sa akong Amahan;"},{"verse":38,"text":"Ug siya nga modawat sa akong Amahan modawat sa gingharian sa akong Amahan; busa ang tanan nga anaa sa akong Amahan ihatag ngadto kaniya."},{"verse":39,"text":"Ug kini sumala sa panumpa ug pakigsaad nga nahisakop sa pagkapari."},{"verse":40,"text":"Busa, kadtong tanan nga modawat sa pagkapari, modawat niini nga panumpa ug pakigsaad sa akong Amahan, nga dili niya malapas, ni mausab."},{"verse":41,"text":"Apan kadtong makalapas niini nga pakigsaad human niya kini madawat, ug sa hingpit mobiya gikan niini, walay kapasayloan sa mga sala dinhi niini nga kalibotan ni sa kalibotan nga moabot."},{"verse":42,"text":"Ug alaot kadtong tanan nga dili modawat niini nga pagkapari nga inyong nadawat, nga akong itugyan kaninyo karon kinsa ania niining adlawa, pinaagi sa akong kaugalingon nga tingog gikan sa mga langit; ug gani gisugo nako ang langitnong mga panon ug ang akong mga anghel sa pag-atiman kaninyo."},{"verse":43,"text":"Ug karon hatagan ko kamo og sugo nga bantayi ang inyong mga kaugalingon, magmakugihon sa pagpatalinghog sa mga pulong sa kinabuhing dayon."},{"verse":44,"text":"Kay kamo mabuhi pinaagi sa matag pulong nga mogula gikan sa ba-ba sa Dios."},{"verse":45,"text":"Kay ang pulong sa Ginoo mao ang kamatuoran, ug bisan unsa nga kamatuoran mao ang kahayag, ug bisan unsa nga kahayag mao ang Espiritu, gani ang Espiritu ni Jesukristo."},{"verse":46,"text":"Ug ang Espiritu naghatag og kahayag ngadto sa matag tawo nga mianhi sa kalibotan; ug ang Espiritu naglamdag sa matag tawo sa tibuok kalibotan, nga nagpatalinghog sa tingog sa Espiritu."},{"verse":47,"text":"Ug ang matag usa nga nagpatalinghog sa tingog sa Espiritu moduol ngadto sa Dios, gani ang Amahan."},{"verse":48,"text":"Ug ang Amahan motudlo kaniya bahin sa pakigsaad nga iyang gibag-o ug gitugyan nganha kaninyo, nga gitugyan nganha kaninyo alang sa inyong kaayohan, ug dili lamang alang sa inyong mga kaayohan, apan alang sa kaayohan sa tibuok kalibotan."},{"verse":49,"text":"Ug ang tibuok nga kalibotan naglunang sa sala, ug nag-agulo ilawom sa kangitngit ug ubos sa pagkaulipon sa sala."},{"verse":50,"text":"Ug pinaagi niini inyong masayran nga ubos sila sa pagkaulipon sa sala, tungod kay dili sila moduol kanako."},{"verse":51,"text":"Kay kinsa kadtong dili moduol kanako ubos sa pagkaulipon sa sala."},{"verse":52,"text":"Ug kinsa kadtong dili modawat sa akong tingog wala makasinati sa akong tingog, ug dili akoa."},{"verse":53,"text":"Ug tungod niini masayod kamo sa matarong gikan sa daotan, ug nga ang tibuok kalibotan mag-agulo ubos sa sala ug sa kangitngit bisan karon."},{"verse":54,"text":"Ug ang inyong mga hunahuna sa milabay nga mga panahon nangitngitan tungod sa pagkawalay pagtuo, ug tungod kay gibaliwala ninyo ang mga butang nga inyong nadawat—"},{"verse":55,"text":"Kansang garbo ug pagkawalay pagtuo maoy nakaingon nga ang tibuok simbahan anaa ubos sa panghimaraot."},{"verse":56,"text":"Ug kini nga panghimaraot anaa sa mga anak sa Zion, gani sa tanan."},{"verse":57,"text":"Ug magpabilin sila ubos niini nga panghimaraot hangtod nga sila maghinulsol ug mahinumdom sa bag-o nga pakigsaad, gani ang Basahon ni Mormon ug ang kaniadto nga mga sugo nga akong gihatag kanila, dili lamang isulti, apan buhaton sumala nianang akong gisulat—"},{"verse":58,"text":"Aron makadala sila og bunga nga angay alang sa gingharian sa ilang Amahan; kay kon dili adunay magpabilin nga silot ug paghukom nga ibu-bo diha sa mga anak sa Zion."},{"verse":59,"text":"Kay ang mga anak sa gingharian mohugaw ba sa akong balaan nga yuta? Sa pagkatinuod, sultihan ko kamo, Dili."},{"verse":60,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo kinsa nakadungog karon sa akong mga pulong, nga mao ang akong tingog, bulahan kamo kon dawaton ninyo kining mga butanga;"},{"verse":61,"text":"Kay ako mopasaylo kaninyo sa inyong mga sala uban niini nga sugo—nga kamo magpabilin nga makanunayon sa inyong mga hunahuna sa kaligdong ug sa espiritu sa pag-ampo, sa pagpamatuod ngadto sa tibuok kalibotan bahin niadtong mga butang nga gipahayag nganha kaninyo."},{"verse":62,"text":"Busa, pangadto kamo sa tibuok kalibotan; ug ngadto sa mga dapit nga dili ninyo maadto magpadala kamo, aron ang pagpamatuod nga magagikan kaninyo moabot sa tibuok kalibotan ngadto sa matag linalang."},{"verse":63,"text":"Ug sama sa akong gisulti sa akong mga apostol, sa ingon niana sultihan ko kamo, kay kamo akong mga apostol, gani ang mga high priest sa Dios; kamo mao ang gihatag sa akong Amahan ngari kanako; kamo ang akong mga higala;"},{"verse":64,"text":"Busa, sama sa akong gisulti ngadto sa akong mga apostol sultihan ko kamo pag-usab, nga ang matag kalag nga motuo sa inyong mga pulong, ug mabunyagan pinaagi sa tubig alang sa kapasayloan sa mga sala, makadawat sa Espiritu Santo."},{"verse":65,"text":"Ug kining mga timailhan magauban kanila nga motuo—"},{"verse":66,"text":"Pinaagi sa akong ngalan mohimo sila og daghan nga katingalahang mga buhat;"},{"verse":67,"text":"Pinaagi sa akong ngalan mosalikway sila sa mga yawa;"},{"verse":68,"text":"Pinaagi sa akong ngalan moayo sila sa masakiton;"},{"verse":69,"text":"Pinaagi sa akong ngalan mopabuka sila sa mga mata sa mga buta; ug mopadungog sa mga dunggan sa mga bungol;"},{"verse":70,"text":"Ug ang dila sa amang makasulti;"},{"verse":71,"text":"Ug kon adunay tawo nga mopainom kanila og hilo dili kini makadaot kanila;"},{"verse":72,"text":"Ug ang hilo sa bitin walay gahom sa pagdaot kanila;"},{"verse":73,"text":"Apan usa ka sugo ang akong ihatag kanila, nga dili nila ipanghambog ang ilang mga kaugalingon bahin niining mga butanga, ni isulti kini sa atubangan sa kalibotan; kay kining mga butanga gihatag kaninyo alang sa inyong kaayohan ug alang sa kaluwasan."},{"verse":74,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, sila nga dili motuo sa inyong mga pulong, ug dili magpabunyag sa tubig pinaagi sa akong ngalan, alang sa kapasayloan sa ilang mga sala, aron sila makadawat sa Espiritu Santo, pagasilotan, ug dili makasulod sa gingharian sa akong Amahan diin ang akong Amahan ug ako anaa."},{"verse":75,"text":"Ug kini nga pagpadayag nganha kaninyo, ug ang sugo, mao ang tumanon gikan niini nga takna diha sa tibuok kalibotan, ug ang ebanghelyo alang sa tanang wala makadawat niini."},{"verse":76,"text":"Apan, sa pagkatinuod sultihan ko kadtong tanan nga gihatagan sa gingharian—gikan kaninyo kinahanglan isangyaw kini ngadto kanila, aron maghinulsol sila sa ilang kanhi daotang mga binuhatan; kay kinahanglan nga mabadlong sila sa ilang daotan nga mga kasingkasing tungod sa pagkawalay pagtuo, ug ang inyong kaigsoonan sa Zion tungod sa ilang pagsukol batok kaninyo sa panahon nga gipadala ko kamo."},{"verse":77,"text":"Ug usab sultihan ko kamo, akong mga higala, kay gikan karon tawgon ko kamo og mga higala, angay nga hatagan ko kamo niini nga sugo, aron mahimo kamong sama sa akong mga higala sa mga adlaw nga nakig-uban ako kanila, nagpanaw sa pagsangyaw sa ebanghelyo pinaagi sa akong gahom;"},{"verse":78,"text":"Kay wala ako motugot nga magdala sila og puntil o bag, ni duha ka kupo."},{"verse":79,"text":"Tan-awa, gipadala ko kamo aron sa pagpamatuod ngadto sa kalibotan, ug ang mamumuo takos sa iyang suhol."},{"verse":80,"text":"Ug bisan kinsa nga tawo ang molakaw ug mosangyaw niini nga ebanghelyo sa gingharian, ug wala mapakyas sa padayon nga pagmatinud-anon sa tanang butang, dili kapuyon sa hunahuna, ni magkulang sa panabot, ni kapuyon ang mga lawas, bahin sa lawas, ni ang lutahan; ug ang usa ka buhok sa iyang ulo dili mahulog ngadto sa yuta nga dili mahibaloan. Ug dili sila gutomon, ni uhawon."},{"verse":81,"text":"Busa, ayaw kamo paghunahuna alang sa ugma, kon unsa ang inyong kan-on, o unsa ang inyong imnon, o unsa ang inyong isul-ob."},{"verse":82,"text":"Kay, palandonga ang mga lirio sa umahan, giunsa nila sa pagtubo, wala sila maghago, ni maghimo og sapot; ug ang mga gingharian sa kalibotan, sa ilang tanang himaya, walay katahom sama sa usa niini."},{"verse":83,"text":"Kay ang inyong Amahan, nga tua sa langit, nasayod nga nagkinahanglan kamo niining tanan nga butang."},{"verse":84,"text":"Busa, pasagdi ang ugma nga maoy maghunahuna alang sa mga butang sa iyang kaugalingon."},{"verse":85,"text":"Ni kamo maghunahuna og una sa unsay inyong isulti; apan pagtigom sa kanunay diha sa inyong mga hunahuna og mga pulong sa kinabuhi, ug ihatag kini kaninyo niini nga takna, kana nga bahin nga angayang madawat sa matag tawo."},{"verse":86,"text":"Busa, ayaw tugoti si bisan kinsa kaninyo, kay kini nga sugo alang sa tanang matinud-anon nga gitawag sa Dios diha sa simbahan ngadto sa pangalagad, gikan niini nga takna nga magdala og puntil o bag, nga molakaw aron sa pagpahayag niini nga ebanghelyo sa gingharian."},{"verse":87,"text":"Tan-awa, ipadala ko kamo aron sa pagbadlong sa kalibotan sa ilang tanan nga dili matarong nga binuhatan, ug sa pagtudlo kanila sa usa ka paghukom nga moabot."},{"verse":88,"text":"Ug kinsa kadtong modawat kaninyo, didto anaa usab ako, kay ako magauban kaninyo. Ako anaa sa inyong tuo nga kamot ug sa inyong walà, ug ang akong Espiritu anaa sa inyong mga kasingkasing, ug ang akong mga anghel anaa libot kaninyo, aron sa pagtabang kaninyo."},{"verse":89,"text":"Kinsa kadtong modawat kaninyo modawat kanako; ug mao gihapon ang mopakaon kaninyo, ug mosinina kaninyo, ug mohatag kaninyo og kwarta."},{"verse":90,"text":"Ug siya nga mopakaon kaninyo, o mosinina kaninyo, ug mohatag kaninyo og kwarta, dili gayod mawad-an sa iyang ganti."},{"verse":91,"text":"Ug siya nga dili mobuhat niining mga butanga dili akong disipulo; pinaagi niini kamo makaila sa akong mga disipulo."},{"verse":92,"text":"Siya nga dili modawat kaninyo, palayo kamong mag-inusara gikan kaniya, ug limpyohi ang inyong mga tiil gamit ang tubig, lunsay nga tubig, init man o bugnaw, ug pagpamatuod bahin niini ngadto sa inyong Amahan nga tua sa langit, ug ayaw na balika pag-usab kana nga tawo."},{"verse":93,"text":"Ug sa bisan unsa nga baryo o siyudad nga inyong sudlan, buhata ang mao gihapon."},{"verse":94,"text":"Bisan pa niana, magkugi sa pagpangita ug ayaw paghunong; ug alaot kana nga balay, o kana nga baryo o siyudad nga misalikway kaninyo, o sa inyong mga pulong, o sa inyong pagpamatuod mahitungod kanako."},{"verse":95,"text":"Alaot, sublion ko sa pagsulti, kana nga balay, o kana nga baryo o siyudad nga misalikway kaninyo o sa inyong mga pulong, o sa inyong pagpamatuod kanako;"},{"verse":96,"text":"Kay ako, ang Labawng Makagagahom, migamit sa akong mga kamot diha sa mga nasod, sa pagsilot kanila tungod sa ilang pagkadaotan."},{"verse":97,"text":"Ug ang mga sakit nga midagsang magpadayon, ug dili kini pagakuhaon gikan sa yuta hangtod nga makompleto nako ang akong buluhaton, nga daling matapos sumala sa pagkamatarong—"},{"verse":98,"text":"Hangtod ang tanan makaila kanako, kinsa magpabilin, bisan gikan sa labing ubos ngadto sa labing taas, ug mapuno sa kahibalo mahitungod sa Ginoo, ug makakita, ug mopataas sa ilang mga tingog, ug sa dungan nga tingog manag-awit niining bag-o nga awit, nga mag-ingon:"},{"verse":99,"text":"Gipahiuli sa Ginoo ang Zion;Gitubos sa Ginoo ang iyang katawhan, ang Israel,Sumala sa pagpili pinaagi sa grasya,Nga nahitabo pinaagi sa pagtuoUg sa pakigsaad sa ilang mga amahan."},{"verse":100,"text":"Ang Ginoo mitubos sa iyang katawhan;Ug si Satanas gigapos ug ang panahon natapos na.Ang Ginoo mipundok sa tanang butang ngadto sa usa ka pundok.Ang Ginoo mipakanaog sa Zion gikan sa kahitas-an.Ang Ginoo mibayaw sa Zion gikan sa yuta."},{"verse":101,"text":"Ang yuta naglisod ug mipagula sa iyang kusog;Ug ang kamatuoran iyang gibati sa kasingkasing;Ug ang mga kalangitan mipahiyom kaniya;Ug gisul-oban siya sa himaya sa iyang Dios;Kay nagbarog siya taliwala sa iyang katawhan."},{"verse":102,"text":"Ang himaya, ug dungog, ug gahom, ug kusog,Maanaa kanunay sa atong Dios; kay siya puno sa kaluoy,Kaangayan, grasya ug kamatuoran, ug kalinaw,Hangtod sa kahangtoran, Amen."},{"verse":103,"text":"Ug usab, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, angay nga ang matag tawo nga molakaw aron mopahayag sa akong walay kataposan nga ebanghelyo, nga tungod kay sila adunay mga pamilya, ug modawat og kwarta pinaagi sa gasa, sila kinahanglan mopadala niini ngadto kanila o mogamit niini alang sa ilang kaayohan, sumala sa gimando sa Ginoo kanila, kay ang ingon niana maayo alang kanako."},{"verse":104,"text":"Ug himoa nga kadtong tanan nga walay mga pamilya, nga modawat og kwarta, mopadala niini ngadto sa bishop sa Zion, o ngadto sa bishop sa Ohio, aron mapahinungod kini alang sa pagmantala sa mga pagpadayag ug sa pagpa-imprinta niini, ug alang sa pagtukod sa Zion."},{"verse":105,"text":"Ug kon adunay tawo nga mohatag ni bisan kinsa kaninyo og usa ka kupo, o usa ka terno nga parisan, dad-a ang daan ug ihatag kini sa kabos, ug lakaw nga magmaya."},{"verse":106,"text":"Ug kon adunay tawo uban kaninyo nga lig-on pinaagi sa Espiritu, tugoti siya nga ipadala kaniya siya nga huyang, aron siya mahatagan og kaayohan sa tanan nga kaaghop, aron siya malig-on usab."},{"verse":107,"text":"Busa, dad-a ninyo kadtong gi-orden ngadto sa ubos nga pagkapari, ug ipadala sila gikan kaninyo aron sa paghimo og mga pakigsabot, ug sa pag-andam sa agianan, ug sa paghimo sa pakigsabot nga dili ninyo mahimo."},{"verse":108,"text":"Tan-awa, ingon niini ang gihimo sa akong mga apostol, sa karaang mga adlaw, sa pagtukod sa akong simbahan ngari kanako."},{"verse":109,"text":"Busa, himoa nga ang matag tawo mobarog sa iyang kaugalingon nga katungdanan, ug motrabaho sa iyang kaugalingon nga balaang tawag; ug ayaw tugoti nga ang ulo moingon sa mga tiil nga wala kini magkinahanglan sa tiil; kay kon walay tiil unsaon pagbarog sa lawas?"},{"verse":110,"text":"Ang lawas nagkinahanglan usab sa matag sakop, aron ang tanan mahatagan og kaayohan, aron ang tibuok organisasyon mahimong hingpit."},{"verse":111,"text":"Ug tan-awa, ang mga high priest kinahanglan nga mobiyahe, ug ang mga elder usab, ug ang mas ubos usab nga mga priest; apan ang mga deacon, ug ang mga teacher kinahanglang sangonan nga mobantay sa simbahan, aron magpabilin nga tigpangalagad sa simbahan."},{"verse":112,"text":"Ug ang bishop, si Newel K. Whitney, kinahanglan mobiyahe usab sa palibot ug taliwala sa tanang simbahan, mangita sa mga kabos aron makapangalagad sa ilang mga panginahanglan pinaagi sa pagpaubos sa mga adunahan ug mga mapahitas-on."},{"verse":113,"text":"Siya kinahanglan usab mosuhol, og usa ka tinugyanan sa pagdumala ug sa pagbuhat sa iyang pang-sekular nga buluhaton sumala sa iyang imando."},{"verse":114,"text":"Bisan pa niana, himoa nga ang bishop moadto sa siyudad sa New York, sa siyudad usab sa Albany, ug sa siyudad usab sa Boston, ug mopasidaan sa katawhan niadtong mga siyudad pinaagi sa tingog sa ebanghelyo, sa makusog nga tingog, mahitungod sa pagkagun-ob ug sa hingpit nga pagkalaglag nga nagpaabot kanila kon isalikway nila kining mga butanga."},{"verse":115,"text":"Kay kon isalikway nila kining mga butanga ang takna nga sila hukman duol na, ug ang ilang balay biyaan nila nga magmingaw."},{"verse":116,"text":"Himoa nga mosalig siya kanako ug dili siya pagalibogon; ug ang usa ka buhok sa iyang ulo dili mahulog sa yuta nga dili mahibaloan."},{"verse":117,"text":"Ug sa pagkatinuod sultihan ko kamong mga nahibilin sa akong mga sulugoon, panglakaw kamo kon itugot sa inyong mga kahimtang, sa inyong pipila ka balaang mga tawag, ngadto sa dako ug inila nga mga siyudad ug mga baryo, magbadlong sa kalibotan tungod sa ilang tanang dili matarong ug mga buhat nga dili diosnon, nagpasabot sa klaro nga paagi sa kalaglagan sa mga daotan sa kataposang mga adlaw."},{"verse":118,"text":"Kay, kaninyo miingon ang Ginoo nga Labawng Makagagahom, lumpagon ko ang ilang mga gingharian; dili lang kay akong uyogon ang yuta, apan ang kalangitan nga puno sa bitoon mokurog."},{"verse":119,"text":"Kay ako, ang Ginoo, nagpahimutang sa akong kamot sa pagpalihok sa mga gahom sa langit; kamo dili makakita niini karon, apan sa dili madugay makita ninyo kini, ug masayod nga ako mao, ug nga ako moabot ug mohari kauban sa akong katawhan."},{"verse":120,"text":"Ako ang Alpha ug Omega, ang sinugdanan ug ang kataposan. Amen."}]},{"chapter":85,"verses":[{"verse":1,"text":"Katungdanan sa klerk sa Ginoo, nga iyang pinili, ang pagsulat og kasaysayan, ug kinatibuk-an nga talaan sa simbahan bahin sa mga butang nga nahitabo sa Zion, ug niadtong tanan nga mopahinungod sa mga kabtangan, ug modawat og mga kabilin sa legal nga paagi gikan sa bishop;"},{"verse":2,"text":"Ug usab sa pamaagi nila sa pagpakabuhi, sa ilang pagtuo, ug mga buluhaton; ug usab sa mga mibiya sa tinuohan kinsa mibiya sa kamatuoran human makadawat sa ilang mga kabilin."},{"verse":3,"text":"Supak sa kabubut-on ug sugo sa Dios nga kadtong wala modawat sa ilang kabilin pinaagi sa pagpahinungod, sumala sa iyang balaod, nga iyang gihatag, aron siya mopabayad og ikapulo sa iyang katawhan, sa pag-andam kanila batok sa adlaw sa pagpanimalos ug pagsunog, magpalista sa ilang mga ngalan uban sa katawhan sa Dios."},{"verse":4,"text":"Ni ang ilang mga kasaysayan sa kagikanan pagatipigan, o makuha kon asa kini makit-an sa bisan hain sa mga talaan o kasaysayan sa simbahan."},{"verse":5,"text":"Ang ilang mga ngalan dili makit-an, ni ang mga ngalan sa ilang mga amahan, ni ang mga ngalan sa ilang mga anak nga mahisulat sa basahon sa balaod sa Dios, nag-ingon ang Ginoo sa mga Panon."},{"verse":6,"text":"Oo, sa ingon niana miingon ang ligdong nga hinagawhaw nga tingog, nga mihunghong ug midulot sa tanang butang, ug sa makadaghan nga higayon kini nakapakurog sa akong mga bukog samtang nagpakita kini, nga nag-ingon:"},{"verse":7,"text":"Ug mahitabo nga ako, ang Ginoong Dios, mopadala sa usa ka gamhanan ug adunay abilidad sa pagdani, nagkupot sa sungkod sa gahom diha sa iyang kamot, gisul-oban sa kahayag, kansang ba-ba molitok og mga pulong, mga pulong nga mahangtoron; samtang ang iyang kasingkasing mahimong tinubdan sa kamatuoran, sa paghan-ay sa balay sa Dios, ug sa paghan-ay pinaagi sa pagripa sa mga kabilin sa mga santos kansang mga ngalan makita, ug ang mga ngalan sa ilang mga amahan, ug sa ilang mga anak, nga nalista diha sa basahon sa balaod sa Dios;"},{"verse":8,"text":"Samtang kana nga tawo, nga gitawag sa Dios ug gipili, nga mopahimutang sa iyang kamot sa pagpahunong sa arka sa Dios, mamatay pinaagi sa pana sa kamatayon, sama sa usa ka kahoy nga naigo sa liti sa kilat."},{"verse":9,"text":"Ug silang tanan nga wala makit-i nga nahisulat sa basahon sa handomanan dili makadawat og kabilin niana nga adlaw, apan ipahimulag sila, ug ang ilang bahin ihatag ngadto sa mga dili matuohon, diin adunay pag-agulo ug pagpangagot sa mga ngipon."},{"verse":10,"text":"Kining mga butanga dili nako isulti sa akong kaugalingon; busa, sumala sa gipamulong sa Ginoo, iya usab nga tumanon."},{"verse":11,"text":"Ug sila nga anaa sa Labaw nga Pagkapari, kansang mga ngalan dili makit-an nga nahisulat sa basahon sa balaod, o nga nakit-an nga mibiya sa kamatuoran, o gipahimulag, gikan sa simbahan, ingon man usab sa mas ubos nga pagkapari, o ang mga sakop, nianang adlawa dili makadawat og kabilin kauban sa mga santos sa Labing Halangdon;"},{"verse":12,"text":"Busa, pagahimoon ngadto kanila ang sama sa mga anak sa mga pari, sama sa makit-an nga narekord sa ikaduhang kapitulo ug ikakan-uman ug usa ug ikaduhang mga bersikulo sa Esdras."}]},{"chapter":86,"verses":[{"verse":1,"text":"Sa pagkatinuod, nag-ingon ang Ginoo kaninyo akong mga sulugoon, mahitungod sa sambingay sa trigo ug sa mga sagbot:"},{"verse":2,"text":"Tan-awa, sa pagkatinuod moingon ko, ang umahan mao ang kalibotan, ug ang mga apostol mao ang mga tigsabwag sa mga binhi;"},{"verse":3,"text":"Ug human sila makatulog ang gamhanan nga tiglutos sa simbahan, ang mibiya sa tinuohan, ang nagbaligya og dungog, bisan ang Babilon, nga mipainom sa tanang nasod sa iyang kopa, kansang mga kasingkasing iya sa kaaway, bisan si Satanas, milingkod sa paghari—tan-awa misabwag siya og mga sagbot; busa, ang mga sagbot mituok sa trigo ug miabog sa simbahan ngadto sa kamingawan."},{"verse":4,"text":"Apan tan-awa, sa kataposang mga adlaw, bisan karon samtang ang Ginoo nagsugod sa pagdala sa pulong, ug ang udlot migitib ug gani linghod pa—"},{"verse":5,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, ang mga anghel nangamuyo sa Ginoo maadlaw ug magabii, kinsa andam na ug naghulat nga ipadala sa pag-ani sa mga umahan;"},{"verse":6,"text":"Apan gisultihan sila sa Ginoo, ayaw ibta ang mga sagbot samtang ang udlot linghod pa (kay sa pagkatinuod ang inyong pagtuo huyang), basin pa unya og inyong maibot usab ang trigo."},{"verse":7,"text":"Busa, itugot nga ang trigo ug ang mga sagbot magdungan sa pagtubo hangtod sa pag-ani; unya kamo moani pag-una sa trigo gikan sa mga sagbot, ug human sa pagpundok sa trigo, tan-awa ug sud-onga, ang mga sagbot bugkoson, ug ang umahan ibilin aron sunogon."},{"verse":8,"text":"Busa, sa ingon niana miingon ang Ginoo kaninyo, diin ang pagkapari nagpadayon pinaagi sa kaliwatan sa inyong mga amahan—"},{"verse":9,"text":"Kay kamo mao ang adunay katungod nga manununod, sumala sa kaliwatan, ug natago gikan sa kalibotan kauban ni Kristo sa Dios—"},{"verse":10,"text":"Busa ang inyong kinabuhi ug ang pagkapari nagpabilin, ug kinahanglan nga magpabilin pinaagi kaninyo ug sa inyong kaliwatan hangtod sa pagpahiuli sa tanang butang nga gipamulong sa mga ba-ba sa tanang balaan nga propeta sukad sa sinugdanan sa kalibotan."},{"verse":11,"text":"Busa, bulahan kamo kon padayon ninyong dawaton ang akong pagkamaayo, usa ka kahayag sa mga Hentil, ug pinaagi niini nga pagkapari, usa ka manluluwas sa akong katawhan sa Israel. Ang Ginoo nag-ingon niini. Amen."}]},{"chapter":87,"verses":[{"verse":1,"text":"Sa pagkatinuod, nagsulti ang Ginoo mahitungod sa mga gubat nga mahitabo sa dili madugay, magsugod sa rebelyon sa Habagatang Carolina, nga sa kataposan moresulta sa kamatayon ug pagkaalaot sa daghang kalag;"},{"verse":2,"text":"Ug ang panahon moabot nga ang gubat ibu-bo sa tanang nasod, sugod niining dapita."},{"verse":3,"text":"Kay tan-awa, ang Habagatang mga Estado mabahin batok sa Amihanang mga Estado, ug ang Habagatang mga Estado motawag sa ubang nasod, bisan ang nasod sa Britanya, nga maoy tawag niini, ug sila usab motawag sa ubang nasod, sa pagpanalipod sa ilang mga kaugalingon batok sa ubang nasod; ug unya ang gubat ibu-bo ngadto sa tanang nasod."},{"verse":4,"text":"Ug mahitabo, human sa daghang adlaw, ang mga ulipon moalsa batok sa ilang mga agalon, kinsa pagapundokon ug pagabansayon alang sa gubat."},{"verse":5,"text":"Ug mahitabo usab nga ang mga salin nga nahibilin sa yuta mopundok sa ilang mga kaugalingon, ug masuko sa hilabihan, ug mosakit sa mga Hentil uban sa hilabihan nga kasakit."},{"verse":6,"text":"Ug sa ingon niana, pinaagi sa espada ug sa pagpaagas sa dugo, ang mga lumulupyo sa yuta magbangotan; ug tungod sa kagutom, ug kasakit, ug sa linog, ug sa dugdog sa langit, ug sa mabangis ug masanag nga kilat usab, mabatyagan sa mga lumulupyo sa yuta ang kapungot, ug kasuko, ug ang mga kamot sa pagpanton gikan sa Makagagahom nga Dios, hangtod matapos sa hingpit ang gitakda nga kalaglagan sa tanang nasod;"},{"verse":7,"text":"Nga ang pangamuyo sa mga santos, ug ang dugo sa mga santos, mohunong sa pagsaka ngadto sa mga dunggan sa Ginoo nga Labing Gamhanan, gikan sa yuta, nga mapanimaslan ang ilang mga kaaway."},{"verse":8,"text":"Mao nga, barog kamo sa balaang mga dapit, ug ayaw pagbalhin, hangtod ang adlaw sa Ginoo moabot; kay tan-awa, moabot kini sa labing madali, miingon ang Ginoo. Amen."}]},{"chapter":88,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niini misulti ang Ginoo nganha kaninyong nagkapundok sa inyong mga kaugalingon aron modawat sa iyang kabubut-on mahitungod kaninyo:"},{"verse":2,"text":"Tan-awa, makapahimuot kini sa inyong Ginoo, ug ang mga anghel magmaya kaninyo; ang mga halad sa inyong mga pag-ampo miabot sa mga dunggan sa Ginoo nga labing Makagagahom, ug narekord sa basahon sa mga ngalan sa gibalaan, gani kanila nga anaa sa celestial nga kalibotan."},{"verse":3,"text":"Mao nga, ipadala ko karon kaninyo ang laing Maghuhupay, gani kaninyo akong mga higala, nga magpabilin kini sa inyong mga kasingkasing, gani ang Balaan nga Espiritu sa saad; nga mao ang laing Maghuhupay nga akong gisaad sa akong mga disipulo, sumala sa narekord sa pagpamatuod ni Juan."},{"verse":4,"text":"Kini nga Maghuhupay mao ang saad nga ihatag ko kaninyo mahitungod sa kinabuhing dayon, gani ang himaya sa celestial nga gingharian;"},{"verse":5,"text":"Kana nga himaya mao ang simbahan sa Unang Natawo, gani ang Dios, ang labing balaan sa tanan, pinaagi ni Jesukristo nga iyang Anak—"},{"verse":6,"text":"Siya nga mikayab sa kahitas-an, ingon nga siya usab mikunsad paubos sa tanang butang, nga niana iyang masabtan ang tanang butang, aron maanaa siya sa tanan ug agi sa tanang butang, ang kahayag sa kamatuoran;"},{"verse":7,"text":"Nga ang mao nga kamatuoran midan-ag. Mao kini ang kahayag ni Kristo. Siya usab anaa sa adlaw, ug ang kahayag sa adlaw, ug ang gahom niana diin kini nabuhat."},{"verse":8,"text":"Siya usab anaa sa bulan, ug mao ang kahayag sa bulan, ug ang gahom niana diin kini nabuhat;"},{"verse":9,"text":"Mao usab ang kahayag sa mga bitoon, ug ang gahom niana diin kini nabuhat;"},{"verse":10,"text":"Ug ang yuta usab, ug ang gahom niana, gani ang yuta nga inyong gibarogan."},{"verse":11,"text":"Ug ang kahayag nga nagdan-ag, nga naghatag kaninyo og kahayag, naggikan kaniya kinsa naglamdag sa inyong mga mata, nga mao gihapon nga kahayag nga nakapadugang sa inyong mga pagsabot;"},{"verse":12,"text":"Nga ang maong kahayag naggikan sa presensya sa Dios aron mopuno sa kalapdon sa kawanangan—"},{"verse":13,"text":"Ang kahayag nga anaa sa tanang butang, nga naghatag og kinabuhi sa tanang butang, nga mao ang balaod nga nagdumala sa tanang butang, gani ang gahom sa Dios kinsa naglingkod sa iyang trono, kinsa anaa sa taliwala sa kahangtoran, nga anaa sa taliwala sa tanang butang."},{"verse":14,"text":"Karon, sa pagkatinuod sultihan ko kamo, nga pinaagi sa katubsanan nga nabuhat alang kaninyo nahitabo ang pagkabanhaw gikan sa mga patay."},{"verse":15,"text":"Ug ang espiritu ug ang lawas mao ang kalag sa tawo."},{"verse":16,"text":"Ug ang pagkabanhaw gikan sa mga patay mao ang katubsanan sa kalag."},{"verse":17,"text":"Ug ang katubsanan sa kalag pinaagi kaniya naghatag og kinabuhi sa tanang butang, kansang dughan nagtakda nga ang mga kabos ug ang maaghop sa yuta makapanunod niini."},{"verse":18,"text":"Busa, gikinahanglan gayod nga pagabalaanon kini gikan sa tanan nga dili matarong, aron maandam kini alang sa celestial nga himaya;"},{"verse":19,"text":"Kay human sa katumanan sa katuyoan sa pagkalalang niini, pagakoronahan kini og himaya, gani sa presensya sa Dios nga Amahan;"},{"verse":20,"text":"Nga ang nabanhaw nga mga tawo kinsa anaa sa celestial nga gingharian makabaton niini hangtod sa kahangtoran; kay, alang niini nga katuyoan kini nabuhat ug nalalang, ug alang niini nga katuyoan sila gipakabalaan."},{"verse":21,"text":"Ug sila nga wala mabalaan pinaagi sa balaod nga akong gihatag kaninyo, gani sa balaod ni Kristo, kinahanglan gayod makapanunod og lain nga gingharian, gani kana nga terrestrial nga gingharian, o kana nga telestial nga gingharian."},{"verse":22,"text":"Kay siya nga dili makatuman sa balaod sa celestial nga gingharian dili makalahutay sa celestial nga himaya."},{"verse":23,"text":"Ug siya nga dili makatuman sa balaod sa terrestrial nga gingharian dili makalahutay sa terrestrial nga himaya."},{"verse":24,"text":"Ug siya nga dili makatuman sa balaod sa telestial nga gingharian dili makalahutay sa telestial nga himaya; busa dili siya angay alang sa gingharian sa himaya. Busa adto siya mopuyo sa usa ka gingharian nga dili usa ka gingharian sa himaya."},{"verse":25,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ang yuta nagtuman sa balaod sa celestial nga gingharian, kay mipuno kini sa sukod sa iyang pagkalalang, ug wala makalapas sa balaod—"},{"verse":26,"text":"Mao nga, pagabalaanon kini; oo, bisan pa og kini mamatay, pagabuhion kini pag-usab, ug makalahutay sa gahom diin kini gibuhi, ug ang mga matarong makapanunod niini."},{"verse":27,"text":"Kay bisan pa og mamatay sila, mobangon sila pag-usab, sa usa ka espirituwal nga lawas."},{"verse":28,"text":"Sila nga anaa sa celestial nga espiritu makadawat sa mao gihapon nga lawas nga mao ang kinaiyanhon nga lawas; gani kamo makadawat sa inyong mga lawas, ug ang inyong himaya nga mao kana nga himaya diin ang inyong mga lawas mabuhi."},{"verse":29,"text":"Kamo nga gipabuhi pinaagi sa usa ka bahin sa celestial nga himaya makadawat unya sa mao gihapon, gani sa kahingpitan."},{"verse":30,"text":"Ug sila nga gibuhi pinaagi sa usa ka bahin sa terrestrial nga himaya makadawat unya sa mao gihapon, gani sa kahingpitan."},{"verse":31,"text":"Ug usab sila nga buhion pinaagi sa usa ka bahin sa telestial nga himaya makadawat unya sa mao gihapon, gani sa kahingpitan."},{"verse":32,"text":"Ug sila nga nahibilin buhion pag-usab; bisan pa niana, mobalik sila pag-usab sa ilang kaugalingon nga dapit, aron makatagamtam nianang ilang andam nga dawaton, tungod kay dili sila andam nga motagamtam nianang unta ilang madawat."},{"verse":33,"text":"Kay unsay kaayohan nga makuha sa usa ka tawo kon ihatag ang gasa kaniya, ug dili siya modawat sa gasa? Tan-awa, wala siya malipay nianang gihatag diha kaniya, ni malipay kaniya nga naghatag sa gasa."},{"verse":34,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kana nga gidumala pinaagi sa balaod mao usab ang tipigan pinaagi sa balaod ug gihingpit ug gibalaan pinaagi sa balaod."},{"verse":35,"text":"Kana nga misupak sa usa ka balaod, ug wala mosunod sa balaod, apan nangandoy nga mahimong balaod sa iyang kaugalingon, ug andam nga magpabilin diha sa sala, ug sa hingpit magpabilin sa sala, dili mabalaan sa balaod, ni pinaagi sa kaluoy, kaangayan, ni paghukom. Busa, magpabilin gihapon sila nga mahugaw."},{"verse":36,"text":"Ang tanang gingharian adunay gihatag nga balaod;"},{"verse":37,"text":"Ug adunay daghang gingharian; kay walay luna nga walay gingharian; ug walay gingharian nga walay luna, mas taas man o mas ubos nga gingharian."},{"verse":38,"text":"Ug didto sa matag gingharian gihatagan og usa ka balaod; ug ngadto sa matag balaod adunay piho nga mga limitasyon usab ug mga kondisyon."},{"verse":39,"text":"Ang tanang binuhat nga wala motuman niadtong mga kondisyon dili kahatagan og kaangayan."},{"verse":40,"text":"Kay ang salabotan mounong sa salabotan; ang kaalam modawat og kaalam; ang kamatuoran mohangop sa kamatuoran; ang hiyas mohigugma sa hiyas; ang kahayag mounong sa kahayag; ang kaluoy adunay kapuangod sa kaluoy ug moangkon sa unsay iya niini; ang kaangayan mopadayon sa tumong niini ug moangkon sa unsay iya niini; ang paghukom mag-una sa atubangan kaniya nga naglingkod sa trono ug nagdumala ug nagpatuman sa tanang butang."},{"verse":41,"text":"Masabtan niya ang tanang butang, ug ang tanang butang anaa sa iyang atubangan, ug ang tanang butang anaa sa iyang palibot; ug siya labaw sa tanang butang, ug diha sa tanang butang, ug pinaagi sa tanang butang, ug anaa palibot sa tanang butang; ug ang tanang butang gihimo pinaagi kaniya, ug gikan kaniya, gani ang Dios, hangtod sa kahangtoran."},{"verse":42,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, mihatag siya og balaod ngadto sa tanang butang, kon giunsa nila sa paglihok ang ilang mga higayon ug ang ilang mga panahon;"},{"verse":43,"text":"Ug ang ilang mga agianan natino na, bisan ang mga agianan sa kalangitan ug ang kalibotan, nga naglangkob sa kalibotan ug sa tanang planeta."},{"verse":44,"text":"Ug naghatag kini og kahayag ngadto sa usag usa diha sa ilang mga higayon ug sa ilang mga panahon, sa ilang mga gutlo, sa ilang mga takna, sa ilang mga adlaw, sa ilang mga semana, sa ilang mga bulan, sa ilang mga tuig—kining tanan usa ka tuig sa Dios, apan dili sa tawo."},{"verse":45,"text":"Ang kalibotan nagtuyok pinaagi sa mga pako niini, ug ang adlaw mohatag sa kahayag niini maadlaw, ug ang bulan mohatag sa kahayag niini magabii, ug ang mga bitoon usab mohatag sa kahayag niini, samtang magtuyok kini pinaagi sa mga pako niini diha sa himaya niini, taliwala sa gahom sa Dios."},{"verse":46,"text":"Asa nako ikapahisama kini nga mga gingharian, aron kamo makasabot?"},{"verse":47,"text":"Tan-awa, kining tanang gingharian, ug si bisan kinsa nga tawo nga nakakita sa bisan hain o sa labing gamay niini nakakita sa Dios nga naglihok sa iyang pagkahalangdon ug gahom."},{"verse":48,"text":"Sultihan ko kamo, nakakita siya kaniya; bisan pa niana, siya nga mianha sa iyang kaugalingong katawhan wala masabti."},{"verse":49,"text":"Ang kahayag midan-ag sa kangitngit, ug ang kangitngit wala makasabot niini; bisan pa niana, ang adlaw moabot nga kamo makasabot gani ang Dios, nga gibuhi diha kaniya ug pinaagi kaniya."},{"verse":50,"text":"Dayon masayod kamo nga nakakita kamo kanako, nga ako mao, ug nga ako mao ang tinuod nga kahayag nga anaa kaninyo, ug nga kamo ania kanako; kay kon dili kamo dili magmalamposon."},{"verse":51,"text":"Tan-awa, ipahisama ko kining mga gingharian ngadto sa usa ka tawo nga adunay umahan, ug gipadala niya ang iyang mga sulugoon ngadto sa umahan aron pagbugwal sa umahan."},{"verse":52,"text":"Ug gisultihan niya ang nag-una: Lakaw ug pagtrabaho sa umahan, ug sa unang oras anhaon ko ikaw, ug makita nimo ang kamaya sa akong panagway."},{"verse":53,"text":"Ug gisultihan niya ang ikaduha: Lakaw usab ngadto sa umahan, ug sa ikaduhang oras duawon ko ikaw uban sa kamaya sa akong panagway."},{"verse":54,"text":"Ug usab sa ikatulo, nag-ingon: Duawon ko ikaw;"},{"verse":55,"text":"Ug ngadto sa ikaupat, ug hangtod sa ikanapulog duha."},{"verse":56,"text":"Ug ang agalon sa umahan miadto sa nag-una sa unang oras, ug nagpabilin uban kaniya sa tibuok oras, ug nagmalipayon siya sa kasanag sa panagway sa iyang agalon."},{"verse":57,"text":"Ug dayon mibiya siya gikan sa nag-una aron duawon usab niya ang ikaduha, ug sa ikatulo, ug sa ikaupat, ug hangtod sa ikanapulog duha."},{"verse":58,"text":"Ug sa ingon niana silang tanan nakadawat sa kahayag sa panagway sa ilang agalon, ang matag tawo sa iyang oras, ug sa iyang mugbo nga higayon, ug sa iyang panahon—"},{"verse":59,"text":"Nagsugod sa nag-una, ug hangtod sa kataposan, ug gikan sa kataposan hangtod sa nag-una, ug gikan sa nag-una hangtod sa kataposan;"},{"verse":60,"text":"Matag tawo sa iyang kaugalingong dapit nga nahimutangan/puwesto, hangtod nga natapos ang iyang oras, gani sumala sa gisugo sa agalon kaniya, aron ang iyang agalon pagahimayaon pinaagi kaniya, ug siya pinaagi sa iyang agalon, silang tanan pagahimayaon."},{"verse":61,"text":"Busa, kini nga sambingay akong ipahisama niining tanang gingharian, ug sa mga lumulupyo niana—matag gingharian sa takna niini, ug sa iyang panahon, ug sa tiyempo niini, gani sumala sa mando nga gibuhat sa Dios."},{"verse":62,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, akong mga higala, ibilin ko kining mga panultihon nganha kaninyo aron pamalandongan diha sa inyong mga kasingkasing, uban niini nga sugo nga akong ihatag kaninyo, aron kamo motawag kanako samtang ania pa ako sa duol—"},{"verse":63,"text":"Paduol kamo kanako ug ako mopaduol kaninyo; pagkugi kamo sa pagpangita kanako ug kamo makakaplag kanako; pangayo, ug kamo makadawat; tuktok, ug kini pagaablihan nganha kaninyo."},{"verse":64,"text":"Bisan unsa ang inyong pangayoon sa Amahan pinaagi sa akong ngalan nga angay alang kaninyo ihatag kini kaninyo;"},{"verse":65,"text":"Ug kon mangayo kamo og bisan unsa nga dili angay alang kaninyo, mosangpot kini nga silotan hinuon kamo."},{"verse":66,"text":"Tan-awa, kanang inyong nadungog sama kana sa tingog sa usa nga nagsinggit didto sa kamingawan—didto sa kamingawan, tungod kay dili kamo makakita kaniya—sa akong tingog, tungod kay ang akong tingog mao ang Espiritu; ang akong Espiritu mao ang kamatuoran; ang kamatuoran magpadayon ug walay kataposan; ug kon kini anaa kaninyo kini molambo."},{"verse":67,"text":"Ug kon ang inyong mata bug-os ngadto sa akong himaya, ang inyong tibuok kalawasan mapuno sa kahayag, ug walay kangitngit diha kaninyo; ug kana nga lawas nga napuno sa kahayag makasabot sa tanang butang."},{"verse":68,"text":"Busa, balaana ang inyong mga kaugalingon aron ang inyong mga hunahuna mabug-os ngadto sa Dios, ug ang mga adlaw moabot nga kamo makakita kaniya; kay siya mopakita sa iyang nawong nganha kaninyo, ug mahimo kini sa iyang kaugalingon nga panahon, ug sa iyang kaugalingon nga paagi, ug sumala sa iyang kaugalingon nga kabubut-on."},{"verse":69,"text":"Hinumdomi ang mahinungdanon ug kataposang saad nga akong gihimo nganha kaninyo; isalikway ang inyong mga hunahuna nga walay hinungdan ug ang inyong naghingapin nga pagkatawa ipalayo gikan kaninyo."},{"verse":70,"text":"Pabilin kamo, pabilin kamo niini nga dapit, ug pagtawag og usa ka maligdong nga katigoman, bisan kadtong unang mga mamumuo niining kataposan nga gingharian."},{"verse":71,"text":"Ug himoa nga kadtong ilang gipasidan-an sa ilang pagbiyahe motawag sa Ginoo, ug mamalandong sa pasidaan nga ilang nadawat sulod sa ilang mga kasingkasing, sa mubong panahon."},{"verse":72,"text":"Tan-awa, ug sud-onga, atimanon nako ang inyong mga panon, ug moandam og mga elder ug ipadala ngadto kanila,"},{"verse":73,"text":"Tan-awa, dalion nako ang akong buhat sa saktong panahon."},{"verse":74,"text":"Ug akong ihatag kaninyo, kon kinsa ang unang mga mamumuo niining kataposan nga gingharian, ang usa ka sugo nga magpundok kamo, ug han-ayon ang inyong kaugalingon, ug andamon ang inyong mga kaugalingon, ug balaanon ang inyong kaugalingon; oo, limpyohan ang inyong mga kasingkasing, ug hugasan ang inyong mga kamot ug ang inyong mga tiil sa akong atubangan, aron himoon ko kamong limpyo;"},{"verse":75,"text":"Aron makapamatuod ako ngadto sa inyong Amahan, ug inyong Dios, ug akong Dios, nga kamo limpyo gikan sa dugo niining daotan nga henerasyon; aron matuman nako kini nga saad, kining mahinungdanon ug kataposan nga saad, nga akong gihimo nganha kaninyo, sumala sa akong kabubut-on."},{"verse":76,"text":"Usab, akong ihatag kaninyo ang usa ka sugo nga kinahanglan kamong mopadayon sa pag-ampo ug pagpuasa sugod karon."},{"verse":77,"text":"Ug akong ihatag kaninyo ang usa ka sugo nga kinahanglan kamong motudlo sa usag usa sa doktrina sa gingharian."},{"verse":78,"text":"Tudloi ninyo ang usag nga makugihon usa ug ang akong grasya magauban kaninyo, aron kamo mas hingpit nga matudloan sa teyoriya, sa baroganan, sa doktrina, sa balaod sa ebanghelyo, sa tanang butang mahitungod sa gingharian sa Dios, nga angay ninyong masabtan;"},{"verse":79,"text":"Sa mga butang nga tua sa langit ug ania sa yuta, ug sa ilawom sa yuta; mga butang nga nahitabo na, mga butang nga nahitabo karon, mga butang nga mahitabo sa dili madugay; mga butang nga anaa sa panimalay, mga butang nga tua sa laing nasod; ang mga gubat ug ang mga kagubot sa mga nasod, ug ang mga paghukom nga ania sa yuta; ug ang kasayoran usab bahin sa mga nasod ug sa mga gingharian—"},{"verse":80,"text":"Aron makaandam kamo sa tanang butang kon ipadala ko kamo pag-usab sa pagpalambo sa balaan nga tawag diin ako mitawag kaninyo, ug sa misyon nga akong gisugo kaninyo."},{"verse":81,"text":"Tan-awa, gipadala ko kamo aron sa pagpamatuod ug pagpasidaan sa katawhan, ug kinahanglan nga ang matag tawo nga napasidan-an mopasidaan sa iyang silingan."},{"verse":82,"text":"Busa, sila walay ikapangatarongan, ug ang ilang mga sala anaa sa ilang kaugalingon nga mga ulo."},{"verse":83,"text":"Siya nga nagtinguha kanako nga makugihon makakaplag kanako, ug dili isalikway."},{"verse":84,"text":"Busa, pabilin kamo, ug pagkugi sa pagtrabaho, aron mahingpit kamo sa inyong pangalagad sa pag-adto sa mga Hentil alang sa kataposang higayon, kutob sa tawgon sa ba-ba sa Ginoo, sa pagbugkos sa balaod ug sa pagselyo sa pagpamatuod, ug sa pag-andam sa mga santos alang sa oras sa paghukom nga moabot;"},{"verse":85,"text":"Aron ang ilang mga kalag makalingkawas sa kasuko sa Dios, sa kalaglagan sa pagkasalawayon nga nagpaabot sa mga daotan, niini nga kalibotan ug sa kalibotan nga moabot. Sa pagkatinuod, sultihan ko kamo, himoa nga kadtong dili unang mga elder magpadayon sa ubasan hangtod nga ang ba-ba sa Ginoo motawag kanila, kay ang ilang panahon wala pa moabot; ang ilang mga sapot dili limpyo gikan sa dugo niini nga henerasyon."},{"verse":86,"text":"Pabilin kamo sa pagkagawasnon diin kamo nahimo nga gawasnon; ayaw ipalambigit ang inyong mga kaugalingon sa sala, apan himoa nga limpyo ang inyong mga kamot, hangtod ang Ginoo moabot."},{"verse":87,"text":"Kay sa dili madugay gikan karon ug ang yuta mokurog ug mouyog ngadto ug nganhi ingon sa usa ka hubog nga tawo; ug ang adlaw motago, ug magdumili sa paghatag og kahayag; ug ang bulan maligo sa dugo; ug ang mga bitoon masuko sa hilabihan, ug mangahulog sama sa usa ka igos nga nahulog gikan sa kahoy nga igos."},{"verse":88,"text":"Ug human sa inyong pagpamatuod moabot ang kapungot ug kaligutgot nganha sa katawhan."},{"verse":89,"text":"Kay human sa inyong pagpamatuod moabot ang pagpamatuod sa mga linog, nga makamugna og mga pag-agulo sa taliwala sa kayutaan, ug ang mga tawo mangatumba sa yuta ug dili makabarog."},{"verse":90,"text":"Ug usab moabot ang pagpamatuod sa tingog sa mga dugdog, ug sa tingog sa mga kilat, ug sa tingog sa mga bagyo, ug sa tingog sa mga balod sa dagat nga mobanlas sa ilang mga kaugalingon lapas sa kabaybayonan niini."},{"verse":91,"text":"Ug ang tanang butang magkaguliyang; ug sa pagkatinuod, ang mga kasingkasing sa mga tawo mohunong sa pagpitik; kay ang kahadlok moabot sa tanang katawhan."},{"verse":92,"text":"Ug ang mga anghel molupad taliwala sa langit, mopahayag sa kusog nga tingog, mopatingog sa trumpeta sa Dios, mag-ingon: Pangandam kamo, pangandam kamo, O mga lumulupyo sa yuta; kay ang paghukom sa atong Dios miabot na. Tan-awa, ug sud-onga, ang Pamanhonon miabot na; lakaw kamo sugata siya."},{"verse":93,"text":"Ug diha-diha adunay magpakita nga usa ka dakong timailhan sa langit, ug ang tanang katawhan dungan nga makakita niini."},{"verse":94,"text":"Ug laing anghel mopatingog sa iyang trumpeta, mag-ingon: Kanang gamhanan nga simbahan, ang inahan sa mga salawayon, nga mipainom sa tanang nasod sa bino sa kapungot sa iyang pagsimba og dios-dios, nga migukod sa mga santos sa Dios, nga mipaagas sa ilang dugo—siya kinsa naglingkod sa daghang katubigan, ug diha sa mga isla sa mga kadagatan—tan-awa, siya ang sagbot sa yuta; gibugkos siya; ang iyang mga higot gihimong lig-on, ug walay tawo nga makabadbad niini; busa, andam na siya nga sunogon. Ug patingogon niya og dugay ug kusog ang iyang trumpeta, ug ang tanang nasod makadungog niini."},{"verse":95,"text":"Ug adunay kahilom sa langit sulod sa tunga sa oras; ug pagkahuman dayon ang kurtina sa langit ablihan, sama sa usa ka papel nga linukot nga ablihan human kini malukot, ug ang nawong sa Ginoo makita;"},{"verse":96,"text":"Ug ang mga santos nga anaa sa yuta, kinsa mga buhi, madasig ug mosaka sa itaas aron sa pagsugat kaniya."},{"verse":97,"text":"Ug sila nga nangatulog diha sa ilang mga lubnganan mobangon, kay ang ilang mga lubnganan pagaablihan; ug sila usab mosaka sa itaas aron sa pagsugat kaniya sa taliwala sa haligi sa langit—"},{"verse":98,"text":"Sila iya ni Kristo, ang unang mga bunga, sila nga manaog uban kaniya pag-una, ug sila nga ania sa yuta ug ang anaa sa ilang mga lubnganan, nga unang misaka sa itaas aron sa pagsugat kaniya; ug kining tanan pinaagi sa pagpatingog sa trumpeta sa anghel sa Dios."},{"verse":99,"text":"Ug human niini laing anghel ang mopatingog, nga mao ang ikaduhang trumpeta; ug unya moabot ang katubsanan niadtong kinsa iya ni Kristo sa iyang pag-anhi; kinsa nakadawat sa ilang bahin niana nga prisohan nga giandam alang kanila, aron madawat nila ang ebanghelyo, ug pagahukman sumala sa mga tawo sa unod."},{"verse":100,"text":"Ug usab, lain nga trumpeta ang motingog, nga mao ang ikatulo nga trumpeta; ug unya moabot ang mga espiritu sa mga tawo kinsa pagahukman, ug nakita nga ubos sa panghimaraot;"},{"verse":101,"text":"Ug mao kini ang nahibilin sa mga patay; ug dili sila mabuhi pag-usab hangtod mahuman ang liboan ka tuig, dili usab, hangtod sa kataposan sa yuta."},{"verse":102,"text":"Ug motingog ang laing trumpeta, nga mao ang ikaupat nga trumpeta, nag-ingon: Adunay nakit-an niadtong magpabilin hangtod nianang mahinungdanon ug kataposan nga adlaw, gani ang kataposan, kinsa sa gihapon magpabilin nga mahugaw."},{"verse":103,"text":"Ug motingog ang laing trumpeta, nga mao ang ikalima nga trumpeta, nga mao ang ikalima nga anghel nga gisaligan sa walay kataposan nga ebanghelyo—naglupad taliwala sa langit, ngadto sa tanang kanasoran, kaliwatan, pinulongan, ug katawhan;"},{"verse":104,"text":"Ug mao kini ang tingog sa iyang trumpeta, mag-ingon sa tanang katawhan, nga anaa sa langit ug sa yuta, ug niana nga anaa sa ilawom sa yuta—kay ang matag dunggan makadungog niini, ug matag tuhod moluhod, ug matag dila mokompisal, samtang sila naminaw sa tingog sa trumpeta, mag-ingon: Kahadloki ang Dios, ug ihatag ang himaya ngadto kaniya kinsa naglingkod sa trono, hangtod sa kahangtoran; kay ang oras sa iyang paghukom miabot na."},{"verse":105,"text":"Ug usab, laing anghel ang mopatingog sa iyang trumpeta, nga mao ang ikaunom nga anghel, nag-ingon: Siya napukan kinsa mihimo sa tanang nasod nga moinom sa bino sa kaligutgot sa iyang pagsimba og dios-dios; siya napukan, napukan!"},{"verse":106,"text":"Ug usab, laing anghel ang mopatingog sa iyang trumpeta, nga mao ang ikapito nga anghel, nag-ingon: Natapos na; natapos na! Ang Kordero sa Dios mibuntog ug mitunob-tunob sa intosan sa bino nga nag-inusara, gani ang intosan sa bino sa kabangis sa kaligutgot sa Labawng Makagagahom nga Dios."},{"verse":107,"text":"Ug unya ang mga anghel pagakoronahan sa himaya sa iyang gahom, ug ang mga santos pagapun-on sa iyang himaya, ug modawat sa ilang kabilin ug himoon nga sama kaniya."},{"verse":108,"text":"Ug unya ang unang anghel mopatingog pag-usab sa iyang trumpeta nga madungog sa tanang buhi, ug mopadayag sa tinago nga mga binuhatan sa mga tawo, ug ang gamhanan nga mga buhat sa Dios sa unang liboan ka tuig."},{"verse":109,"text":"Ug dayon ang ikaduhang anghel mopatingog sa iyang trumpeta, ug mopadayag sa tinago nga mga binuhatan sa mga tawo, ug sa mga hunahuna ug sa mga katuyoan sa ilang mga kasingkasing, ug ang gamhanan nga mga buhat sa Dios sa ikaduhang liboan ka tuig—"},{"verse":110,"text":"Ug magpadayon, hangtod nga ang ikapito nga anghel mopatingog sa iyang trumpeta; ug siya mobarog diha sa yuta ug diha sa dagat, ug manumpa sa ngalan niya kinsa naglingkod diha sa trono, nga wala nay panahon; ug si Satanas pagagaposon, kanang karaan nga bitin, nga gitawag og yawa, ug dili pagabuhian sulod sa liboan ka tuig."},{"verse":111,"text":"Ug dayon pagabuhian siya sa mubo nga panahon, aron siya mopundok sa iyang kasundalohan."},{"verse":112,"text":"Ug si Miguel, ang ikapito nga anghel, gani ang arkanghel, mopundok sa iyang kasundalohan, gani ang mga panon sa langit."},{"verse":113,"text":"Ug ang yawa mopundok sa iyang kasundalohan; bisan ang mga panon sa impyerno, ug mosulong aron makig-away batok ni Miguel ug sa iyang kasundalohan."},{"verse":114,"text":"Ug dayon moabot ang gubat sa halangdon nga Dios; ug ang yawa ug ang iyang kasundalohan isalikway ngadto sa ilang kaugalingon nga dapit, aron sila wala nay gahom sa mga santos bisan kanus-a."},{"verse":115,"text":"Kay si Miguel makig-away alang sa ilang mga gubat, ug mobuntog kaniya nga nagtinguha sa trono kaniya nga naglingkod diha sa trono, gani ang Kordero."},{"verse":116,"text":"Kini mao ang himaya sa Dios, ug ang gibalaan; ug dili na sila makatagamtam og kamatayon."},{"verse":117,"text":"Busa, sa pagkatinuod sultihan ko kamo, akong mga higala, tawaga ang inyong ligdong nga katigoman, sumala sa akong gisugo kaninyo."},{"verse":118,"text":"Ug tungod kay ang tanan walay pagtuo, pagkugi kamo sa pagpangita ug tudloi ang usag usa sa mga pulong sa kaalam; oo, pangitaa ninyo gikan sa labing maayo nga mga basahon ang mga pulong sa kaalam; tinguhaa ang pagkat-on, gani pinaagi sa pagtuon ug usab pinaagi sa pagtuo."},{"verse":119,"text":"Han-aya ang inyong mga kaugalingon; andama ang matag butang nga kinahanglanon; ug paghimo og usa ka balay, gani usa ka balay sa pag-ampo, usa ka balay sa pagpuasa, usa ka balay sa pagtuo, usa ka balay sa pagkat-on, usa ka balay sa himaya, usa ka balay sa kahusay, usa ka balay sa Dios;"},{"verse":120,"text":"Aron ang inyong mga pagsulod mahimo pinaagi sa ngalan sa Ginoo; aron ang inyong mga paggawas mahimo pinaagi sa ngalan sa Ginoo; aron ang inyong mga pagtimbaya mahimo pinaagi sa ngalan sa Ginoo, uban sa pinataas nga mga kamot ngadto sa Labing Halangdon."},{"verse":121,"text":"Busa, hunong gikan sa inyong tanan nga walay hinungdan nga mga pakigpulong, gikan sa tanan nga pagkatawa, gikan sa inyong tanan nga higal nga mga tinguha, gikan sa inyong tanan nga garbo ug walay hinungdan nga panghunahuna, ug gikan sa inyong tanang daotan nga mga binuhatan."},{"verse":122,"text":"Pagpili kamo taliwala kaninyo og usa ka magtutudlo, ug ayaw itugot nga ang tanan mosulti og dungan; apan himoa nga ang usa mamulong pag-una ug ang tanan maminaw ngadto sa iyang mga gipamulong, aron kon ang tanan nakapamulong na nga ang tanan mahatagan og kaayohan sa tanan, ug nga ang matag tawo makabaton og managsama nga pribilihiyo."},{"verse":123,"text":"Tan-awa nga kamo maghigugmaay sa usag usa; mohunong sa pagkamaibogon; makat-on sa paghatag ngadto sa usag usa sumala sa gikinahanglan sa ebanghelyo."},{"verse":124,"text":"Hunong sa pagkatapolan; hunong sa pagkahugaw; hunong sa pagpangita og kasaypanan sa usag usa; hunong sa pagkatulog og taas kay sa gikinahanglan; katulog og sayo, aron kamo dili kapoyon; bangon og sayo, aron ang inyong mga kalawasan ug ang inyong hunahuna molagsik."},{"verse":125,"text":"Ug labaw sa tanang butang, sul-obi ang inyong mga kaugalingon sa makapahiusa nga gugma nga putli, sama sa usa ka kupo, nga mao ang makapahiusa sa pagkahingpit ug kalinaw."},{"verse":126,"text":"Pag-ampo kanunay, aron kamo dili mawad-an og paglaom, hangtod ako moabot. Tan-awa, ug sud-onga, moabot ako sa labing madali, ug modawat kaninyo ngari kanako. Amen."},{"verse":127,"text":"Ug usab, ang han-ay nga pamaagi sa balay nga giandam alang sa kapangulohan sa eskwelahan sa mga propeta, gitukod alang sa ilang pagpanudlo sa tanang butang nga mahinungdanon alang kanila, gani alang sa tanang opisyal sa simbahan, o sa lain nga pulong, kadtong gitawag sa pagpangalagad diha sa simbahan, sugod sa labaw nga mga pari, bisan ngadto sa mga deacon—"},{"verse":128,"text":"Ug kini mao ang han-ay nga pamaagi sa balay sa kapangulohan sa eskwelahan: Siya nga napili nga mahimong presidente, o magtutudlo, makit-an nga magbarog sa iyang dapit, sa balay nga giandam alang kaniya."},{"verse":129,"text":"Busa, siya ang una sa balay sa Dios, sa dapit diin ang kongregasyon diha sa balay mainampingon ug klaro nga maminaw sa iyang mga pulong, dili pinaagi sa kusog nga pagkasulti."},{"verse":130,"text":"Ug kon moabot siya sa balay sa Dios, kay kinahanglan nga una siyang moabot sa balay—tan-awa, kini maanindot, aron mahimo siyang usa ka ehemplo—"},{"verse":131,"text":"Himoa nga ihalad niya ang iyang kaugalingon sa pag-ampo nga magluhod sa atubangan sa Dios, agi og timaan o handomanan sa walay kataposan nga pakigsaad."},{"verse":132,"text":"Ug kon adunay mosulod sunod kaniya, himoa nga ang magtutudlo mobarog, ug, sa pinataas nga mga kamot ngadto sa langit, oo, bisan direkta, motimbaya sa iyang igsoon o kaigsoonan niini nga mga pulong:"},{"verse":133,"text":"Ikaw ba igsoon o kaigsoonan? Ako motimbaya kanimo pinaagi sa ngalan sa Ginoo nga si Jesukristo, agi og timaan o handomanan sa walay kataposan nga pakigsaad, diin nga pakigsaad ako modawat kaninyo sa panagdait, inubanan sa katuyoan nga makanunayon, dili matarog, ug dili mausabon, nga mahimo ninyong higala ug igsoon pinaagi sa grasya sa Dios sa makapahiusa nga impluwensya sa gugma, sa pagsunod sa tanang sugo sa Dios nga walay tulubagon, sa pagpasalamat, hangtod sa kahangtoran. Amen."},{"verse":134,"text":"Ug siya nga makit-an nga dili takos niini nga pagtimbaya dili makabaton og dapit diha kaninyo; kay kamo dili makatugot nga ang akong balay iyang pagahugaw-hugawan."},{"verse":135,"text":"Ug siya nga mosulod ug matinud-anon sa akong atubangan, ug usa ka igsoon, o kon sila kaigsoonan, motimbaya sila sa presidente o magtutudlo inubanan sa pinataas nga mga kamot ngadto sa langit, sa samang pag-ampo ug pakigsaad, o pinaagi sa pag-ingon og Amen, agi og timaan gihapon niini."},{"verse":136,"text":"Tan-awa, sa pagkatinuod, sultihan ko kamo, kini mao ang ehemplo nganha kaninyo sa usa ka pagtimbaya sa usag usa diha sa balay sa Dios, sa eskwelahan sa mga propeta."},{"verse":137,"text":"Ug kamo gitawag sa pagbuhat niini pinaagi sa pag-ampo ug sa pagpasalamat, sumala sa ihatag sa Espiritu sa inyong tanang binuhatan sulod sa balay sa Ginoo, sa eskwelahan sa mga propeta, nga kini mahimo nga usa ka santuwaryo, usa ka tabernakulo sa Balaan nga Espiritu sa inyong kaayohan."},{"verse":138,"text":"Ug dili kamo modawat ni bisan kinsa kaninyo ngadto niini nga eskwelahan gawas kon siya limpyo gikan sa dugo niini nga henerasyon."},{"verse":139,"text":"Ug pagadawaton siya pinaagi sa ordinansa sa paghugas sa mga tiil, kay tungod niini nga katuyoan ang ordinansa sa paghugas sa mga tiil gitudlo."},{"verse":140,"text":"Ug usab, ang ordinansa sa paghugas sa mga tiil pagahimoon sa presidente, o sa tigdumala nga elder sa simbahan."},{"verse":141,"text":"Pagasugdan kini sa usa ka pag-ampo; ug human sa pag-ambit sa pan ug bino, siya mobakos sa iyang kaugalingon sumala sa sundanan nga gihatag sa ikanapulog tulo nga kapitulo sa pagpamatuod ni Juan mahitungod kanako. Amen."}]},{"chapter":89,"verses":[{"verse":1,"text":"Ang Pulong sa Kaalam, alang sa kaayohan sa konseho sa mga high priest, nga nagtigom sa Kirtland, ug sa simbahan, ug usab sa mga santos sa Zion—"},{"verse":2,"text":"Ipadala isip katahoran; dili pinaagi sa sugo o pagpugos, apan pinaagi sa pagpadayag ug sa pulong sa kaalam, mopakita sa mga pamaagi ug kabubut-on sa Dios sa temporal nga kaluwasan sa tanang santos sa kataposang mga adlaw—"},{"verse":3,"text":"Gihatag isip usa ka baroganan inubanan og saad, gipahiangay sa kapasidad sa huyang ug sa labing huyang sa tanang santos, kinsa mao o mahimong tawagon nga mga santos."},{"verse":4,"text":"Tan-awa, sa pagkatinuod, sa ingon niana ang Ginoo miingon kaninyo: Isip sangpotanan sa mga daotan ug mga laraw nga anaa ug maanaa sa mga kasingkasing sa nagkunsabong mga tawo sa kataposang mga adlaw, nagpasidaan ako kaninyo, ug mopasidaan kaninyo, pinaagi sa paghatag kaninyo niini nga pulong sa kaalam pinaagi sa pagpadayag—"},{"verse":5,"text":"Nga kutob adunay tawo nga moinom og bino o isog nga ilimnon uban kaninyo, tan-awa dili kini maayo, ni angay sa panan-aw sa inyong Amahan, gawas lamang sa panagtigom sa inyong kaugalingon sa paghalad sa inyong mga sakramento sa iyang atubangan."},{"verse":6,"text":"Ug, tan-awa, kinahanglan nga bino gayod kini, oo, lunsay nga bino sa ubas, nga inyong kaugalingong binuhat."},{"verse":7,"text":"Ug, usab, ang isog nga mga ilimnon dili alang sa tiyan, apan alang sa paghugas sa inyong lawas."},{"verse":8,"text":"Ug usab, ang tabako dili alang sa lawas, ni alang sa tiyan, ug dili maayo alang sa tawo, apan usa ka hilba alang sa mga pangos ug sa tanang masakiton nga baka, gamiton sa tukmang paghukom ug kahanas."},{"verse":9,"text":"Ug usab, ang init nga ilimnon dili alang sa lawas o sa tiyan."},{"verse":10,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ang tanang maayo nga hilba giandam sa Dios alang sa panglawas, kinaiyahan, ug paggamit sa tawo—"},{"verse":11,"text":"Ang matag hilba sa panahon niini, ug matag bunga sa panahon niini; kining tanan angay nga gamiton uban sa pagmatngon ug pagpasalamat."},{"verse":12,"text":"Oo, ang unod usab sa mga mananap ug sa mga langgam sa kahanginan, ako, ang Ginoo, miandam niini aron gamiton sa tawo uban sa pagpasalamat; bisan pa niana gamiton kini sa panagsa;"},{"verse":13,"text":"Ug akong ikahimuot nga dili kini gamiton, gawas sa mga panahon sa tingtugnaw, o sa katugnaw, o sa kagutom."},{"verse":14,"text":"Ang tanang lugas giandam aron gamiton alang sa tawo ug sa kahayopan, nga mahimo nga sangkap sa kinabuhi, dili lamang alang sa tawo apan alang sa kahayopan sa umahan, ug sa mga langgam sa kalangitan, ug sa tanang ihalas nga mga mananap nga nagdagan o nagkamang sa yuta;"},{"verse":15,"text":"Ug gihimo kini sa Dios aron gamiton sa tawo sa mga panahon lamang sa kagutom ug hilabihan nga kagutom."},{"verse":16,"text":"Ang tanang lugas maayo nga pagkaon sa tawo; sama usab ang bunga sa bagon; kana nga namunga, bisan diha sa yuta o sa ibabaw sa yuta—"},{"verse":17,"text":"Hinuon, ang trigo alang sa tawo, ug ang mais alang sa baka, ug ang mga abena alang sa kabayo, ug ang gahi nga mga lugas alang sa mga langgam ug alang sa baboy, ug alang sa tanang kahayopan sa umahan, ug ang sebada alang sa tanang mapuslanong mga hayop, ug alang sa dili maisog nga mga ilimnon, ingon usab ang ubang mga lugas."},{"verse":18,"text":"Ug ang tanang santos kinsa mohinumdom sa pagsunod ug mobuhat niining mga panultihon, maglakaw nga masulundon sa mga sugo, makadawat og kahimsog sa ilang pusod ug uyok sa ilang mga bukog;"},{"verse":19,"text":"Ug makakaplag og kaalam ug dagkong mga bahandi sa kahibalo, gani tinago nga mga bahandi;"},{"verse":20,"text":"Ug modagan ug dili kapoyon, ug molakaw ug dili maluya."},{"verse":21,"text":"Ug ako, ang Ginoo, mohatag ngadto kanila og saad, nga sila labyan ra sa tiglaglag nga anghel, sama sa nahitabo sa mga anak ni Israel, ug dili mopatay kanila. Amen."}]},{"chapter":90,"verses":[{"verse":1,"text":"Sa ingon niini miingon ang Ginoo, sa pagkatinuod, sa pagkatinuod sultihan ko ikaw akong anak, ang imong mga sala gipasaylo na, sumala sa imong hangyo, kay ang imong mga pag-ampo ug ang mga pag-ampo sa imong kaigsoonan miabot sa akong mga dunggan."},{"verse":2,"text":"Busa, bulahan ikaw gikan karon nga naghupot sa mga yawe sa gingharian nga gihatag kanimo; kansang gingharian matukod sa kataposan nga higayon."},{"verse":3,"text":"Sa pagkatinuod sultihan ko ikaw, ang mga yawe niini nga gingharian dili na gayod kuhaon gikan kanimo, samtang ikaw anaa sa kalibotan, ni sa kalibotan nga moabot;"},{"verse":4,"text":"Hinuon, pinaagi kanimo ang buhing mga pulong mahatag ngadto sa uban, oo, gani ngadto sa simbahan."},{"verse":5,"text":"Ug tanan sila nga modawat sa buhing mga pulong sa Dios, pamatngona sila kon giunsa nila kini sa pagdawat basin pa unya og isipon nila kini nga usa ka butang nga dili kaayo mahinungdanon, ug dad-on ubos sa panghimaraot tungod niana, ug mapandol ug madagma kon ang mga bagyo moabot, ug ang mga hangin mohuros, ug ang mga ulan mobundak, ug mohampak sa ilang balay."},{"verse":6,"text":"Ug usab, sa pagkatinuod sultihan ko ang imong kaigsoonan, si Sidney Rigdon ug Frederick G. Williams, nga gipasaylo usab sila sa ilang mga sala, ug pagaisipon sila nga sama kanimo og katungod sa paghupot sa mga yawe niining kataposan nga gingharian;"},{"verse":7,"text":"Dugang pa pinaagi sa imong pagdumala sa mga yawe sa tulunghaan sa mga propeta, nga akong gisugo nga pagatukoron;"},{"verse":8,"text":"Nga pinaagi niini mahingpit sila sa ilang pagpangalagad alang sa kaluwasan sa Zion, ug sa mga nasod sa Israel, ug sa mga Hentil, kutob sa motuo;"},{"verse":9,"text":"Nga pinaagi sa imong pagdumala madawat nila ang pulong, ug pinaagi sa ilang pagdumala ang pulong modangat ngadto sa mga kinatumyan sa yuta, una ngadto sa mga Hentil, ug unya, tan-awa, ug sud-onga, mamalik sila ngadto sa mga Judeo."},{"verse":10,"text":"Ug unya moabot ang adlaw nga ang bukton sa Ginoo mapadayag pinaagi sa gahom sa pag-agni sa mga nasod, sa pagano nga mga nasod, sa balay ni Jose, sa ebanghelyo sa ilang kaluwasan."},{"verse":11,"text":"Kay mahitabo niana nga adlaw, nga ang matag tawo maminaw sa kahingpitan sa ebanghelyo sa iyang kaugalingong sinultihan, ug sa iyang kaugalingong pinulongan, pinaagi niadtong giordinahan niini nga gahom, pinaagi sa pagdumala sa Maghuhupay, nga gibu-bo diha kanila aron mapadayag si Jesukristo."},{"verse":12,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, hatagan ko kamo og sugo nga magpadayon kamo sa pagpangalangad ug sa kapangulohan."},{"verse":13,"text":"Ug kon mahuman na ninyo sa paghubad ang basahon sa mga propeta, sukad niana kamo ang modumala sa mga kalihokan sa simbahan ug sa tulunghaan;"},{"verse":14,"text":"Ug sa matag karon ug unya, sumala sa ipadayag sa Maghuhupay, makadawat og mga pagpadayag sa pagbutyag sa mga misteryo sa gingharian;"},{"verse":15,"text":"Ug mopahiluna sa mga simbahan, ug magtuon ug magkat-on, ug mosinati sa tanan nga maayong mga basahon, ug sa mga pinulongan, mga sinultihan, ug katawhan."},{"verse":16,"text":"Ug mao kini ang inyong buluhaton ug misyon sa inyong tibuok nga kinabuhi, sa pagpangulo sa konseho, ug pagpahiluna sa tanang kalihokan niini nga simbahan ug gingharian."},{"verse":17,"text":"Ayaw kaulaw, ni pagkalibog; apan pagmatngon sa inyong tanang mapahitas-on nga panghunahuna ug garbo, kay magdala kini og lit-ag diha sa inyong mga kalag."},{"verse":18,"text":"Ipahimutang sa kahusay ang inyong mga balay; ipahilayo gikan kaninyo ang pagkatapolan ug pagkahugawan."},{"verse":19,"text":"Karon, sa pagkatinuod sultihan ko ikaw, pag-andam og dapit, sa labing madali, alang sa pamilya sa imong magtatambag ug tigsulat, gani si Frederick G. Williams."},{"verse":20,"text":"Ug tugoti nga ang akong edaran nga sulugoon, si Joseph Smith, Sen., magpadayon uban sa iyang pamilya sa dapit diin siya karon nagpuyo; ug ayaw kini ipabaligya hangtod ang ba-ba sa Ginoo mosugo."},{"verse":21,"text":"Ug isugyot nga ang akong magtatambag, gani si Sidney Rigdon, magpabilin diin siya karon nagpuyo hangtod ang ba-ba sa Ginoo ang mosugo."},{"verse":22,"text":"Ug papangitaa ang bishop nga makugihon aron makakaplag og tinugyanan, ug ipapangita ang usa ka tawo nga adunay daghang tinipigan nga bahandi—usa ka tawo sa Dios, ug lig-on ang pagtuo—"},{"verse":23,"text":"Nga pinaagi niana makabayad siya sa matag utang; aron ang balay tipiganan sa Ginoo dili mapakaulawan sa mga mata sa katawhan."},{"verse":24,"text":"Pangita nga makugihon, pag-ampo sa kanunay, ug pagmatuohon, ug ang tanang butang maghiusa sa pagtabang alang sa inyong kaayohan, kon maglakaw kamo nga matarong ug mahinumdom sa pakigsaad diin kamo nagpakigsaad sa usag usa."},{"verse":25,"text":"Himoa nga ang inyong mga pamilya gamay lang, ilabi na sa akong edaran nga sulugoon nga si Joseph Smith, Sen., kalabot niadtong dili sakop sa inyong mga pamilya;"},{"verse":26,"text":"Nga kadtong mga butang nga giandam alang kaninyo, sa pagpahitabo sa akong buluhaton, dili kuhaon gikan kaninyo ug ihatag ngadto sa mga dili takos—"},{"verse":27,"text":"Ug tungod niana mapugngan kamo sa pagtuman nianang mga butang nga akong gisugo kaninyo."},{"verse":28,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, akong kabubut-on nga ang akong sulugoong babaye nga si Vienna Jaques kinahanglan makadawat og kwarta alang sa iyang galastohan, ug moadto sa yuta sa Zion;"},{"verse":29,"text":"Ug ang mahibilin sa kwarta mahimo nga ipahinungod ngari kanako, ug pagagantihan siya sa akong kaugalingong tukma nga panahon."},{"verse":30,"text":"Sa pagkatinuod sultihan ko kamo, nga sakto sa akong panan-aw nga moadto siya sa yuta sa Zion, ug modawat sa kabilin gikan sa kamot sa bishop;"},{"verse":31,"text":"Nga mapahiluna siya sa kalinaw kon matinud-anon siya, ug dili magtinapolan sa iyang mga adlaw gikan karon."},{"verse":32,"text":"Ug tan-awa, sa pagkatinuod sultihan ko kamo, nga inyong isulat kini nga sugo, ug moingon ngadto sa inyong kaigsoonan sa Zion, pinaagi sa mahigugmaong katahoran, nga gitawag ko usab kamo sa pagdumala sa Zion sa akong kaugalingong tukma nga panahon."},{"verse":33,"text":"Busa, pahunonga sila sa pagsamok kanako mahitungod niining butanga."},{"verse":34,"text":"Tan-awa, sultihan ko kamo nga ang inyong kaigsoonan sa Zion nagsugod sa paghinulsol, ug ang mga anghel malipayon mahitungod kanila."},{"verse":35,"text":"Bisan pa niana, wala ako mahimuot sa daghang butang; ug wala ako mahimuot sa akong sulugoon nga si William E. McLellin, ni sa akong sulugoon nga si Sidney Gilbert; ug sa bishop usab, ug ang uban adunay daghang butang nga angay nga hinulsolan."},{"verse":36,"text":"Apan sa pagkatinuod sultihan ko kamo, nga ako, ang Ginoo, makiglantogi sa Zion, ug mohangyo sa iyang mga pangulo, ug mopanton kaniya hangtod nga siya makabuntog ug limpyo sa akong atubangan."},{"verse":37,"text":"Kay dili siya papahawaon gikan sa iyang dapit. Ako, ang Ginoo, namulong niini. Amen."}]},{"chapter":91,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niini misulti ang Ginoo kanimo mahitungod sa Apokripa—Adunay daghang butang nga nalakip niini nga tinuod, ug ang kadaghanan niini sakto ang pagkahubad;"},{"verse":2,"text":"Adunay daghang butang nga nalakip niini nga dili tinuod, nga mga pagdugang sa mga kamot sa mga tawo."},{"verse":3,"text":"Sa pagkatinuod, sultihan ko kamo, nga dili na kinahanglan nga hubaron ang Apokripa."},{"verse":4,"text":"Busa, kinsa kadtong mobasa niini, kinahanglan nga sabton niya, kay ang Espiritu mopadayag sa kamatuoran;"},{"verse":5,"text":"Ug kinsa kadtong makadawat og kahibalo pinaagi sa Espiritu makakuha og kaayohan gikan niini;"},{"verse":6,"text":"Ug kinsa kadtong dili modawat pinaagi sa Espiritu, dili mahatagan og kaayohan. Busa dili na kinahanglan nga hubaron kini. Amen."}]},{"chapter":92,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niini miingon ang Ginoo, akong hatagan ang hiniusa nga kapunongan, nga gitukod subay sa sugo nga kanhi gihatag, og pagpadayag ug sugo mahitungod sa akong sulugoon nga si Frederick G. Williams, nga dawaton ninyo siya ngadto sa kapunongan. Ang akong isulti sa usa akong isulti alang sa tanan."},{"verse":2,"text":"Ug usab, sultihan ko ikaw akong sulugoong Frederick G. Williams, mahimo ka nga usa ka madasigon nga sakop niini nga kapunongan; ug kon magmatinud-anon ka sa pagtuman sa tanan nga nahaunang mga sugo ikaw panalanginan sa kahangtoran. Amen."}]},{"chapter":93,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niini misulti ang Ginoo: Mahitabo unya nga ang matag kalag nga mosalikway sa iyang mga sala ug moduol kanako, ug motawag sa akong ngalan, ug motuman sa akong tingog, ug mohupot sa akong mga sugo, makakita sa akong nawong ug masayod nga ako kini;"},{"verse":2,"text":"Ug nga ako ang tinuod nga kahayag nga nagdan-ag sa matag tawo nga moanhi sa kalibotan;"},{"verse":3,"text":"Ug nga ako anaa sa Amahan, ug ang Amahan ania kanako, ug ang Amahan ug ako usa ra—"},{"verse":4,"text":"Ang Amahan tungod kay gihatag niya kanako ang iyang kahingpitan, ug ang Anak tungod kay dinhi ako sa kalibotan ug gihimo ang unod nga akong tabernakulo, ug nagpuyo kauban sa mga anak sa mga tawo."},{"verse":5,"text":"Dinhi ako sa kalibotan ug nakadawat gikan sa akong Amahan, ug ang iyang mga buhat tataw nga gipakita."},{"verse":6,"text":"Ug si Juan nakakita ug nagpamatuod sa kahingpitan sa akong himaya, ug ang kahingpitan sa talaan ni Juan ipadayag sa umaabot."},{"verse":7,"text":"Ug mipamatuod siya, nga nag-ingon: Akong nakita ang iyang himaya, nga diha na siya sa sinugdanan, sa wala pa ang kalibotan;"},{"verse":8,"text":"Busa, sa sinugdanan diha na ang Pulong, kay siya mao ang Pulong, gani ang sulugoon sa kaluwasan—"},{"verse":9,"text":"Ang kahayag ug ang Manunubos sa kalibotan; ang Espiritu sa kamatuoran, kinsa mianhi sa kalibotan, tungod kay ang kalibotan iyang binuhat, ug diha kaniya ang kinabuhi sa mga tawo ug ang kahayag sa mga tawo."},{"verse":10,"text":"Ang mga kalibotan binuhat niya; ang mga tawo binuhat niya; ang tanang butang binuhat niya, ug pinaagi kaniya, ug iya."},{"verse":11,"text":"Ug ako, si Juan, mopamatuod nga akong nakita ang iyang himaya, sama sa himaya sa Bugtong Anak sa Amahan, puno sa grasya ug kamatuoran, gani ang Espiritu sa kamatuoran, nga mianhi ug mipuyo sa unod, ug mipuyo uban kanato."},{"verse":12,"text":"Ug ako, si Juan, nakakita nga wala niya madawat ang kahingpitan sa sinugdanan, apan nakaangkon og grasya alang sa grasya;"},{"verse":13,"text":"Ug wala niya madawat ang kahingpitan sa sinugdanan, apan nagpadayon gikan sa ginagmay nga mga grasya, hangtod nga nadawat niya ang kahingpitan;"},{"verse":14,"text":"Ug sa ingon niana gitawag siya nga Anak sa Dios, tungod kay wala siya makadawat sa kahingpitan sa sinugdanan."},{"verse":15,"text":"Ug ako, si Juan, mopamatuod, ug tan-awa, naabli ang kalangitan, ug ang Espiritu Santo mikunsad ngadto kaniya, nga sama sa salampati, ug mitugdon kaniya, ug dihay usa ka tingog nga gikan sa langit nga nag-ingon: Mao kini ang akong hinigugmang Anak."},{"verse":16,"text":"Ug ako, si Juan, nagpamatuod nga siya nakadawat sa usa ka kahingpitan sa himaya sa Amahan;"},{"verse":17,"text":"Ug nadawat niya ang tanang gahom, sa langit ug sa yuta, ug ang himaya sa Amahan nag-uban kaniya, kay siya anaa kaniya."},{"verse":18,"text":"Ug mahitabo, nga kon kamo magmatinud-anon, madawat ninyo ang kahingpitan sa talaan ni Juan."},{"verse":19,"text":"Ihatag ko kaninyo kini nga mga panultihon aron makasabot ug masayod kamo kon unsaon sa pagsimba, ug masayod unsa ang inyong gisimba, aron makaadto kamo sa Amahan pinaagi sa akong ngalan, ug sa tukmang panahon makadawat sa iyang kahingpitan."},{"verse":20,"text":"Kay kon inyong tumanon ang akong mga sugo makadawat kamo sa iyang kahingpitan, ug mahimaya ngari kanako sama nga anaa ako sa Amahan; busa, sultihan ko kamo, makadawat kamo og grasya alang sa grasya."},{"verse":21,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, ako diha na sa sinugdanan uban sa Amahan, ug ako mao ang Unang Natawo;"},{"verse":22,"text":"Ug kadtong tanan nga gipanganak pinaagi kanako mga mag-aambit niana nga himaya ug mao ang simbahan sa Unang Natawo."},{"verse":23,"text":"Kamo usab diha na sa sinugdanan uban sa Amahan; kana nga Espiritu, gani ang Espiritu sa kamatuoran;"},{"verse":24,"text":"Ug ang kamatuoran mao ang kahibalo sa mga butang kon unsa sila karon, ug unsa sila kaniadto, ug unsa sila sa umaabot;"},{"verse":25,"text":"Ug ang bisan unsa nga mas labaw o kulang kaysa niini mao ang espiritu nianang daotan nga usa ka bakakon sukad pa sa sinugdanan."},{"verse":26,"text":"Ang Espiritu sa kamatuoran iya sa Dios. Ako ang Espiritu sa kamatuoran, ug si Juan mipamatuod bahin kanako, nga nag-ingon: Nakadawat siya og kahingpitan sa kamatuoran, oo, gani sa tanang kamatuoran;"},{"verse":27,"text":"Ug walay tawo nga makadawat sa kahingpitan gawas kon motuman siya sa iyang mga sugo."},{"verse":28,"text":"Siya nga motuman sa iyang mga sugo makadawat og kamatuoran ug kahayag, hangtod nga mahimaya siya diha sa kamatuoran ug masayod sa tanang butang."},{"verse":29,"text":"Ang tawo usab diha na sa sinugdanan uban sa Dios. Ang kinaadman, o ang kahayag sa kamatuoran, wala malalang o mabuhat, ni dili gayod mahimo."},{"verse":30,"text":"Ang tanang kamatuoran gawasnon niana nga dapit diin kini gibutang sa Dios, sa paglihok alang sa iyang kaugalingon, sama usab sa tanang kinaadman; kay kon dili walay kinabuhi."},{"verse":31,"text":"Tan-awa, ania ang kabubut-on sa tawo, ug ania ang panghimaraot sa tawo; kay kana nga naggikan pa sa sinugdanan yano nga gipadayag ngadto kanila, ug wala sila modawat sa kahayag."},{"verse":32,"text":"Ug ang matag tawo kansang espiritu dili modawat sa kahayag ubos sa panghimaraot."},{"verse":33,"text":"Kay ang tawo espiritu. Ang mga elemento mahangtoron, ug ang espiritu ug elemento, nga dili na gayod mabulag, makadawat og kahingpitan sa kamaya;"},{"verse":34,"text":"Ug kon magkabulag, ang tawo dili makadawat og kahingpitan sa kamaya."},{"verse":35,"text":"Ang mga elemento mao ang tabernakulo sa Dios; oo, ang tawo mao ang tabernakulo sa Dios, gani mga templo; ug ang bisan unsang templo nga mahugawan, kana nga templo laglagon sa Dios."},{"verse":36,"text":"Ang himaya sa Dios mao ang kinaadman, o, sa laing pagkasulti kahayag, ug kamatuoran."},{"verse":37,"text":"Ang kahayag ug kamatuoran mobiya nianang usa nga daotan."},{"verse":38,"text":"Ang matag espiritu sa tawo inosente sa sinugdanan; ug kay ang Dios mitubos man sa tawo gikan sa pagkapukan, ang mga tawo nahimo na usab, sa ilang pagkamasuso, nga inosente sa atubangan sa Dios."},{"verse":39,"text":"Ug kanang usa nga daotan miabot ug mikuha sa kahayag ug kamatuoran, pinaagi sa pagkamasinupakon, gikan sa mga anak sa mga tawo, ug tungod sa mga tradisyon sa ilang mga amahan."},{"verse":40,"text":"Apan gisugo ko kamo sa pag-amuma sa inyong mga anak sa kahayag ug kamatuoran."},{"verse":41,"text":"Apan sa pagkatinuod sultihan ko ikaw, akong sulugoong Frederick G. Williams, nagpadayon ka ubos niini nga panghimaraot;"},{"verse":42,"text":"Wala nimo tudloi ang imong mga anak sa kahayag ug kamatuoran, sumala sa mga sugo; ug kanang usa nga daotan adunay gahom, sa gihapon, diha kanimo, ug mao kini ang hinungdan sa imong kasakit."},{"verse":43,"text":"Ug karon usa ka sugo ang akong ihatag kanimo—kon luwason ka ipahimutang nimo sa kahusay ang imong kaugalingong balay, kay adunay daghang butang nga dili sakto diha sa imong balay."},{"verse":44,"text":"Sa pagkatinuod, sultihan ko ang akong sulugoon nga si Sidney Rigdon, nga sa pipila ka butang wala siya makatuman sa akong mga sugo mahitungod sa iyang mga anak; busa, unaha ang pagpahimutang sa kahusay sa imong balay."},{"verse":45,"text":"Sa pagkatinuod, sultihan ko ang akong sulugoon nga si Joseph Smith, Jun., o sa laing pagkasulti, tawagon ko kamo nga mga higala, kay mga higala ko kamo, ug makaangkon kamo og kabilin uban kanako—"},{"verse":46,"text":"Gitawag ko kamo nga mga sulugoon alang sa kaayohan sa kalibotan, ug kamo ilang mga sulugoon alang sa akong kaayohan—"},{"verse":47,"text":"Ug karon, sa pagkatinuod sultihan ko si Joseph Smith, Jun.,—Wala ka makatuman sa akong mga sugo, ug kinahanglan gayod nga mabadlong sa atubangan sa Ginoo;"},{"verse":48,"text":"Ang imong pamilya kinahanglan gayod nga maghinulsol ug mobiya sa pipila ka butang, ug mohatag og mas kinasingkasing nga pagpatalinghog sa imong mga pulong, o pagakuhaon gikan sa ilang dapit."},{"verse":49,"text":"Unsay akong isulti ngadto sa usa akong isulti ngadto sa tanan; pag-ampo kanunay basin pa unya kanang usa nga daotan makaangkon og gahom diha kaninyo, ug papahawaon kamo gikan sa inyong nahimutangan."},{"verse":50,"text":"Ang akong sulugoon nga si Newel K. Whitney usab, nga bishop sa akong simbahan, kinahanglan pagapantonon, ug mopahimutang sa iyang pamilya sa kahusay, ug tan-awon nga sila labaw nga makugihon ug manggihunahunaon diha sa panimalay, ug mag-ampo kanunay, o sila papahawaon gikan sa ilang dapit."},{"verse":51,"text":"Karon, sultihan ko kamo, akong mga higala, papadayona ang akong sulugoon nga si Sidney Rigdon sa iyang panaw, ug padalia, ug usab ipasangyaw ang tuig sa pagdawat sa Ginoo sa iyang katawhan, ug sa ebanghelyo sa kaluwasan, sa ingon nga ako mohatag kaniya og kahanas sa pagpamulong; ug pinaagi sa inyong pag-ampo inubanan sa pagtuo uban ang hiniusa nga pag-uyon ako mobulig kaniya."},{"verse":52,"text":"Ug sultihi ang akong mga sulugoon nga si Joseph Smith, Jun., ug si Frederick G. Williams nga magdali usab, gani pagahatagan sila sumala sa pag-ampo nga nagagikan sa pagtuo; ug kon kamo motuman sa akong mga pulong dili kamo pagalibogon dinhi niini nga kalibotan, ni sa kalibotan nga moabot."},{"verse":53,"text":"Ug, sa pagkatinuod sultihan ko kamo, nga maoy akong pagbuot nga angay kamong magdali sa paghubad sa akong mga kasulatan, ug sa pag-angkon og kahibalo sa kasaysayan, ug sa mga nasod, ug sa mga gingharian, sa mga balaod sa Dios ug sa tawo, ug kining tanan alang sa kaluwasan sa Zion. Amen."}]},{"chapter":94,"verses":[{"verse":1,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, akong mga higala, hatagan ko kamo og usa ka sugo, nga inyong sugdan ang usa ka buhat sa pagpahimutang ug sa pagpangandam sa sinugdanan ug tukoranan sa siyudad sa stake sa Zion, dinhi sa yuta sa Kirtland, nga magsugod sa akong balay."},{"verse":2,"text":"Ug tan-awa, kini kinahanglan nga pagabuhaton sumala sa sundanan nga gihatag ko na kaninyo."},{"verse":3,"text":"Ug ang unang lote sa habagatan ipahinungod ngari kanako alang sa pagtukod og balay alang sa kapangulohan, alang sa buluhaton sa kapangulohan, sa pagdawat og mga pagpadayag; ug alang sa buluhaton sa pagpangalagad sa kapangulohan, sa tanang butang mahitungod sa simbahan ug sa gingharian."},{"verse":4,"text":"Sa pagkatinuod sultihan ko kamo, nga kini pagatukoron sa kalim-an ug lima ug kan-oman ug lima ka tiil ang gilapdon ug ang gitas-on niini, sa sulod nga hawanan."},{"verse":5,"text":"Ug adunay hawanan sa ubos ug sa taas, sumala sa sundanan nga ihatag kaninyo human niini."},{"verse":6,"text":"Ug kini ipahinungod ngadto sa Ginoo, gikan sa tukoranan niini, sumala sa kapunongan sa pagkapari, sumala sa sundanan nga ihatag nganha kaninyo sa umaabot."},{"verse":7,"text":"Ug ihalad kini sa kinatibuk-an ngadto sa Ginoo alang sa buluhaton sa unang kapangulohan."},{"verse":8,"text":"Ug dili ninyo itugot nga adunay mahugaw nga butang nga mosulod niini; ug ang akong himaya maanaa dinha, ug ang akong presensiya maanaa dinha."},{"verse":9,"text":"Apan kon adunay mosulod niini nga bisan unsa nga mahugaw nga butang, ang akong himaya mawala dinha; ug ang akong presensiya dili moduol niini."},{"verse":10,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ang ikaduha nga lote sa habagatan kinahanglan nga ipahinungod ngari kanako aron tukoran og balay alang kanako, alang sa buluhaton sa pag-imprinta sa paghubad sa akong mga kasulatan, ug sa tanang butang bisan unsa nga akong isugo kaninyo."},{"verse":11,"text":"Ug kalim-an ug lima ug kan-oman ug lima ka tiil ang gilapdon niini ug ang gitas-on niini, sa sulod nga hawanan; ug adunay hawanan sa ubos ug sa taas."},{"verse":12,"text":"Ug ang kinatibuk-an niini nga balay ipahinungod ngadto sa Ginoo gikan sa tukoranan niini, alang sa buluhaton sa pag-imprinta, sa tanang bisan unsa nga akong isugo kaninyo, aron mahimong balaan, walay lama, sumala sa sundanan sa tanang butang ingon nga kini igahatag kaninyo."},{"verse":13,"text":"Ug sa ikatulong lote makadawat ang akong sulugoon nga si Hyrum Smith sa iyang kabilin."},{"verse":14,"text":"Ug sa una ug sa ikaduhang mga lote sa amihanan makadawat ang akong mga sulugoon nga sila si Reynolds Cahoon ug Jared Carter sa ilang mga kabilin—"},{"verse":15,"text":"Aron buhaton nila ang buhat nga akong gisangon kanila, nga mahimong komitiba sa pagtukod sa akong mga balay, sumala sa sugo, diin ako, ang Ginoong Dios, mihatag kaninyo."},{"verse":16,"text":"Kining duha ka balay dili pagatukoron hangtod ako mohatag kaninyo og sugo kabahin niini."},{"verse":17,"text":"Ug karon dili ako mohatag pa kaninyo og pagpadayag niining panahona. Amen."}]},{"chapter":95,"verses":[{"verse":1,"text":"Sa pagkatinuod, kini ang gisulti sa Ginoo kaninyo nga akong gihigugma, ug sila nga akong gihigugma pantonon ko usab aron ang ilang mga sala mapasaylo, kay uban sa pagpanton ako nag-andam og paagi alang sa ilang paglingkawas sa tanang butang gikan sa tentasyon, ug ako naghigugma kaninyo—"},{"verse":2,"text":"Mao nga, gikinahanglan gayod nga kamo pantonon ug badlongon sa akong atubangan;"},{"verse":3,"text":"Kay nakasala kamo batok kanako og bug-at kaayo nga sala, kay wala kamo maghunahuna sa mahinungdanon nga sugo sa tanang butang, nga akong gihatag kaninyo mahitungod sa pagtukod sa akong balay;"},{"verse":4,"text":"Alang sa pagpangandam nga akong gilaraw sa pag-andam sa akong mga apostol sa pagpul-ong sa akong ubasan sa kataposang higayon, aron akong ipahitabo ang akong katingad-an nga buhat, aron akong ibu-bo ang akong Espiritu sa tanang unod—"},{"verse":5,"text":"Apan tan-awa, sa pagkatinuod sultihan ko kamo nga daghan na uban kaninyo ang naordinahan kinsa akong gitawag apan gamay lang kanila ang napili."},{"verse":6,"text":"Sila nga wala mapili nakasala og bug-at kaayo nga sala, diin sila naglakaw sa kangitngit sa udtong tutok."},{"verse":7,"text":"Ug tungod niini nga hinungdan gihatagan ko kamo og sugo nga kamo kinahanglan nga magpatawag sa inyong sagradong panagtigom, nga ang inyong mga pagpuasa ug ang inyong mga pagbangotan moabot sa mga dunggan sa Ginoo sa mga Panon, nga kon hubaron, ang tiglalang sa unang adlaw, ang sinugdanan ug ang kataposan."},{"verse":8,"text":"Oo, sa pagkatinuod sultihan ko kamo, hatagan ko kamo og sugo nga gikinahanglan kamong magtukod og balay, diin sa sulod niini nga balay akong gilaraw nga tugahan kadtong akong gipili sa gahom gikan sa kahitas-an;"},{"verse":9,"text":"Kay mao kini ang saad sa Amahan nganha kaninyo; busa sugoon ko kamo nga magpabilin, gani sama sa akong mga apostol sa Jerusalem."},{"verse":10,"text":"Bisan pa niana, ang akong mga sulugoon nakasala og bug-at kaayo nga sala; ug ang mga panagbingkil nahitabo sa tulunghaan sa mga propeta; nga bug-at kaayo ngari kanako, miingon ang Ginoo; busa sila akong gipapahawa aron pantonon."},{"verse":11,"text":"Sa pagkatinuod sultihan ko kamo, akong kabubut-on nga magtukod kamo og balay. Kon maghupot kamo sa akong mga sugo maangkon ninyo ang gahom sa pagtukod niini."},{"verse":12,"text":"Kon dili kamo maghupot sa akong mga sugo, ang gugma sa Amahan dili magpadayon uban kaninyo, busa maglakaw kamo sa kangitngit."},{"verse":13,"text":"Karon aniay kaalam, ug ang hunahuna sa Ginoo—itukod ang balay, dili sama sa paagi sa kalibotan, kay wala ko ihatag kaninyo nga magpuyo kamo sama sa paagi sa kalibotan;"},{"verse":14,"text":"Busa, tukora kini sama sa paagi nga ipakita ko kaninyong tulo, kon kinsa ang inyong itudlo ug ordinahan ngadto niini nga gahom."},{"verse":15,"text":"Ug ang gidak-on niini may kalim-an ug lima ka tiil ang gilapdon, ug himoa kini nga kan-oman ug lima ka tiil ang gitas-on, sa sulod nga hawanan niini."},{"verse":16,"text":"Ug himoa ang ubos nga bahin sa sulod nga hawanan nga ipahinungod ngari kanako alang sa inyong halad sa sakramento, ug alang sa inyong mga pagsangyaw, ug sa inyong pagpuasa, ug sa inyong pag-ampo, ug sa paghalad sa inyong labing balaan nga mga katuyoan ngari kanako, nagsulti ang Ginoo."},{"verse":17,"text":"Ug himoa ang taas nga bahin sa sulod nga korte nga ipahinungod ngari kanako alang sa tulunghaan sa akong mga apostol, nagsulti ang Anak nga si Ahman; o, sa laing mga pulong, si Alphus; o, sa laing pulong, si Omegus; gani si Jesukristo ang inyong Ginoo. Amen."}]},{"chapter":96,"verses":[{"verse":1,"text":"Tan-awa, sultihan ko kamo, ania ang kaalam, nga pinaagi niini inyong masayran unsa ang buhaton mahitungod niining butanga, kay mahinungdanon alang kanako nga kini nga stake nga akong gipahiluna alang sa kalig-on sa Zion kinahanglan nga himoong lig-on."},{"verse":2,"text":"Busa, ipadumala sa akong sulugoon nga si Newel K.Whitney ang dapit nga inyong gihisgotan, diin akong gilaraw nga itukod ang akong balaan nga balay."},{"verse":3,"text":"Ug usab, ilote-lote ang pagbahin niini, sumala sa kaalam, alang sa kaayohan niadtong nagtinguha og mga kabilin, sama sa unsay mahukman pinaagi sa konseho taliwala kaninyo."},{"verse":4,"text":"Busa, paminaw kamo aron makakita niini nga mga butang, ug kana nga bahin nga gikinahanglan aron makaayo sa akong kapunongan, alang sa katuyoan sa pagdala sa akong pulong ngadto sa mga anak sa katawhan."},{"verse":5,"text":"Kay tan-awa, sa pagkatinuod sultihan ko kamo, kini ang labing mahinungdanon alang kanako, nga ang akong mga pulong kinahanglan mahiadto sa mga anak sa katawhan, alang sa katuyoan sa paglukmay sa mga kasingkasing sa mga anak sa katawhan alang sa inyong kaayohan. Ug mao gayod kana. Amen."},{"verse":6,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kaalam kini ug mahinungdanon alang kanako, nga ang akong sulugoon nga si John Johnson kansang halad akong gidawat, ug kansang mga pag-ampo akong gidungog, kinsa akong gihatagan og saad sa kinabuhing dayon kon ugaling tumanon niya ang akong mga sugo gikan karon—"},{"verse":7,"text":"Kay kaliwat siya ni Jose ug mag-aambit sa mga panalangin sa saad nga gihimo ngadto sa iyang mga amahan—"},{"verse":8,"text":"Sa pagkatinuod sultihan ko kamo, mahinungdanon alang kanako nga mahimo siyang sakop sa kapunongan, nga motabang siya sa pagdala sa akong pulong ngadto sa mga anak sa katawhan."},{"verse":9,"text":"Busa ordinahan ninyo siya niini nga panalangin, ug magtinguha siya nga makugihon sa pagbayad sa mga balayranan niana nga balay nga inyong gihinganlan, aron makapuyo siya niini. Ug mao gayod kana. Amen."}]},{"chapter":97,"verses":[{"verse":1,"text":"Sa pagkatinuod sultihan ko kamo akong mga higala, mamulong ako kaninyo pinaagi sa akong tingog, gani sa tingog sa akong Espiritu, aron akong mapakita kaninyo ang akong kabubut-on mahitungod sa inyong kaigsoonan diha sa yuta sa Zion, nga ang kadaghanan kanila tinuod nga mapainubsanon ug makugihon nga nangita aron makaangkon og kaalam ug aron makakaplag og kamatuoran."},{"verse":2,"text":"Sa pagkatinuod, sa pagkatinuod sultihan ko kamo, bulahan ang sama niana, kay sila makaangkon og kaalam; kay ako, ang Ginoo, mopakita og kaluoy ngadto sa tanan nga maaghop, ug ngadto sa tanan nga akong kaluy-an, nga ako mahatagan og kaangayan sa panahon nga dad-on ko sila ngadto sa paghukom."},{"verse":3,"text":"Tan-awa, sultihan ko kamo, mahitungod sa tulunghaan sa Zion, ako, ang Ginoo, nahimuot kaayo nga adunay tulunghaan sa Zion, ug usab sa akong sulugoon nga si Parley P. Pratt, kay nagmatinud-anon siya kanako."},{"verse":4,"text":"Ug kon ugaling magpadayon siya nga magmatinud-anon kanako magpadayon siya sa pagdumala sa tulunghaan sa yuta sa Zion hangtod nga siya akong mahatagan og ubang mga sugo."},{"verse":5,"text":"Ug panalanginan ko siya og daghang panalangin, sa pagpahayag sa tanang kasulatan ug mga misteryo alang sa kaayohan sa tulunghaan, ug sa simbahan sa Zion."},{"verse":6,"text":"Ug ngadto sa uban pang mga sakop sa tulunghaan, ako, ang Ginoo, andam nga mopakita og kaluoy; hinuon, aduna pa kanila ang kinahanglan nga mapanton, ug ang ilang mga binuhatan ipadayag."},{"verse":7,"text":"Ang atsa gipahimutang na sa gamot sa mga kahoy; ug ang matag kahoy nga dili magdala og maayong mga bunga pagaputlon ug itambog sa kalayo. Ako, ang Ginoo, namulong niini."},{"verse":8,"text":"Sa pagkatinuod sultihan ko kamo, ang tanan kanila nga nasayod nga ang ilang mga kasingkasing matinud-anon, ug masulub-on, ug ang ilang mga espiritu mahinulsolon, ug matinguhaon nga motuman sa ilang mga pakigsaad pinaagi sa pagsakripisyo—oo, sa matag sakripisyo nga ako, ang Ginoo, magasugo—sila pagadawaton ko."},{"verse":9,"text":"Kay ako, ang Ginoo, mosugo kanila sa pagpatubo og usa ka mabungahon kaayo nga kahoy nga gitanom sa maayong yuta, daplin sa lunsay nga sapa, nga mamunga og bililhon kaayong mga bunga."},{"verse":10,"text":"Sa pagkatinuod sultihan ko kamo, kabubut-on ko kini nga adunay balay nga itukod alang kanako sa yuta sa Zion, sama sa sundanan nga gihatag ko na kaninyo."},{"verse":11,"text":"Oo, itukod kini sa labing madali, pinaagi sa ikapulo sa akong katawhan."},{"verse":12,"text":"Tan-awa, kini ang ikapulo ug ang sakripisyo diin ako, ang Ginoo, nangayo gikan sa ilang mga kamot, aron adunay balay nga matukod ngari kanako alang sa kaluwasan sa Zion—"},{"verse":13,"text":"Isip usa ka dapit nga kapasalamatan alang sa tanang santos, ug isip usa ka dapit alang sa pagpanudlo sa tanan nga gitawag ngadto sa buhat sa pangalagad sa tanan nilang balaan nga mga tawag ug mga katungdanan;"},{"verse":14,"text":"Aron mahingpit ang ilang pagsabot sa ilang pagpangalagad, sa teoriya, sa baroganan, ug sa doktrina, sa tanang butang nga may kalabotan sa gingharian sa Dios dinhi sa yuta, sa mga yawe sa maong gingharian nga gitugyan diha kaninyo."},{"verse":15,"text":"Ug kon ang akong mga katawhan motukod og balay ngari kanako sa ngalan sa Ginoo, ug dili motugot sa bisan unsang mahugaw nga butang nga mosulod niini, aron dili kini mahugawan, ang akong himaya mopuyo diha niini;"},{"verse":16,"text":"Oo, ug ang akong presensya maanaa didto, kay ako mosulod niini, ug ang tanang putli og kasingkasing nga mosulod niini makakita sa Dios."},{"verse":17,"text":"Apan kon mahugawan kini ako dili mosulod niini, ug ang akong himaya wala diha; kay ako dili mosulod nganha sa mga templo nga dili balaan."},{"verse":18,"text":"Ug, karon, tan-awa, kon ang Zion mohimo niining mga butanga mouswag siya, ug mopakuyanap sa iyang kaugalingon, ug mahimong labing mahimayaon, labing bantogan, ug labing makahahadlok."},{"verse":19,"text":"Ug ang mga nasod sa yuta mopasidungog kaniya, ug moingon: Sa pagkatinuod ang Zion mao ang siyudad sa atong Dios, ug sa pagkatinuod ang Zion dili mapukan, ni mapapahawa gikan sa iyang dapit, kay ang Dios anaa niana nga dapit, ug ang kamot sa Ginoo anaa niana nga dapit;"},{"verse":20,"text":"Ug iyang gipanumpa pinaagi sa gahom sa iyang kusog nga siya moluwas ug mopanalipod sa iyang taas nga tore."},{"verse":21,"text":"Busa, sa pagkatinuod, ingon niini ang gisulti sa Ginoo, tugoti ang Zion nga magmaya, kay kini ang Zion—ang putli og kasingkasing; busa, tugoti ang Zion nga maglipay, samtang ang tanang daotan magbangotan."},{"verse":22,"text":"Kay tan-awa, ug sud-onga, ang panimalos kalit nga moabot ngadto sa mga dili diosnon sama sa alimpulos; ug kinsa ang makalingkawas niini?"},{"verse":23,"text":"Ang silot sa Ginoo moagi inigka-gabii ug inigka-adlaw, ug ang asoy mahitungod niini makapahasol sa tanang katawhan; oo, dili kini mahunong hangtod nga moabot ang Ginoo;"},{"verse":24,"text":"Kay ang kayugot sa Ginoo napukaw batok sa ilang mga pagkasalawayon ug sa ilang tanan nga daotang buhat."},{"verse":25,"text":"Bisan pa niana, ang Zion makalingkawas kon magtinguha siya sa pagbuhat sa tanan nga akong gisugo kaniya."},{"verse":26,"text":"Apan kon dili siya magtinguha sa pagbuhat sa bisan unsa nga akong gisugo kaniya, pagaduawon ko siya sumala sa tanan niyang mga binuhatan, dala ang mahapdos nga kasakitan, dala ang kamatay, dala ang kadaot, dala ang espada, dala ang panimalos, dala ang molamoy nga kalayo."},{"verse":27,"text":"Bisan pa niana, ipabasa kini sa makausa ngadto sa iyang mga dunggan, nga ako, ang Ginoo, midawat na sa iyang halad; ug kon dili na siya magpakasala walay bisan usa niining mga butanga ang moabot kaniya;"},{"verse":28,"text":"Ug ako manalangin kaniya og mga panalangin, ug mopasanay sa daghang panalangin ngadto kaniya, ug sa iyang mga henerasyon hangtod sa kahangtoran, nagsulti ang Ginoo nga imong Dios. Amen."}]},{"chapter":98,"verses":[{"verse":1,"text":"Sa pagkatinuod sultihan ko kamo akong mga higala, ayaw kahadlok, hupaya ang inyong mga kasingkasing; oo, maglipay hangtod sa hangtod, ug pasalamati ang tanang butang;"},{"verse":2,"text":"Pagmapailobon nga maghulat sa Ginoo, kay ang inyong mga pag-ampo nakasulod na sa mga dunggan sa Ginoo sa mga Panon, ug natala uban niini nga selyo ug tugon—ang Ginoo nanumpa ug nagtakda nga kini igahatag."},{"verse":3,"text":"Busa, naghatag siya niini nga saad nganha kaninyo, uban sa dili mausab nga pakigsaad nga kini matuman; ug ang tanang butang nga nakahatag kaninyo og kasakitan makatabang alang sa inyong kaayohan, ug sa himaya sa akong ngalan, nagsulti ang Ginoo."},{"verse":4,"text":"Ug karon, sa pagkatinuod sultihan ko kamo mahitungod sa mga balaod sa yuta, akong kabubut-on nga ang akong katawhan magtinguha sa pagbuhat sa tanang butang bisan unsa ang akong isugo kanila."},{"verse":5,"text":"Ug kana nga balaod sa yuta nga nagsubay sa batakang balaod, nga nagsuporta nianang baroganan sa kagawasan sa pagpatunhay sa mga katungod ug sa mga kahigayonan, iya sa tanang katawhan, ug makataronganon sa akong atubangan."},{"verse":6,"text":"Busa, ako, ang Ginoo, mohatag kaninyo og kaangayan, ug sa inyong kaigsoonan sa akong simbahan, sa pagpakighigala nianang balaod nga mao ang batakang balaod sa yuta;"},{"verse":7,"text":"Ug mahitungod sa balaod sa tawo, bisan unsa nga adunay sobra o adunay kulang kay sa niini, naggikan sa daotan."},{"verse":8,"text":"Ako, ang Ginoong Dios, mohimo kaninyo nga gawasnon, busa gawasnon gayod kamo; ug ang balaod usab mohimo kaninyong gawasnon."},{"verse":9,"text":"Hinuon, kon ang daotan magmando ang katawhan magbangotan."},{"verse":10,"text":"Mao nga, ang mga tawo nga matinuoron ug maalamon kinahanglan nga pangitaon sa tumang kakugi, ug ang mga tawo nga maayo ug maalamon inyo gayod nga buligan; kay kon dili ang bisan unsa nga mas menos niini naggikan sa daotan."},{"verse":11,"text":"Ug ako mohatag kaninyo og usa ka sugo, nga kamo mosalikway sa tanang daotan ug mounong sa tanang maayo, nga kamo magpakabuhi sa matag pulong nga mogawas gikan sa ba-ba sa Dios."},{"verse":12,"text":"Kay mohatag siya ngadto sa matinud-anon og pagtulun-an human sa laing pagtulun-an, sugo human sa laing sugo; ug ako mosulay kaninyo ug mosukod kaninyo pinaagi niini."},{"verse":13,"text":"Ug kinsa kadtong mohatag sa iyang kinabuhi alang sa akong gimbuhaton, alang sa kaayohan sa akong ngalan, makakaplag niini pag-usab, gani sa kinabuhing dayon."},{"verse":14,"text":"Busa, ayaw kahadlok sa inyong mga kaaway, kay ako nakahukom na sa akong kasingkasing, misulti ang Ginoo, nga ako mosukod kaninyo sa tanang butang, kon kamo motuman ba sa akong pakigsaad, bisan ngadto sa kamatayon, aron kamo makita nga takos."},{"verse":15,"text":"Kay kon dili kamo magsubay sa akong pakigsaad dili kamo takos kanako."},{"verse":16,"text":"Busa, isalikway ang gubat ug ipahayag ang kalinaw, ug tinguhaa nga makugihon ang pagpabalik sa mga kasingkasing sa mga anak ngadto sa ilang mga amahan, ug sa mga kasingkasing sa mga amahan ngadto sa mga anak;"},{"verse":17,"text":"Ug usab, ang mga kasingkasing sa mga Judeo ngadto sa mga propeta, ug ang mga propeta ngadto sa mga Judeo; basin pa unya ako moabot ug mohampak sa tibuok yuta sa usa ka tunglo, ug ang tanang tawo maugdaw sa akong atubangan."},{"verse":18,"text":"Himoa nga dili mahasol ang inyong mga kasingkasing; kay didto sa balay sa akong Amahan adunay daghang mansyon, ug nag-andam na ako og dapit alang kaninyo; ug kon hain ang akong Amahan ug ako, atua usab kamo."},{"verse":19,"text":"Tan-awa, ako, ang Ginoo, wala mahimuot sa daghan nga anaa sa simbahan sa Kirtland;"},{"verse":20,"text":"Kay dili sila mosalikway sa ilang mga sala, ug sa ilang daotang mga paagi, sa garbo sa ilang kasingkasing, ug sa ilang pagkamasinahon, ug sa ilang tanang salawayon nga mga butang, ug sa pagsunod sa mga pulong sa kaalam ug sa kinabuhing dayon nga akong gihatag kanila."},{"verse":21,"text":"Sa pagkatinuod sultihan ko kamo, nga ako, ang Ginoo, mopanton kanila ug mobuhat sa bisan unsa nga akong gusto, kon dili sila maghinulsol ug mosunod sa tanang butang sa bisan unsa nga ako nang gikasulti kanila."},{"verse":22,"text":"Ug usab sultihan ko kamo, kon magtinguha kamo sa pagbuhat sa bisan unsa nga akong isugo kaninyo, ako ang Ginoo, mopahilayo sa tanang kapungot ug kasuko gikan kaninyo, ug ang mga ganghaan sa impyerno dili makabuntog batok kaninyo."},{"verse":23,"text":"Karon, mamulong ako kaninyo mahitungod sa inyong mga pamilya—kon ang mga tawo mopasakit kaninyo, o sa inyong mga pamilya, sa usa ka higayon, ug moantos kamo niini nga mapailobon ug dili moyubit batok kanila, ni magtinguha og panimalos, pagagantihan kamo;"},{"verse":24,"text":"Apan kon dili kamo moantos niini nga mapailobon, pagaisipon kini nga usa ka makiangayong silot nga gipahamtang nganha kaninyo."},{"verse":25,"text":"Ug usab, kon ang inyong kaaway mohampak kaninyo sa ikaduhang higayon, ug dili kamo mobalos batok sa inyong kaaway, ug moantos niini sa tumang pagpailob, ang inyong ganti mapilo-pilo sa kagatosan."},{"verse":26,"text":"Ug usab, kon siya mohampak kaninyo sa ikatulo nga higayon, ug kamo moantos niini nga mapailobon, ang inyong ganti madoble alang kaninyo sa makaupat;"},{"verse":27,"text":"Ug kining tulo ka pagpamatuod mobarog batok sa inyong kaaway kon dili siya maghinulsol, ug dili mapapas."},{"verse":28,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, kon kana nga kaaway makaikyas sa akong panimalos, aron dili siya madala ngadto sa paghukom sa akong atubangan, seguroha ninyo nga kamo mopasidaan kaniya pinaagi sa akong ngalan, aron dili na siya mosulong kaninyo, ni sa inyong mga pamilya, bisan sa mga anak sa inyong mga anak ngadto sa ikatulo ug ikaupat nga henerasyon."},{"verse":29,"text":"Ug unya, kon mosulong siya kaninyo o sa inyong mga anak, o sa mga anak sa inyong mga anak ngadto sa ikatulo ug ikaupat nga henerasyon, akong gitugyan ang inyong kaaway sa inyong mga kamot;"},{"verse":30,"text":"Ug unya kon pasayloon ninyo siya, kamo pagagantihan tungod sa inyong pagkamatarong; ug usab ang inyong mga anak ug mga anak sa inyong mga anak ngadto sa ikatulo ug ikaupat nga henerasyon."},{"verse":31,"text":"Bisan pa niana, ang inyong kaaway anaa sa inyong mga kamot; ug kon gantihan ninyo siya sumala sa iyang mga buhat ipakamatarong kamo; kon nagtinguha siya sa inyong kinabuhi, ug ang inyong kinabuhi anaa sa kakuyaw tungod kaniya, ang inyong kaaway anaa sa inyong mga kamot ug ipakamatarong kamo."},{"verse":32,"text":"Tan-awa, mao kini ang balaod nga akong gihatag ngadto sa akong sulugoon nga si Nephi, ug sa inyong mga amahan, nga sila si Jose, ug Jacob, ug Isaac, ug Abraham, ug sa akong tanan nga karaang mga propeta ug apostoles."},{"verse":33,"text":"Ug usab, mao kini ang balaod nga akong gihatag ngadto sa akong karaang katawhan, nga dili gayod sila makig-away batok sa bisan unsa nga nasod, kaliwatan, pinulongan, o katawhan, gawas nga ako, ang Ginoo, magsugo kanila."},{"verse":34,"text":"Ug kon ang bisan unsa nga nasod, pinulongan, o mga katawhan, mopadayag gayod og gubat batok kanila, sila kinahanglang motanyag una og sumbanan sa kalinaw ngadto niana nga katawhan, kanasoran, o pinulongan;"},{"verse":35,"text":"Ug kon kana nga katawhan dili modawat sa tanyag sa kalinaw, ni sa ikaduha ni sa ikatulo nga higayon, kinahanglan dad-on nila kini nga mga pagpamatuod sa atubangan sa Ginoo;"},{"verse":36,"text":"Dayon ako, ang Ginoo, mohatag kanila og sugo, ug mopakamatarong kanila sa pagpakiggubat batok niana nga nasod, pinulongan, o katawhan."},{"verse":37,"text":"Ug ako, ang Ginoo, makig-away sa ilang mga gubat, ug sa mga gubat sa ilang mga anak, ug sa mga anak sa ilang mga anak, hangtod nga sila makapanimalos sa ilang kaugalingon ngadto sa ilang tanan nga kaaway, ngadto sa ikatulo ug ikaupat nga henerasyon."},{"verse":38,"text":"Tan-awa, usa kini ka sanglitanan ngadto sa tanan nga katawhan, nagsulti ang Ginoo nga inyong Dios, alang sa pagpakamatarong sa akong atubangan."},{"verse":39,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kon human ang inyong kaaway makasulong na sa unang higayon, maghinulsol siya ug moduol kaninyo mohangyo sa inyong pagpasaylo, kamo mopasaylo kaniya, ug kinahanglan nga dili na ninyo kini pagaisipon nga usa ka pagpamatuod batok sa inyong kaaway—"},{"verse":40,"text":"Ug hangtod sa ikaduha ug ikatulo nga higayon; ug bisan sa matag higayon nga ang inyong kaaway maghinulsol sa kalapasan diin siya nakalapas batok kaninyo, inyo siya nga pasayloon hangtod sa kapitoang higayon pilopiloon og kapito."},{"verse":41,"text":"Ug kon makalapas siya batok kaninyo ug dili maghinulsol sa unang higayon, bisan pa pasayloon ninyo siya."},{"verse":42,"text":"Ug kon makalapas siya batok kaninyo sa ikaduhang higayon, ug dili maghinulsol, bisan pa niana pasayloon ninyo siya."},{"verse":43,"text":"Ug kon makalapas siya batok kaninyo sa ikatulo nga higayon, ug dili maghinulsol, sa gihapon pasayloon ninyo siya."},{"verse":44,"text":"Apan kon makalapas siya batok kaninyo sa ikaupat nga higayon ayaw ninyo siya pasayloa, apan dad-on ninyo kini nga pagpamatuod ngadto sa atubangan sa Ginoo; ug kini dili papason hangtod nga maghinulsol siya, ug moganti kaninyo sa upat ka pilo sa tanang butang diin siya nakalapas batok kaninyo."},{"verse":45,"text":"Ug kon himoon niya kini, pasayloon ninyo siya sa inyong tibuok nga kasingkasing; ug kon dili siya mohimo niini, ako, ang Ginoo, ang mopanimalos kaninyo sa inyong kaaway sa usa ka gatos ka pilo;"},{"verse":46,"text":"Ug ngadto sa iyang mga anak, ug sa mga anak sa iyang mga anak sa tanan kanila nga nasilag kanako, ngadto sa ikatulo ug ikaupat nga henerasyon."},{"verse":47,"text":"Apan kon ang mga anak maghinulsol, o ang mga anak sa mga anak, ug mobalik sa Ginoo nga ilang Dios, sa tibuok nilang kasingkasing ug sa tanan nila nga gahom, hunahuna, ug kusog, ug mopahiuli sa kaupat nga gidaghanon sa tanan nilang kalapasan diin sila nakalapas, o diin ang ilang mga amahan nakalapas, o ang amahan sa ilang mga amahan, niana ang inyong kasuko mawala;"},{"verse":48,"text":"Ug ang panimalos dili na moabot kanila, nagsulti ang Ginoo nga inyong Dios, ug ang ilang kalapasan dili na dad-on sa atubangan sa Dios isip usa ka pagpamatuod batok kanila. Amen."}]},{"chapter":99,"verses":[{"verse":1,"text":"Tan-awa, sa ingon niana miingon ang Ginoo ngadto sa akong sulugoon nga si John Murdock—Gitawag ka sa pag-adto sa silangang mga nasod gikan sa usa ka balay ngadto sa laing balay, gikan sa usa ka balangay ngadto sa laing balangay, ug gikan sa usa ka siyudad ngadto sa laing siyudad, sa pagsangyaw sa akong walay kataposang ebanghelyo ngadto sa mga lumulupyo niini, taliwala sa pagpanglutos ug pagkadaotan."},{"verse":2,"text":"Ug kinsa kadtong modawat kanimo modawat kanako; ug makabaton ikaw og gahom sa pagpadayag sa akong pulong pinaagi sa pagpadayag sa akong Balaang Espiritu."},{"verse":3,"text":"Ug kadtong modawat kanimo sama sa usa ka gamay nga bata, makadawat sa akong gingharian; ug bulahan sila, kay makaangkon sila og kaluoy."},{"verse":4,"text":"Ug kadtong mosalikway kanimo isalikway sa akong Amahan ug sa iyang balay; ug limpyohan nimo ang imong mga tiil sa tinago nga mga dapit diha sa agianan alang sa usa ka pagpamatuod batok kanila."},{"verse":5,"text":"Ug tan-awa, ug sud-onga, ako moabot sa dili madugay aron sa paghukom, sa pagmatuod sa ilang tanang buhat nga dili diosnon nga ilang gihimo batok kanako, sama sa daghang nahisulat mahitungod kanako diha sa basahon sa kasulatan."},{"verse":6,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, wala kinahanglana nga molakaw kamo hangtod nga ang inyong mga anak masangkapan sa panginahanglan, ug sa mabination nga paagi ipadala ngadto sa bishop sa Zion."},{"verse":7,"text":"Ug human sa pipila ka tuig, kon ikaw magtinguha gikan kanako, mahimo usab nga moadto ka sa maayo nga yuta, aron makaangkon sa imong kabilin;"},{"verse":8,"text":"Gawas niini ikaw mopadayon sa pagsangyaw sa akong ebanghelyo hangtod nga ikaw pagakuhaon. Amen."}]},{"chapter":100,"verses":[{"verse":1,"text":"Sa pagkatinuod, kini ang gisulti sa Ginoo nganha kaninyo, akong mga higala nga Sidney ug Joseph, ang inyong mga pamilya anaa sa maayo nga kahimtang; ania sila sa akong mga kamot, ug akong himoon alang kanila kon unsa ang akong gibati nga maayo; kay ania kanako ang tanang gahom."},{"verse":2,"text":"Busa, sunod kanako, ug paminaw sa mga tambag nga akong ihatag kaninyo."},{"verse":3,"text":"Tan-awa, ug sud-onga, ako adunay daghang katawhan niini nga dapit, sa naglibot nga mga rehiyon; ug ang usa ka mahinungdanon nga pultahan pagaablihan diha sa naglibot nga mga rehiyon niining silangan nga bahin sa yuta."},{"verse":4,"text":"Busa, ako, ang Ginoo, nagtugot kaninyo sa pag-anhi niini nga dapit; kay alang kanako mahinungdanon kini alang sa kaluwasan sa mga kalag."},{"verse":5,"text":"Busa, sa pagkatinuod sultihan ko kamo, ipataas ang inyong mga tingog ngadto niini nga katawhan; ipamulong ang mga hunahuna nga akong ibutang sa inyong mga kasingkasing, ug kamo dili pagalibogon sa atubangan sa mga tawo;"},{"verse":6,"text":"Kay igahatag ra kini kaninyo sa takna gayod, oo, niana gayod nga higayon, kon unsa ang inyong isulti."},{"verse":7,"text":"Apan usa ka sugo ang akong ihatag kaninyo, nga kamo mopahayag sa bisan unsang butang nga inyong ipahayag pinaagi sa akong ngalan, sa kaligdong sa kasingkasing, pinaagi sa espiritu sa kaaghop, sa tanang butang."},{"verse":8,"text":"Ug ihatag ko kaninyo kini nga saad, nga kon ugaling buhaton ninyo kini ang Espiritu Santo igabu-bo aron sa pagpamatuod sa tanang butang bisan unsa ang inyong isulti."},{"verse":9,"text":"Ug mahinungdanon alang kanako nga ikaw, akong sulugoon nga Sidney, mahimong tigpama-ba ngadto niini nga katawhan; oo, sa pagkatinuod, ako moordina kanimo niini nga katungdanan, gani nga mamahimong tigpama-ba sa akong sulugoon nga si Joseph."},{"verse":10,"text":"Ug hatagan ko siya og gahom nga mamahimong gamhanan sa pagpamatuod."},{"verse":11,"text":"Ug hatagan ko ikaw og gahom nga mahimong gamhanan sa pagpasabot sa tanang kasulatan, nga mahimo ikaw nga tigpama-ba ngadto kaniya, ug siya mahimo nga usa ka tigpadayag nganha kanimo, nga ikaw gayod masayod sa katiunay sa tanang butang kalabot sa mga butang sa akong gingharian dinhi sa yuta."},{"verse":12,"text":"Busa, padayon sa inyong panaw ug himoa ang inyong kasingkasing nga magmaya; kay tan-awa ug sud-onga, mag-uban ako kaninyo gani ngadto sa kataposan."},{"verse":13,"text":"Ug karon hatagan ko kamo og usa ka pulong mahitungod sa Zion. Ang Zion pagatubson, bisan tuod og gipanton siya sulod sa mubo nga panahon."},{"verse":14,"text":"Ang inyong mga igsoong lalaki, ang akong mga sulugoon nga sila si Orson Hyde ug si John Gould, ania sa akong mga kamot; ug tungod kay naghupot sila sa akong mga sugo pagaluwason sila."},{"verse":15,"text":"Busa, tugoti ang inyong mga kasingkasing nga mahupay; kay ang tanang butang magkatambayayong alang kanila nga maglakaw nga matarong, ug sa pagkahimong balaan sa simbahan."},{"verse":16,"text":"Kay mopasanay ako ngari kanako og usa ka putli nga katawhan, aron moalagad kanako diha sa pagkamatarong;"},{"verse":17,"text":"Ug ang tanan nga motawag sa ngalan sa Ginoo, ug magtuman sa iyang mga sugo, pagaluwason. Ug mao gayod kana. Amen."}]},{"chapter":101,"verses":[{"verse":1,"text":"Sa pagkatinuod sultihan ko kamo, mahitungod sa inyong kaigsoonan kinsa gisakit, ug gilutos, ug gipapahawa gikan sa yuta nga ilang kabilin—"},{"verse":2,"text":"Ako, ang Ginoo, mitugot sa kasakit nga moabot kanila, diin sila gisakit, agi og sangpotanan sa ilang mga kalapasan;"},{"verse":3,"text":"Gani ako moangkon kanila, ug mahimo sila nga akoa niana nga adlaw nga ako moabot aron sa pagpundok sa akong mga bahandi."},{"verse":4,"text":"Busa, kinahanglan nga mapanton sila ug masulayan, sama ni Abraham, nga gisugo sa paghalad sa iyang bugtong anak."},{"verse":5,"text":"Kay ang tanan niadtong dili molahutay sa pagpanton, apan molimod kanako, dili mabalaan."},{"verse":6,"text":"Tan-awa, sultihan ko kamo, adunay mga pagtay-og, ug mga panagbingkil, ug mga kasina, ug mga panagbangi, ug kahigal ug maibogon nga mga tinguha taliwala kanila; busa pinaagi niini nga mga butang gihugaw-hugawan nila ang ilang mga kabilin."},{"verse":7,"text":"Dugay sila nga mopatalinghog sa tingog sa Ginoo nga ilang Dios; busa, ang Ginoo nga ilang Dios dugay nga mopatalinghog sa ilang mga pag-ampo, sa pagtubag kanila sa adlaw sa ilang kasamok."},{"verse":8,"text":"Sa adlaw sa ilang kalinaw gibaliwala nila ang akong tambag; apan, sa adlaw sa ilang kasamok, sa panginahanglan nangita sila kanako."},{"verse":9,"text":"Sa pagkatinuod sultihan ko kamo, bisan pa sa ilang mga sala, ang akong kasingkasing napuno sa kapuangod ngadto kanila. Ako dili mosalikway kanila sa hingpit; ug sa adlaw sa kaligutgot akong hinumdoman ang kaluoy."},{"verse":10,"text":"Nakapanumpa ako, ug ang balaod ninglabay na pinaagi sa nahauna nga sugo nga akong gihatag kaninyo, nga akong ihulog ang espada sa akong kasuko alang sa akong katawhan; ug gani sumala sa akong gisulti, kini mahitabo."},{"verse":11,"text":"Ang akong kasuko sa dili madugay ibubo nga walay sukod nganha sa tanang nasod; ug buhaton ko kini kon ang kopa sa ilang kadaotan mapuno na."},{"verse":12,"text":"Ug niana nga adlaw ang tanan nga makaplagan nga nagabantay, o sa laing pagkasulti, ang tanan sa akong Israel, pagaluwason."},{"verse":13,"text":"Ug sila nga nagkatibulaag pagapundokon."},{"verse":14,"text":"Ug silang tanan nga nagbangotan pagahupayon."},{"verse":15,"text":"Ug silang tanan nga mitugyan sa ilang kinabuhi alang sa akong ngalan pagakoronahan."},{"verse":16,"text":"Busa, himoa nga ang inyong mga kasingkasing mahupay mahitungod sa Zion; kay ang tanang tawo ania sa akong mga kamot; pagmalinawon ug hibaloi nga ako mao ang Dios."},{"verse":17,"text":"Ang Zion dili pagakuhaon gikan sa iyang dapit, bisan pa og ang iyang mga anak nagkatibulaag."},{"verse":18,"text":"Sila nga nahibilin, ug putli og kasingkasing, makabalik, ug makaadto sa ilang mga kabilin, sila ug ang ilang mga anak, manag-awit sa walay kataposang kalipay, sa pagtukod sa biniyaang mga dapit sa Zion—"},{"verse":19,"text":"Ug kining tanan nga butang mahitabo aron ang pulong sa mga propeta matuman."},{"verse":20,"text":"Ug, tan-awa, walay lain nga dapit nga pilion gawas nianang akong gipili; ni adunay bisan unsa nga laing dapit nga pilion gawas nianang akong gipili, alang sa buhat sa pagpundok sa akong mga santos—"},{"verse":21,"text":"Hangtod nga moabot ang adlaw nga wala nay makita nga lawak alang kanila; ug unya ako adunay laing mga dapit nga akong ihatag kanila, ug tawagon sila og mga stake, alang sa mga tabil o kalig-on sa Zion."},{"verse":22,"text":"Tan-awa, kabubut-on ko kini, nga silang tanan nga motawag sa akong ngalan, ug mosimba kanako sumala sa akong walay kataposang ebanghelyo, magpundok, ug mobarog sa balaang mga dapit;"},{"verse":23,"text":"Ug mangandam alang sa pagpadayag nga moabot, sa higayon nga ang tabil nga gitabon sa akong templo, sa akong tabernakulo, nga nagtago sa yuta, pagakuhaon, ug ang tanang tawo makakita kanako."},{"verse":24,"text":"Ug ang matag madunot nga butang, tawo man, o mga hayop sa umahan o mga langgam sa mga langit, o mga isda sa dagat, nga nagpuyo sa ibabaw sa tibuok yuta maugdaw;"},{"verse":25,"text":"Ug usab kana nga ginama sa elemento matunaw tungod sa hilabihang kainit; ug ang tanang butang mahimong bag-o, nga ang akong kahibalo ug himaya mopuyo sa ibabaw sa tibuok yuta."},{"verse":26,"text":"Ug niana nga adlaw ang pagdumot sa tawo, ug ang pagdumot sa mga hayop, oo, ang pagdumot sa tanang unod, mahunong na sa akong atubangan."},{"verse":27,"text":"Ug niana nga adlaw bisan unsa ang pangayoon sa tawo, ihatag kini ngadto kaniya."},{"verse":28,"text":"Ug niana nga adlaw si Satanas wala nay gahom sa pagtental ni bisan kinsa nga tawo."},{"verse":29,"text":"Ug wala nay kasubo tungod kay wala nay kamatayon."},{"verse":30,"text":"Niana nga adlaw ang masuso dili mamatay hangtod siya matigulang; ug ang iyang kinabuhi sama sa panuigon sa usa ka kahoy;"},{"verse":31,"text":"Ug kon siya mamatay dili siya matulog, nga ang buot ipasabot diha sa yuta, apan mausab sa usa ka pagpamilok, ug pagabayawon, ug ang iyang kapahulayan mahimayaon."},{"verse":32,"text":"Oo, sa pagkatinuod sultihan ko kamo, niana nga adlaw inig anhi sa Ginoo, iyang ipadayag ang tanang butang—"},{"verse":33,"text":"Mga butang nga milabay na, ug tinago nga mga butang nga walay tawo nga nasayod, mga butang sa yuta, diin kini gibuhat, ug ang katuyoan ug ang kataposan niini—"},{"verse":34,"text":"Mga butang nga labing bililhon, mga butang nga anaa sa itaas ug mga butang nga ania sa ubos, mga butang dinhi sa yuta ug sa ibabaw sa yuta, ug sa langit."},{"verse":35,"text":"Ug silang tanan nga nag-antos sa pagpanggukod tungod sa akong ngalan, ug molahutay inubanan sa pagtuo, bisan kon gitawag sila aron sa paghatag sa ilang kinabuhi alang sa akong kaayohan sa gihapon makaambit sila niining tanan nga himaya."},{"verse":36,"text":"Mao nga, ayaw kahadlok bisan sa kamatayon; kay dinhi niining kalibotan ang imong kalipay dili hingpit, apan kanako ang imong kalipay hingpit."},{"verse":37,"text":"Busa, ayaw kabalaka sa lawas, ni sa kinabuhi sa lawas; apan kabalak-i ang kalag, ug ang mahitungod sa kinabuhi sa kalag."},{"verse":38,"text":"Ug pangitaa sa kanunay ang nawong sa Ginoo, nga sa pagpailob kamo makabaton sa inyong mga kalag, ug maangkon ninyo ang kinabuhing dayon."},{"verse":39,"text":"Kon ang mga tawo natawag ngadto sa akong walay kataposang ebanghelyo, ug makigsaad sa walay kataposang pakigsaad, pagaisipon sila nga asin sa yuta ug panimpla sa mga tawo;"},{"verse":40,"text":"Sila gitawag nga panimpla sa mga tawo, busa, kon kanang asin sa yuta mawagtangan sa iyang kalami, tan-awa, sukad niana kini wala nay kapuslanan ug angay na lamang isalibay ug tunob-tunoban sa mga tawo."},{"verse":41,"text":"Tan-awa, aniay kaalam mahitungod sa mga anak sa Zion, gani daghan, apan dili tanan; nasakpan sila nga mga malapason, busa kinahanglan nga sila mapanton—"},{"verse":42,"text":"Siya nga nagpataas sa iyang kaugalingon ipaubos, ug siya nga nagpaubos sa iyang kaugalingon ipataas."},{"verse":43,"text":"Ug karon, isugilon ko kaninyo ang usa ka sambingay, aron inyong mahibaloan ang akong kabubut-on mahitungod sa katubsanan sa Zion."},{"verse":44,"text":"Ang usa ka halangdon nga tawo adunay luna sa yuta, nga labing pinili; ug giingnan niya ang iyang mga sulugoon: Pangadto kamo sa akong ubasan, gani niining labing pinili nga luna sa yuta, ug pagtanom og napulog duha ka kahoy nga olibo;"},{"verse":45,"text":"Ug pagbutang og magbalantay sa palibot niini, ug pagtukod og usa ka tore, aron adunay usa nga molantaw sa yuta sa palibot, aron mahimong usa ka magbalantay diha sa tore, aron ang akong mga kahoy nga olibo dili matumba kon ang kaaway moabot aron sa pagpangguba ug pagpanguha sa bunga sa akong ubasan."},{"verse":46,"text":"Karon, ang mga sulugoon sa halangdon nga tawo miadto ug mihimo sumala sa gisugo sa ilang agalon kanila, ug mitanom sa mga kahoy nga olibo ug mitukod og ali sa palibot, ug mibutang og mga magbalantay, ug misugod sa pagtukod og tore."},{"verse":47,"text":"Ug samtang gipahiluna nila ang tukoranan niini, nagsugod sila sa pag-ingon sa ilang mga kaugalingon: Unsay gamitan sa akong agalon niini nga tore?"},{"verse":48,"text":"Ug nagtambagay sulod sa taas nga panahon, nag-ingon sa ilang mga kaugalingon: Unsa ang gamitan sa akong agalon niini nga tore, nga nagtan-aw nga kini usa ka panahon sa kalinaw?"},{"verse":49,"text":"Dili ba angay nga kining kwarta ihatag ngadto sa mga tigpailis? Kay wala na kinahanglana kini nga mga butang."},{"verse":50,"text":"Ug samtang nanagsumpaki pa sila sa usag usa nahimo silang tapulan kaayo, ug wala sila mopatalinghog sa mga sugo sa ilang agalon."},{"verse":51,"text":"Ug ang kaaway miabot sa pagkagabii, ug miguba sa ali; ug ang mga sulugoon sa halangdon nga tawo namangon ug nangahadlok, ug nanglayas; ug ang kaaway miguba sa ilang mga gipanghimo, ug gipangtumba ang mga kahoy nga olibo."},{"verse":52,"text":"Karon, tan-awa, ang halangdon nga tawo, ang agalon sa ubasan, mitawag sa iyang mga sulugoon, ug miingon kanila, Ngano! unsa ang hinungdan niining dako nga kadaot?"},{"verse":53,"text":"Wala ba diay ninyo buhata ang akong gimando kaninyo, ug—human sa inyong pagtanom sa ubasan, ug sa pagtukod sa ali sa palibot niini, ug sa pagbutang og mga magbalantay diha sa mga paril niini—magtukod usab og tore, ug magbutang og magbalantay diha sa tore, ug magbantay sa akong ubasan, ug dili matulog, basin pa unya og ang kaaway moabot diha kaninyo?"},{"verse":54,"text":"Ug tan-awa, nakit-an unta sa magbalantay diha sa tore ang kaaway samtang anaa pa siya sa layo; ug unya nakapangandam unta kamo ug napugngan ang kaaway gikan sa pagguba sa ali niini, ug naluwas ang akong ubasan gikan sa mga kamot sa tiglaglag."},{"verse":55,"text":"Ug ang agalon sa ubasan miingon sa usa sa iyang mga sulugoon: Lakaw ug pundoka ang tanang nahibilin sa akong mga sulugoon, ug dad-a ang tanan nga tawong lig-on sa akong balay, nga mao ang akong mga manggugubat, ang akong mga batan-ong lalaki, sila usab nga mga hamtong taliwala sa tanan nakong mga sulugoon, nga mao ang kalig-on sa akong balay, gawas niadtong akong gipili nga magpabilin;"},{"verse":56,"text":"Ug lakaw kamo sa walay langan ngadto sa yuta sa akong ubasan, ug bawia ang akong ubasan; kay akoa kini; napalit ko kini sa kwarta."},{"verse":57,"text":"Busa, lakaw kamo sa walay langan ngadto sa akong yuta; gub-a ang mga paril sa akong mga kaaway; gub-a ang ilang tore, ug patibulaaga ang ilang mga magbalantay."},{"verse":58,"text":"Ug kon magpundok sila batok kaninyo, ipanimalos ako sa akong mga kaaway, nga sa dili madugay moadto ko uban sa nahibilin sa akong balay ug manag-iya sa yuta."},{"verse":59,"text":"Ug ang sulugoon miingon sa iyang agalon: Kanus-a mahitabo kini nga mga butang?"},{"verse":60,"text":"Ug miingon siya sa iyang sulugoon: Sumala sa akong pagbuot; lakaw sa walay langan, ug buhata ang tanan bisan unsa nga akong gisugo kanimo;"},{"verse":61,"text":"Ug mao kini ang akong selyo ug panalangin nganha kanimo—usa ka matinud-anon ug maalamon nga tinugyanan taliwala sa akong balay, usa ka magmamando sa akong gingharian."},{"verse":62,"text":"Ug ang iyang sulugoon sa walay langan miadto, ug mihimo sa tanang butang bisan unsa ang gisugo sa agalon kaniya; ug human sa pipila ka adlaw ang tanang butang natuman."},{"verse":63,"text":"Usab, sa pagkatinuod, sultihan ko kamo, akong ipakita kaninyo ang kaalam nga ania kanako mahitungod sa tanang simbahan, kon sila andam nga magiyahan sa matarong ug sa tukmang paagi alang sa ilang kaluwasan—"},{"verse":64,"text":"Aron ang buhat sa pagpundok sa akong mga santos magpadayon, nga sila akong mapalig-on diha sa akong ngalan sa balaang mga dapit; kay ang panahon sa pag-ani miabot na, ug ang akong pulong kinahanglan gayod nga matuman."},{"verse":65,"text":"Busa, kinahanglan nga akong pundokon ang akong katawhan, sumala sa sambingay sa trigo ug mga sagbot, nga ang trigo mapanalipdan diha sa balay tipiganan aron makabaton og kinabuhing dayon, ug makoronahan og celestial nga himaya, kon moadto na ko sa gingharian sa akong Amahan aron gantihan ang matag tawo sumala sa iyang buhat;"},{"verse":66,"text":"Samtang ang mga sagbot pagabugkoson, ug ang mga higot niini pagahimoon nga lig-on, aron kini sunogon sa dili mapalong nga kalayo."},{"verse":67,"text":"Busa, usa ka sugo ang akong ihatag sa tanang simbahan, nga silang tanan magpadayon sa pagpundok ngadto sa mga dapit nga akong gipili."},{"verse":68,"text":"Bisan pa niana, sama sa akong gisulti kaninyo sa nahauna nga sugo, ayaw dalidalia ang inyong panagpundok, ni ang inyong pagpanaw; apan andama ang tanang butang sa inyong atubangan."},{"verse":69,"text":"Ug aron maandam ang tanang butang sa inyong atubangan, sunda ang sugo nga akong gihatag mahitungod niini nga mga butang—"},{"verse":70,"text":"Nga nag-ingon, o nagtudlo, sa pagpalit sa tanang yuta, nga mahimong mapalit sa kwarta, sa rehiyon libot sa yuta nga akong gipili nga mahimong yuta sa Zion, alang sa sinugdanan sa pagpundok sa akong mga santos;"},{"verse":71,"text":"Ang tanan nga yuta sa lalawigan sa Jackson nga mahimong paliton, ug ang mga distrito sa palibot, ug ibilin ang nahibilin sa akong kamot."},{"verse":72,"text":"Karon, sa pagkatinuod sultihan ko kamo, tugoti nga ang tanang simbahan mopundok sa ilang tanang kwarta; tugoti nga ang mga butang pagahimoon sa ilang tukmang panahon, apan dili sa dinalidali; ug iseguro nga ang tanang butang maandam sa inyong atubangan."},{"verse":73,"text":"Ug tugoti nga ang talahorong mga tawo mao ang pilion, gani ang mga tawo nga maalamon, ug ipadala sila aron paliton kining mga yuta."},{"verse":74,"text":"Ug ang mga simbahan sa silangang mga nasod, kon matukod na kini, kon mopatalinghog sila niini nga tambag mahimo silang mamalit og mga yuta ug magpundok diha niini; ug sa ingon niini nga paagi sila makatukod sa Zion."},{"verse":75,"text":"Gani karon adunay igo na nga natigom, oo, gani daghan na, aron itubos sa Zion, ug tukoron ang iyang biniyaan nga mga dapit, nga dili na pagagun-obon, kon ang mga simbahan, nga nagtawag sa ilang mga kaugalingon sama sa akong ngalan, andam nga mopatalinghog sa akong tingog."},{"verse":76,"text":"Ug usab sultihan ko kamong mga gipatibulaag sa ilang mga kaaway, mao kini ang akong kabubut-on nga sila mopadayon sa paghangyo alang sa paghusay, ug katubsanan, pinaagi sa mga kamot niadtong gibutang nga mga magmamando ug adunay katungod labaw kaninyo—"},{"verse":77,"text":"Sumala sa mga balaod ug sa konstitusyon sa katawhan, nga akong gitugotan nga matukod, ug kinahanglan nga ampingan alang sa mga katungod ug sa pagpanalipod sa tanang tawo, sumala sa makiangayon ug balaang mga baroganan;"},{"verse":78,"text":"Aron ang matag tawo molihok sumala sa doktrina ug baroganan mahitungod sa umaabot, sumala sa matarong nga kabubut-on nga akong gihatag kaniya, nga ang matag tawo mao ang manubag sa iyang kaugalingong mga sala sa adlaw sa paghukom."},{"verse":79,"text":"Busa, dili matarong nga si bisan kinsa nga tawo mahimong ulipon ngadto sa usag-usa."},{"verse":80,"text":"Ug tungod niini nga katuyoan akong gitukod ang Konstitusyon niini nga yuta, pinaagi sa mga kamot sa mga tawo nga maalamon nga akong giandam niining mao nga katuyoan, ug gitubos ang yuta pinaagi sa pagpaagas og dugo."},{"verse":81,"text":"Karon, asa nako ipahisama ang mga anak sa Zion? Ipahisama nako sila ngadto sa sambingay sa babaye ug sa usa ka maghuhukom nga dili makiangayon, kay ang mga tawo kinahanglan nga mag-ampo sa kanunay ug dili mawad-an og paglaom, nga nag-ingon—"},{"verse":82,"text":"Adunay usa ka maghuhukom sa usa ka siyudad nga walay kahadlok sa Dios, ni may tawo nga gitahod."},{"verse":83,"text":"Ug adunay usa ka biyuda niana nga siyudad, ug miduol siya kaniya, nga nag-ingon: Ipanimalos ako sa akong kaaway."},{"verse":84,"text":"Ug wala dayon siya mosugot, apan sa wala madugay miingon siya sa iyang kaugalingon: Bisan og ako wala mahadlok sa Dios, ni motahod sa tawo, apan tungod kay kini nga biyuda nagsamok kanako mobalos ko niya, basin pa unya og sa iyang kanunay nga pagduol iya akong mahasol."},{"verse":85,"text":"Sa ingon niana ako mopahisama sa mga anak sa Zion."},{"verse":86,"text":"Tugoti nga magpakiluoy sila sa tighukom;"},{"verse":87,"text":"Ug kon dili siya maminaw kanila, tugoti nga magpakiluoy sila sa tiilan sa gobernador;"},{"verse":88,"text":"Ug kon ang gobernador dili maminaw kanila, tugoti sila nga magpakiluoy sa tiilan sa presidente;"},{"verse":89,"text":"Ug kon ang presidente dili maminaw kanila, nan ang Ginoo mopakita ug mogula gikan sa iyang dapit nga tagoanan, ug sa iyang kapungot mohasol sa nasod;"},{"verse":90,"text":"Ug sa iyang labihan nga kalagot, ug sa iyang pintas nga kapungot, sa iyang tukmang panahon; pagalaglagon kadtong dili matinud-anon, ug dili makiangayong mga tinugyanan, ug ihatag ang ilang bahin kauban sa mga tigpakaaron-ingnon, ug mga dili matuohon;"},{"verse":91,"text":"Gani ngadto sa kawanangan sa kangitngit, diin adunay pagbakho, ug pagdanguyngoy, ug pagpangagot sa ngipon."},{"verse":92,"text":"Busa, pag-ampo kamo nga ang ilang mga dunggan makadungog sa inyong mga pangamuyo, aron ako maluoy kanila, aron kini nga mga butang dili moabot kanila."},{"verse":93,"text":"Ang akong gisulti kaninyo kinahanglang mahitabo, nga ang tanang tawo magpabiling walay ikapangatarongan;"},{"verse":94,"text":"Aron ang maalamong mga tawo ug ang mga magmamando makadungog ug masayod nianang wala pa gayod nila mahunahuna;"},{"verse":95,"text":"Aron akong mapadayon ang pagpahitabo sa akong buluhaton, akong kahibulongan nga buluhaton, ug sa paghimo sa akong buhat, akong kahibulongan nga buhat, aron ang mga tawo makaila tali sa matarong ug sa daotan, miingon ang inyong Dios."},{"verse":96,"text":"Ug usab, sultihan ko kamo, supak sa akong sugo ug sa akong kabubut-on nga ibaligya sa akong sulugoon nga si Sidney Gilbert ang akong balay tipiganan, nga akong gipili alang sa akong katawhan, ngadto sa mga kamot sa akong mga kaaway."},{"verse":97,"text":"Ayaw tugoti nga kanang akong gipili mahugawan sa akong mga kaaway, pinaagi sa pagtugot niadtong kinsa nagtawag sa ilang mga kaugalingon sama sa akong ngalan;"},{"verse":98,"text":"Kay kini usa ka labihan ug bug-at kaayo nga sala batok kanako, ug batok sa akong katawhan, agi og sangpotanan niadtong mga butang nga akong gitakda ug nga sa dili madugay moabot sa mga nasod."},{"verse":99,"text":"Busa, mao kini ang akong kabubut-on nga ang akong katawhan, kinahanglang moangkon, ug padayong moangkon nianang akong gipili alang kanila, bisan og dili sila tugotan nga mopuyo niini."},{"verse":100,"text":"Hinuon, wala ko moingon nga sila dili makapuyo niini; kay kon magdala sila og bunga ug mga buhat nga angay alang sa akong gingharian makapuyo sila niini."},{"verse":101,"text":"Makatukod sila, ug ang uban dili makapanunod niini; makapananom sila og mga ubasan, ug sila makakaon sa bunga niini. Ug mao gayod kana. Amen."}]},{"chapter":102,"verses":[{"verse":1,"text":"Niining adlawa ang kinatibuk-ang konseho sa kawhaan ug upat ka high priest nagpundok sa balay ni Joseph Smith, Jun., pinaagi sa pagpadayag, ug nagpadayon sa pagtukod sa halangdong konseho sa simbahan ni Kristo, nga naglangkob sa napulog duha ka high priest, ug usa o tulo ka presidente sumala sa panginahanglan sa kahigayonan."},{"verse":2,"text":"Ang halangdong konseho gipili pinaagi sa pagpadayag alang sa katuyoan sa paghusay sa mahinungdanong mga problema nga posibling motumaw sa simbahan, nga dili mahusay sa simbahan o sa konseho sa bishop ngadto sa katagbawan sa mga hingtungdan."},{"verse":3,"text":"Sila si Joseph Smith, Jun., Sidney Rigdon ug Frederick G. Williams giila nga mga presidente pinaagi sa tingog sa konseho; ug sila si Joseph Smith, Sen., John Smith, Joseph Coe, John Johnson, Martin Harris, John S. Carter, Jared Carter, Oliver Cowdery, Samuel H. Smith, Orson Hyde, Sylvester Smith, ug Luke Johnson, mga high priest, gipili nga mobarog isip konseho alang sa simbahan, pinaagi sa nagkahiusa nga tingog sa konseho."},{"verse":4,"text":"Ang ginganlan sa ibabaw nga mga sakop sa konseho gipangutana kon gidawat ba nila ang ilang pagkapili, ug kon motuman ba sila sa mao nga katungdanan sumala sa balaod sa langit, diin silang tanan mitubag nga gidawat nila ang ilang pagkapili, ug motuman sa ilang mga katungdanan sumala sa grasya sa Dios nga gihatag nganha kanila."},{"verse":5,"text":"Ang gidaghanon nga naglangkob sa konseho, nga miboto sa ngalan ug alang sa simbahan sa pagpili sa ginganlan sa ibabaw nga mga sakop sa konseho mga kap-atan ug tulo, sama sa mosunod: siyam ka high priest, napulo ug pito ka elder, upat ka priest, ug napulog tulo ka miyembro."},{"verse":6,"text":"Nauyonan: nga ang halangdong konseho walay gahom sa paghimo kon wala ang pito nga ginganlan sa ibabaw nga mga sakop sa konseho, o dili motambong ang kasagarang gipili nga mga sumusunod."},{"verse":7,"text":"Kining pito adunay gahom sa pagpili og laing mga high priest, nga ilang giisip nga takos ug makahimo sa paglihok puli sa mga sakop sa konseho nga wala makatambong."},{"verse":8,"text":"Nabotohan: nga sa matag higayon nga adunay bakante nga mahitabo tungod sa kamatayon, pagpapahawa gikan sa katungdanan tungod sa kalapasan, o pagbalhin gikan sa mga utlanan sa pamunoan niini nga simbahan, ni bisan kinsa sa mga sakop sa konseho nga ginganlan sa ibabaw, pulihan kini pinaagi sa sugyot sa presidente, o mga presidente, ug tugotan pinaagi sa tingog sa kinatibuk-an nga konseho sa mga high priest, nga nagkatigom alang niana nga katuyoan, sa paglihok pinaagi sa ngalan sa simbahan."},{"verse":9,"text":"Ang presidente sa simbahan, nga mao usab ang presidente sa konseho, gipili pinaagi sa pagpadayag, ug giila sa iyang pagdumala pinaagi sa tingog sa simbahan."},{"verse":10,"text":"Ug kini sumala sa kahalangdon sa iyang katungdanan nga siya kinahanglang modumala sa konseho sa simbahan; ug kini mao ang iyang kahigayonan nga pagaabagan sa laing duha ka presidente, nga gipili sa samang paagi sa pagpili kaniya."},{"verse":11,"text":"Ug kon dili motambong ang usa o duha nga gipili sa pagtabang kaniya, siya adunay gahom nga mangulo sa konseho nga walay tig-abag; ug kon siya mismo ang dili makatambong, ang laing mga presidente adunay gahom sa pagpangulo puli kaniya, ang duha o bisan hain kanila."},{"verse":12,"text":"Sa matag higayon nga ang halangdong konseho sa simbahan ni Kristo hapsay na ang pagkaorganisar, sumala sa nahauna nga sumbanan, katungdanan sa napulog duha ka sakop sa konseho ang pagripa og mga numero, ug pinaagi niini matino kon kinsa sa napulog duha ang unang mosulti, sugod sa unang numero ug magsunod-sunod hangtod sa ikanapulog duha."},{"verse":13,"text":"Sa higayon nga kining konseho magtigom aron sa paghusay og bisan unsa nga kaso, ang napulog duha ka sakop sa konseho maghunahuna kon lisod ba kini o dili; ug kon dili, duha lamang sa mga sakop sa konseho ang mosulti diha niini, sumala sa sumbanan nga nahisulat sa ibabaw."},{"verse":14,"text":"Apan kon gihunahuna kini nga lisod, upat ang pilion; ug kon mas lisod pa, unom; apan dili mahitabo nga molabaw sa unom ang pilion aron mosulti."},{"verse":15,"text":"Ang sinumbong, sa tanang kaso, adunay katungod sa katunga sa konseho, aron kapugngan ang pang-insulto o ang kadili makiangayon."},{"verse":16,"text":"Ug ang mga sakop sa konseho nga gipili nga mosulti sa atubangan sa konseho mao ang mopahayag sa kaso, human masusi ang ebidensya, sa tinuod nga panghitabo sa atubangan sa konseho; ug ang matag tawo mosulti pinasubay sa patas nga paagi ug kaangayan."},{"verse":17,"text":"Kadtong mga sakop sa konseho nga nakahulbot sa mga pares nga numero, nga mao ang, 2, 4, 6, 8, 10 ug 12, mao ang mobarog alang sa sinumbong, ug mopugong sa pang-insulto ug kadili makiangayon."},{"verse":18,"text":"Sa tanang kaso ang nagsumbong ug ang sinumbong adunay kahigayonan sa pagsulti alang sa ilang kaugalingon sa atubangan sa konseho, human madungog ang mga ebidensya ug ang mga sakop sa konseho nga gipili nga maoy mosulti bahin sa kaso nakahuman na sa ilang pagpamahayag."},{"verse":19,"text":"Human mapaminaw ang mga ebidensya, ug ang mga sakop sa konseho, ang nagsumbong ug ang sinumbong nakasulti na, ang presidente mohatag sa hukom sumala sa pagsabot nga iyang nakuha sa kaso, ug motawag sa napulog duha ka sakop sa konseho aron uyonan ang hukom pinaagi sa ilang pagboto."},{"verse":20,"text":"Apan kon ang nahibilin nga mga sakop sa konseho, nga wala pa makasulti, o bisan hain kanila, human madungog ang mga ebidensya ug mga paghangyo nga walay pagdapig, nakakita og sayop sa hukom sa presidente, mahimo nila kining isulti, ug ang kaso sublion sa paghusay."},{"verse":21,"text":"Ug kon, human sa mainampingong pagsubli nga paghusay, adunay nadugang nga katin-awan nga nakita sa kaso, ang hukom mahimo nga usbon pinasubay niana."},{"verse":22,"text":"Apan kon walay nahatag nga dugang nga katin-awan, ang una nga hukom ang mopatigbabaw, ang kinadaghanan sa konseho mao gihapon ang adunay gahom sa paghukom."},{"verse":23,"text":"Kon may problema sa paghukom bahin sa doktrina o baroganan, kon dili igo ang sinulat aron makahatag og katin-awan sa kaso ngadto sa mga hunahuna sa konseho, ang presidente magpakisayod ug mangayo sa hunahuna sa Ginoo pinaagi sa pagpadayag."},{"verse":24,"text":"Ang mga high priest, kon anaa sila sa layong dapit, adunay gahom sa pagtawag ug paghimo og konseho sama sa gihisgotan sa ibabaw, sa paghusay sa mga problema, kon ang mga hingtungdan o bisan hain kanila mohangyo niini."},{"verse":25,"text":"Ug ang gihisgotan nga konseho sa mga high priest adunay gahom sa pagpili og usa sa kaugalingon nila nga pundok nga modumala sa mao nga konseho sa makadiyot."},{"verse":26,"text":"Katungdanan sa gihisgotan nga konseho ang pagpadala, diha dayon, og kopya sa ilang mga gipanghimo, uban sa kinatibuk-ang pamahayag sa pagpamatuod inubanan sa ilang hukom, ngadto sa halangdong konseho sa buhatan sa Unang Kapangulohan sa Simbahan."},{"verse":27,"text":"Kon ang mga hingtungdan o bisan hain kanila wala kaayo mahimuot sa hukom sa gihisgotan nga konseho, mahimo silang mohangyo sa halangdong konseho sa buhatan sa Unang Kapangulohan sa Simbahan, ug himoon ang pagsubli nga paghusay, kansang kaso pagadumalahon, sumala sa nahauna nga sumbanan nga nahisulat, sama og wala pay hukom nga nahitabo."},{"verse":28,"text":"Kini nga konseho sa mga high priest nga anaa sa layong dapit ipatawag lamang atol sa labing lisod nga mga kaso nga may kalabotan sa simbahan; ug ang komon o ordinaryo nga kaso dili angay nga ipatawag sa ingon niana nga konseho."},{"verse":29,"text":"Ang tigbiyahe o anaa sa layong dapit nga mga high priest adunay gahom sa pagsulti kon gikinahanglan ba nga magtawag og ingon niini nga konseho o dili."},{"verse":30,"text":"Adunay kalainan tali sa halangdong konseho o tigbiyahe nga mga high priest sa laing nasod, ug sa tigbiyahe nga halangdong konseho nga gilangkoban sa napulog duha ka apostoles, sa ilang mga hukom."},{"verse":31,"text":"Gikan sa hukom sa nag-una mahimo nga adunay usa ka pag-apela; apan sa hukom sa naulahi wala na."},{"verse":32,"text":"Ang naulahi mahimo lamang nga mapangutana sa kinatibuk-ang mga awtoridad sa simbahan kon adunay nalambigit nga kalapasan."},{"verse":33,"text":"Gikasabotan: nga ang presidente o mga presidente sa buhatan sa Unang Kapangulohan sa Simbahan adunay gahom sa pagtino kon ang ingon niana nga kaso, nga iapela, angay ba nga sublion sa paghusay, human masuta ang hangyo ug ang mga ebidensya ug mga pamahayag nga gilakip niini."},{"verse":34,"text":"Ang napulog duha ka sakop sa konseho human niana nagpadayon sa paghimo og mga ripa o mga balota, aron sa pagtino kon kinsa ang unang mosulti, ug ang mosunod mao ang resulta, nga ginganlan: 1, Oliver Cowdery; 2, Joseph Coe; 3, Samuel H. Smith; 4, Luke Johnson; 5, John S. Carter; 6, Sylvester Smith; 7, John Johnson; 8, Orson Hyde; 9, Jared Carter; 10, Joseph Smith, Sen.; 11, John Smith; 12, Martin Harris.Human sa pag-ampo ang komperensiya natapos."},{"verse":35,"text":"Oliver Cowdery,"},{"verse":36,"text":"Orson Hyde,"},{"verse":37,"text":"Mga Klerk"}]},{"chapter":103,"verses":[{"verse":1,"text":"Sa pagkatinuod sultihan ko kamo, akong mga higala, tan-awa, hatagan ko kamo og usa ka pagpadayag ug sugo, aron masayran ninyo kon unsaon sa paglihok ang pagtuman sa inyong mga katungdanan mahitungod sa kaluwasan ug katubsanan sa inyong kaigsoonan, nga nagkatibulaag sa yuta sa Zion;"},{"verse":2,"text":"Gipalayas ug gihampak sa mga kamot sa akong mga kaaway, kang kinsa ako mobu-bo sa akong kapungot nga walay sukod sa akong kaugalingong tukma nga panahon."},{"verse":3,"text":"Kay akong gitugotan sila hangtod karon, aron ilang pun-on ang sukdanan sa ilang mga kadaotan, nga ang ilang kopa mapuno;"},{"verse":4,"text":"Ug kadtong nagtawag sa ilang mga kaugalingon sunod sa akong ngalan mapanton sa mubo nga panahon uban ang grabe ug bug-at nga pagpanton, tungod kay wala sila mopatalinghog sa mga lagda ug mga sugo nga akong gihatag kanila."},{"verse":5,"text":"Apan sa pagkatinuod sultihan ko kamo, nga ako mitakda og balaod aron ang akong katawhan makaamgo, kon mopatalinghog sila gikan gayod niini nga takna sa tambag diin ako, ang Ginoo nga ilang Dios, mohatag kanila."},{"verse":6,"text":"Tan-awa, kay ako ang misugo niini, mosugod sila sa pagpildi sa akong mga kaaway gikan gayod niini nga takna."},{"verse":7,"text":"Ug pinaagi sa pagpatalinghog sa pagsunod sa tanang pulong diin ako, ang Ginoo nga ilang Dios, mamulong ngadto kanila, dili mahunong ang ilang pagkamadaogon hangtod nga ang mga gingharian sa kalibotan mayatakyatakan sa akong mga tiil, ug ang yuta ihatag ngadto sa mga santos, aron mapanag-iya kini hangtod sa kahangtoran."},{"verse":8,"text":"Apan kon dili sila motuman sa akong mga sugo, ug dili mopatalinghog sa pagsunod sa akong tanan nga pulong, ang mga gingharian sa kalibotan mopildi kanila."},{"verse":9,"text":"Kay gitakda sila nga mahimong kahayag sa kalibotan, ug mahimong mga manluluwas sa mga tawo;"},{"verse":10,"text":"Ug kay kon dili man sila mga manluluwas sa mga tawo, susama sila sa asin nga nawad-an sa iyang lami, ug sukad niana wala nay kapuslanan apan angay lamang ilabay ug tunob-tunoban sa mga tawo."},{"verse":11,"text":"Apan sa pagkatinuod sultihan ko kamo, ako ang nagsugo nga ang inyong kaigsoonan nga nagkatibulaag mobalik ngadto sa mga yuta nga ilang mga kabilin, ug motukod sa mga biniyaang mga dapit sa Zion."},{"verse":12,"text":"Kay human sa hilabihang kalisdanan, sama sa akong gisulti kaninyo sa nahauna nga sugo, moabot ang panalangin."},{"verse":13,"text":"Tan-awa, mao kini ang panalangin nga akong gisaad human sa inyong mga kalisdanan, ug sa mga kalisdanan sa inyong kaigsoonan—ang inyong katubsanan, ug ang katubsanan sa inyong kaigsoonan, gani pagpahiuli kanila ngadto sa yuta sa Zion, nga pagatukoron, ug dili na mapukan."},{"verse":14,"text":"Apan, kon hugaw-hugawan nila ang ilang mga kabilin malaglag sila; kay ako dili moluwas kanila kon ilang hugaw-hugawan ang ilang mga panulundon."},{"verse":15,"text":"Tan-awa, sultihan ko kamo, ang katubsanan sa Zion kinahanglang mahitabo pinaagi sa gahom;"},{"verse":16,"text":"Busa, mag-andam ako og usa ka tawo diha sa akong katawhan, nga mangulo kanila sama ni Moises nga nangulo sa Israel."},{"verse":17,"text":"Kay mga anak kamo ni Israel, ug mga binhi ni Abraham, ug kinahanglan nga haw-ason kamo gikan sa pagkaulipon pinaagi sa gahom, ug sa gituyhad nga mga bukton."},{"verse":18,"text":"Ug sama nga ang inyong mga amahan gihaw-as pag-una, mao usab ang katubsanan sa Zion."},{"verse":19,"text":"Busa, ayaw tugoti nga ang inyong mga kasingkasing mawad-an og paglaom, kay dili ako mosulti kaninyo sa akong gisulti ngadto sa inyong mga amahan: Ang akong anghel mogiya kaninyo, apan dili ang akong presensya."},{"verse":20,"text":"Apan sultihan ko kamo: Ang akong mga anghel mogiya kaniyo, ug usab anaa ang akong presensya, ug sa tukmang panahon inyong mapanag-iya ang maayo nga yuta."},{"verse":21,"text":"Sa pagkatinuod, sa pagkatinuod sultihan ko kamo, nga ang akong sulugoon nga si Joseph Smith, Jun., mao ang tawo nga akong gitandi sa sulugoon nga gihisgotan sa Ginoo sa ubasan diha sa sambingay nga akong gihatag kaninyo."},{"verse":22,"text":"Busa tugoti nga ang akong sulugoon nga si Joseph Smith, Jun., mosulti ngadto sa mga tawo nga naghatag og kalig-on sa akong panimalay, nga akong mga batan-ong lalaki ug mga hamtong—Pagpundok kamo diha sa yuta sa Zion, sa yuta nga akong gipalit og kwarta nga gipahinungod ngari kanako."},{"verse":23,"text":"Ug tugoti nga ang tanang simbahan mopadala og mga tawo nga maalamon dala ang ilang mga kwarta, ug mamalit og mga yuta gani sumala sa akong gisugo kanila."},{"verse":24,"text":"Ug kon ang akong mga kaaway mosulong kaninyo aron papahawaon kamo sa akong maayo nga yuta, nga akong gipahinungod nga mahimong yuta sa Zion, gani gikan sa inyong kaugalingong mga yuta human niining mga pagpamatuod, nga inyong gidala sa akong atubangan batok kanila, tungloha ninyo sila;"},{"verse":25,"text":"Ug si bisan kinsa nga inyong tunglohon, akong tunglohon, ug ipanimalos ninyo ako sa akong mga kaaway."},{"verse":26,"text":"Ug ang akong presensya magauban kaninyo gani sa inyong pagpanimalos kanako sa akong mga kaaway, ngadto sa ikatulo ug ikaupat nga henerasyon kanila nga nasilag kanako."},{"verse":27,"text":"Walay tawo nga angay mahadlok nga motugyan sa iyang kinabuhi alang kanako; kay kinsa kadtong motugyan sa iyang kinabuhi alang kanako makakaplag niini pag-usab."},{"verse":28,"text":"Ug kinsa kadtong dili andam nga motugyan sa iyang kinabuhi alang kanako dili akong disipulo."},{"verse":29,"text":"Kabubut-on ko kini nga ang akong sulugoon nga si Sidney Rigdon mopataas sa iyang tingog diha sa mga kongregasyon sa silangang mga nasod, sa pag-andam sa mga simbahan aron mosunod sa mga sugo nga akong gihatag kanila mahitungod sa pagpahiuli ug sa katubsanan sa Zion."},{"verse":30,"text":"Kabubut-on ko kini nga ang akong sulugoon nga si Parley P. Pratt ug ang akong sulugoon nga si Lyman Wight dili na mobalik ngadto sa yuta sa ilang kaigsoonan, hangtod nga makakuha sila og mga kauban nga moadto sa yuta sa Zion, sa tignapulo, o tigkawhaan, o tigkalim-an, o tiggatosan, hangtod nga makuha nila ang gidaghanon nga lima ka gatos ka lig-ong mga tawo sa akong balay."},{"verse":31,"text":"Tan-awa kabubut-on ko kini; pangayo ug kamo makadawat; apan ang mga tawo dili sa kanunay mobuhat sa akong kabubut-on."},{"verse":32,"text":"Busa, kon dili kamo makakuha og lima ka gatos, kugihi sa pagpangita basin pa og makakuha kamo og tulo ka gatos."},{"verse":33,"text":"Ug kon dili kamo makakuha og tulo ka gatos, kugihi sa pagpangita basin pa og makakuha kamo og usa ka gatos."},{"verse":34,"text":"Apan sa pagkatinuod sultihan ko kamo, hatagan ko kamo og usa ka sugo, nga ayaw kamo pag-adto sa yuta sa Zion hangtod nga makakuha kamo og usa ka gatos ka lig-ong mga tawo sa akong panimalay, nga mouban kaninyo ngadto sa yuta sa Zion."},{"verse":35,"text":"Busa, sama sa akong gisulti kaninyo, pangayo ug kamo makadawat; pag-ampo nga matinguhaon basin pa og ang akong sulugoon nga si Joseph Smith, Jun., mokuyog kaninyo, ug modumala taliwala sa akong katawhan, ug motukod sa akong gingharian diha sa gipahinungod nga yuta, ug moestablisar sa mga anak sa Zion sa mga balaod ug mga sugo nga gihatag ug ihatag nganha kaninyo."},{"verse":36,"text":"Ang tanang kadaogan ug himaya ipatuman nganha kaninyo pinaagi sa inyong kakugi, pagkamatinud-anon, ug mga pag-ampo inubanan sa pagtuo."},{"verse":37,"text":"Pabiyahia ang akong sulugoon nga si Parley P. Pratt kuyog sa akong sulugoon nga si Joseph Smith, Jun."},{"verse":38,"text":"Pabiyahia ang akong sulugoon nga si Lyman Wight kuyog sa akong sulugoon nga si Sidney Rigdon."},{"verse":39,"text":"Pabiyahia ang akong sulugoon nga si Hyrum Smith kuyog sa akong sulugoon nga si Frederick G. Williams."},{"verse":40,"text":"Pabiyahia ang akong sulugoon nga si Orson Hyde kuyog sa akong sulugoon nga si Orson Pratt, bisan unsay itambag sa akong sulugoon nga si Joseph Smith, Jun., kanila, aron matuman kini nga mga sugo nga akong gihatag kaninyo, ug isalig ang tanan pang mga butang sa akong mga kamot. Ug mao gayod kana. Amen."}]},{"chapter":104,"verses":[{"verse":1,"text":"Sa pagkatinuod sultihan ko kamo, akong mga higala, hatagan ko kamo og usa ka tambag, ug usa ka sugo, mahitungod sa tanang kabtangan nga gipanag-iya sa kapunongan nga akong gisugo nga han-ayon ug tukoron, nga mahimong nagkahiusa nga kapunongan, ug walay kataposang kapunongan alang sa kaayohan sa akong simbahan, ug alang sa kaluwasan sa mga tawo hangtod sa akong pag-anha—"},{"verse":2,"text":"Inubanan sa saad nga dili mabalhin ug dili mausab, nga kon kadtong akong mga gisugo magmatinud-anon mapanalanginan sila sa pinilo-pilo nga mga panalangin;"},{"verse":3,"text":"Apan kon dili sila magmatinud-anon haduol sila sa pagtunglo."},{"verse":4,"text":"Busa, kay ang pipila sa akong mga sulugoon wala motuman sa sugo, kondli milapas sa pakigsaad pinaagi sa pagkamasinahon, ug sa mga pulong sa pagpakaaron-ingnon, gitunglo ko sila og usa ka hilabihan ka sakit ug makalilisang nga tunglo."},{"verse":5,"text":"Kay ako, ang Ginoo, nakatakda sa akong kasingkasing, nga kon dunay tawo nga nahisakop sa kapunongan nga masakpang nakalapas, o, sa laing mga pulong, makalapas sa pakigsaad nga naghiusa kaninyo, tunglohon siya panahon sa iyang kinabuhi, ug tunob-tunoban ni bisan kinsa sumala sa akong pagbuot;"},{"verse":6,"text":"Kay, ako ang Ginoo, dili mahimong bugalbugalan niining mga butanga—"},{"verse":7,"text":"Ug tanan kini aron ang walay sala taliwala kaninyo dili masilotan kauban sa mga dili makiangayon; ug aron ang adunay sala taliwala kaninyo dili makalingkawas; tungod kay ako, ang Ginoo, misaad kaninyo og usa ka korona sa himaya dapit sa tuo nakong kamot."},{"verse":8,"text":"Busa, kon masakpan kamong nakalapas, dili kamo makalingkawas sa akong kapungot sa inyong kinabuhi."},{"verse":9,"text":"Kon gisalikway kamo tungod sa kalapasan, dili kamo makalingkawas sa mga pagsakit ni Satanas hangtod sa adlaw sa katubsanan."},{"verse":10,"text":"Ug hatagan ko kamo og gahom sugod gayod karon, nga kon adunay tawo taliwala kaninyo, sa kapunongan, nga masakpang nakalapas ug dili maghinulsol sa kadaotan, itugyan ninyo siya ngadto sa mga pagsakit ni Satanas; ug siya walay gahom sa pagdala og kadaotan nganha kaninyo."},{"verse":11,"text":"Kini akong kaalam; busa, hatagan ko kamo og usa ka sugo, nga kamo moorganisar sa inyong mga kaugalingon ug mosangon sa matag tawo sa iyang pagkatinugyanan;"},{"verse":12,"text":"Aron ang matag tawo mohatag og asoy ngari kanako sa pagkatinugyanan diin siya ang gisangonan nga modumala."},{"verse":13,"text":"Kay gikinahanglan nga ako, ang Ginoo, mohimo sa matag tawo nga manubag, isip tinugyanan sa yutan-ong mga panalangin, nga akong gihimo ug giandam alang sa akong mga linalang."},{"verse":14,"text":"Ako, ang Ginoo, mipakaylap sa mga kalangitan, ug mibuhat sa yuta, nga kaugalingon nakong binuhat; ug ang tanang butang nga anaa niini akoa."},{"verse":15,"text":"Ug mao kini ang akong katuyoan sa pagsangkap sa akong mga santos, kay ang tanang butang akoa."},{"verse":16,"text":"Apan kinahanglan kining himoon sa akong kaugalingong pamaagi; ug tan-awa kini ang pamaagi nga ako, ang Ginoo, mitakda sa pagsangkap sa akong mga santos, aron ang mga kabos ipataas, nga niana ang mga adunahan ipaubos."},{"verse":17,"text":"Kay ang yuta puno, ug adunay igo ug sobra pa; oo, akong giandam ang tanan nga butang, ug mihatag sa katawhan og gahom nga mahimong mga tinugyanan sa ilang kaugalingon."},{"verse":18,"text":"Busa, kon adunay tawo diin ang kabuhong nga akong gibuhat gamiton sa iyang kaugalingon, ug dili mohatag sa iyang bahin, sumala sa balaod sa akong ebanghelyo, ngadto sa mga kabos ug mga timawa, siya, kuyog sa mga daotan, moyahat sa iyang mga mata ngadto sa impiyerno, nga mag-antos sa kasakit."},{"verse":19,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, mahitungod sa mga kabtangan sa kapunongan—"},{"verse":20,"text":"Isangon sa akong sulugoon nga si Sidney Rigdon ang pagdumala sa dapit nga iyang gipuy-an karon, ug ang yuta sa tinaan alang sa iyang pagkatinugyanan, alang sa iyang kabuhian samtang nagtrabaho siya sa akong ubasan, gani sumala sa akong pagbuot, sa higayon nga ako mosugo kaniya."},{"verse":21,"text":"Ipabuhat ang tanang butang sumala sa tambag sa kapunongan, ug sa nagkahiusang pag-uyon o tingog sa kapunongan, nga anaa sa yuta sa Kirtland."},{"verse":22,"text":"Ug kini nga pagkatinugyanan ug panalangin, ako, ang Ginoo, motugyan sa akong sulugoon nga si Sidney Rigdon alang sa iyang panalangin, ug sa iyang binhi nga nagsunod kaniya;"},{"verse":23,"text":"Ug akong pilo-piloon ang mga panalangin diha kaniya, kon magpaubos siya sa akong atubangan."},{"verse":24,"text":"Ug usab, tugoti nga ang akong sulugoon nga si Martin Harris masangonan nga modumala, sa lote nga naangkon sa akong sulugoon nga si John Johnson agi og ilis sa iyang una nga kabilin, alang kaniya ug sa iyang binhi nga nagsunod kaniya;"},{"verse":25,"text":"Ug kon magmatinud-anon siya, akong pilo-piloon ang mga panalangin diha kaniya ug sa iyang mga binhi nga nagsunod kaniya."},{"verse":26,"text":"Ug ipahalad sa akong sulugoon nga si Martin Harris ang iyang mga kwarta sa pagsangyaw sa akong mga pulong, sumala sa imando sa akong sulugoon nga si Joseph Smith, Jun."},{"verse":27,"text":"Ug usab, tugoti nga maangkon sa akong sulugoon nga si Frederick G. Williams ang dapit nga iyang gipuy-an karon."},{"verse":28,"text":"Ug tugoti nga maangkon sa akong sulugoon nga si Oliver Cowdery ang lote nga kasikbit sa sunod nga balay, nga maoy himoong imprintahanan, nga mao ang una nga lote, ug usab ang lote nga gipuy-an sa iyang amahan."},{"verse":29,"text":"Ug tugoti nga maangkon sa akong mga sulugoon nga si Frederick G. Williams ug Oliver Cowdery ang imprintahanan ug ang tanang butang nga may kalabotan niini."},{"verse":30,"text":"Ug mao kini ang ilang pagkatinugyanan nga isangon ngadto kanila nga idumala."},{"verse":31,"text":"Ug kon magmatinud-anon sila, tan-awa ako mopanalangin, ug mopilo-pilo sa mga panalangin diha kanila."},{"verse":32,"text":"Ug mao kini ang sinugdanan sa pagkatinugyanan nga akong gipili alang kanila, ug sa ilang mga binhi nga nagsunod kanila."},{"verse":33,"text":"Ug, kon magmatinud-anon sila, akong pilo-piloon ang mga panalangin diha kanila ug sa ilang mga binhi nga nagsunod kanila, gani pilo-piloon og kadaghan nga mga panalangin."},{"verse":34,"text":"Ug usab, tugoti nga ang akong sulugoon nga si John Johnson makaangkon sa balay nga iyang gipuy-an, ug sa kabilin, ang tanan gawas sa yuta nga gitagana alang sa pagtukod sa akong mga balay, nga may kalabotan niana nga kabilin, ug niadtong mga lote nga ginganlan alang sa akong sulugoon nga si Oliver Cowdery."},{"verse":35,"text":"Ug kon magmatinud-anon siya, akong pilo-piloon ang mga panalangin diha kaniya."},{"verse":36,"text":"Ug mao kini ang akong kabubut-on nga siya kinahanglang mobaligya sa mga lote nga gilatid alang sa pagtukod sa siyudad sa akong mga santos, kon kini ipahibalo ngadto kaniya pinaagi sa tingog sa Espiritu, ug sumala sa tambag sa kapunongan, ug pinaagi sa tingog sa kapunongan."},{"verse":37,"text":"Ug sinugdanan kini sa pagkatinugyanan nga akong gipili kaniya nga ipadumala, alang sa panalangin ngadto kaniya ug sa iyang binhi nga nagsunod kaniya."},{"verse":38,"text":"Ug kon magmatinud-anon siya akong pilo-piloon og kadaghan ang mga panalangin nganha kaniya."},{"verse":39,"text":"Ug usab, tugoti nga ang akong sulugoon nga si Newel K. Whitney ang gipili nga modumala sa mga balay ug lote nga iyang gipuy-an karon, ug sa lote ug balay nga nahimutangan sa balay patigayon, ug usab sa lote sa habagatang bahin sa balay patigayon, ug usab sa lote nga nahimutangan sa buhatan sa abuno."},{"verse":40,"text":"Ug kining tanan si Newel K. Whitney ang akong gipili nga modumala alang sa iyang pagkatinugyanan, alang sa panalangin diha kaniya ug sa iyang binhi nga nagsunod kaniya, alang sa kaayohan sa balay patigayon sa akong kapunongan nga akong gitukod alang sa akong stake sa yuta sa Kirtland."},{"verse":41,"text":"Oo, sa pagkatinuod, mao kini ang pagkatinugyanan nga akong gipili nga ipadumala sa akong sulugoon nga si N. K. Whitney, gani kining tibuok balay patigayon, kaniya ug sa iyang tinugyanan, ug sa iyang mga binhi nga nagsunod kaniya."},{"verse":42,"text":"Ug kon magmatinud-anon siya sa pagtuman sa akong mga sugo, nga akong gihatag kaniya, akong pilo-piloon ang mga panalangin nganha kaniya ug sa iyang binhi nga nagsunod kaniya, gani sa pinilo-pilo nga mga panalangin."},{"verse":43,"text":"Ug usab, tugoti nga ang akong sulugoon nga si Joseph Smith, Jun., mopili nga siya ang modumala sa lote nga gilatid alang sa pagtukod sa akong balay, nga adunay duha ka gatos ka metros ang gitas-on ug kan-uman ka metros ang gilapdon, ug usab sa kabilin nga gipuy-an karon sa iyang amahan;"},{"verse":44,"text":"Ug mao kini ang sinugdanan sa pagkatinugyanan nga akong gipili nga siya ang modumala, ug sa iyang amahan."},{"verse":45,"text":"Kay tan-awa, nagtagana ako og kabilin alang sa iyang amahan, alang sa iyang kabuhian; busa ilhon siya nga sakop sa balay sa akong sulugoon nga si Joseph Smith, Jun."},{"verse":46,"text":"Ug akong pilo-piloon ang mga panalangin nganha sa balay sa akong sulugoon nga si Joseph Smith, Jun., kon siya magmatinud-anon, gani sa pinilo-pilo nga mga panalangin."},{"verse":47,"text":"Ug karon, hatagan ko kamo og usa ka sugo mahitungod sa Zion, nga kamo wala nay obligasyon isip sakop sa nagkahiusa nga kapunongan ngadto sa inyong kaigsoonan sa Zion gawas lamang niini nga paagi—"},{"verse":48,"text":"Human kamo matukod, kamo pagatawgon og Nagkahiusa nga Kapunongan sa Stake sa Zion, ang Siyudad sa Kirtland. Ug ang inyong kaigsoonan, human sila maorganisar, pagatawgon og Nagkahiusa nga Kapunongan sa Siyudad sa Zion."},{"verse":49,"text":"Ug han-ayon sila gamit ang ilang kaugalingong mga ngalan, ug pinaagi sa ilang kaugalingong ngalan; ug mobuhat sila sa ilang buluhaton gamit ang ilang kaugalingong ngalan, ug pinaagi sa ilang kaugalingong mga ngalan;"},{"verse":50,"text":"Ug kamo mobuhat sa inyong kaugalingong buluhaton gamit ang inyong kaugalingon nga ngalan, ug pinaagi sa inyong kaugalingong mga ngalan."},{"verse":51,"text":"Ug gimando ko kini nga buhaton alang sa inyong kaluwasan, ug alang usab sa ilang kaluwasan, agi og sangpotanan sa pagpalayas kanila ug niana nga moabot."},{"verse":52,"text":"Ang mga pakigsaad nga wala matuman tungod sa kalapasan, sa pagkamasinahon ug sa mga pagpakaaron-ingnon nga pulong—"},{"verse":53,"text":"Busa, nagkatibulaag sa kamo isip nagkahiusang kapunongan uban sa inyong kaigsoonan, nga dili lamang kutob karong orasa nakagapos kamo ngadto kanila, sa ingon lamang niini nga paagi, sama sa akong giingon, pinaagi sa pagpanghulam nga pagauyonan sa konseho niini nga kapunongan, sumala sa pagtugot sa inyong mga kahimtang ug sa imando sa tingog sa konseho."},{"verse":54,"text":"Ug usab, hatagan ko kamo og usa ka sugo mahitungod sa inyong pagkatinugyanan nga akong gipili nga inyong idumala."},{"verse":55,"text":"Tan-awa, kining tanang kabtangan akoa, o kay kon dili ang inyong pagtuo makawang, ug masakpan kamo nga mga nagpakaaron-ingnon, ug ang mga pakigsaad nga inyong gihimo ngari kanako naguba;"},{"verse":56,"text":"Ug kon ang mga kabtangan akoa, nan kamo mga tinugyanan; kay kon dili, kamo dili mga tinugyanan."},{"verse":57,"text":"Apan, sa pagkatinuod sultihan ko kamo, gipili ko kamo nga mahimong mga tinugyanan sa akong balay, gani tinuod nga mga tinugyanan."},{"verse":58,"text":"Ug tungod niini nga katuyoan ako misugo kaninyo sa pagpundok sa inyong mga kaugalingon, gani sa pag-imprinta sa akong mga pulong, sa kahingpitan sa akong mga kasulatan, sa mga pagpadayag nga akong gihatag kaninyo, ug diin ako, human niini, sa matag karon og unya mohatag nganha kaninyo—"},{"verse":59,"text":"Alang sa katuyoan sa pagtukod sa akong simbahan ug sa gingharian sa yuta, ug sa pag-andam sa akong katawhan sa panahon nga ako mopuyo uban kanila, diin haduol na."},{"verse":60,"text":"Ug mangandam kamo alang sa inyong kaugalingon og usa ka dapit nga tipiganan, ug ipahinungod kini sa akong ngalan."},{"verse":61,"text":"Ug magpili kamo og usa taliwala kaninyo nga mobantay sa tipiganan, ug i-orden siya ngadto niini nga panalangin."},{"verse":62,"text":"Ug kinahanglan nga adunay selyo diha sa tipiganan, ug ang tanang sagrado nga butang kinahanglang ihatod ngadto sa tipiganan; ug walay tawo diha kaninyo nga moangkon niini nga iyang kaugalingon, o sa bisan unsang bahin niini, kay kini alang kaninyong tanan uban sa usa ka pag-uyon."},{"verse":63,"text":"Ug ihatag ko kini kaninyo niini gayod nga takna; ug karon seguroha, nga moadto kamo ug gamiton ang pagkatinugyanan nga akong gipili alang kaninyo, walay labot sa sagradong mga butang, alang sa katuyoan sa pag-imprinta niining sagradong mga butang sama sa akong gisulti."},{"verse":64,"text":"Ug ang mga halin sa sagradong mga butang kinahanglang anaa sa tipiganan, ug butangan kini og selyo; ug kinahanglang dili gamiton o kuhaon gikan sa tipiganan ni bisan kinsa, ni tangtangon ang selyo nga ibutang niini, gawas lamang kon pinaagi sa tingog sa kapunongan, o pinaagi sa sugo."},{"verse":65,"text":"Ug sa ingon niini inyong matipigan sa tipiganan ang mga halin sa sagradong mga butang, alang sa sagrado ug balaang mga katuyoan."},{"verse":66,"text":"Ug tawagon kini nga sagradong tipiganan sa Ginoo; ug butangan kini og selyo aron mahimo kining balaan ug ipahinungod sa Ginoo."},{"verse":67,"text":"Ug usab, kinahanglang adunay laing tipiganan nga andamon, ug usa ka tighupot sa bahandi ang pilion aron motipig sa tipiganan, ug butangan kini og selyo;"},{"verse":68,"text":"Ug ang tanang kwarta nga inyong madawat sa inyong pagkatinugyanan, pinaagi sa pagpalambo sa mga kabtangan nga akong gipili alang kaninyo, diha sa mga balay, o sa mga yuta, o sa dagkong mga hayop, o sa tanang butang gawas sa balaan ug sagradong mga sinulat, nga akong gitagana ngari kanako alang sa balaan ug sagradong mga katuyoan, kinahanglang ibutang sa tipiganan kutob sa mga kwarta nga inyong madawat, nga taggatosan, o tagkalim-an, o tagkawhaan, o tagnapulo, o taglima."},{"verse":69,"text":"O sa lain nga mga pulong, kon adunay tawo taliwala kaninyo nga makadawat og lima ka dolyares ipabutang kini niya ngadto sa tipiganan; o kon siya makadawat og napulo, o kawhaan, o kalim-an, o gatosan, ipahimo niya sa mao nga paagi;"},{"verse":70,"text":"Ug walay tugotan taliwala kaninyo nga moingon nga kini iyang kaugalingon; kay kini dili angkonon nga iya, ni ang bisan unsa nga bahin niini."},{"verse":71,"text":"Ug walay bisan unsa nga bahin niini nga pagagamiton, o pagakuhaon gikan sa tipiganan, gawas lamang kon pinaagi sa tingog ug pag-uyon sa kadaghanan sa kapunongan."},{"verse":72,"text":"Ug mao kini ang tingog ug pag-uyon sa kadaghanan sa kapunongan—nga si bisan kinsa nga tawo diha kaninyo moingon ngadto sa tighupot sa bahandi: Nagkinahanglan ako niini aron matabangan ako sa akong pagkatinugyanan—"},{"verse":73,"text":"Kon lima man kini ka dolyar, o napulo ka dolyar, o kawhaan, o kalim-an, o gatosan, ang tighupot sa bahandi mohatag kaniya sa kantidad nga iyang gikinahanglan aron matabangan siya sa iyang pagkatinugyanan—"},{"verse":74,"text":"Gawas kon masakpan siya nga nakalapas, ug klarong ikapakita atubangan sa konseho sa kapunongan nga siya dili matinud-anon ug usa ka dili maalamon nga tinugyanan."},{"verse":75,"text":"Apan samtang anaa pa siya sa hingpit nga pakigdait, ug matinud-anon ug maalamon sa iyang pagkatinugyanan, iya kini nga ilhanan ngadto sa tighupot sa bahandi nga dili mahimong ilimod sa tighupot sa bahandi."},{"verse":76,"text":"Apan kon adunay nahimong paglapas, ang tighupot sa bahandi mapaubos ngadto sa konseho ug sa tingog sa kapunongan."},{"verse":77,"text":"Ug kon ang tighupot sa bahandi masakpan nga dili matinud-anon ug dili maalamon nga tinugyanan, ipaubos siya sa konseho ug sa tingog sa kapunongan, ug palagpoton sa iyang katungdanan, ug adunay lain nga pilion nga ipuli kaniya."},{"verse":78,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, mahitungod sa inyong mga utang—tan-awa akong kabubut-on nga kamo kinahanglang mobayad sa inyong tanan nga utang."},{"verse":79,"text":"Ug akong kabubut-on nga kamo magpaubos sa inyong kaugalingon sa akong atubangan, ug magbaton niini nga mga panalangin pinaagi sa inyong kakugi ug kamapaubsanon ug pag-ampo inubanan sa pagtuo."},{"verse":80,"text":"Ug kon magmakugihon ug mapaubsanon kamo, ug maningkamot sa pag-ampo inubanan sa pagtuo, tan-awa, akong pahumokon ang mga kasingkasing niadtong inyong giutangan, hangtod nga makapadala ako og mga paagi nganha kaninyo aron kamo makalingkawas."},{"verse":81,"text":"Busa pagsulat dayon ngadto sa New York ug isulat ang unsay isulti sa akong Espiritu; ug akong pahumokon ang mga kasingkasing niadtong inyong giutangan, aron mawala sa ilang mga hunahuna ang pagsakit kaninyo."},{"verse":82,"text":"Ug kon magpaubos kamo ug magmatinud-anon ug motawag sa akong ngalan, tan-awa, hatagan ko kamo og kadaogan."},{"verse":83,"text":"Hatagan ko kamo og usa ka saad, nga kamo makalingkawas niining higayona gikan sa inyong pagkaulipon."},{"verse":84,"text":"Ug kon makabaton kamo og kahigayonan sa paghulam og kwarta nga taggatosan, o tagkaliboan, hangtod nga makahulam kamo og igo nga makalingkawas ang inyong kaugalingon gikan sa pagkaulipon, inyo kini nga kahigayonan."},{"verse":85,"text":"Ug isaad ang mga kabtangan nga akong gitugyan sa inyong mga kamot, sa makausa, pinaagi sa paghatag sa inyong mga ngalan pinaagi sa pag-uyon sa kadaghanan o kon dili, sigon sa unsay maayo alang kaninyo."},{"verse":86,"text":"Hatagan ko kamo niini nga kahigayonan, sa makausa; ug tan-awa, kon ipadayon ninyo ang pagbuhat sa mga butang nga akong gipahayag sa inyong atubangan, sumala sa akong mga sugo, kining tanang butang akoa, ug kamo akong mga tinugyanan, ug ang agalon dili motugot nga ang iyang balay mabungkag. Ug mao gayod kana. Amen."}]},{"chapter":105,"verses":[{"verse":1,"text":"Sa pagkatinuod sultihan ko kamong nagkapundok sa inyong mga kaugalingon aron makakat-on kamo sa akong kabubut-on mahitungod sa katubsanan sa akong sinakit nga katawhan—"},{"verse":2,"text":"Tan-awa, sultihan ko kamo, kon dili pa tungod sa mga kalapasan sa akong katawhan, kon hisgotan ang simbahan ug dili sa tinagsa-tagsang mga tawo, natubos na unta sila karon."},{"verse":3,"text":"Apan tan-awa, wala sila makakat-on sa pagsunod sa mga butang nga akong gipangayo gikan sa ilang mga kamot, apan puno sa tanang matang sa kadaotan, ug dili makigbahin sa ilang kabuhian, sama sa unsay angay nga buhaton sa mga santos, ngadto sa mga kabos ug mga sinakit diha kanila;"},{"verse":4,"text":"Ug wala magkahiusa sumala sa pagkahiusa nga gikinahanglan sa balaod sa celestial nga gingharian;"},{"verse":5,"text":"Ug ang Zion dili matukod kondili pinaagi sa mga baroganan sa balaod sa celestial nga gingharian; kay kondili, ako dili makadawat kaniya sa akong kaugalingon."},{"verse":6,"text":"Ug ang akong katawhan kinahanglan nga mapanton hangtod nga makakat-on sila sa pagkamasulundon, kon gikinahanglan gayod, pinaagi sa mga butang nga ilang giantos."},{"verse":7,"text":"Wala ako mamulong mahitungod niadtong gitahasan sa pagpangulo sa akong katawhan, kinsa mao ang una nga mga elder sa akong simbahan, kay silang tanan dili ubos niini nga paghukom;"},{"verse":8,"text":"Apan mamulong ako mahitungod sa akong mga simbahan sa layo nga dapit—adunay daghan nga moingon: Hain ang ilang Dios? Tan-awa, siya moluwas kanila sa panahon sa kasamok, kay kon dili man gani dili kita moadto sa Zion, ug itago ang atong mga salapi."},{"verse":9,"text":"Busa, agi og sangpotanan sa mga kalapasan sa akong katawhan, mahinungdanon alang kanako nga ang akong mga elder maghulat og mubong panahon alang sa katubsanan sa Zion—"},{"verse":10,"text":"Aron sila sa ilang kaugalingon mahimong andam, ug aron ang akong katawhan mas hingpit nga matudloan, ug makabaton og kasinatian, ug mas hingpit nga mahibalo mahitungod sa ilang katungdanan, ug sa mga butang nga gikinahanglan nako sa ilang mga kamot."},{"verse":11,"text":"Ug dili kini mapahitabo hangtod ang akong mga elder matugahan og gahom gikan sa kahitas-an."},{"verse":12,"text":"Kay tan-awa, nag-andam ako og mahinungdanong pagtuga ug panalangin nga ibu-bo diha kanila, kon magmatinud-anon sila ug magpadayon sa pagkamapainubsanon sa akong atubangan."},{"verse":13,"text":"Busa mahinungdanon alang kanako nga ang akong mga elder maghulat og mubong panahon, alang sa katubsanan sa Zion."},{"verse":14,"text":"Kay tan-awa, wala nako kinahanglana gikan sa ilang mga kamot nga makig-away sa gubat sa Zion; kay, sama sa akong gikasulti sa unang sugo,—Ako ang makig-away alang sa inyong mga gubat."},{"verse":15,"text":"Tan-awa, ang tiglaglag akong gipadala aron molaglag ug molumpag sa akong mga kaaway; ug dili pa moabot ang daghang katuigan gikan karon dili sila pasagdang magpabilin nga mohugaw-hugaw sa akong kabilin, ug sa pagpasipala sa akong ngalan diha sa mga yuta nga akong gipahinungod alang sa pagpundok sa akong mga santos."},{"verse":16,"text":"Tan-awa, akong gisugo ang akong sulugoon nga si Joseph Smith, Jun., sa pagsulti ngadto sa dugang nga kusog sa akong balay, gani ang akong mga manggugubat, ug ang akong mga batan-ong lalaki, ug mga hamtong, sa pagpundok alang sa katubsanan sa akong katawhan, ug sa pagguba sa mga tore sa akong mga kaaway, ug patibulaagon ang ilang mga magbalantay;"},{"verse":17,"text":"Apan ang dugang nga kusog sa akong balay wala mopatalinghog sa akong mga pulong."},{"verse":18,"text":"Apan kon adunay mopatalinghog sa akong mga pulong, nag-andam ako og panalangin ug usa ka pagtuga alang kanila, kon magpadayon sila nga matinud-anon."},{"verse":19,"text":"Gidungog ko na ang ilang mga pag-ampo, ug modawat sa ilang mga halad; ug mahinungdanon alang kanako nga dad-on sila sa ingon niini nga gilay-on alang sa pagsulay sa ilang pagtuo."},{"verse":20,"text":"Ug karon, sa pagkatinuod sultihan ko kamo, usa ka sugo ang akong ihatag kaninyo, nga kutob sa moanhi dinhi, nga makapabilin sa palibot nga rehiyon, tugoti nga sila magpabilin;"},{"verse":21,"text":"Ug kadto nga dili magpabilin, kinsa adunay mga pamilya sa silangan, pahulata sila sa mubong panahon, kon ang akong sulugoon nga si Joseph mosugo kanila;"},{"verse":22,"text":"Kay motambag ako kaniya mahitungod niini nga butang, ug ang tanang bisan unsang butang nga iyang isugo ngadto kanila matuman."},{"verse":23,"text":"Ug himoa nga ang akong katawhan nga nagpuyo sa palibot nga mga rehiyon magmatinud-anon kaayo, ug magmainampoon, ug magmapainubsanon sa akong atubangan, ug dili mopadayag sa mga butang nga akong gipadayag ngadto kanila, hangtod nga maalamon na alang kanako nga ipadayag kini."},{"verse":24,"text":"Ayaw paghisgot og mga paghukom, ni pagpasigarbo sa pagtuo ni sa kahibulongang mga buhat, apan pagmabinantayon nga magtigom, kutob sa mahimo diha sa usa ka rehiyon, sumala sa mga pagbati sa katawhan;"},{"verse":25,"text":"Ug tan-awa, hatagan ko kamo og pabor ug pagsalig sa ilang mga mata, aron magpuyo kamo sa kalinaw ug luwas sa katalagman, samtang makigsulti kamo sa katawhan: Ipahamtang ang paghukom ug kaangayan ngari kanamo sumala sa balaod, ug pasayloa kami sa among mga kasaypanan."},{"verse":26,"text":"Karon, tan-awa, sultihan ko kamo, akong mga higala, sa ingon niini nga paagi paboran kamo sa mga mata sa katawhan, hangtod ang kasundalohan sa Israel mahimo nga labing bantogan."},{"verse":27,"text":"Ug akong pahumokon ang mga kasingkasing sa katawhan, sama sa akong gibuhat sa kasingkasing ni Paraon, sa matag karon ug unya, hangtod nga ang akong sulugoon nga si Joseph Smith, Jun., ug ang akong mga elder, nga akong gipili, makahigayon sa pagpundok og kusgan nga mga tawo sa akong balay,"},{"verse":28,"text":"Ug makapadala og mga tawo nga maalamon, sa pagtuman sa akong gisugo mahitungod sa pagpalit sa tanang yuta sa lalawigan sa Jackson nga mapalit, ug sa kasikbit nga mga lalawigan sa palibot."},{"verse":29,"text":"Kay maoy kabubut-on nako nga paliton kini nga mga yuta; ug human nga kini mapalit ang akong mga santos makapanag-iya niini sumala sa mga balaod sa pagpahinungod nga ako nang gihatag."},{"verse":30,"text":"Ug human mapalit kining mga yuta, dili ko pakasad-on ang mga sundalo sa Israel sa pagpanag-iya sa ilang kaugalingong mga yuta, nga kanhi ilang napalit sa ilang mga salapi, ug sa pagguba sa mga tore sa akong mga kaaway nga mohasmag kanila, ug sa pagpatibulaag sa ilang mga magbalantay, ug sa pagpanimalos alang kanako sa akong mga kaaway ngadto sa ikatulo ug ikaupat nga henerasyon kanila nga nagdumot kanako."},{"verse":31,"text":"Apan himoang bantogan kaayo ang akong mga sundalo, ug himoa kini nga balaan sa akong atubangan, aron mahimo nga hayag sama sa adlaw, ug tin-aw sama sa bulan, ug aron ang iyang mga bandila mahimong makalilisang ngadto sa tanang kanasoran;"},{"verse":32,"text":"Aron ang mga gingharian niini nga kalibotan mapugos sa pagdawat nga ang gingharian sa Zion sa pagkatinuod mao ang gingharian sa atong Dios ug sa iyang Kristo; busa, magpaubos kita sa iyang mga balaod."},{"verse":33,"text":"Sa pagkatinuod sultihan ko kamo, mahinungdanon alang kanako nga ang unang mga elder sa akong simbahan kinahanglan nga makadawat sa ilang pagtuga gikan sa kahitas-an diha sa akong balay, nga akong gisugo nga tukoron alang sa akong ngalan sa yuta sa Kirtland."},{"verse":34,"text":"Ug kadtong mga sugo nga akong gihatag mahitungod sa Zion ug ang iyang balaod ipahamtang ug ipatuman, human sa iyang katubsanan."},{"verse":35,"text":"Dihay adlaw sa balaan nga pagtawag, apan ang panahon miabot na alang sa adlaw sa pagpili; ug pilia kadtong mga takos."},{"verse":36,"text":"Ug ipadayag kini ngadto sa akong sulugoon, pinaagi sa tingog sa Espiritu, kadto sila nga gipili; ug sila pagabalaanon;"},{"verse":37,"text":"Ug kon mosunod sila sa tambag nga ilang nadawat, makabaton sila og gahom human sa daghang adlaw sa pagtuman sa tanang butang kalabot sa Zion."},{"verse":38,"text":"Ug sa gihapon sultihan ko kamo, pangamuyo alang sa kalinaw, dili lamang ngadto sa katawhan nga nagdagmal kaninyo, apan ngadto usab sa tanang katawhan;"},{"verse":39,"text":"Ug pagpakayab og bandila sa kalinaw, ug paghimo og pamahayag sa kalinaw ngadto sa mga kinatumyan sa yuta;"},{"verse":40,"text":"Ug paghimo og mga sugyot alang sa kalinaw ngadto niadtong nagdagmal kaninyo, sumala sa tingog sa Espiritu nga anaa kaninyo, ug ang tanang butang magtinabangay alang sa inyong kaayohan."},{"verse":41,"text":"Busa, pagmatinud-anon; ug tan-awa, ug sud-onga, ako magauban kaninyo gani hangtod sa kataposan. Ug mao gayod kana. Amen."}]},{"chapter":106,"verses":[{"verse":1,"text":"Akong kabubut-on nga ang akong sulugoon nga si Warren A. Cowdery tawagon sa katungdanan ug ordinahan nga tigdumalang high priest sa akong simbahan, sa yuta sa Freedom ug sa palibot nga mga rehiyon;"},{"verse":2,"text":"Ug mosangyaw sa akong walay kataposang ebanghelyo, ug mopataas sa iyang tingog ug mopasidaan sa katawhan, dili lamang sa iyang kaugalingong dapit, apan sa kasikbit nga mga lalawigan;"},{"verse":3,"text":"Ug mohalad sa iyang tibuok nga panahon niining halangdon ug balaan nga tawag, nga karon akong ihatag ngadto kaniya, makugihong mangita sa gingharian sa langit ug sa pagkamatarong niini, ug ang tanang butang nga gikinahanglan madugang ngadto niini; kay ang mamumuo takos sa iyang suhol."},{"verse":4,"text":"Ug usab, sa pagkatinuod sulithan ko kamo, ang pag-anhi sa Ginoo nagkaduol na, ug mopahikurat sa kalibotan sama sa usa ka kawatan sa kagabhion—"},{"verse":5,"text":"Busa, baksi ang inyong mga bat-ang, aron kamo mahimo nga mga anak sa kahayag, ug kana nga adlaw dili mopahikurat kaninyo sama sa kawatan."},{"verse":6,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, dihay kamaya sa langit sa dihang ang akong sulugoon nga si Warren miyukbo sa akong gahom, ug mibulag gikan sa mga panikas sa mga tawo;"},{"verse":7,"text":"Busa, bulahan ang akong sulugoon nga si Warren, kay may kaluoy ako kaniya; ug, bisan pa sa garbo sa iyang kasingkasing, ituboy nako siya kon ugaling magpaubos siya sa iyang kaugalingon sa akong atubangan."},{"verse":8,"text":"Hatagan nako siya og grasya ug kasegurohan bisan asa siya mobarog; ug kon magpadayon siya nga matinud-anon nga saksi ug kahayag ngadto sa simbahan nag-andam ako og korona alang kaniya sa mga mansyon sa akong Amahan. Ug mao gayod kana. Amen."}]},{"chapter":107,"verses":[{"verse":1,"text":"Sa simbahan, adunay duha ka pagkapari, nga ginganlan, og Melchizedek ug Aaronic, lakip niini ang Levitico nga Pagkapari."},{"verse":2,"text":"Kon nganong ang una gitawag og Melchizedek nga Pagkapari, tungod kay si Melchizedek usa ka bantogan nga high priest."},{"verse":3,"text":"Sa wala pa ang iyang panahon gitawag kini nga ang Balaang Pagkapari, sunod sa Kapunongan sa Anak sa Dios."},{"verse":4,"text":"Apan tungod sa pagtahod o balaanong pagtahod sa ngalan sa Labing Gamhanang Binuhat, sa paglikay usab sa kanunay kaayo nga pagbalik-balik sa iyang ngalan, sila, ang simbahan, sa karaang mga adlaw, mitawag niana nga pagkapari sunod ni Melchizedek, o ang Melchizedek nga Pagkapari."},{"verse":5,"text":"Ang ubang mga awtoridad o mga buhatan diha sa simbahan mga sumpay lamang niini nga pagkapari."},{"verse":6,"text":"Apan adunay duha ka bahin o labing taas nga mga pangulo—ang usa mao ang Melchizedek nga Pagkapari, ug ang usa pa mao ang Aaronic o Levitico nga Pagkapari."},{"verse":7,"text":"Ang buhatan sa elder nagagikan sa pagkapari ni Melchizedek."},{"verse":8,"text":"Ang Melchizedek nga Pagkapari naghupot sa katungod sa kapangulohan, ug adunay gahom ug awtoridad labaw sa tanang buhatan sa Simbahan sa tanang panahon sa kalibotan, sa pagdumala sa espirituhanong mga butang."},{"verse":9,"text":"Ang Kapangulohan sa Labaw nga Pagkapari sunod sa kapunongan ni Melchizedek, adunay katungod sa pagdumala sa tanang buhatan sa simbahan."},{"verse":10,"text":"Ang mga high priest sunod sa kapunongan sa Melchizedek nga Pagkapari adunay katungod sa pagdumala sa ilang kaugalingong katungdanan, ubos sa pagmando sa kapangulohan, sa pagpangalagad sa espirituhanong mga butang, ug usab sa buhatan sa usa ka elder, priest sa (Levitico nga kapunongan), magtutudlo, deacon, ug sakop."},{"verse":11,"text":"Ang usa ka elder adunay katungod sa pagdumala sa iyang dapit kon ang high priest wala diha."},{"verse":12,"text":"Ang high priest ug ang elder mangalagad sa espirituhanong mga butang, subay sa mga pakigsaad ug mga sugo sa simbahan; ug may katungod sila sa pagdumala niining tanang buhatan sa simbahan kon walay mas taas og awtoridad nga anaa."},{"verse":13,"text":"Ang ikaduha nga pagkapari gitawag og Pagkapari ni Aaron, tungod kay gitugyan kini ngadto ni Aaron ug sa iyang binhi, sa tanan nila nga henerasyon."},{"verse":14,"text":"Nganong gitawag kini nga mas ubos nga pagkapari tungod kay sumpay kini sa mas labaw, o sa Melchizedek nga Pagkapari, ug adunay gahom sa pagpangalagad sa dayag nga mga ordinansa."},{"verse":15,"text":"Ang bishopric mao ang kapangulohan niini nga pagkapari, ug naghupot sa mga yawe sa sama nga awtoridad."},{"verse":16,"text":"Walay tawo nga adunay legal nga katungod niini nga buhatan, sa paghupot sa mga yawe niini nga pagkapari, gawas kon siya tinuod nga kaliwat ni Aaron."},{"verse":17,"text":"Apan tungod kay ang high priest sa Melchizedek nga Pagkapari may awtoridad sa pagdumala sa tanang mas ubos nga mga buhatan, mahimo siyang modumala sa buhatan sa bishop kon walay makit-an nga tinuod nga kaliwat ni Aaron, basta tawagon siya ug igahin sa tahas ug ordinahan ngadto niini nga gahom pinaagi sa mga kamot sa Kapangulohan sa Melchizedek nga Pagkapari."},{"verse":18,"text":"Ang gahom ug awtoridad sa mas labaw, o sa Melchizedek nga Pagkapari, mao ang paghupot sa mga yawe sa tanang espirituhanong mga panalangin sa simbahan—"},{"verse":19,"text":"Aron makaangkon sa kahigayonan sa pagdawat sa mga misteryo sa gingharian sa langit, aron maabli ang kalangitan ngadto kanila, makigdait sa kinatibuk-an nga pundok ug simbahan sa Unang Natawo, ug aron makasinati sa pakigdait ug sa presensiya sa Dios nga Amahan, ug ni Jesus ang tigpataliwala sa bag-ong pakigsaad."},{"verse":20,"text":"Ang gahom ug awtoridad sa mas ubos, o sa Aaronic nga Pagkapari, mao ang paghupot sa mga yawe sa pagpangalagad sa mga anghel, ug sa pagdumala sa dayag nga mga ordinansa, ang sinulat nga ebanghelyo, ang bunyag sa paghinulsol alang sa kapasayloan sa mga sala, nga nahiuyon sa mga pakigsaad ug mga sugo."},{"verse":21,"text":"Tungod niana, gikinahanglan nga adunay mga presidente, o mga opisyal nga tigdumala nga magagikan, o mapili o gikan niadtong giordinahan ngadto sa pipila ka buhatan niining duha ka pagkapari."},{"verse":22,"text":"Sa Melchizedek nga Pagkapari, ang tulo ka Tigdumala nga mga High Priest, nga gipili sa mga sakop, nga gisangonan ug giordinahan niana nga buhatan, ug gituboy pinaagi sa pagsalig, pagtuo, ug pag-ampo sa simbahan, mao ang mahimong korum sa Kapangulohan sa Simbahan."},{"verse":23,"text":"Ang napulog duha ka tigbiyahe nga mga sakop sa konseho tawagon aron mahimong Napulog Duha ka Apostoles, o espesyal nga mga saksi sa ngalan ni Kristo sa tibuok kalibotan—sa ingon malahi gikan sa ubang mga opisyal sa simbahan sumala sa mga katungdanan sa ilang balaang tawag."},{"verse":24,"text":"Ug mahimo silang usa ka korum, patas ang awtoridad ug gahom sa tulo ka presidente nga gihisgotan na."},{"verse":25,"text":"Ang Seventy gitawag usab sa pagsangyaw sa ebanghelyo, ug aron mahimong talagsaong mga saksi ngadto sa mga Hentil ug sa tibuok kalibotan—sa ingon lahi gikan sa ubang mga opisyal sa simbahan sumala sa mga katungdanan sa ilang balaang tawag."},{"verse":26,"text":"Ug maporma sila nga usa ka korum, patas og awtoridad ngadto sa Napulog Duha ka talagsaong mga saksi o Apostoles nga bag-o lang nga ginganlan."},{"verse":27,"text":"Ug ang matag paghukom nga himoon sa bisan hain niini nga korum kinahanglan nga ipaagi sa hiniusa nga tingog niini nga korum; nga mao, nga ang matag sakop sa tagsa-tagsa ka korum kinahanglan nga mouyon sa ilang mga paghukom, aron sa paghimo sa ilang paghukom nga sama og gahom o kalig-on sa usag usa—"},{"verse":28,"text":"Ang sobra sa katunga sa mga sakop makaporma og korum kon ang mga sirkumstansiya dili motugot nga magkapundok ang tanan—"},{"verse":29,"text":"Gawas niini nga kahimtang, ang ilang mga paghukom walay katungod sa samang mga panalangin nga gihatag ngadto sa mga paghukom sa korum sa tulo ka pangulo sa karaang panahon, kinsa giordinahan sumala sa kapunongan ni Melchizedek, ug mga matarong ug mga tawo nga balaan."},{"verse":30,"text":"Ang mga paghukom niini nga mga korum, o bisan hain kanila, pagahimoon sa tanang pagkamatarong, sa kabalaan, ug pagpaubos sa kasingkasing, kaaghop ug pagkamainantoson, ug sa pagtuo, ug hiyas, ug kahibalo, pagkamapugnganon sa kaugalingon, pailob, pagkadiosnon, inigsoon nga pagkamabination ug gugmang putli;"},{"verse":31,"text":"Tungod kay ang saad mao nga, kon buhong sila niining mga butanga dili sila magkulang sa kahibalo sa Ginoo."},{"verse":32,"text":"Ug kon sa higayon nga adunay paghukom niini nga mga korum nga himoon sa dili matarong nga paagi, mahimo kining dad-on sa atubangan sa kinatibuk-ang pundok sa lain-laing mga korum, nga naglangkob sa espirituhanong mga awtoridad sa simbahan; kondili walay mahimo nga pag-apelar sa ilang paghukom."},{"verse":33,"text":"Ang Napulog Duha mao ang Tigbiyahe nga Tigdumala nga Labaw nga Konseho, aron mangalagad sa ngalan sa Ginoo, ubos sa direksyon sa Kapangulohan sa Simbahan, uyon sa pamaagi sa langit; aron mopalig-on sa simbahan, ug modumala sa tanang kalihokan niini sa tanang nasod, una ngadto sa mga Hentil ug ikaduha ngadto sa mga Judeo."},{"verse":34,"text":"Ang Seventy molihok sa ngalan sa Ginoo, ubos sa direksiyon sa Napulog Duha o sa tigbiyahe nga labaw nga konseho, sa pagpalig-on sa simbahan ug pagdumala sa tanang kalihokan niini sa tanang nasod, una ngadto sa mga Hentil ug unya sa mga Judeo—"},{"verse":35,"text":"Ang Napulog Duha nga gipadala, naghupot sa mga yawe, sa pag-abli sa pultahan pinaagi sa pagpahayag sa ebanghelyo ni Jesukristo, ug una ngadto sa mga Hentil ug dayon sa mga Judeo."},{"verse":36,"text":"Ang lokal nga labaw nga mga konseho, sa mga stake sa Zion, magporma og korum nga kaparehas og awtoridad sa mga kalihokan sa simbahan, sa tanan nilang paghukom, ngadto sa korum sa kapangulohan, o sa tigbiyahe nga labaw nga konseho."},{"verse":37,"text":"Ang labaw nga konseho sa Zion moporma og korum nga kaparehas og awtoridad sa mga kalihokan sa simbahan, sa ilang tanan nga paghukom, ngadto sa mga konseho sa Napulog Duha sa mga stake sa Zion."},{"verse":38,"text":"Katungdanan sa tigbiyahe nga labaw nga konseho ang pagtawag og Seventy, kon magkinahanglan sila og tabang, aron sa pagbutang og pipila ka katungdanan alang sa pagsangyaw ug pagpangalagad sa ebanghelyo, imbis ni bisan kinsa."},{"verse":39,"text":"Katungdanan sa Napulog Duha, sa tanang dagko nga mga sanga sa simbahan, ang pag-ordina og mga ebanghelista nga tigpangalagad, kay sila ihatag ngadto kanila pinaagi sa pagpadayag—"},{"verse":40,"text":"Ang kapunongan niini nga pagkapari gimatuod nga gipasa gikan sa amahan ngadto sa anak nga lalaki, ug tukmang gihuptan sa tinuod nga kaliwat sa pinili nga binhi, kang kinsa ang mga saad gihimo."},{"verse":41,"text":"Kini nga kapunongan gitukod sa panahon ni Adan, ug gipasa sa nagsunod nga kaliwatan sa mosunod nga pamaagi:"},{"verse":42,"text":"Gikan ni Adan ngadto ni Seth, nga giordinahan ni Adan sa edad nga kan-oman ug siyam ka tuig, ug napanalanginan pinaagi kaniya tulo ka tuig sa wala pa ang iyang kamatayon (ni Adan), ug nakadawat sa saad sa Dios pinaagi sa iyang amahan, nga ang iyang kaliwat pilion sa Ginoo, ug nga sila mapatunhay hangtod sa kataposan sa yuta;"},{"verse":43,"text":"Tungod kay siya (si Seth) tawo nga hingpit, ug ang iyang panagway liwat sa iyang amahan, nga niana maingon nga sama siya sa iyang amahan sa tanang butang, ug mailhan lamang ang kalainan gikan kaniya tungod sa iyang edad."},{"verse":44,"text":"Si Enos giordinahan sa edad nga usa ka gatos ug katloan ug upat ka tuig ug upat ka bulan, pinaagi sa kamot ni Adan."},{"verse":45,"text":"Ang Dios mitawag ni Cainan gikan sa kamingawan sa edad nga ikakap-atan ka tuig; ug iyang gikasugat si Adan samtang nagpanaw ngadto sa dapit sa Shedolamak. Nag-edad siya og kawaloan ug pito ka tuig sa dihang nadawat niya ang iyang ordinasyon."},{"verse":46,"text":"Si Mahalaleel nag-edad og upat ka gatos ug kasiyaman ug unom ka tuig ug pito ka adlaw sa dihang giordinahan siya pinaagi sa kamot ni Adan, kinsa usab mipanalangin kaniya."},{"verse":47,"text":"Si Jared nagpanuigon og duha ka gatos ka tuig sa dihang gi-orden siya ubos sa kamot ni Adan, kinsa usab mipanalangin kaniya."},{"verse":48,"text":"Si Enoch nagpanuigon og kawhaan ug lima ka tuig sa dihang giordinahan siya ubos sa kamot ni Adan; ug kan-oman ug lima siya ug si Adan mipanalangin kaniya."},{"verse":49,"text":"Ug nakita niya ang Ginoo, ug naglakaw siya uban kaniya, ug kanunay nga anaa sa iyang atubangan; ug naglakaw siya uban sa Dios sa tulo ka gatos ug kan-oman ug lima ka tuig, mihimo kaniya og upat ka gatos ug katloan ka tuig ang edad sa dihang nahimaya ang iyang lawas."},{"verse":50,"text":"Si Matusela nag-edad og usa ka gatos sa dihang giordinahan siya ubos sa kamot ni Adan."},{"verse":51,"text":"Si Lamech nag-edad og katloan ug duha ka tuig sa dihang giordinahan siya ubos sa kamot ni Seth."},{"verse":52,"text":"Si Noe nag-edad og napulo ka tuig sa dihang giordinahan siya sa kamot ni Metusela."},{"verse":53,"text":"Tulo ka tuig sa wala pa ang kamatayon ni Adan, iyang gitawag si Seth, Enos, Cainan, Mahalaleel, Jared, Enoch ug Metusela, kinsa pulos mga hight priest, uban sa nahibilin sa iyang matarong nga kaliwatan, ngadto sa walog sa Adam-ondi-Ahman, ug didto gituga ngadto kanila ang iyang kataposang panalangin."},{"verse":54,"text":"Ug ang Ginoo mipakita kanila, ug mibarog sila ug mipanalangin ni Adan, ug mitawag kaniya nga Miguel, ang prinsipe, ang arkanghel."},{"verse":55,"text":"Ug ang Ginoo mihatag kang Adan og kahupayan, ug misulti kaniya: Ako miandam kanimo nga mahimong pangulo; daghang nasod magagikan kanimo, ug ikaw ang ilang prinsipe sa kahangtoran."},{"verse":56,"text":"Ug si Adan mibarog taliwala sa katigoman; ug, bisan pa og nagbakô na siya tungod sa edad, samtang puno sa Espiritu Santo, nanagna kon unsa ang mahitabo sa iyang kaliwatan hangtod sa labing ulahi nga henerasyon."},{"verse":57,"text":"Kining tanan nga butang nahisulat sa basahon ni Enoch, ug ipamatuod sa tukmang panahon."},{"verse":58,"text":"Katungdanan usab sa Napulog Duha, ang pag-orden ug sa pagpahimutang diha sa kahusay sa uban pang mga opisyal sa simbahan, nga mahiuyon sa pagpadayag nga nag-ingon:"},{"verse":59,"text":"Ngadto sa simbahan ni Kristo sa yuta sa Zion, agig dugang sa mga balaod sa simbahan bahin sa mga kalihokan sa simbahan—"},{"verse":60,"text":"Sa pagkatinuod, sultihan ko kamo, nag-ingon ang Ginoo sa mga Panon, kinahanglan nga adunay tigdumala nga mga elder nga modumala niadtong anaa sa buhatan sa usa ka elder;"},{"verse":61,"text":"Ug usab ang mga priest modumala niadtong anaa sa katungdanan sa usa ka priest;"},{"verse":62,"text":"Ug usab ang mga teacher aron modumala niadtong anaa sa katungdanan sa teacher, sa samang paagi, ug mao usab ang mga deacon—"},{"verse":63,"text":"Mao nga, gikan sa deacon ngadto sa teacher, ug gikan sa teacher ngadto sa priest, ug gikan sa priest ngadto sa elder, tagsa-tagsa sa samang paagi nga sila gipahimutang sa katungdanan, sumala sa mga pakigsaad ug mga sugo sa simbahan."},{"verse":64,"text":"Dayon anaa ang Labaw nga Pagkapari, nga mao ang labaw sa tanan."},{"verse":65,"text":"Mao nga, gikinahanglan nga adunay usa nga matudlo sa Labaw nga Pagkapari aron modumala sa pagkapari, ug pagatawgon siya nga Pangulo sa Labaw nga Pagkapari sa Simbahan;"},{"verse":66,"text":"O, sa laing mga pulong, ang Tigdumala nga High Priest ibabaw sa Labaw nga Pagkapari sa Simbahan."},{"verse":67,"text":"Gikan gihapon niana maggikan ang pagdumala sa mga ordinansa ug mga panalangin diha sa simbahan, pinaagi sa pagpandong sa mga kamot."},{"verse":68,"text":"Mao nga, ang buhatan sa bishop dili parehas niini; kay ang buhatan sa bishop mao ang pagpangalagad sa tanang temporal nga butang;"},{"verse":69,"text":"Bisan pa niana ang bishop kinahanglan nga pilion gikan sa Labaw nga Pagkapari, gawas kon siya tinuod nga kaliwat ni Aaron;"},{"verse":70,"text":"Kay gawas kon tinuod siya nga kaliwat ni Aaron dili siya makahupot sa mga yawe niana nga pagkapari."},{"verse":71,"text":"Hinuon, ang usa ka high priest, sunod sa kapunongan ni Melchizedek, mahimong igahin sa pagpangalagad sa temporal nga mga butang, nakaangkon og kahibalo niini pinaagi sa Espiritu sa kamatuoran;"},{"verse":72,"text":"Ug usab aron mahimong maghuhukom sa Israel, nga mohimo sa mga kalihokan sa simbahan, aron mohukom sa mga malapason sumala sa pagpamatuod nga ipadayag sa iyang atubangan sumala sa mga balaod, pinaagi sa panabang sa iyang mga magtatambag, nga iyang gipili o pilion taliwala sa mga elder sa simbahan."},{"verse":73,"text":"Mao kini ang katungdanan sa bishop nga dili tinuod nga kaliwat ni Aaron, apan giordinahan ngadto sa Labaw nga Pagkapari sunod sa kapunongan ni Melchizedek."},{"verse":74,"text":"Sa ingon niana mahimo siyang maghuhukom, gani maghuhukom alang sa tanang lumulupyo sa Zion, o sa istaka sa Zion, o sa bisan asa nga sanga sa simbahan diin siya igahin alang niini nga pagpangalagad, hangtod ang mga utlanan sa Zion modako ug magkinahanglan nga adunay uban pang mga bishop o mga maghuhukom sa Zion o sa laing mga dapit."},{"verse":75,"text":"Ug maingon nga adunay uban pang mga bishop nga ibutang sa katungdanan molihok sila diha niini nga samang buhatan."},{"verse":76,"text":"Apan ang tinuod nga kaliwat ni Aaron adunay legal nga katungod sa kapangulohan niini nga pagkapari, sa mga yawe niini nga pagpangalagad, sa paglihok sa gimbuhaton sa buhatan sa bishop nga magkinaugalingon, walay mga magtatambag, gawas sa usa ka hitabo diin ang usa ka Pangulo sa Labaw nga Pagkapari, sunod sa kapunongan ni Melchizedek, pagahukman, nga molingkod ingon nga usa ka maghuhukom sa Israel."},{"verse":77,"text":"Ug ang paghukom sa bisan hain niining mga konseho, nga mahiuyon sa sugo nga nag-ingon:"},{"verse":78,"text":"Usab, sa pagkatinuod, sultihan ko kamo, ang labing mahinungdanon nga kalihokan sa simbahan, ug ang labing lisod nga mga kaso sa simbahan, kon ugaling dili makakontento ang mga paghukom sa bishop o sa mga maghuhukom, isang-at kini ngadto ug dad-on ngadto sa konseho sa simbahan, atubangan sa Kapangulohan sa Labaw nga Pagkapari."},{"verse":79,"text":"Ug ang Kapangulohan sa konseho sa Labaw nga Pagkapari makaangkon og gahom sa pagtawag og uban pa nga mga high priest, gani napulog duha, aron motabang isip mga magtatambag; ug sa ingon niana ang Kapangulohan sa Labaw nga Pagkapari ug ang mga magtatambag niini adunay gahom sa paghukom sumala sa pagpamatuod sumala sa mga balaod sa simbahan."},{"verse":80,"text":"Ug human niini nga paghukom dili na kini hinumdoman sa atubangan sa Ginoo; kay mao kini ang labing taas nga konseho sa simbahan sa Dios, ug kataposang paghukom sa mga panagsumpaki sa espirituhanong mga butang."},{"verse":81,"text":"Walay tawo nga nahisakop sa simbahan ang makalingkawas gikan niini nga konseho sa simbahan."},{"verse":82,"text":"Ug kon ang usa ka Presidente sa Labaw nga Pagkapari makalapas, pagadad-on siya sa atubangan sa komon nga konseho sa simbahan, kinsa pagaabagan pinaagi sa napulog duha ka magtatambag sa Labaw nga Pagkapari;"},{"verse":83,"text":"Ug ang ilang hukom diha sa iyang ulo makapahunong sa panagsumpaki mahitungod kaniya."},{"verse":84,"text":"Sa ingon niana, walay makalingkawas gikan sa kaangayan ug sa mga balaod sa Dios, aron ang tanang butang mahimo diha sa kahusay ug sa kaligdong sa iyang atubangan, sumala sa kamatuoran ug sa pagkamatarong."},{"verse":85,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ang katungdanan sa usa ka pangulo ibabaw sa buhatan sa deacon mao ang pagdumala sa napulog duha ka deacon, sa paglingkod diha sa konseho uban kanila, ug sa pagtudlo kanila sa ilang katungdanan, mopalig-on sa usag usa, sama sa gihatag sumala sa mga pakigsaad."},{"verse":86,"text":"Ug usab ang katungdanan sa pangulo sa buhatan sa mga teacher mao ang pagdumala sa kawhaan ug upat ka teacher, ug sa paglingkod sa konseho uban kanila, magtudlo kanila sa mga katungdanan sa ilang buhatan, sama sa gihatag diha sa mga pakigsaad."},{"verse":87,"text":"Usab ang katungdanan sa pangulo sa Pagkapari ni Aaron mao ang pagdumala sa kap-atan ug walo ka priest, ug molingkod sa konseho uban kanila, sa pagtudlo kanila sa mga katungdanan sa ilang buhatan, sama sa gihatag diha sa mga pakigsaad—"},{"verse":88,"text":"Kini nga pangulo mao ang usa ka bishop; kay kini mao ang usa sa mga katungdanan niini nga pagkapari."},{"verse":89,"text":"Usab, ang katungdanan sa pangulo diha sa buhatan sa mga elder mao ang pagdumala sa kasiyaman ug unom ka elder, ug sa paglingkod sa konseho uban kanila, ug sa pagtudlo kanila sumala sa mga pakigsaad."},{"verse":90,"text":"Kini nga kapangulohan lahi kay sa seventy, ug gihatag alang niadtong dili mobiyahe sa tibuok kalibotan."},{"verse":91,"text":"Ug usab, ang katungdanan sa Pangulo sa buhatan sa Labaw nga Pagkapari mao ang pagdumala sa tibuok simbahan, ug aron mahisama kang Moises—"},{"verse":92,"text":"Tan-awa, aniay kaalam; oo, aron mahimo nga usa ka manalagna, usa ka tigpadayag, maghuhubad, ug propeta, nga makaangkon sa tanang gasa sa Dios nga iyang ihatag sa pangulo sa simbahan."},{"verse":93,"text":"Ug sumala kini sa panan-awon nga nagpakita sa kapunongan sa Seventy, nga sila kinahanglan nga adunay pito ka pangulo aron magdumala kanila, nga pilion gikan sa sakop sa seventy;"},{"verse":94,"text":"Ug ang ikapito nga pangulo niini nga mga pangulo mao ang modumala sa unom;"},{"verse":95,"text":"Ug kining pito ka pangulo mao ang mopili sa ubang mga seventy gawas sa una nga seventy diin sila nahisakop, ug modumala kanila;"},{"verse":96,"text":"Ug usab ang lain nga seventy, hangtod ang pito pilo-piloon og kapitoan, kon ang buluhaton sa ubasan nagkinahanglan niini."},{"verse":97,"text":"Ug kini nga mga seventy mao ang tigbiyahe nga mga ministro, una ngadto sa mga Hentil ug usab ngadto sa mga Judeo."},{"verse":98,"text":"Samtang ang ubang mga opisyal sa simbahan, kinsa wala mahisakop sa Napulog Duha, ni ngadto sa Seventy, dili ubos sa katungdanan nga mobiyahe sa tanang nasod, apan mobiyahe kon ang ilang kahimtang motugot, bisan pa makahupot sila og mahinungdanon ug taas og katungdanan nga mga buhatan sa simbahan."},{"verse":99,"text":"Mao nga, pakat-ona ang matag tawo sa iyang katungdanan, ug pabuhata sa gimbuhaton diin siya gipili, sa tanang kakugi."},{"verse":100,"text":"Siya nga tapolan dili isipon nga takos nga mobarog, ug siya nga dili magkat-on sa iyang katungdanan ug magpakita sa iyang kaugalingon nga dili angay dili isipon nga takos nga mobarog. Ug mao gayod kana. Amen."}]},{"chapter":108,"verses":[{"verse":1,"text":"Sa pagkatinuod nagsulti ang Ginoo nganha kanimo, akong sulugoong Lyman: Ang imong mga sala gipasaylo na, tungod kay ikaw nagsunod sa akong tingog nga moanhi niini nga kabuntagon aron modawat og tambag gikan kaniya nga akong gipili."},{"verse":2,"text":"Busa,papahulaya ang imong kalag kalabot sa imong espirituhanong kahimtang, ug ayaw na supaka ang akong tingog."},{"verse":3,"text":"Ug barog ug dugangi ang imong pagmatngon gikan karon sa pagsunod sa imong mga panumpa, nga imong nahimo ug gibuhat, ug mapanalanginan ka og daghan kaayong panalangin."},{"verse":4,"text":"Pagmapailobon sa paghulat hangtod ang maligdong nga katigoman pagahimoon pinaagi sa akong mga sulugoon, dayon ikaw mahinumdoman kauban sa nag-una sa akong mga elder, ug modawat og katungod pinaagi sa pag-orden uban sa nahibilin sa akong mga elder nga akong napili."},{"verse":5,"text":"Tan-awa, mao kini ang saad sa Amahan nganha kanimo kon ikaw mopadayon nga matinud-anon."},{"verse":6,"text":"Ug matuman kini diha kanimo sa adlaw nga ikaw makabaton og katungod sa pagsangyaw sa akong ebanghelyo bisan asa man ako mopadala kanimo, sukad karon ug sukad niana nga higayon."},{"verse":7,"text":"Busa, lig-ona ang imong kaigsoonan sa tanan ninyong panagsultihanay, sa tanan ninyong pag-ampo, sa tanan ninyong pagdasig, ug sa tanan ninyong buhat."},{"verse":8,"text":"Ug tan-awa, ug sud-onga, magauban ako kanimo aron sa pagpanalangin kanimo ug pagpalingkawas kanimo sa kahangtoran. Amen."}]},{"chapter":109,"verses":[{"verse":1,"text":"Salamat sa imong ngalan, O Ginoo nga Dios sa Israel, kinsa nagtuman sa pakigsaad ug nagpakita og kaluoy ngadto sa imong mga sulugoon nga naglakaw sa pagkamatarong sa imong atubangan, sa tibuok nilang kasingkasing—"},{"verse":2,"text":"Ikaw nga nagsugo sa imong mga sulugoon sa pagtukod og balay sa imong ngalan dinhi niini nga dapit [Kirtland]."},{"verse":3,"text":"Ug karon nakita nimo, O Ginoo, nga ang imong mga sulugoon nakahimo sumala sa imong sugo."},{"verse":4,"text":"Ug karon mangayo kami kanimo, Balaan nga Amahan, sa ngalan ni Jesukristo, ang Anak sa imong dughan, kansang ngalan lamang ang kaluwasan ikapangalagad ngadto sa katawhan, mangayo kami kanimo, O Ginoo, nga dawaton kini nga balay, ang binuhat sa among mga kamot, imong mga sulugoon, nga gisugo nimo nga among itukod."},{"verse":5,"text":"Kay ikaw nasayod nga nahimo namo kini nga buhat pinaagi sa dakong kalisdanan; ug gikan sa among kakabos nahatag namo ang among mga kabtangan aron magtukod og balay sa imong ngalan, aron ang Anak sa Tawo adunay dapit diin ikapakita niya ang iyang kaugalingon ngadto sa iyang katawhan."},{"verse":6,"text":"Ug sama sa imong gisulti sa usa ka pagpadayag, nga gihatag ngari kanamo, nagtawag kanamo nga imong mga higala, nga nag-ingon—Ipatawag ang inyong maligdong nga katigoman, sama sa akong gisugo kaninyo;"},{"verse":7,"text":"Ug tungod kay dili ang tanan adunay pagtuo, tinguhaa ninyo pinaagi sa kakugi ug pagtinudloay sa usag usa sa mga pulong sa kaalam; oo, pangitaa gikan sa labing maayong basahon ang mga pulong sa kaalam, tinguhaa ang pagkat-on pinaagi sa pagtuon ug usab pinaagi sa pagtuo;"},{"verse":8,"text":"Ipahimutang ang inyong mga kaugalingon; andama ang tanang panginahanglan, ug pagtukod og balay, gani balay sa pag-ampo, balay sa pagpuasa, balay sa pagtuo, balay sa pagkat-on, balay sa himaya, balay sa kahusay, balay sa Dios;"},{"verse":9,"text":"Aron ang inyong mga pagsulod mahimo pinaagi sa ngalan sa Ginoo, nga ang inyong mga paggawas mahimo unta pinaagi sa ngalan sa Ginoo, nga ang inyong tanang pagpangatahoran mahimo pinaagi sa ngalan sa Ginoo, nga ibayaw ang kamot ngadto sa Labing Halangdon—"},{"verse":10,"text":"Ug karon, Balaan nga Amahan, mohangyo kami kanimo sa pagtabang kanamo, nga imong katawhan, sa imong grasya, sa pagtawag sa among maligdong nga katigoman, aron kini mahimo alang sa imong dungog ug sa imong diosnon nga pagdawat;"},{"verse":11,"text":"Ug sa paagi nga kami makita nga takos, sa imong panan-aw, sa pagseguro sa katumanan sa mga saad nga imong gihimo ngari kanamo, ang imong katawhan, pinaagi sa mga pagpadayag nga gihatag ngari kanamo;"},{"verse":12,"text":"Aron ang imong himaya mokunsad sa imong katawhan, ug dinhi niini nga imong balay, nga karon among ipahinungod kanimo, aron kini mabalaan ug mapahinungod nga mahimong balaan, ug aron ang imong balaanon nga presensya magpadayon dinhi niini nga balay;"},{"verse":13,"text":"Ug aron ang tanang katawhan nga mosulod sa pultahan sa balay sa Ginoo mobati sa imong gahom, ug mobati og tinguha sa pag-ila nga ikaw nagbalaan niini, ug nga kini mao ang imong balay, usa ka dapit sa imong pagkabalaan."},{"verse":14,"text":"Ug imong itugot, Balaan nga Amahan, nga ang tanan nga mosimba dinhi niini nga balay matudloan sa mga pulong sa kaalam gikan sa labing maayong mga basahon, ug nga sila maninguha sa pagkat-on gani pinaagi sa pagtuon, ug usab pinaagi sa pagtuo, sama sa imong gisulti;"},{"verse":15,"text":"Ug nga sila magtubo diha kanimo, ug makadawat og kahingpitan sa Espiritu Santo, ug mahan-ay sumala sa imong mga balaod, ug makaandam sa pag-angkon sa matag gikinahanglan nga butang;"},{"verse":16,"text":"Ug nga kini nga balay mahimong balay sa pag-ampo, balay sa pagpuasa, balay sa pagtuo, balay sa himaya ug sa Dios, gani imong balay;"},{"verse":17,"text":"Nga ang tanang pagsulod sa imong katawhan, ngadto niini nga balay, mahimo pinaagi sa ngalan sa Ginoo;"},{"verse":18,"text":"Nga ang ilang tanang paggawas gikan niini nga balay mahimo pinaagi sa ngalan sa Ginoo;"},{"verse":19,"text":"Ug nga ang ilang tanang pagtahod mahimo pinaagi sa ngalan sa Ginoo, gamit ang balaang mga kamot, nga ibayaw ngadto sa Labing Halangdon;"},{"verse":20,"text":"Ug nga walay mahugaw nga butang nga tugotan sa pagsulod sa imong balay aron sa paghugaw-hugaw niini;"},{"verse":21,"text":"Ug kon ang imong katawhan makalapas, bisan kinsa kanila, sila unta maghinulsol diha-diha dayon ug mobalik kanimo, ug makaangkon og kaluoy sa imong panan-aw, ug mapahiuli ngadto sa mga panalangin nga imong gipagbut-an nga ibu-bo niadtong motahod kanimo diha sa imong balay."},{"verse":22,"text":"Ug mangayo kami kanimo, Balaan nga Amahan, nga ang imong mga sulugoon molakaw gikan niini nga balay inubanan sa imong gahom, ug nga ang imong ngalan maanaa kanila, ug ang imong himaya maglibot kanila, ug ang imong mga anghel magabantay kanila;"},{"verse":23,"text":"Ug gikan niini nga dapit magdala sila og mahinungdanon kaayo ug mahimayaong mga balita, sumala sa kamatuoran, ngadto sa kinatumyan sa yuta, aron masayod sila nga imo kining buhat, ug nga imong gibutang ang imong kamot, aron sa pagtuman sa imong gipamulong pinaagi sa mga ba-ba sa mga propeta, mahitungod sa kataposang mga adlaw."},{"verse":24,"text":"Kami mangayo kanimo, Balaan nga Amahan, nga palig-onon ang katawhan nga mosimba, ug maghupot og madungganon nga ngalan ug katungdanan dinhi sa imong balay, sa tanang henerasyon ug sa kahangtoran;"},{"verse":25,"text":"Aron walay hinagiban nga gihimo batok kanila nga mouswag; aron siya nga magkalot og gahong alang kanila mao ang mahulog ngadto niini;"},{"verse":26,"text":"Aron walay pundok sa mga daotan nga makabaton og gahom sa pag-alsa, ug pagbuntog sa imong katawhan kang kinsa ang imong ngalan maila dinhi niini nga balay;"},{"verse":27,"text":"Ug kon adunay katawhan nga moalsa batok niini nga katawhan, nga ang imong kasuko mapukaw batok kanila;"},{"verse":28,"text":"Ug kon sila mohampak niini nga katawhan ikaw mohampak kanila; ikaw makig-away alang sa imong katawhan sama sa imong gibuhat sa adlaw sa gubat, aron maluwas sila gikan sa mga kamot sa tanan nilang kaaway."},{"verse":29,"text":"Kami mangayo kanimo, Balaan nga Amahan, sa pagpakgang, ug pagpatingala, ug sa pagdala ngadto sa kaulawan ug pagkalibog, sa tanan nga nagsabwag og bakak nga mga balita sa lagyong dapit, sa tibuok kalibotan, batok sa imong sulugoon o mga sulugoon, kon sila dili maghinulsol, sa dihang ang walay kataposan nga ebanghelyo ipadayag sa ilang mga dalunggan;"},{"verse":30,"text":"Ug nga ang ilang tanan nga binuhatan himoon nga walay kapuslanan, ug maanod pinaagi sa unos nga yelo, ug pinaagi sa mga paghukom nga imong ipadala ngadto kanila tungod sa imong kasuko, nga maadunay kataposan ang mga pagpamakak, ug mga pagbutang-butang batok sa imong katawhan."},{"verse":31,"text":"Kay nasayod ka, O Ginoo, nga ang imong mga sulugoon walay sala sa imong atubangan mahitungod sa pagpamatuod sa imong ngalan, nga tungod niini nag-antos sila niining mga butanga."},{"verse":32,"text":"Busa mangamuyo kami sa imong atubangan alang sa tibuok ug hingpit nga pagkaluwas gikan niini nga yugo;"},{"verse":33,"text":"Kuhaa kini, O Ginoo; kuhaa kini gikan sa mga liog sa imong mga sulugoon, pinaagi sa imong gahom, aron kami makabarog sa taliwala niini nga henerasyon ug mobuhat sa imong buhat."},{"verse":34,"text":"O Jehova, kaluy-i kini nga katawhan, ug kay makasala man ang tanang tawo, pasayloa ang mga kalapasan sa imong katawhan, ug papasa kini sa kahangtoran."},{"verse":35,"text":"Iselyo ang pagdihog sa imong mga tigpangalagad diha kanila uban sa gahom gikan sa kahitas-an."},{"verse":36,"text":"Ipatuman kini diha kanila, sama niadtong mga adlaw sa Pagkunsad sa Espiritu Santo; ibu-bo ang gasa sa mga dila ngadto sa imong katawhan, gani ingon sa nagsanga nga mga dila sa kalayo, ug ang paghubad niini."},{"verse":37,"text":"Ug pun-a ang imong balay, sama sa naghaguros nga kusog kaayo nga hangin, sa imong himaya."},{"verse":38,"text":"Ihatag sa imong mga sulugoon ang pagpamatuod sa pakigsaad, nga sa panahon nga molakaw sila ug mopahayag sa imong pulong ilang maselyo ang balaod, ug andamon ang mga kasingkasing sa imong mga santos alang sa tanang paghukom nga hapit na nimo ipadala, tungod sa imong kapungot, sa mga lumulupyo sa yuta, tungod sa ilang mga kalapasan, aron ang imong katawhan dili maluya sa adlaw sa kasamok."},{"verse":39,"text":"Ug ang bisan unsa nga siyudad nga pagasudlan sa imong mga sulugoon, ug ang katawhan niana nga siyudad modawat sa ilang pagpamatuod, ihatag ang imong kalinaw ug ang imong kaluwasan niana nga siyudad; aron pundokon nila gikan niana nga siyudad ang mga matarong, aron moadto sila sa Zion, o sa iyang mga istaka, sa mga dapit nga imong gipili, uban sa mga awit sa walay kataposang kamaya;"},{"verse":40,"text":"Ug hangtod nga kini matuman, ayaw ipadangat ang imong mga paghukom niana nga siyudad."},{"verse":41,"text":"Ug bisan unsa nga siyudad nga pagasudlan sa imong mga sulugoon, ug ang katawhan niana nga siyudad dili modawat sa pagpamatuod sa imong mga sulugoon, ug ang imong mga sulugoon mopasidaan kanila sa pagluwas sa ilang mga kaugalingon gikan niining hiwi nga henerasyon, ipahitabo niana nga siyudad sumala sa imong gipamulong pinaagi sa mga ba-ba sa imong mga propeta."},{"verse":42,"text":"Apan luwasa, O Jehova, nangaliya kami kanimo, ang imong mga sulugoon gikan sa ilang mga kamot, ug limpyohi sila gikan sa ilang dugo."},{"verse":43,"text":"O Ginoo, dili namo ikalipay ang kalaglagan sa among isigkatawo; ang ilang mga kalag bililhon sa imong atubangan;"},{"verse":44,"text":"Apan ang imong pulong kinahanglan nga matuman. Tabangi ang imong mga sulugoon sa pagsulti, pinaagi sa imong grasya nga motabang kanila: Ang imong pagbuot mao ang matuman, O Ginoo, ug dili ang amoa."},{"verse":45,"text":"Nasayod kami nga ikaw namulong pinaagi sa ba-ba sa imong mga propeta sa makalilisang nga mga butang mahitungod sa daotan, sa kataposang mga adlaw—nga ikaw mobu-bo sa imong mga paghukom, nga walay sukod;"},{"verse":46,"text":"Busa, O Ginoo, luwasa ang imong katawhan gikan sa katalagman sa mga daotan; Tugoti ang imong mga sulugoon sa pagselyo sa balaod, ug sa pagbugkos sa pagpamatuod, aron maandam sila batok sa adlaw sa pagsunog."},{"verse":47,"text":"Mohangyo kami kanimo, Balaan nga Amahan, sa paghinumdom niadtong giabog sa mga lumulupyo sa lalawigan sa Jackson, Missouri, gikan sa mga yuta sa ilang kabilin, ug kuhaa, O Ginoo, kini nga yugo sa kasakit nga gisangon diha kanila."},{"verse":48,"text":"Ikaw nasayod, O Ginoo, nga gidaogdaog sila pag-ayo ug gisakit sa daotang mga tawo; ug ang among mga kasingkasing nasobrahan sa kasubo tungod sa ilang bug-at nga mga suliran."},{"verse":49,"text":"O Ginoo, hangtod kanus-a ikaw motugot nga kini nga katawhan mag-antos niini nga kasakit, ug ang mga pag-ampo sa ilang mga walay sala moabot diha sa imong mga dunggan, ug ang ilang dugo motunga isip pagpamatuod sa imong atubangan, ug dili mopakita sa imong pagpamatuod alang sa ilang kaayohan?"},{"verse":50,"text":"Kaluy-i, O Ginoo, ang daotan nga panon sa manggugubot, nga nag-abog sa imong katawhan, nga mohunong sila sa pagpanglungkab, nga maghinulsol sila sa ilang mga sala kon adunay paghinulsol nga makaplagan;"},{"verse":51,"text":"Apan kon dili sila maghinulsol, ipakita ang imong gahom, O Ginoo, ug tubsa kanang imong gipili nga Zion alang sa imong katawhan."},{"verse":52,"text":"Ug kon dili man kini mahitabo, aron ang kawsa sa imong katawhan dili mapakyas sa imong atubangan unta ang imong kasuko mapukaw, ug ang imong kasuko moabot kanila, nga sila malaglag, ang gamot ug sanga, gikan sa ubos sa langit;"},{"verse":53,"text":"Apan kon maghinulsol sila, mabination man ikaw ug magmaluluy-on, ug mopahilayo sa imong kapungot kon ikaw motan-aw sa nawong sa imong mga Dinihogan."},{"verse":54,"text":"Pagmaluluy-on, O Ginoo, sa tanang nasod sa yuta; pagmaluluy-on sa mga magmamando sa among yuta; hinaot nga kanang mga baroganan, nga gipanalipdan sa halangdon ug madungganong paagi, nga gitawag nga, ang Batakang Balaod sa among yuta, pinaagi sa among mga amahan, matukod sa kahangtoran."},{"verse":55,"text":"Hinumdomi ang mga hari, ang mga prinsipe, ang mga halangdon, ug kadtong mga bantogan sa yuta, ug ang tanang katawhan, ug ang mga simbahan, ang tanang mga kabos, ang timawa, ug ang mga sinakit sa yuta;"},{"verse":56,"text":"Nga ang ilang mga kasingkasing mahumok sa panahon nga ang imong mga sulugoon mogula gikan sa imong balay, O Jehova, aron mohatag og pagpamatuod sa imong ngalan; aron ang ilang sayop nga mga paghukom mahanaw sa atubangan sa kamatuoran, ug ang imong katawhan makaangkon og kaluoy sa panan-aw sa tanan;"},{"verse":57,"text":"Nga ang tanang lumulupyo sa yuta masayod nga kami, ang imong mga sulugoon, nakadungog sa imong tingog, ug nga kami imong gipadala;"},{"verse":58,"text":"Nga gikan niining tanan, ang imong mga sulugoon, ang mga anak ni Jacob, mopundok sa mga matarong aron motukod og balaan nga siyudad alang sa imong ngalan, sama sa imong gisugo kanila."},{"verse":59,"text":"Mohangyo kami kanimo sa paghatag sa Zion og ubang mga istaka gawas niini nga imong gihatag, aron ang pagpundok sa imong katawhan magpadayon sa dakong gahom ug kaharianon, nga ang imong buhat mapadali sa pagkamatarong."},{"verse":60,"text":"Karon kini nga mga pulong, O Ginoo, among gipamulong sa imong atubangan, kalabot sa mga pagpadayag ug mga sugo nga imong gihatag kanamo, kinsa giila nga kahabig sa mga Hentil."},{"verse":61,"text":"Apan nasayod ka nga dako ang imong paghigugma sa mga anak ni Jacob, kinsa nagkatibulaag sa mga kabukiran sulod sa dugay nang panahon, sa madag-om ug mangitngit nga adlaw."},{"verse":62,"text":"Busa mohangyo kami nga imong kaluy-an ang mga anak ni Jacob, aron ang Jerusalem, gikan niini nga takna, masugdan sa pagtubos;"},{"verse":63,"text":"Ug ang yugo sa pagkaulipon masugdan sa pagkatangtang gikan sa balay ni David;"},{"verse":64,"text":"Ug ang mga anak ni Judah magsugod sa pagbalik ngadto sa mga yuta nga imong gihatag kang Abraham, nga ilang amahan."},{"verse":65,"text":"Ug ipahitabo nga ang mga salin ni Jacob, kinsa gitunglo ug gihampak tungod sa ilang kalapasan, makabig gikan sa ilang pagkaihalas ug bangis nga kahimtang ngadto sa kahingpitan sa walay kataposang ebanghelyo;"},{"verse":66,"text":"Nga ibutang nila ang ilang mga hinagiban sa pagpaagas og dugo, ug mohunong sa ilang mga pagsukol."},{"verse":67,"text":"Ug unta ang tanan nga nagkatibulaag nga salin sa Israel, kinsa giabog ngadto sa mga kinatumyan sa yuta, makaangkon og kahibalo sa kamatuoran, motuo sa Mesiyas, ug matubos gikan sa pagdaog-daog, ug magmaya sa imong atubangan."},{"verse":68,"text":"O Ginoo, hinumdomi ang imong sulugoon, nga si Joseph Smith, Jun., ug ang tanan niyang mga kasakit ug mga pagpanglutos—kon giunsa niya sa pagpakigsaad kang Jehova, ug miyukbo nganha kanimo, O Makagagahom nga Dios ni Jacob—ug ang mga sugo nga imong gihatag ngadto kaniya, ug nga siya sa tinuod naningkamot sa pagbuhat sa imong kabubut-on."},{"verse":69,"text":"Kaluy-i, O Ginoo, ang iyang asawa ug mga anak, nga mahimaya sila sa imong atubangan, ug mapatunhay pinaagi sa imong maamumahon nga kamot."},{"verse":70,"text":"Kaluy-i ang tanan nilang labing suod nga mga kabanay, aron ang ilang mga pagpangdaot mahunong ug maanod maingon sa baha; nga sila madani ug matubos uban sa Israel, ug masayod nga ikaw ang Dios."},{"verse":71,"text":"Hinumdomi, O Ginoo, ang mga pangulo, gani ang tanang pangulo sa imong simbahan, nga ang imong tuo nga kamot mopahimaya kanila, uban sa tanan nilang mga pamilya, ug sa ilang labing duol nga mga kabanay, aron ang ilang mga ngalan mapadayon ug makaangkon og walay kataposang handomanan gikan sa usa ka henerasyon ngadto sa sunod nga henerasyon."},{"verse":72,"text":"Hinumdomi ang tibuok nimong simbahan, O Ginoo, uban sa tanan nilang mga pamilya, ug sa tanan nilang labing duol nga mga kabanay, uban sa tanan nilang mga masakiton ug kadtong mga sinakit, uban sa tanang kabos ug maaghop sa yuta; aron ang gingharian, nga imong gipabarog nga dili pinaagi sa kamot, mahimong dako nga bukid ug mopuno sa tibuok yuta;"},{"verse":73,"text":"Nga ang imong simbahan mogawas gikan sa kamingawan nga mangitngit, ug mohayag nga matahom sama sa buwan, tin-aw sama sa adlaw, ug makalilisang sama sa kasundalohan nga may dalang mga bandila;"},{"verse":74,"text":"Ug dayandayanan sama sa pangasaw-onon alang niana nga adlaw nga imong ablihan ang tabil sa kalangitan, ug ipaanod ang kabukiran ngadto sa imong atubangan, ug ang mga walog ipataas, ang mga batoon nga dapit mahimong hapsay; nga ang imong himaya mopuno sa yuta;"},{"verse":75,"text":"Nga sa higayon nga ang trumpeta motingog alang sa mga patay, kami pagabayawon sa mga panganod aron sa pagsugat kanimo, aron kami sa kanunay mag-uban sa Ginoo;"},{"verse":76,"text":"Nga ang among mga sapot mahimong putli, nga aron kami pagasul-oban sa mga kupo sa pagkamatarong, nga maggunit og mga palwa sa palmera sa among mga kamot, ug mga korona sa himaya sa among mga ulo, ug moani og walay kataposang kamaya alang sa tanan namong mga pag-antos."},{"verse":77,"text":"O Ginoong Dios nga Labawng Makagagahom, dungga kami niining among mga pangamuyo, ug tubaga kami gikan sa langit, ang imong balaang pinuy-anan, diin ikaw naglingkod sa trono, inubanan sa himaya, dungog, gahom, kaharianon, kusog, kamandoan, kamatuoran, kaangayan, paghukom, kaluoy, ug usa ka walay kataposan nga kahingpitan, gikan sa kahangtoran ngadto sa kahangtoran."},{"verse":78,"text":"O dungga, O dungga, O dungga kami, O Ginoo! Ug tubaga kining mga pangamuyo, ug dawata ang pagpahinungod niini nga balay nganha kanimo, ang buhat sa among mga kamot, nga among gitukod alang sa imong ngalan;"},{"verse":79,"text":"Ug usab kini nga simbahan, aron magdala kini sa imong ngalan. Ug tabangi kami pinaagi sa gahom sa imong Espiritu, nga among isagol ang among mga tingog nianang mahayag, ug masanag nga mga serapin libot sa imong trono, nga nagpasidungog ug nagadayeg, nanag-awit og Hosanna sa Dios ug sa Kordero!"},{"verse":80,"text":"Ug himoa kini, ang imong mga dinihogan, nga masul-oban sa kaluwasan, ug ang imong mga santos mosinggit sa makusog tungod sa kamaya. Amen, ug Amen."}]},{"chapter":110,"verses":[{"verse":1,"text":"Ang tabil gitangtang gikan sa among mga hunahuna, ug ang mga mata sa among panabot naablihan."},{"verse":2,"text":"Among nakita ang Ginoo nga nagbarog sa barandilya sa pulpito, sa among atubangan; ug ubos sa iyang mga tiil mao ang usa ka hinlo nga buhat sa lunsay nga bulawan, nga ang bulok sama sa baga."},{"verse":3,"text":"Ang iyang mga mata sama sa siga sa kalayo; ang buhok sa iyang ulo puti sama sa lunsay nga yelo; ang iyang panagway mihayag labaw sa kahayag sa adlaw; ug ang iyang tingog sama sa dahunog sa dagkong katubigan, gani ang tingog ni Jehova, nga nag-ingon:"},{"verse":4,"text":"Ako ang sinugdanan ug ang kataposan; Ako mao siya nga nabuhi, Ako mao kadtong gipatay; Ako ang inyong manlalaban ngadto sa Amahan."},{"verse":5,"text":"Tan-awa, ang inyong mga sala napasaylo na kaninyo; limpyo na kamo sa akong atubangan; busa, ihangad ang inyong mga ulo, ug pagmaya."},{"verse":6,"text":"Himoa ang mga kasingkasing sa inyong kaigsoonan nga magmaya, ug himoa ang mga kasingkasing sa tanan kong katawhan nga magmaya, kinsa nakahimo, pinaagi sa ilang kusog, sa pagtukod niini nga balay sa akong ngalan."},{"verse":7,"text":"Kay tan-awa, akong gidawat kini nga balay, ug ang akong ngalan maania dinhi; ug akong ipakita ang akong kaugalingon ngadto sa akong katawhan tungod sa kaluoy dinhi niini nga balay."},{"verse":8,"text":"Oo, mopakita ako sa akong mga sulugoon, ug makigsulti kanila sa akong kaugalingong tingog, kon ang akong katawhan maghupot sa akong mga sugo, ug dili maghugawhugaw niining balaan nga balay."},{"verse":9,"text":"Oo ang mga kasingkasing sa mga kaliboan ug tagnapulo ka kaliboan malipay sa hilabihan tungod sa mga panalangin nga ibu-bo, ug sa pagtuga nga gigasa ngadto sa akong mga sulugoon dinhi niini nga balay."},{"verse":10,"text":"Ug ang pagkabantog niini nga balay mokaylap ngadto sa lagyo nga mga yuta; ug kini ang sinugdanan sa panalangin nga ibu-bo diha sa mga ulo sa akong katawhan. Ug mao gayod kana. Amen."},{"verse":11,"text":"Human matapos kini nga panan-awon, ang kalangitan naabli pag-usab ngari kanamo; ug si Moises mipakita sa among atubangan, ug mitugyan kanamo sa mga yawe sa pagpundok sa Israel gikan sa upat ka bahin sa yuta, ug sa pagdala sa napulo ka tribo gikan sa yuta sa amihanan."},{"verse":12,"text":"Human niini, mipakita si Elias, ug mitugyan sa dispensasyon sa ebanghelyo ni Abraham, nagsulti nga, diri kanamo ug sa among binhi ang tanang henerasyon nga mosunod kanamo pagapanalanginan."},{"verse":13,"text":"Sa pagkatapos niini nga panan-awon, lain na usab nga mahinungdanon ug mahimayaong panan-awon ang miabot kanamo; kay si Elijah ang propeta, kinsa gidala ngadto sa langit nga wala makatilaw og kamatayon, nagbarog sa among atubangan, ug miingon:"},{"verse":14,"text":"Tan-awa, ang panahon hingpit nang miabot, nga gipamulong pinaagi sa ba-ba ni Malaquias—nagpamatuod nga siya [si Elijah] ipadala, sa dili pa moabot ang mahinungdanon ug makalilisang nga adlaw sa Ginoo—"},{"verse":15,"text":"Aron ipabalik ang mga kasingkasing sa mga amahan ngadto sa mga anak, ug ang mga anak ngadto sa mga amahan, basin pa unya ang tibuok yuta pagahampakon pinaagi sa tunglo—"},{"verse":16,"text":"Busa, ang mga yawe niini nga dispensasyon gitugyan sa inyong mga kamot; ug pinaagi niini masayod kamo nga ang mahinungdanon ug makalilisang nga adlaw sa Ginoo duol na, gani anaa na sa mga pultahan."}]},{"chapter":111,"verses":[{"verse":1,"text":"Ako, ang Ginoo nga inyong Dios, wala masuko sa inyong pag-abot niini nga pagbiyahe, bisan pa sa inyong mga binuang nga buhat."},{"verse":2,"text":"Ako adunay daghang bahandi niini nga siyudad alang kaninyo, alang sa kaayohan sa Zion, ug daghang mga tawo niini nga siyudad, ang akong pundokon sa tukma nga higayon alang sa kaayohan sa Zion, pinaagi kaninyo."},{"verse":3,"text":"Busa, gikinahanglan nga makighigala kamo sa mga tawo niini nga siyudad, ingon nga kamo pagatudloan, ug kini ihatag kaninyo."},{"verse":4,"text":"Ug mahitabo nga sa tukmang panahon nga akong ihatag kini nga siyudad sa inyong mga kamot, aron kamo adunay gahom niini, nga niana dili sila makahibalo sa inyong tinago nga mga plano; ug ang bahandi niini kalabot sa bulawan ug pilak inyong mapanag-iya."},{"verse":5,"text":"Ayaw kabalaka sa inyong mga kaugalingon mahitungod sa inyong mga utang, kay hatagan ko kamo og gahom nga makabayad niini."},{"verse":6,"text":"Ayaw kabalaka sa inyong mga kaugalingon bahin sa Zion, kay ipakita nako kaniya ang kaluoy."},{"verse":7,"text":"Pabilin niining dapita, ug sa mga rehiyon sa palibot;"},{"verse":8,"text":"Ug sa dapit nga gusto nako nga kamo magpabilin, kay ang kadaghanan, ipakita nganha kaninyo pinaagi sa kalinaw ug gahom sa akong Espiritu, nga moabot kaninyo."},{"verse":9,"text":"Kini nga dapit inyong maangkon pinaagi sa abang. Ug kugihi ang pagpakisayod mahitungod sa labing karaang mga lumulupyo ug mga magtutukod niini nga siyudad;"},{"verse":10,"text":"Kay adunay daghan pang bahandi alang kaninyo niini nga siyudad."},{"verse":11,"text":"Busa, pagmaalamon kamo sama sa mga bitin apan walay sala; ug mandoan nako ang tanang butang alang sa inyong kaayohan, ingon ka paspas kutob sa mahimo ninyong dawaton. Amen."}]},{"chapter":112,"verses":[{"verse":1,"text":"Sa pagkatinuod sa ingon niana miingon ang Ginoo kanimo akong sulugoon nga Thomas: Nakadungog ako sa imong mga pag-ampo; ug ang imong maayo nga mga buhat midangat sa akong atubangan ingon nga usa ka handomanan, alang niadtong, imong kaigsoonan, nga napili sa pagpamatuod sa akong ngalan, ug sa pagdala niini sa layo taliwala sa tanang kanasoran, kaliwatan, pinulongan, ug katawhan, ug i-orden pinaagi sa panabang sa akong mga sulugoon."},{"verse":2,"text":"Sa pagkatinuod sultihan ko ikaw, adunay pipila ka butang sulod sa imong kasingkasing ug diha kanimo nga ako, ang Ginoo, wala kaayo mahimuot."},{"verse":3,"text":"Bisan pa niana, tungod kay ikaw nagpaubos sa imong kaugalingon ikaw pagabayawon; busa, ang imong tanang sala gipasaylo na."},{"verse":4,"text":"Himoa ang imong kasingkasing nga magmalipayon sa akong atubangan; ug ikaw magpamatuod sa akong ngalan, dili lamang ngadto sa mga Hentil, apan usab ngadto sa mga Judeo; ug ikaw mopadangat sa akong pulong ngadto sa mga kinatumyan sa yuta."},{"verse":5,"text":"Busa pakigbisog, sa matag buntag; ug sa matag adlaw ipaabot ang imong tingog sa pasidaan; ug kon moabot na ang kagabhion, ayaw pakatulga ang mga lumulupyo sa yuta, tungod sa imong gipamulong."},{"verse":6,"text":"Ipahibalo ang imong pinuy-anan sa Zion, ug ayaw balhina ang imong balay; kay ako, ang Ginoo, adunay usa ka mahinungdanon nga buluhaton alang kanimo nga imong buhaton, sa pagmantala sa akong ngalan ngadto sa katawhan."},{"verse":7,"text":"Busa, baksi ang imong mga bat-ang alang sa buhat. Sapatosi usab ang imong mga tiil, kay ikaw napili, ug ang imong agianan nahimutang sa mga bukid, ug diha sa daghang nasod."},{"verse":8,"text":"Ug pinaagi sa imong pulong daghang mapahitas-on ang mahimong mapainubsanon, ug pinaagi sa imong pulong daghang mapainubsanon ang pagabayawon."},{"verse":9,"text":"Ang imong tingog mobadlong sa malapason; ug sa imong pagbadlong mahunong ang dila sa mabutang-butangon sa pagkabakakon niini."},{"verse":10,"text":"Pagmapainubsanon; ug ang Ginoo nga imong Dios moagak kanimo pinaagi sa kamot, ug mohatag kanimo og tubag sa imong mga pag-ampo."},{"verse":11,"text":"Nasayod ako sa imong kasingkasing, ug nakadungog sa imong mga pag-ampo mahitungod sa imong kaigsoonan. Kinahanglan nga dili molabaw ang imong paghigugma kanila kay sa uban, apan higugmaa sila sama sa imong kaugalingon; ug higugmaa ang tanang tawo, ug ang tanan nga nahigugma sa akong ngalan."},{"verse":12,"text":"Ug pag-ampo alang sa imong kaigsoonan sa Napulog Duha. Pahimangno-i sila pag-ayo alang ug tungod sa akong ngalan, ug pahimangnoi sila sa ilang tanang sala, ug pagmatinud-anon sa akong atubangan ngadto sa akong ngalan."},{"verse":13,"text":"Ug human sa ilang mga pagsulay, ug daghang kalisdanan, tan-awa ako, ang Ginoo, mopiho sa ilang mga hunahuna, ug kon dili sila magpatig-a sa ilang mga kasingkasing, ug dili mopatikig sa ilang mga liog batok kanako, makabig sila, ug ako moayo kanila."},{"verse":14,"text":"Karon, sultihan ko ikaw, ug unsay akong gisulti kanimo, gisulti nako ngadto sa tanan nga Napulog Duha: Tindog ug baksi ang imong mga hawak, pas-ana ang imong krus, sunod kanako, ug pakan-a ang akong mga karnero."},{"verse":15,"text":"Ayaw himayaa ang inyong mga kaugalingon; ayaw pagsukol sa akong sulugoon nga si Joseph; kay sa pagkatinuod sultihan ko ikaw, ako mag-uban kaniya, ug ang akong kamot anaa sa ibabaw kaniya; ug ang mga yawe nga akong gihatag kaniya, ug usab kaninyo, dili pagakuhaon gikan kaniya hangtod ako moabot."},{"verse":16,"text":"Sa pagkatinuod sultihan ko ikaw akong sulugoon nga Thomas, ikaw ang tawo nga akong gipili nga mohupot sa mga yawe sa akong gingharian, kalabot sa Napulog Duha, sa layo nga mga dapit taliwala sa tanang nasod—"},{"verse":17,"text":"Aron ikaw mahimo nakong sulugoon nga moabli sa ganghaan sa gingharian sa tanang dapit nga dili mahimong adtoon sa akong sulugoon nga si Joseph, ug sa akong sulugoon nga si Sidney, ug sa akong sulugoon nga si Hyrum;"},{"verse":18,"text":"Kay akong gihatag kanila ang palas-anon sa tanang simbahan sulod sa mubo nga panahon."},{"verse":19,"text":"Mao nga, bisan asa ka nila ipadala, moadto ka, ug ako mag-uban kanimo; ug bisan asa nga dapit nga ikaw mopahayag sa akong ngalan usa ka pultahan sa kahigayonan ang pagabuksan nganha kanimo, aron sila makadawat sa akong pulong."},{"verse":20,"text":"Bisan kinsa ang modawat sa akong pulong modawat kanako, ug bisan kinsa ang modawat kanako, modawat kanila, sa Unang Kapangulohan, nga akong gipadala, nga akong gihimo nga mga magtatambag alang ug tungod sa akong ngalan nganha kanimo."},{"verse":21,"text":"Ug usab, sultihan ko ikaw, nga bisan kinsa ang imong ipadala pinaagi sa akong ngalan, pinaagi sa tingog sa imong kaigsoonan, ang Napulog Duha, sa tukmang paagi imong girekomendar ug gitugotan, makabaton og gahom sa pag-abli sa pultahan sa akong gingharian sa bisan asa nga nasod nga sila imong ipadala—"},{"verse":22,"text":"Kon magpaubos sila sa ilang mga kaugalingon sa akong atubangan, ug magpadayon diha sa akong pulong ug mopatalinghog sa tingog sa akong Espiritu."},{"verse":23,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, ang kangitngit motabon sa yuta, ug hilabihan ang kangitngit nga motabon sa mga hunahuna sa katawhan, ug ang tanang tawo mahimong daotan sa akong atubangan."},{"verse":24,"text":"Tan-awa, ang panimalos moabot diha-diha dayon sa mga lumulupyo sa yuta, usa ka adlaw sa kapungot, usa ka adlaw sa pagsunog, usa ka adlaw sa kalaglagan, sa pagdangoyngoy, sa pagbangotan, sa pagbasol; ug sama sa usa ka alimpulos kini moabot diha sa ibabaw sa tibuok yuta, nag-ingon ang Ginoo."},{"verse":25,"text":"Ug sa akong balay kini magsugod, ug gikan sa akong balay kini magpadayon, nag-ingon ang Ginoo;"},{"verse":26,"text":"Mag-una kini taliwala kaninyo, nag-ingon ang Ginoo, kinsa nangangkon nga nakaila sa akong ngalan ug wala makaila kanako, ug nanamastamas batok kanako taliwala sa akong balay, miingon ang Ginoo."},{"verse":27,"text":"Busa, seguroha nga dili ninyo mahasol ang inyong mga kaugalingon mahitungod sa mga kalihokan sa akong simbahan niini nga dapit, nag-ingon ang Ginoo."},{"verse":28,"text":"Apan limpyohi ang inyong mga kasingkasing sa akong atubangan; ug dayon panglakaw kamo ngadto sa tibuok kalibotan, ug isangyaw ang akong ebanghelyo ngadto sa matag linalang kinsa wala makadawat niini;"},{"verse":29,"text":"Ug siya nga motuo ug magpabunyag mao ang maluwas, ug siya nga dili motuo, ug dili magpabunyag, panghimaraoton."},{"verse":30,"text":"Alang kaninyo, ang Napulog Duha, ug kanila, ang Unang Kapangulohan, kinsa natudlo uban kaninyo nga mahimo ninyong mga magtatambag ug inyong mga lider, nga gihatagan niining gahom sa pagkapari, alang sa kataposang mga adlaw ug alang sa kataposang higayon, nga mao ang dispensasyon sa kahingpitan sa mga panahon,"},{"verse":31,"text":"Kansang gahom inyong gihuptan, nga may kalabotan sa tanan niadtong nakadawat og katungdanan sa ebanghelyo sa bisan unsa nga higayon sukad sa sinugdanan sa paglalang;"},{"verse":32,"text":"Kay sa pagkatinuod sultihan ko kamo, ang mga yawe sa dispensasyon, nga inyong nadawat, miabot gikan sa mga amahan, ug sa kataposan sa tanan, gipadala gikan sa langit nganha kaninyo."},{"verse":33,"text":"Sa pagkatinuod sultihan ko kamo, tan-awa pagkamahinungdanon sa inyong katungdanan. Limpyohi ang inyong mga kasingkasing ug ang inyong mga sapot, basin pa unya og ang dugo niini nga henerasyon pangitaon gikan sa inyong mga kamot."},{"verse":34,"text":"Pagmatinud-anon hangtod ako moabot, kay ako moabot og kalit; ug magdala sa akong ganti nga isuhol sa matag tawo sumala sa iyang buhat. Ako mao ang Alpha ug Omega. Amen."}]},{"chapter":113,"verses":[{"verse":1,"text":"Kinsa ang Kaliwat ni Jese nga gihisgotan sa una, ikaduha, ikatulo, ikaupat, ug ikalima nga mga bersikulo sa ikanapulog usa nga kapitulo sa Isaias?"},{"verse":2,"text":"Sa pagkatinuod sa ingon niini misulti ang Ginoo: Kini si Kristo."},{"verse":3,"text":"Unsa ang saha nga gipamulong sa unang bersikulo sa ikapulo og usa nga kapitulo sa Isaias, nga kinahanglan moabot sa Kaliwat ni Jese?"},{"verse":4,"text":"Tan-awa, sa ingon niini miingon ang Ginoo: Mao kini ang usa ka sulugoon ubos sa gahom ni Kristo, kinsa mao ang usa ka bahin sa kaliwat ni Jese ingon usab ni Ephraim, o sa balay ni Jose, kang kinsa adunay gitugyan nga dakong gahom."},{"verse":5,"text":"Unsa ang gamot ni Jese nga gipamulong diha sa ika-10 nga bersikulo sa ika-11 nga kapitulo?"},{"verse":6,"text":"Tan-awa, sa ingon niini miingon ang Ginoo, mao kini ang usa ka kaliwat ni Jese, ingon usab ni Jose, kinsa adunay katungod sa pagkapari, ug sa mga yawe sa gingharian, alang sa usa ka bandila, ug alang sa pagpundok sa akong katawhan sa kataposang mga adlaw."},{"verse":7,"text":"Mga pangutana ni Elias Higbee: Unsa ang buot ipasabot sa sugo diha sa Isaias, ikakalim-an ug duha nga kapitulo, unang bersikulo, nga nag-ingon: Isul-ob ang imong kusog, O Zion—ug kinsa nga katawhan ang gipasabot ni Isaias?"},{"verse":8,"text":"Siya nagpasabot niadtong kinahanglan nga pagatawgon sa Dios sa kataposang mga adlaw, nga kinahanglang maghupot sa gahom sa pagkapari aron sa pagpabalik sa Zion, ug sa katubsanan sa Israel; ug ang pagsul-ob sa iyang kusog mao ang pagsul-ob sa awtoridad sa pagkapari, nga siya, ang Zion, adunay katungod pinaagi sa kaliwatan; usab sa pagpabalik niana nga gahom nga iyang nawala."},{"verse":9,"text":"Unsa ang atong angay nga masabtan sa Zion nga nagbadbad sa iyang kaugalingon gikan sa mga higot sa iyang liog; ikaduha nga bersikulo?"},{"verse":10,"text":"Kinahanglan natong masabtan nga ang mga nagkatibulaag nga salin giawhag sa pagbalik ngadto sa Ginoo gikan sa ilang pagkapukan; nga kon sila mohimo, ang saad sa Ginoo mao nga siya makigsulti kanila, o mohatag kanila og pagpadayag. Tan-awa sa ika-6, ika-7, ug ika-8 nga mga bersikulo. Ang mga higot sa iyang liog mao ang mga tunglo sa Dios nganha kaniya, o ang mga salin sa Israel sa ilang nagkatibulaag nga kahimtang diha sa mga Hentil."}]},{"chapter":114,"verses":[{"verse":1,"text":"Sa pagkatinuod sa ingon niini misulti ang Ginoo: Maalamon alang sa akong sulugoon nga si David W. Patten, nga iyang atimanon dayon ang iyang tanang patigayon kutob sa iyang mahimo, ug ipamaligya ang iyang mga baligya, aron makamisyon siya alang kanako sa sunod nga tingpamulak, kuyog sa uban, gani napulog duha lakip ang iyang kaugalingon, sa pagpamatuod sa akong ngalan ug sa pagdala sa malipayong mga balita ngadto sa tibuok kalibotan."},{"verse":2,"text":"Kay sa pagkatinuod sa ingon niana misulti ang Ginoo, nga kon aduna man kaninyo ang molimod sa akong ngalan, lain ang ibutang sa ilang dapit ug makadawat sa ilang katungdanan. Amen."}]},{"chapter":115,"verses":[{"verse":1,"text":"Sa pagkatinuod kini ang gisulti sa Ginoo kaninyo, akong sulugoon nga Joseph Smith, Jun., ug usab akong sulugoon nga Sidney Rigdon, ug usab akong sulugoon nga Hyrum Smith, ug sa inyong mga magtatambag nga gitudlo karon, ug itudlo human niini;"},{"verse":2,"text":"Ug usab kanimo, akong sulugoong Edward Partridge, ug sa iyang mga magtatambag;"},{"verse":3,"text":"Ug usab sa akong matinud-anong mga sulugoon kinsa anaa sa labaw nga konseho sa akong simbahan diha sa Zion, kay sa ingon niana kini pagatawgon, ug sa tanang elder ug katawhan sa akong Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw, nga nagkatag sa layo nga mga dapit sa tibuok kalibotan;"},{"verse":4,"text":"Kay sa ingon niana ang akong simbahan pagatawgon sa kataposang mga adlaw, gani Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw."},{"verse":5,"text":"Sa pagkatinuod sultihan ko kamong tanan: Barog ug pagmahimong ehemplo, aron ang inyong kahayag mahimong simbolo alang sa mga nasod;"},{"verse":6,"text":"Ug nga ang panagpundok nganha sa yuta sa Zion, ug sa iyang mga stake, alang sa usa ka panalipod, ug alang sa usa ka dangpanan gikan sa unos, ug gikan sa kaligutgot sa higayon nga ibu-bo kini nga walay pagpugong diha sa tibuok yuta."},{"verse":7,"text":"Tugoti ang siyudad, sa Far West, nga mahimong balaan ug gipahinungod nga yuta ngari kanako; ug kini pagatawgon nga labing balaan, kay ang yuta nga inyong gitindogan balaan."},{"verse":8,"text":"Busa, mosugo ako kaninyo sa pagtukod og balay ngari kanako, alang sa pagpundok sa akong mga santos, aron mosimba sila kanako."},{"verse":9,"text":"Ug kinahanglan nga adunay pagsugod niini nga buhat, ug usa ka pundasyon, ug pasiuna nga trabaho niining sunod nga ting-init;"},{"verse":10,"text":"Ug kinahanglan nga adunay pagsugod nga mahimo sa umaabot nga ikaupat nga adlaw sa Hulyo; ug gikan niana nga higayon patrabahoa nga makugihon ang akong katawhan aron sa pagtukod og balay sa akong ngalan;"},{"verse":11,"text":"Ug sulod sa usa ka tuig gikan niining adlawa kinahanglan nga sugdan nila pag-usab ang pagpahimutang sa pundasyon sa akong balay."},{"verse":12,"text":"Sa ingon niana patrabahoa sila nga makugihon gikan nianang higayona hangtod nga mahuman kini, gikan sa tukoran nga bato niini ngadto sa labing ibabaw niana, hangtod nga walay bisan unsa nga butang nga mahibilin nga wala mahuman."},{"verse":13,"text":"Sa pagkatinuod sultihan ko kamo, ayaw itugot nga makautang pa ang akong sulugoon nga si Joseph, ni ang akong sulugoon nga si Sidney, ni ang akong sulugoon nga si Hyrum, tungod sa pagtukod og balay alang sa akong ngalan;"},{"verse":14,"text":"Apan pagtukod og balay alang sa akong ngalan sumala sa sumbanan nga akong ipakita kanila."},{"verse":15,"text":"Ug kon ang akong katawhan motukod niini nga dili subay sa sumbanan nga akong ipakita sa ilang kapangulohan, dili nako kini dawaton gikan sa ilang mga kamot."},{"verse":16,"text":"Apan kon ang akong katawhan motukod niini sumala sa sundanan nga akong ipakita sa ilang kapangulohan, gani ang akong sulugoon nga si Joseph ug ang iyang mga magtatambag, nan dawaton nako kini gikan sa mga kamot sa akong katawhan."},{"verse":17,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, mao kini ang akong kabubut-on nga ang siyudad sa Far West kinahanglan tukoron sa daling panahon pinaagi sa pagpundok sa akong mga santos;"},{"verse":18,"text":"Ug may lain pang mga dapit usab nga kinahanglan itagana alang sa mga stake diha sa mga rehiyon sa palibot, sama sa ipakita ngadto sa akong sulugoon nga si Joseph, matag karon ug unya."},{"verse":19,"text":"Kay tan-awa, ako mag-uban kaniya, ug siya akong balaanon sa atubangan sa katawhan; kay ngadto kaniya akong gihatag ang mga yawe niini nga gingharian ug sa pagpangalagad. Mao gayod kana. Amen."}]},{"chapter":116,"verses":[{"verse":1,"text":"Ang Spring Hill mao ang ginganlan sa Ginoo nga Adam-ondi-Ahman, tungod, kay miingon siya, kini mao ang dapit diin si Adan moduaw sa iyang katawhan, o ang Karaan sa mga Adlaw molingkod, sama sa gipamulong ni Daniel ang propeta."}]},{"chapter":117,"verses":[{"verse":1,"text":"Sa pagkatinuod sa ingon niini misulti ang Ginoo sa akong sulugoon nga si William Marks, ug usab sa akong sulugoon nga si Newel K.Whitney, ipaatiman dayon nila ang ilang patigayon ug pabiyahea gikan sa yuta sa Kirtland, sa dili pa ako, ang Ginoo, mopadala pag-usab og mga yelo diha sa yuta."},{"verse":2,"text":"Pamat-a, ug pabaroga, ug palakta sila ug dili maglangay-langay, kay ako, ang Ginoo, nagsugo niini."},{"verse":3,"text":"Busa, kon maglangay-langay sila dili kini maayo alang kanila."},{"verse":4,"text":"Pahinulsola sila sa ilang tanang sala, ug sa ilang tanang hakog nga mga tinguha, sa akong atubangan, nag-ingon ang Ginoo; kay unsay pulos sa kabtangan ngari kanako? miingon ang Ginoo."},{"verse":5,"text":"Ipabaligya ang mga kabtangan sa Kirtland aron ibayad sa mga utang, miingon ang Ginoo. Ayaw kini ipabilin, miingon ang Ginoo, ug ang bisan unsa ang mahibilin, ipabilin kini diha sa inyong mga kamot, miiingon ang Ginoo."},{"verse":6,"text":"Kay dili ba ako ang tag-iya sa mga langgam sa kalangitan, ug usab sa mga isda sa kadagatan, ug sa mga mananap sa kabukiran? Wala ba nako buhata ang kalibotan? Dili ba ako ang naghupot sa mga kapalaran sa tanang kasundalohan sa mga nasod sa yuta?"},{"verse":7,"text":"Busa, dili ba ako makahimo sa mga mingaw nga dapit sa pagpangudlot ug sa pagpamulak, ug sa pagpamunga og daghan? miingon ang Ginoo."},{"verse":8,"text":"Wala bay igong luna sa kabukiran sa Adam-ondi-Ahman, ug sa kapatagan sa Olaha Shinehah, o sa yuta diin nagpuyo si Adan, nga kaibgan ninyo ang usa lamang ka gamay nga butang, ug taligam-an ang mas mahinungdanong mga butang?"},{"verse":9,"text":"Busa, lakaw ngadto sa yuta sa akong katawhan, gani ang Zion."},{"verse":10,"text":"Sugoa ang akong sulugoon nga si William Marks nga magmatinud-anon sa pipila ka butang, ug siya mahimong tigmando sa daghan. Siya ang magdumala sa taliwala sa akong katawhan sa siyudad sa Far West, ug mapanalanginan siya sa mga panalangin sa akong katawhan."},{"verse":11,"text":"Kinahanglang ikaulaw ni Newel K. Whitney ang pundok sa mga Nicolaitane ug ang ilang tanang tinago nga binuhatan, ug ang ilang tanang kakulang sa pagka-espirituwal sa akong atubangan, miingon ang Ginoo, ug moadto sa yuta sa Adam-ondi-Ahman, ug mahimong usa ka bishop sa akong katawhan, miingon ang Ginoo, dili sa ngalan apan sa buhat, miingon ang Ginoo."},{"verse":12,"text":"Ug usab, sultihan ko kamo, nahinumdom ako sa akong sulugoon nga si Oliver Granger; tan-awa, sa pagkatinuod sultihan ko siya nga ang iyang ngalan pagahinumdoman nga sagrado gikan sa henerasyon ngadto sa henerasyon, hangtod sa kahangtoran, miingon ang Ginoo."},{"verse":13,"text":"Busa, kinahanglan nga maningkamot siya sa pagbayad sa utang sa Unang Kapangulohan sa akong Simbahan, miingon ang Ginoo; ug kon siya mapukan makabangon siya pag-usab, kay ang iyang sakripisyo mas sagrado ngari kanako kay sa iyang paglambo, miingon ang Ginoo."},{"verse":14,"text":"Busa, padalia siya sa pag-adto, sa yuta sa Zion; ug sa tukma nga higayon mahimo siyang usa ka magpapatigayon sa akong ngalan, miingon ang Ginoo, alang sa kaayohan sa akong katawhan."},{"verse":15,"text":"Busa ayaw tugoti nga adunay tawo nga mobiay-biay sa akong sulugoon nga si Oliver Granger, apan madawat niya ang mga panalangin nga nadawat sa akong katawhan hangtod sa kahangtoran."},{"verse":16,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, pahinumdoma sa Ginoo, nga ilang Dios, ang akong tanang sulugoon sa yuta sa Kirtland, ug ang akong balay usab, sa pagbalaan ug pagpatunhay niini, ug sa pagpapahawa sa mga tig-ilis og kwarta sa akong kaugalingong tukma nga panahon, miingon ang Ginoo. Ug mao gayod kana. Amen."}]},{"chapter":118,"verses":[{"verse":1,"text":"Sa pagkatinuod, miingon ang Ginoo: Kinahanglan nga ang usa ka komperensiya ipahigayon dayon; ipaorganisar ang Napulog Duha ug pagpili og mga tawo nga mopuli sa dapit niadtong nakasala."},{"verse":2,"text":"Kinahanglang magpabilin si Thomas sa mubo nga panahon diha sa yuta sa Zion, aron sa pagmantala sa akong pulong."},{"verse":3,"text":"Ipapadayon sa nahibilin ang pagsangyaw gikan niana nga takna, ug kon sila mohimo niini sa tumang pagpaubos sa kasingkasing, sa kaaghop ug pagkamapainubsanon, ug pagkamainantoson, ako, ang Ginoo, mohatag kanila og usa ka saad nga ako mosangkap sa ilang mga pamilya; ug usa ka pultahan sa kahigayonan ang pagaablihan alang kanila, gikan karon."},{"verse":4,"text":"Ug sa sunod nga tingpamulak kinahanglan silang mobiya aron moadto tabok sa lawod, ug didto mopahayag sa akong ebanghelyo, sa kahingpitan niini, ug magpamatuod sa akong ngalan."},{"verse":5,"text":"Kinahanglan nga mobiya sila sa akong mga santos sa siyudad sa Far West, sa ikakawhaan ug unom nga adlaw sa sunod Abril, sa dapit diin tukoron ang akong balay, nag-ingon ang Ginoo."},{"verse":6,"text":"Kinahanglan nga ang akong sulugoon nga si John Taylor, ug usab ang akong sulugoon nga si John E.Page, ug usab ang akong sulugoon nga si Wilford Woodruff, ug usab ang akong sulugoon nga si Willard Richards, matudlo aron mopuli sa mga dapit niadtong nakasala, ug opisyal nga mapahibalo sa ilang pagkatudlo."}]},{"chapter":119,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niini miingon ang Ginoo, gikinahanglan nako ang ilang tanang sobra nga kabtangan nga ihatag ngadto sa mga kamot sa bishop sa akong simbahan sa Zion,"},{"verse":2,"text":"Alang sa pagtukod sa akong balay, ug alang sa pagpahiluna sa pundasyon sa Zion ug alang sa pagkapari, ug alang sa mga utang sa Kapangulohan sa akong Simbahan."},{"verse":3,"text":"Ug kini ang sinugdanan sa ikapulo sa akong katawhan."},{"verse":4,"text":"Ug human niana, kinsa kadtong nagbayad og ikapulo mobayad sa ikanapulo sa ilang tanang tubo sa matag tuig; ug kini mao ang mahangtorong balaod ngadto kanila hangtod sa kahangtoran, alang sa akong balaan nga pagkapari, miingon ang Ginoo."},{"verse":5,"text":"Sa pagkatinuod sultihan ko kamo, mahitabo nga kadtong tanan nga nagpundok sa yuta sa Zion mobayad sa ikapulo sa sobra nilang mga kabtangan, ug mosunod niini nga balaod, o sila dili makita nga takos nga magpabilin uban kaninyo."},{"verse":6,"text":"Ug sultihan ko kamo, kon ang akong katawhan dili mosunod niini nga balaod, sa pagbalaan niini, ug pinaagi niini nga balaod mobalaan sa yuta sa Zion ngari kanako, nga ang akong mga balaod ug ang akong mga paghukom masunod unta, nga kini mahimo nga labing balaan, tan-awa sa pagkatinuod sultihan ko kamo, kini dili mahimo nga usa ka yuta sa Zion nganha kaninyo."},{"verse":7,"text":"Ug mahimo kining panig-ingnan ngadto sa tanang stake sa Zion. Mao gayod kana. Amen."}]},{"chapter":120,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niini miingon ang Ginoo, ang panahon miabot na, nga kini atimanon na sa konseho, nga naglangkob sa Unang Kapangulohan sa akong Simbahan, ug sa bishop ug sa iyang konseho, ug pinaagi sa akong high council; ug pinaagi sa akong kaugalingon nga tingog ngadto kanila, miingon ang Ginoo. Mao gayod kana. Amen."}]},{"chapter":121,"verses":[{"verse":1,"text":"O Dios, hain ka ba? Ug hain ang imong tolda nga nagsalipod sa imong tagoanan?"},{"verse":2,"text":"Hangtod kanus-a nimo gamiton ang imong kamot, ug ang imong mata, oo ang imong matin-aw nga mata, tan-awa gikan sa mahangtorong kalangitan ang mga kawalay kaangayan nga gihimo ngadto sa imong katawhan ug sa imong mga sulugoon, ug ang imong dunggan makadungog sa ilang mga pagtuaw?"},{"verse":3,"text":"Oo, O Ginoo, hangtod kanus-a sila mag-antos niining mga kawalay kaangayan ug dili makataronganong mga pagdaog-daog, ayha pa malukmay ang imong kasingkasing ngadto kanila, ug ang imong kasingkasing mobati og kaluoy ngadto kanila?"},{"verse":4,"text":"O Ginoong Dios nga Labawng Makagagahom, magbubuhat sa langit, sa yuta, ug sa mga dagat, ug sa tanang butang nga anaa niini, ug kinsa nagpugong ug nag-ulipon sa yawa, ug sa kangitngit ug walay paglamdag nga kagamhanan ni Sheol—ilugway ang imong kamot; tugoti nga makakita ang imong mga mata, nga ang imong tolda kuhaon, tugoti nga ang imong tagoanan dili na masalipdan, tugoti nga ang imong dunggan maminaw; nga malukmay na ang imong kasingkasing, ug ang imong kasingkasing mobati og kaluoy ngari kanamo."},{"verse":5,"text":"Tugoti nga mapukaw ang imong kasuko batok sa among mga kaaway, ug sa kaligutgot sa imong kasingkasing, pinaagi sa imong espada ipanimalos kami sa walay kaangayan nga gibuhat ngari kanamo."},{"verse":6,"text":"Hinumdomi ang imong mga santos nga nag-antos, O among Dios; ug ang imong mga sulugoon maglipay sa imong ngalan sa kahangtoran."},{"verse":7,"text":"Akong anak, kalinaw nganha sa imong kalag; ang imong kalisdanan ug ang imong mga kasakitan sulod lamang sa mubo nga higayon;"},{"verse":8,"text":"Ug dayon, kon ikaw molahutay pag-ayo, ang Dios mobayaw kanimo sa kahitas-an; ikaw magmadaogon ibabaw sa imong tanang kaaway."},{"verse":9,"text":"Ang imong mga higala nakig-unong kanimo, ug moyukbo sila kanimo pag-usab uban ang mabinationg mga kasingkasing ug mahigalaong mga kamot."},{"verse":10,"text":"Wala pa ikaw mahisama ni Job; ang imong mga higala wala makigbatok kanimo, ni mipasangil kanimo og kalapasan, sama sa ilang gibuhat ni Job."},{"verse":11,"text":"Ug sila nga nagpasangil kanimo og kalapasan, ang ilang paglaom pagawagtangon, ug ang ilang mga gipaabot mawala sama sa katugnaw nga malanay sa atubangan sa nagsiga nga kasilaw sa nagsaka nga adlaw;"},{"verse":12,"text":"Ug usab nga ang Dios misugod sa paggamit sa iyang kamot ug miselyo aron sa pag-usab sa mga higayon ug mga panahon, ug sa pagbuta sa ilang mga hunahuna, aron dili sila makasabot sa iyang kahibulongang mga buhat; aron siya momatuod usab kanila ug mounay kanila sa ilang kaugalingon nga pagkamalipoton;"},{"verse":13,"text":"Tungod usab kay ang ilang mga kasingkasing mga daotan, ug ang mga butang nga gusto nilang ipatagamtam sa uban, ug mahimuot nga mag-antos ang uban, moabot sa ilang mga kaugalingon sa hilabihan gayod;"},{"verse":14,"text":"Aron usab mapakyas sila, ug ang ilang mga paglaom mahanaw;"},{"verse":15,"text":"Ug dili moabot ang daghang tuig gikan karon, nga sila ug ang ilang mga kaliwat pagalaglagon gikan sa yuta, miingon ang Dios, aron walay usa kanila nga magpabilin nga buhi."},{"verse":16,"text":"Tunglohon silang tanan nga mobatok sa akong dinihogan, miingon ang Ginoo, ug mituaw sila nga nakasala bisan og wala sila makasala sa akong atubangan, miingon ang Ginoo, apan mihimo niana nga matarong sa akong mga panan-aw, ug sa akong gisugo kanila."},{"verse":17,"text":"Apan kinsa kadtong nagpahayag og kalapasan mihimo niini tungod kay sila ang mga sulugoon sa sala, ug sila mismo mga anak sa ilang pagkamasinupakon."},{"verse":18,"text":"Ug niadtong mga nanumpa og bakak batok sa akong mga sulugoon, aron sila ilang madala ngadto sa pagkaulipon ug kamatayon—"},{"verse":19,"text":"Alaot sila; tungod kay ilang gipasakitan ang akong mga sulugoon ipahimulag sila gikan sa mga ordinansa sa akong balay."},{"verse":20,"text":"Ang ilang mga bukag dili mapuno, ang ilang mga balay ug ang ilang mga kamalig mangahanaw, ug sila mismo pagatamayon niadtong nag-ulog-ulog kanila."},{"verse":21,"text":"Sila walay katungod sa pagkapari, ni ang ilang kaliwat nga mosunod kanila gikan sa henerasyon ngadto sa henerasyon."},{"verse":22,"text":"Mas maayo pa alang kanila nga higtan ang ilang mga liog og usa ka bato, ug lumsan sila sa kahiladman sa dagat."},{"verse":23,"text":"Alaot kadtong tanan nga mihatag og kalisdanan sa akong katawhan, ug miabog, ug mipatay, ug mipamatuod batok kanila, miingon ang Ginoo sa mga Panon; ang usa ka henerasyon sa katawhan nga mala-la og dila dili makalingkawas sa silot sa impyerno."},{"verse":24,"text":"Tan-awa, ang akong mga mata nakakita ug nasayod sa ilang tanan nga binuhatan, ug nag-andam ako og hinanali nga paghukom sa panahon niini, alang kanilang tanan;"},{"verse":25,"text":"Kay adunay usa ka panahon nga gitakda alang sa matag tawo, sumala sa iyang mga binuhatan."},{"verse":26,"text":"Ang Dios mohatag kaninyo og kahibalo pinaagi sa iyang Balaan nga Espiritu, oo, pinaagi sa dili mahulagway nga gasa sa Espiritu Santo, nga wala pa gayod mapadayag sukad nalalang ang kalibotan hangtod karon;"},{"verse":27,"text":"Nga gihulat sa atong mga katigulangan uban sa matinguhaong pagpaabot nga ipadayag sa kataposan nga higayon, nga ang ilang mga hunahuna gitumong pinaagi sa mga anghel, nga giandam alang sa kahingpitan sa ilang himaya;"},{"verse":28,"text":"Usa ka higayon ang moabot nga walay itago, kon aduna bay usa ka Dios o daghan nga dios, kini ipadayag."},{"verse":29,"text":"Tanang trono ug mga kamandoan, gagmayng mga gingharian ug mga gahom, ipadayag ug ihatag ngadto sa tanan kinsa makalahutay nga maisogon alang sa ebanghelyo ni Jesukristo."},{"verse":30,"text":"Ug usab, kon adunay mga utlanan nga gipahimutang sa kalangitan, o sa kadagatan, o sa uga nga yuta, o sa adlaw, buwan, o mga bitoon—"},{"verse":31,"text":"Ang tanang panahon sa ilang mga paglibot, ang tanan nga gitakda nga mga adlaw, mga bulan, ug mga tuig, ug ang tanang adlaw sa ilang mga adlaw, mga bulan, ug mga tuig, ug ang ilang tanan nga himaya, mga balaod, ug gikatakda nga panahon, ipadayag sa mga adlaw sa dispensasyon sa kahingpitan sa panahon—"},{"verse":32,"text":"Sumala nianang gi-orden taliwala sa Konseho sa Dios sa Kahangtoran uban sa tanang mga dios sa wala pa ang kalibotan, nga kinahanglan nga itagana hangtod sa pagkahuman ug sa kataposan niini, sa higayon nga ang matag tawo mosulod ngadto sa iyang presensya sa kahangtoran ug ngadto sa iyang imortal nga kapahulayan."},{"verse":33,"text":"Hangtod kanus-a magpabiling hugaw ang nag-agos nga tubig? Unsa nga gahom ang makapugong sa kalangitan? Maayo pa sa tawo nga molugway sa iyang walay kusog nga kamot sa pagpahunong sa sapa sa Missouri sa iyang naandan nga agianan, o sa pagpabalik niini, kay sa pagpugong sa Labawng Makagagahom sa pagbu-bo sa kahibalo gikan sa langit diha sa mga ulo sa mga Santos sa Ulahing mga Adlaw."},{"verse":34,"text":"Tan-awa, adunay daghan nga gitawag, apan pipila lamang ang gipili. Ug ngano nga wala sila mapili?"},{"verse":35,"text":"Tungod kay gipahimutang nila sa hilabihan ang ilang mga kasingkasing diha sa mga butang niini nga kalibotan, ug nagtinguha sa mga pasidungog sa mga tawo, mao nga wala sila makakat-on niining usa ka leksiyon—"},{"verse":36,"text":"Nga ang mga katungod sa pagkapari dili mabulag gikan sa mga gahom sa langit, ug nga ang mga gahom sa langit dili makontrolar ni madumala gawas lamang sa mga baroganan sa pagkamatarong."},{"verse":37,"text":"Tinuod kini, aron ikatugyan kini ngari kanato; apan kon mosulay kita sa pagtabon sa atong mga sala, o sa pagtagbaw sa atong garbo, sa atong walay kapuslanan nga pangandoy, o sa paggamit sa gahom o kamandoan o pagpugos sa mga pagbati sa katawhan, sa bisan unsa nga matang sa pagkadili matarong, tan-awa, ang kalangitan mobiya; ang Espiritu sa Ginoo maguol; ug kon kini mobiya, Amen sa pagkapari o sa awtoridad niana nga tawo."},{"verse":38,"text":"Tan-awa, sa dili pa siya masayod, siya nag-inusara na lamang, sa pagpatid batok sa mga tinalinsang kahoy, sa pagpanggukod sa mga santos, ug pagpakig-away batok sa Dios."},{"verse":39,"text":"Atong nakat-onan pinaagi sa makapasubo nga kasinatian nga mao kini ang kinaiyahan ug pamaagi sa hapit tanang tawo, nga kon makaangkon na sila og gamay nga awtoridad, sama sa ilang gituohan, mosugod dayon sila sa paghimo og dili matarong nga kamandoan."},{"verse":40,"text":"Tungod niini daghan ang gitawag, apan pipila lamang ang gipili."},{"verse":41,"text":"Walay gahom o impluwensya ang makahimo o angay nga magpadayon pinaagi sa hiyas sa pagkapari, gawas lamang sa pagdani, sa pagkamainantoson, sa kalumo ug kaaghop, ug sa tiunay nga paghigugma;"},{"verse":42,"text":"Pinaagi sa pagkamabination, ug lunsay nga kahibalo, nga makapabalaan sa hilabihan sa kalag nga walay pagpakaaron-ingnon, ug walay pagpanglimbong—"},{"verse":43,"text":"Ang tukmang panahon sa pagpanton uban sa tuman nga kahigpit, kon gidasig sa Espiritu Santo; ug dayon human niana magpakita og dugang nga paghigugma ngadto kaniya nga inyong gipanton, basin og siya moisip kaninyo nga iyang kaaway;"},{"verse":44,"text":"Aron masayod siya nga ang inyong pagkamatinud-anon mas lig-on pa kay sa mga higot sa kamatayon."},{"verse":45,"text":"Kinahanglan usab nga ang inyong mga kasingkasing mapuno sa gugma nga putli ngadto sa tanang tawo, ug sa mga sakop sa pagtuo, ug kinahanglan nga ang hiyas modayan-dayan sa inyong mga hunahuna nga walay paghunong; unya ang inyong pagsalig mosamot pagkalig-on sa atubangan sa Dios; ug ang doktrina sa pagkapari motuhop diha sa imong kalag ingon sa mga yamog nga gikan sa langit."},{"verse":46,"text":"Ang Espiritu Santo mao ang inyong kauban sa kanunay, ug ang inyong awtoridad usa ka walay pagkausab nga awtoridad sa pagkamatarong ug kamatuoran; ug ang inyong kamandoan mao ang usa ka walay kataposan nga kamandoan, ug walay pagpamugos nga kini moabot nganha kaninyo hangtod sa kahangtoran."}]},{"chapter":122,"verses":[{"verse":1,"text":"Ang lumulupyo sa yuta magpakisayod sa imong ngalan, ug ang mga buangon mobiay-biay kanimo; ug ang impyerno makig-away batok kanimo."},{"verse":2,"text":"Samtang ang putli og kasingkasing, ug ang maalamon, ug ang bantogan, ug ang maligdong, mangayo og tambag, ug awtoridad, ug mga panalangin gikan sa imong kamot sa kanunay."},{"verse":3,"text":"Ug ang imong katawhan dili gayod motalikod batok kanimo pinaagi sa pagpamatuod sa mga mabudhion."},{"verse":4,"text":"Ug bisan kon ang ilang impluwensya modala kanimo ngadto sa kasamok, ug ngadto sa bilanggoan, ikaw pagapasidunggan; ug apan sa mubo nga higayon lang, ug ang imong tingog labaw pa nga makalilisang diha sa taliwala sa imong mga kaaway kay sa mabangis nga leon, tungod sa imong pagkamatarong; ug ang imong Dios moabag kanimo hangtod sa kahangtoran."},{"verse":5,"text":"Kon ikaw gitawag sa pagsugakod sa mga kalisdanan; kon ikaw nameligro taliwala sa mga igsoon nga bakakon; kon ikaw nameligro taliwala sa mga kawatan; kon ikaw nameligro diha sa yuta o sa dagat;"},{"verse":6,"text":"Kon ikaw gipasanginlan sa tanang matang sa mga bakak nga pasangil; kon ang imong mga kaaway mosulong kanimo; kon sila mopahilayo kanimo gikan sa kapunongan sa imong amahan ug inahan ug mga igsoon nga lalaki ug mga babaye; ug kon pinaagi sa usa ka hinulbot nga espada ang imong mga kaaway mopahilayo kanimo gikan sa sabakan sa imong asawa, ug sa imong kaliwat, ug ang imong kinamagulangang anak nga lalaki, bisan og unom pa ka tuig ang panuigon, mokapyot sa imong mga sapot, ug moingon, Akong amahan, akong amahan, ngano nga dili ka magpabilin uban kanamo? O, akong amahan, unsa ang buhaton sa mga tawo kanimo? ug kon siya itulod pahilayo kanimo gamit ang espada, ug ikaw maguroy ngadto sa bilanggoan, ug ang imong mga kaaway magtinguha kanimo sama sa mga lobo nga gustong mopatay sa karnero;"},{"verse":7,"text":"Ug kon ikaw ihulog ngadto sa lungag, o ngadto sa mga kamot sa mga mamumuno, ug ang silot sa kamatayon ipahamtang diha kanimo; kon ikaw itambog ngadto sa ilawom; kon ang dagkong mga balod nagkunsabo batok kanimo; kon ang mapintas nga mga hangin mahimo nimong kaaway; kon ang mga langit mopundok og kangitngit, ug ang tanang elemento magkahiusa nga mobabag sa agianan; ug labaw sa tanan, kon ang mga apapangig sa impyerno mobuka ug moabli sa ba-ba og dako diha kanimo, ikaw masayod, akong anak, nga kining tanan nga butang makahatag kanimo og kasinatian, ug alang sa imong kaayohan."},{"verse":8,"text":"Ang Anak sa Tawo mikunsad ubos kanilang tanan. Labaw pa ba ikaw kay kaniya?"},{"verse":9,"text":"Busa, padayon sa imong pamaagi, ug ang gahom sa pagkapari magpabilin uban kanimo; kay ang ilang mga utlanan gitakda na, dili sila makaagi. Ang imong mga adlaw nahibaloan, ug ang imong mga tuig dili makulangan; busa, ayaw kahadlok sa unsay mahimo sa tawo, kay ang Dios magauban kanimo hangtod sa kahangtoran."}]},{"chapter":123,"verses":[{"verse":1,"text":"Ug usab, mosugyot kami alang sa inyong konsiderasyon kon angay ba sa tanang santos nga mopundok og kasayoran sa tanang importante nga impormasyon sa nahitabo, ug sa mga pag-antos ug mga pang-abuso nga gipahamtang kanila sa katawhan niini nga Estado;"},{"verse":2,"text":"Ug usab sa tanan nga kabtangan ug kantidad sa mga kadaot nga ilang nahiagoman, sa dungog ug sa personal nga mga kadaot, ingon man usab sa balay ug yuta."},{"verse":3,"text":"Ug usab ang mga ngalan sa tanang tawo nga may kalabotan sa pagpanglupig, kutob sa ilang mahibaloan ug makita."},{"verse":4,"text":"Ug tingali usa ka komitiba ang mahimong sangonan sa pagsusi niini nga mga butang, ug aron pagkuha ug mga pamahayag ug mga gipanumpaan nga kalig-onan; ug usab sa pagpundok sa makauulaw nga mga pamahayag nga gihungihong;"},{"verse":5,"text":"Ug ang tanan nga anaa sa mga magasin, ug sa mga ensayklopedya, ug ang tanan nga makauulaw nga kasaysayan nga gimantala, ug mga sinulat, ug pinaagi kaniya, ug ipakita ang kinatibuk-ang sunod-sunod nga yawan-ong mga buhat ug pagkadaotan ug sa gihimong mga pagpatay nga maoy naandan niini nga katawhan—"},{"verse":6,"text":"Nga dili kay imantala lang namo ngadto sa tibuok kalibotan, apan ipakita kini ngadto sa mga pangulo sa panggamhanan sa ilang tanan nga daotan ug yawan-ong tinguha, isip ang kataposang paningkamot nga mao ang gikinahanglan gikan kanato sa atong Langitnong Amahan, sa dili pa kita sa kinatibuk-an ug sa hingpit makaangkon niana nga saad nga magtawag kaniya gikan sa iyang tagoanan nga dapit; ug usab aron ang tibuok nasod walay ikabalibad sa dili pa siya mopadala sa gahom sa iyang gamhanan nga bukton."},{"verse":7,"text":"Mao kini ang usa ka dili malikayan nga katungdanan nga utang nato sa Dios, sa mga anghel, kang kinsa kita pagadad-on aron mobarog, ug usab sa atong mga kaugalingon, sa atong mga asawa ug mga anak, nga nag-antos sa kaguol, kasakit, ug kabalaka, ubos sa labing daotan nga kamot sa pagpatay, pagpanlupig, ug pagpangdaog-daog, nga gisuportahan ug giawhag ug gituboy pinaagi sa impluwensya niana nga espiritu nga nakagamot pag-ayo sa mga tinuohan sa mga amahan, nga nagbilin og mga bakak, diha sa mga kasingkasing sa mga anak, ug mipuno sa kalibotan sa kalibog, ug nag-anam og kalig-on, ug karon mao ang tinubdan sa tanang pagkadaotan, ug ang tibuok yuta nag-agulo nga nagpas-an sa kabug-at sa pagkadaotan niini."},{"verse":8,"text":"Kini mao ang puthaw nga yugo, lig-on kini nga higot; mao kini ang mga posas ug mga kadena, ug mga talikala, ug mga higot sa impyerno."},{"verse":9,"text":"Busa mao kini ang dili malikayan nga katungdanan nga atong nautang, dili lamang sa atong kaugalingong mga asawa ug mga anak, apan sa mga biyuda ug sa walay mga amahan, kansang mga bana ug mga amahan gipamatay ubos sa puthaw nga kamot;"},{"verse":10,"text":"Diin ang kangitngit ug itom nga mga binuhatan igo na aron makapakurog sa impyerno, ug makapabarog nga nahadlok ug nangluspad, ug ang mga kamot sa mao nga yawa mokuray ug mangurog."},{"verse":11,"text":"Ug usab mao kini ang dili malikayan nga katungdanan nga atong nautang sa tanan nga nagtubo nga henerasyon, ug sa tanan nga putli og kasingkasing—"},{"verse":12,"text":"Kay aduna pay daghan sa ibabaw sa yuta sa tanang tinuohan, mga pundok, ug mga pundok sa relihiyon, nga nabutaan sa malipoton nga paglingla sa mga tawo, diin sila naghulat aron makapangilad, ug kinsa natago gikan sa kamatuoran tungod kay wala sila masayod asa kini pangitaa—"},{"verse":13,"text":"Busa, kinahanglan nga kita mohalad ug motugyan sa atong kinabuhi sa pagpadayag sa tanang tinago nga butang sa kangitngit, nga atong nahibaloan; ug kini sa pagkatinuod gipadayag gikan sa langit—"},{"verse":14,"text":"Kinahanglan nga atimanon kini uban sa dakong kakugi."},{"verse":15,"text":"Ayaw itugot nga dunay tawo nga moisip niini nga walay hinungdan nga mga butang; kay aduna pay daghan nga umaabot, kalabot sa mga santos, nga nagsalig niining mga butanga."},{"verse":16,"text":"Nasayod kamo, kaigsoonan, nga ang dako kaayo nga barko matabangan gayod sa usa ka gamay kaayo nga timon sa panahon sa unos, pinaagi sa pagpaubay-ubay sa hangin ug sa mga balod."},{"verse":17,"text":"Busa, minahal nga kaigsoonan, maglipay kita nga mobuhat sa tanang butang nga anaa sa atong gahom; ug dayon kita magmalinawon, uban ang labing dako nga kaseguroan, nga makasaksi sa kaluwasan sa Dios, ug aron ang iyang mga bukton ipadayag."}]},{"chapter":124,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niini nagsulti ang Ginoo nganha kanimo, akong sulugoong Joseph Smith, ako nahimuot kaayo sa imong halad ug mga sakripisyo, nga imong gihimo; tungod niini nga katuyoan ako mipabayaw kanimo, aron ako makapakita sa akong kaalam pinaagi sa huyang nga mga butang sa yuta."},{"verse":2,"text":"Ang imong mga pag-ampo angayan nga akong dawaton; ug agi og tubag niini sultihan ko ikaw, nga ikaw karon dayon gitawag sa paghimo og usa ka ligdong nga pamahayag sa akong ebanghelyo, ug niini nga stake nga akong gitukod aron mahimong tukoranan nga bato sa Zion, nga pahamison sa kaanindot nga sama sa usa ka palasyo."},{"verse":3,"text":"Kini nga pamahayag pagabuhaton ngadto sa tanang hari sa kalibotan, ngadto sa upat ka suok niini, ngadto sa talahoron nga napili nga presidente, ug halangdon nga mga gobernador sa nasod nga imong gipuy-an, ug ngadto sa tanang nasod sa yuta nga nagkatibulaag sa langyaw nga mga dapit."},{"verse":4,"text":"Ipasulat kini pinaagi sa espiritu sa kaaghop ug pinaagi sa gahom sa Espiritu Santo, nga maanaa kanimo sa panahon sa pagsulat niini;"},{"verse":5,"text":"Kay ihatag kini kanimo sa Espiritu Santo aron mahibaloan ang akong kabubut-on mahitungod niana nga mga hari ug mga opisyal, bisan og unsa ang mahitabo kanila sa panahon nga moabot."},{"verse":6,"text":"Kay, tan-awa, hapit na ako motawag kanila sa pagsunod sa kahayag ug himaya sa Zion, kay ang gitakda nga panahon sa pagbulig kaniya og kaluoy miabot na."},{"verse":7,"text":"Busa, tawaga sila sa makusog nga pamahayag, ug pinaagi sa imong pagpamatuod, dili mahadlok kanila, kay sama sila sa sagbot, ug ang ilang tanang himaya sama sa bulak niini nga sa dili madugay mangalarag, nga sila usab walay ikapangatarongan—"},{"verse":8,"text":"Ug aron moduaw ako kanila sa adlaw sa pagduaw, nga akong ablihan ang tabil sa akong nawong, aron hatagan og dapit ang malupigon kauban sa mga hipokrito, diin adunay pagpangagot sa ngipon, kon isalikway nila ang akong mga sulugoon, ug ang akong pagpamatuod nga akong gipadayag ngadto kanila."},{"verse":9,"text":"Ug usab, moduaw ako ug pahumokon ang ilang mga kasingkasing, ang daghan kanila alang sa inyong kaayohan, aron makaangkon kamo og pagtahod sa ilang mga mata, aron moadto sila sa kahayag sa kamatuoran, ug ang mga Hentil ngadto sa kahimayaan o sa pagtuboy sa Zion."},{"verse":10,"text":"Kay ang adlaw sa akong pagduaw moabot sa labing madali, sa takna nga dili kamo magdahom; ug hain ang luwas nga dapit sa akong katawhan, ug ang kadangpan alang sa mahibilin kanila?"},{"verse":11,"text":"Pagmata, O mga hari sa yuta! Duol kamo, O, duol kamo, dala ang inyong bulawan ug ang inyong pilak, aron itabang sa akong katawhan, ngadto sa balay sa mga anak nga babaye sa Zion."},{"verse":12,"text":"Ug usab, sa pagkatinuod sultihan ko ikaw, patabanga ang akong sulugoon nga si Robert B. Thompson kanimo sa pagsulat niini nga pamahayag, kay nahimuot kaayo ako kaniya, ug nga siya magauban kanimo;"},{"verse":13,"text":"Busa, sugoa siya, sa pagpatalinghog sa imong tambag, ug ako mopanalangin kaniya og daghan kaayong panalangin; sugoa siya nga magmatinud-anon ug magmatinuoron sa tanang butang gikan karon, ug mahimo siyang halangdon sa akong mga mata;"},{"verse":14,"text":"Apan ipahinumdom kaniya nga ang iyang pagkatinugyanan akong gikinahanglan sa iyang mga kamot."},{"verse":15,"text":"Ug usab, sa pagkatinuod sultihan ko ikaw, bulahan ang akong sulugoon nga si Hyrum Smith; kay ako, ang Ginoo, nahigugma kaniya tungod sa kaligdong sa iyang kasingkasing, ug tungod kay gihigugma niya kanang matarong sa akong atubangan, miingon ang Ginoo."},{"verse":16,"text":"Usab, patabanga ang akong sulugoon nga si John C. Bennett kanimo sa imong paghago sa pagpadala sa akong pulong ngadto sa mga hari ug katawhan sa yuta, ug mosuporta kanimo, gani ikaw nga akong sulugoong Joseph Smith, sa takna sa kasakit; ug ang iyang ganti dili mapakyas kon siya modawat og tambag."},{"verse":17,"text":"Ug tungod sa iyang gugma mabantog siya, kay maako siya kon mobuhat siya niini, miingon ang Ginoo. Akong nakita ang buhat nga iyang nahimo, nga akong dawaton kon mopadayon siya, ug mokorona kaniya og mga panalangin ug dakong himaya."},{"verse":18,"text":"Ug usab, sultihan ko ikaw nga maoy akong kabubut-on nga ang akong sulugoon nga si Lyman Wight magpadayon sa pagsangyaw alang sa Zion, sa espiritu sa kaaghop, moangkon kanako atubangan sa kalibotan; ug dad-on ko siya pataas sama nga anaa ibabaw sa mga pako sa mga agila; ug makaangkon siya og himaya ug dungog sa iyang kaugalingon ug alang sa akong ngalan."},{"verse":19,"text":"Nga kon matapos na niya ang iyang buluhaton dawaton ko siya sa akong kaugalingon, gani sama sa akong gibuhat sa akong sulugoon nga si David Patten, kinsa ania uban kanako niining higayona, ug usab sa akong sulugoon nga si Edward Partridge, ug usab sa akong tigulang nga sulugoon nga si Joseph Smith, Sen., kinsa naglingkod uban ni Abraham sa iyang tuo nga kamot, ug bulahan ug balaan siya, kay akô man siya."},{"verse":20,"text":"Ug usab, sa pagkatinuod sultihan ko ikaw, nga ang akong sulugoon nga si George Miller dili malimbongon; masaligan siya tungod sa kaligdong sa iyang kasingkasing; ug tungod sa iyang gugma sa akong pagpamatuod ako, ang Ginoo, nahigugma kaniya."},{"verse":21,"text":"Busa sultihan ko ikaw, akong giselyo sa iyang ulo ang katungdanan sa bishopric, sama sa akong sulugoon nga si Edward Partridge, aron madawat niya ang mga pagpahinungod sa akong balay, aron makahatag siya og mga panalangin sa mga ulo sa mga kabos sa akong katawhan, miingon ang Ginoo. Ayaw ipabiay-biay ni bisan kinsang tawo ang akong sulugoon nga si George, kay mopasidungog siya kanako."},{"verse":22,"text":"Ang akong sulugoon nga si George, ug ang akong sulugoon nga si Lyman, ug ang akong sulugoon nga si John Snider, ug uban pa, patukora og balay alang sa akong ngalan, sama sa ipakita sa akong sulugoon nga si Joseph ngadto kanila, sa dapit nga ipakita usab niya kanila."},{"verse":23,"text":"Ug himoon kini nga balay sak-anan, balay nga aron adunay kasak-an ang tagalagyo nga mga dayo; busa himoa kining maayo nga balay, angay nga dawaton, aron ang gikapoy nga mga tigbiyahe makakaplag og kapahulayan ug luwas nga dapit samtang mamalandong siya sa pulong sa Ginoo; ug sa tukoranan nga bato nga akong gipili alang sa Zion."},{"verse":24,"text":"Kini nga balay mahimong maayo nga puy-anan kon itukod kini alang sa akong ngalan, ug kon ang tigdumala nga pilion alang niini dili motugot sa bisan unsang kahugawan nga mahitabo dinhi niini. Mamahimo kining balaan, o ang Ginoo nga imong Dios dili mopuyo niini."},{"verse":25,"text":"Ug usab, sa pagkatinuod sultihan ko ikaw, paanhia ang tanang santos gikan sa layo."},{"verse":26,"text":"Ug pagpadala og abtik nga mga sinugo, oo, pinili nga mga sinugo, ug sultihi sila nga: Panganhi kamo, dala ang inyong tanan nga bulawan, ug inyong pilak, ug inyong mahalon nga mga bato, ug dala ang inyong tanan nga karaang mga butang; ug ang tanan nga adunay kasayoran sa karaang mga butang, nga moanhi, mahimo nga moanhi, ug modala og sipre nga kahoy, ug palatano nga kahoy, ug maribuhok nga kahoy, uban sa tanang mahalon nga mga kahoy sa yuta;"},{"verse":27,"text":"Ug magdala og puthaw, magdala og tumbaga, ug magdala og bronse, ug magdala og sin, ug magdala sa tanan ninyong mahalon nga mga butang sa yuta; ug magtukod og balay alang sa akong ngalan, kay ang Labing Halangdon mopuyo diha niini."},{"verse":28,"text":"Kay walay dapit diha sa yuta nga iyang kaadtoan ug ipahiuli na usab ang nawala nganha kaninyo, o kadtong iyang gikuha, gani ang kahingpitan sa pagkapari."},{"verse":29,"text":"Kay walay bunyaganan diha sa yuta, aron sila, ang akong mga santos, mabunyagan alang niadtong nangamatay na—"},{"verse":30,"text":"Kay kini nga ordinansa ipahigayon sulod sa akong balay, ug dili nako mahimong dawaton, gawas lamang sa mga adlaw sa inyong kakabos, diin kamo dili makatukod og balay alang kanako."},{"verse":31,"text":"Apan mandoan ko kamo, kamong tanan nga akong mga santos, sa pagtukod og balay alang kanako; ug mohatag ako kaninyo og igong panahon sa pagtukod og balay alang kanako; ug sa sulod niini nga panahon ang inyong mga pagbunyag akong pagadawaton."},{"verse":32,"text":"Apan tan-awa, pagkahuman niining gitakda nga panahon ang inyong mga pagbunyag alang sa inyong mga patay dili ko na pagadawaton; ug kon dili ninyo buhaton kining mga butanga sa kataposan sa gitakda nga panahon isalikway kamo isip usa ka simbahan, uban sa inyong mga patay, miingon ang Ginoo nga inyong Dios."},{"verse":33,"text":"Kay sa pagkatinuod sultihan ko kamo, nga human kamo makagahin og igong panahon sa pagtukod og balay alang kanako, kon diin ang ordinansa sa pagbunyag alang sa mga patay pagahimoon, ug alang niana gisugdan kini sa wala pa ang katukoran sa kalibotan, ang inyong mga pagbunyag alang sa inyong mga patay dili ko na mahimong dawaton;"},{"verse":34,"text":"Kay diha sa sulod niini ang mga yawe sa balaang pagkapari giordina, aron makadawat kamo og dungog ug himaya."},{"verse":35,"text":"Ug human niini nga panahon, ang inyong mga pagbunyag alang sa mga patay, pinaagi niadtong nagkatibulaag sa layo nga mga dapit, dili ko madawat, miingon ang Ginoo."},{"verse":36,"text":"Kay giordina kini nga sa Zion, ug sa iyang mga stake, ug sa Jerusalem, kanang mga dapit nga akong gipili aron mahimong dalangpan, mahimong mga dapit alang sa inyong mga pagbunyag alang sa inyong mga patay."},{"verse":37,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, sa unsang paagi nga ang inyong mga paghugas akong madawat, gawas kon ipahigayon ninyo kini sa balay nga inyong gitukod sa akong ngalan?"},{"verse":38,"text":"Kay, tungod niini nga hinungdan mimando ako kang Moises nga kinahanglan magtukod siya og tabernakulo, nga dad-on nila kini sa kamingawan, ug magtukod og balay didto sa yutang saad, aron mapadayag kadto nga mga ordinansa nga gitago sa wala pa ang kalibotan."},{"verse":39,"text":"Busa, sa pagkatinuod sultihan ko kamo, aron ang inyong mga pagdihog, ug ang inyong mga paghugas, ug ang inyong mga pagbunyag alang sa mga patay, ug ang inyong sagradong mga panagtigom, ug ang inyong mga handomanan sa inyong mga sakripisyo pinaagi sa mga anak ni Levi, ug alang sa inyong mga orakulo sa inyong labing balaan nga mga dapit diin makadawat kamo sa mga pagpakigsulti, ug ang inyong mga balaod ug mga paghukom, alang sa sinugdanan sa mga pagpadayag ug katukoran sa Zion, ug alang sa himaya, dungog, ug pagtuga sa tanan niya nga lumulupyo, gi-orden pinaagi sa ordinansa sa akong balaan nga balay, kon diin ang akong katawhan gisugo sa kanunay nga magtukod alang sa akong balaan nga ngalan."},{"verse":40,"text":"Ug sa pagkatinuod sultihan ko kamo, itukod kini nga balay alang sa akong ngalan, aron akong ipadayag ang akong mga ordinansa diha niini alang sa akong katawhan;"},{"verse":41,"text":"Kay akong giisip nga tukma ang pagpadayag ngadto sa akong simbahan sa mga butang nga dugay nang gitago sukad pa sa pagtukod sa kalibotan, mga butang nga mahitungod sa dispensasyon sa kahingpitan sa panahon."},{"verse":42,"text":"Ug akong ipakita sa akong sulugoon nga si Joseph ang tanang butang kalabot niini nga balay, ug ang pagkapari niini, ug ang dapit diin kini kinahanglan nga itukod."},{"verse":43,"text":"Ug itukod ninyo kini sa dapit kon diin inyong gilaraw nga itukod kini, kay mao kana ang luna nga akong gipili alang kaninyo aron matukod kini."},{"verse":44,"text":"Kon maghago kamo sa tibuok ninyong kusog, akong ipahinungod kana nga luna nga kini mahimo nga balaan."},{"verse":45,"text":"Ug kon ang akong katawhan mopatalinghog sa akong tingog, ug sa tingog sa akong mga sulugoon kinsa akong pilion nga mangulo sa akong katawhan, tan-awa, sa pagkatinuod sultihan ko kamo, dili sila mapapahawa sa ilang dapit."},{"verse":46,"text":"Apan kon dili sila mopatalinghog sa akong tingog, ni sa tingog niining mga tawo nga akong gipili, dili sila mapanalanginan, kay gihugawan nila ang akong balaang mga nataran, ug ang akong balaang mga ordinansa, ug mga pamalaod, ug ang akong balaang mga pulong nga akong gihatag ngadto kanila."},{"verse":47,"text":"Ug mahitabo nga kon magtukod kamo og balay sa akong ngalan, ug dili mohimo sa mga butang nga akong isulti, ako dili motuman sa panumpa nga akong gihimo alang kaninyo, ni motuman sa mga saad nga inyong gilaoman gikan sa akong mga kamot, miingon ang Ginoo."},{"verse":48,"text":"Kay imbis nga mga panalangin, kamo, pinaagi sa inyong kaugalingong mga buhat, magdala og mga tunglo, kapungot, kasuko, ug mga paghukom diha sa inyong kaugalingong mga ulo, pinaagi sa inyong mga kabuang, ug sa inyong tanang salawayon nga buhat, nga inyong gipakita sa akong atubangan, miingon ang Ginoo."},{"verse":49,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, nga kon ako mohatag og sugo ngadto ni bisan kinsa nga mga anak sa mga tawo sa paghimo og buhat alang sa akong ngalan, ug kana nga mga anak sa mga tawo molihok sa tibuok nilang kusog ug sa tanan nga anaa kanila sa paghimo niana nga buluhaton, ug dili mohunong sa ilang kakugi, ug ang ilang mga kaaway mosulong kanila ug mopugong kanila sa paghimo niana nga buhat, tan-awa, akong kabubut-on nga dili na mangayo niana nga buhat gikan sa mga kamot sa mga anak sa tawo, hinuon dawaton ang ilang mga halad."},{"verse":50,"text":"Ug ang pagkadaotan ug paglapas sa akong balaan nga mga balaod ug mga sugo akong ipahamtang sa mga ulo niadtong mipugong sa akong buhat, ngadto sa ikatulo ug ikaupat nga henerasyon, samtang dili sila maghinulsol, ug masilag kanako, miingon ang Ginoong Dios."},{"verse":51,"text":"Busa, tungod niini nga hinungdan akong gidawat ang mga halad niadtong akong gisugo sa pagtukod og siyudad ug balay alang sa akong ngalan, sa lalawigan sa Jackson, Missouri, ug napugngan sa ilang mga kaaway, miingon ang Ginoo nga inyong Dios."},{"verse":52,"text":"Ug akong tubagon og paghukom, kapungot, kasuko, pagdanguyngoy, kaguol, ug pangagot sa ngipon sa ilang mga ulo, ngadto sa ikatulo ug ikaupat nga henerasyon, samtang dili sila maghinulsol, ug masilag kanako, miingon ang Ginoo nga inyong Dios."},{"verse":53,"text":"Ug kini akong himoon nga panig-ingnan alang kaninyo, alang sa inyong kahupayan mahitungod sa tanan nga gisugo sa paghimo og usa ka buluhaton ug napugngan sa mga kamot sa ilang mga kaaway, ug pinaagi sa pagpanglupig, miingon ang Ginoo nga inyong Dios."},{"verse":54,"text":"Kay ako ang Ginoo nga inyong Dios, ug moluwas sa tanan nga inyong kaigsoonan nga mga putli og kasingkasing, ug gipamatay didto sa yuta sa Missouri, miingon ang Ginoo."},{"verse":55,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ako mosugo na usab kaninyo sa pagtukod og balay sa akong ngalan, gani dinhi niini nga dapit, aron inyong mapamatud-an ang inyong kaugalingon ngari kanako nga kamo matinud-anon sa tanang butang bisan unsa nga akong isugo kaninyo, aron ako mopanalangin kaninyo, ug mokorona kaninyo og dungog, imortalidad, ug kinabuhing dayon."},{"verse":56,"text":"Ug karon sultihan ko kamo, kalabot sa akong balay sak-anan nga akong gisugo kaninyo nga tukoron aron kasak-an sa mga dayo, itukod kini sa akong ngalan, ug ibutang ang akong ngalan diha niini, ug tugoti ang akong sulugoon nga si Joseph ug ang mga sakop sa iyang balay nga mopuyo niini, gikan sa usa ka henerasyon hangtod sa sunod nga mga henerasyon."},{"verse":57,"text":"Kay kini nga pagdihog akong gibutang sa iyang ulo, aron ang iyang panalangin mabutang usab sa ulo sa iyang kaliwatan nga mosunod kaniya."},{"verse":58,"text":"Ug sama sa akong gisulti ngadto kang Abraham kabahin sa mga kaliwatan sa yuta, gani akong isulti sa akong sulugoon nga si Joseph: Diha kanimo ug sa imong binhi mapanalanginan ang kaliwatan sa yuta."},{"verse":59,"text":"Busa, hatagi ang akong sulugoon nga si Joseph ug ang iyang binhi nga mosunod kaniya og dapit niana nga balay, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon, hangtod sa kahangtoran, miingon ang Ginoo."},{"verse":60,"text":"Ug ang ngalan niana nga balay tawagon og Balay sa Nauvoo; ug himoa kini nga usa ka makalipay nga pinuy-anan alang sa tawo, ug kapahulayan nga dapit alang sa gikapoy nga tigbiyahe, aron makapamalandong siya sa himaya sa Zion, ug sa himaya niini, ang tukoranan nga bato niini;"},{"verse":61,"text":"Aron makadawat usab siya sa tambag gikan niadtong akong gitakda nga mahimong sama sa mga tanom nga bantogan, ug sama sa mga tawo nga magbalantay sa iyang mga paril."},{"verse":62,"text":"Tan-awa, sa pagkatinuod sultihan ko kamo, ipatarong sa akong sulugoon nga si George Miller, ug sa akong sulugoon nga si Lyman Wight, ug sa akong sulugoon nga si John Snider, ug sa akong sulugoon nga si Peter Haws, ang ilang kaugalingon, ug magpili og usa kanila nga mahimong pangulo sa ilang korum alang sa katuyoan nga matukod kana nga balay."},{"verse":63,"text":"Ug magmugna sila og batakang balaod, nga pinaagi niini modawat sila og puhunan alang sa pagtukod niana nga balay."},{"verse":64,"text":"Ug dili sila modawat og minos sa kalim-an ka dolyares alang sa tampo sa puhunan niana nga balay, ug tugotan sila sa pagdawat og napulog lima ka libo ka dolyares gikan ni bisan kinsang tawo alang sa puhunan niana nga balay."},{"verse":65,"text":"Apan dili sila tugotan nga modawat og kapin sa napulog lima ka libo ka dolyares nga puhunan gikan ni bisan kinsang tawo."},{"verse":66,"text":"Ug dili sila tugotan nga modawat og ubos kay sa kalim-an ka dolyares alang sa tampo sa puhunan gikan ni bisan kinsang tawo niana nga balay."},{"verse":67,"text":"Ug dili sila tugotan nga modawat ni bisan kinsang tawo, isip tigpamuhonan niini nga balay, gawas kon mobayad siya sa iyang puhonan ngadto sa ilang mga kamot sa higayon nga madawat niya ang iyang sertipiko sa puhunan;"},{"verse":68,"text":"Ug tugbang sa bili sa puhunan nga iyang ibayad ngadto sa ilang mga kamot makadawat siya og sertipiko sa puhunan niana nga balay; apan kon siya walay nabayad ngadto sa ilang mga kamot dili siya makadawat og bisan unsang sertipiko sa puhunan niana nga balay."},{"verse":69,"text":"Ug kon si kinsa ang mobayad og puhunan ngadto sa ilang mga kamot alang kini sa puhunan niana nga balay, alang sa iyang kaugalingon, ug alang sa iyang henerasyon nga mosunod kaniya, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon, samtang siya ug ang iyang sumusunod maghupot niana nga sertipiko sa puhunan, ug dili mobaligya o mohatag niana nga sertipiko sa puhunan ngadto sa laing mga kamot pinaagi sa ilang kaugalingon nga kabubut-on ug pagbuot, kon kamo mobuhat sa akong kabubut-on, miingon ang Ginoo nga inyong Dios."},{"verse":70,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kon ang akong sulugoon nga si George Miller, ug ang akong sulugoon nga si Lyman Wight, ug ang akong sulugoon nga si John Snider, ug ang akong sulugoon nga si Peter Haws, makadawat og bisan unsang puhunan ngadto sa ilang mga kamot, nga salapi, o mga kabtangan diin sila nakadawat sa tugbang nga bili sa mga salapi, dili nila igahin ang bisan unsa nga bahin niana nga puhunan ngadto sa laing katuyoan, diha lamang niana nga balay."},{"verse":71,"text":"Ug kon igahin nila ang bisan unsang bahin niana nga puhunan sa laing butang, gawas lamang niana nga balay, nga walay pagtugot sa tigpamuhunan, ug dili mobayad og balik sa puhunan sa makaupat sa puhunan nga ilang gigahin sa laing butang, gawas lamang niana nga balay, pagatunglohon sila, ug papahawaon gikan sa ilang dapit, miingon ang Ginoong Dios; kay ako, ang Ginoo, mao ang Dios, ug dili mabiaybiay sa bisan unsa niini nga mga butang."},{"verse":72,"text":"Sa pagkatinuod sultihan ko kamo, pabayara ang akong sulugoon nga si Joseph og puhunan ngadto sa ilang mga kamot alang sa pagtukod niana nga balay, kon gihunahuna niya nga makaayo; apan ang akong sulugoon nga si Joseph dili mahimong mobayad og kapin sa napulog lima ka libo ka dolyares nga puhunan niana nga balay, ni ubos sa kalim-an ka dolyares; ni si bisan kinsang tawo, miingon ang Ginoo."},{"verse":73,"text":"Ug adunay uban usab nga nagtinguha nga masayod sa akong kabubut-on mahitungod kanila, kay sila nangayo niini sa akong mga kamot."},{"verse":74,"text":"Busa, sultihan ko kamo mahitungod sa akong sulugoon nga si Vinson Knight, kon mobuhat siya sa akong kabubut-on pahataga siya og puhunan niana nga balay alang sa iyang kaugalingon, ug alang sa iyang henerasyon nga mosunod kaniya, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon."},{"verse":75,"text":"Ug ipabayaw ug ipalanog niya ang iyang tingog, sa taliwala sa katawhan, aron mohangyo alang sa kawsa sa mga kabos ug timawa; ug ayaw itugot nga siya mapakyas, ni ipaluya ang iyang kasingkasing; ug akong dawaton ang iyang mga halad, kay dili kini sama sa mga halad ni Cain, alang kanako, kay maangkon ko siya, miingon ang Ginoo."},{"verse":76,"text":"Pasadyaa ang iyang pamilya ug ipahilayo ang ilang mga kasingkasing gikan sa kasakit; kay gipili ko siya ug midihog kaniya, ug siya mapasidunggan taliwala sa iyang balay, kay pasayloon ko ang tanan niyang mga sala, miingon ang Ginoo. Amen."},{"verse":77,"text":"Sa pagkatinuod, sultihan ko kamo, pahataga og puhunan ang akong sulugoon nga si Hyrum niana nga balay kon gihunahuna niya nga makaayo, alang sa iyang kaugalingon ug sa iyang henerasyon nga mosunod kaniya, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon."},{"verse":78,"text":"Pahataga og puhunan ang akong sulugoon nga si Isaac Galland niana nga balay; kay ako, ang Ginoo, nahigugma kaniya tungod sa buhat nga iyang nahimo, ug mopasaylo sa tanan niyang mga sala; busa, hinumdomi nga siya adunay tampo sa puhunan niana nga balay gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon."},{"verse":79,"text":"Pilia ang akong sulugoon nga si Isaac Galland uban kaninyo ug i-orden pinaagi sa akong sulugoon nga si William Marks, ug iyang mapanalanginan, aron mouban sa akong sulugoon nga si Hyrum aron motuman sa buhat nga ipakita ngadto kanila sa akong sulugoon nga si Joseph, ug sila mapanalanginan pag-ayo."},{"verse":80,"text":"Pabayara ang akong sulugoon nga si William Marks og puhunan ngadto niana nga balay, kon gihunahuna niya nga makaayo, alang sa iyang kaugalingon ug sa iyang henerasyon, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon."},{"verse":81,"text":"Pabayara ang akong sulugoon nga si Henry G. Sherwood og puhonan ngadto niana nga balay, kon gihunahuna niya nga makaayo, alang sa iyang kaugalingon ug sa iyang binhi nga mosunod kaniya, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon."},{"verse":82,"text":"Pabayara ang akong sulugoon nga si William Law og puhunan ngadto niana nga balay, alang sa iyang kaugalingon ug sa iyang binhi nga mosunod kaniya, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon."},{"verse":83,"text":"Kon buhaton niya ang akong kabubut-on ayaw ipadala ang iyang pamilya ngadto sa silangang mga yuta, bisan ngadto sa Kirtland; bisan pa niana, ako, ang Ginoo, motukod sa Kirtland, apan ako, ang Ginoo, adunay latigo nga giandam alang sa mga lumulupyo niini."},{"verse":84,"text":"Ug kabahin sa akong sulugoon nga si Almon Babbitt, adunay daghang butang nga wala nako ikahimuot; tan-awa, nagtinguha siya sa pagpatigbabaw sa iyang tambag kay sa tambag nga akong gimando, gani kana nga nagagikan sa Kapangulohan sa akong Simbahan; ug nagpahimutang siya og bulawan nga baka aron simbahon sa akong katawhan."},{"verse":85,"text":"Himoa nga walay tawo nga mobiya gikan niini nga dapit kinsa mianhi dinhi nga naningkamot sa paghupot sa akong mga sugo."},{"verse":86,"text":"Kon mopuyo sila dinhi magpakabuhi sila ngari kanako; ug kon mamatay sila itugot nga mamatay sila ngari kanako; kay makapahulay sila sa tanan nilang mga kahago dinhi, ug mopadayon sa ilang mga buluhaton."},{"verse":87,"text":"Busa, ipabutang sa akong sulugoon nga si William ang iyang pagsalig ngari kanako, ug ipahunong ang kahadlok mahitungod sa iyang pamilya, tungod sa mga sakit sa maong dapit. Kon gihigugma ko ninyo, sunda ang akong mga sugo; ug ang mga sakit sa maong dapit mosangpot sa inyong himaya."},{"verse":88,"text":"Paadtoa ug pasangyawa ang akong sulugoon nga si William sa akong walay kataposang ebanghelyo pinaagi sa makusog nga tingog, ug sa dakong kamaya, ingon nga siya pagaaghaton sa akong Espiritu, ngadto sa mga lumulupyo sa Warsaw, ug usab ngadto sa mga lumulupyo sa Carthage, ug usab ngadto sa mga lumulupyo sa Burlington, ug usab ngadto sa mga lumulupyo sa Madison, ug maghulat nga mapailobon ug makugihon alang sa dugang nga mga panudlo sa akong kinatibuk-ang komperensiya, miingon ang Ginoo."},{"verse":89,"text":"Kon buhaton niya ang akong kabubut-on papatalinghoga siya gikan karon sa tambag sa akong sulugoon nga si Joseph, ug gamit ang iyang mga kinitaan motabang sa kawsa sa mga kabos, ug momantala sa bag-ong hubad sa akong balaan nga pulong ngadto sa mga lumulupyo sa yuta."},{"verse":90,"text":"Ug kon mobuhat siya niini ako mopanalangin kaniya og daghang panalangin, aron dili siya masalikway, ni ang iyang mga binhi makita nga magpakilimos og pagkaon."},{"verse":91,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, ipapili, paordinahi, ug padihogi ang akong sulugoon nga si William, isip magtatambag sa akong sulugoon nga si Joseph, puli sa akong sulugoon nga si Hyrum, aron ang akong sulugoon nga si Hyrum modawat sa katungdanan sa Pagkapari, ug Patriyarka, nga gihatag kaniya sa iyang amahan, pinaagi sa panalangin ug usab pinaagi sa katungod;"},{"verse":92,"text":"Aron gikan karon maghupot siya sa mga yawe sa patriyarkal nga mga panalangin diha sa mga ulo sa tanan nakong katawhan,"},{"verse":93,"text":"Aron si bisan kinsa nga iyang panalanginan, pagapanalanginan, ug bisan kinsa nga iyang tunglohon pagatunglohon; nga bisan unsa nga iyang bugkoson dinhi sa yuta pagabugkoson didto sa langit; ug ang bisan unsa nga iyang luagan dinhi sa yuta pagaluagan didto sa langit."},{"verse":94,"text":"Ug gikan niini nga takna ako mopili kaniya nga mahimong propeta, ug manalagna, ug tigpadayag sa akong simbahan, sama sa akong sulugoon nga si Joseph;"},{"verse":95,"text":"Aron molihok siya uyon sa akong sulugoon nga si Joseph; ug aron usab makadawat siya og tambag gikan sa akong sulugoon nga si Joseph, kinsa mopakita kaniya sa mga yawe nga pinaagi niini mangayo siya ug makadawat, ug pagakoronahan sa samang panalangin, ug himaya, ug dungog, ug pagkapari, ug mga gasa sa pagkapari, nga sa makausa gihatag sa akong sulugoon nga si Oliver Cowdery;"},{"verse":96,"text":"Aron ang akong sulugoon nga si Hyrum mopamatuod sa mga butang nga akong ipakita kaniya, aron ang iyang ngalan pagahinumdoman nga halangdon gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon."},{"verse":97,"text":"Padawata usab ang akong sulugoon nga si William Law sa mga yawe nga sa maong paagi makapangayo ug makadawat siya og mga panalangin; tudloi siya nga magmapaubsanon sa akong atubangan, ug walay pagpanglimbong, ug madawat niya ang akong Espiritu, gani ang Maghuhupay, nga mopadayag ngadto kaniya sa kamatuoran sa tanang butang, ug mohatag kaniya, niana mismo nga takna, unsa ang iyang isulti."},{"verse":98,"text":"Ug kini nga mga timailhan mosunod kaniya—iyang ayohon ang masakiton, iyang hinginlan ang mga yawa, ug pagaluwason gikan niadtong mopainom kaniya og makamatay nga hiló;"},{"verse":99,"text":"Ug pagagiyahan siya sa agianan diin ang lala nga bitin dili makapaak sa iyang tikod, ug mosulbong siya sa handurawan sa iyang mga hunahuna sama nga nagsakay sa mga pako sa mga agila."},{"verse":100,"text":"Ug kon akong pagbut-an nga iyang pabangonon ang patay, ayaw niya papugngi ang iyang tingog."},{"verse":101,"text":"Busa, pasinggita og kusog ang akong sulugoon nga si William ug dili managana, uban ang kamaya ug kasadya, ug uban ang mga pagdayeg ngadto kaniya nga naglingkod sa trono hangtod sa kahangtoran, miingon ang Ginoo nga inyong Dios."},{"verse":102,"text":"Tan-awa, sultihan ko kamo, adunay gitagana nako nga misyon alang sa akong sulugoon nga si William, ug sa akong sulugoon nga si Hyrum, ug alang kanila lamang; ug ipabilin sa panimalay ang akong sulugoon nga si Joseph, kay siya gikinahanglan. Ang nahibilin ipakita nako kaninyo human niini. Ug mao gayod kana. Amen."},{"verse":103,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kon ang akong sulugoon nga si Sidney moalagad kanako ug mahimong magtatambag sa akong sulugoon nga si Joseph, pabaroga siya ug pabuhata sa katungdanan sa iyang tawag, ug magpaubos sa iyang kaugalingon sa akong atubangan."},{"verse":104,"text":"Ug kon mohalad siya ngari kanako og angayang dawaton nga halad, ug mga pagkompisal, ug magpabilin uban sa akong katawhan, tan-awa, ako, ang Ginoo nga inyong Dios, motambal kaniya aron siya mamaayo; ug mopataas na usab sa iyang tingog ibabaw sa kabukiran, ug mahimong usa ka tigpamaba sa akong atubangan."},{"verse":105,"text":"Paanhia siya ug papuy-a ang iyang pamilya sa kasilinganan kon diin nagpuyo ang akong sulugoon nga si Joseph."},{"verse":106,"text":"Ug sa tanan niyang mga pagpanaw ipataas niya ang iyang tingog sama sa tunog sa trumpeta, ug mopasidaan sa mga lumulupyo sa yuta sa paglikay sa kapungot nga moabot."},{"verse":107,"text":"Patabanga siya sa akong sulugoon nga si Joseph, ug usab patabanga ang akong sulugoon nga si William Law sa akong sulugoon nga si Joseph, sa paghimo og usa ka maligdong nga pamahayag ngadto sa mga hari sa yuta, gani sama sa akong gikasulti kaninyo sa miagi."},{"verse":108,"text":"Kon ang akong sulugoon nga si Sidney mobuhat sa akong kabubut-on, ayaw niya ipadala ang iyang pamilya ngadto sa kayutaan sa silangan, apan ipabalhin niya ang ilang pinuy-anan, gani sama sa akong gikasulti."},{"verse":109,"text":"Tan-awa, dili akong kabubut-on nga mangita siya og luwas nga dapit ug kadangpan nga layo sa akong gipili alang kaninyo, gani ang dakbayan sa Nauvoo."},{"verse":110,"text":"Sa pagkatinuod sultihan ko kamo, bisan karon, kon mopatalinghog siya sa akong tingog, makaayo kini kaniya. Ug mao gayod kana. Amen."},{"verse":111,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, pabayra ang akong sulugoon nga si Amos Davies og puhunan ngadto sa mga kamot sa akong mga gipili nga motukod og balay nga kasak-an, gani ang Balay sa Nauvoo."},{"verse":112,"text":"Ipahimo kini kaniya kon nagtinguha siya nga makabaton og katungod sa pagpanag-iya; ug papatalinghoga siya sa tambag sa akong sulugoon nga si Joseph, ug maghago sa iyang kaugalingong mga kamot aron maangkon niya ang pagsalig sa mga tawo."},{"verse":113,"text":"Ug dihang mapamatud-an niya ang iyang kaugalingon nga matinud-anon sa tanang butang nga gisalig sa iyang pag-atiman, oo, bisan sa gagmay nga mga butang, pagahimoon siya nga tigdumala sa daghang butang;"},{"verse":114,"text":"Busa ipaubos niya ang iyang kaugalingon, aron siya pagahimayaon. Ug mao gayod kana. Amen."},{"verse":115,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kon ang akong sulugoon nga si Robert D. Foster mosunod sa akong tingog, patukora siya og balay alang sa akong sulugoon nga si Joseph, sumala sa kasabotan nga iyang gihimo uban kaniya, kay ang pultahan pagaablihan ngadto kaniya sa matag karon ug unya."},{"verse":116,"text":"Ug pahinulsola siya sa tanan niyang binuang, ug sul-oban ang iyang kaugalingon og gugmang putli; ug mohunong sa pagbuhat og daotan, ug mohunong sa pagsulti og dili mabinationg mga pulong;"},{"verse":117,"text":"Ug usab pabayara og puhunan ngadto sa mga kamot sa korum sa Balay sa Nauvoo, alang sa iyang kaugalingon ug alang sa iyang henerasyon nga mosunod kaniya, gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon;"},{"verse":118,"text":"Ug mopatalinghog sa tambag sa akong sulugoon nga si Joseph, ug Hyrum, ug William Law, ug ngadto sa mga awtoridad nga akong gitawag sa pagpahimutang sa katukoran sa Zion; ug makaayo kini kaniya hangtod sa kahangtoran. Ug mao gayod kana. Amen."},{"verse":119,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, walay tawo nga pabayron og puhunan ngadto sa korum sa Balay sa Nauvoo gawas kon siya usa ka tumutuo sa Basahon ni Mormon, ug sa mga pagpadayag nga akong gihatag kaninyo, miingon ang Ginoo nga inyong Dios;"},{"verse":120,"text":"Kay kana nga mokapin o mokulang pa niini nagagikan sa daotan, ug pagaubanan og mga tunglo ug dili mga panalangin, miingon ang Ginoo nga inyong Dios. Ug mao gayod kana. Amen."},{"verse":121,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, hatagi og makataronganon nga suhol ang korum sa Balay sa Nauvoo sa ilang tanang kahago nga ilang gihimo sa pagtukod sa Balay sa Nauvoo; ug ipatuman ang ilang mga suhol sama sa masabotan, kabahin sa kantidad niini."},{"verse":122,"text":"Ug ang matag tawo nga mobayad og puhunan pahataga og tampo sa ilang mga suhol, kon kini gikinahanglan, alang sa ilang kabuhian, miingon ang Ginoo; kondili, ang ilang mga kahago pagakwentahon nga ilang puhunan niana nga balay. Ug mao gayod kana. Amen."},{"verse":123,"text":"Sa pagkatinuod sultihan ko kamo, ipahibalo ko karon kaninyo ang mga opisyal nga nahisakop sa akong Pagkapari, nga huptan ninyo ang mga yawe niini, gani ang Pagkapari nga subay sa kapunongan ni Melchizedek, nga subay sa kapunongan sa akong Bugtong nga Anak."},{"verse":124,"text":"Una, ihatag ko kaninyo si Hyrum Smith nga mahimong patriyarka nganha kaninyo, aron maghupot sa mga panalangin sa pagselyo alang sa akong Simbahan, gani ang Balaan nga Espiritu sa saad, nga pinaagi niini maselyo kamo hangtod sa adlaw sa katubsanan, aron dili kamo mapukan bisan pa sa takna sa pagtental nga moabot diha kaninyo."},{"verse":125,"text":"Ihatag ko kaninyo ang akong sulugoon nga si Joseph nga mahimong tigdumala nga elder sa akong tibuok simbahan, nga mahimong tighubad, tigpadayag, manalagna, ug propeta."},{"verse":126,"text":"Ihatag ko kaniya nga mahimong magtatambag ang akong sulugoon nga si Sidney Rigdon ug ang akong sulugoon nga si William Law, nga kini maglangkob sa korum ug Unang Kapangulohan, aron modawat sa mga orakulo alang sa tibuok simbahan."},{"verse":127,"text":"Ihatag ko kaninyo ang akong sulugoon nga si Brigham Young nga mahimong presidente sa Napulog Duha ka tigbiyahe nga konseho;"},{"verse":128,"text":"Ang Napulog Duha nga mao ang maghupot sa mga yawe sa pag-abli sa awtoridad sa akong gingharian sa upat ka suok sa yuta, ug human niana modala sa akong pulong ngadto sa matag linalang."},{"verse":129,"text":"Sila mao si Heber C. Kimball, Parley P. Pratt, Orson Pratt, Orson Hyde, William Smith, John Taylor, John E. Page, Wilford Woodruff, Willard Richards, George A. Smith;"},{"verse":130,"text":"Si David Patten akong gidala ngari sa akong kaugalingon; tan-awa, ang iyang pagkapari walay tawo nga makakuha gikan kaniya; apan, sa pagkatinuod sultihan ko kamo, adunay lain nga pilion nianang sama nga tawag."},{"verse":131,"text":"Ug usab, sultihan ko kamo, hatagan ko kamo og labaw nga konseho, alang sa tukoranan nga bato sa Zion—"},{"verse":132,"text":"Sila si, Samuel Bent, Henry G. Sherwood, George W. Harris, Charles C. Rich, Thomas Grover, Newel Knight, David Dort, Dunbar Wilson—si Seymour Brunson akong gidala ngari sa akong kaugalingon; walay tawo nga makakuha sa iyang pagkapari, apan ang laing tawo mahimong pilion alang nianang sama nga pagkapari puli sa iyang dapit; ug sa pagkatinuod sultihan ko kamo, ang akong sulugoon nga si Aaron Johnson paordinahan ngadto niining balaan nga tawag puli sa iyang dapit—David Fullmer, Alpheus Cutler, William Huntington."},{"verse":133,"text":"Ug usab, ihatag ko kaninyo si Don C. Smith nga mahimong presidente sa usa ka korum sa mga high priest;"},{"verse":134,"text":"Diin kini nga ordinansa gipasiugdahan alang sa katuyoan nga mahimong takos kadtong pilion nga mga presidente sa piho nga mga dapit o mga sulugoon diha sa nagkalain-laing mga stake nga nagkatag sa langyaw nga mga dapit;"},{"verse":135,"text":"Ug mahimo usab silang mobiyahe kon pilion nila, apan hinuon i-orden sila nga mahimong mga presidente sa piho nga mga dapit; mao kini ang katungdanan sa ilang balaan nga tawag, miingon ang Ginoo nga inyong Dios."},{"verse":136,"text":"Ihatag ko kaniya si Amasa Lyman ug Noah Packard nga mga magtatambag, aron modumala sila sa korum sa mga high priest sa akong simbahan, miingon ang Ginoo."},{"verse":137,"text":"Ug usab, sultihan ko kamo, akong ihatag kaninyo sila si John A. Hicks, Samuel Williams, ug Jesse Baker, nga ang maong pagkapari mao ang modumala sa korum sa mga elder, kini nga korum gitukod alang sa mga tigpangalad sa pihong mga dapit; bisan pa niana mahimo silang mobiyahe, apan gi-orden sila nga mga ministro sa pihong dapit sa akong simbahan, miingon ang Ginoo."},{"verse":138,"text":"Ug usab, ihatag ko kaninyo si Joseph Young, Josiah Butterfield, Daniel Miles, Henry Herriman, Zera Pulsipher, Levi Hancock, James Roster, aron modumala sa korum sa seventy;"},{"verse":139,"text":"Kini nga korum gitukod alang sa tigpanaw nga mga elder aron mopamatuod sa akong ngalan sa tibuok kalibotan, bisan asa nga ang tigbiyahe nga labaw nga konseho, nga akong mga apostol, mopadala kanila aron mag-andam og agianan alang kanako."},{"verse":140,"text":"Ang kalainan tali niini nga korum ug sa korum sa mga elder mao nga ang usa mobiyahe kanunay, ug ang lain mao ang modumala sa mga simbahan matag karon ug unya; ang usa adunay kapangakohan sa pagdumala matag karon ug unya, ug ang lain walay kapangakohan sa pagdumala, miingon ang Ginoo nga inyong Dios."},{"verse":141,"text":"Ug usab, sultihan ko kamo, ihatag ko kaninyo si Vinson Knight, Samuel H. Smith, ug Shadrach Roundy, kon modawat siya niini, aron modumala sa bishopric; ang kasayoran sa giingon nga bishopric gihatag kaninyo diha sa basahon sa Doktrina ug mga Pakigsaad."},{"verse":142,"text":"Ug usab, sultihan ko kamo, si Samuel Rolfe ug ang iyang mga magtatambag alang sa mga pari, ug ang presidente sa mga magtutudlo ug ang iyang mga magtatambag, ug usab ang presidente sa mga deacon ug ang iyang mga magtatambag, ug usab ang presidente sa stake ug ang iyang mga magtatambag."},{"verse":143,"text":"Kanang gihisgotan nga mga katungdanan akong gihatag kaninyo, ug ang mga yawe niini, alang sa mga tabang ug alang sa mga pamunoan, alang sa buluhaton sa pangalagad ug sa paghingpit sa akong mga santos."},{"verse":144,"text":"Ug adunay sugo nga akong ihatag kaninyo, nga kinahanglan inyong butangan og mga tawo kining tanan nga buhatan ug aprobahan kana nga mga ngalan nga akong gihisgotan, kondili, ayaw sila aprobahi atol sa akong kinatibuk-an nga komperensiya;"},{"verse":145,"text":"Ug nga kamo kinahanglan moandam og mga dapit alang niini nga mga buhatan sa akong balay kon kamo motukod niini alang sa akong ngalan, miingon ang Ginoo nga inyong Dios. Ug mao gayod kana. Amen."}]},{"chapter":125,"verses":[{"verse":1,"text":"Unsa man ang kabubut-on sa Ginoo kabahin sa mga santos sa Teritoryo sa Iowa?"},{"verse":2,"text":"Sa pagkatinuod, kini ang giingon sa Ginoo, sultihan ko kamo, kon kadto sila nga nagtawag sa ilang kaugalingon sa akong ngalan ug naningkamot nga mahimong akong mga santos, kon buhaton nila ang akong kabubut-on ug motuman sa akong mga sugo mahitungod kanila, papundoka sila sa ilang kaugalingon ngadto sa mga dapit nga akong pilion alang kanila pinaagi sa akong sulugoon nga si Joseph, ug patukora og mga siyudad sa akong ngalan, aron makapangandam sila alang nianang gitagana alang sa panahon nga moabot."},{"verse":3,"text":"Patukora sila og siyudad sa akong ngalan diha sa yuta nga atbang sa siyudad sa Nauvoo, ug ang ngalan nga Zarahemla mao ang ipangalan niini."},{"verse":4,"text":"Ug kadtong tanan nga moanhi gikan sa silangan, ug sa kasadpan, ug sa amihanan, ug sa habagatan, nga adunay mga tinguha nga mopuyo diha niini, makaangkon sa ilang mga kabilin diha niini, ingon usab sa siyudad sa Nashville, o sa siyudad sa Nauvoo, ug sa tanang stake nga akong gipili, miingon ang Ginoo."}]},{"chapter":126,"verses":[{"verse":1,"text":"Minahal ug hinigugma nga igsoon, Brigham Young, sa pagkatinuod nagsulti ang Ginoo nganha kanimo: Akong sulugoon nga Brigham, wala na kinahanglana gikan kanimo nga biyaan nimo ang imong pamilya sama sa nangaging mga panahon, kay ang imong halad akong gidawat."},{"verse":2,"text":"Nakita nako ang imong paghago ug pagpaningkamot og maayo sa mga pagbiyahe alang sa akong ngalan."},{"verse":3,"text":"Busa mosugo ko kanimo sa pagdala sa akong pulong ngadto sa langyaw nga mga dapit, ug sa pag-atiman og maayo sa imong pamilya gikan niining panahona, sugod karon ug hangtod sa hangtod. Amen."}]},{"chapter":127,"verses":[{"verse":1,"text":"Tungod kay ang Ginoo mipadayag ngari kanako nga ang akong mga kaaway, sa Missouri ug niini nga Estado, migukod na usab kanako; ug tungod kay naggukod sila kanako nga walay hinungdan, ug walay bisan gamay nga anino o bulok sa kaangayan o katungod sa ilang habig sa pagdemanda batok kanako; ug tungod kay ang ilang mga pasangil gipasikad sa mga bakak sa labing daotan nga matang, akong gihunahuna nga angay ug maalamon ang akong pagbiya sa dapit sulod sa mubong panahon, alang sa akong kaugalingong kaluwasan gikan sa peligro ug alang sa kaluwasan niini nga katawhan gikan sa peligro. Gusto nakong isulti sa tanan kang kinsa aduna akoy obligasyon sa patigayon, nga akong gipiyal ang akong mga kalihokan ngadto sa mga tinugyanan ug mga tig-alagad sa buhatan kinsa moatiman sa tanan nga patigayon sa walay langan ug sa tukmang mga paagi, ug moseguro nga ang akong tanang utang mabayran sa tukmang panahon, pinaagi sa pagbaligya sa mga kabtangan, o sa lain nga paagi, sumala sa panginahanglan sa higayon, o sumala sa pagkabutang. Sa panahon nga akong mahibaloan nga ang unos hingpit na nga mahunong, niana dayon mobalik na usab ako kaninyo."},{"verse":2,"text":"Ug mahitungod sa mga kakuyaw diin ako gitawag sa paglahutay, maingon nga gamay ra kini nga butang alang kanako, kay ang kasina ug kapungot sa tawo mao man ang kasagarang nahitabo sa tanang adlaw sa akong kinabuhi; ug kon unsa man ang hinungdan maingon nga kahibulongan, gawas lang kon gi-orden ako kaniadto sa wala pa matukod ang kalibotan alang sa maayong katuyoan, o sa dili maayo, kon unsa man ang buot ninyo nga itawag niini. Hukmi sa inyong kaugalingon. Ang Dios nasayod niining tanan nga butang, kon kini maayo man o daotan. Apan bisan pa niana, ang lawom nga tubig mao ang akong naandan nga langoyan. Kining tanan nahimong akong ikaduhang kinaiya; ug akong gibati, sama ni Pablo, ang paghimaya sa kalisdanan; kay hangtod niining adlawa ang Dios sa akong mga amahan miluwas kanako gikan nianang tanan, ug moluwas kanako sukad karon; kay tan-awa, ug sud-onga, ako magmadaogon batok sa tanan nakong mga kaaway, kay ang Ginoong Dios namulong niini."},{"verse":3,"text":"Busa, pasadyaa ang tanang santos, ug magmaya sa hilabihan; kay ang Dios sa Israel mao ang ilang Dios, ug siya mohatag og makataronganong balos isip ganti diha sa mga ulo sa tanan nilang mga tigdaog-daog."},{"verse":4,"text":"Ug usab, sa pagkatinuod kini ang gisulti sa Ginoo: Padayona ang buluhaton sa akong templo, ug ang tanang buluhaton nga akong gihatag kaninyo, ug ayaw ihunong; ug dobleha ang inyong kakugi, ug ang inyong pagkaporsigido, ug pagkamapailobon, ug ang inyong mga buhat, ug dili gayod mawala ang inyong ganti, miingon ang Ginoo sa mga Panon. Ug kon sila molutos kaninyo, gilutos usab nila ang mga propeta ug matarong nga mga tawo nga nag-una kaninyo. Agig bugti niining tanan adunay ganti didto sa langit."},{"verse":5,"text":"Ug usab, hatagan ko kamo og pulong kalabot sa bunyag alang sa inyong mga patay."},{"verse":6,"text":"Sa pagkatinuod, kini ang gisulti sa Ginoo kaninyo mahitungod sa inyong mga patay: Kon si bisan kinsa kaninyo ang pagabunyagan alang sa inyong mga patay, gikinahanglan nga adunay tigrekord, ug pasaksiha siya sa inyong mga bunyag; papaminawa siya pinaagi sa iyang mga dunggan, aron mopamatuod siya sa kamatuoran, miingon ang Ginoo;"},{"verse":7,"text":"Aron ang tanan nga inyong itala matala didto sa langit; bisan unsa nga inyong bugkoson dinhi sa yuta, pagabugkoson didto sa langit; bisan unsa ang inyong luagan dinhi sa yuta, pagaluagan didto sa langit;"},{"verse":8,"text":"Kay ako hapit na mopahiuli sa daghang butang ngadto sa yuta, kalabot sa pagkapari, miingon ang Ginoo sa mga Panon."},{"verse":9,"text":"Ug usab, ipahan-ay ang tanang talaan, aron mabutang kini sa tipiganan sa mga dokumento sa akong balaan nga templo, aron mahuptan nga handomanan gikan sa usa ka henerasyon ngadto sa mosunod nga mga henerasyon, miingon ang Ginoo sa mga Panon."},{"verse":10,"text":"Sutihan ko ang tanang santos, nga ako nagtinguha, sa labing dako nga tinguha, nga makigsulti kanila gikan sa pulpito kalabot sa hilisgotan sa bunyag alang sa mga patay, sa mosunod nga Igpapahulay. Apan tungod kay wala sa akong gahom ang paghimo niini, akong isulat ang pulong sa Ginoo sa matag karon ug unya, kalabot niana nga hilisgotan, ug ipadala kini kaninyo pinaagi sa koreyo, ingon man usab sa daghan pa nga butang."},{"verse":11,"text":"Taposon ko na ang akong sulat sa pagkakaron, tungod sa kakulang sa panahon; kay ang kaaway nagmaabtik, ug sama sa gisulti sa Manunubos, ang prinsipe niini nga kalibotan moabot, apan wala siyay gahom nga makabuntog kanako."},{"verse":12,"text":"Tan-awa, ang akong pag-ampo sa Dios mao nga kamong tanan maluwas unta. Ug ako mopirma sa akong ngalan nga inyong sulugoon diha sa Ginoo, propeta, ug manalagna sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw."},{"verse":13,"text":"Joseph Smith."}]},{"chapter":128,"verses":[{"verse":1,"text":"Sama sa akong gipamahayag kaninyo sa akong sulat sa wala pa ako mobiya sa akong dapit, nga mosulat ako kaninyo matag karon ug unya ug mohatag kaninyo og kasayoran kalabot sa daghang hilisgotan, karon akong ipadayon ang hilisgotan sa bunyag alang sa mga patay, kay kana nga hilisgotan ingon og anaa kanunay sa akong hunahuna, ug nakatandog kaayo kini sa akong mga pagbati, sukad nga gigukod ko sa akong mga kaaway."},{"verse":2,"text":"Misulat ko og pipila ka pulong sa pagpadayag nganha kaninyo kabahin sa tigrekord. Ako adunay pipila ka dugang nga mga hunahuna kalabot niini nga butang, nga karon akong pamatud-an. Mao kini, gipahayag sa akong unang sulat nga kinahanglan nga adunay tigrekord, kinsa mao ang saksi nga nakakita mismo, ug usab nakadungog sa iyang dunggan mismo, aron siya mohimo og talaan sa kamatuoran sa atubangan sa Ginoo."},{"verse":3,"text":"Karon, kalabot niining butanga, malisod sa usa lang ka tigrekord nga makatambong sa tanan nga higayon, ug mobuhat sa tanan nga buluhaton. Sa paglikay niini nga kalisod, mahimong adunay tigrekord nga pilion sa matag ward sa siyudad, kinsa takos sa paghimo sa tukmang talaan sa mga gihisgotan sa tigom; ug ipahimo kaniya ang detalyado ug tukma nga pagrekord sa tibuok nga kahimoan, magmatuod sa iyang talaan nga nakita niya mismo sa iyang mga mata, ug nadungog mismo sa iyang mga dunggan, mosulat sa petsa, ug mga ngalan, ug uban pa, ug sa kasaysayan sa tibuok kalihokan; mongalan usab og tulo ka tawo nga anaa, kon adunay bisan kinsa nga mitambong, kinsa makamatuod bisan kanus-a sa panahon nga tawgon aron pagmatuod niini, aron sa ba-ba sa duha o tulo ka saksi ang matag pulong mapamatud-an."},{"verse":4,"text":"Dugang pa, himoa nga adunay kinatibuk-ang tigrekord, nga mao ang hatagan niining uban nga mga talaan, inubanan sa mga sertipiko nga may ilang kaugalingong mga pirma, nagmatuod nga ang talaan nga ilang gihimo tinuod. Dayon ang kinatibuk-ang tigrekord sa simbahan makabutang sa talaan ngadto sa kinatibuk-ang basahon sa simbahan, uban sa mga sertipiko ug sa tanang saksi, inubanan sa iyang kaugalingong pahayag nga sa pagkatinuod nagtuo siya nga kanang gihisgotan nga pahayag ug mga talaan tinuod, gikan sa iyang kahibalo sa kinatibuk-ang kinaiya ug sa pagpili sa simbahan niana nga mga tawo. Ug sa pagkahuman niini diha sa kinatibuk-ang basahon sa simbahan, ang talaan mahimong sama ka balaan, ug mopanghimatuod sa ordinansa nga sama ra nga nakita niya sa iyang mga mata mismo ug nadungog sa iyang mga dunggan mismo, ug mihimo og sama nga talaan diha sa kinatibuk-ang basahon sa simbahan."},{"verse":5,"text":"Kamo tingali makahunahuna nga kini nga han-ay sa mga butang kuti kaayo; apan sultihan ko kamo nga pagtubag lamang kini sa kabubut-on sa Dios, pinasubay sa ordinansa ug pagpangandam nga gi-orden ug giandam sa Ginoo sa wala pa ang katukoran sa kalibotan, alang sa kaluwasan sa mga patay nga namatay nga walay kahibalo sa ebanghelyo."},{"verse":6,"text":"Ug dugang pa, gusto nako nga mahinumdom kamo nga si Juan ang Tigpadayag namalandong niining mao nga hilisgotan kalabot sa mga patay, sa dihang mipahayag siya, sama sa inyong makita nga nahisulat sa Pinadayag 20:12—Ug ako nakakita sa mga patay, bantogan ug dili bantogan, nagtindog sa atubangan sa Dios; ug ang mga basahon gibuksan; ug lain nga basahon gibuksan, nga mao ang basahon sa kinabuhi; ug ang mga patay gihukman gikan sa mga butang nga nahisulat didto sa mga basahon, sumala sa ilang mga binuhatan."},{"verse":7,"text":"Inyong makita dinhi niini nga kinutlo nga ang mga basahon gibuksan; ug lain nga basahon gibuksan, nga mao ang basahon sa kinabuhi; apan ang mga patay gihukman gikan niadtong mga butang nga nahisulat didto sa mga basahon, sumala sa ilang mga binuhatan; busa, ang mga basahon nga gipamulong mao ang mga basahon nga naglangkob sa talaan sa ilang mga binuhatan, ug nagpasabot sa mga talaan nga gitipigan sa ibabaw sa yuta. Ug ang basahon nga mao ang basahon sa kinabuhi mao ang talaan nga gitipigan sa langit; ang baroganan tukma nga nahiuyon sa doktrina nga gisugo kaninyo diha sa pagpadayag nga nalakip sa sulat nga akong gisulat kaninyo sa wala pa ang akong pagbiya sa akong dapit—aron ang tanan nga inyong itala kini matala didto sa langit."},{"verse":8,"text":"Karon, ang kinaiyahan niini nga ordinansa anaa sa gahom sa pagkapari, pinaagi sa pagpadayag ni Jesukristo, diin gitugot nga bisan unsa ang inyong bugkoson dinhi sa yuta, pagabugkoson didto sa langit, ug bisan unsa ang inyong luagan dinhi sa yuta pagaluagan didto sa langit. O, sa laing pagkasulti, kon sabton sa laing paagi ang paghubad, bisan unsa ang inyong itala dinhi sa yuta mahitala didto sa langit, ug bisan unsa ang dili ninyo itala dinhi sa yuta dili mahitala didto sa langit; kay gikan sa mga basahon ang inyong mga patay pagahukman, sumala sa ilang kaugalingong binuhatan, kon sila ba nakapahigayon sa mga ordinansa sa ilang kaugalingon propria persona, o pinaagi sa ilang kaugalingong mga tinugyanan, sumala sa ordinansa nga giandam sa Dios alang sa ilang kaluwasan gikan sa wala pa matukod ang kalibotan, sumala sa mga talaan nga ilang gitipigan kalabot sa ilang mga patay."},{"verse":9,"text":"Kini maingon ngadto sa uban nga usa ka mapangahason nga doktrina nga atong gihisgotan—ang gahom nga motala o mobugkos dinhi sa yuta ug mobugkos didto sa langit. Bisan pa niana, sa tanang panahon sa kalibotan, sa matag higayon nga ang Ginoo naghatag og dispensasyon sa pagkapari ngadto ni bisan kinsang tawo pinaagi sa tinuod nga pagpadayag, o ni bisan kinsang pundok sa mga tawo, kini nga gahom kanunay nga gihatag. Busa, bisan unsa ang gibuhat niadto nga mga tawo pinaagi sa awtoridad, sa ngalan sa Ginoo, ug mibuhat niini nga matinuoron ug matinud-anon, ug mitipig og tukma ug matinud-anon nga talaan niini, nahimo kining balaod sa ibabaw sa yuta ug sa langit, ug dili na mabakwi, sumala sa mga sugo sa halangdong Jehova. Tinuod kini nga panultihon. Kinsa may makadawat niini?"},{"verse":10,"text":"Ug usab, alang sa panig-ingnan, Mateo 16:18, 19: Ug ako moingon usab nganha kanimo, ikaw mao si Pedro, ug sa ibabaw niini nga bato ako motukod sa akong simbahan; ug ang mga ganghaan sa impyerno dili makabuntog batok niini. Ug ako mohatag nganha kanimo sa mga yawe sa gingharian sa langit: ug bisan unsa ang imong bugkoson dinhi sa yuta pagabugkoson didto sa langit; ug bisan unsa ang imong luagan dinhi sa yuta pagaluagan didto sa langit."},{"verse":11,"text":"Karon ang mahinungdanon ug labing dako nga tinagoan sa tanang butang, ug ang summum bonum sa tibuok nga hilisgotan nga anaa sa atong atubangan, gilangkob diha sa pag-angkon sa mga gahom sa Balaang Pagkapari. Alang kaniya nga gihatagan niini nga mga yawe dili malisod ang pagbaton og kahibalo sa mga kamatuoran kalabot sa kaluwasan sa mga anak sa katawhan, alang sa mga patay ingon man sa mga buhi."},{"verse":12,"text":"Dinhi niini anaa ang himaya ug dungog, ug imortalidad ug kinabuhing dayon—Ang ordinansa sa bunyag pinaagi sa tubig, aron ipaunlod niini aron mahimong sama sa patay, aron ang usa ka baroganan mahiuyon ngadto sa laing baroganan; aron ipaunlod sa tubig ug motunga gikan sa tubig nga nagsimbolo sa pagkabanhaw sa mga patay pinaagi sa pagbangon gikan sa ilang mga lubnganan; busa, kini nga ordinansa gihimo aron sa pagpakita og relasyon ngadto sa ordinansa sa bunyag alang sa mga patay, tungod kay nagsimbolo kini sa pagkamatay."},{"verse":13,"text":"Busa, ang bunyaganan gihimo nga sama sa lubnganan, ug gimando nga ipabutang sa usa ka dapit sa ilawom diin ang mga buhi naanad nga magpundok, aron sa pagpakita og panig-ingnan sa mga buhi ug sa mga patay, ug aron ang tanang butang adunay kasusama, ug aron kini magkauyon sa usag usa—aron ang kalibotanon mapahiuyon niana nga langitnon, sama sa gipahayag ni Pablo, diha sa 1 Mga Taga-Corinto 15:46, 47, ug 48:"},{"verse":14,"text":"Hinuon ang nahauna dili ang espirituhanon, apan ang kinaiyanhon; ug human niana ang espirituhanon. Ang unang tawo gikan sa yuta, yutan-on; ang ikaduhang tawo mao ang Ginoo gikan sa langit. Sila nga yutan-on, sama usab kanila nga yutan-on; ug sila nga langitnon, sama usab kanila nga langitnon. Ug sama sa mga talaan sa yuta kalabot sa inyong mga patay, nga gitala sa tukmang paagi, mao usab ang mga talaan sa langit. Busa, kini, mao ang gahom sa pagselyo ug pagbugkos, sa laing pagsabot, ang mga yawe sa gingharian, nga naglangkob sa yawe sa kahibalo."},{"verse":15,"text":"Ug karon, akong hinigugmang mga igsoon nga lalaki ug babaye, ipasalig ko kaninyo nga kini ang mga baroganan kalabot sa mga patay ug sa mga buhi nga dili mahimong hatagan lamang og gamay nga pagtagad, kalabot sa atong kaluwasan. Kay ang ilang kaluwasan gikinahanglan ug mahinungdanon sa atong kaluwasan, sama sa gisulti ni Pablo kabahin sa mga amahan—nga sila kon wala kita dili mahingpit—ni kita kon wala ang atong mga patay mahimong hingpit."},{"verse":16,"text":"Ug karon, kalabot sa bunyag alang sa mga patay, ako mohatag kaninyo og laing kinutlo ni Pablo, 1 Mga Taga-Corinto 15:29: Kon dili pa, unsa may ilang mahimo niadtong mga tawo nga gibunyagan alang sa mga patay, kon ang mga patay dili man ugaling mabanhaw? Ngano man nga gibunyagan sila alang sa mga patay?"},{"verse":17,"text":"Ug usab, agi og sumpay niini nga kinutlo mohatag ako kaninyo og kinutlo gikan sa usa sa mga propeta, kinsa mitumong sa iyang panan-aw ngadto sa pagpahiuli sa pagkapari, sa mga himaya nga ipadayag sa kataposang mga adlaw, ug sa talagsaong paagi kini nga labing mahimayaon sa tanang hilisgotan nga nahiapil sa walay kataposang ebanghelyo, nga gitawag nga, ang bunyag alang sa mga patay; kay si Malaquias nag-ingon, sa kataposang kapitulo, mga bersikulo 5 ug 6: Tan-awa, ako mopadala kaninyo ni Elijah ang propeta sa dili pa moabot ang mahinungdanon ug makalilisang nga adlaw sa Ginoo: Ug siya mopabalik sa kasingkasing sa mga amahan ngadto sa mga anak, ug ang kasingkasing sa mga anak ngadto sa ilang mga amahan, basin unya ako moabot ug mohampak sa yuta uban sa tunglo."},{"verse":18,"text":"Tingali makahatag unta ko og mas yano nga paghubad niini, apan igo na ang pagkayano niini aron mahiangay sa akong katuyoan niini karon. Igo na nga masayod, niini nga sitwasyon, nga ang yuta hampakon sa tunglo gawas kon adunay makatakdo nga sumpay sa bisan unsa nga matang tali sa mga amahan ug sa mga anak, mahitungod sa pipila o ubang hilisgotan—ug tan-awa unsa kana nga hilisgotan? Mao kana ang bunyag alang sa mga patay. Kay kita kon wala sila dili mahimo nga hingpit; ni sila kon wala kita mahimong hingpit. Wala kanila ni kanato ang mahingpit kon wala kadtong nangamatay usab diha sa ebanghelyo; kay gikinahanglan kini alang sa pagpasiuna sa dispensasyon sa kahingpitan sa mga panahon, diin nga dispensasyon karon nagsugod na, nga ang tibuok ug kompleto ug hingpit nga pagkahiusa, ug lig-on nga pagtakdo sa mga dispensasyon, ug mga yawe, ug mga gahom, ug mga himaya kinahanglan nga mahitabo, ug ipadayag gikan sa mga adlaw ni Adan bisan hangtod karon nga panahon. Ug dili lamang kini, apan kadtong mga butang nga wala pa gayod mapadayag gikan sa pagtukod sa kalibotan, apan gitagoan gikan sa maalamon ug mabuot, ipadayag ngadto sa mga bata ug mga masuso karon, ang dispensasyon sa kahingpitan sa mga panahon."},{"verse":19,"text":"Karon, unsa pa ang atong nadungog mahitungod sa ebanghelyo nga atong nadawat? Ang tingog sa kalipay! Ang tingog sa kaluoy gikan sa langit; ug tingog sa kamatuoran gikan sa yuta; malipayong mga balita alang sa mga patay; ang tingog sa kalipay alang sa mga buhi ug sa mga patay; malipayon nga mga balita sa dakong kamaya. Pagkatahom sa ibabaw sa kabukiran sa mga tiil niadtong nanagdala sa mga maayong balita, nga nanagmantala sa pakigdait, nga nanagdala og mga maayong balita sa kaayohan, nga nanagmantala sa kaluwasan, nga nanag-ingon sa Zion: Ang imong Dios nagahari! Sama sa mga yamog sa Carmel, ang kahibalo mahitungod sa Dios mokunsad usab diha kanila!"},{"verse":20,"text":"Ug usab, unsa ang atong nadungog? Malipayong mga balita gikan sa Cumorah! Si Moroni, ang anghel gikan sa langit, nga nagpadayag sa katumanan sa mga propeta—ang basahon nga ipadayag. Ang tingog sa Ginoo sa kamingawan sa Fayette, lalawigan sa Seneca, nga nagpahayag sa tulo ka saksi nga mopamatuod sa basahon! Ang tingog ni Miguel sa mga baybayon sa Susquehanna, nga nagpaila sa yawa sa diha nga nagpakita siya nga sama sa anghel sa kahayag! Ang tingog nila ni Pedro, Santiago, ug Juan didto sa kamingawan taliwala sa Harmony, lalawigan sa Susquehanna, ug sa lungsod sa Colesville, lalawigan sa Broome, sa suba sa Susquehanna, nga nagpahayag sa ilang kaugalingon ingon nga naghupot sa mga yawe sa gingharian, ug sa dispensasyon sa kahingpitan sa panahon!"},{"verse":21,"text":"Ug usab, ang tingog sa Dios didto sa lawak sa tigulang nga si Amahang Whitmer, sa Fayette, lalawigan sa Seneca, ug sa nagkalainlaing panahon, ug sa nagkalainlaing dapit latas sa tanang panaw ug kalisdanan niini nga Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw! Ug ang tingog ni Miguel, ang arkanghel; ang tingog ni Gabriel, ug ni Rafael, ug sa nagkalain-lain nga mga anghel, gikan ni Miguel o ni Adan hangtod niini nga panahon, ang tanan nga nagpahayag sa ilang dispensasyon, sa ilang mga katungod, ilang mga yawe, ilang mga dungog, ilang pagkaharianon ug himaya, ug sa gahom sa ilang pagkapari; naghatag niini sa hinayhinay nga mga lakang, pagtulun-an human sa usa ka pagtulun-an; gamay dinhi, ug gamay didto; naghatag kanato og kahupayan pinaagi sa paglaom nianang moabot, nagpalig-on sa atong paglaom!"},{"verse":22,"text":"Kaigsoonan, dili ba kita mopadayon sa hilabihan ka mahinungdanon nga katuyoan? Padayon ug ayaw pagsibog. Pagmaisogon, kaigsoonan; ug padayon, padayon ngadto sa kadaogan! Pasadyaa ang inyong mga kasingkasing, ug paglipay sa hilabihan. Paawita og kalit ang yuta. Pasultiha ang mga patay sa mga awit sa walay kataposang pagdayeg ngadto ni Hari Immanuel, kinsa mi-orden, sa wala pa ang kalibotan, nianang makapahimo kanato sa pagtubos kanila gikan sa ilang bilanggoan; kay ang mga binilanggo mahimong gawasnon."},{"verse":23,"text":"Pasinggita ang mga kabukiran sa kamaya, ug tanan kamo nga mga walog singgit og kusog; ug tanan kamo nga mga dagat ug uga nga mga yuta isulti ang mga kahibulongan sa inyong Mahangtoron nga Hari! Ug kamong mga suba, ug mga sapa, ug mga sapa-sapa, pagbaha kamo sa kalipay. Ang mga kalasangan ug ang tanang kakahoyan sa umahan padayega sa Ginoo; ug kamong lig-on nga mga bato mohilak sa kamaya! Ug ang adlaw, buwan, ug mga bitoon sa kabuntagon paawita nga magdungan, ug ang tanang anak sa Dios pasinggita sa kamaya! Ug ang mahangtorong mga nilalang pasangyawa sa iyang ngalan hangtod sa kahangtoran! Ug usab ako moingon, pagkamahimayaon sa tingog nga atong nadungog gikan sa langit, nga nagpahayag sa atong mga dunggan, himaya, ug kaluwasan, ug dungog, ug imortalidad, ug kinabuhing dayon; mga gingharian, kayutaan, ug mga kagamhanan!"},{"verse":24,"text":"Tan-awa, ang mahinungdanon nga adlaw sa Ginoo nagkaduol na; ug kinsa ang makalahutay sa adlaw sa iyang pag-anhi, ug kinsa ang makaharong sa panahon nga magpakita na siya? Kay sama siya sa kalayo sa magtutunaw, ug sama sa sabon sa maglalaba; ug molingkod siya sama sa magtutunaw ug tiglunsay sa pilak, ug himoon niyang lunsay ang mga anak ni Levi, ug hinloan sila sama sa bulawan ug pilak, aron mohalad sila sa Ginoo og usa ka halad sa pagkamatarong. Busa, kita, isip simbahan ug katawhan, ug isip mga Santos sa Ulahing mga Adlaw, mohalad sa Ginoo og usa ka halad sa pagkamatarong; ug mogasa kita sa sulod sa iyang balaan nga templo, sa panahon nga mahuman na kini, og usa ka basahon nga naglangkob sa mga talaan sa atong mga patay, nga takos alang sa tanang pagdawat."},{"verse":25,"text":"Kaigsoonan, ako adunay daghang butang nga isulti kaninyo mahitungod sa maong hilisgotan; apan sa pagkakaron taposon, ug ipadayon ang hilisgotan sa laing higayon. Ako, sa kanunay, ang inyong mapainubsanon nga sulugoon ug matinud-anong higala,"},{"verse":26,"text":"Joseph Smith."}]},{"chapter":129,"verses":[{"verse":1,"text":"Adunay duha ka matang sa mga binuhat sa langit, nga ginganlan og: mga Anghel, nga nabanhaw nga personahe, nga adunay mga lawas nga unod ug mga bukog—"},{"verse":2,"text":"Pananglitan, si Jesus miingon: Hikapa ako ug tan-awa, kay ang usa ka espiritu walay unod ug mga bukog, sama sa inyong nakita kanako."},{"verse":3,"text":"Ikaduha: ang mga espiritu sa mga tawo nga makiangayon nga nahimong hingpit, sila nga wala mabanhaw, apan nakapanunod sa sama nga himaya."},{"verse":4,"text":"Kon ang usa ka mensahero moabot ug moingon nga siya adunay mensahe gikan sa Dios, itunol ang imong kamot kaniya ug hangyoa siya sa pagpakiglamano kanimo."},{"verse":5,"text":"Kon siya usa ka anghel siya mobuhat niini, ug ikaw makahikap sa iyang kamot."},{"verse":6,"text":"Kon siya espiritu sa usa ka makiangayon nga tawo nga nahimong hingpit siya mopakita sa iyang himaya; kay mao lamang kana nga paagi nga siya makapakita—"},{"verse":7,"text":"Hangyoa siya sa pagpakiglamano kanimo, apan dili siya molihok, tungod kay supak kini sa lagda sa langit sa usa ka makiangayon nga tawo nga manglimbong; apan mosulti gihapon siya sa iyang mensahe."},{"verse":8,"text":"Kon kini mao ang yawa nga nagpakaanghel sa kahayag, kon ikaw mohangyo kaniya sa pagpakiglamano siya motunol sa iyang kamot, ug ikaw dili mobati og bisan unsa; busa ikaw makaila kaniya."},{"verse":9,"text":"Mao kini ang tulo ka mahinungdanong mga paagi nga imong masayran kon ang pagpangalagad gikan ba sa Dios."}]},{"chapter":130,"verses":[{"verse":1,"text":"Sa higayon nga ang Manluluwas magpakita kita makakita kaniya ingon nga siya mao siya. Makita nato siya nga usa ka tawo sama sa atong kaugalingon."},{"verse":2,"text":"Ug kanang sama nga pakigrelasyon ngadto sa uban nga atong gitagamtam dinhi magpadayon kanato didto, gawas nga kini ubanan sa mahangtorong himaya, himaya nga wala nato matagamtam karon."},{"verse":3,"text":"Sa Juan 14:23—Ang pagpakita sa Amahan ug sa Anak, niana nga bersikulo, mao ang personal nga pagpakita; ug ang ideya nga ang Amahan ug ang Anak nagpuyo sulod sa kasingkasing sa tawo usa ka kinaraang hunahuna sa sekta, ug bakak kini."},{"verse":4,"text":"Agi og tubag sa pangutana nga—dili ba ang kalkulasyon sa panahon sa Dios, sa panahon sa anghel, sa panahon sa propeta, ug sa panahon sa tawo, nag-agad sa planeta nga ilang gipuy-an?"},{"verse":5,"text":"Motubag ko og, Oo. Apan walay mga anghel kinsa mangalagad niini nga kalibotan apan kadtong sakop o nahisakop niini."},{"verse":6,"text":"Ang mga anghel wala magpuyo sa usa ka planeta nga sama niini nga kalibotan;"},{"verse":7,"text":"Apan nagpuyo sila sa atubangan sa Dios, sa usa ka kalibotan sama sa usa ka dagat nga bildo ug kalayo, diin ang tanang butang alang sa ilang himaya gipakita, ang kaniadto, ang karon, ug ang umaabot, ug sa kanunay anaa sa atubangan sa Ginoo."},{"verse":8,"text":"Ang dapit diin magpuyo ang Dios mao ang dako nga Urim ug Thummim."},{"verse":9,"text":"Kini nga kalibotan, sa pagkabalaan ug pagka-imortal nga kahimtang niini, pagahimoon nga sama sa kristal ug mahimong usa ka Urim ug Thummim ngadto sa mga lumulupyo kinsa mopuyo niini, diin ang tanang butang nga may kalabotan sa mas ubos nga gingharian, o ang tanang gingharian sa mas ubos nga han-ay, ipakita niadtong mopuyo niini; ug kini nga kalibotan maiya ni Kristo."},{"verse":10,"text":"Unya ang puti nga bato nga gisulti sa Pinadayag 2:17, mahimong usa ka Urim ug Thummim ngadto sa matag indibidwal nga makadawat niini, diin ang mga butang nga may kalabotan sa mas taas nga han-ay sa gingharian ipahibalo;"},{"verse":11,"text":"Ug usa ka puti nga bato ihatag sa matag usa niadtong kinsa moadto sa celestial nga gingharian, diin ang bag-o nga ngalan nahisulat, nga walay tawo nga nasayod gawas kaniya nga nakadawat niini. Ang bag-o nga ngalan mao ang sekreto nga pulong."},{"verse":12,"text":"Ako managna, pinaagi sa ngalan sa Ginoong Dios, nga ang sinugdan sa mga kalisdanan nga maoy hinungdan sa pagbanaw sa daghang dugo sa dili pa moanhi ang Anak sa Tawo mahitabo sa Habagatang Carolina."},{"verse":13,"text":"Mahitabo tingali kini pinaagi sa pangutana bahin sa pagkaulipon. Mao kini ang tingog nga gipahayag ngari kanako, samtang ako sinsero nga nag-ampo bahin sa hilisgotan, niadtong ika-25 sa Disyembre, 1832."},{"verse":14,"text":"Sinsero akong nag-ampo aron masayod sa takna sa pag-anhi sa Anak sa Tawo, sa dihang nakadungog ko og tingog nga misubli sa pagsulti sa mosunod:"},{"verse":15,"text":"Joseph, akong anak, kon ikaw mabuhi hangtod sa kawaloan ug lima nga panuigon, ikaw makakita sa nawong sa Anak sa Tawo; busa himoa kini nga igo na, ug ayaw na ako samoka mahitungod niining butanga."},{"verse":16,"text":"Gibiyaan ako sa ingon niini nga kahimtang, nga wala makahukom kon kini nga pag-anhi nagpasabot ba sa sinugdanan sa milenyo o sa ubang nangagi nga pagpakita, o kon ako kinahanglan bang mamatay ug sa ingon niana makakita sa iyang nawong."},{"verse":17,"text":"Naghunahuna ko nga ang pag-anhi sa Anak sa Tawo dili mahimong mas masayo kay sa niana nga panahon."},{"verse":18,"text":"Bisan unsa nga baroganan sa salabotan nga makab-ot nato niining kinabuhia, madala nato kini sa pagkabanhaw."},{"verse":19,"text":"Ug kon ang usa ka tawo makaangkon og daghan pa nga kahibalo ug salabotan niini nga kinabuhi pinaagi sa iyang kakugi ug pagkamasulondon kay sa uban, siya adunay dako kaayong bintaha sa kalibotan nga moabot."},{"verse":20,"text":"Adunay balaod, nga dili mausab nga gipahayag didto sa langit sa wala pa ang mga pundasyon niini nga kalibotan, diin ang tanang panalangin gipasikad—"},{"verse":21,"text":"Ug kon kita makadawat og bisan unsa nga panalangin gikan sa Dios, tungod kini sa pagsunod niana nga balaod diin kini gipasikad."},{"verse":22,"text":"Ang Amahan adunay lawas nga unod ug mga bukog nga mahikap sama sa tawo, ang Anak usab, apan ang Espiritu Santo walay lawas nga unod ug mga bukog, apan usa ka personahe sa Espiritu. Kon dili pa tungod niini, ang Espiritu Santo dili makapuyo sulod kanato."},{"verse":23,"text":"Ang tawo mahimong modawat sa Espiritu Santo, ug mahimo kining mokunsad diha kaniya ug dili magpabilin uban kaniya."}]},{"chapter":131,"verses":[{"verse":1,"text":"Sa celestial nga himaya adunay tulo ka langit o mga ang-ang;"},{"verse":2,"text":"Ug aron maangkon ang labing taas, ang tawo kinahanglang mosulod niini nga kapunongan sa pagkapari [ang gipasabot mao ang bag-o ug walay kataposan nga pakigsaad sa kaminyoon];"},{"verse":3,"text":"Ug kon dili siya mosulod, siya dili makaangkon niini."},{"verse":4,"text":"Siya mahimo nga mosulod ngadto sa lain, apan mao na kana ang kataposan sa iyang gingharian; dili siya makauswag."},{"verse":5,"text":"(Ika-17 sa Mayo, 1843.) Ang mas segurado nga pulong sa panagna nagpasabot nga ang tawo nasayod nga siya naselyo ngadto sa kinabuhing dayon, pinaagi sa pagpadayag ug sa espiritu sa panagna, pinaagi sa gahom sa Balaan nga Pagkapari."},{"verse":6,"text":"Imposible nga ang usa ka tawo maluwas nga walay kahibalo."},{"verse":7,"text":"Walay butang nga maingon nga walay elemento. Ang tanang espiritu mga elemento, apan kini mas dalisay o putli, ug makita lamang sa mas putli nga mga mata;"},{"verse":8,"text":"Dili kita makakita niini; apan sa panahon nga ang atong lawas malimpyohan makita nato nga kining tanan mga elemento."}]},{"chapter":132,"verses":[{"verse":1,"text":"Sa pagkatinuod, sa ingon niana ang Ginoo misulti kanimo akong sulugoong Joseph, kay ikaw nangutana kanako aron makahibalo ug makasabot nganong ako, ang Ginoo, namahayag nga walay sala ang akong mga sulugoon nga sila si Abraham, Isaac, ug Jacob, ingon man usab sila ni Moises, David ug Solomon, nga akong mga sulugoon, kalabot sa baroganan ug doktrina sa ilang pagbaton ug daghang asawa ug mga puyo-puyo—"},{"verse":2,"text":"Tan-awa, ug sud-onga, ako ang Ginoo nga imong Dios, ug motubag kanimo mahitungod niining butanga."},{"verse":3,"text":"Busa, andama ang imong kasingkasing sa pagdawat ug pagsunod sa mga instruksiyon nga sa dili madugay akong ihatag kanimo; kay kadtong tanan nga nakadawat niini nga balaod nga gipadayag ngadto kanila kinahanglan nga mosunod niini nga balaod."},{"verse":4,"text":"Kay tan-awa, ako mopadayag nganha kanimo sa bag-o ug usa ka walay kataposan nga pakigsaad; ug kon ikaw dili mosunod niana nga pakigsaad, ikaw pagasilotan; kay walay usa nga makasalikway niini nga pakigsaad ug tugotan nga makasulod sa akong himaya."},{"verse":5,"text":"Alang sa tanan nga gustong modawat og panalangin sa akong mga kamot kinahanglan nga motuman sa balaod nga gitakda alang niana nga panalangin, ug sa mga kondisyon niini, nga gitukod sa wala pa ang pundasyon sa kalibotan."},{"verse":6,"text":"Ug kalabot sa bag-o ug walay kataposan nga pakigsaad, kini gitukod alang sa kahingpitan sa akong himaya; ug siya nga modawat sa kahingpitan niini kinahanglan nga mosunod sa balaod, o siya pagasilotan, miingon ang Ginoong Dios."},{"verse":7,"text":"Ug sa pagkatinuod sultihan ko kamo, nga ang mga kondisyon niini nga balaod mao kini: Ang tanang pakigsaad, mga kontrata, mga kauyonan, mga obligasyon, mga panumpa, mga saad, mga buluhaton, mga panagkahiusa, mga panag-uban o mga panghinaot, nga wala mahimo ug masulod ngadto ug maselyo pinaagi sa Balaan nga Espiritu sa saad, kaniya kinsa nadihogan, alang sa karon ug alang sa tibuok kahangtoran, ug kana usab nga labing balaan, pinaagi sa pagpadayag ug sugo pinaagi sa sa akong dinihogan, nga akong gitudlo sa yuta sa paghupot niini nga gahom (ug gitudlo nako ang akong sulugoon nga si Joseph sa paghupot niini nga gahom sa kataposan nga mga adlaw, ug walay lain gayod gawas sa usa ka tawo sa ibabaw sa yuta sa usa ka higayon nga tugyanan sa gahom ug mga yawe niini nga pagkapari), walay epekto, katungod o kapuslanan diha o human sa pagkabanhaw gikan sa mga patay; kay ang tanang kontrata nga wala mabuhat diha niini nga katuyoan adunay kataposan kon ang mga tawo patay na."},{"verse":8,"text":"Tan-awa, ang akong balay mao ang balay sa kahusay, miingon ang Ginoong Dios, ug dili usa ka balay sa kalibog."},{"verse":9,"text":"Ako ba modawat sa usa ka halad, miingon ang Ginoo, nga wala himoa pinaagi sa akong ngalan?"},{"verse":10,"text":"O ako ba modawat gikan sa inyong mga kamot nianang wala nako isugo?"},{"verse":11,"text":"Ug ako motudlo ba kanimo, miingon ang Ginoo, gawas kon pinaagi sa balaod, gani ingon nga ako ug ang akong Amahan miorden kanimo, sa wala pa ang kalibotan?"},{"verse":12,"text":"Ako ang Ginoo nga imong Dios; ug ako mohatag kanimo niini nga sugo—nga walay tawo nga makaadto sa Amahan gawas pinaagi kanako o pinaagi sa akong pulong, nga mao ang akong balaod, miingon ang Ginoo."},{"verse":13,"text":"Ug ang tanan nga anaa sa kalibotan, bisan kon giorden man sa mga tawo, pinaagi sa mga trono, o sa mga kayutaan, o sa mga kagamhanan, o sa mga butang nga gibantog, bisan unsa pa man kini, nga dili pinaagi kanako o pinaagi sa akong pulong, miingon ang Ginoo, pagalumpagon ug dili molungtad human ang mga tawo mamatay, ni diha o human sa pagkabanhaw, miingon ang Ginoo nga inyong Dios."},{"verse":14,"text":"Kay ang bisan unsa nga butang molungtad pinaagi kanako; ug bisan unsa nga butang nga dili pinaagi kanako pagatay-ugon ug laglagon."},{"verse":15,"text":"Busa, kon ang usa ka lalaki mangasawa dinhi sa kalibotan, ug siya pangasaw-on niya nga dili pinaagi kanako ni pinaagi sa akong pulong, ug siya makigsaad kaniya hangtod nga siya ania sa kalibotan, ug ang asawa ngadto sa bana, ang ilang pakigsaad ug kaminyoon walay epekto unya kon sila patay na, ug kon wala na sila sa kalibotan; busa, wala sila mabugkos sa bisan unsa nga balaod kon wala na sila sa kalibotan."},{"verse":16,"text":"Busa, kon wala na sila sa kalibotan wala sila maminyo ni gihatag ngadto sa kaminyoon; apan gipili nga mga anghel didto sa langit, diin nga mga anghel mga tigpangalagad nga sulugoon, sa pagpangalagad alang niadtong mga takos og dugang pa, ug naghingapin, ug mahangtorong gidaghanon nga himaya."},{"verse":17,"text":"Kay kini nga mga anghel wala mosunod sa akong balaod; busa dili sila mouswag, apan magpabilin nga linain ug mag-inusara, walay kahimayaan, diha sa ilang naluwas nga kahimtang, ngadto sa tibuok kahangtoran; ug sukad niana dili mga dios; apan mga anghel sa Dios hangtod sa kahangtoran."},{"verse":18,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kon ang tawo mangasawa, ug mohimo og pakigsaad uban kaniya alang sa karon ug alang sa tibuok kahangtoran, kon kana nga pakigsaad dili pinaagi kanako o pinaagi sa akong pulong, nga mao ang akong balaod, ug wala maselyo pinaagi sa Balaang Espiritu sa saad, pinaagi kaniya nga akong gidihogan ug gipahimutang ngadto niini nga gahom, nan kini dili balido o walay kapuslanan kon sila wala na sa kalibotan, tungod kay wala sila mahiusa pinaagi kanako, miingon ang Ginoo, ni pinaagi sa akong pulong; kon wala na sila sa kalibotan kini dili madawat didto, tungod kay ang mga anghel ug mga dios ang gitudlo didto, diin dili sila mahimong moagi; busa, dili sila makapanunod sa akong himaya; kay ang akong balay usa ka balay sa kahusay; miingon ang Ginoong Dios."},{"verse":19,"text":"Ug usab, sa pagkatinuod sultihan ko kamo, kon ang lalaki mangasawa pinaagi sa akong pulong, nga mao ang akong balaod, ug pinaagi sa bag-o ug walay kataposan nga pakigsaad, ug giselyo kini ngadto kanila pinaagi sa Balaan nga Espiritu sa saad, pinaagi kaniya kinsa nadihogan, nga akong gihatagan niini nga gahom ug mga yawe niini nga pagkapari; ug kini isulti ngadto kanila—Kamo mobangon sa unang pagkabanhaw; ug kon kini human sa unang pagkabanhaw, nan sa sunod nga pagkabanhaw; ug makapanunod og mga trono, mga gingharian, mga kayutaan, ug mga kagamhanan, kamandoan, tanang butang sa kahitas-an ug kahiladman—dayon isulat kini sa Basahon sa Kinabuhi sa Kordero, nga wala siyay nahimo nga pagpatay nga mopaagas og dugo sa walay sala, ug kon ikaw mosunod sa akong pakigsaad, ug walay nahimo nga pagpatay nga mopaagas sa dugo sa walay sala, kini pagahimoon ngadto kanila sa tanang butang bisan unsa ang gibutang sa akong sulugoon diha kanila, karon ug sa tibuok kahangtoran; ug hingpit nga moepekto kon wala na sila sa kalibotan; ug moagi sila sa mga anghel, ug sa mga dios, nga gibutang didto, ngadto sa ilang kahimayaan ug himaya sa tanang butang, sumala sa naselyo sa ilang mga ulo, diin nga himaya mao ang kahingpitan ug pagpadayon sa mga binhi hangtod sa kahangtoran."},{"verse":20,"text":"Dayon mahimo silang mga dios, tungod kay wala na silay kataposan; busa sila mahimong walay sinugdanan ug walay kataposan, tungod kay sila magpadayon; dayon sila mahimong labaw sa tanan, tungod kay ang tanang butang ubos kanila. Unya sila mahimong mga dios, tungod kay sila aduna sa tanang gahom, ug ang mga anghel ubos kanila."},{"verse":21,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, gawas kon kamo mosunod sa akong balaod dili ninyo makab-ot kini nga himaya."},{"verse":22,"text":"Kay higpit ang ganghaan, ug pig-ot ang agianan nga padulong sa kahimayaan ug sa pagpadayon sa mga kinabuhi, ug pipila lang ang makakita niini, tungod kay wala kamo modawat kanako dinhi sa kalibotan ug wala kamo makaila kanako."},{"verse":23,"text":"Apan kon modawat kamo kanako sa kalibotan, nan makaila kamo kanako, ug makadawat sa inyong kahimayaan; nga kon asa ako anaa usab kamo."},{"verse":24,"text":"Mao kini ang mga kinabuhing dayon—nga makaila sa bugtong maalamon ug tinuod nga Dios, ug ni Jesukristo, nga iyang gipadala. Ako mao siya. Busa, dawata ninyo ang akong balaod."},{"verse":25,"text":"Lapad ang ganghaan, ug sayon ang dalan nga padulong sa kalaglagan; ug daghan ang misulod niini, tungod kay sila wala modawat kanako, ni sila mosunod sa akong balaod."},{"verse":26,"text":"Sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, kon ang tawo mangasawa sumala sa akong pulong, ug naselyo sila sa Balaan nga Espiritu sa saad, sumala sa akong pagtudlo, ug ang lalaki o babaye makasala o makalapas sa bag-o ug walay kataposan nga pakigsaad sa bisan unsa pa, ug tanang matang sa mga pagpanamastamas, ug kon sila wala mohimo og pagpatay nga sila mopaagas og dugo sa walay sala, mobangon sila sa unang pagkabanhaw, ug mosulod sa ilang kahimayaan; apan sila pagalaglagon dinhi sa unod, ug itugyan sa mga pagsakit ni Satanas ngadto sa adlaw sa katubsanan, miingon ang Ginoong Dios."},{"verse":27,"text":"Ang pagpanamastamas batok sa Espiritu Santo, nga dili mapasaylo dinhi sa kalibotan o gawas sa kalibotan, mahitabo kon kamo nakapatay nga nakapaagas kamo og dugo sa walay sala, ug mitabang sa pagpahitabo sa akong kamatayon, human madawat ninyo ang akong bag-o ug walay kataposan nga pakigsaad, miingon ang Ginoong Dios; ug siya nga dili mosunod niini nga balaod dili gayod makasulod sa akong himaya, apan pagasilotan, miingon ang Ginoo."},{"verse":28,"text":"Ako mao ang Ginoo nga inyong Dios, ug mohatag kaninyo sa balaod sa akong Balaan nga Pagkapari, nga gi-orden pinaagi kanako ug sa akong Amahan sa wala pa ang kalibotan."},{"verse":29,"text":"Si Abraham nakadawat sa tanang butang, bisan unsa ang iyang nadawat, pinaagi sa pagpadayag ug sa sugo, pinaagi sa akong pulong, miingon ang Ginoo, ug misulod sa iyang kahimayaan ug milingkod diha sa iyang trono."},{"verse":30,"text":"Si Abraham nakadawat og mga saad mahitungod sa iyang binhi, ug mga kaliwatan—kang kinsa nga mga kaliwatan kamo nagagikan, nga mao, ang akong sulugoon nga si Joseph—nga mopadayon samtang anaa pa sila sa kalibotan; ug mahitungod ni Abraham ug sa iyang binhi, sa gawas sa kalibotan sila magpadayon; diha sa kalibotan ug gawas sa kalibotan magpadayon sila sama sa mga bituon nga dili maihap; o, kon kamo moihap sa balas sa baybayon dili ninyo kini maihap."},{"verse":31,"text":"Kini nga saad mainyo usab, tungod kay kamo gikan ni Abraham, ug ang saad nahimo ngadto ni Abraham; ug pinaagi niini nga balaod magpadayon ang mga buhat sa akong Amahan, diin gihimaya niya ang iyang kaugalingon."},{"verse":32,"text":"Busa, panglakaw, ug buhata ang mga buhat ni Abraham; sulod kamo sa akong balaod ug kamo maluwas."},{"verse":33,"text":"Apan kon dili kamo mosulod sa akong balaod dili kamo makadawat sa saad sa akong Amahan, nga iyang gihimo ngadto ni Abraham."},{"verse":34,"text":"Ang Dios misugo ni Abraham, ug si Sara mihatag ni Agar ngadto ni Abraham aron pangasaw-on. Ug nganong gibuhat man kini niya? Tungod kay kini ang balaod; ug gikan ni Agar naggikan ang daghang katawhan. Busa, mao kini ang katumanan sa ubang butang, sa mga saad."},{"verse":35,"text":"Busa, ubos ba si Abraham sa silot? Sa pagkatinuod sultihan ko kamo, Dili; kay ako, ang Ginoo, ang misugo niini."},{"verse":36,"text":"Gisugo si Abraham sa paghalad sa iyang anak nga si Isaac; bisan pa niana, nahisulat nga: Dili ikaw mopatay. Si Abraham, bisan pa niana, wala mobalibad, ug giisip kini nga matarong ngadto kaniya."},{"verse":37,"text":"Midawat si Abraham og mga puyo-puyo, ug nakabaton sila kaniya og mga anak; ug kini giisip nga matarong ngadto kaniya, tungod kay gihatag sila ngadto kaniya, ug gituman niya ang akong balaod; ingon man usab si Isaac ug si Jacob wala mohimo og laing mga butang gawas nianang gisugo kanila; ug tungod kay wala sila mohimo og lain nga mga butang gawas nianang gisugo kanila, misulod sila ngadto sa ilang kahimayaan, sumala sa mga saad, ug naglingkod diha sa mga trono, ug dili mga anghel apan mga dios."},{"verse":38,"text":"Si David usab nakadawat og daghang asawa ug mga puyo-puyo, ug usab si Solomon ug si Moises nga akong mga sulugoon, ingon man usab ang akong daghan pang sulugoon, gikan sa sinugdanan sa paglalang hangtod niining panahona; ug wala gayod sila makasala gawas niadtong mga butang nga ilang nadawat nga dili gikan kanako."},{"verse":39,"text":"Ang mga asawa ug mga puyo-puyo ni David gihatag ngadto kaniya gikan kanako, pinaagi sa kamot ni Natan, nga akong sulugoon, ug ang ubang mga propeta kinsa may mga yawe niini nga gahom; ug wala siya makasala niining mga butanga batok kanako gawas sa hitabo ni Uria ug sa iyang asawa; ug, busa napukan siya gikan sa iyang kahimayaan, ug nakadawat sa iyang bahin; ug dili siya makapanunod niini kon wala na sa kalibotan, kay gihatag nako kini ngadto sa lain, miingon ang Ginoo."},{"verse":40,"text":"Ako ang Ginoo nga imong Dios, ug mohatag ako kanimo, akong sulugoong Joseph, og usa ka katungdanan, ug ipahiuli ang tanang butang. Pangayo unsa ang imong buot pangayoon, ug ihatag kini kanimo sumala sa akong pulong."},{"verse":41,"text":"Ug kay nangutana ka mahitungod sa pagpanapaw, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, kon ang usa ka tawo modawat og asawa sa bag-o ug walay kataposan nga pakigsaad, ug kon mouban siya sa lain nga lalaki, ug wala nako itudlo ngadto kaniya pinaagi sa balaan nga pagdihog, siya nakahimo og panapaw ug pagalaglagon."},{"verse":42,"text":"Kon wala siya mosulod sa bag-o ug walay kataposan nga pakigsaad, ug mouban siya sa lain nga lalaki, siya nakahimo og panapaw."},{"verse":43,"text":"Ug kon ang iyang bana mouban sa lain nga babaye, ug siya ubos sa usa ka panaad, nakasupak siya sa iyang panaad ug nakahimo og pagpanapaw."},{"verse":44,"text":"Ug kon ang asawa wala makapanapaw, apan inosente ug wala makasupak sa iyang panaad, ug siya nasayod niini, ug kini gipadayag ko kanimo, akong sulugoong Joseph, nan ikaw adunay gahom, pinaagi sa gahom sa akong Balaan nga Pagkapari, sa paghatag sa babaye ngadto kaniya nga wala makapanapaw apan nagmatinud-anon; kay pagahimoon siya nga tigmando sa kadaghanan."},{"verse":45,"text":"Kay akong gitugyan kanimo ang mga yawe ug gahom sa pagkapari, diin ipahiuli nako ang tanang butang, ug ipahibalo kanimo ang tanang butang sa tukma nga panahon."},{"verse":46,"text":"Ug sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, nga bisan unsa ang imong iselyo dinhi sa yuta maselyo didto sa langit; ug bisan unsa ang imong bugkoson dinhi sa yuta, pinaagi sa akong ngalan ug pinaagi sa akong pulong, miingon ang Ginoo, mahangtoron kining mabugkos didto sa kalangitan; ug ang mga sala ni bisan kinsa nga imong pasayloon dinhi sa yuta pasayloon sa kahangtoran didto sa kalangitan; ug ang mga sala ni bisan kinsa nga magpabilin dinhi sa yuta magpabilin didto sa langit."},{"verse":47,"text":"Ug usab, sa pagkatinuod moingon ko, si bisan kinsa nga imong panalanginan akong panalanginan, ug si bisan kinsa nga imong tunglohon akong tunglohon, miingon ang Ginoo; kay ako, ang Ginoo, mao ang imong Dios."},{"verse":48,"text":"Ug usab, sa pagkatinuod sultihan ko ikaw, akong sulugoong Joseph, nga bisan unsa ang imong ihatag dinhi sa yuta, ug si bisan kinsa nga imong hatagan dinhi sa yuta, pinaagi sa akong pulong ug sumala sa akong balaod, pagahatagan og mga panalangin ug dili mga tunglo, ug sa akong gahom, miingon ang Ginoo, ug walay panghimaraot dinhi sa yuta ug didto sa langit."},{"verse":49,"text":"Kay ako ang Ginoo nga imong Dios, ug mag-uban kanimo gani ngadto sa kinatumyan sa kalibotan, ug hangtod sa tibuok kahangtoran; kay sa pagkatinuod iselyo nako diha kanimo ang imong kahimayaan, ug moandam og usa ka trono alang kanimo sa gingharian sa akong Amahan, uban ni Abraham nga imong amahan."},{"verse":50,"text":"Tan-awa, nakita nako ang imong mga sakripisyo, ug mopasaylo sa imong tanang sala; nakita nako ang imong mga sakripisyo sa pagsunod nianang akong gisulti kanimo. Busa, lakaw, ug mangita ko og paagi sa imong pag-ikyas, sama sa akong pagdawat sa paghalad ni Abraham sa iyang anak nga si Isaac."},{"verse":51,"text":"Sa pagkatinuod, sultihan ko ikaw: Usa ka sugo akong ihatag sa akong sulugoon, si Emma Smith, ang imong asawa, nga akong gihatag kanimo, nga pugngan niya ang iyang kaugalingon ug dili moambit nianang akong gisugo kanimo nga ihalad ngadto kaniya; kay ako mihimo niini, miingon ang Ginoo, sa pagsulay kanimo sa tanan, sama sa akong gibuhat ni Abraham, ug aron momando ako kanimo nga mohatag og halad, pinaagi sa pakigsaad ug sakripisyo."},{"verse":52,"text":"Ug ipadawat sa akong sulugoon nga si Emma Smith, ang tanang gihatag ngadto sa akong sulugoon nga si Joseph, ug kinsa mahiyason ug putli sa akong atubangan; ug kadtong mga dili putli ug miingon nga putli sila, pagalaglagon, miingon ang Ginoong Dios."},{"verse":53,"text":"Kay ako ang Ginoo nga imong Dios, ug ikaw mosunod sa akong tingog; ug motugot ko sa akong sulugoon nga si Joseph nga siya pagahimoon nga tigdumala sa daghang butang; kay siya nagmatinud-anon sa pipila ka butang, ug gikan karon lig-onon ko siya."},{"verse":54,"text":"Ug sugoon nako ang akong sulugoon nga babaye, nga si Emma Smith, sa pagsunod ug pag-unong sa akong sulugoon nga si Joseph, ug wala nay lain. Apan kon dili siya mosunod niini nga sugo siya pagalaglagon, miingon ang Ginoo; kay ako ang Ginoo nga imong Dios, ug molaglag kaniya kon dili siya mosunod sa akong balaod."},{"verse":55,"text":"Apan kon dili siya mosunod niini nga sugo, nan ang akong sulugoon nga si Joseph mohimo sa tanang butang alang kaniya, bisan sumala sa iyang gisulti; ug panalanginan nako siya ug mopasanay og kaliwatan kaniya ug mohatag ngadto kaniya og gatosan ka pilopilo dinhi niini nga kalibotan, sa mga amahan, ug sa mga inahan, mga igsoon nga lalaki ug babaye, mga balay ug mga yuta, mga asawa ug mga anak, ug mga korona sa kinabuhing dayon didto sa mahangtorong mga kalibotan."},{"verse":56,"text":"Ug usab, sa pagkatinuod ako moingon, kinahanglan nga ang akong sulugoon nga babaye mopasaylo sa akong sulugoon nga si Joseph sa iyang mga kalapasan; ug niini siya mapasaylo sa iyang kalapasan, nga iyang nalapas batok kanako; ug ako, ang Ginoo nga imong Dios, mopanalangin kaniya, ug mopasanay og kaliwatan kaniya, ug molipay sa iyang kasingkasing."},{"verse":57,"text":"Ug usab, ako moingon, ayaw ipabaligya sa akong sulugoon nga si Joseph ang iyang kabtangan, basin unya og ang kaaway moabot ug molaglag kaniya; kay si Satanas nagtinguha sa paglaglag; kay ako ang Ginoo nga imong Dios, ug siya akong sulugoon; ug tan-awa, ug sud-onga, ubanan ko siya, sama nga ako miuban ni Abraham, nga inyong amahan, gani ngadto sa iyang kahimayaan ug himaya."},{"verse":58,"text":"Karon, kon kabahin sa balaod sa pagkapari, adunay daghan pang butang mahitungod niana."},{"verse":59,"text":"Sa pagkatinuod, kon ang usa ka tawo tawagon sa akong Amahan, sama ni Aaron, pinaagi sa akong kaugalingon nga tingog, ug pinaagi sa iyang tingog nga nagpadala kanako, ug siya akong gitugahan sa mga yawe sa gahom niini nga pagkapari, kon mohimo siya og bisan unsa nga butang pinaagi sa akong ngalan, ug sumala sa akong balaod ug pinaagi sa akong pulong, dili siya makahimo og sala, ug ako mohukom nga siya walay sala."},{"verse":60,"text":"Busa, kinahanglan nga walay usa, nga mosaway sa akong sulugoon nga si Joseph; kay mopahayag ko nga siya walay sala; kay mohimo siya sa sakripisyo nga akong gipabuhat sa iyang mga kamot tungod sa iyang mga kalapasan, miingon ang Ginoo nga imong Dios."},{"verse":61,"text":"Ug usab, kabahin sa balaod sa pagkapari—kon si bisan kinsa nga tawo nga mangasawa og birhen, ug may tinguha nga mangasawa og lain, ug ang una mohatag sa iyang pag-uyon, ug kon siya mangasawa sa ikaduha, ug sila mga birhen, ug wala maminyo ngadto sa laing tawo, niana wala siya makasala; wala siya makapanapaw kay gihatag sila ngadto kaniya; kay wala siya makapanapaw nianang iyaha ug dili sa lain."},{"verse":62,"text":"Ug kon siya adunay napulo ka birhen nga gihatag ngadto kaniya pinaagi niini nga balaod, siya wala makapanapaw, kay sila iyaha, ug gihatag sila ngadto kaniya; busa wala siya makasala."},{"verse":63,"text":"Apan kon ang usa o bisan hain sa napulo ka birhen, human siya gipangasawa, mouban og lain nga lalaki, siya nakapanapaw, ug pagalaglagon; kay gihatag sila ngadto kaniya aron mosanay ug mopuno sa yuta, sumala sa akong sugo, ug sa pagtuman sa saad nga gihatag sa akong Amahan sa wala pa ang pundasyon sa kalibotan, ug alang sa ilang kahimayaan sa mahangtorong mga kalibotan, aron sila modala sa mga kalag sa mga tawo; kay niini magpadayon ang buhat sa akong Amahan, aron siya pagahimayaon."},{"verse":64,"text":"Ug usab, sa pagkatinuod, sa pagkatinuod, sultihan ko kamo, kon si bisan kinsa nga tawo adunay asawa, nga naghupot sa mga yawe niini nga gahom, ug tudloan niya siya sa balaod sa akong pagkapari, kalabot niining mga butanga, nan siya motuo ug moalagad kaniya, o pagalaglagon siya, miingon ang Ginoo nga imong Dios; kay laglagon nako siya; kay pasidunggan nako ang akong ngalan niadtong tanan nga modawat ug mosunod sa akong balaod."},{"verse":65,"text":"Busa, makataronganon ngari kanako, kon ang babaye dili modawat niini nga balaod, aron makadawat ang lalaki sa tanang butang bisan unsa nga, ako, ang Ginoo nga iyang Dios, mohatag kaniya, tungod kay ang babaye wala motuo ug moalagad sa lalaki sumala sa akong pulong; ug niana nahimo siyang malapason; ug siya walay labot gikan sa balaod ni Sara, nga mialagad ni Abraham sumala sa balaod sa dihang gisugo nako si Abraham sa pagpangasawa ni Agar."},{"verse":66,"text":"Ug karon, kalabot niini nga balaod, sa pagkatinuod, sa pagkatinuod, sultihan ko ikaw, mas daghan ko og ipadayag kanimo, sa umaabot; busa, himoa kini nga igò sa pagkakaron. Tan-awa, ako mao ang Alpha ug Omega. Amen."}]},{"chapter":133,"verses":[{"verse":1,"text":"Patalinghog, O kamo nga katawhan sa akong simbahan, miingon ang Ginoo nga inyong Dios, ug paminaw sa pulong sa Ginoo mahitungod kaninyo—"},{"verse":2,"text":"Ang Ginoo kinsa kalit nga moabot sa iyang templo; ang Ginoo kinsa manaog sa kalibotan uban ang usa ka tunglo sa paghukom; oo, sa tanang nasod nga nakalimot sa Dios, ug sa tanang dili diosnon taliwala kaninyo;"},{"verse":3,"text":"Kay siya mopakita sa iyang balaan nga bukton sa mga mata sa tanang nasod, ug ang tanang katawhan makakita sa kaluwasan sa ilang Dios."},{"verse":4,"text":"Mao nga, pag-andam kamo, pag-andam kamo, O akong katawhan; balaana ang inyong mga kaugalingon; pagpundok kamo, O kamong katawhan sa akong simbahan, diha sa yuta sa Zion, kamong tanan nga wala sugoa sa pagpabilin."},{"verse":5,"text":"Panggawas kamo gikan sa Babilonia. Pagmalimpyo kamo nga nagdala sa mga sudlanan sa Ginoo."},{"verse":6,"text":"Tawga ang inyong maligdong nga mga katigoman, ug hisgoti kanunay ang mga butang sa Ginoo ngadto sa usag usa. Ug kinahanglan nga ang matag tawo motawag sa ngalan sa Ginoo."},{"verse":7,"text":"Oo, sa pagkatinuod sultihan ko kamo pag-usab, miabot na ang panahon nga ang tingog sa Ginoo anaa kaninyo: Panggawas kamo gikan sa Babilonia; pagpundok kamo gikan sa mga nasod, gikan sa upat ka direksyon sa yuta, gikan sa usa ka tumoy sa langit ngadto sa lain."},{"verse":8,"text":"Ipadala ang mga elder sa akong simbahan ngadto sa lagyo nga mga nasod; ngadto sa mga isla sa dagat; ipadala ngadto sa langyaw nga mga yuta; tawga ang tanang nasod, unaha ang mga Hentil, ug unya ang mga Judeo."},{"verse":9,"text":"Ug tan-awa, ug sud-onga, mao kini ang ilang ipahayag, ug ang tingog sa Ginoo ngadto sa tanang katawhan: Panglakaw kamo ngadto sa yuta sa Zion, aron ang mga utlanan sa akong katawhan mapalapdan, ug nga ang iyang mga stake malig-on ug nga ang Zion mokanap sa mga rehiyon sa palibot."},{"verse":10,"text":"Oo, kinahanglan nga ang pahayag moabot ngadto sa tanang katawhan: Pagmata ug bangon ug lakaw aron sugaton ang Pamanhonon; tan-awa ug sud-onga, ang Pamanhonon moabot; panggawas kamo aron sugaton siya. Andama ang inyong mga kaugalingon alang sa mahinungdanong nga adlaw sa atong Ginoo."},{"verse":11,"text":"Busa, pagbantay, kay kamo wala masayod sa adlaw o sa takna."},{"verse":12,"text":"Busa, sila nga anaa sa taliwala sa mga Hentil kinahanglan nga modangop sa Zion."},{"verse":13,"text":"Ug sila nga sakop ni Juda modangop sa Jerusalem, ngadto sa kabukiran sa balay sa Ginoo."},{"verse":14,"text":"Panggawas kamo gikan sa mga nasod, bisan gikan sa Babilonia, gikan sa taliwala sa pagkadaotan, nga mao ang espirituwal nga Babilonia."},{"verse":15,"text":"Apan sa pagkatinuod, miingon ang Ginoo, ayaw kamo pagdali, apan kinahanglan nga ang tanang butang maandam sa inyong atubangan; ug siya nga molakaw, ayaw siya palingia basin pa unya og ang kalit nga kalaglagan moabot kaniya."},{"verse":16,"text":"Patalinghog ug paminaw, O kamong mga lumulupyo sa yuta. Paminaw, kamong mga elder sa akong simbahan, ug paminawa ang tingog sa Ginoo; kay siya nagtawag sa tanang tawo, ug siya nagsugo sa tanang tawo sa tanang dapit sa paghinulsol."},{"verse":17,"text":"Kay tan-awa, ang Ginoong Dios mipadala sa anghel nga nagsinggit sa taliwala sa langit, nag-ingon: Andama ang agianan sa Ginoo, ug himoa ang iyang mga agianan nga tul-id, kay ang takna sa iyang pag-anhi duol na—"},{"verse":18,"text":"Sa panahon nga ang Kordero mobarog sa Bukid sa Zion, ug uban kaniya ang gatosan ug kap-atan ug upat ka libo, nga ang ngalan sa iyang Amahan nakasulat sa ilang mga agtang."},{"verse":19,"text":"Mao nga, pag-andam kamo alang sa pag-anhi sa Pamanhonon; panglakaw kamo, panggawas kamo aron sugaton siya."},{"verse":20,"text":"Kay tan-awa, mobarog siya sa bukid sa Olivet, ug sa lapad nga mga lawod, gani sa dakong lawod, ug sa mga isla sa dagat, ug sa yuta sa Zion."},{"verse":21,"text":"Ug mamulong siya gikan sa Zion, ug mosulti siya gikan sa Jerusalem, ug ang iyang tingog mabati sa tanang katawhan;"},{"verse":22,"text":"Ug kini usa ka tingog sama sa dahunog sa daghang katubigan, ug sama sa tingog sa usa ka kusog nga dugdog, nga mopatag sa kabukiran, ug ang mga walog mahanaw."},{"verse":23,"text":"Mandoan niya ang dakong lawod, ug kini moatras pabalik ngadto sa amihanang mga nasod, ug ang mga isla mahimong usa ka yuta;"},{"verse":24,"text":"Ug ang yuta sa Jerusalem ug ang yuta sa Zion mobalik sa ilang kaugalingong dapit, ug ang yuta mahisama ingon sa mga adlaw sa wala pa kini mabahin."},{"verse":25,"text":"Ug ang Ginoo, gani ang Manluluwas, mobarog taliwala sa iyang katawhan, ug mohari sa tanang tawo."},{"verse":26,"text":"Ug sila nga anaa sa amihanang mga nasod moduol sa paghinumdom sa atubangan sa Ginoo; ug ang ilang mga propeta maminaw sa iyang tingog ug dili na mapugngan sa ilang kaugalingon; ug ilang bunalan ang dagkong mga bato, ug ang yelo modagayday sa ilang atubangan."},{"verse":27,"text":"Ug usa ka dakong dalan ang matukod sa taliwala sa dakong lawod."},{"verse":28,"text":"Ang ilang mga kaaway mahimo nilang mga bihag."},{"verse":29,"text":"Ug sa panas nga mga desiyerto mogawas ang lim-aw sa buhi nga tubig; ug ang uga nga yuta dili na mahimo nga uhaw nga yuta."},{"verse":30,"text":"Ug dad-on nila ang ilang daghang bahandi ngadto sa mga anak ni Ephraim, ang akong mga sulugoon."},{"verse":31,"text":"Ug ang mga utlanan sa walay kataposan nga kabungtoran mokurog sa ilang atubangan."},{"verse":32,"text":"Ug didto moluhod sila ug koronahan sa himaya, gani sa Zion, pinaagi sa mga kamot sa mga sulugoon sa Ginoo, gani sa mga anak ni Ephraim."},{"verse":33,"text":"Ug mapuno sila sa mga awit sa walay kataposan nga kalipay."},{"verse":34,"text":"Tan-awa, mao kini ang panalangin sa walay kataposan nga Dios sa mga tribo ni Israel, ug ang daghang panalangin sa ulo ni Ephraim ug sa iyang mga kauban."},{"verse":35,"text":"Ug usab sila nga gikan sa mga tribo ni Juda, human sa ilang kasakit, pagasantoson sa kabalaan sa atubangan sa Ginoo, aron mopuyo sa iyang atubangan adlaw ug gabii, hangtod sa kahangtoran."},{"verse":36,"text":"Ug karon, sa pagkatinuod miingon ang Ginoo, nga kining mga butanga inyo untang mahibaloan, O mga lumulupyo sa yuta, gipadala nako ang akong anghel nga naglupad sa taliwala sa langit, nga adunay walay kataposan nga ebanghelyo, kinsa nagpakita sa uban ug nagtugyan niini ngadto sa tawo, nga mopakita sa kadaghanan nga nagpuyo sa yuta."},{"verse":37,"text":"Ug kini nga ebanghelyo isangyaw ngadto sa matag, kanasoran ug kaliwatan, ug pinulongan, ug katawhan."},{"verse":38,"text":"Ug ang mga sulugoon sa Dios manglakaw, mosulti sa makusog nga tingog: Kahadloki ang Dios ug ihatag ang himaya ngadto kaniya, kay ang takna sa iyang paghukom moabot;"},{"verse":39,"text":"Ug mosimba kaniya nga nagbuhat sa langit, ug sa yuta, ug sa dagat, ug sa mga tuburan sa mga tubig—"},{"verse":40,"text":"Motawag sa ngalan sa Ginoo adlaw ug gabii, mag-ingon: O nga ikaw mobukas sa mga langit, nga ikaw manaog, aron ang kabukiran mapatag sa imong atubangan."},{"verse":41,"text":"Ug kini pagatubagon diha sa ilang mga ulo; kay ang presensya sa Ginoo sama sa nagdilaab nga kalayo nga makatunaw, ug ang kalayo nga mopabukal sa katubigan."},{"verse":42,"text":"O Ginoo, manaog ka aron mailhan ang imong ngalan ngadto sa imong mga kaaway, ug ang tanang kanasoran mokurog sa imong atubangan—"},{"verse":43,"text":"Sa panahon nga maghimo ka og makalilisang nga mga buhat, nga wala nila paabota;"},{"verse":44,"text":"Oo, sa panahon nga ikaw manaog, ang kabukiran mapatag sa imong atubangan, ikaw mosugat kaniya nga nagmaya ug nagbuhat sa pagkamatarong, nga naghinumdom kanimo sa imong mga paagi."},{"verse":45,"text":"Kay sukad sa sinugdanan sa kalibotan ang tawo wala makadungog ni makasabot pinaagi sa dalunggan, ni adunay mata nga nakakita, O Dios, gawas kanimo, kon unsa ka nindot sa mga butang nga imong giandam alang kaniya nga naghulat kanimo."},{"verse":46,"text":"Ug ginaingon: Kinsa kining manaog gikan sa Dios sa langit nga tinina ang mga sapot; oo, gikan sa mga rehiyon nga wala mailhi, sinul-oban sa iyang mahimayaon nga panapot, nagpanaw pinaagi sa kahalangdon sa iyang gahom?"},{"verse":47,"text":"Ug siya moingon: Ako mao siya nga nagsulti sa pagkamatarong, adunay gahom nga moluwas."},{"verse":48,"text":"Ug ang Ginoo magsul-ob og pula, ug ang iyang mga sapot sama kaniya nga nagpuga og ubas."},{"verse":49,"text":"Ug hilabihan kadako sa himaya sa iyang atubangan nga ang adlaw motago sa iyang nawong sa kaulaw, ug ang bulan magdumili sa pagsiga, ug ang mga bituon balhinon gikan sa ilang mga dapit."},{"verse":50,"text":"Ug ang iyang tingog madungog: Gitunob-tunoban nako ang intosan sa ubas nga nag-inusara, ug nagdala og paghukom sa tanang katawhan; ug walay usa nga mitabang kanako;"},{"verse":51,"text":"Ug sa akong kasuko gitamak-tamakan ko kini, ug sa akong kalagot kini akong gitunob-tunoban, ug nahumod ang akong bisti sa ilang dugo, ug namantsahan ang tibuok kong sinina, kay kini mao ang adlaw sa pagpanimalos nga anaa sa akong kasingkasing."},{"verse":52,"text":"Ug miabot na ang panahon nga luwason ko ang akong katawhan; ug hisgotan nila ang mahigugmaon nga kaluoy sa ilang Ginoo, ug ang tanan nga iyang nahatag kanila sumala sa iyang kaayo, ug sumala sa iyang mahigugmaon nga kaluoy, hangtod sa kahangtoran."},{"verse":53,"text":"Sa ilang tanan nga kasakit siya ang gisakit. Ug ang anghel sa iyang atubangan miluwas kanila; ug pinaagi sa iyang gugma, ug pinaagi sa iyang kaluoy, gitubos niya sila, ug miagak kanila, ug midala kanilang tanan sa mga adlaw sa karaan;"},{"verse":54,"text":"Oo, ug si Enoch usab, ug sila nga uban kanila; ang mga propeta nga nag-una kaniya; ug si Noe usab, ug sila nga nag-una kaniya ug si Moises usab, ug sila nga nag-una kaniya,"},{"verse":55,"text":"Ug gikan ni Moises ngadto ni Elijah, ug gikan ni Elijah ngadto ni Juan, nga kauban ni Kristo sa iyang pagkabanhaw, ug ang balaan nga apostoles, uban kang Abraham, Isaac, ug Jacob, anaa sa atubangan sa Kordero."},{"verse":56,"text":"Ug ang mga lubnganan sa mga santos maabli; ug mabanhaw sila ug mobarog sa tuo nga bahin sa Kordero, sa panahon nga siya mobarog sa Bukid sa Zion, ug sa balaan nga siyudad, ang Bag-ong Jerusalem; ug moawit sila sa awit sa Kordero, adlaw ug gabii hangtod sa kahangtoran."},{"verse":57,"text":"Ug tungod niini nga hinungdan, nga ang mga tawo mahimong tig-ambit sa mga himaya nga ipadayag pa, ang Ginoo mipadala sa kahingpitan sa iyang ebanghelyo, ang iyang walay kataposan nga pakigsaad, nga nagpahayag diha sa katin-aw ug kayano—"},{"verse":58,"text":"Aron maandam ang mga mahuyang alang niadtong mga butang nga moabot sa yuta, ug alang sa buluhaton sa Ginoo sa adlaw nga ang mga huyang mopakaulaw sa mga maalamon, ug ang usa ka huyang mahimong lig-on nga nasod, ug pinaagi sa duha ka tawo ang ilang napulo ka libo managan sa kahadlok."},{"verse":59,"text":"Ug pinaagi sa huyang nga mga butang sa yuta yatakan sa Ginoo ang kanasoran pinaagi sa gahom sa iyang Espiritu."},{"verse":60,"text":"Ug tungod niini nga hinungdan kini nga mga sugo gihatag; gisugo sila sa pagtago niini gikan sa kalibotan sa adlaw nga kini gihatag kanila, apan karon ihatag sa tanang tawo—"},{"verse":61,"text":"Ug sumala kini sa hunahuna ug kabubut-on sa Ginoo, kinsa nagmando ibabaw sa tanang tawo."},{"verse":62,"text":"Ug ngadto kaniya nga maghinulsol ug magbalaan sa iyang kaugalingon sa atubangan sa Ginoo pagahatagan og kinabuhing dayon."},{"verse":63,"text":"Ug sila nga dili mopatalinghog sa tingog sa Ginoo matuman kanang gisulat ni propeta Moises, nga sila pagapuohon gikan sa taliwala sa katawhan."},{"verse":64,"text":"Ug usab kanang gisulat ni propeta Malaquias: Kay, tan-awa, ang adlaw moabot nga ang tanang mapahitas-on ug daotan sunogon ingon sa hudno, ug ang tanan nga mapahitas-on, oo, ug ang tanan nga nagbuhat og daotan, mahimo nga dagami; ug ang adlaw nga umaabot mosunog kanila, miingon ang Ginoo sa mga panon, walay gamot o sanga ang mahibilin."},{"verse":65,"text":"Mao nga, kini mao ang tubag sa Ginoo kanila:"},{"verse":66,"text":"Niana nga adlaw nga miadto ako ngadto sa mga akoa, walay tawo taliwala kaninyo ang midawat kanako, ug kamo gihinginlan."},{"verse":67,"text":"Sa dihang mitawag ako pag-usab walay usa ninyo ang mitubag; apan ang akong bukton wala kawad-i og gahom nga dili ako makatubos, ni ang akong gahom sa pagluwas."},{"verse":68,"text":"Tan-awa, sa akong pagbadlong gipauga nako ang dagat. Gihimo nako ang mga suba nga kamingawan; ang ilang isda nangabaho, ug nangamatay tungod sa kauhaw."},{"verse":69,"text":"Gipangitngit ko ang kalangitan nga daw nagbangotan alang sa mga patay."},{"verse":70,"text":"Ug kini maangkon ninyo sa akong kamot—makasinati kamo og kasub-anan."},{"verse":71,"text":"Tan-awa, ug sud-onga, walay moluwas kaninyo; kay wala kamo mosunod sa akong tingog sa dihang gitawag ko kamo gikan sa kalangitan; wala kamo motuo sa akong mga sulugoon, ug sa dihang gipadala sila kaninyo wala kamo modawat kanila."},{"verse":72,"text":"Mao nga, giselyohan nila ang pagpamatuod ug mipahamtang sa balaod, ug gitugyan kamo ngadto sa kangitngit."},{"verse":73,"text":"ltambog sila ngadto sa kawanangan nga mangitngit, diin adunay pagdangoyngoy, ug pagminatay, ug pagpangagot sa mga ngipon."},{"verse":74,"text":"Tan-awa ang Ginoo nga inyong Dios namulong niini. Amen."}]},{"chapter":134,"verses":[{"verse":1,"text":"Nagatuo kami nga ang mga gobyerno gitukod sa Dios alang sa kaayohan sa tawo; ug gihatagan niya ang mga tawo og tulubagon sa ilang mga binuhatan kalabot niini, sa paghimo og mga balaod ug sa pagdumala niini, alang sa kaayohan ug kaluwasan sa katilingban."},{"verse":2,"text":"Nagatuo kami nga walay gobyerno nga molungtad sa kalinaw, gawas kon kana nga mga balaod gitukod ug gipatuman nga walay paglapas ingon man mopanalipod sa matag indibidwal sa gawasnon nga paggamit sa tanlag, sa katungod ug pagkontrol sa kabtangan, ug pagpanalipod sa kinabuhi."},{"verse":3,"text":"Nagatuo kami nga ang tanang gobyerno angay gayod nga mosugo sa sibil nga mga opisyal ug mga maghuhukom sa pagpatuman sa maong mga balaod; ug nga sa ingon ang pagdumala sa balaod diha sa katarong ug kaangayan kinahanglang tinguhaon ug suportahan pinaagi sa tingog sa katawhan kon usa kini ka republika, o sa kabubut-on sa labaw nga kamandoan."},{"verse":4,"text":"Nagatuo kami nga ang relihiyon gitukod sa Dios; ug ang tawo adunay kapangakohan ngadto kaniya, ug ngadto kaniya lamang, sa paggamit niini, gawas kon ang ilang relihiyoso nga mga opinyon moaghat nila sa paglapas sa mga katungod ug mga kalingkawasan sa uban; apan dili kami motuo nga ang balaod sa tawo adunay katungod sa pagpanghilabot sa paghimo og mga lagda sa pagsimba aron pugngan ang mga tanlag sa mga tawo, ni momando og mga paagi alang sa kadaghanan o kinaugalingon nga paghalad; nga ang sibil nga maghuhukom kinahanglang mopugong sa krimen, apan dili gayod mokontrol sa tanlag; kinahanglang mosilot sa sala, apan dili gayod mopugong sa kagawasan sa kalag."},{"verse":5,"text":"Nagatuo kami nga ang tanang tawo kinahanglang mopaluyo ug mosuporta sa kaugalingong mga gobyerno diin sila nagpuyo, samtang gipanalipdan sa ilang kinaiyanhon ug dili mailog nga mga katungod pinaagi sa mga balaod niana nga mga gobyerno; ug nga ang pagsupak ug pagsupil dili angay sa matag lumulupyo sa ingon niana gipanalipdan, ug kinahanglang silotan sumala niana; ug nga ang tanang gobyerno adunay katungod sa paghimo nianang mga balaod sumala sa ilang kaugalingong mga paghukom nga gihunahuna nga labing maayo aron mapanalipdan ang tinguha sa kadaghanan; sa samang higayon, hinuon, nagtamod sa kasagrado sa kagawasan sa tanlag."},{"verse":6,"text":"Nagatuo kami nga ang matag tawo kinahanglang tahoron sa iyang kahimtang, ingon nga mga magmamando ug mga maghuhukom, nga gibutang aron sa pagpanalipod sa walay sala ug sa pagsilot sa may sala; ug ngadto sa mga balaod ang tanang tawo kinahanglang motahod ug motamod, kay kon wala kini ang kalinaw ug panag-uyon mapulihan sa kagubot ug kahadlok; ang tawhanong mga balaod nga gitukod sa klaro nga katuyoan sa paghan-ay sa atong mga tinguha isip mga indibidwal ug mga nasod, tali sa usa ka tawo ngadto sa usa ka tawo; ug ang balaanong mga balaod nga gihatag sa langit, nagtudlo og mga lagda nga may kalabotan sa espirituhanong mga butang, alang sa pagtuo ug pagsimba, parehong pagatubagon sa tawo ngadto sa Iyang Magbubuhat."},{"verse":7,"text":"Nagatuo kami nga ang mga magmamando, mga nasod, ug mga gobyerno adunay katungod, ug kinahanglang mohimo og mga balaod aron mapanalipdan ang tanang lumulupyo sa gawasnong paggamit sa ilang relihiyoso nga pagtuo; apan dili kami motuo nga sila adunay katungod sumala sa kaangayan nga mohikaw sa mga lumulupyo niini nga kahigayonan, o sa pagdili kanila sa ilang mga opinyon, basta ang pagtamod ug pagtahod sa balaod gipakita ug kana nga relihiyosong mga opinyon dili himoon nga katarongan sa pagsukol ni sa panagkunsabo."},{"verse":8,"text":"Nagatuo kami nga ang paghimo og krimen kinahanglang silotan sumala sa matang sa sala; nga ang pagpatay, pagbudhi, pagpanulis, pagpangawat, ug pagguba sa kinatibuk-ang kalinaw, sa tanang paagi, kinahanglang silotan sumala sa gibug-aton sa ilang sala ug sa ilang kalagmitan nga mohimo og daotan taliwala sa mga tawo, pinaagi sa mga balaod niana nga gobyerno diin ang sala gibuhat; ug alang sa kalinaw ug panagdait sa kadaghanan ang tanang tawo kinahanglang mangusog ug mogamit sa ilang abilidad sa pagsilot sa mga makasasala nga mibatok sa maayong mga balaod."},{"verse":9,"text":"Dili kami motuo nga makiangayong itipon ang relihiyoso nga impluwensya sa sibil nga gobyerno, diin ang usa ka relihiyoso nga kapunongan atimanon ug ang lain did-an sa espirituhanong mga kahigayonan niini, ug ang tagsa-tagsa nga mga katungod sa mga sakop niini, isip mga lumulupyo, ihikaw."},{"verse":10,"text":"Nagatuo kami nga ang tanang relihiyoso nga kapunongan adunay katungod sa pagbadlong sa ilang mga sakop tungod sa dili maayong pamatasan, sumala sa mga lagda ug mga balaod niana nga mga kapunongan; kon kana nga mga pagbadlong gihimo alang sa panagdait ug maayo nga kadungganan; apan dili kami motuo nga ang bisan unsa nga relihiyoso nga kapunongan adunay awtoridad sa paghusay sa mga tawo bahin sa katungod sa katigayonan o sa kinabuhi, sa pagkuha gikan nila niining kalibotanong mga kabtangan, o sa pagbutang nila sa kakuyaw sa kinabuhi man o ubang bahin sa lawas, o sa pagpahamtang nila og bisan unsang pisikal nga silot. Makahimo lamang kini sa pagpahimulag nila gikan sa kapunongan, ug sa pagtangtang nila gikan sa ilang panagdait."},{"verse":11,"text":"Nagatuo kami nga ang mga tawo kinahanglang mosang-at ngadto sa sibil nga balaod alang sa pagtul-id sa tanang kasaypanan ug mga pasipala, diin ang personal nga pag-abuso gipahamtang o ang katungod sa kabtangan o pagkatawo gilapas, diin adunay ingon nga mga balaod nga mopanalipod niana; apan nagatuo kami nga ang tanang tawo adunay katungod sa pagpanalipod sa ilang kaugalingon, sa ilang mga higala, ug mga kabtangan, ug sa gobyerno, gikan sa supak sa balaod nga mga pagsulong ug mga paglapas sa tanang tawo sa mga panahon sa panginahanglan, diin ang dinalian nga paghangyo og kahupay dili mahimo sa mga balaod, ug ang tabang dili mahatag."},{"verse":12,"text":"Nagatuo kami nga makiangayon nga isangyaw ang ebanghelyo ngadto sa mga nasod sa yuta, ug pasidan-an ang mga matarong sa pagluwas sa ilang kaugalingon gikan sa kadaotan sa kalibotan; apan kami dili motuo nga matarong ang pagpanghilabot sa mga ulipon, ni mosangyaw sa ebanghelyo, ni mobunyag kanila nga supak sa kabubut-on ug tinguha sa ilang mga agalon, ni manghilabot o moimpluwensya kanila bisan sa labing gamay nga paagi aron dili sila makontento sa ilang mga kahimtang dinhi niini nga kinabuhi, nga pinaagi niana mabutang sa peligro ang mga kinabuhi sa mga tawo; nagatuo kami nga kana nga pagpanghilabot supak sa balaod ug dili makiangayon, ug makadaot sa kalinaw sa matag gobyerno nga nagtugot sa mga tawo nga magpabilin diha sa pagkaulipon."}]},{"chapter":135,"verses":[{"verse":1,"text":"Aron maselyo ang pagpamatuod niini nga basahon ug sa Basahon ni Mormon, among ipahibalo ang pagkamartir ni Joseph Smith ang Propeta, ug ni Hyrum Smith ang Patriyarka. Gipusil sila didto sa bilanggoan sa Carthage, niadtong ika-27 sa Hunyo, 1844, mga alas singko sa hapon, sa armado nga mga manggugubot—nagpintal og itom sa ilang mga nawong—gikan sa 150 ngadto sa 200 ka tawo. Si Hyrum ang unang gipusil ug inanay nga natumba, nga nagtuaw: Patay na ko! Misulay si Joseph sa pag-ambak gikan sa bintana, ug gipusil-patay, nga nagtuaw: O Ginoo akong Dios! Silang duha gipamusil bisan og patay na, sa walay kaluoy nga paagi, ug ang duha nakaangkon og upat ka pinusilan."},{"verse":2,"text":"Si John Taylor ug si Willard Richards, duha sa Napulog Duha, mao lamang ang mga tawo diha sa lawak nianang higayona; ang una nasamdan sa mabangis nga paagi nga may upat ka pinusilan, apan naayo ra; ang ulahi, pinaagi sa kaluoy sa Dios, nakaikyas, nga walay bisan usa ka buslot sa iyang kupo."},{"verse":3,"text":"Si Joseph Smith, ang Propeta ug Manalagna sa Ginoo, mas daghan og nahimo, gawas lamang kang Jesus, alang sa kaluwasan sa mga tawo niini nga kalibotan, kaysa ubang tawo nga nakapuyo dinhi. Sulod sa mubong panahon sa kawhaan ka tuig, siya ang mipatungha sa Basahon ni Mormon, nga iyang gihubad pinaagi sa gasa ug gahom sa Dios, ug nahimong pamaagi nga mamantala kini sa duha ka kontinente; mipadala sa kahingpitan sa walay kataposan nga ebanghelyo, nga anaa niini, ngadto sa upat ka bahin sa kalibotan; mipatungha sa mga pagpadayag ug mga sugo nga naglangkob niini nga basahon sa Doktrina ug mga Pakigsaad, ug daghan pang maalamon nga mga dokumento ug mga panudlo alang sa kaayohan sa katawhan; mipundok sa daghang liboan ka Santos sa Ulahing mga Adlaw, nagtukod og dakong siyudad, ug nagbilin og dungog ug ngalan nga dili mamatay. Nagpuyo siya nga halangdon, ug namatay nga halangdon sa mga mata sa Dios ug sa iyang katawhan; ug sama sa kadaghanan nga gidihogan sa Ginoo sa karaang mga panahon, miselyo sa iyang misyon ug sa iyang buhat pinaagi sa iyang kaugalingong dugo; ug ingon man usab ang iyang igsoon nga si Hyrum. Sa kinabuhi wala sila mabahin, ug sa kamatayon wala sila mabulag!"},{"verse":4,"text":"Sa dihang miadto si Joseph sa Carthage aron itugyan ang iyang kaugalingon ngadto sa gipakaaron-ingnon nga mga kinahanglanon sa balaod, duha o tulo ka adlaw sa wala pa siya gipatay, miingon siya: “Moadto ako sama sa usa ka karnero paingon sa ihawanan; apan malinawon ako sama sa kabuntagon sa ting-init; Dala ko ang tanlag nga walay sala ngadto sa Dios, ug sa tanang tawo. Mamatay ako nga walay sala, ug ikasulti pa kini mahitungod kanako—gituyo siya sa pagpatay sa walay kaluoy.”—Nianang buntaga, human makaandam si Hyrum sa paglakaw—ato bang masulti nga moadto sa ihawan? oo, kay mao gayod kadto—gibasa niya ang mosunod nga parapo, dapit sa kataposan sa ikanapulog duha nga kapitulo sa Ether, sa Basahon ni Mormon, ug gipakli ang palid niini:"},{"verse":5,"text":"Ug nahitabo nga nag-ampo ako sa Ginoo nga siya mohatag sa mga Hentil og grasya, nga sila makaangkon og gugma nga putli. Ug nahitabo nga ang Ginoo miingon kanako: Kon sila walay gugma nga putli dili kini mahinungdanon nganha kanimo, ikaw nagmatinud-anon; mao nga ang imong mga sapot pagahimoon nga limpyo. Ug kay nakita nimo ang imong kahuyang, ikaw pagalig-onon, gani ngadto sa paglingkod sa dapit nga akong giandam didto sa mga mansyon sa akong Amahan. Ug karon … manamilit ako sa mga Hentil; oo, ug usab ngadto sa akong kaigsoonan nga akong gihigugma, hangtod nga magkita kita sa atubangan sa hukmanan ni Kristo, diin ang tanang tawo masayod nga ang akong mga sapot walay lama sa inyong dugo. Ang mga testigo patay na, ug ang ilang testamento nagpadayon pa."},{"verse":6,"text":"Si Hyrum Smith kap-atan ug upat ang panuigon niadtong Pebrero, 1844, ug si Joseph Smith katloan ug walo niadtong Disyembre, 1843; ug sukad niadto ang ilang mga ngalan nahilakip sa mga martir sa relihiyon; ug ang magbabasa sa matag nasod mapahinumdoman nga ang Basahon ni Mormon, ug kini nga basahon sa Doktrina ug mga Pakigsaad sa simbahan, nagkantidad sa labing mahal nga dugo sa ikanapulo ug siyam ka gatos nga siglo aron sa pagpatungha niini alang sa kaluwasan sa usa ka daotan nga kalibotan; ug nga kon ang kalayo makasunog sa usa ka buhi nga kahoy alang sa himaya sa Dios, sayon ra kaayo niining sunogon ang uga nga mga kahoy aron malimpyohan ang ubasan gikan sa pagkadaot. Nabuhi sila alang sa himaya; namatay sila alang sa himaya; ug ang himaya mao ang ilang walay kataposan nga ganti. Gikan sa usa ka panahon ngadto sa laing panahon ang ilang mga ngalan mahinumdoman sa kaliwatan ingon og mga mutya alang sa gibalaan."},{"verse":7,"text":"Wala sila makasala sa bisan unsa nga krimen, ingon nga sila sa kanunay napamatud-an kaniadto, ug nabilanggo lamang pinaagi sa plano sa mga mabudhion ug daotang mga tawo; ug ang ilang dugo nga walay sala nga nagbanaw sa bilanggoan sa Carthage usa ka lig-ong selyo nga napatik sa “pagka-Mormon” nga dili masalikway sa bisan unsa nga hukmanan sa yuta, ug ang ilang dugo nga walay sala diha sa dayan-dayan sa Estado sa Illinois, uban sa nabungkag nga pagtuo sa Estado sama sa gipanumpaan sa gobernador, mao ang usa ka saksi sa kamatuoran sa walay kataposang ebanghelyo nga dili malalis sa tibuok kalibotan; ug ang ilang dugo nga walay sala diha sa bandila sa kalingkawasan, ug diha sa magna charta sa Estados Unidos, mao ang nagrepresentar sa relihiyon ni Jesukristo, nga motandog sa mga kasingkasing sa matinuorong mga tawo sa tanang kanasoran; ug ang ilang dugo nga walay sala, kauban ang dugo nga walay sala sa tanang martir nga anaa sa ilawom sa altar nga nakita ni Juan, motuaw ngadto sa Ginoo sa mga Panon hangtod nga siya manimalos niana nga dugo dinhi sa yuta. Amen."}]},{"chapter":136,"verses":[{"verse":1,"text":"Ang Pulong ug ang Kabubut-on sa Ginoo mahitungod sa Kampo sa Israel sa ilang mga pagpanaw paingon sa Kasadpan:"},{"verse":2,"text":"Tugoti nga ang katawhan sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw, ug kadtong mopanaw uban kanila, maorganisar ngadto sa mga pundok, uban sa usa ka pakigsaad ug panaad sa pagsunod sa tanang sugo ug mga balaod sa Ginoo nga atong Dios."},{"verse":3,"text":"Tugoti nga ang mga pundok maorganisar uban sa mga pangulo sa matag ginatos, mga pangulo sa matag kalim-an, ug mga pangulo sa matag napulo, uban sa usa ka presidente ug sa iyang duha ka magtatambag nga mangulo kanila, ubos sa pagmando sa Napulog Duha ka Apostoles."},{"verse":4,"text":"Ug mao kini ang atong pakigsaad—nga kita maglakaw subay sa tanang ordinansa sa Ginoo."},{"verse":5,"text":"Tugoti nga ang matag pundok moandam sa ilang kaugalingon sa tanang kahayopan, mga karwahe, mga kasangkapan, mga sapot, ug ubang mga kinahanglanon alang sa panaw, nga ilang maandam."},{"verse":6,"text":"Kon ang mga pundok maorganisar na tugoti nga manglakaw sila inubanan sa tanan nilang paningkamot, aron sa pag-andam alang niadtong magpabilin."},{"verse":7,"text":"Tugoti nga ang matag pundok, uban sa ilang mga pangulo ug mga presidente, modesisyon kon pila ang makalakaw sa sunod nga tingpamulak; unya mopili og igong gidaghanon sa mga himsog ug hanas nga mga tawo, sa pagdala sa mga kahayopan, mga liso, ug galamiton sa pagpanguma, sa paglakaw isip mga unang pumupuyo aron sa pag-andam alang sa pagpananom og mga lagutmon sa tingpamulak."},{"verse":8,"text":"Tugoti nga ang matag pundok magdala og managsama nga bahin, sumala sa bili sa ilang kabtangan, sa pag-amuma sa mga kabos, sa mga biyuda, sa mga walay amahan, ug sa mga pamilya niadtong mikuyog sa kasundalohan, aron ang mga paghilak sa biyuda ug sa mga walay amahan dili makaabot ngadto sa mga dunggan sa Ginoo batok sa iyang katawhan."},{"verse":9,"text":"Tugoti nga ang matag pundok mag-andam og mga balay, ug mga umahan nga patuboan og mga lugas, alang niadtong magpabilin niini nga panahon; ug mao kini ang kabubut-on sa Ginoo mahitungod sa iyang katawhan."},{"verse":10,"text":"Tugoti nga ang matag tawo mogamit sa iyang tanang impluwensya ug kabtangan sa pagdala niini nga katawhan ngadto sa dapit diin ang Ginoo mopahimutang sa stake sa Zion."},{"verse":11,"text":"Ug kon buhaton ninyo kini uban sa putli nga kasingkasing, sa tanang pagkamatinuoron, mapanalanginan kamo; mapanalanginan kamo sa inyong gagmayng kahayopan, ug sa inyong dagkong kahayopan, ug sa inyong mga umahan, ug sa inyong mga balay, ug sa inyong mga pamilya."},{"verse":12,"text":"Tugoti nga ang akong mga sulugoon nga sila si Ezra T. Benson ug Erastus Snow moorganisar og usa ka pundok."},{"verse":13,"text":"Ug tugoti nga ang akong mga sulugoon nga sila si Orson Pratt ug Wilford Woodruff moorganisar og usa ka pundok."},{"verse":14,"text":"Usab, tugoti nga ang akong mga sulugoon nga sila si Amasa Lyman ug George A. Smith moorganisar og usa ka pundok."},{"verse":15,"text":"Ug pagpili og mga presidente, ug mga pangulo sa matag ginatos, ug sa matag kalim-an, ug sa matag napulo."},{"verse":16,"text":"Ug tugoti nga ang akong mga sulugoon nga gipili molakaw ug motudlo niini, sa akong kabubut-on, ngadto sa mga santos, nga sila maandam sa paglakaw ngadto sa usa ka yuta sa kalinaw."},{"verse":17,"text":"Lakaw ug buhata sumala sa akong gisulti kaninyo, ug ayaw kahadlok sa inyong mga kaaway; kay sila walay gahom sa pagpahunong sa akong buhat."},{"verse":18,"text":"Ang Zion pagatubson sa akong kaugalingong tukmang panahon."},{"verse":19,"text":"Ug si bisan kinsa nga tawo ang magtinguha sa pagpalambo sa iyang kaugalingon, ug wala magtinguha sa akong tambag, siya walay gahom, ug ang iyang kabuang ipadayag."},{"verse":20,"text":"Tinguhaa ninyo; ug tumana ang tanan ninyong mga panaad sa usag usa; ug ayaw kaibog nianang iya sa imong igsoon."},{"verse":21,"text":"Ipalayo ang inyong kaugalingon gikan sa daotan sa pagpasipala sa ngalan sa Ginoo, kay ako ang Ginoo nga inyong Dios, gani ang Dios sa inyong mga amahan, ang Dios ni Abraham ug ni Isaac ug ni Jacob."},{"verse":22,"text":"Ako mao siya nga nangulo sa mga anak sa Israel gikan sa yuta sa Ehipto; ug ang akong bukton ipatuyhad sa kataposang mga adlaw, aron sa pagluwas sa akong katawhan nga Israel."},{"verse":23,"text":"Hunong sa pagpakigbangi sa usag usa; hunong sa pagsulti og daotan sa usag usa."},{"verse":24,"text":"Ihunong ang paghubog-hubog; ug tugoti nga ang inyong mga pulong gitumong sa paghatag og kaayohan sa usag usa."},{"verse":25,"text":"Kon manghulam kamo sa inyong silingan, iuli kanang inyong gihulaman; ug kon dili ninyo mauli bayari kana, dayon sultihi ang inyong silingan, basin pa unya og panghimaraoton niya kamo."},{"verse":26,"text":"Kon makit-an nimo kanang nawala sa imong silingan, pagkugi sa pagpangita hangtod nga imong mahatod kini og balik ngadto kaniya."},{"verse":27,"text":"Pagmakugihon sa pag-amping sa unsay anaa kanimo, nga ikaw mahimong maalamon nga tinugyanan; kay libre kini nga gasa sa Ginoo nga imong Dios, ug ikaw mao ang iyang tinugyanan."},{"verse":28,"text":"Kon ikaw malipayon, dayga ang Ginoo pinaagi sa pagkanta, pinaagi sa musika, pinaagi sa pagsayaw, ug pinaagi sa pag-ampo sa pagdayeg ug pagpasalamat."},{"verse":29,"text":"Kon ikaw masulub-on, tawga ang Ginoo nga imong Dios pinaagi sa pagpangamuyo, nga ang imong kalag magmaya."},{"verse":30,"text":"Ayaw kahadlok sa imong mga kaaway, kay sila ania sa akong mga kamot ug ako mohimo sumala sa akong gusto ngadto kanila."},{"verse":31,"text":"Ang akong katawhan kinahanglang pagasulayan sa tanang butang, aron maandam sila sa pagdawat sa himaya nga anaa kanako alang kanila, gani ang himaya sa Zion; ug siya nga dili makaantos sa pagpanton dili takos sa akong gingharian."},{"verse":32,"text":"Tugoti nga siya nga walay nahibaloan nga magkat-on og kaalam pinaagi sa pagpaubos sa iyang kaugalingon ug sa pagtawag sa Ginoo nga iyang Dios, nga ang iyang mga mata mabuka aron makakita siya, ug ang iyang mga dunggan maabli aron siya makadungog;"},{"verse":33,"text":"Kay ang akong Espiritu gipadala sa kalibotan aron modan-ag sa mga mapaubsanon ug mahinulsolon, ug sa pagpanghimaraot sa mga dili diosnon."},{"verse":34,"text":"Ang inyong kaigsoonan nagsalikway kaninyo ug sa inyong pagpamatuod, bisan ang nasod nga nagpalayas kaninyo;"},{"verse":35,"text":"Ug karon miabot na ang ilang adlaw sa katalagman, gani ang mga adlaw sa kagul-anan, sama sa usa ka babaye nga nahiagom sa kasakit; ug ang ilang kagul-anan mograbe gawas kon maghinulsol dayon sila, oo, sa labing madali."},{"verse":36,"text":"Kay gipangpatay nila ang mga propeta, ug sila nga gipadala ngadto kanila; ug nakapaagas sila og dugo sa walay sala, nga mituaw gikan sa yuta batok kanila."},{"verse":37,"text":"Busa, ayaw katingala niining mga butanga, kay kamo dili pa putli; dili pa kamo makasugakod sa akong himaya; apan makita kini ninyo kon magmatinud-anon kamo sa pagsunod sa akong tanang pulong nga akong gihatag kaninyo, gikan sa mga adlaw ni Adan ngadto ni Abraham, gikan ni Abraham ngadto ni Moises, gikan ni Moises ngadto ni Jesus ug sa iyang apostoles, ug gikan ni Jesus ug sa iyang apostoles ngadto ni Joseph Smith, nga akong gitawag pinaagi sa akong mga anghel, akong tigpangalagad nga mga sulugoon, ug pinaagi sa akong kaugalingong tingog gikan sa kalangitan, sa pagdala sa akong buhat;"},{"verse":38,"text":"Diin nga pundasyon siya ang mipahimutang, ug nagmatinud-anon; ug ako mikuha kaniya ngari sa akong kaugalingon."},{"verse":39,"text":"Daghan ang nahibulong tungod sa iyang kamatayon; apan gikinahanglan nga iyang iselyo ang iyang pagpamatuod pinaagi sa iyang dugo, aron siya mapasidunggan ug ang daotan masilotan."},{"verse":40,"text":"Wala ba ako moluwas kaninyo gikan sa inyong mga kaaway, pinaagi lamang niana ako nakabilin og usa ka saksi sa akong ngalan?"},{"verse":41,"text":"Busa, karon, paminaw, O kamong katawhan sa akong simbahan; ug kamong mga elder maghiusa sa pagpaminaw; nakadawat kamo sa akong gingharian."},{"verse":42,"text":"Pagmakugihon sa pagsunod sa akong tanang sugo, basin pa unya og ang mga paghukom moabot kaninyo, ug ang inyong pagtuo mopakyas kaninyo, ug ang inyong mga kaaway mobuntog kaninyo. Busa mao lamang kini sa pagkakaron. Amen ug Amen."}]},{"chapter":137,"verses":[{"verse":1,"text":"Ang kalangitan naabli ngari kanamo, ug nakita nako ang celestial nga gingharian sa Dios, ug ang himaya niini, kon dinhi man sa lawas o gawas sa lawas ako dili makasulti niini."},{"verse":2,"text":"Nakita nako ang talagsaon nga katahom sa ganghaan diin mosulod ang mga manununod sa gingharian, nga daw sama sa nagtuyok nga mga siga sa kalayo;"},{"verse":3,"text":"Usab ang mahimayaon nga trono sa Dios, diin naglingkod ang Amahan ug ang Anak."},{"verse":4,"text":"Nakita nako ang matahom nga mga dalan niana nga gingharian, nga may panagway nga sementadong bulawan."},{"verse":5,"text":"Nakita nako ang Amahan nga si Adan ug si Abraham; ug ang akong amahan ug ang akong inahan; ang akong igsoong lalaki nga si Alvin, nga dugay nang namatay;"},{"verse":6,"text":"Ug natingala ko kon sa unsang paagi siya nakabaton og panulondon niana nga gingharian, kay mibiya siya niini nga kinabuhi sa wala pa ang Ginoo makapahimutang sa iyang kamot aron sa pagpundok sa Israel sa ikaduha nga higayon, ug wala pa mabunyagi alang sa kapasayloan sa mga sala."},{"verse":7,"text":"Sa ingon niana miabot ang tingog sa Ginoo ngari kanako, nga nag-ingon: Ang tanang namatay nga wala makahibalo niini nga ebanghelyo, kinsa modawat unta niini kon gitugotan pa sila sa pagpabilin, mahimong mga manununod sa celestial nga gingharian sa Dios;"},{"verse":8,"text":"Usab ang tanang mamatay sukad karon nga wala mahibalo niini, kinsa modawat unta niini sa tibuok nilang kasingkasing, mahimong manununod niana nga gingharian;"},{"verse":9,"text":"Kay ako, ang Ginoo, mohukom sa tanang tawo sumala sa ilang binuhatan, sumala sa tinguha sa ilang mga kasingkasing."},{"verse":10,"text":"Ug nakita usab nako nga ang tanang bata nga namatay sa wala pa sila moabot sa panuigon sa pagkamay-tulubagon maluwas diha sa celestial nga gingharian sa langit."}]},{"chapter":138,"verses":[{"verse":1,"text":"Sa ikatulo sa Oktubre, sa napulog siyam ka gatos ug napulog walo nga tuig, naglingkod ko sa akong lawak namalandong sa mga kasulatan;"},{"verse":2,"text":"Ug naghunahuna bahin sa dakong sakripisyo sa pag-ula nga gihimo sa Anak sa Dios, alang sa katubsanan sa kalibotan;"},{"verse":3,"text":"Ug sa dako ug talagsaon nga gugma nga gipakita sa Amahan ug sa Anak sa pag-anhi sa Manunubos sa kalibotan;"},{"verse":4,"text":"Nga pinaagi sa iyang pag-ula, ug sa pagkamasulondon sa mga baroganan sa ebanghelyo, ang katawhan maluwas."},{"verse":5,"text":"Samtang naghimo ko sa ingon, ang akong hunahuna mibalik ngadto sa mga sinulat ni apostol Pedro, ngadto sa nahauna nga mga santos nga nagkatibulaag sa laing nasod sa Ponto, Galacia, Capadocia, ug sa ubang bahin sa Asya, diin ang ebanghelyo gisangyaw human gilansang sa krus ang Ginoo."},{"verse":6,"text":"Gipakli nako ang Biblia ug gibasa ang ikatulo ug ikaupat nga mga kapitulo sa unang epistola ni Pedro, ug samtang ako nagbasa nadasig kaayo ako, labaw pa kaysa nangagi, sa mosunod nga mga tudling:"},{"verse":7,"text":"“Kay si Kristo usab sa makausa nag-antos sa mga sala, ang makiangayon alang sa dili makiangayon, nga siya unta makadala kanato ngadto sa Dios, ingon nga gipatay diha sa unod, apan gibuhi pinaagi sa Espiritu:"},{"verse":8,"text":"“Nga niini usab siya miadto ug misangyaw ngadto sa mga espiritu didto sa bilanggoan;"},{"verse":9,"text":"“Kinsa usahay mga masinupakon, nga sa kaniadto nga panahon ang taas nga pag-antos sa Dios nagpaabot sa mga adlaw ni Noe, samtang ang arka gibuhat pa, diin pipila lamang, mao kadto, ang walo ka kalag nga naluwas pinaagi sa tubig.” (1 Pedro 3:18–20.)"},{"verse":10,"text":"“Kay mao kini ang hinungdan nga ang ebanghelyo gisangyaw usab ngadto kanila nga mga patay na, nga sila unta mahukman sumala sa mga tawo diha sa unod, apan mabuhi sumala sa Dios diha sa Espiritu.” (1 Pedro 4:6.)"},{"verse":11,"text":"Samtang namalandong ko niini nga mga butang nga nahisulat, ang mga mata sa akong salabotan nabuksan, ug ang Espiritu sa Ginoo mikunsad kanako, ug akong nakita ang mga panon sa mga patay, ang dili bantogan ug bantogan."},{"verse":12,"text":"Ug adunay nagpundok sa usa ka dapit nga dili maihap nga mga espiritu sa mga makiangayon, kinsa nagmatinud-anon sa pagpamatuod bahin ni Jesus samtang nagpuyo sila sa pagka-mortal;"},{"verse":13,"text":"Ug kinsa nakahalad og sakripisyo nga may pagkasusama sa dakong sakripisyo sa Anak sa Dios, ug nakaantos sa kalisdanan pinaagi sa ngalan sa ilang Manunubos."},{"verse":14,"text":"Kining tanan mibiya sa mortal nga kinabuhi, lig-on sa paglaom sa usa ka mahimayaon nga pagkabanhaw, pinaagi sa grasya sa Dios nga Amahan ug sa iyang Bugtong Anak, si Jesukristo."},{"verse":15,"text":"Nakita nako nga napuno sila sa kamaya ug kalipay, ug nagduyog sa kalipay tungod kay ang adlaw sa ilang kaluwasan haduol na."},{"verse":16,"text":"Nagpundok sila nga naghulat sa pag-abot sa Anak sa Dios ngadto sa kalibotan sa mga espiritu, aron ipahayag ang katubsanan gikan sa mga higot sa kamatayon."},{"verse":17,"text":"Ang ilang nahikatulog nga lawas mahibalik ngadto sa hingpit nga bayanan niini, bukog ngadto sa iyang bukog, ug ang mga ugat ug mga unod nganha niini, ang espiritu ug ang lawas pagahiusahon nga dili na gayod mabulag pag-usab, nga sila makadawat og kahingpitan sa kalipay."},{"verse":18,"text":"Samtang kining dako kaayo nga pundok naghulat ug nagsultihanay, naglipay sa takna sa ilang kaluwasan gikan sa mga kadena sa kamatayon, ang Anak sa Dios, mipakita, nagpahayag sa kalingkawasan sa mga binilanggo nga nagmatinud-anon;"},{"verse":19,"text":"Ug didto iyang gisangyaw kanila ang walay kataposang ebanghelyo, ang doktrina sa pagkabanhaw ug ang katubsanan sa katawhan gikan sa pagkapukan, ug gikan sa kaugalingong mga sala kon sila maghinulsol."},{"verse":20,"text":"Apan ngadto sa mga daotan siya wala moadto, ug taliwala sa mga dili diosnon ug sa wala maghinulsol nga mihugaw sa ilang kaugalingon samtang buhi pa, ang iyang tingog wala ipaabot;"},{"verse":21,"text":"Ang mga masupilon nga misalikway sa mga pagpamatuod ug sa mga pasidaan sa karaang mga propeta wala makakita sa iyang presensya, ni makakita sa iyang nawong."},{"verse":22,"text":"Dinhi niini, ang kangitngit naghari, apan sa taliwala sa mga matarong adunay kalinaw;"},{"verse":23,"text":"Ug ang mga santos nagmaya sa ilang katubsanan, ug miluhod ug miila sa Anak sa Dios isip ilang Manunubos ug Tigluwas gikan sa kamatayon ug sa mga kadena sa impyerno."},{"verse":24,"text":"Ang ilang mga panagway misanag, ug ang kahayag gikan sa presensya sa Ginoo midangat kanila, ug sila nag-awit og mga pagdayeg ngadto sa iyang balaan nga ngalan."},{"verse":25,"text":"Natingala ako, kay akong nasabtan nga ang Manluluwas migahin og tulo ka tuig sa iyang pangalagad taliwala sa mga Judeo ug niadtong mga sakop sa balay ni Israel, naningkamot sa pagtudlo kanila sa walay kataposang ebanghelyo ug sa pagtawag kanila ngadto sa paghinulsol;"},{"verse":26,"text":"Ug, bisan pa sa iyang gamhanan nga mga buhat, ug mga milagro, ug pagpahayag sa kamatuoran, pinaagi sa dakong gahom ug katungod, adunay pipila lang ang mipatalinghog sa iyang tingog, ug nagmaya sa iyang presensya, ug midawat sa kaluwasan diha sa iyang mga kamot."},{"verse":27,"text":"Apan ang iyang pangalagad taliwala niadtong mga patay na limitado ra sa mubo nga panahon tali sa pagkalansang sa krus ug sa iyang pagkabanhaw;"},{"verse":28,"text":"Ug naghunahuna ko sa mga pulong ni Pedro—diin miingon siya nga ang Anak sa Dios nagsangyaw didto sa bilanggoan sa mga espiritu, kinsa sa makausa masinupakon, sa panahon nga ang taas nga pag-antos sa Dios nagpaabot sa mga adlaw ni Noe—ug kon sa unsang paagi nga nahimo niya ang pagsangyaw niadtong mga espiritu ug nakahimo sa gikinahanglan nga buhat taliwala kanila sa mubo lamang kaayo nga panahon."},{"verse":29,"text":"Ug samtang naghunahuna ko, ang akong mga mata nabuka, ug ang akong salabotan nalamdagan, ug akong nasabtan nga ang Ginoo wala mismo moadto taliwala sa mga daotan ug sa mga masinupakon nga misalikway sa kamatuoran, aron motudlo kanila;"},{"verse":30,"text":"Apan tan-awa, gikan sa taliwala sa mga matarong, miorganisar siya sa iyang mga pundok ug mitudlo og mga mensahero, sinul-oban sa gahom ug pagtugot, ug misugo kanila sa paglakaw ug pagdala sa kahayag sa ebanghelyo ngadto nila nga anaa sa kangitngit, gani ngadto sa tanan nga espiritu sa mga tawo; ug sa ingon niana ang ebanghelyo nasangyaw ngadto sa mga patay."},{"verse":31,"text":"Ug ang napili nga mga mensahero miadto sa pagpahayag sa adlaw nga ikahimuot sa Ginoo ug sa pagsangyaw og kalingkawasan ngadto sa mga binilanggo nga ginapos, gani ngadto sa tanan kinsa maghinulsol sa ilang mga sala ug modawat sa ebanghelyo."},{"verse":32,"text":"Sa ingon niana ang ebanghelyo gisangyaw ngadto niadtong nangamatay sa ilang mga sala, nga wala mahibalo sa kamatuoran, o sa kalapasan, nga pagsalikway sa mga propeta."},{"verse":33,"text":"Gitudloan sila og pagtuo sa Dios, paghinulsol sa sala, puli nga bunyag alang sa kapasayloan sa mga sala, sa gasa sa Espiritu Santo pinaagi sa pagpandong sa mga kamot,"},{"verse":34,"text":"Ug sa tanang uban pang mga baroganan sa ebanghelyo nga kinahanglan nilang masayran aron mahimong takos ang ilang kaugalingon nga sila mahukman sumala sa mga tawo diha sa unod, apan mabuhi sumala sa Dios diha sa espiritu."},{"verse":35,"text":"Ug sa ingon niini nga paagi kini gipahibalo taliwala sa mga patay, sa mga dili bantogan ug bantogan, sa mga daotan ingon man usab sa mga matinud-anon, nga ang katubsanan nahimo pinaagi sa sakripisyo sa Anak sa Dios pinaagi sa krus."},{"verse":36,"text":"Sa ingon niana kini gipahibalo nga ang atong Manunubos migahin sa iyang panahon atol sa iyang pag-adto didto sa kalibotan sa mga espiritu, nagtudlo ug nag-andam sa matinud-anong mga espiritu sa mga propeta kinsa mipamatuod kaniya kaniadto sa buhi pa;"},{"verse":37,"text":"Nga ilang dad-on ang mensahe sa katubsanan ngadto sa tanang patay, ngadto sa dili niya mismo maadto, tungod sa ilang pagsupil ug kalapasan, nga sila pinaagi sa pangalagad sa iyang mga sulugoon makadungog usab sa iyang mga pulong."},{"verse":38,"text":"Taliwala sa mga madungganon ug gamhanan nga gipundok niining dako kaayo nga katigoman sa mga matarong mao si Amahang Adan, ang Karaan sa mga Adlaw ug amahan sa tanan,"},{"verse":39,"text":"Ug ang atong mahimayaong Inahan nga si Eva, uban sa iyang daghang matinud-anong mga anak nga babaye kinsa nagpuyo sa tanang kapanahonan ug nagsimba sa tinuod ug buhi nga Dios."},{"verse":40,"text":"Si Abel, ang unang martir, anaa didto, ug ang iyang igsoong lalaki nga si Seth, usa sa mga bantogan, kinsa sama og panagway sa iyang amahan, si Adan."},{"verse":41,"text":"Si Noe, kinsa mihatag og pasidaan bahin sa lunop; si Shem, ang madungganon nga halangdong pari; si Abraham, ang amahan sa mga matinud-anon; si Isaac, si Jacob, ug si Moises, ang halangdon nga magbabalaod sa Israel;"},{"verse":42,"text":"Ug si Isaias, kinsa mipahayag pinaagi sa panagna nga ang Manunubos gidihogan aron sa pag-alim sa mga masulub-on og kasingkasing, sa pagsangyaw og kalingkawasan ngadto sa mga binilanggo, ug sa pag-abli sa bilanggoan ngadto kanila nga mga ginapos, anaa usab didto."},{"verse":43,"text":"Dugang pa, si Ezequiel, nga gipakitaan sa panan-awon sa dako nga walog sa uga nga mga bukog, nga pagasul-oban og unod, nga motungha pag-usab sa pagkabanhaw sa mga patay, buhi nga mga kalag;"},{"verse":44,"text":"Si Daniel, nga daan nang nakakita ug nanagna sa pagkatukod sa gingharian sa Dios sa ulahing mga adlaw, nga dili na gayod magun-ob pag-usab ni ihatag ngadto sa laing mga tawo;"},{"verse":45,"text":"Si Elias, kinsa kauban ni Moises didto sa Bungtod sa Transpigurasyon;"},{"verse":46,"text":"Ug si Malaquias, ang propeta nga mipamatuod bahin sa pag-anhi ni Elijah—nga gipamulong usab ni Moroni ngadto ni Propeta Joseph Smith, nag-ingon nga siya kinahanglan nga moanhi sa dili pa magsugod ang mahinungdanon ug makalilisang nga adlaw sa Ginoo—anaa usab didto."},{"verse":47,"text":"Si Propeta Elijah, ang motanom diha sa mga kasingkasing sa mga anak sa mga saad nga gihimo ngadto sa ilang mga amahan,"},{"verse":48,"text":"Nanagna sa mahinungdanong buhat nga pagahimoon sulod sa mga templo sa Ginoo sa dispensasyon sa kahingpitan sa mga panahon, alang sa katubsanan sa mga patay, ug sa pagselyo sa mga anak ngadto sa ilang mga ginikanan, basin pa unya og ang tibuok yuta pagahampakon sa usa ka tunglo ug hingpit nga malaglag sa iyang pag-anhi."},{"verse":49,"text":"Silang tanan ug daghan pa, gani ang mga propeta kinsa mipuyo taliwala sa mga Nephita ug mipamatuod sa pag-anhi sa Anak sa Dios, miipon sa dako kaayo nga katigoman ug naghulat sa ilang kaluwasan,"},{"verse":50,"text":"Kay ang mga patay nagtan-aw sa dugay nang pagkawala sa ilang mga espiritu gikan sa ilang mga lawas isip pagkaulipon."},{"verse":51,"text":"Sila ang gitudloan sa Ginoo, ug gipanghatagan sila og gahom nga mobangon, human sa iyang pagkabanhaw gikan sa mga patay, aron mosulod sa gingharian sa iyang Amahan, didto koronahan og pagka-imortal ug kinabuhing dayon,"},{"verse":52,"text":"Ug magpadayon sukad niana sa ilang paghago sama sa gisaad sa Ginoo, ug mahimong mga tig-ambit sa tanang panalangin nga gitagana alang kanila nga nahigugma kaniya."},{"verse":53,"text":"Si Propeta Joseph Smith, ug ang akong amahan, nga si Hyrum Smith, si Brigham Young, si John Taylor, si Wilford Woodruff, ug ubang pinili nga mga espiritu kinsa gitagana aron motungha sa kahingpitan sa mga panahon sa pag-apil sa pagpahiluna sa mga pundasyon sa mahinungdanong buhat sa ulahing mga adlaw,"},{"verse":54,"text":"Lakip sa pagtukod og mga templo ug sa pagpahigayon sa mga ordinansa diha niana alang sa katubsanan sa mga patay, anaa usab didto sa kalibotan sa mga espiritu."},{"verse":55,"text":"Nakita nako nga kauban usab sila sa mga hamili ug mga halangdon nga gipili sa sinugdanan aron mahimong mga magmamando sa Simbahan sa Dios."},{"verse":56,"text":"Bisan sa wala pa sila matawo, sila, kauban sa daghan pa, nakadawat sa ilang unang mga leksiyon didto sa kalibotan sa mga espiritu ug giandam nga motungha sa tukmang panahon sa Ginoo aron sa paghago sa iyang ubasan alang sa kaluwasan sa mga kalag sa mga tawo."},{"verse":57,"text":"Nakita nako nga ang matinud-anong mga elder niini nga dispensasyon, sa panahon nga mobiya na sila gikan sa mortal nga kinabuhi, mopadayon sa ilang mga paghago sa pagsangyaw sa ebanghelyo sa paghinulsol ug katubsanan, pinaagi sa sakripisyo sa Bugtong Anak sa Dios, taliwala niadtong anaa sa kangitngit ug ubos sa pagkaulipon sa sala didto sa dako nga kalibotan sa mga espiritu sa mga patay."},{"verse":58,"text":"Ang mga patay nga naghinulsol matubos, pinaagi sa pagkamasulondon ngadto sa mga ordinansa sa balay sa Dios,"},{"verse":59,"text":"Ug human nga ilang mabayaran ang silot sa ilang mga kalapasan, ug mahugasan nga limpyo, makadawat og ganti sumala sa ilang binuhatan, kay sila mga manununod sa kaluwasan."},{"verse":60,"text":"Sa ingon niana ang panan-awon sa katubsanan sa mga patay gipadayag ngari kanako, ug ako mopamatuod, ug nasayod ako nga kining talaan tinuod, pinaagi sa panalangin sa atong Ginoo ug Manluluwas, si Jesukristo, ug mao gayod kana. Amen."}]}]},{"id":"official-declarations","title":"Opisyal nga Pahayag","englishTitle":"Official Declarations","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Ngadto Kaniya nga Mahitungdan:"},{"verse":2,"text":"Kay adunay gipadalang mga balita alang sa mga katuyoang politikal, gikan sa Siyudad sa Salt Lake, diin lapad na kaayo ang naabot sa gimantala, tungod niini ang Utah Commission, sa ilang bag-o lang nga gitaho ngadto sa Secretary of the Interior, mipasangil nga ang dinaghan nga kaminyoon gipahigayon pa gihapon ug nga kap-atan o labaw pa sa mao nga mga kaminyoon ang gipahigayon didto sa Utah sukad sa miagi nga Hunyo o atol sa miaging tuig, nag-ingon usab nga sa publiko nga mga pakigpulong ang mga lider sa Simbahan nagtudlo, nag-awhag ug nag-aghat nga ipadayon ang pagbaton og daghang asawa—"},{"verse":3,"text":"Busa, ako, isip Presidente sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw, sa ingon niini, sa labing ligdong nga paagi, nagpahayag nga kini nga mga pasangil dili tinuod. Wala kami magtudlo og pagbaton og daghang asawa o sa dinaghan nga kaminyoon, ni motugot ni bisan kinsa nga tawo sa pagsulod ngadto sa mao nga buhat, ug ako dili moangkon nga may kap-atan o bisan unsa pa nga gidaghanon nga nalambigit sa dinaghan nga kaminyoon sulod niana nga panahon nga gipahigayon sa among mga Templo o bisan asa sa ubang dapit sa Teritoryo."},{"verse":4,"text":"Usa ka kaso ang gikataho, diin ang mga grupo mipamatuod nga ang kaminyoon gipahigayon sa Endowment House, sa Siyudad sa Salt Lake, sa Tingpamulak sa 1889, apan wala gayod ako masayod kon kinsa ang mipahigayon sa mao nga seremonya; bisan unsa man ang nabuhat kalabot niini nga butang ako walay kasayoran. Agi og sangpotanan niining gipasangil nga hitabo ang Endowment House, pinaagi sa akong mga pahimangno, gitangtang dayon sa walay paglangan."},{"verse":5,"text":"Kay ang mga balaod gipatuman pinaagi sa Kongreso nga nagdili sa dinaghan nga kaminyoon, diin ang mga balaod gipamulong nga konstitusyonal pinaagi sa korte sa kataposan nga dangpanan, sa ingon ako mopahayag sa akong tumong sa pagtuman niana nga mga balaod, ug sa paggamit sa akong impluwensya ngadto sa mga miyembro sa Simbahan nga akong gidumala sa pagtuman usab niini."},{"verse":6,"text":"Wala sa akong mga pagpanudlo sa Simbahan o ngadto sa akong mga kauban, sulod sa panahon nga gipiho, diin mahimong makataronganon nga sabton ang pagtudlo o iawhag nga magbaton og daghang asawa; ug si bisan kinsa nga Elder sa Simbahan migamit og pinulongan nga ingon og nagpahayag sa bisan unsa niana nga pagtudlo, siya pagabadlongon diha dayon. Ug karon dayag nakong ipahayag sa publiko nga ang akong mga tambag ngadto sa mga Santos sa Ulahing mga Adlaw mao ang paglikay sa paghimo og bisan unsa nga kaminyoon nga gidili sa balaod sa yuta."},{"verse":7,"text":"Wilford Woodruff"},{"verse":8,"text":"Presidente sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw."},{"verse":9,"text":"Si Presidente Lorenzo Snow mitanyag sa mga mosunod:"},{"verse":10,"text":"“Akong isugyot nga, sa pag-ila kang Wilford Woodruff isip ang Presidente sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw, ug mao lamang nga tawo sa yuta sa karon nga panahon nga naghupot sa mga yawe sa mga ordinansa sa pagselyo, kami moisip kaniya nga hingpit nga gitugyanan sa katungod pinaagi sa gahom sa iyang katungdanan sa pag-isyu sa Manipesto nga gibasa atol sa among husay, ug gipetsahan og ika-24 sa Septiyembre 1890, ug nga isip usa ka Simbahan nga nagkatigom sa Kinatibuk-ang Komperensiya, dawaton namo ang iyang pahayag nga may kalabotan sa dinaghan nga kaminyoon nga angay sundon ug kinahanglang ipatuman.”"},{"verse":11,"text":"Salt Lake City, Utah, October 6, 1890."},{"verse":12,"text":"Ang Ginoo dili gayod motugot kanako o ni bisan kinsa nga tawo nga nagbarog isip Presidente niini nga Simbahan nga dad-on kamo sa pagkahisalaag. Wala kini sa plano. Wala kini sa hunahuna sa Dios. Kon ako mangahas man niana, ang Ginoo motangtang kanako gikan sa akong dapit, ug buhaton usab Niya kini ngadto ni bisan kinsa nga tawo nga mangahas sa pagdala sa katawhan sa paghisalaag gikan sa mga orakulo sa Dios ug gikan sa ilang katungdanan. (Ikakan-oman ug usa nga Matag Tunga sa Tuig nga Kinatibuk-ang Komperensiya sa Simbahan, Lunes, Oktubre 6, 1890, Siyudad sa Salt Lake, Utah. Gibalita sa Deseret Evening News, Oktubre 11, 1890, p. 2.)"},{"verse":13,"text":"Dili igsapayan kon kinsa ang mabuhi o kinsa ang mamatay, o kinsa ang gitawag sa pagpangulo niini nga Simbahan, kinahanglang mangulo sila niini pinaagi sa inspirasyon sa Labawng Makagagahom nga Dios. Kon dili nila kini himoon sa ingon niana nga paagi, dili gayod nila kini mahimo. …"},{"verse":14,"text":"Ako adunay pipila ka pagpadayag dili pa dugay, ug hilabihan ka mahinungdanon ngari kanako, ug sultihan ko kamo kon unsay giingon sa Ginoo ngari kanako. Tugoti ako nga mopasabot kaninyo sa pulong nga manipesto. …"},{"verse":15,"text":"Giingnan ako sa Ginoo nga pangutan-on ang mga Santos sa Ulahing mga Adlaw og usa ka pangutana, ug Iya usab akong giingnan nga kon maminaw sila sa unsay akong gisulti kanila ug motubag sa pangutana nga gipangutana kanila, pinaagi sa Espiritu ug gahom sa Dios, silang tanan parehas og itubag, ug silang tanan parehas nga motuo kabahin niini nga butang."},{"verse":16,"text":"Ang pangutana mao kini: Hain ang labing maalamon nga paagi nga angayang sundon sa mga Santos sa Ulahing mga Adlaw—ang pagpadayon ba sa pagpangahas sa paghimo sa dinaghan nga kaminyoon, diin ang balaod sa nasod supak niini ug supak ang kan-oman ka milyon nga katawhan, ug ang bugti mao ang pagsakmit ug pagkawala sa tanang Templo, ug paghunong sa tanang ordinansa diha niana, alang sa buhi ug sa mga patay, ug sa pagkabilanggo sa Unang Kapangulohan ug sa Napulog Duha ug sa mga pangulo sa mga pamilya sa Simbahan, ug pagsakmit sa kaugalingong mga kabtangan sa katawhan (tanan kini maoy makapahunong niini nga buhat); o, human sa pagbuhat ug pag-antos sa unsay atong giantos pinaagi sa atong pagsunod niini nga baroganan nga ihunong ang paghimo og dinaghan nga kaminyoon ug sundon ang balaod, ug pinaagi sa pagbuhat sa ingon magpabilin ang mga Propeta, Apostoles ug mga amahan diha sa panimalay, aron makatudlo sila sa katawhan ug makaalagad sa mga katungdanan sa Simbahan, ug usab ikabilin ang mga Templo ngadto sa mga kamot sa mga Santos, aron makapahigayon sila sa mga ordinansa sa Ebanghelyo, alang sa mga buhi ug sa mga patay?"},{"verse":17,"text":"Gipakita kanako sa Ginoo pinaagi sa panan-awon ug sa pagpadayag sa tukma nga paagi unsa ang mahitabo kon wala nato ihunong kini nga buhat. Kon wala nato kini gihunong, kamo wala na unta magkinahanglan … ni bisan kinsa nga tawo niini nga templo sa Logan; kay ang tanang ordinansa mahunong na sa tibuok yuta sa Zion. Ang kalibog mohari sa tibuok Israel, ug daghang kalalakin-an ang mahimong mga binilanggo. Kini nga kagubot mahitabo unta sa tibuok Simbahan, ug mapugos unta kita sa paghunong sa buhat. Karon, ang pangutana mao, kon kinahanglan ba kini nga hunongon niini nga paagi, o sa paagi nga gipakita sa Ginoo kanato, ug ipabilin ang atong mga Propeta ug Apostoles ug mga amahan nga gawasnong mga tawo, ug ang mga templo diha sa mga kamot sa katawhan, aron ang mga patay matubos. Daghan na kaayo ang naluwas gikan sa balay bilanggoanan sa kalibotan sa mga espiritu pinaagi niini nga katawhan, ug angay bang ipadayon ang buluhaton o ihunong? Mao kini ang pangutana nga akong gipadayag sa atubangan sa mga Santos sa Ulahing mga Adlaw. Kinahanglan kamong mohukom sa inyong kaugalingon. Gusto ko nga kamo ang motubag niini alang sa inyong kaugalingon. Dili ko kini tubagon; apan sultihan ko kamo nga kana mao gayod ang kahimtang nga atong sagubangon isip usa ka katawhan kon wala pa nato sunda ang paagi nga angay natong sundon."},{"verse":18,"text":"… Nakita nako kon unsa gayod ang mahitabo kon wala pay gihimo nga pipila ka butang. Ania kanako kini nga espiritu sulod sa dugay nang panahon. Apan gusto kong mosulti niini: Mahimo ra gyod unta nakong tugotan nga ang tanang templo mawala sa atong mga kamot; mahimo ra gyod unta nga ako mismo mabilanggo, ug motugot nga mahiadto ang uban pang mga tawo, kon wala pa ang Dios sa langit mosugo kanako sa pagbuhat sa unsay akong gibuhat; ug sa dihang miabot ang takna nga ako gisugo sa pagbuhat niana, kining tanan klaro ngari kanako. Miadto ako sa atubangan sa Ginoo ug akong gisulat unsay gisulti sa Ginoo kanako nga isulat. …"},{"verse":19,"text":"Gisulti ko kini kaninyo, aron inyong pamalandongan ug mahunahuna. Ang Ginoo nakigtambayayong kanato. (Cache Stake Conference, Logan, Utah, Dominggo, Nobiyembre 1, 1891. Gibalita sa Deseret Weekly, Nobiyembre 14, 1891.)"},{"verse":20,"text":"Karon sultihan ko kamo kon unsay gipakita ngari kanako ug unsay gihimo sa Anak sa Dios niini nga butang. … Kining tanang butang mahitabo unta, sama kaseguro nga ang Labawng Makagagahom nga Dios buhi, kon kana nga Manipesto wala pa ikahatag. Busa, ang Anak sa Dios mibati nga kana nga butang ipakita ngadto sa Simbahan ug ngadto sa kalibotan alang sa mga katuyoan sa iyang kaugalingong mga hunahuna. Ang Ginoo nagtakda sa pag-establisar sa Zion. Siya nagtakda nga humanon kini nga templo. Iyang gimando nga ang kaluwasan sa mga buhi ug sa mga patay kinahanglang mahatag dinhi sa mga walog sa kabukiran. Ug ang Labawng Makagagahom nga Dios mimando nga ang Yawa dili makababag niini. Kon kana inyong masabtan, mao kana ang yawe niini. (Gikan sa usa ka diskurso sa ikaunom nga sesyon sa pagpahinungod sa Templo sa Salt Lake, Abril 1893. Typescript of Dedicatory Services, Archives, Church Historical Department, Salt Lake City, Utah.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"Ngadto Kaniya nga Mahitungdan:"},{"verse":2,"text":"Niadtong Septiyembre 30, 1978, sa ika-148 nga Matag Tunga sa Tuig nga Kinatibuk-ang Komperensiya sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw, ang mosunod gipresentar ni Presidente N. Eldon Tanner, Unang Magtatambag sa Unang Kapangulohan sa Simbahan:"},{"verse":3,"text":"Sa sayo sa Hunyo niini nga tuig, ang Unang Kapangulohan mipahibalo nga ang usa ka pagpadayag nadawat ni Presidente Spencer W. Kimball nga magtugyan sa pagkapari ug sa mga panalangin sa templo ngadto sa tanang takos nga lalaki nga miyembro sa Simbahan. Si Presidente Kimball mihangyo nga akong ipahibalo sa komperensiya nga human niya madawat kini nga pagpadayag, nga miabot kaniya human sa dugayng pagpamalandong ug pag-ampo didto sa sagradong mga lawak sa balaan nga templo, kini napahibalo na niya sa iyang mga magtatambag, kinsa midawat niini ug miuyon niini. Gipahibalo dayon kini ngadto sa Korum sa Napulog Duha ka Apostoles, kinsa nagkahiusa sa pag-uyon niini, ug sunod niana gipahibalo kini ngadto sa tanang uban pa nga Kinatibuk-ang Awtoridad, kinsa nagkahiusa nga miuyon niini."},{"verse":4,"text":"Si Presidente Kimball mihangyo nga karon akong basahon kini nga sulat:"},{"verse":5,"text":"Hunyo 8, 1978"},{"verse":6,"text":"Ngadto sa tanang kinatibuk-an ug lokal nga mga opisyal sa pagkapari sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw sa tibuok kalibotan:"},{"verse":7,"text":"Minahal kong Kaigsoonan:"},{"verse":8,"text":"Samtang nasaksihan namo ang paglambo sa buhat sa Ginoo ibabaw sa yuta, mapasalamaton kami nga ang katawhan sa daghang kanasoran mitubag sa mensahe sa gipahiuli nga ebanghelyo, ug nagpasakop sa Simbahan sa padayong nagtubo nga gidaghanon. Kini, sa ingon, nakapadasig kanamo uban sa tinguha sa paghatag sa matag takos nga miyembro sa Simbahan sa tanang kahigayonan ug mga panalangin nga mahatag sa ebanghelyo."},{"verse":9,"text":"Nakahibalo sa mga saad nga gihimo sa mga propeta ug mga presidente sa Simbahan nga nag-una kanamo nga sa umaabot nga panahon, diha sa walay kataposang plano sa Dios, tanan sa atong kaigsoonan nga takos mahimo nang makadawat sa pagkapari, ug kay nakasaksi sa kamatinud-anon niadtong wala pa tugoti nga makadawat sa pagkapari, dugay na kaming naghangyo ug nagtinguha gayod alang kanila, ang atong matinud-anon nga kaigsoonan, migahin og daghang takna sa Ibabaw nga Lawak sa Templo nga nangamuyo sa Ginoo alang sa langitnon nga giya."},{"verse":10,"text":"Gidungog niya ang among mga pag-ampo, ug pinaagi sa pagpadayag nagmatuod nga ang dugay nang gisaad nga adlaw miabot na diin ang matag matinud-anon, takos nga lalaki sa Simbahan mahimo nang makadawat sa balaan nga pagkapari, uban sa gahom sa paggamit niining balaanong awtoridad, ug makatagamtam uban sa iyang mga minahal sa matag panalangin nga naggikan niini, lakip na ang mga panalangin sa templo. Sumala niini, ang tanang takos nga lalaki nga miyembro sa Simbahan mahimo nga i-orden sa pagkapari sa walay pag-isip sa kaliwat o kolor. Ang mga lider sa pagkapari gitudloan sa pagsunod sa palisiya sa mainampingong pag-interbiyo sa tanang girekomendar nga i-orden ngadto sa Aaronic o sa Melchizedek nga Pagkapari aron sa pagseguro nga sila nagtuman sa naestablisar nga mga sumbanan sa katakos."},{"verse":11,"text":"Among ipahayag uban sa kaligdong nga ang Ginoo karon mipadayag sa iyang kabubut-on sa pagpanalangin sa tanan niyang anak sa tibuok yuta nga mopatalinghog sa tingog sa iyang awtorisado nga mga sulugoon, ug moandam sa ilang mga kaugalingon sa pagdawat sa matag panalangin sa ebanghelyo."},{"verse":12,"text":"Spencer W. Kimball"},{"verse":13,"text":"N. Eldon Tanner"},{"verse":14,"text":"Marion G. Romney"},{"verse":15,"text":"Ang Unang Kapangulohan"},{"verse":16,"text":"Kay giila si Spencer W. Kimball isip ang propeta, manalagna, ug tigpadayag, ug presidente sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw, kini gisugyot nga kita isip usa ka bahin sa katigoman modawat niini nga pagpadayag isip pulong ug kabubut-on sa Ginoo. Tanan nga mouyon palihog ipakita pinaagi sa pagpataas sa inyong tuo nga kamot. Bisan kinsa nga mosupak pinaagi sa mao gihapon nga timailhan."},{"verse":17,"text":"Ang boto alang sa pagpaluyo sa gihisgotan nga mosyon gikauyonan sa tanan."},{"verse":18,"text":"Salt Lake City, Utah, September 30, 1978."}]}]},{"id":"moses","title":"Moises","englishTitle":"Moses","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Ang mga pulong sa Dios, nga iyang gipamulong ngadto ni Moises sa panahon nga si Moises gidala ngadto sa hilabihan ka taas nga bukid,"},{"verse":2,"text":"Ug nakakita siya sa Dios nawong sa nawong, ug nakigsulti siya kaniya, ug ang himaya sa Dios anaa kang Moises; mao nga si Moises nakalahutay sa iyang atubangan."},{"verse":3,"text":"Ug misulti ang Dios kang Moises, nga nag-ingon: Tan-awa, ako ang Ginoong Dios nga Labawng Makagagahom, ug Walay Kataposan ang akong ngalan; kay ako walay sinugdanan sa mga adlaw o kataposan sa katuigan; ug dili ba kini walay kataposan?"},{"verse":4,"text":"Ug, tan-awa, ikaw mao ang akong anak; mao nga tan-awa, ug akong ipakita kanimo ang mga binuhat sa akong kaugalingong mga kamot; apan dili ang tanan, kay ang akong mga buhat walay kataposan, ug usab ang akong mga pulong, kay dili gayod kini mohunong."},{"verse":5,"text":"Mao nga, walay tawo nga makakita sa akong tanang buhat, gawas kon iyang makita ang akong tanang himaya; ug walay tawo nga makakita sa akong tanang himaya, ug human niana magpabiling buhi dinhi sa yuta."},{"verse":6,"text":"Ug ako adunay buhat alang kanimo, Moises, akong anak; ug ikaw adunay pagkasusama sa akong Bugtong Anak; ug ang akong Bugtong Anak mao ug mamahimo nga Manluluwas, kay puno siya sa grasya ug sa kamatuoran; apan walay laing Dios gawas kanako, ug ang tanang butang ania uban kanako, kay nakaila ako kanilang tanan."},{"verse":7,"text":"Ug karon, tan-awa, kining usa ka butang nga akong ipakita kanimo, Moises, akong anak, kay ikaw anaa sa kalibotan, ug karon ipakita ko kini kanimo."},{"verse":8,"text":"Ug nahitabo nga mitan-aw si Moises, ug nakita ang kalibotan diin siya gilalang; ug nakita ni Moises ang kalibotan ug ang mga kinatumyan niini, ug ang tanang katawhan nga gilalang, ug nalalang; mahitungod niana hilabihan ang iyang kahibulong ug katingala."},{"verse":9,"text":"Ug ang presensya sa Dios mibiya ni Moises, nga ang iyang himaya wala na ni Moises; ug si Moises nag-inusara na lang. Ug samtang nag-inusara siya, natumba siya sa yuta."},{"verse":10,"text":"Ug nahitabo nga milungtad kini sulod sa daghang oras sa wala pa si Moises makadawat pag-usab sa iyang kinaiyanhon nga kusog sama sa tawo; ug miingon siya sa iyang kaugalingon: Karon, tungod niini nasayod ko nga ang tawo walay mahimo, butang nga wala gayod nako mahunahunai sukad."},{"verse":11,"text":"Apan karon ang akong kaugalingong mga mata nakakita sa Dios; apan dili sa akong kinaiyanhon nga mga mata, apan sa akong espirituwal nga mga mata, kay ang akong kinaiyanhon nga mga mata dili mahitabong makakita; kay nalaya na unta ko ug namatay sa iyang atubangan; apan ang iyang himaya ania kanako; ug nakakita ko sa iyang nawong, kay nahimaya ang akong panagway sa iyang atubangan."},{"verse":12,"text":"Ug nahitabo nga sa dihang si Moises nakasulti niini nga mga pulong, tan-awa, si Satanas miabot nga nagtental kaniya, nga nag-ingon: Moises, anak sa tawo, simbaha ako."},{"verse":13,"text":"Ug nahitabo nga si Moises mitan-aw kang Satanas ug miingon: Kinsa man ka? Kay tan-awa, ako mao ang anak sa Dios, nga adunay pagkasama sa iyang Bugtong Anak; ug asa man ang imong himaya, aron mosimba ako kanimo?"},{"verse":14,"text":"Kay tan-awa, dili ako makatan-aw sa Dios, gawas kon ang iyang himaya maana kanako, ug mahimaya ang akong panagway sa iyang atubangan. Apan makatan-aw ko kanimo pinaagi sa akong kinaiyanhon nga pagkatawo. Dili ba ingon man kini niana, sa pagkatinuod?"},{"verse":15,"text":"Bulahan ang ngalan sa akong Dios, kay ang iyang Espiritu wala mobiya sa hingpit kanako, o labot pa asa man ang imong himaya, kay kangitngit man kini ngari kanako? Ug makaila ako tali kanimo ug sa Dios; kay ang Dios nagsulti kanako: Simbaha ang Dios, kay kaniya lamang ikaw moalagad."},{"verse":16,"text":"Pahawa, Satanas; ayaw ko linglaha; kay ang Dios nagsulti kanako: Ikaw adunay pagkasusama sa akong Bugtong Anak."},{"verse":17,"text":"Ug mihatag usab siya kanako og mga sugo sa dihang iya kong gitawag gikan sa nagdilaab nga sagbot, nga nag-ingon: Tawga ang Dios pinaagi sa ngalan sa akong Bugtong Anak, ug simbaha ako."},{"verse":18,"text":"Ug usab miingon si Moises: Dili ko mohunong sa pagtawag sa Dios, ako adunay laing mga butang nga ipangutana kaniya: kay ang iyang himaya misulod kanako, mao nga makaila ako sa kalainan tali kaniya ug kanimo. Pahawa, Satanas."},{"verse":19,"text":"Ug karon, sa dihang si Moises nakasulti na niini nga mga pulong, si Satanas misinggit sa kusog nga tingog, ug nagyawyaw sa yuta, ug mimando, nga nag-ingon: Ako ang Bugtong Anak, simbaha ako."},{"verse":20,"text":"Ug nahitabo nga si Moises misugod sa pagkahadlok sa hilabihan; ug sa dihang misugod siya sa pagkahadlok, iyang nakita ang pagkapait sa impyerno. Bisan pa man, pinaagi sa pagtawag sa Dios, nakadawat siya og kalig-on, ug mimando siya, nga nag-ingon: Pahawa gikan kanako, Satanas, kay niining usa ka Dios lamang ako mosimba, nga mao ang Dios sa himaya."},{"verse":21,"text":"Ug karon si Satanas misugod sa pagkurog, ug ang yuta nauyog; ug si Moises nakadawat og kalig-on, ug mitawag sa Dios, nga nag-ingon: Sa ngalan sa Bugtong Anak, pahawa, Satanas."},{"verse":22,"text":"Ug nahitabo nga misinggit si Satanas sa makusog nga tingog, uban ang pagbakho, ug pagdanguyngoy, ug pagpangagot sa mga ngipon; ug mipahawa siya, gani gikan sa atubangan ni Moises, nga wala na siya makakita kaniya."},{"verse":23,"text":"Ug karon mao kini ang mga butang nga gipamatud-an ni Moises; apan tungod sa pagkadaotan wala na kini sa taliwala sa katawhan."},{"verse":24,"text":"Ug nahitabo nga sa dihang mipahawa na si Satanas sa atubangan ni Moises, nga si Moises mihangad ngadto sa langit, samtang puno sa Espiritu Santo, nga nagpamatuod sa Amahan ug sa Anak;"},{"verse":25,"text":"Ug nagtawag sa ngalan sa Dios, nakita niya ang iyang himaya pag-usab, kay anaa kini kaniya; ug nakadungog siya og usa ka tingog, nga nag-ingon: Bulahan ikaw, Moises, kay ako, ang Labawng Makagagahom, nagpili kanimo, ug ikaw pagahimoong mas gamhanan kaysa daghang katubigan; kay motuman kini sa imong mando sama nga ikaw mao ang Dios."},{"verse":26,"text":"Ug tan-awa, magauban ako kanimo, bisan ngadto sa kataposan sa imong mga adlaw; kay ikaw moluwas sa akong katawhan gikan sa pagkaulipon, gani ang Israel nga akong pinili."},{"verse":27,"text":"Ug nahitabo, samtang nagsulti pa ang tingog, gipunting ni Moises ang iyang mga mata ug nakita ang yuta, oo, gani ang tanan niini; ug walay bisan usa ka tipik niini nga wala niya makita, nga nag-ila niini pinaagi sa Espiritu sa Dios."},{"verse":28,"text":"Ug nakita usab niya ang mga lumulupyo niini, ug walay bisan usa ka kalag nga wala niya makita; ug siya miila kanila pinaagi sa Espiritu sa Dios; ug daghan kaayo sila, gani dili maihap sama sa mga balas sa baybayon."},{"verse":29,"text":"Ug nakita niya ang daghang yuta; ug ang matag yuta gitawag og kalibotan, ug adunay mga lumulupyo sa ibabaw niini."},{"verse":30,"text":"Ug nahitabo nga si Moises mitawag sa Dios, nga nag-ingon: Sultihi ko, ako nangamuyo kanimo, ngano nga kini nga mga butang naingon niana, ug sa unsang paagi nga ikaw mibuhat niini?"},{"verse":31,"text":"Ug tan-awa, ang himaya sa Ginoo anaa ni Moises, mao nga si Moises nakabarog sa atubangan sa Dios, ug nakigsulti kaniya nawong sa nawong. Ug ang Ginoong Dios misulti kang Moises: Alang sa akong kaugalingong katuyoan gibuhat ko kini nga mga butang. Ania ang kaalam ug nagpabilin kini kanako."},{"verse":32,"text":"Ug pinaagi sa pulong sa akong gahom, milalang ako niini, nga mao ang akong Bugtong Anak, nga puno sa grasya ug kamatuoran."},{"verse":33,"text":"Ug ang mga kalibotan nga dili maihap akong gilalang; ug milalang usab ako niini alang sa akong kaugalingong katuyoan; ug pinaagi sa akong Anak milalang ako niini, nga mao ang akong Bugtong Anak."},{"verse":34,"text":"Ug ang una nga lalaki sa tanang lalaki akong gitawag og Adan, nga nagpasabot og daghan."},{"verse":35,"text":"Apan ang kasaysayan lamang niini nga kalibotan, ug ang mga lumulupyo niini, ang akong ihatag kanimo. Kay tan-awa, adunay daghang kalibotan nga milabay na pinaagi sa pulong sa akong gahom. Ug adunay daghan nga karon anaa pa, ug dili sila maihap sa tawo; apan ang tanang butang inihap ngari kanako, kay sila akoa ug nakaila ako kanila."},{"verse":36,"text":"Ug nahitabo nga si Moises misulti sa Ginoo, nga nag-ingon: Pagmaluloy-on sa imong sulugoon, O Dios, ug sultihi ako mahitungod niini nga kalibotan, ug sa mga lumulupyo niini, ug usab sa mga langit, ug niana ang imong sulugoon makontento na."},{"verse":37,"text":"Ug ang Ginoong Dios misulti kang Moises, nga nag-ingon: Ang mga langit, daghan kini, ug dili kini maihap sa tawo; apan inihap kini ngari kanako, kay kini akoa."},{"verse":38,"text":"Ug ingon nga ang usa ka kalibotan molabay, ug ang mga langit niini bisan pa niana adunay lain nga moabot; ug walay kataposan ngadto sa akong mga buhat, ni ngadto sa akong mga pulong."},{"verse":39,"text":"Kay tan-awa, mao kini ang akong buhat ug akong himaya—ang pagpahitabo sa pagka-imortal ug kinabuhing dayon sa tawo."},{"verse":40,"text":"Ug karon, Moises, akong anak, sultihan ko ikaw mahitungod niini nga kalibotan nga imong gibarogan; ug imong isulat ang mga butang nga akong isulti."},{"verse":41,"text":"Ug sa adlaw nga ang katawhan dili mohatag og bili sa akong mga pulong ug tangtangon ang daghan niini gikan sa basahon nga imong gisulat, tan-awa, ako mopabarog og laing sama kanimo; ug kini maangkon pag-usab taliwala sa mga anak sa katawhan—taliwala sa kadaghanan kutob sa motuo."},{"verse":42,"text":"(Kini nga mga pulong mao ang gisulti ngadto ni Moises didto sa bukid, diin ang ngalan dili ipahibalo taliwala sa mga anak sa katawhan. Ug karon gisulti kini nganha kanimo. Ayaw kini ipakita ngadto ni bisan kinsa gawas kanila nga motuo. Ug mao gayod kana. Amen.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"Ug nahitabo nga ang Ginoo nakigsulti kang Moises, nga nag-ingon: Tan-awa, ako nagpadayag kanimo mahitungod niining langit, ug niining yuta; isulat ang mga pulong nga akong isulti. Ako mao ang Sinugdanan ug ang Kataposan, ang Labawng Makagagahom nga Dios; pinaagi sa akong Bugtong Anak milalang ako niini nga mga butang; oo, sa sinugdanan milalang ako sa langit, ug sa yuta nga imong gibarogan."},{"verse":2,"text":"Ug ang yuta walay porma ug walay sulod; ug akong gipangitngit ang kahiladman sa lawod; ug ang akong Espiritu milihok diha sa ibabaw sa tubig; kay ako mao ang Dios."},{"verse":3,"text":"Ug ako, ang Dios, miingon: Himoa nga adunay kahayag; ug dihay kahayag."},{"verse":4,"text":"Ug ako, ang Dios, nakakita sa kahayag; ug kana nga kahayag maayo. Ug ako, ang Dios, mibahin sa kahayag gikan sa kangitngit."},{"verse":5,"text":"Ug ako, ang Dios, mitawag sa kahayag og Adlaw; ug ang kangitngit, akong gitawag og Gabii; ug kini akong gihimo pinaagi sa pulong sa akong gahom, ug kini nahimo sama sa akong gipamulong; ug ang kagabhion ug ang kabuntagon mao ang unang adlaw."},{"verse":6,"text":"Ug usab, ako, ang Dios, miingon: Himoa nga adunay kawanangan taliwala sa tubig, ug kini nahimo, gani sama sa akong gipamulong; ug miingon ko: Himoa kini nga mobahin sa katubigan gikan sa katubigan; ug kini nahimo;"},{"verse":7,"text":"Ug ako, ang Dios, mibuhat sa kawanangan ug mibahin sa mga tubig, oo, ang dagkong mga tubig nga anaa sa ubos sa kawanangan gikan sa mga tubig nga anaa sa ibabaw sa kawanangan, ug kini nahimo, gani sama sa akong gipamulong."},{"verse":8,"text":"Ug ako, ang Dios, mitawag sa kawanangan og Langit; ug ang kagabhion ug ang kabuntagon mao ang ikaduhang adlaw."},{"verse":9,"text":"Ug ako, ang Dios, miingon: Papundoka ang mga tubig nga anaa sa ubos sa langit ngadto sa usa ka dapit, ug kini nahimo; ug ako, ang Dios, miingon: Himoa nga adunay uga nga yuta; ug kini nahimo."},{"verse":10,"text":"Ug ako, ang Dios, mitawag sa uga nga yuta og Yuta; ug ang nagpundok nga mga tubig, akong gitawag og Dagat; ug ako, ang Dios, nakakita nga ang tanang butang nga akong gibuhat mga maayo."},{"verse":11,"text":"Ug ako, ang Dios, miingon: Himoa nga moturok sa yuta ang mga sagbot, ang tanom nga mohatag og binhi, ang mga kahoy nga mamunga, sumala sa matang niini, ug ang kahoy nga mamunga, kansang binhi sama mismo niini maanaa sa yuta, ug kini nahimo gani sumala sa akong gipamulong."},{"verse":12,"text":"Ug ang yuta mipatubo og mga sagbot, matag tanom nga naghatag og binhi sumala sa matang niini, ug ang kahoy nga namunga, kansang binhi kinahanglang sama mismo niini, sumala sa matang niini; ug ako, ang Dios, nakakita nga ang tanang butang nga akong gibuhat mga maayo;"},{"verse":13,"text":"Ug ang kagabhion ug ang kabuntagon mao ang ikatulo nga adlaw."},{"verse":14,"text":"Ug ako, ang Dios, miingon: Himoa nga adunay mga kahayag diha sa kawanangan sa langit, aron mobahin sa adlaw gikan sa gabii, ug himoa kini nga mga timailhan, ug alang sa mga panahon, ug alang sa mga adlaw, ug alang sa katuigan;"},{"verse":15,"text":"Ug himoa kini nga mga kahayag diha sa kawanangan sa langit aron mohatag og kahayag diha sa yuta; ug kini nahimo."},{"verse":16,"text":"Ug ako, ang Dios, mibuhat og duha ka dagko nga mga kahayag; ang mas dako nga kahayag mopatigbabaw sa adlaw, ug ang mas gamay nga kahayag mopatigbabaw sa gabii, ug ang mas dako nga kahayag mao ang adlaw, ug ang mas gamay nga kahayag mao ang buwan; ug ang mga bituon gibuhat usab sumala sa akong pulong."},{"verse":17,"text":"Ug ako, ang Dios, mipahimutang niini diha sa kawanangan sa langit aron maghatag og kahayag diha sa yuta,"},{"verse":18,"text":"Ug ang adlaw mopatigbabaw maadlaw, ug ang buwan mopatigbabaw magabii, ug mobahin sa kahayag gikan sa kangitngit; ug ako, ang Dios, nakakita nga ang tanang butang nga akong gibuhat mga maayo;"},{"verse":19,"text":"Ug ang kagabhion ug ang kabuntagon mao ang ikaupat nga adlaw."},{"verse":20,"text":"Ug ako, ang Dios, miingon: Himoa nga ang mga tubig mopagula og daghang maglihok nga binuhat nga adunay kinabuhi, ug mga langgam nga molupad sa ibabaw sa yuta diha sa lapad nga kawanangan sa langit."},{"verse":21,"text":"Ug ako, ang Dios, milalang og dagkong mga balyena, ug matag buhi nga binuhat nga naglihok, nga ang mga tubig mipagula og daghan, sumala sa ilang matang, ug matag may pako nga langgam, sumala sa matang niini; ug ako, ang Dios, nakakita nga ang tanang butang nga akong gilalang mga maayo."},{"verse":22,"text":"Ug ako, ang Dios, mipanalangin kanila, nga nag-ingon: Pagmabungahon, ug pagsanay, ug pun-a ang mga tubig sa dagat; ug himoa nga ang mga langgam mosanay diha sa yuta;"},{"verse":23,"text":"Ug ang kagabhion ug ang kabuntagon mao ang ikalima nga adlaw."},{"verse":24,"text":"Ug ako, ang Dios, miingon: Himoa nga ang yuta mopagula og mga buhi nga binuhat sumala sa matang niini, mga baka, ug nagkamang nga mga butang, ug mga mananap sa yuta sama sa ilang matang, ug kini nahimo;"},{"verse":25,"text":"Ug ako, ang Dios, mibuhat sa mga mananap sa yuta sumala sa ilang matang, ug mga baka sumala sa ilang matang, ug tanang nagkamang sa yuta sumala sa matang niini; ug ako, ang Dios, nakakita nga kining tanang butang mga maayo."},{"verse":26,"text":"Ug ako, ang Dios, miingon sa akong Bugtong Anak, nga kuyog kanako sukad pa sa sinugdanan: Magbuhat kita og tawo sama sa atong hitsura, sumala sa atong panagway; ug kini nahimo. Ug ako, ang Dios, miingon: Tugoti sila nga adunay kamandoan ibabaw sa mga isda sa dagat, ug ibabaw sa mga langgam sa kahanginan, ug ibabaw sa mga baka, ug ibabaw sa tibuok yuta, ug ibabaw sa matag nagkamang nga butang nga nagkamang sa yuta."},{"verse":27,"text":"Ug ako, ang Dios, milalang og tawo sama sa akong kaugalingong hitsura, sama sa hitsura sa akong Bugtong Anak ako milalang kaniya; lalaki ug babaye ako milalang kanila."},{"verse":28,"text":"Ug ako, ang Dios, mipanalangin kanila, ug miingon kanila: Pagmabungahon, ug pagsanay, ug pun-a ang yuta, ug mangulo niini, ug pagbaton og kamandoan ibabaw sa mga isda sa dagat, ug ibabaw sa mga langgam sa kahanginan, ug ibabaw sa matag buhi nga butang nga naglihok diha sa yuta."},{"verse":29,"text":"Ug ako, ang Dios, misulti sa tawo: Tan-awa, gihatagan ko ikaw sa matag tanom nga mohatag og binhi, nga anaa sa ibabaw sa tibuok yuta, ug matag kahoy diin ang bunga sa kahoy mohatag og binhi; nganha kanimo aron himoon kining pagkaon."},{"verse":30,"text":"Ug ngadto sa matag mananap sa yuta, ug ngadto sa matag langgam sa kahanginan, ug ngadto sa tanang nagkamang sa yuta, nga akong gihatagan og kinabuhi, adunay ihatag nga limpyo nga tanom aron himoon kining pagkaon; ug kini nahimo, gani sumala sa akong gipamulong."},{"verse":31,"text":"Ug ako, ang Dios, nakakita sa tanang butang nga akong gibuhat, ug, tan-awa, ang tanang butang nga akong gibuhat mga maayo kaayo; ug ang kagabhion ug ang kabuntagon mao ang ikaunom nga adlaw."}]},{"chapter":3,"verses":[{"verse":1,"text":"Sa ingon niana ang langit ug ang yuta nahuman, ug ang tanang panon niini."},{"verse":2,"text":"Ug sa ikapito nga adlaw ako, ang Dios, mihunong sa akong buhat, ug sa tanang butang nga akong gihimo; ug ako mipahulay sa ikapito nga adlaw gikan sa tanan nakong buhat, ug ang tanang butang nga akong gihimo nahuman na, ug ako, ang Dios, nakakita nga mga maayo kini;"},{"verse":3,"text":"Ug ako, ang Dios, mipanalangin sa ikapito nga adlaw, ug mibalaan niini; tungod kay diha niini ako mipahulay gikan sa akong tanang buhat diin ako, ang Dios, milalang ug mihimo."},{"verse":4,"text":"Ug karon, tan-awa, sultihan ko kamo, nga kini mao ang mga henerasyon sa langit ug sa yuta, sa dihang gilalang kini, sa adlaw nga ako, ang Ginoong Dios, mihimo sa langit ug sa yuta,"},{"verse":5,"text":"Ug sa matag tanom sa kaumahan sa wala pa kini dinhi sa yuta, ug sa matag hilba sa kaumahan sa wala pa kini motubo. Kay ako, ang Ginoong Dios, milalang sa tanang butang, nga akong gipamulong, sa espirituhanong paagi, sa wala pa kini malalang sa kinaiyanhon nga paagi dinhi sa ibabaw sa yuta. Kay ako, ang Ginoong Dios, wala mopaulan sa ibabaw sa yuta. Ug ako, ang Ginoong Dios, milalang sa tanang anak sa katawhan; ug wala pay tawo nga mougmad sa yuta; kay sa langit gilalang ko sila; ug wala pay unod dinhi sa yuta, ni sa tubig, ni sa hangin;"},{"verse":6,"text":"Apan ako, ang Ginoong Dios, namulong, ug dihay gabon nga mitumaw gikan sa yuta, ug mibisbis sa ibabaw sa tibuok yuta."},{"verse":7,"text":"Ug ako, ang Ginoo, miumol sa tawo gikan sa abog sa yuta, ug miginhawa ngadto sa lungag sa iyang ilong sa ginhawa sa kinabuhi; ug ang tawo nahimong usa ka buhi nga kalag, ang una nga unod diha sa yuta, ang unang tawo usab; bisan pa niana, ang tanang butang gilalang na kaniadto; apan sa espirituhanong paagi kini gilalang ug gihimo sumala sa akong pulong."},{"verse":8,"text":"Ug ako, ang Ginoong Dios, nagtanom og tanaman sa silangang bahin sa Eden, ug didto akong gibutang ang tawo nga akong giumol."},{"verse":9,"text":"Ug gikan sa yuta ako, ang Ginoong Dios, mihimo nga motubo ang matag kahoy, sa kinaiyanhon nga paagi, nga makalipay sa panan-aw sa tawo; ug ang tawo makakita niini. Ug nahimo usab kini nga usa ka buhi nga kalag. Kay kini espirituhanon atol sa adlaw nga gilalang nako kini; kay nagpabilin kini sa kalibotan diin ako, ang Dios, milalang niini, oo, gani ang tanang butang nga akong giandam aron magamit sa tawo; ug ang tawo nakakita nga maayo kini alang sa pagkaon. Ug ako, ang Ginoong Dios, nagtanom usab og kahoy sa kinabuhi sa taliwala sa tanaman, ug usab sa kahoy sa kahibalo sa maayo ug sa daotan."},{"verse":10,"text":"Ug ako, ang Ginoong Dios, mihimo nga ang usa ka suba mogula gikan sa Eden aron mobisbis sa tanaman; ug gikan didto nagbulag-bulag kini, ug nahimong upat ka tinubdan."},{"verse":11,"text":"Ug ako, ang Ginoong Dios, mitawag sa nahauna og Pison, ug nagliyok kini sa tibuok yuta sa Havilah, diin ako, ang Ginoong Dios, mihimo og daghang bulawan;"},{"verse":12,"text":"Ug ang bulawan niana nga yuta maayo, ug dihay bdellium ug ang onyx nga bato."},{"verse":13,"text":"Ug ang ngalan sa ikaduhang suba gitawag og Gihon; nga nagliyok sa tibuok yuta sa Ethiopia."},{"verse":14,"text":"Ug ang ngalan sa ikatulong suba mao ang Hidekel; kana nga nagpadulong paingon sa silangan sa Asiria. Ug ang ikaupat nga suba mao ang Eufrates."},{"verse":15,"text":"Ug ako, ang Ginoong Dios, mikuha sa tawo, ug mibutang kaniya ngadto sa Tanaman sa Eden, aron moatiman niini, ug moalima niini."},{"verse":16,"text":"Ug ako, ang Ginoong Dios, misugo sa tawo, nga nag-ingon: Sa matag kahoy sa tanaman gawasnon ka nga mokaon,"},{"verse":17,"text":"Apan sa kahoy sa kahibalo sa maayo ug sa daotan, dili ka mokaon niini, bisan pa niana, makapili ka alang sa imong kaugalingon, kay gihatag kini kanimo; apan, hinumdomi nga nagdili ako niini, kay sa adlaw nga ikaw mokaon niana ikaw sa pagkatinuod mamatay."},{"verse":18,"text":"Ug ako, ang Ginoong Dios, miingon ngadto sa akong Bugtong Anak, nga dili maayo nga ang tawo mag-inusara; mao nga, ako mohimo og usa ka katabang alang kaniya."},{"verse":19,"text":"Ug gikan sa yuta ako, ang Ginoong Dios, miumol sa matag mananap sa kaumahan, ug matag langgam sa kahanginan; ug misugo nga sila moadto kang Adan, aron makita unsa ang iyang itawag kanila; ug sila usab buhi nga mga kalag; kay ako, ang Dios, miginhawa ngadto kanila og ginhawa sa kinabuhi, ug mimando nga bisag unsa ang itawag ni Adan sa matag buhi nga nilalang, kinahanglan mao kana ang ngalan niini."},{"verse":20,"text":"Ug si Adan mihatag og mga ngalan sa tanang baka, ug sa mga langgam sa kahanginan, ug sa matag mananap sa kaumahan; apan alang kang Adan, walay katabang alang kaniya."},{"verse":21,"text":"Ug ako, ang Ginoong Dios, mihimo nga si Adan mahikatulog og maayo; ug nahikatulog siya, ug akong gikuha ang usa sa iyang mga gusok, ug mitak-op sa unod niini;"},{"verse":22,"text":"Ug ang gusok diin ako, ang Ginoong Dios, mikuha gikan sa tawo, gihimo nako og usa ka babaye, ug midala kaniya ngadto sa lalaki."},{"verse":23,"text":"Ug si Adan miingon: Karon nakahibalo ako nga kini mao ang bukog sa akong mga bukog, ug unod sa akong unod; siya pagatawgon og Babaye, tungod kay gikuha siya gikan sa lalaki."},{"verse":24,"text":"Busa ang lalaki mobiya sa iyang amahan ug inahan, ug mounong sa iyang asawa; ug sila mahimong usa ka unod."},{"verse":25,"text":"Ug silang duha mga hubo, ang lalaki ug ang iyang asawa, ug wala maulaw."}]},{"chapter":4,"verses":[{"verse":1,"text":"Ug ako, ang Ginoong Dios, namulong kang Moises, nga nag-ingon: Kana si Satanas, nga imong gimandoan sa ngalan sa akong Bugtong Anak, mao gihapon sukad sa sinugdanan, ug miduol siya sa akong atubangan, nga nag-ingon—Tan-awa, ania ako, ipadala ako, mahimo ko nimong anak, ug ako motubos sa tanang katawhan, nga walay usa ka kalag nga mawala, ug sa pagkatinuod buhaton ko kini; mao nga ihatag ngari kanako ang imong dungog."},{"verse":2,"text":"Apan, tan-awa, ang akong Hinigugmang Anak, nga akong Hinigugma ug Pinili sukad pa sa sinugdanan, miingon kanako—Amahan, ang imong pagbuot mao ang matuman, ug ang himaya imo sa kahangtoran."},{"verse":3,"text":"Mao nga, tungod kay si Satanas misukol nako, ug nagtinguha sa pagguba sa kabubut-on sa tawo, diin ako, ang Ginoong Dios, mihatag kaniya, ug usab, nga ako kinahanglang mohatag kaniya sa akong kaugalingong gahom; pinaagi sa gahom sa akong Bugtong Anak, misugo ako nga siya isalikway;"},{"verse":4,"text":"Ug siya nahimong Satanas, oo, gani ang yawa, ang amahan sa tanang bakak, sa pag-ilad ug sa pagbuta sa mga tawo, ug sa pagdala nila nga maulipon sumala sa iyang kabubut-on, gani kutob sa dili maminaw sa akong tingog."},{"verse":5,"text":"Ug karon ang bitin mas malipoton kaysa bisan unsang mananap sa umahan nga ako, ang Ginoong Dios, mihimo."},{"verse":6,"text":"Ug si Satanas mibutang niini sulod sa kasingkasing sa bitin, (kay siya nakadala og daghan nga mokuyog kaniya,) ug nagtinguha usab siya sa paglingla ni Eva, kay wala siya masayod sa hunahuna sa Dios, mao nga nagtinguha siya sa paglaglag sa kalibotan."},{"verse":7,"text":"Ug miingon siya ngadto sa babaye: Oo, miingon ba ang Dios—Dili kamo mokaon sa matag kahoy sa tanaman? (Ug misulti siya pinaagi sa ba-ba sa bitin.)"},{"verse":8,"text":"Ug ang babaye miingon sa bitin: Kami mahimo nga mokaon sa bunga sa mga kahoy sa tanaman;"},{"verse":9,"text":"Apan sa bunga sa kahoy nga imong makita sa taliwala sa tanaman, ang Dios nag-ingon—Dili kamo mokaon niana, ni mohikap kamo niana, basin pa unya og mamatay kamo."},{"verse":10,"text":"Ug ang bitin miingon sa babaye: Kamo sa pagkatinuod dili mamatay;"},{"verse":11,"text":"Kay ang Dios nasayod nga sa adlaw nga mokaon kamo niana, nan ang inyong mga mata mabuka, ug mahimo kamo nga sama sa mga dios, masayod sa maayo ug sa daotan."},{"verse":12,"text":"Ug sa dihang nakita sa babaye nga ang kahoy maayo alang sa pagkaon, ug nga kini nahimong maanindot nga tan-awon, ug ang kahoy nga angayng tinguhaon aron makahimo niya nga maalamon, mikuha siya sa bunga niana, ug mikaon, ug usab mihatag sa iyang bana, ug siya mikaon."},{"verse":13,"text":"Ug ang ilang mga mata nabuka, ug nasayod sila nga sila hubo. Ug nagtahi sila og mga dahon sa igos ug naghimo alang sa ilang mga kaugalingon og mga tapis."},{"verse":14,"text":"Ug nakadungog sila sa tingog sa Ginoong Dios, samtang naglakaw sila sa tanaman, sa kabugnaw sa adlaw; ug si Adan ug ang iyang asawa mitago gikan sa atubangan sa Ginoong Dios taliwala sa kakahoyan sa tanaman."},{"verse":15,"text":"Ug ako, ang Ginoong Dios, mitawag kang Adan, ug miingon kaniya: Asa ka paingon?"},{"verse":16,"text":"Ug miingon siya: Nakadungog ko sa imong tingog sa tanaman, ug nahadlok ko, tungod kay akong nakita nga hubo ko, ug mitago ko."},{"verse":17,"text":"Ug ako, ang Ginoong Dios, miingon ni Adan: Kinsa ang nagsulti kanimo nga ikaw hubo? Nakakaon ka ba sa kahoy nga gisugo ko kanimo nga dili nimo angay nga kan-on, kon mao ikaw sa pagkatinuod mamatay?"},{"verse":18,"text":"Ug ang lalaki miingon: Ang babaye nga imong gihatag kanako, ug gisugo nga siya magpabilin uban kanako, siya mihatag kanako sa bunga sa kahoy ug mikaon ako."},{"verse":19,"text":"Ug ako, ang Ginoong Dios, miingon sa babaye: Unsa kini nga butang nga imong gibuhat? Ug ang babaye miingon: Ang bitin milingla kanako, ug mikaon ako."},{"verse":20,"text":"Ug ako, ang Ginoong Dios, miingon sa bitin: Tungod kay ikaw mibuhat niini ikaw pagatunglohon labaw sa tanang baka, ug labaw sa matag mananap sa kaumahan; pinaagi sa imong tiyan ikaw magkamang, ug abog ang imong pagakan-on sa tibuok adlaw sa imong kinabuhi;"},{"verse":21,"text":"Ug mobutang ko og panagdumot tali kanimo ug sa babaye, tali sa imong binhi ug sa iyang binhi; ug siya mosamad sa imong ulo, ug ikaw mosamad sa iyang tikod."},{"verse":22,"text":"Ngadto sa babaye, ako, ang Ginoong Dios, miingon: Ako mopadaghan sa imong kasakit ug sa imong pagpanamkon. Diha sa kasakit ikaw manganak, ug ang imong tinguha adto sa imong bana, ug siya ang magmando ibabaw kanimo."},{"verse":23,"text":"Ug ngadto kang Adan, ako, ang Ginoong Dios, miingon: Tungod kay ikaw naminaw sa tingog sa imong asawa, ug mikaon sa bunga sa kahoy nga akong gisugo nimo, nga nag-ingon—Ikaw dili mokaon niini, pagatunglohon ang yuta alang kanimo; sa kasakit ikaw mokaon niini sa tibuok mga adlaw sa imong kinabuhi."},{"verse":24,"text":"Mga tunok usab, ug mga sampinit ang dad-on niini nganha kanimo, ug ikaw mokaon sa hilba sa kaumahan."},{"verse":25,"text":"Pinaagi sa singot sa imong nawong ikaw makakaon og pan, hangtod nga ikaw mopauli sa yuta—kay sa pagkatinuod ikaw mamatay—kay diha niini ikaw nagagikan: kay ikaw gikan sa abog, ug sa abog ikaw mopauli."},{"verse":26,"text":"Ug si Adan mitawag sa ngalan sa iyang asawa og Eva, tungod kay siya mao ang inahan sa tanang buhi; kay sa ingon niana ako, ang Ginoong Dios, mitawag sa kinaunhan sa tanang babaye, nga daghan."},{"verse":27,"text":"Ngadto ni Adan, ug usab ngadto sa iyang asawa, ako, ang Ginoong Dios, naghimo og mga kupo nga mga panit, ug gisul-ob kanila."},{"verse":28,"text":"Ug ako, ang Ginoong Dios, miingon sa akong Bugtong Anak: Tan-awa, ang tawo nahimong usa kanato nga nasayod sa maayo ug sa daotan; ug karon basin pa unya og mokab-ot ang iyang kamot ug mokuha usab sa kahoy sa kinabuhi, ug mokaon ug mabuhi sa kahangtoran,"},{"verse":29,"text":"Busa ako, ang Ginoong Dios, mopapahawa kaniya gikan sa Tanaman sa Eden, aron sa pagtikad sa yuta diin siya gikuha;"},{"verse":30,"text":"Kay ingon nga ako, ang Ginoong Dios, buhi, maingon man ang akong mga pulong dili mahimong mobalik nga walay hinungdan, kay kon kini nasulti sa akong ba-ba kini kinahanglan gayod nga matuman."},{"verse":31,"text":"Busa ako mihingilin sa tawo, ug ako mibutang sa silangan sa Tanaman sa Eden, og kerubin ug usa ka nagdilaab nga espada, nga nagliyok sa matag agianan aron sa pagbantay sa kahoy sa kinabuhi."},{"verse":32,"text":"(Ug mao kini ang mga pulong nga akong gisulti sa akong sulugoon nga si Moises, ug kini tinuod gani sumala sa akong pagbuot; ug ako namulong niini nganha kanimo. Tan-awa nga dili nimo kini ipakita sa tawo, hangtod nga mosugo ako kanimo, gawas ngadto kanila nga motuo. Amen.)"}]},{"chapter":5,"verses":[{"verse":1,"text":"Ug nahitabo nga human ako, ang Ginoong Dios, mihingilin kanila, nga si Adan misugod sa pagtikad sa yuta, ug sa pagmando ibabaw sa tanang mananap sa kaumahan, ug sa pagkaon sa iyang pan pinaagi sa singot sa iyang agtang, ingon nga ako ang Ginoo misugo kaniya. Ug si Eva, usab, nga iyang asawa, naghago uban kaniya."},{"verse":2,"text":"Ug si Adan nakigdulog sa iyang asawa, ug siya nanganak kaniya og mga anak nga lalaki ug mga anak nga babaye, ug nagsugod sila sa pagsanay ug sa pagpuno sa yuta."},{"verse":3,"text":"Ug sukad nianang higayona, ang mga anak nga lalaki ug mga anak nga babaye ni Adan nagsugod sa pagminyoay diha sa yuta, ug sa pagtikad sa yuta, ug sa pag-atiman sa mga kahayopan, ug usab nanganak sila og mga anak nga lalaki ug mga anak nga babaye."},{"verse":4,"text":"Ug si Adan ug si Eva, nga iyang asawa, mitawag sa ngalan sa Ginoo, ug nakadungog sila sa tingog sa Ginoo gikan sa agianan paingon sa Tanaman sa Eden, nga nagsulti ngadto kanila, ug wala sila makakita kaniya; kay sila gipahilayo gikan sa iyang atubangan."},{"verse":5,"text":"Ug siya mihatag kanila og mga sugo, nga sila kinahanglan nga mosimba sa Ginoo nga ilang Dios, ug kinahanglan nga mohalad sa unang mga anak sa ilang mga kahayopan, isip halad ngadto sa Ginoo. Ug si Adan nagmasulundon sa mga sugo sa Ginoo."},{"verse":6,"text":"Ug human sa daghang adlaw ang usa ka anghel sa Ginoo mipakita ni Adan, nga nag-ingon: Nganong naghalad ka og mga sakripisyo ngadto sa Ginoo? Ug si Adan miingon kaniya: Wala ako masayod, gawas nga ang Ginoo misugo kanako."},{"verse":7,"text":"Ug unya ang anghel misulti, nga nag-ingon: Kini nga butang usa ka pagkasama sa sakripisyo sa Bugtong Anak sa Amahan, nga puno sa grasya ug kamatuoran."},{"verse":8,"text":"Mao nga, buhaton mo ang tanan nga imong buhaton pinaagi sa ngalan sa Anak, ug ikaw maghinulsol ug motawag sa Dios pinaagi sa ngalan sa Anak hangtod sa kahangtoran."},{"verse":9,"text":"Ug niana nga adlaw ang Espiritu Santo mikunsad ni Adan, nga nagpamatuod sa Amahan ug sa Anak, nga nag-ingon: Ako mao ang Bugtong Anak sa Amahan gikan sa sinugdanan, gikan karon ug sa kahangtoran, ingon nga ikaw napukan ikaw mahimong matubos, ug ang tanang katawhan, gani bisan kinsa nga magtinguha."},{"verse":10,"text":"Ug niana nga adlaw si Adan mihimaya sa Dios ug natagbaw, ug misugod sa pagpanagna mahitungod sa tanang pamilya sa yuta, nga nag-ingon: Daygon ang ngalan sa Dios, kay tungod sa akong kalapasan ang akong mga mata nabuka, ug niini nga kinabuhi makabaton ako og kalipay, ug usab sa unod makakita ako sa Dios."},{"verse":11,"text":"Ug si Eva, nga iyang asawa, nakadungog niining tanang butang ug nalipay, nga nag-ingon: Kon dili pa tungod sa atong kalapasan dili unta kita makaangkon og binhi, ug dili gayod masayod sa maayo ug sa daotan, ug sa kalipay sa atong katubsanan, ug sa kinabuhing dayon nga ihatag sa Dios ngadto sa tanang masulundon."},{"verse":12,"text":"Ug si Adan ug si Eva mihimaya sa ngalan sa Dios, ug ang tanang butang ilang gipahibalo sa ilang mga anak nga lalaki ug sa ilang mga anak nga babaye."},{"verse":13,"text":"Ug si Satanas miabot taliwala kanila, nag-ingon: Anak usab ako sa Dios; ug siya misugo kanila, nga nag-ingon: Ayaw pagtuo niini; ug wala sila motuo niini, ug gihigugma nila si Satanas labaw pa kaysa Dios. Ug ang mga tawo sukad nianang higayona nagsugod sa pagkakalibotanon, pagkamahilayon, ug pagkayawan-on."},{"verse":14,"text":"Ug ang Ginoong Dios mitawag sa mga tawo pinaagi sa Espiritu Santo bisan asa ug misugo kanila nga sila kinahanglang maghinulsol;"},{"verse":15,"text":"Ug kutob sa mituo sa Anak, ug naghinulsol sa ilang mga sala, pagaluwason; ug kutob sa dili motuo ug dili maghinulsol, pagasilotan; ug ang mga pulong migula gikan sa ba-ba sa Dios pinaagi sa hugot nga balaod; mao nga kini kinahanglan gayod nga matuman."},{"verse":16,"text":"Ug si Adan ug si Eva, nga iyang asawa, wala mohunong sa pagtawag sa Dios. Ug si Adan nakigdulog ni Eva nga iyang asawa, ug nanamkon siya ug nanganak ni Cain, ug miingon: Ako nakapanamkon og tawo gikan sa Ginoo; mao nga siya dili mahimong mosalikway sa iyang mga pulong. Apan tan-awa, si Cain wala maminaw, nga nag-ingon: Kinsa ang Ginoo nga kinahanglan man ako nga makaila kaniya?"},{"verse":17,"text":"Ug nanamkon na usab siya ug nanganak sa iyang igsoong lalaki nga si Abel. Ug si Abel naminaw sa tingog sa Ginoo. Ug si Abel usa ka magbalantay sa karnero, apan si Cain usa ka magtitikad sa yuta."},{"verse":18,"text":"Ug si Cain nahigugma ni Satanas labaw pa kaysa Dios. Ug si Satanas misugo kaniya, nga nag-ingon: Paghimo og halad ngadto sa Ginoo."},{"verse":19,"text":"Ug paglabay sa panahon nahitabo nga si Cain nagdala og bunga sa yuta isip halad ngadto sa Ginoo."},{"verse":20,"text":"Ug si Abel, nagdala usab siya sa unang mga anak sa iyang kahayopan, ug sa tambok niana. Ug ang Ginoo adunay pagtahod ni Abel, ug sa iyang halad;"},{"verse":21,"text":"Apan kang Cain, ug sa iyang halad, siya walay pagtahod. Karon si Satanas nasayod niini, ug nakapahimuot kini kaniya. Ug hilabihan ang kasuko ni Cain, ug ang iyang panagway nahugno."},{"verse":22,"text":"Ug ang Ginoo misulti ni Cain: Nganong nasuko ka? Nganong subo man ang imong panagway?"},{"verse":23,"text":"Kon magbuhat ka og maayo, ikaw pagadawaton. Ug kon dili ka magbuhat og maayo, ang sala nagahulat sa pultahan, ug si Satanas nagtinguha sa pag-angkon kanimo; ug gawas kon ikaw maminaw sa akong mga sugo, moluwas ako kanimo, ug mahitabo kini kanimo sumala sa iyang tinguha. Ug ikaw ang magmando kaniya;"},{"verse":24,"text":"Kay sukad niining higayona ikaw mahimong amahan sa iyang mga bakak; pagatawgon ikaw og Kapildihan; kay ikaw ingon usab niana sa wala pa ang kalibotan."},{"verse":25,"text":"Ug kini igasulti sa panahon nga moabot—Nga kining mga pagkasalawayon nagsugod kang Cain; kay iyang gisalikway ang mahinungdanong tambag nga nadawat gikan sa Dios; ug mao kini ang tunglo nga akong ibutang diha kanimo, gawas kon ikaw maghinulsol."},{"verse":26,"text":"Ug si Cain nasuko, ug wala na maminaw sa tingog sa Ginoo, ni ngadto kang Abel, nga iyang igsoon nga lalaki, nga naglakaw sa pagkabalaan sa atubangan sa Ginoo."},{"verse":27,"text":"Ug si Adan ug ang iyang asawa nagbangotan sa atubangan sa Ginoo, tungod ni Cain ug sa iyang kaigsoonan."},{"verse":28,"text":"Ug nahitabo nga si Cain mikuha sa usa sa mga anak nga babaye sa iyang mga igsoong lalaki aron pangasaw-on, ug gihigugma nila si Satanas nga labaw pa kaysa Dios."},{"verse":29,"text":"Ug si Satanas misulti ni Cain: Panumpa ngari kanako pinaagi sa imong tutonlan, ug kon ikaw motug-an niini ikaw mamatay; ug papanumpaa ang imong kaigsoonan pinaagi sa ilang mga ulo, ug pinaagi sa buhi nga Dios, nga sila dili motug-an niini; kay kon sila motug-an niini, sila sa pagkatinuod mamatay; ug himoa kini aron ang imong amahan dili masayod niini; ug niini nga adlaw akong itugyan ang imong igsoon nga lalaki nga si Abel nganha sa imong mga kamot."},{"verse":30,"text":"Ug si Satanas nanumpa ni Cain nga siya mobuhat sumala sa iyang mga sugo. Ug kining tanan nga butang gibuhat diha sa tago."},{"verse":31,"text":"Ug si Cain miingon: Sa pagkatinuod ako si Mahan, ang agalon niining dako nga tinago, nga ako mopatay ug makaangkon og bahandi. Mao nga si Cain gitawag og Agalong Mahan, ug siya naghimaya sa iyang pagkadaotan."},{"verse":32,"text":"Ug si Cain miadto sa kaumahan, ug si Cain nakigsulti ni Abel, nga iyang igsoong lalaki. Ug nahitabo nga samtang anaa sila didto sa kaumahan, si Cain midasmag ni Abel, iyang igsoong lalaki, ug mipatay kaniya."},{"verse":33,"text":"Ug si Cain nalipay nianang iyang nabuhat, nga nag-ingon: Gawasnon na ako; segurado gayod nga ang mga kahayopan sa akong igsoong lalaki maangkon na nako."},{"verse":34,"text":"Ug ang Ginoo miingon ngadto ni Cain: Hain si Abel, nga imong igsoon nga lalaki? Ug miingon siya: Wala ko masayod. Ako ba ang magbalantay sa akong igsoong lalaki?"},{"verse":35,"text":"Ug ang Ginoo miingon: Unsa ang imong gibuhat? Ang tingog sa dugo sa imong igsoong lalaki mituaw ngari kanako gikan sa yuta."},{"verse":36,"text":"Ug karon ikaw pagatunglohon gikan sa yuta nga mibuka sa iyang ba-ba aron dawaton ang dugo sa imong igsoong lalaki gikan sa imong kamot."},{"verse":37,"text":"Kon ikaw magtikad sa yuta dili na kini mohatag kanimo sa iyang abot. Ikaw mahimong usa ka laag ug usa ka latagaw diha sa yuta."},{"verse":38,"text":"Ug si Cain miingon sa Ginoo: si Satanas mitental kanako tungod sa mga kahayopan sa akong igsoong lalaki. Ug nasuko usab ako; kay ang iyang halad imong gidawat ug dili ang akoa; ang akong silot labaw pa kaysa akong madaog."},{"verse":39,"text":"Tan-awa ikaw mihingilin kanako niini nga adlaw gikan sa nawong sa Ginoo, ug gikan sa imong nawong ako pagatagoan; ug ako mahimong usa ka laag ug usa ka latagaw dinhi sa yuta; ug mahitabo, nga siya nga makakita kanako mopatay kanako, tungod sa akong pagkadaotan, kay kini nga mga butang dili matago sa Ginoo."},{"verse":40,"text":"Ug ako ang Ginoo miingon kaniya: Si bisan kinsa nga mopatay kanimo, ang panimalos ipahamtang kaniya sa pito ka pilo. Ug ako ang Ginoo nagbutang og usa ka marka diha kang Cain, basin unya og kon kinsa ang makakita kaniya mopatay kaniya."},{"verse":41,"text":"Ug si Cain gipahilayo gikan sa atubangan sa Ginoo, ug uban sa iyang asawa, ug daghan sa iyang kaigsoonan nagpuyo didto sa yuta sa Nod, sa silangan sa Eden."},{"verse":42,"text":"Ug si Cain nakigdulog sa iyang asawa, ug nanamkon siya ug nanganak ni Enoch, nanganak usab siya og daghang anak nga lalaki ug mga anak nga babaye. Ug nagtukod siya og usa ka siyudad, ug iyang ginganlan ang siyudad sama sa ngalan sa iyang anak nga lalaki, nga si Enoch."},{"verse":43,"text":"Ug ngadto ni Enoch natawo si Irad, ug ubang mga anak nga lalaki ug mga anak nga babaye. Ug gipanganak ni Irad si Mahujael, ug ubang mga anak nga lalaki ug mga anak nga babaye. Ug gipanganak ni Mahujael si Methusael, ug ubang mga anak nga lalaki ug mga anak nga babaye. Ug gipanganak ni Methusael si Lamech."},{"verse":44,"text":"Ug si Lamech mikuha sa iyang kaugalingon og duha ka asawa; ang ngalan sa usa si Adah, ug ang ngalan sa lain si Zilla."},{"verse":45,"text":"Ug gipanganak ni Adah si Jabal; siya ang amahan sa nagpuyo diha sa mga tolda, ug sila ang magbalantay sa mga baka; ug ang ngalan sa iyang igsoong lalaki mao si Jubal, nga mao ang amahan sa tanang naggunit sa alpa ug organo."},{"verse":46,"text":"Ug si Zilla, iya usab nga gipanganak si Tubal Cain, usa ka tigtudlo sa tanang panday sa tumbaga ug puthaw. Ug ang igsoon nga babaye ni Tubal Cain ginganlan og Naamah."},{"verse":47,"text":"Ug si Lamech miingon sa iyang mga asawa, nga si Adah ug si Zilla: Paminaw sa akong tingog, kamo nga mga asawa ni Lamech, paminaw sa akong isulti; kay nakapatay ako og usa ka tawo tungod sa pagsamad kanako, ug usa ka batan-on nga tawo tungod sa pagpasakit kanako."},{"verse":48,"text":"Kon pito ka pilo ang pagpanimalos kang Cain, sa pagkatinuod ang kang Lamech kapitoan ug pito ka pilo;"},{"verse":49,"text":"Kay si Lamech nakasulod sa panumpa ngadto ni Satanas, sumala sa paagi ni Cain, diin nahimo siya nga si Agalong Mahan, ang agalon nianang dako nga tinago nga gihatag ngadto ni Cain pinaagi ni Satanas; ug si Irad, ang anak ni Enoch, sa pagkasayod sa ilang tinago, misugod sa pagtug-an niini ngadto sa mga anak nga lalaki ni Adan;"},{"verse":50,"text":"Mao nga si Lamech, kay nasuko, mipatay kaniya, dili sama ni Cain, sa iyang igsoong lalaki nga si Abel, aron makaangkon og bahandi, apan siya mipatay kaniya tungod sa gipanumpaan."},{"verse":51,"text":"Kay, sukad sa mga adlaw ni Cain, adunay tinago nga kalihokan, ug ang ilang mga buhat anaa sa kangitngit, ug nailhan nila ang matag lalaki nga iyang igsoon."},{"verse":52,"text":"Mao nga ang Ginoo mitunglo ni Lamech, ug sa iyang panimalay, ug nilang tanan nga nanumpa ni Satanas; kay wala sila maghupot sa mga sugo sa Dios, ug nakapasubo kini sa Dios, ug wala siya mangalagad ngadto kanila, ug ang ilang mga buhat mga salawayon, ug misugod sa pagkatap taliwala sa tanang anak nga lalaki sa mga tawo. Ug anaa kini taliwala sa mga anak nga lalaki sa mga tawo."},{"verse":53,"text":"Ug taliwala sa mga anak nga babaye sa mga tawo kini nga mga butang wala hisgoti, tungod kay si Lamech nakasulti sa tinago ngadto sa iyang mga asawa, ug misukol sila batok kaniya, ug mipadayag niini nga mga butang sa lain nga nasod, ug walay mga kaluoy;"},{"verse":54,"text":"Mao nga si Lamech gisaway, ug gisalikway, ug wala moipon taliwala sa mga anak nga lalaki sa mga tawo, basin pa unya og siya mamatay."},{"verse":55,"text":"Ug sa ingon niana ang mga buhat sa kangitngit misugod sa pagdaghan taliwala sa tanang anak nga lalaki sa mga tawo."},{"verse":56,"text":"Ug ang Dios mitunglo sa yuta og hilabihan kapintas nga tunglo, ug nasuko sa daotan, uban sa tanang anak nga lalaki sa mga tawo nga iyang gibuhat;"},{"verse":57,"text":"Kay wala sila maminaw sa iyang tingog, ni motuo sa iyang Bugtong Anak, bisan kaniya nga iyang gipadayag nga moabot sa tunga-tunga sa panahon, nga giandam sa wala pa ang katukoran sa kalibotan."},{"verse":58,"text":"Ug sa ingon niana ang Ebanghelyo gisugdan sa pagsangyaw, gikan sa sinugdanan, ingon nga gipadayag sa balaang mga anghel nga gipadala gikan sa atubangan sa Dios, ug pinaagi sa iyang kaugalingon nga tingog, ug pinaagi sa gasa sa Espiritu Santo."},{"verse":59,"text":"Ug sa ingon niana ang tanang butang natugyan ngadto kang Adan, pinaagi sa balaan nga ordinansa, ug ang Ebanghelyo gisangyaw, ug usa ka balaod ang gipadala, nga kini kinahanglang maanaa sa kalibotan, hangtod sa kataposan niini; ug mao gayod kadto. Amen."}]},{"chapter":6,"verses":[{"verse":1,"text":"Ug naminaw si Adan sa tingog sa Dios, ug mitawag sa iyang mga anak nga lalaki sa paghinulsol."},{"verse":2,"text":"Ug miila pag-usab si Adan sa iyang asawa, ug nanganak og usa ka lalaki ang iyang asawa, ug gitawag niya ang iyang ngalan og Seth. Gihimaya ni Adan ang ngalan sa Dios; kay miingon siya: Gihatagan ako sa Dios og laing binhi, puli ni Abel, nga gipatay ni Cain."},{"verse":3,"text":"Gipadayag sa Dios ang iyang kaugalingon ngadto ni Seth, ug wala siya mosukol, apan mihalad og usa ka madawat nga sakripisyo, sama sa iyang igsoong lalaki nga si Abel. Ug kaniya usab natawo ang usa ka anak nga lalaki, ug gitawag niya ang iyang ngalan og Enos."},{"verse":4,"text":"Ug misugod dayon kini nga mga tawo sa pagtawag sa ngalan sa Ginoo, ug gipanalanginan sila sa Ginoo;"},{"verse":5,"text":"Ug ang usa ka basahon sa handomanan gitipigan, diin nahisulat, sa pinulongan ni Adan, kay kini gihatag kutob sa gitawag sa Dios nga mosulat pinaagi sa espiritu sa inspirasyon;"},{"verse":6,"text":"Ug pinaagi niini gitudloan ang ilang mga anak sa pagbasa ug pagsulat, kay nakaangkon og usa ka pinulongan nga putli ug walay mansa."},{"verse":7,"text":"Karon kining mao nga Pagkapari, nga diha na sa sinugdanan, maanaa usab sa kataposan sa kalibotan."},{"verse":8,"text":"Karon kini nga panagna nga gipamulong ni Adan, samtang siya gidasig sa Espiritu Santo, ug ang usa ka kasaysayan sa kagikanan gitipigan sa mga anak sa Dios. Ug kini mao ang basahon sa mga henerasyon ni Adan, nag-ingon: Sa adlaw nga ang Dios milalang sa tawo, sa panagway sa Dios mibuhat siya kaniya;"},{"verse":9,"text":"Diha sa imahe sa iyang kaugalingon nga lawas, lalaki ug babaye, gilalang niya sila, ug gipanalanginan sila, ug ginganlan sila og Adan, sa adlaw nga gilalang sila ug nahimong buhi nga mga kalag sa yuta diha sa tiilan sa Dios."},{"verse":10,"text":"Ug si Adan nagpuyo og usa ka gatos ug katloan ka tuig, ug nanganak og usa ka anak nga lalaki sa iyang kaugalingon nga panagway, sama sa iyang kaugalingon nga imahe, ug gitawag ang iyang ngalan og Seth."},{"verse":11,"text":"Ug ang mga adlaw ni Adan, human siya nanganak ni Seth, walo ka gatos ka tuig, ug nanganak siya og daghang anak nga lalaki ug anak nga babaye;"},{"verse":12,"text":"Ug ang tanang adlaw nga si Adan nagpuyo sa yuta siyam ka gatos ug katloan ka tuig, ug siya namatay."},{"verse":13,"text":"Nagpuyo si Seth sa yuta og usa ka gatos ug lima ka tuig, ug nanganak ni Enos, ug nanagna sa iyang tanang adlaw, ug nagtudlo sa iyang anak nga si Enos sa mga pamaagi sa Dios; busa si Enos nanagna usab."},{"verse":14,"text":"Ug nagpuyo si Seth sa yuta, human siya nanganak ni Enos, walo ka gatos ug pito ka tuig, ug nanganak og daghang anak nga lalaki ug anak nga babaye."},{"verse":15,"text":"Ug ang katawhan daghan kaayo sa ibabaw sa tibuok yuta. Ug niadtong mga panahona si Satanas adunay dako nga kamandoan sa mga tawo, ug mipayugot sa ilang mga kasingkasing; ug sukad niadto miabot ang mga gubat ug pagpaagas sa dugo; ug ang kamot sa usa ka tawo gibatok ngadto sa iyang kaugalingon nga igsoon, sa pagpahamtang sa kamatayon, tungod sa tinago nga mga buhat, nga nagtinguha og gahom."},{"verse":16,"text":"Ang tanang adlaw ni Seth mga siyam ka gatos ug napulog duha ka tuig, ug namatay siya."},{"verse":17,"text":"Ug nagpuyo si Enos sa yuta og kasiyaman ka tuig, ug nanganak ni Cainan. Ug si Enos ug ang nahibilin sa katawhan sa Dios mibiya gikan sa yuta, nga gitawag og Shulon, ug mipuyo sa usa ka yuta sa saad, nga iyang gitawag parehas sa ngalan sa iyang kaugalingon nga anak, nga ginganlan niya og Cainan."},{"verse":18,"text":"Ug padayong nagpuyo si Enos sa yuta, human siya nanganak ni Cainan, walo ka gatos ug napulog lima ka tuig, ug nanganak og daghang anak nga lalaki ug anak nga babaye. Ug ang tanang adlaw ni Enos mga siyam ka gatos ug lima ka tuig, ug namatay siya."},{"verse":19,"text":"Ug nagpadayon sa pagpuyo si Cainan sa yuta og kapitoan ka tuig, ug nanganak ni Mahalaleel; ug si Cainan nagpuyo sa yuta human siya nanganak ni Mahalaleel mga walo ka gatos ug kap-atan ka tuig, ug nanganak og mga anak nga lalaki ug mga anak nga babaye. Ug ang tanang adlaw ni Cainan mga siyam ka gatos ug napulo ka tuig, ug namatay siya."},{"verse":20,"text":"Ug nagpuyo si Mahalaleel sa yuta og kan-uman ug lima ka tuig, ug nanganak ni Jared; ug nagpuyo si Mahalaleel sa yuta, human siya nanganak ni Jared, walo ka gatos ug katloan ka tuig, ug nanganak og mga anak nga lalaki ug mga anak nga babaye. Ug ang tanang adlaw ni Mahalaleel mga walo ka gatos ug kasiyaman ug lima ka tuig, ug namatay siya."},{"verse":21,"text":"Ug nagpuyo si Jared sa yuta og usa ka gatos ug kan-uman ug duha ka tuig, ug nanganak ni Enoch; ug nagpuyo si Jared sa yuta, human siya nanganak ni Enoch, mga walo ka gatos ka tuig, ug nanganak og mga anak nga lalaki ug mga anak nga babaye. Ug gitudloan ni Jared si Enoch sa tanang pamaagi sa Dios."},{"verse":22,"text":"Ug mao kini ang kasaysayan sa kagikanan sa mga anak ni Adan, kinsa mao ang anak sa Dios, nga gikaistorya sa Dios, sa iyang kaugalingon."},{"verse":23,"text":"Ug sila mao ang mga tigsangyaw sa pagkamatarong, ug namulong ug nanagna, ug mitawag sa tanang tawo, bisan asa, sa paghinulsol; ug ang pagtuo gitudlo ngadto sa katawhan."},{"verse":24,"text":"Ug nahitabo nga ang tanang adlaw ni Jared siyam ka gatos ug kan-uman ug duha ka tuig, ug namatay siya."},{"verse":25,"text":"Ug si Enoch mipuyo sa yuta ug kan-uman ug lima ka tuig, ug nanganak ni Metusela."},{"verse":26,"text":"Ug nahitabo nga mipanaw si Enoch sa yuta, taliwala sa katawhan; ug samtang mipanaw siya, mikunsad ang Espiritu sa Dios gikan sa langit, ug mipuyo diha kaniya."},{"verse":27,"text":"Ug nakadungog siya og tingog gikan sa langit, nga nag-ingon: Enoch, akong anak, panagna ngadto niini nga katawhan, ug isulti ngadto kanila—Paghinulsol, kay ang Ginoo nag-ingon: Nasuko ako niini nga katawhan, ug ang akong mapintas nga kasuko napukaw batok kanila; kay ang ilang kasingkasing nag-anam sa pagkatig-a, ug ang ilang mga dunggan dili makadungog, ug ang ilang mga mata dili makakita sa layo;"},{"verse":28,"text":"Ug sulod niining daghang henerasyon, sukad sa adlaw nga ako milalang kanila, sila nahisalaag, ug milimod kanako, ug nangita sa ilang kaugalingon nga mga kaalam diha sa kangitngit; ug sa ilang mga pagkasalawayon nagplano sila sa pagpatay, ug wala motuman sa mga sugo, nga akong gihatag ngadto sa ilang amahan, nga si Adan."},{"verse":29,"text":"Mao nga, sayop ang ilang panumpa sa ilang kaugalingon, ug, pinaagi sa ilang mga panumpa, gidala nila diha sa ilang kaugalingon ang kamatayon; ug ang impyerno akong giandam alang kanila, kon dili sila maghinulsol;"},{"verse":30,"text":"Ug kini mao ang balaod, nga gipadala nako sa sinugdanan sa kalibotan, gikan sa akong kaugalingon nga ba-ba, gikan sa katukoran niini, ug pinaagi sa mga ba-ba sa akong mga sulugoon, nga inyong mga amahan, gimando nako kini, gani ingon nga gipadala kini dinhi sa kalibotan, ngadto sa mga kinatumyan niini."},{"verse":31,"text":"Ug sa dihang nakadungog si Enoch niini nga mga pulong, miyukbo siya sa yuta, sa atubangan sa Ginoo, ug misulti sa atubangan sa Ginoo, nga nag-ingon: Nganong nakakaplag ako og pag-uyon sa imong panan-aw, ug nga usa lamang ako ka batan-on, ug ang tanang katawhan nagdumot kanako; kay dili ko maayong mosulti; kay imo ba akong sulugoon?"},{"verse":32,"text":"Ug gisultihan sa Ginoo si Enoch: Lakaw ug buhata ang gisugo nako nimo, ug walay tawo nga makatulisok kanimo. Bukha ang imong ba-ba, ug mapuno kini, ug hatagan ko ikaw og igsusulti, kay ang tanang unod ania sa akong mga kamot, ug buhaton nako unsay akong hunahuna nga maayo."},{"verse":33,"text":"Sultihi kini nga katawhan: Pilia ninyo niining adlawa, sa pag-alagad sa Ginoong Dios nga nagbuhat kaninyo."},{"verse":34,"text":"Tan-awa ang akong Espiritu anaa kanimo, mao nga ang imong tanang pulong hatagan nako og kaangayan; ug ang kabukiran mahanaw sa imong atubangan, ug ang mga suba mobalhin sa ilang agianan; ug makig-uban ikaw kanako, ug ako nganha kanimo; busa lakaw uban kanako."},{"verse":35,"text":"Ug namulong ang Ginoo ngadto ni Enoch, ug gisultihan siya: Dihogi ang imong mga mata sa lapok, ug hugasi kini, ug ikaw makakita. Ug gibuhat niya kini."},{"verse":36,"text":"Ug nakita niya ang mga espiritu nga gilalang sa Dios; ug nakita usab niya ang mga butang nga dili makita sa kinaiyanhon nga mata; ug sukad niadto ang panultihon miabot sa layong dapit sa yuta: Usa ka manalagna ang gimatuto sa Ginoo ngadto sa iyang katawhan."},{"verse":37,"text":"Ug nahitabo nga miadto si Enoch sa yuta, taliwala sa katawhan, nagtindog sa mga bungtod ug sa taas nga mga dapit, ug misinggit og makusog nga tingog, nagpamatuod batok sa ilang mga binuhatan; ug ang tanang tawo wala mahimuot kaniya."},{"verse":38,"text":"Ug miduol sila aron maminaw kaniya, diha sa taas nga mga dapit, nga nag-ingon ngadto sa mga magbalantay sa tolda: Pagpabilin dinhi ug bantayi ang mga tolda, samtang moadto kami didto aron motan-aw sa manalagna, kay nanagna siya, ug dihay usa ka katingalahan nga butang sa yuta; usa ka ihalas nga tawo ang miabot taliwala kanato."},{"verse":39,"text":"Ug nahitabo sa dihang nakadungog sila kaniya, walay tawo nga mibakyaw sa mga kamot ngadto kaniya; kay ang kahadlok miabot kanilang tanan nga nakadungog kaniya; kay siya naglakaw uban sa Dios."},{"verse":40,"text":"Ug dihay miduol nga usa ka tawo ngadto kaniya, kansang ngalan mao si Mahijah, ug misulti ngadto kaniya: Sultihi kami sa yano kon kinsa ka, ug diin ka gikan?"},{"verse":41,"text":"Ug gisultihan niya sila: Gikan ko sa yuta sa Cainan, ang yuta sa akong mga amahan, usa ka yuta sa pagkamatarong hangtod niining adlawa. Ug ang akong amahan mitudlo kanako sa tanang pamaagi sa Dios."},{"verse":42,"text":"Ug nahitabo, samtang ako mipanaw gikan sa yuta sa Cainan, subay sa silangan nga dagat, nakita nako ang usa ka panan-awon; ug tan-awa, ang mga langit maoy akong nakita, ug namulong ang Ginoo kanako, ug mihatag kanako og sugo; mao nga, tungod niini nga katuyoan, sa pagtuman sa sugo, namulong ako niini nga mga pulong."},{"verse":43,"text":"Ug mipadayon si Enoch sa iyang pakigpulong, nga nag-ingon: Ang Ginoo nga nakigsulti kanako, mao usab ang Dios sa langit, ug siya ang akong Dios, ug ang inyong Dios, ug kamo akong kaigsoonan, ug ngano nga misalig kamo sa inyong kaugalingon, ug milimod sa Dios sa langit?"},{"verse":44,"text":"Gibuhat niya ang mga langit; ang yuta mao ang iyang tumbanan; ug ang katukoran niini iya. Tan-awa, gipahimutang niya niini, ang panon sa mga tawo iyang gidala sa ibabaw niini."},{"verse":45,"text":"Ug miabot ang kamatayon sa atong mga amahan; bisan pa niana nakaila kita kanila, ug dili ikalimod, ug gani ang una sa tanan nakaila kita, gani ni Adan."},{"verse":46,"text":"Kay usa ka basahon sa handomanan atong gisulat, sumala sa sundanan nga gihatag pinaagi sa tudlo sa Dios; ug kini gihatag sa atong kaugalingon nga pinulongan."},{"verse":47,"text":"Ug samtang namulong si Enoch sa mga pulong sa Dios, ang katawhan nangurog, ug dili makalahutay sa iyang atubangan."},{"verse":48,"text":"Ug gisultihan niya sila: Tungod kay si Adan napukan, kita usab; ug pinaagi sa iyang pagkapukan miabot ang kamatayon; ug kita nahimong mga mag-aambit sa kasakit ug sa kaalaot."},{"verse":49,"text":"Tan-awa si Satanas miabot taliwala sa katawhan, ug mitintal kanila sa pagsimba kaniya; ug ang mga tawo nahimong kalibotanon, mahilayon, ug yawan-on, ug gisalikway gikan sa atubangan sa Dios."},{"verse":50,"text":"Apan gipahibalo sa Dios ngadto sa atong mga amahan nga ang tanang tawo kinahanglan nga maghinulsol."},{"verse":51,"text":"Ug gitawag niya ang atong amahan nga si Adan pinaagi sa iyang kaugalingon nga tingog, nga nag-ingon: Ako mao ang Dios; gibuhat nako ang kalibotan, ug ang mga tawo sa wala pa sila matawo."},{"verse":52,"text":"Ug gisultihan usab niya siya: Kon moduol ka kanako, ug maminaw sa akong tingog, ug motuo, ug maghinulsol sa imong tanang kalapasan, ug magpabunyag, bisan sa tubig, pinaagi sa ngalan sa akong Bugtong Anak, nga puno sa grasya ug kamatuoran, nga mao si Jesukristo, ang bugtong ngalan nga ihatag ubos sa langit, diin ang kaluwasan moabot sa katawhan, makadawat ka sa gasa sa Espiritu Santo, mangayo sa tanang butang pinaagi sa iyang ngalan, ug bisan unsa ang imong pangayoon, ihatag kini kanimo."},{"verse":53,"text":"Ug namulong ang atong amahan nga si Adan ngadto sa Ginoo, ug miingon: Nganong kinahanglan man nga maghinulsol ang mga tawo ug magpabunyag sa tubig? Ug gisultihan sa Ginoo si Adan: Tan-awa gipasaylo ko ikaw sa imong kalapasan didto sa Tanaman sa Eden."},{"verse":54,"text":"Tungod niini miabot ang panultihon sa laing dapit taliwala sa katawhan, nga ang Anak sa Dios miula sa orihinal nga sala, diin ang mga sala sa mga ginikanan dili pagatubagon diha sa mga ulo sa mga anak, kay sila walay sala gikan sa katukoran sa kalibotan."},{"verse":55,"text":"Ug namulong ang Ginoo ngadto ni Adan, nga nag-ingon: Tungod kay gipanamkon ang imong mga anak diha sa sala, nga sa ingon niana kon sila mosugod sa pagtubo, ang sala anaa na diha sa ilang mga kasingkasing, ug matilawan nila ang kapait, aron masayod sila sa paghatag og bili sa maayo."},{"verse":56,"text":"Ug gihatag kini kanila aron masayod sa maayo gikan sa daotan; mao nga sila mga tinugyanan sa ilang mga kaugalingon, ug mihatag ako kanimo og lain nga balaod ug sugo."},{"verse":57,"text":"Mao nga itudlo kini sa imong mga anak, aron ang tanang tawo, bisan asa, kinahanglang maghinulsol, o dili sila makapanunod sa gingharian sa Dios, kay walay mahugaw nga butang nga makapuyo didto, o makapuyo sa iyang atubangan; kay, sa pinulongan ni Adan, Tawo sa Pagkabalaan mao ang iyang ngalan, ug ang ngalan sa iyang Bugtong Anak mao ang Anak sa Tawo, gani si Jesukristo, usa ka matarong nga Maghuhukom, nga moabot sa tunga-tunga sa panahon."},{"verse":58,"text":"Busa mohatag ko kanimo og usa ka sugo, sa pagtudlo niini nga mga butang sa gawasnon nga paagi ngadto sa imong mga anak, nga mag-ingon:"},{"verse":59,"text":"Nga tungod sa kalapasan miabot ang pagkapukan, diin nga pagkapukan nagdala og kamatayon, ug tungod kay natawo ka sa kalibotan pinaagi sa tubig, ug dugo, ug sa espiritu, nga gibuhat nako, ug busa gikan sa abog nahimo ang buhi nga kalag, sa ingon niana ikaw kinahanglan nga matawo pag-usab ngadto sa gingharian sa langit, sa tubig, ug sa Espiritu, ug malimpyohan pinaagi sa dugo, gani sa dugo sa akong Bugtong Anak; aron ikaw mabalaan gikan sa tanang sala, ug matagamtam ang mga pulong sa kinabuhing dayon niini nga kalibotan, ug kinabuhing dayon sa kalibotan nga moabot, gani ang imortal nga himaya;"},{"verse":60,"text":"Kay pinaagi sa tubig ikaw maghupot sa sugo; pinaagi sa Espiritu ikaw kahatagan og kaangayan, ug pinaagi sa dugo ikaw pagabalaanon;"},{"verse":61,"text":"Busa gihatag kini aron magpabilin diha kanimo; ang talaan sa langit; ang Maghuhupay; ang malinawong mga butang sa imortal nga himaya; ang kamatuoran sa tanang butang; nga nagpalihok sa tanang butang, nga nakapabuhi sa tanang butang; nga nasayod sa tanang butang, ug aduna sa tanang gahom sumala sa kaalam, kaluoy, kamatuoran, kaangayan, ug paghukom."},{"verse":62,"text":"Ug karon, tan-awa, sultihan ko ikaw: Kini mao ang plano sa kaluwasan ngadto sa tanang tawo, pinaagi sa dugo sa akong Bugtong Anak, nga moabot sa tunga-tunga sa panahon."},{"verse":63,"text":"Ug tan-awa, ang tanang butang adunay ilang pagkasama, ug ang tanang butang gilalang ug gibuhat aron sa pagpamatuod kanako, mga butang nga temporal, ug mga butang nga espirituhanon; mga butang nga anaa sa mga langit, ug mga butang nga anaa sa ibabaw sa yuta, ug mga butang nga anaa sa yuta, ug mga butang nga anaa sa ilawom sa yuta, sa ibabaw ug sa ilawom: ang tanang butang nagpamatuod kanako."},{"verse":64,"text":"Ug nahitabo, sa dihang nakapamulong na ang Ginoo ngadto ni Adan, ang atong amahan, nga si Adan mituaw ngadto sa Ginoo, ug gidala siya sa Espiritu sa Ginoo, ug gidala ngadto sa tubig, ug gipaunlod ilawom sa tubig, ug gihaw-as gikan sa tubig."},{"verse":65,"text":"Ug sa ingon nabunyagan siya, ug mikunsad ang Espiritu sa Dios diha kaniya, ug sa ingon niana siya natawo sa Espiritu, ug nabuhi ang kaugalingong pagkatawo."},{"verse":66,"text":"Ug nakadungog siya og tingog gikan sa langit, nga nag-ingon: Gibunyagan ka pinaagi sa kalayo, ug sa Espiritu Santo. Kini mao ang talaan sa Amahan, ug sa Anak, gikan karon ug hangtod sa kahangtoran;"},{"verse":67,"text":"Ug ikaw anaa subay sa iyang kapunongan nga walay sinugdanan sa mga adlaw o kataposan sa mga tuig, gikan sa tanang kahangtoran ngadto sa tanang kahangtoran."},{"verse":68,"text":"Tan-awa, ikaw usa ngari kanako, usa ka anak sa Dios; ug sa ingon ang tanan mahimo nakong mga anak nga lalaki. Amen."}]},{"chapter":7,"verses":[{"verse":1,"text":"Ug nahitabo nga mipadayon si Enoch sa iyang pakigpulong, nga nag-ingon: Tan-awa, mitudlo ang atong amahan nga si Adan niini nga mga butang, ug daghan ang mituo ug nahimong mga anak sa Dios, ug daghan ang wala motuo, ug namatay diha sa ilang mga sala, ug nagpaabot uban sa kahadlok, sa kasakit, kay ang nagdilaab nga makataronganon nga kasuko sa Dios ibu-bo diha kanila."},{"verse":2,"text":"Ug gikan niana nga panahon misugod si Enoch sa pagpanagna, nag-ingon ngadto sa katawhan, nga: Samtang nagpanaw ko, ug nagbarog sa dapit sa Mahujah, ug mituaw ngadto sa Ginoo, dihay miabot nga tingog gikan sa langit, nga nag-ingon—Balik, ug lakaw ngadto sa bungtod sa Simeon."},{"verse":3,"text":"Ug nahitabo nga mibalik ko ug mitungas sa bungtod; ug samtang nagbarog ko sa bungtod, nakita nako ang mga langit nga miabli, ug gisul-oban ko sa himaya;"},{"verse":4,"text":"Ug nakita nako ang Ginoo; ug nagbarog siya sa akong atubangan, ug nakigsulti siya nako, gani sama sa usa ka tawo nga nakigsulti sa lain, nawong sa nawong; ug gisultihan ko niya: Tan-awa, ug ipakita ko kanimo ang kalibotan sulod sa daghang henerasyon."},{"verse":5,"text":"Ug nahitabo nga nakita nako sa walog sa Shum, ug tan-awa, daghang katawhan ang nagpuyo sa mga tolda, nga mao ang katawhan sa Shum."},{"verse":6,"text":"Ug gisultihan na usab ako sa Ginoo: Tan-awa; ug mitan-aw ko paingon sa amihanan, ug nakita nako ang katawhan sa Canaan, nga nagpuyo sa mga tolda."},{"verse":7,"text":"Ug gisultihan ako sa Ginoo: Panagna; ug nanagna ko, nga nag-ingon: Tan-awa ang katawhan sa Canaan, nga daghan kaayo, mosulong sa gubat batok sa katawhan sa Shum, ug mopatay kanila aron malaglag sila sa hingpit; ug ang katawhan sa Canaan managbahin-bahin diha sa yuta, ug ang yuta dili katuboan ug dili makapamunga, ug walay laing katawhan ang makapuyo didto gawas sa katawhan sa Canaan;"},{"verse":8,"text":"Kay tan-awa, tunglohon sa Ginoo ang yuta sa tumang kainit, ug ang pagkadili katuboan niana molungtad hangtod sa hangtod; ug nahimong itomon ang tanang anak sa Canaan, nga sila gitamay taliwala sa tanang katawhan."},{"verse":9,"text":"Ug nahitabo nga gisultihan ako sa Ginoo: Tan-awa; ug mitan-aw ko, ug nakita nako ang yuta sa Sharon, ug ang yuta sa Enoch, ug ang yuta sa Omer, ug ang yuta sa Heni, ug ang yuta sa Shem, ug ang yuta sa Haner, ug ang yuta sa Hanannihah, ug ang tanang lumulupyo niini;"},{"verse":10,"text":"Ug gisultihan ako sa Ginoo: Lakaw ngadto niini nga katawhan, ug isulti ngadto kanila—Paghinulsol, basin pa unya og mopakita ko ug mohampak kanila sa usa ka tunglo, ug mamatay sila."},{"verse":11,"text":"Ug gihatagan ko niya og sugo nga ako kinahanglang mobunyag pinaagi sa ngalan sa Amahan, ug sa Anak, nga puno sa grasya ug kamatuoran, ug sa Espiritu Santo, nga nagpamatuod sa Amahan ug sa Anak."},{"verse":12,"text":"Ug nahitabo nga mipadayon si Enoch sa pagtawag sa tanang katawhan, gawas lang sa katawhan sa Canaan, sa paghinulsol;"},{"verse":13,"text":"Ug dako kaayo ang pagtuo ni Enoch nga nangulo siya sa katawhan sa Dios, ug miabot ang ilang mga kaaway aron sa pakiggubat batok kanila; ug gipamulong niya ang pulong sa Ginoo, ug ang yuta mikurog, ug ang kabukiran nahanaw, gani sumala sa iyang sugo; ug nabalhin ang agianan sa katubigan sa mga suba; ug nadungog ang ngulob sa mga liyon gikan sa kamingawan; ug nahadlok sa hilabihan ang tanang nasod, gamhanan kaayo ang pulong ni Enoch, ug hilabihan ka dako ang gahom sa pinulongan nga gihatag sa Dios kaniya."},{"verse":14,"text":"Usab dihay mitunga nga yuta gikan sa kahiladman sa dagat, ug hilabihan gayod ang kahadlok sa mga kaaway sa katawhan sa Dios, nga sila milayas ug mipahilayo ug miadto sa yuta nga migula gikan sa kahiladman sa dagat."},{"verse":15,"text":"Ug ang mga higante sa yuta, usab, mitindog didto sa layo; ug dihay miabot nga usa ka tunglo sa tanang katawhan nga nakig-away batok sa Dios;"},{"verse":16,"text":"Ug gikan nianang panahona dihay mga gubat ug pagbanaw sa dugo taliwala kanila; apan miabot ang Ginoo ug mipuyo uban sa iyang katawhan, ug sila nagpuyo diha sa pagkamatarong."},{"verse":17,"text":"Ang kahadlok ngadto sa Ginoo anaa sa tanang nasod, dako kaayo ang himaya sa Ginoo, nga anaa sa iyang katawhan. Ug gipanalanginan sa Ginoo ang yuta, ug napanalanginan sila diha sa kabukiran, ug diha sa taas nga mga dapit, ug miuswag."},{"verse":18,"text":"Ug gitawag sa Ginoo ang iyang katawhan og Zion, tungod kay nagkahiusa sila sa kasingkasing ug sa hunahuna, ug nagpuyo sa pagkamatarong; ug walay kabos taliwala kanila."},{"verse":19,"text":"Ug nagpadayon si Enoch sa iyang pagsangyaw sa pagkamatarong ngadto sa katawhan sa Dios. Ug nahitabo sa iyang mga adlaw, nga gitukod niya ang usa ka siyudad nga gitawag og siyudad sa Pagkabalaan, gani ang Zion."},{"verse":20,"text":"Ug nahitabo nga nakigsulti si Enoch sa Ginoo; ug gisultihan niya ang Ginoo: Sa pagkamatuod ang Zion magpuyo sa kalinaw hangtod sa hangtod. Apan gisultihan sa Ginoo si Enoch: Ang Zion gipanalanginan nako, apan ang nahibilin sa katawhan akong gitunglo."},{"verse":21,"text":"Ug nahitabo nga gipakita sa Ginoo ngadto ni Enoch ang tanang lumulupyo sa yuta; ug nakita niya, ug tan-awa, ang Zion, sa paglabay sa panahon, gidala ngadto sa langit. Ug gisultihan sa Ginoo si Enoch: Tan-awa ang akong pinuy-anan sa kahangtoran."},{"verse":22,"text":"Ug nakita usab ni Enoch ang nahibilin sa katawhan nga mao ang mga anak ni Adan; ug sila mao ang mga nagkasagol-sagol sa tanang binhi ni Adan gawas sa binhi ni Cain, kay ang binhi ni Cain mga itom, ug walay dapit taliwala kanila."},{"verse":23,"text":"Ug human nga ang Zion gidala ngadto sa langit, nakita ni Enoch, ug tan-awa, ang tanang kanasoran sa yuta diha sa iyang atubangan;"},{"verse":24,"text":"Ug dihay miabot nga henerasyon human sa laing henerasyon; ug gihimaya ug gibayaw si Enoch, gani ngadto sa sabakan sa Amahan, ug sa Anak sa Tawo; ug tan-awa, ang gahom ni Satanas anaa sa ibabaw sa tibuok yuta."},{"verse":25,"text":"Ug nakakita siya og mga anghel nga mikunsad gikan sa langit; ug nakadungog siya og makusog nga tingog nga nag-ingon: Alaot, alaot ang mga lumulupyo sa yuta."},{"verse":26,"text":"Ug nakita niya ni Satanas; ug siya adunay dagko nga kadena sa iyang kamot, ug mitabon kini sa ibabaw sa tibuok yuta uban sa kangitngit; ug mitan-aw siya sa ibabaw ug mikatawa, ug ang iyang mga anghel nagmaya."},{"verse":27,"text":"Ug nakita ni Enoch ang mga anghel nga mikunsad gikan sa langit, nga nagpamatuod sa Amahan ug sa Anak; ug misulod ang Espiritu Santo sa daghang tawo, ug gidala sila sa mga gahom sa langit ngadto sa Zion."},{"verse":28,"text":"Ug nahitabo nga ang Dios sa langit mitan-aw sa nahibilin sa katawhan, ug mibakho; ug mipamatuod si Enoch niini, nga nag-ingon: Ngano nga ang mga langit nagbakho, ug nagpaagas sa mga luha niini sama sa ulan diha sa mga bukid?"},{"verse":29,"text":"Ug si Enoch miingon sa Ginoo: Nganong nagbakho ka, nga ikaw balaan man, ug gikan sa tanang kahangtoran ngadto sa tanang kahangtoran?"},{"verse":30,"text":"Ug kon posible pa lang nga ang tawo makaihap sa mga butang sa yuta, oo, sa minilyon nga mga yuta nga sama niini, kini dili usa ka sinugdanan sa gidaghanon sa imong mga nilalang; ug ang imong mga tabil gibukhad sa gihapon; ug gani ikaw anaa gihapon diha, ug ang imong sabakan anaa diha; ug usab ikaw makiangayon; ikaw maluluy-on ug mabination sa kahangtoran;"},{"verse":31,"text":"Ug gidawat nimo ang Zion nganha sa imong kaugalingong sabakan, gikan sa imong tanang nilalang, gikan sa tanang kahangtoran ngadto sa tanang kahangtoran; ug walay lain apan ang kalinaw, hustisya, ug kamatuoran mao ang pinuy-anan sa imong trono; ug ang kaluoy anaa sa imong atubangan ug walay kataposan; nganong nagbakho man ikaw?"},{"verse":32,"text":"Gisultihan sa Ginoo si Enoch: Tan-awa kining imong kaigsoonan; sila ang mga binuhat sa akong kaugalingong mga kamot, ug gihatagan ko sila sa ilang kahibalo, sa adlaw nga gilalang ko sila; ug didto sa Tanaman sa Eden, gihatag nako sa tawo ang iyang kabubut-on;"},{"verse":33,"text":"Ug gisultihan nako ang imong kaigsoonan, ug mihatag usab sa sugo, nga maghigugmaay sila sa usag usa, ug nga kinahanglan nga mopili sila kanako, nga ilang Amahan; apan tan-awa, sila walay mga balatian ug nasilag sila sa kaugalingong kaliwatan;"},{"verse":34,"text":"Ug ang dilaab sa akong kaligutgot napukaw batok kanila; ug sa kainit sa akong kahiubos ipadala nako ang mga lunop diha kanila, kay ang akong mabangis nga kasuko napukaw batok kanila."},{"verse":35,"text":"Tan-awa, ako ang Dios; Tawo nga Balaan mao ang akong ngalan; Tawo sa Tambag mao ang akong ngalan; ug Walay Kataposan ug Mahangtoron mao usab ang akong ngalan."},{"verse":36,"text":"Mao nga, makapataas ko sa akong mga kamot ug makagunit sa tanang gilalang nga akong binuhat; ug ang akong mata makatulisok usab kanila, ug taliwala sa tanang binuhat sa akong mga kamot walay sama nga hilabihan ang pagkadaotan sama sa imong kaigsoonan."},{"verse":37,"text":"Apan tan-awa, ang ilang mga sala maanaa sa mga ulo sa ilang mga amahan; si Satanas mahimo nga ilang amahan, ug ang pagkauyamot mao ang ilang kapalaran; ug ang tibuok langit mobakho tungod kanila, gani ang tanang binuhat sa akong mga kamot; mao nga dili ba mobakho ang mga langit, nga nagtan-aw niini nga mag-antos?"},{"verse":38,"text":"Apan tan-awa, kini nga nakita sa imong mga mata mangamatay sa mga lunop; ug tan-awa, ako mosumpo kanila; nag-andam ko og bilanggoan alang kanila."},{"verse":39,"text":"Ug kana nga akong pinili nagahangyo sa akong atubangan. Mao nga, nag-antos siya tungod sa ilang mga sala; kon maghinulsol sila sa adlaw nga mobalik ang akong Pinili ngari kanako, ug hangtod nianang adlawa mag-antos sila;"},{"verse":40,"text":"Mao nga, tungod niini ang langit magbakho, oo, ug ang tanang binuhat sa akong mga kamot."},{"verse":41,"text":"Ug nahitabo nga gisultihan sa Ginoo si Enoch, ug gisulti ngadto ni Enoch ang tanang binuhatan sa katawhan; mao nga nasayod si Enoch, ug mitan-aw sa ilang pagkadaotan, ug sa ilang kasub-anan, ug mibakho ug mipatuy-od sa iyang mga bukton; ug ang iyang kasingkasing milugway ngadto sa kahangtoran; ug ang iyang kahiladman nangandoy; ug miuyog ang tanang kahangtoran."},{"verse":42,"text":"Ug nakita usab ni Enoch si Noe, ug ang iyang pamilya; nga ang kaliwatan sa tanang anak ni Noe kinahanglan maluwas sa usa ka temporal nga kaluwasan;"},{"verse":43,"text":"Mao nga nakita ni Enoch nga si Noe nagbuhat og arka; ug mipahiyom ang Ginoo niini, ug mikupot niini sa iyang kaugalingon nga kamot; apan ngadto sa nahibilin nga mga daotan ang lunop miabot ug milamoy kanila."},{"verse":44,"text":"Ug samtang nakita kini ni Enoch, mibati siya og kasakit sa kalag, ug nagbakho tungod sa iyang kaigsoonan, ug gisultihan ang kalangitan: Magdumili ko nga mahupay; apan gisultihan sa Ginoo si Enoch: Pagmaya sa imong kasingkasing, ug pagmalipayon; ug tan-awa."},{"verse":45,"text":"Ug nahitabo nga mitan-aw si Enoch; ug gikan ni Noe, nakita niya ang tanang pamilya sa yuta; ug mituaw siya ngadto sa Ginoo, nga nag-ingon: Kanus-a moabot ang adlaw sa Ginoo? Kanus-a moagas ang dugo sa Matarong, nga ang tanan nga nagbangotan mabalaan ug makaangkon og kinabuhing dayon?"},{"verse":46,"text":"Ug misulti ang Ginoo: Moabot kini sa tunga-tunga sa panahon, sa mga adlaw sa pagkadaotan ug pagpanimalos."},{"verse":47,"text":"Ug tan-awa, nakita ni Enoch ang adlaw sa pag-anhi sa Anak sa Tawo, bisan diha sa unod; ug nagmaya ang iyang kalag, nga nag-ingon: Ang Matarong gibayaw, ug ang Kordero gipatay gikan sa katukoran sa kalibotan; ug pinaagi sa pagtuo ako anaa sa sabakan sa Amahan, ug tan-awa, ang Zion nag-uban kanako."},{"verse":48,"text":"Ug nahitabo nga mitan-aw si Enoch sa yuta; ug nakadungog siya og tingog gikan sa mga kahiladman niini, nga nag-ingon: Alaot, alaot ako, ang inahan sa mga tawo, nag-antos ako, gikapoy ako, tungod sa pagkadaotan sa akong mga anak. Kanus-a ako makapahulay, ug malimpyohan gikan sa kahugaw nga migula gikan kanako? Kanus-a ako himoong balaan sa akong Tiglalang aron makapahulay na ako, ug ang pagkamatarong sulod sa usa ka panahon maanaa kanako?"},{"verse":49,"text":"Ug sa dihang nadungog ni Enoch nga nagbangotan ang yuta, mibakho siya, ug mituaw ngadto sa Ginoo, nag-ingon: O Ginoo, wala ka bay kaluoy sa yuta? Dili ba nimo panalanginan ang mga anak ni Noe?"},{"verse":50,"text":"Ug nahitabo nga mipadayon si Enoch sa iyang pagtuaw ngadto sa Ginoo, nga nag-ingon: Mohangyo ko kanimo, O Ginoo, sa ngalan sa imong Bugtong Anak, gani si Jesukristo, nga kaluy-an nimo si Noe ug ang iyang binhi, nga ang yuta dili na unta matabonan sa mga lunop."},{"verse":51,"text":"Ug wala makapugong ang Ginoo; ug nakigsaad siya ni Enoch, ug nanumpa ngadto kaniya sa usa ka panumpa, nga mopahunong sa mga lunop; aron siya motawag sa mga anak ni Noe;"},{"verse":52,"text":"Ug mipadala siya og usa ka dili mausab nga sugo, nga ang salin sa iyang binhi kinahanglan kanunay nga makita diha sa tanang nasod, samtang ang kalibotan magpabilin;"},{"verse":53,"text":"Ug misulti ang Ginoo: Bulahan siya nga pinaagi sa iyang binhi moabot ang Mesiyas; kay miingon siya—Ako mao ang Mesiyas, ang Hari sa Zion, ang Bato sa Langit, nga halapad sama sa kahangtoran; kinsa ang mosulod sa ganghaan ug mosaka pinaagi kanako dili gayod mahulog; mao nga, bulahan sila nga akong gipamulong, kay moabot sila uban sa mga awit sa walay kataposan nga kalipay."},{"verse":54,"text":"Ug nahitabo nga mituaw si Enoch ngadto sa Ginoo, nga nag-ingon: Sa panahon nga magpakatawo ang Anak sa Tawo, makapahulay na ba ang yuta? Nag-ampo ko kanimo, ipakita kanako kining mga butanga."},{"verse":55,"text":"Ug gisultihan sa Ginoo si Enoch: Tan-awa, ug mitan-aw siya ug nakita ang Anak sa Tawo nga gituboy sa krus, subay sa pamaagi sa mga tawo;"},{"verse":56,"text":"Ug nakadungog siya og makusog nga tingog; ug gisalipdan ang mga langit; ug nagbangotan ang tanang nilalang sa Dios; ug nag-agulo ang yuta; ug nangabuak ang mga bato; ug namangon ang mga santos, ug gikoronahan diha sa tuong kamot sa Anak sa Tawo, uban sa mga korona sa himaya;"},{"verse":57,"text":"Ug kutob sa gidaghanon sa mga espiritu nga didto sa bilanggoan nanggawas, ug namarog sa tuong kamot sa Dios; ug ang nahibilin gireserbar sa mga kadena sa kangitngit hangtod sa paghukom sa mahinungdanon nga adlaw."},{"verse":58,"text":"Ug mibakho ug mituaw pag-usab si Enoch ngadto sa Ginoo, nga nag-ingon: Kanus-a makapahulay ang yuta?"},{"verse":59,"text":"Ug nakita ni Enoch ang Anak sa Tawo nga mikayab sa itaas ngadto sa Amahan; ug gitawag niya ang Ginoo, nag-ingon: Dili ba ikaw mobalik pag-usab sa yuta? Tungod kay ikaw ang Dios, ug nakaila ko kanimo, ug nanumpa ka ngari kanako, ug misugo kanako nga kinahanglan mangayo pinaagi sa ngalan sa imong Bugtong Anak; ikaw mibuhat kanako, ug mihatag kanako og katungod sa imong trono, ug dili sa akong kaugalingon, apan pinaagi sa imong kaugalingon nga grasya; mao nga, mangutana ko kanimo kon ikaw dili ba mobalik pag-usab sa yuta."},{"verse":60,"text":"Ug gisultihan sa Ginoo si Enoch: Segurado ako, sa ingon niana ako mobalik sa kataposang mga adlaw, sa mga adlaw sa pagkadaotan ug sa pagpanimalos, aron sa pagtuman sa panumpa nga akong gihimo kanimo mahitungod sa mga anak ni Noe;"},{"verse":61,"text":"Ug moabot ang adlaw nga ang yuta mopahulay, apan sa dili pa moabot kana nga adlaw ang langit mongitngit, ug ang tabil sa kangitngit motabon sa yuta, ug mokurog ang mga langit, ug usab ang yuta; ug ang dagkong mga katalagman moabot taliwala sa katawhan, apan luwason nako ang akong katawhan;"},{"verse":62,"text":"Ug ang pagkamatarong ipakanaog nako gikan sa langit, ug ipadala nako ang kamatuoran gikan sa yuta, aron sa pagpamatuod sa akong Bugtong Anak; sa iyang pagkabanhaw gikan sa patay; oo, ug usab ang pagkabanhaw sa tanang tawo; ug ang pagkamatarong ug kamatuoran akong himoon nga mobanlas sa yuta sama sa usa ka lunop, aron sa pagpundok sa akong pinili gikan sa upat ka suok sa yuta, ngadto sa usa ka dapit nga akong giandam, ang usa ka Balaan nga siyudad, aron ang akong katawhan mobakos sa ilang mga bat-ang, ug magpaabot sa panahon sa akong pag-anhi; kay anaa diha ang akong tabernakulo, ug kini pagatawgon og Zion, usa ka Bag-ong Jerusalem."},{"verse":63,"text":"Ug gisultihan sa Ginoo si Enoch: Dayon ikaw ug ang imong tibuok nga siyudad makigkita kanila didto, ug sila atong pagadawaton ngari sa atong sabakan, ug makakita sila kanato; ug mogakos kita kanila, ug mogakos sila kanato, ug maghinagkanay kita;"},{"verse":64,"text":"Ug anaa diha ang akong pinuy-anan, ug kini mao ang Zion, diin mogula ang tanan nga nilalang nga akong gibuhat; ug sulod sa usa ka libo ka tuig ang yuta mopahulay."},{"verse":65,"text":"Ug nahitabo nga nakita ni Enoch ang adlaw sa pag-anhi sa Anak sa Tawo, sa kataposang mga adlaw, aron mopuyo sa yuta diha sa pagkamatarong sulod sa usa ka libo ka tuig;"},{"verse":66,"text":"Apan sa dili pa mahitabo kana nga adlaw nakita niya ang dagkong mga kalisdanan taliwala sa mga daotan; ug nakita usab niya ang dagat, nga nagkaguliyang, ug ang mga kasingkasing sa mga tawo mihunong sa pagpitik, nagpaabot uban sa kahadlok sa mga paghukom sa Labawng Makagagahom nga Dios, nga moabot sa mga daotan."},{"verse":67,"text":"Ug gipakita sa Ginoo kang Enoch ang tanang butang, gani ngadto sa kinatumyan sa kalibotan; ug nakita niya ang adlaw sa mga matarong, ang takna sa ilang katubsanan, ug nakadawat sa kahingpitan sa kalipay;"},{"verse":68,"text":"Ug ang tanang adlaw sa Zion, sa mga adlaw ni Enoch, mga tulo ka gatos ug kan-uman ug lima ka tuig."},{"verse":69,"text":"Ug si Enoch ug ang iyang tanang katawhan naglakaw uban sa Dios, ug nagpuyo siya taliwala sa Zion; ug nahitabo nga ang Zion nawala, kay ang Dios midawat niini ngadto sa iyang kaugalingong sabakan; ug gikan didto gisangyaw ang panultihon, nga ang Zion Nawala."}]},{"chapter":8,"verses":[{"verse":1,"text":"Ug ang tanang adlaw ni Enoch mga upat ka gatos ug katloan ka tuig."},{"verse":2,"text":"Ug nahitabo nga si Metusela, ang anak ni Enoch, wala kuhaa, aron matuman ang mga pakigsaad sa Ginoo, nga gihimo niya ngadto ni Enoch; kay mipakigsaad siya sa pagkatinuod ngadto ni Enoch nga si Noe mahimong bunga sa iyang mga bat-ang."},{"verse":3,"text":"Ug nahitabo nga si Metusela nanagna nga gikan sa iyang mga bat-ang motungha ang tanang gingharian sa yuta (pinaagi ni Noe), ug gihimaya niya ang iyang kaugalingon."},{"verse":4,"text":"Ug dihay miabot nga usa ka dakong gutom sa yuta, ug gitunglo sa Ginoo ang yuta sa usa ka mapait nga tunglo, ug daghan sa lumulupyo niini ang namatay."},{"verse":5,"text":"Ug nahitabo nga si Metusela nagpuyo sa yuta og usa ka gatos ug kawaloan ug pito ka tuig, ug nanganak ni Lamech;"},{"verse":6,"text":"Ug si Metusela nagpuyo sa yuta, human siya nanganak ni Lamech, mga pito ka gatos ug kawaloan ug duha ka tuig, ug nanganak og mga anak nga lalaki ug mga anak nga babaye;"},{"verse":7,"text":"Ug ang tanang adlaw ni Metusela mga siyam ka gatos ug kan-uman ug siyam ka tuig, ug namatay siya."},{"verse":8,"text":"Ug si Lamech nagpuyo sa yuta og usa ka gatos ug kawaloan ug duha ka tuig, ug nanganak og usa ka lalaki,"},{"verse":9,"text":"Ug gitawag niya ang iyang ngalan og Noe, nga nag-ingon: Kini nga anak nga lalaki mohupay kanato kalabot sa atong buhat ug sa pag-ugmad sa atong mga kamot, tungod kay ang yuta gitunglo sa Ginoo."},{"verse":10,"text":"Ug si Lamech nagpuyo sa yuta, human siya nanganak ni Noe, mga lima ka gatos ug kasiyaman ug lima katuig, ug nanganak og mga anak nga lalaki ug mga anak nga babaye;"},{"verse":11,"text":"Ug ang tanang adlaw ni Lamech mga pito ka gatos ug kapitoan ug pito ka tuig, ug namatay siya."},{"verse":12,"text":"Ug nagpanuigon si Noe og upat ka gatos ug kalim-an ka tuig, ug nanganak ni Japet; ug human sa kap-atan ug duha ka tuig nanganak siya ni Shem gikan kaniya nga mao ang inahan ni Japet, ug sa dihang nagpanuigon siya og lima ka gatos ka tuig nanganak siya ni Ham."},{"verse":13,"text":"Ug si Noe ug ang iyang mga anak mipatalinghog sa Ginoo, ug mituman, ug gitawag sila nga mga anak nga lalaki sa Dios."},{"verse":14,"text":"Ug sa dihang misugod kini nga mga tawo sa pagdaghan sa ibabaw sa yuta, ug ang mga anak nga babaye natawo ngadto kanila, ang mga anak nga lalaki sa mga tawo nakakita nga kadtong mga anak nga babaye mga matahom, ug sila gihimo nila nga mga asawa, gani sumala sa ilang pagpili."},{"verse":15,"text":"Ug gisultihan sa Ginoo si Noe: Ang mga anak nga babaye sa imong mga anak nga lalaki mibaligya sa ilang mga kaugalingon; kay tan-awa ang akong kasuko napukaw batok sa mga anak nga lalaki sa mga tawo, kay wala sila mopatalinghog sa akong tingog."},{"verse":16,"text":"Ug nahitabo nga nanagna si Noe, ug mitudlo sa mga butang sa Dios, sama sa sinugdanan."},{"verse":17,"text":"Ug ang Ginoo miingon ngadto ni Noe: Ang akong Espiritu dili kanunay moimpluwensya sa tawo, kay siya masayod nga ang tanang tawo mamatay; apan ang iyang mga adlaw mahimo nga usa ka gatosan ug kawhaan ka tuig; ug kon ang mga tawo dili maghinulsol, ipadala nako ang mga lunop diha kanila."},{"verse":18,"text":"Ug niadtong mga adlawa dihay mga higante sa yuta, ug nagtinguha sila sa pagpatay ni Noe; apan nagauban ang Ginoo kang Noe, ug ang gahom sa Ginoo diha kaniya."},{"verse":19,"text":"Ug giordinahan sa Ginoo si Noe subay sa iyang kaugalingong kapunongan, ug mimando kaniya sa paglakaw ug sa pagpahayag sa iyang Ebanghelyo ngadto sa katawhan, sumala sa gisugo ngadto ni Enoch."},{"verse":20,"text":"Ug nahitabo nga gitawag ni Noe ang katawhan nga kinahanglan nga maghinulsol sila; apan wala sila maminaw sa iyang mga pulong;"},{"verse":21,"text":"Ug usab, human sila makapaminaw kaniya, miduol sila kaniya, nga nag-ingon: Tan-awa, kami mga anak nga lalaki sa Dios; wala ba kami makigminyo sa mga anak nga babaye sa mga tawo? Ug wala ba kami mokaon ug mag-inom, ug magminyoay ug gipaminyo? Ug ang among mga asawa naghatag kanamo og mga anak, ug kini sila gamhanan nga mga tawo, nga sama sa mga tawo sa karaan, mga tawo nga bantogan. Ug wala sila maminaw sa mga pulong ni Noe."},{"verse":22,"text":"Ug nakita sa Dios nga ang pagkadaotan sa mga tawo misamot diha sa yuta; ug gibayaw ang matag tawo sa handurawan sa mga hunahuna sa iyang kasingkasing, nga sa kanunay daotan."},{"verse":23,"text":"Ug nahitabo nga mipadayon si Noe sa iyang pagsangyaw ngadto sa katawhan, nga nag-ingon: Paminaw, ug patalinghog sa akong mga pulong;"},{"verse":24,"text":"Motuo ug maghinulsol sa inyong mga sala ug magpabunyag pinaagi sa ngalan ni Jesukristo, ang Anak sa Dios, gani sama sa atong mga amahan, ug kamo makadawat sa Espiritu Santo, aron makaangkon kamo sa tanang butang nga gipakita; ug kon dili ninyo kini buhaton, moabot ang mga lunop diha kaninyo; bisan pa niana wala sila maminaw."},{"verse":25,"text":"Ug nakapabasol kini ni Noe, ug ang iyang kasingkasing nasakitan nga gibuhat sa Ginoo ang tawo diha sa yuta, ug nakapaguol kini sa iyang kasingkasing."},{"verse":26,"text":"Ug misulti ang Ginoo: Laglagon nako ang tawo nga akong gilalang, gikan sa ibabaw sa yuta, ang tawo ug mga mananap, ug ang nagkamang nga mga butang, ug ang mga langgam sa kahanginan; kay kini nakapasubo ni Noe nga gilalang nako sila, ug nga gibuhat nako sila; ug mitawag siya kanako; kay nagtinguha sila sa iyang kinabuhi."},{"verse":27,"text":"Ug sa ingon niana naangkon ni Noe ang pagsalig sa mga mata sa Ginoo; kay si Noe usa ka matarong nga tawo, ug hingpit diha sa iyang kaliwatan; ug naglakaw siya kauban sa Dios, ingon man usab ang iyang tulo ka anak nga lalaki, si Shem, Ham, ug si Japet."},{"verse":28,"text":"Daotan ang yuta sa atubangan sa Dios, ug kini napuno sa kasamok."},{"verse":29,"text":"Ug mitan-aw ang Dios sa yuta, ug, tan-awa, daotan kini, kay ang tanang tawo naghugaw-hugaw sa ilang agianan diha sa yuta."},{"verse":30,"text":"Ug gisultihan sa Dios si Noe: Ang kataposan sa tanang tawo miabot sa akong atubangan, kay napuno sa kasamok ang yuta, ug tan-awa laglagon nako ang tanang tawo gikan sa yuta."}]}]},{"id":"abraham","title":"Abraham","englishTitle":"Abraham","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Didto sa yuta sa mga taga-Caldea, sa pinuy-anan sa akong mga amahan, ako, si Abraham, nakaamgo nga kinahanglan makaangkon ko og laing dapit nga kapuy-an;"},{"verse":2,"text":"Ug, kay nahibaloan nako nga adunay labaw pa nga kalipay ug kalinaw ug kapahulayan alang kanako, gitinguha nako ang mga panalangin sa mga amahan, ug ang katungod diin gikinahanglan ko nga maordinahan aron makapangalagad niini; kay ako sa akong kaugalingon usa ka sumusunod sa pagkamatarong, nagtinguha usab nga makaangkon og dakong kahibalo, ug mahimong mas labaw nga sumusunod sa pagkamatarong, ug makaangkon og mas dakong kahibalo, ug mahimong amahan sa daghang nasod, usa ka prinsipe sa kalinaw, ug nagtinguha nga makadawat og mga panudlo, ug mosunod sa mga sugo sa Dios, nahimo kong tinuod nga sumusunod, usa ka High Priest, nga naghupot sa katungod nga gihuptan sa mga amahan."},{"verse":3,"text":"Gitugyan kini ngari kanako gikan sa mga amahan; miabot kini gikan sa mga amahan, gikan pa sa sinugdanan sa panahon, oo, gani sukad pa sa sinugdanan, o sa wala pa matukod ang yuta, hangtod niini nga panahon, gani ang katungod sa unang natawo, o ang unang tawo, nga si Adan, o unang amahan, pinaagi sa mga amahan ngari kanako."},{"verse":4,"text":"Gipaningkamotan nako nga mapili ngadto sa Pagkapari sumala sa paagi sa pagpili sa Dios sa mga amahan mahitungod sa kaliwatan."},{"verse":5,"text":"Ang akong mga amahan, kay mibiya sa ilang pagkamatarong, ug gikan sa balaan nga mga sugo nga gihatag sa Ginoo nga ilang Dios ngadto kanila, hangtod nga nagsimba sa mga dios sa mga pagano, sa hingpit midumili sa pagpaminaw sa akong tingog;"},{"verse":6,"text":"Kay ang ilang kasingkasing gitumong ngadto sa pagbuhat og daotan, ug hingpit nga midangop ngadto sa dios ni Elkenah, ug sa dios ni Libnah, ug sa dios ni Mahmackrah, ug sa dios ni Korash, ug sa dios ni Paraon, hari sa Ehipto;"},{"verse":7,"text":"Busa gidirekta nila ang ilang kasingkasing ngadto sa gihimo sa mga pagano nga sakripisyo sa paghalad sa ilang mga anak ngadto niining amang nga mga dios-dios, ug wala maminaw sa akong tingog, apan nagtinghuha sa paghunos sa akong kinabuhi pinaagi sa kamot sa pari ni Elkenah. Ang pari ni Elkenah mao usab ang pari ni Paraon."},{"verse":8,"text":"Karon, niining higayona nabatasan sa pari ni Paraon, ang hari sa Ehipto, ang paghalad og mga lalaki, mga babaye, ug mga bata ibabaw sa altar nga gitukod didto sa yuta sa Caldea, aron ihalad ngadto niining mga dios nga langyaw."},{"verse":9,"text":"Ug nahitabo nga ang pari mihimo og usa ka halad ngadto sa dios ni Paraon, ug usab ngadto sa dios ni Shagreel, gani sumala sa paagi sa mga Ehiptohanon. Karon ang dios ni Shagreel mao ang adlaw."},{"verse":10,"text":"Gani ang halad-pasalamat sa usa ka bata gihalad sa pari ni Paraon ibabaw sa altar nga nagbarog sa bungtod nga gitawag og Bungtod ni Potiphar, sa ulohan sa kapatagan sa Olishem."},{"verse":11,"text":"Karon, kini nga pari mihalad og tulo ka birhen sa ibabaw niini nga altar sa usa ka higayon, nga mao ang mga anak nga babaye ni Onitah, usa sa halangdon nga kaliwat gikan sa mga bat-ang ni Ham. Kini nga mga birhen gihalad tungod sa ilang mga hiyas; dili sila moyukbo aron sa pagsimba sa mga dios nga kahoy o bato, busa gipatay sila sa ibabaw niini nga altar, ug gibuhat kini sumala sa paagi sa mga Ehiptohanon."},{"verse":12,"text":"Ug nahitabo nga ang mga pari madagmalong midakop nako, aron ila usab akong patyon, sama sa gibuhat nila niadtong mga birhen sa ibabaw niini nga altar; ug aron may kahibalo kamo mahitungod niini nga altar, tan-awa ninyo ang hulagway nga anaa sa sinugdanan niini nga talaan."},{"verse":13,"text":"Gihimo kadto susama sa porma sa higdaanan, sama sa naandan sa mga taga-Caldea, ug nagbarog kadto sa atubangan sa mga dios ni Elkenah, Libnah, Mahmackrah, Korash, ug usab sa usa ka dios nga sama ni Paraon, ang hari sa Ehipto."},{"verse":14,"text":"Aron makasabot kamo mahitungod niini nga mga dios, gipakita ko kaninyo ang mga hitsura niini diha sa mga hulagway sa sinugdanan, kini nga paagi sa paghulagway mao ang gitawag sa mga taga-Caldea nga Rahleenos, nga nagtimailhan sa mga hiroglepiko."},{"verse":15,"text":"Ug sa dihang gibakyaw nila ang ilang mga kamot ngari kanako, aron unta ako ilang ihalad ug hunosan sa akong kinabuhi, tan-awa, akong gipataas ang akong tingog ngadto sa Ginoo nga akong Dios, ug ang Ginoo mipatalinghog ug naminaw, ug gipuno ko niya sa panan-awon sa Makagagahom, ug ang anghel sa iyang atubangan mibarog sa akong kiliran, ug diha-diha mibadbad sa akong mga gapos;"},{"verse":16,"text":"Ug ang iyang tingog misulti ngari kanako: Abraham, Abraham, tan-awa, ang akong ngalan mao si Jehova, ug nakadungog ko kanimo, ug nanaog aron sa pagluwas kanimo, ug aron ipahilayo ka gikan sa balay sa imong amahan, ug gikan sa imong tanan nga kabanay, ngadto sa laing yuta nga wala nimo mahibaloi;"},{"verse":17,"text":"Ug tungod kini kay gipahilayo nila ang ilang kasingkasing gikan kanako, aron mosimba sa dios ni Elkenah, ug sa dios ni Libnah, ug sa dios ni Mahmackrah, ug sa dios ni Korash, ug sa dios ni Paraon, hari sa Ehipto; busa mikanaog ko aron moduaw kanila, ug molaglag kaniya nga mibakyaw sa iyang kamot batok kanimo, Abraham, akong anak, aron sa paghunos sa imong kinabuhi."},{"verse":18,"text":"Tan-awa, giyahan ko ikaw sa akong kamot, ug dad-on ko ikaw, ug ibutang diha kanimo ang akong ngalan, bisan ang Pagkapari sa imong amahan, ug ang akong gahom magpaibabaw kanimo."},{"verse":19,"text":"Ang nahitabo ni Noe mahitabo usab kanimo; apan pinaagi sa imong pagpangalagad ang akong ngalan mailhan dinhi sa yuta hangtod sa kahangtoran, kay ako ang imong Dios."},{"verse":20,"text":"Tan-awa, ang Bungtod ni Potiphar anaa sa yuta sa Ur, sa Caldea. Ug giguba sa Ginoo ang altar ni Elkenah, ug sa mga dios sa yuta, ug gilaglag kini sa hingpit, ug gihampak ang pari mao nga namatay siya; ug dihay dako nga pagbangotan sa Caldea, ug usab sa ginsakopan sa Paraon; ang maong Paraon nga gipasabot nga hari pinaagi sa harianon nga kaliwat."},{"verse":21,"text":"Karon kini nga hari sa Ehipto nagagikan sa mga kaliwatan ni Ham, ug kadugo sa Mga Taga-Canaan sumala sa iyang kagikanan."},{"verse":22,"text":"Gikan niini nga kaliwat nagagikan ang tanang Ehiptohanon, ug sa ingon ang dugo sa mga taga-Canaan gipatunhay sa yuta."},{"verse":23,"text":"Ang yuta sa Ehipto ingon nga unang nakaplagan sa usa ka babaye, kinsa anak nga babaye ni Ham, ug anak nga babaye ni Ehiptus, nga sa taga-Caldea nagpasabot og Ehipto, nga nagpasabot sa butang nga gidili;"},{"verse":24,"text":"Sa dihang nakaplagan niining babaye ang maong yuta diha kini sa ilawom sa tubig, kinsa sa pagkahuman mipahiluna sa iyang mga anak nga lalaki diha niini; ug sa ingon, gikan ni Ham, mitungha kana nga kaliwat nga mipatunhay sa tunglo sa maong yuta."},{"verse":25,"text":"Karon ang unang panggamhanan sa Ehipto gitukod ni Paraon, ang kamagulangang anak nga lalaki ni Ehiptus, ang anak nga babaye ni Ham, ug pinasubay kini sa pamaagi sa panggamhanan ni Ham, sa patriyarkal nga pamaagi."},{"verse":26,"text":"Si Paraon, kay matarong nga tawo, nagtukod sa iyang gingharian ug naghukom sa iyang katawhan sa maalamon ug makiangayong paagi sa iyang tanang adlaw, matinguhaong naningkamot sa pagsunod nianang kapunongan nga gitukod sa mga amahan sa unang kaliwatan, sa mga adlaw sa unang patriyarkal nga pagmando, gani sa pagmando ni Adan, ug usab ni Noe, ang iyang amahan, kinsa mipanalangin kaniya sa mga panalangin sa yuta, ug sa mga panalangin sa kaalam, apan mitunglo kaniya kalabot sa Pagkapari."},{"verse":27,"text":"Karon, si Paraon kay gikan sa maong kaliwat diin siya dili makaangkon sa katungod sa Pagkapari, bisan pa ang mga Paraon malipayon nga makaangkon niini gikan ni Noe, pinaagi ni Ham, busa ang akong amahan nadani sa ilang pagsimba sa mga dios-dios;"},{"verse":28,"text":"Apan maningkamot ko, unya, sa paghulagway sa kronolohiya gikan sa akong kaugalingon balik ngadto sa sinugdanan sa paglalang, kay ang mga talaan miabot sa akong mga kamot, nga akong gihuptan hangtod niini nga panahon."},{"verse":29,"text":"Karon, human gihampak ang pari ni Elkenah nga siya namatay, dihay miabot nga katumanan niadtong mga butang nga giingon ngari kanako mahitungod sa yuta sa Caldea, nga adunay kagutom sa yuta."},{"verse":30,"text":"Ug tuod man may mikuyanap nga kagutom sa tibuok yuta sa Caldea, ug ang akong amahan nag-antos pag-ayo tungod sa kagutom, ug naghinulsol siya sa daotan nga iyang gitinguha batok kanako, sa paghunos sa akong kinabuhi."},{"verse":31,"text":"Apan ang mga talaan sa mga amahan, gani sa mga patriyarka, kalabot sa katungod sa Pagkapari, gipatunhay sa Ginoo nga akong Dios dinhi sa akong kaugalingong mga kamot; busa ang kahibalo sa sinugdanan sa paglalang, ug usab sa mga planeta, ug sa mga bituon, ingon nga kini gipahibalo ngadto sa mga amahan, akong gitipigan gani hangtod karong adlawa, ug maningkamot ko sa pagsulat sa uban niini nga mga butang dinhi niini nga talaan, alang sa kaayohan sa akong kaliwatan nga mosunod kanako."}]},{"chapter":2,"verses":[{"verse":1,"text":"Karon gipalabihan sa Ginoong Dios ang kagutom didto sa yuta sa Ur, hangtod nga si Haran, ang akong igsoong lalaki, namatay; apan si Terah, ang akong amahan, buhi pa didto sa yuta sa Ur, sa mga taga-Caldea."},{"verse":2,"text":"Ug nahitabo nga ako, si Abraham, nangasawa ni Sarai, ug si Nahor, akong igsoong lalaki, nangasawa ni Milcah, nga anak nga babaye ni Haran."},{"verse":3,"text":"Karon nagsulti kanako ang Ginoo nga: Abraham, palayo sa imong nasod, ug gikan sa imong banay, ug gikan sa balay sa imong amahan, ngadto sa usa ka yuta nga ipakita ko kanimo."},{"verse":4,"text":"Busa akong gibiyaan ang yuta sa Ur, sa mga taga-Caldea, aron moadto sa yuta sa Canaan; ug akong gidala si Lot, anak nga lalaki sa akong igsoong lalaki, ug ang iyang asawa, ug si Sarai, ang akong asawa; ug usab ang akong amahan misunod kanako, ngadto sa yuta nga among ginganlan og Haran."},{"verse":5,"text":"Ug ang kagutom mikunhod; ug ang akong amahan nagpabilin sa Haran ug mipuyo didto, tungod kay adunay daghan nga kahayopan sa Haran; ug ang akong amahan mibalik pag-usab sa pagsimba sa mga dios-dios, busa nagpabilin siya sa Haran."},{"verse":6,"text":"Apan ako, si Abraham, ug si Lot, anak nga lalaki sa akong igsoon nga lalaki, nag-ampo sa Ginoo, ug ang Ginoo mipakita ngari kanako, ug miingon kanako: Tindog, ug dad-a si Lot uban kanimo; kay ako adunay katuyoan sa pagpahilayo kanimo gikan sa Haran, ug sa paghimo kanimo nga tigpangalagad aron mopamatuod sa akong ngalan didto sa lain nga yuta nga akong ihatag sa imong binhi nga mosunod kanimo alang sa walay kataposan nga bahandi, sa panahon nga sila maminaw sa akong tingog."},{"verse":7,"text":"Kay ako ang Ginoo nga imong Dios; nagpuyo ako sa langit; ang yuta mao ang akong tumbanan; akong ituyhad ang akong kamot sa ibabaw sa dagat, ug mosunod kini sa akong tingog; akong himoon ang hangin ug ang kalayo nga akong karwahe; akong sultihan ang mga bukid—Pahawa diha—ug tan-awa, madala kini sa alimpulos, diha-diha dayon, sa kalit."},{"verse":8,"text":"Ang akong ngalan mao si Jehova, ug nahibalo ako sa kataposan gikan sa sinugdanan; busa ang akong kamot magpaibabaw kanimo."},{"verse":9,"text":"Ug buhaton ko ikaw nga dakong nasod, ug panalanginan ko ikaw sa walay sukod, ug himoong bantogan ang imong ngalan sa tanang nasod, ug mahimo kang panalangin ngadto sa imong binhi nga mosunod kanimo, nga sa ilang mga kamot sila modala niini nga pagpangalagad ug Pagkapari ngadto sa tanang nasod;"},{"verse":10,"text":"Ug panalanginan ko sila pinaagi sa imong ngalan; kay kutob sa modawat niini nga Ebanghelyo pagatawgon sa imong ngalan, ug pagaiphon nga imong binhi, ug mobarog ug mopanalangin kanimo, isip ilang amahan;"},{"verse":11,"text":"Ug panalanginan ko sila nga mopanalangin kanimo, ug tunglohon sila nga motunglo kanimo; ug diha kanimo (nga buot ipasabot, diha sa imong Pagkapari), ug sa imong binhi (nga buot ipasabot, ang imong Pagkapari), kay hatagan ko ikaw og saad nga kini nga katungod magpadayon diha kanimo, ug sa imong binhi nga mosunod kanimo (nga ang gipasabot, ang tinuod nga binhi, o binhi sa lawas) ang tanang pamilya sa yuta mapanalanginan, gani pinaagi sa mga panalangin sa Ebanghelyo, nga mao ang mga panalangin sa kaluwasan, gani sa kinabuhing dayon."},{"verse":12,"text":"Karon, human ang Ginoo mihunong sa pagpakigsulti kanako, ug mipalayo sa iyang nawong gikan kanako, miingon ako sa akong kasingkasing: Ang imong sulugoon nangita kanimo sa dakong tinguha; karon nakakaplag na ako kanimo;"},{"verse":13,"text":"Imong gipadala ang imong anghel aron moluwas kanako gikan sa mga dios ni Elkenah, ug labing maayo nga mopatalinghog ako sa imong tingog, busa tugoti ang imong sulugoon nga mobarog ug mobiya nga malinawon."},{"verse":14,"text":"Mao nga ako, si Abraham, mibiya sama sa gisulti sa Ginoo ngari kanako, ug si Lot mikuyog kanako; ug ako, si Abraham, nag-edad og kan-oman ug duha ka tuig sa dihang mibiya ko sa Haran."},{"verse":15,"text":"Ug akong gidala si Sarai, kinsa akong gipangasawa sa didto pa ako sa Ur, sa Caldea, ug si Lot, anak nga lalaki sa akong igsoon nga lalaki, ug ang among tanang katigayonan nga among napundok, ug ang mga kalag nga among nakabig didto sa Haran, ug miadto sa agianan paingon sa yuta sa Canaan, ug nagpuyo sa mga tolda samtang nagpadayon kami sa among panaw;"},{"verse":16,"text":"Busa, ang kahangtoran mao ang among panalipod ug ang among bato ug ang among kaluwasan, samtang mipanaw kami gikan sa Haran latas sa Jershon, aron moadto sa yuta sa Canaan."},{"verse":17,"text":"Karon ako, si Abraham, naghimo og altar didto sa yuta sa Jershon, ug mihimo og paghalad ngadto sa Ginoo, ug nag-ampo nga ang kagutom mobiya gikan sa balay sa akong amahan, aron dili sila mamatay."},{"verse":18,"text":"Ug unya miagi kami gikan sa Jershon latas sa yuta ngadto sa dapit nga gitawag og Sechem; nahimutang kini sa kapatagan sa Moreh, ug miabot na kami sa mga utlanan sa yuta sa mga taga-Canaan, ug mihalad ko og sakripisyo didto sa kapatagan sa Moreh, ug mitawag sa Ginoo nga mainampoon, tungod kay miabot na kami sa yuta niini nga nasod nga nagsimba og dios-dios."},{"verse":19,"text":"Ug ang Ginoo mipakita ngari kanako agi og tubag sa akong mga pag-ampo, ug miingon ngari kanako: Nganha sa imong binhi ihatag ko kini nga yuta."},{"verse":20,"text":"Ug ako, si Abraham mibarog gikan sa dapit sa altar nga akong gitukod alang sa Ginoo, ug mipalayo gikan didto ngadto sa usa ka bukid sa silangan sa Bethel, ug mipabarog sa akong tolda didto, sa Bethel sa kasadpan, ug Hai sa silangan; ug didto nagtukod ko og lain nga altar alang sa Ginoo, ug mitawag pag-usab sa ngalan sa Ginoo."},{"verse":21,"text":"Ug ako, si Abraham, mipanaw, paingon gihapon sa habagatan; ug nagpadayon ang kagutom sa maong yuta; ug ako, si Abraham, nakahukom sa pag-adto sa Ehipto, aron mopuyo didto, kay ang kagutom nahimong kuyaw na kaayo."},{"verse":22,"text":"Ug nahitabo nga sa dihang nagkaduol na ako sa Ehipto, ang Ginoo miingon ngari kanako: Tan-awa, si Sarai, ang imong asawa, usa ka matahom kaayong babaye nga tan-awon;"},{"verse":23,"text":"Busa mahitabo, kon ang mga Ehiptohanon makakita kaniya, moingon sila—Siya iyang asawa; ug ikaw ilang patyon, apan siya ilang buhion; busa seguroha nga buhaton nimo kini sa ingon niini nga paagi:"},{"verse":24,"text":"Pasultiha siya ngadto sa mga Ehiptohanon, nga siya imong igsoong babaye, ug ang imong kalag mabuhi."},{"verse":25,"text":"Ug nahitabo nga ako, si Abraham, misulti kang Sarai, nga akong asawa, sa tanang giingon sa Ginoo ngari kanako—Busa sultihi sila, mohangyo ko kanimo, nga ikaw akong igsoong babaye, aron mamaayo ra ang tanan alang kanako alang sa imong kaayohan, ug ang akong kalag mabuhi tungod kanimo."}]},{"chapter":3,"verses":[{"verse":1,"text":"Ug ako, si Abraham, adunay Urim ug Thummim, nga gihatag sa Ginoo nga akong Dios ngari kanako, didto sa Ur sa Caldea;"},{"verse":2,"text":"Ug akong nakita ang mga bituon, nga kini labihan ka hayag, ug nga ang usa niini mao ang labing duol ngadto sa trono sa Dios; ug dihay daghan pa nga labihan ka hayag nga duol niini;"},{"verse":3,"text":"Ug ang Ginoo miingon ngari kanako: Kini mao ang mga tigmando; ug ang ngalan sa usa nga labing hayag mao ang Kolob, tungod kay duol kini kanako, kay ako mao ang Ginoo nga imong Dios: gitakda ko kini nga maoy momando sa tanang nahisakop sa sama nga han-ay sa imong gibarogan."},{"verse":4,"text":"Ug ang Ginoo misulti ngari kanako, pinaagi sa Urim ug Thummim, nga ang Kolob nagsubay sa pamaagi sa Ginoo, sumala sa iyang mga panahon ug mga higayon sa mga paglibot niini; nga ang usa ka paglibot usa ka adlaw sa Ginoo, sumala sa iyang mga paagi sa pag-ihap, usa ka libo kini ka tuig sumala sa panahon nga gitakda nianang imong gibarogan. Mao kini ang pag-ihap sa panahon sa Ginoo, sumala sa pag-ihap sa Kolob."},{"verse":5,"text":"Ug ang Ginoo misulti ngari kanako: Ang planeta nga mas gamay ang kahayag, mas gamay kay sa nianang momando panahon sa adlaw, bisan gani sa panahon sa gabii, mas taas o mas labaw kay sa nianang imong gibarogan sa punto sa pag-ihap, kay naglihok kini sa pamaagi nga labaw ka hinay; ingon niini ang pagkahan-ay kay nagtindog kini ibabaw sa yuta nga imong gibarogan, busa ang pag-ihap sa panahon niini dili kaayo daghan kay sa gidaghanon sa mga adlaw niini, ug sa mga bulan, ug sa mga tuig."},{"verse":6,"text":"Ug ang Ginoo misulti ngari kanako: Karon, Abraham, kining duha ka kamatuoran anaa, tan-awa ang imong mga mata nakakita niini; gihatagan ikaw og kahibalo aron masayod sa panahon sa sistema sa pagsubay sa panahon, ug ang gikatakda nga panahon, oo, ang gikatakda nga panahon sa yuta diin ikaw nagbarog, ug ang gikatakda nga panahon sa mas labaw nga kahayag nga gikatakda nga momando panahon sa adlaw, ug ang gikatakda nga panahon sa mas gamay nga kahayag nga gikatakda nga momando sa gabii."},{"verse":7,"text":"Karon ang gikatakda nga panahon sa mas gamay nga kahayag mas taas og panahon sumala sa pag-ihap niini kay sa pag-ihap sa panahon sa yuta nga imong gibarogan."},{"verse":8,"text":"Ug kon anaa kining duha ka kamatuoran, aduna pay laing kamatuoran nga labaw pa niini, nga mao, nga aduna pay laing planeta kansang pag-ihap sa panahon mas labaw pa ka taas;"},{"verse":9,"text":"Ug sa ingon adunay pag-ihap sa panahon sa usa ka planeta nga labaw pa kay sa lain, hangtod nga moabot ka sa Kolob, hain nga Kolob nagsubay sa pag-ihap sa panahon sa Ginoo; nga ang mao nga Kolob gipahimutang duol sa trono sa Dios, aron momando sa tanang planeta nga nahisakop sa sama nga han-ay niana nga imong gibarogan."},{"verse":10,"text":"Ug gihatag kanimo ang kahibalo sa gitakda nga panahon sa tanang bituon nga gikatakda nga mohatag og kahayag, hangtod nga maduol ka sa trono sa Dios."},{"verse":11,"text":"Sa ingon niana ako, si Abraham, nakigsulti sa Ginoo, nawong sa nawong, ingon sa usa ka tawo nga nakigsulti og laing tawo; ug misulti siya kanako sa mga buhat nga nahimo sa iyang mga kamot;"},{"verse":12,"text":"Ug miingon siya kanako: Akong anak, akong anak (ug ang iyang kamot gipatuy-od), tan-awa ipakita ko kanimo kining tanan. Ug gibutang niya ang iyang kamot sa akong mga mata, ug nakita nako kadtong mga butang nga gihimo sa iyang mga kamot, nga daghan; ug nagkadaghan kini sa akong panan-aw, ug dili nako makita ang kataposan niini."},{"verse":13,"text":"Ug misulti siya kanako: Kini ang Shinehah, nga mao ang adlaw. Ug misulti siya kanako: Ang Kokob, nga mao ang bituon. Ug misulti siya kanako: Ang Olea, nga mao ang bulan. Ug misulti siya kanako: Kokaubeam, nga nangahulogan nga mga bituon, o ang tanang dagko nga mga kahayag, nga anaa sa kawanangan sa langit."},{"verse":14,"text":"Ug panahon kadto sa kagabhion dihang ang Ginoo misulti niini nga mga pulong ngari kanako: Ako mopadaghan kanimo, ug sa imong binhi nga mosunod kanimo, sama niini; ug kon dili ikaw makaihap sa gidaghanon sa mga balas, mao usab ang gidaghanon sa imong mga binhi."},{"verse":15,"text":"Ug ang Ginoo misulti ngari kanako: Abraham, gipakita ko kanimo kining tanan nga butang sa dili pa ikaw moadto sa Ehipto, aron imong ipahayag kining tanan nga pulong."},{"verse":16,"text":"Kon adunay duha ka butang, ug ang usa maoy labaw nilang duha, aduna pay dagkong mga butang nga molabaw pa nila; busa ang Kolob mao ang labing hayag sa tanang Kokaubeam nga imong nakita, tungod kay duol kini kanako."},{"verse":17,"text":"Karon, kon adunay duha ka butang, ang usa maoy labaw nilang duha, ug ang bulan anaa sa ibabaw sa yuta, niana mahimo nga adunay planeta o usa ka bituon nga anaa sa ibabaw niini; ug walay butang nga tinguhaon ang Ginoo nimong Dios sa iyang kasingkasing nga buot Niyang buhaton gawas nga iya kining buhaton."},{"verse":18,"text":"Bisan pa niana gibuhat niya ang mas dako nga bituon; ingon man, usab, kon adunay duha ka espiritu, ug ang usa nila mas maalamon, apan kining duha ka espiritu, bisan pa kon ang usa nila mas maalamon, walay sinugdanan; diha na silang daan, wala silay kataposan, magpadayon silang buhi pagkahuman, kay sila mga gnolaum, o mahangtoron."},{"verse":19,"text":"Ug ang Ginoo misulti kanako: Kining duha ka kamatuoran anaa gayod, nga adunay duha ka espiritu, ang usa nila mas maalamon kay sa usa; aduna pay lain nga mas maalamon kay kanila; Ako mao ang Ginoo nga imong Dios, Ako mas maalamon kay kanilang tanan."},{"verse":20,"text":"Ang Ginoo nga imong Dios mipadala sa iyang anghel aron moluwas kanimo gikan sa mga kamot sa pari ni Elkenah."},{"verse":21,"text":"Ako nagpuyo sa taliwala kanilang tanan; busa, ako karon, nanaog nganha kanimo aron ipadayag diha kanimo ang mga buhat nga gimugna sa akong mga kamot, diin ang akong kaalam milabaw kanilang tanan, kay ako nagmando sa ibabaw sa kalangitan, ug sa ilawom sa yuta, sa tanan nga kaalam ug pagkamabinantayon, ibabaw sa tanang espiritu nga makita sa imong mga mata sukad sa sinugdanan; ako nanaog sa sinugdanan sa taliwala sa tanang espiritu nga imong nakita."},{"verse":22,"text":"Karon ang Ginoo mipakita ngari kanako, si Abraham, sa mga kinaadman nga giorganisar sa wala pa ang kalibotan; ug taliwala niining tanan dihay daghan nga mga halangdon ug bantogan;"},{"verse":23,"text":"Ug nakita sa Dios nga kini nga mga kalag mga maayo, ug mitindog siya sa ilang taliwala, ug miingon siya: Kini sila himoon ko nga akong mga magmamando; kay nagbarog siya uban niadtong mga espiritu, ug nakita niya nga mga maayo sila; ug misulti siya kanako nga: Abraham, usa ikaw kanila; gipili ka sa wala pa ikaw matawo."},{"verse":24,"text":"Ug dihay usa nga nagbarog uban kanila nga sama sa Dios, ug miingon siya ngadto sa iyang mga kauban: Manaog kita, kay adunay luna didto, ug dad-on nato kini nga mga butang, ug magbuhatkita og usa ka yuta diin kini sila mahimo nga makapuyo;"},{"verse":25,"text":"Ug ato silang sulayan pinaagi niini, aron masuta kon mobuhat ba sila sa tanang butang, bisan unsa nga isugo sa Ginoo nga ilang Dios ngadto kanila;"},{"verse":26,"text":"Ug sila nga nagmatinud-anon sa ilang unang naangkon nga kahimtang pagadugangan; ug sila nga dili magmatinud-anon sa ilang unang naangkon nga kahimtang dili makaangkon og himaya sa sama nga gingharian uban niadtong nagmatinud-anon sa ilang unang naangkon nga kahimtang; ug sila nga nagmatinud-anon sa ilang ikaduhang naangkon nga kahimtang makabaton og himaya nga idugang sa ilang mga ulo hangtod sa hangtod."},{"verse":27,"text":"Ug ang Ginoo miingon: Kinsa ang akong ipadala? Ug ang usa mitubag sama sa Anak sa Tawo: Ania ako, ipadala ako. Ug adunay lain nga mitubag ug miingon: Ania ako, ipadala ako. Ug ang Ginoo miingon: Akong ipadala ang nag-una."},{"verse":28,"text":"Ug ang ikaduha nasuko, ug wala magmatinud-anon sa iyang unang naangkon nga kahimtang; ug, nianang adlawa, daghan ang misunod kaniya."}]},{"chapter":4,"verses":[{"verse":1,"text":"Ug unya ang Ginoo miingon: Manaog kita. Ug nanaog sila sa sinugdanan, ug sila, nga mao ang mga Dios, miorganisar ug miumol sa kalangitan ug sa yuta."},{"verse":2,"text":"Ug ang yuta, human kini maumol, walay sulod ug awaaw, tungod kay walay lain nga ilang giumol gawas lang sa yuta; ug ang kangitngit naghari sa ibabaw sa lawod, ug ang Espiritu sa mga Dios nagsuhid sa ibabaw sa katubigan."},{"verse":3,"text":"Ug sila (ang mga Dios) miingon: Padan-aga ang kahayag; ug dihay kahayag."},{"verse":4,"text":"Ug sila (ang mga Dios) nakabatyag sa kahayag, kay sanag kini; ug gibahin nila ang kahayag, o gilain kini, gikan sa kangitngit."},{"verse":5,"text":"Ug gitawag sa mga Dios ang kahayag og Adlaw, ug ang kangitngit gitawag nila og Gabii. Ug nahitabo nga gitawag nila og gabii ang gikan sa kagabhion hangtod sa kabuntagon; ug gitawag nila og adlaw ang gikan sa kabuntagon hangtod sa kagabhion; ug mao kini ang una, o ang sinugdanan, nianang gitawag nila og adlaw ug gabii."},{"verse":6,"text":"Ug ang mga Dios miingon usab: Himoa ang kawanangan sa taliwala sa katubigan, ug mobahin kini sa katubigan gikan sa katubigan."},{"verse":7,"text":"Ug ang mga Dios mimando sa kawanangan, aron kini mobulag sa katubigan nga ubos sa kawanangan gikan sa katubigan nga ibabaw sa kawanangan; ug kini natuman, gani ingon sa ilang pagmando."},{"verse":8,"text":"Ug gitawag sa mga Dios ang kawanangan, og Langit. Ug nahitabo nga nagsugod sa kagabhion hangtod sa kabuntagon ang gitawag nila og gabii; ug nahitabo nga nagsugod sa kabuntagon hangtod sa kagabhion ang gitawag nila og adlaw; ug kini mao ang ikaduhang higayon nga gitawag nila og gabii ug adlaw."},{"verse":9,"text":"Ug mimando ang mga Dios, nga nag-ingon: Pundoka ang katubigan ubos sa langit ngadto sa usa ka dapit, ug patunghaa ang yuta nga uga; ug natuman kini sigon sa ilang gimando;"},{"verse":10,"text":"Ug gitawag sa mga Dios ang uga nga yuta, og Yuta; ug ang pagkapundok sa katubigan, gitawag nila, og Dagko nga Katubigan; ug nakakita ang mga Dios nga gituman sila."},{"verse":11,"text":"Ug miingon ang mga Dios: Andamon nato ang yuta aron makapatubo og sagbot; ang tanom nga mopasanay og binhi; ang kahoy nga mopasanay og bunga, subay sa iyang matang, kansang binhi sa iyang kaugalingon mismo mopasanay sa iyang kaugalingong matang sa ibabaw sa yuta; ug natuman kini, gani sigon sa ilang gimando."},{"verse":12,"text":"Ug ang mga Dios miorganisar sa yuta aron mopatubo og sagbot gikan sa iyang kaugalingong binhi, ug ang tanom aron momugna og tanom gikan sa iyang kaugalingong binhi, mopasanay og binhi sumala sa iyang matang; ug ang yuta aron mopatubo og kahoy gikan sa iyang kaugalingong binhi, nga mamunga, kansang binhi makapatubo lamang og sama kaniya, subay sa iyang matang; ug nakita sa mga Dios nga gituman kini."},{"verse":13,"text":"Ug nahitabo nga giihap nila ang mga adlaw; sugod sa kagabhion hangtod sa buntag gitawag nila og gabii; ug nahitabo, nga ang gikan sa kabuntagon hangtod sa kagabhion gitawag nila og adlaw; ug mao kadto ang ikatulong higayon."},{"verse":14,"text":"Ug giorganisar sa mga Dios ang mga kahayag sa kawanangan nga mao ang langit, ug gipahimo nila nga mabulag ang adlaw gikan sa gabii; ug giorganisar kini aron mahimong mga timailhan ug alang sa kapanahonan, ug alang sa mga adlaw ug mga tuig;"},{"verse":15,"text":"Ug giorganisar kini alang sa mga kahayag sa kawanangan sa langit aron mohatag og kahayag diha sa yuta; ug natuman kadto."},{"verse":16,"text":"Ug ang mga Dios miorganisar sa duha ka dagkong kahayag, ang mas dako nga kahayag aron momando sa adlaw, ug ang mas gamay nga kahayag aron momando sa gabii; uban sa mas gamay nga kahayag gipahimutang usab nila ang mga bituon;"},{"verse":17,"text":"Ug ang mga Dios mipahimutang niini sa kawanangan sa langit, aron mohatag og kahayag sa yuta, ug aron momando sa adlaw ug sa gabii, ug aron mahimong paagi nga mabahin ang kahayag gikan sa kangitngit."},{"verse":18,"text":"Ug ang mga Dios nagbantay niadtong mga butang nga ilang gimandoan hangtod nga misunod kini."},{"verse":19,"text":"Ug nahitabo nga ang gabii nagsugod sa kagabhion hangtod sa buntag; ug nahitabo nga ang adlaw nagsugod gikan sa buntag hangtod sa kagabhion; ug mao kadto ang ikaupat nga higayon."},{"verse":20,"text":"Ug ang mga Dios miingon: Atong andamon ang katubigan aron mopasanay og daghang maglihok nga mga linalang nga adunay kinabuhi; ug ang langgam, aron molupad sila ibabaw sa yuta diha sa lapad nga kawanangan sa langit."},{"verse":21,"text":"Ug giandam sa mga Dios ang katubigan aron modala kini og dagkong mga balyena, ug matag buhi nga linalang nga molihok, nga padaghanon sa katubigan sumala sa ilang matang; ug matag langgam nga may pako sumala sa ilang matang. Ug nakita sa mga Dios nga kinahanglan kining sundon, ug nga ang ilang plano maayo."},{"verse":22,"text":"Ug ang mga Dios miingon: Panalanginan nato sila, ug himoon sila nga mabungahon ug mosanay, ug mopuno sa katubigan diha sa kadagatan o dagkong katubigan; ug sugoon ang mga langgam sa pagdaghan diha sa yuta."},{"verse":23,"text":"Ug nahitabo nga nagsugod sa kagabhion hangtod sa buntag ang gitawag nila og gabii; ug nahitabo nga nagsugod sa buntag hangtod sa kagabhion ang gitawag nila og adlaw; ug kadto ang ikalima nga higayon."},{"verse":24,"text":"Ug giandam sa mga Dios ang yuta aron momugna sa buhi nga mga linalang sumala sa matang niini, mga baka ug mga butang nga magkamang, ug mga mananap sa yuta sumala sa ilang matang; ug natuman kini, sama sa ilang gipamulong."},{"verse":25,"text":"Ug giorganisar sa mga Dios ang yuta aron mopatungha sa mga mananap sumala sa ilang matang, ug mga baka sumala sa ilang matang, ug matag butang nga magkamang sa yuta sumala sa iyang matang; ug nakita sa mga Dios nga mosunod sila."},{"verse":26,"text":"Ug ang mga Dios nagtinambagay sa ilang kaugalingon ug miingon: Manaog kita ug magbuhat og tawo sumala sa atong dagway, sama kanato; ug hatagan nato sila og kamandoan sa mga isda sa dagat, ug sa mga langgam sa kahanginan, ug sa mga baka, ug sa tibuok yuta, ug sa matag butang nga nagkamang sa yuta."},{"verse":27,"text":"Busa nanaog ang mga Dios aron buhaton ang tawo sumala sa ilang kaugalingong dagway, aron siya ilang buhaton sumala sa dagway sa mga Dios, aron sila ilang buhaton nga lalaki ug babaye."},{"verse":28,"text":"Ug ang mga Dios miingon: Panalanginan nato sila. Ug ang mga Dios miingon: Mandoan nato sila nga magmabungahon ug magpasanay, ug mopuno sa yuta, ug mobuntog niini, ug momando sa mga isda sa kadagatan, ug sa mga langgam sa kahanginan, ug sa matag buhi nga butang nga naglihok diha sa yuta."},{"verse":29,"text":"Ug ang mga Dios miingon: Tan-awa, hatagan nato sila sa matag tanom nga magdala og binhi nga makita sa ibabaw sa tibuok yuta, ug sa matag kahoy nga adunay bunga diha niana; oo, ang bunga sa kahoy nga nagdala og binhi ngadto kanila ihatag nato kini; alang kini sa ilang pagkaon."},{"verse":30,"text":"Ug ngadto sa matag mananap sa yuta, ug sa matag langgam sa kahanginan, ug sa matag butang nga nagkamang sa ibabaw sa yuta, tan-awa, hatagan nato sila og kinabuhi, ug usab hatagan nato sila sa matag lunhaw nga tanom alang sa pagkaon, ug tanan niini nga mga butang iorganisar sa ingon niana nga paagi."},{"verse":31,"text":"Ug ang mga Dios miingon: Buhaton nato ang tanan nga atong gisulti, ug organisahon kini; ug tan-awa, magmasulundon kaayo sila. Ug nahitabo nga gikan sa kagabhion hangtod sa buntag ang gitawag nila og gabii; ug nahitabo nga gikan sa buntag hangtod sa kagabhion ang gitawag nila og adlaw; ug nag-ihap sila sa ikaunom nga higayon."}]},{"chapter":5,"verses":[{"verse":1,"text":"Ug sa ingon niana atong taposon ang pagbuhat sa kalangitan ug sa yuta, ug kining tanan nga daghan kaayo."},{"verse":2,"text":"Ug ang mga Dios miingon sa ilang kaugalingon: Sa ikapito nga panahon taposon nato ang atong buhat, nga atong gikauyonan; ug mamahulay kita sa ikapito nga panahon gikan sa tanan natong buhat nga atong gikauyonan."},{"verse":3,"text":"Ug gitapos sa mga Dios sa ikapito nga panahon, tungod kay sa ikapito nga panahon mamahulay sila gikan sa ilang tanang buhat diin sila (ang mga Dios) nagkauyon nga ilang pormahon; ug gibalaan kini. Ug sa ingon mao ang ilang mga paghukom sa higayon nga nagkauyon sila sa pagporma sa mga langit ug sa yuta."},{"verse":4,"text":"Ug nanaog ang mga Dios ug giumol kini nga mga henerasyon sa langit ug sa yuta, sa dihang giumol kini nianang adlawa nga giumol sa mga Dios ang yuta ug ang kalangitan,"},{"verse":5,"text":"Sumala sa tanan nga ilang gisulti mahitungod sa matag tanom sa kaumahan sa wala pa kini sa yuta, ug sa matag hilba sa kaumahan sa wala pa kini motubo; kay ang mga Dios wala magpaulan sa yuta dihang nagkauyon sila sa pagbuhat niini, ug wala pa mag-umol og tawo aron motikad sa yuta."},{"verse":6,"text":"Apan dihay misulbong nga usa ka gabon gikan sa yuta, ug mibisibis sa tibuok yuta."},{"verse":7,"text":"Ug ang mga Dios miumol sa tawo gikan sa abog sa yuta, ug mikuha sa iyang espiritu (nga mao ang espiritu sa tawo), ug mibutang niini ngadto kaniya; ug giginhawa ngadto sa lungag sa iyang mga ilong ang ginhawa sa kinabuhi, ug ang tawo nahimo nga usa ka buhing kalag."},{"verse":8,"text":"Ug ang mga Dios naghimo og tanaman, sa may silangan nga bahin sa Eden, ug didto gibutang nila ang tawo, kansang espiritu gibutang nila ngadto sa lawas nga ilang giumol."},{"verse":9,"text":"Ug gikan sa yuta gihimo sa mga Dios nga motubo ang matag kahoy nga makapahimuot sa panan-aw ug maayo alang sa pagkaon; ang kahoy sa kinabuhi, usab, diha sa taliwala sa tanaman, ug ang kahoy sa kahibalo sa maayo ug daotan."},{"verse":10,"text":"Dihay miagos nga suba gikan sa Eden, aron mobisibis sa tanaman, ug gikan didto nabahin kini ug nahimong upat ka sapa."},{"verse":11,"text":"Ug gikuha sa mga Dios ang tawo ug gibutang siya sa Tanaman sa Eden, aron mogalam niini ug moatiman niini."},{"verse":12,"text":"Ug gisugo sa mga Dios ang tawo, nga nag-ingon: Sa matag kahoy sa tanaman gawasnon ka nga mokaon,"},{"verse":13,"text":"Apan sa kahoy sa kahibalo sa maayo ug daotan, ayaw pagkaon niini; kay sa higayon nga mokaon ka niana, ikaw sa pagkatinuod mamatay. Karon ako, si Abraham, nakakita nga nagsubay kadto sa panahon sa Ginoo, nga nagsubay sa panahon sa Kolob; kay gani wala pa itudlo sa mga Dios ngadto ni Adan ang iyang pag-ihap."},{"verse":14,"text":"Ug miingon ang mga Dios: Maghimo kita og katabang alang sa lalaki, kay dili maayo nga mag-inusara ang lalaki, busa maghimo kita og katabang alang kaniya."},{"verse":15,"text":"Ug gipahinanok sa mga Dios si Adan; ug natulog siya, ug gikuha nila ang usa sa iyang mga gusok, ug gitakpan ang unod sa dapit niini;"},{"verse":16,"text":"Ug gikan sa gusok nga gikuha sa mga Dios gikan sa lalaki, nag-umol sila og babaye, ug gidala siya ngadto sa lalaki."},{"verse":17,"text":"Ug miingon si Adan: Kini mao ang bukog sa akong mga bukog, ug unod sa akong unod; karon pagatawgon siya og Babaye, tungod kay gikuha siya gikan sa lalaki;"},{"verse":18,"text":"Busa ang lalaki mobiya sa iyang amahan ug sa iyang inahan, ug mounong ngadto sa iyang asawa, ug sila mahimong usa ka unod."},{"verse":19,"text":"Ug silang duha mga hubo, ang lalaki ug ang iyang asawa, ug wala maulaw."},{"verse":20,"text":"Ug gikan sa yuta giumol sa mga Dios ang matag mananap sa kaumahan, ug ang matag langgam sa kahanginan, ug gidala sila ngadto ni Adan aron masuta kon unsa ang iyang itawag kanila; ug bisan unsa ang itawag ni Adan sa matag buhi nga binuhat, kana kinahanglan mao ang ngalan niana."},{"verse":21,"text":"Ug si Adan mihatag og mga ngalan sa tanan nga mga baka, sa langgam sa kahanginan, sa matag mananap sa kaumahan; ug alang kang Adan, dihay usa ka katabang nga angay kaniya."}]}]},{"id":"joseph-smith-matthew","title":"Joseph Smith—Mateo","englishTitle":"Joseph Smith-Matthew","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Kay sultihan ko kamo, nga dili kamo makakita kanako sukad karon ug makaila nga ako mao siya ang gisulat sa mga propeta, hangtod nga kamo moingon: Bulahan siya nga moabot sa ngalan sa Ginoo, diha sa mga panganod sa langit, ug ang tanan nga balaang mga anghel uban kaniya. Dayon nakasabot ang iyang mga disipulo nga moanhi siya pag-usab dinhi sa yuta, human siya mahimaya ug makoronahan diha sa tuo nga kamot sa Dios."},{"verse":2,"text":"Ug milakaw si Jesus, ug mibiya gikan sa templo; ug ang iyang mga disipulo miduol kaniya, aron maminaw kaniya, nag-ingon: Magtutudlo, ipakita kanamo ang kabahin sa mga gambalay sa templo, sama sa imong gipamulong—Pagalumpagon kini, ug ibilin diha kaninyo nga biniyaan."},{"verse":3,"text":"Ug si Jesus misulti kanila: Wala ba kamo makakita niining tanan nga butang, ug wala ba kamo makasabot niini? Sa pagkatinuod sultihan ko kamo, walay mahibilin dinhi, dinhi niini nga templo, nga usa ka bato nga gipatong sa laing bato nga dili matumpag."},{"verse":4,"text":"Ug si Jesus mibiya kanila, ug miadto sa Bungtod sa mga Olibo. Ug samtang naglingkod siya sa Bungtod sa mga Olibo, ang mga tinun-an miduol kaniya sa tago, nag-ingon: Sultihi kami kanus-a kini nga mga butang mahitabo nga imong gisulti kabahin sa kalaglagan sa templo, ug sa mga Judeo; ug unsa ang timailhan sa imong pag-anhi, ug sa kataposan sa kalibotan, o sa kalaglagan sa mga daotan, nga mao ang kataposan sa kalibotan?"},{"verse":5,"text":"Ug si Jesus mitubag, ug misulti ngadto kanila: Pagbantay nga walay tawo nga molingla kaninyo;"},{"verse":6,"text":"Kay daghan ang moanhi pinaagi sa akong ngalan, mag-ingon nga—ako mao si Kristo—ug molingla sa daghan;"},{"verse":7,"text":"Unya itugyan nila kamo aron pagasakiton, ug patyon kamo, ug pagadumtan kamo sa tanang nasod, tungod sa akong ngalan;"},{"verse":8,"text":"Ug unya daghan ang masakitan, ug magbudhi sa usag usa, ug magdumot sa usag usa;"},{"verse":9,"text":"Ug motungha ang daghang dili tinuod nga mga propeta, ug molingla og daghan;"},{"verse":10,"text":"Ug tungod kay modagsang ang pagkadaotan, ang gugma sa daghan magkaanam kabugnaw;"},{"verse":11,"text":"Apan siya nga magpabiling lig-on ug dili mabuntog, siya maluwas."},{"verse":12,"text":"Busa, kon kamo, makakita sa makalilisang nga kalaglagan, nga gipamulong sa propeta nga si Daniel, mahitungod sa pagkagun-ob sa Jerusalem, dayon mobarog kamo sa balaan nga dapit; si bisan kinsa nga mobasa iya kining sabton."},{"verse":13,"text":"Dayon palayasa sila nga tua sa Judea ngadto sa mga bukid;"},{"verse":14,"text":"Palayasa siya nga anaa sa atop sa balay, ug ayaw pabalika aron manguha og bisan unsang butang gikan sa iyang balay;"},{"verse":15,"text":"Ayaw usab pabalika siya nga tua sa umahan aron mokuha sa iyang mga sapot;"},{"verse":16,"text":"Ug alaot sila nga nagsabak, ug sila nga nagpasuso niana nga mga adlaw;"},{"verse":17,"text":"Busa, pag-ampo kamo sa Ginoo nga ang inyong panaw dili sa tingtugnaw, ni sa Igpapahulay nga adlaw;"},{"verse":18,"text":"Kay unya, niana nga mga adlaw, mahitabo ang dakong kalisdanan sa mga Judeo, ug sa mga lumulupyo sa Jerusalem, ingon nga wala pa gayod mapadangat sa Dios ngadto sa Israel, sukad sa sinugdanan sa ilang gingharian hangtod niini nga panahon; wala, dili usab kini ipadangat pag-usab bisan kanus-a ngadto sa Israel."},{"verse":19,"text":"Ang tanang butang nga nahitabo kanila mao lamang ang sinugdanan sa mga kagul-anan nga modangat kanila."},{"verse":20,"text":"Ug gawas kon kana nga mga adlaw mapamub-an, walay usa gayod kanila nga maluwas; apan tungod sa mga pinili, sumala sa pakigsaad, kana nga mga adlaw mapamub-an."},{"verse":21,"text":"Tan-awa, kini nga mga butang akong gipamulong kaninyo kabahin sa mga Judeo; ug usab, human sa kalisdanan niana nga mga adlaw nga moabot sa Jerusalem, kon adunay tawo nga moingon nganha kaninyo, Tan-awa, ania si Kristo, o atua didto, ayaw siya tuohi;"},{"verse":22,"text":"Kay niana nga mga adlaw usab adunay motungha nga mga dili tinuod nga Kristo, ug mini nga mga propeta, ug magpakita og dagko nga mga timailhan ug mga kahibulongan, hangtod nga, kon mahimo, molingla sila sa labing pinili, kinsa mga pinili sumala sa pakigsaad."},{"verse":23,"text":"Tan-awa, akong gipamulong kini nga mga butang nganha kaninyo tungod sa mga pinili; ug kamo usab makadungog og mga gubat, ug mga hungihong sa mga gubat; tan-awa nga kamo dili mabalaka, kay ang tanan nga akong gisulti kaninyo kinahanglan gayod nga mahitabo; apan ang kataposan wala pa."},{"verse":24,"text":"Tan-awa, gisultihan ko na kamo kaniadto;"},{"verse":25,"text":"Mao nga, kon mosulti sila kaninyo nga: Tan-awa, atua siya sa kamingawan; ayaw pag-adto didto: Tan-awa, anaa siya sa tinago nga mga lawak; ayaw kini tuohi;"},{"verse":26,"text":"Kay sama nga ang kahayag sa kabuntagon nagagikan sa silangan, ug mobanwag bisan ngadto sa kasadpan, ug motabon sa tibuok yuta, mao usab ang pag-anhi sa Anak sa Tawo."},{"verse":27,"text":"Ug karon pakitaon ko kamo og sambingay. Tan-awa, kon hain ang patay nga lawas, anha usab magpundok ang mga agila; mao usab ang akong mga pinili pagapundokon gikan sa upat ka suok sa yuta."},{"verse":28,"text":"Ug makadungog sila og mga gubat, ug mga hungihong sa mga gubat."},{"verse":29,"text":"Tan-awa mamulong ako tungod ug alang sa akong mga pinili; kay ang nasod moalsa batok sa nasod, ug gingharian batok sa gingharian; adunay mga kagutom, ug mga sakit, ug mga linog, sa nagkalain-laing mga dapit."},{"verse":30,"text":"Ug usab, tungod kay ang pagkadaotan modagsang, ang gugma sa mga tawo mag-anam kabugnaw; apan siya nga dili mabuntog, siya pagaluwason."},{"verse":31,"text":"Ug usab, kini nga Ebanghelyo sa Gingharian isangyaw sa tibuok nga kalibotan, aron mahimong saksi ngadto sa tanang nasod, ug dayon moabot ang kataposan, o ang kalaglagan sa mga daotan;"},{"verse":32,"text":"Ug usab ang mapanamastamason nga kalaglagan, nga gisulti pinaagi sa propeta nga si Daniel, matuman."},{"verse":33,"text":"Ug diha-diha dayon human sa kalisdanan niana nga mga adlaw, ang adlaw mongitngit, ug ang bulan dili mohatag sa iyang kahayag, ug ang mga bituon mahulog gikan sa langit, ug ang mga gahom sa langit pakurogon."},{"verse":34,"text":"Sa pagkatinuod, sultihan ko kamo, kini nga henerasyon, nga pakitaan niini nga mga butang, dili mahanaw hangtod ang tanan nga akong gisulti kaninyo matuman."},{"verse":35,"text":"Bisan tuod, ang mga adlaw moabot, nga ang langit ug yuta mahanaw; apan ang akong mga pulong dili mahanaw, apan ang tanan matuman."},{"verse":36,"text":"Ug, sama sa akong gisulti kaniadto, human sa kalisdanan niana nga mga adlaw, ug ang mga gahom sa kalangitan pakurogon, human niana makita ang timailhan sa Anak sa Tawo nga anaa sa langit, ug unya ang tanan nga mga tribo sa yuta magbangotan; ug sila makakita sa Anak sa Tawo nga moabot diha sa mga panganod sa langit, uban sa gahom ug dakong himaya;"},{"verse":37,"text":"Ug kinsa kadtong mopakabahandi sa akong pulong, dili malingla, kay ang Anak sa Tawo moabot, ug ipadala niya ang iyang mga anghel sa dili pa siya moabot uban sa lanog nga tunog sa trumpeta, ug pundokon nila ang nahibilin sa iyang mga pinili gikan sa upat ka hangin, gikan sa usa ka tumoy sa langit ngadto sa lain."},{"verse":38,"text":"Karon tun-i ang sambingay sa kahoy nga igos—Kon linghod pa ang mga sanga niini, ug magsugod kini sa pagpangudlot, mahibaloan ninyo nga ang ting-init duol na;"},{"verse":39,"text":"Mao usab, ang akong mga pinili, kon makita na nila kining tanan nga butang, mahibaloan nila nga duol na siya, gani anaa na sa mga pultahan;"},{"verse":40,"text":"Apan mahitungod sa adlaw, ug takna, walay usa nga nasayod; wala, dili ang mga anghel sa Dios sa langit, apan ang akong Amahan lamang."},{"verse":41,"text":"Apan sama sa nahitabo sa mga adlaw ni Noe, mao usab ang mahitabo sa pag-anhi sa Anak sa Tawo;"},{"verse":42,"text":"Kay mahitabo kanila, ang nahitabo sa mga adlaw sa wala pa ang baha; kay hangtod sa adlaw nga si Noe misulod sa arka nangaon sila ug nanag-inom, nanagminyo ug nanaghatag og pagtugot alang sa kaminyoon;"},{"verse":43,"text":"Ug wala masayod hangtod ang lunop miabot, ug mianod nilang tanan; mao usab ang pag-anhi sa Anak sa Tawo."},{"verse":44,"text":"Unya matuman kana nga gisulat, nga sa kataposang mga adlaw, duha ka tawo ang anaa sa umahan, ang usa kuhaon, ug ang usa ibilin;"},{"verse":45,"text":"Duha ka tawo ang maggaling sa galingan, ang usa kuhaon, ug ang usa ibilin;"},{"verse":46,"text":"Ug unsa ang akong isulti ngadto sa usa, akong isulti sa tanang tawo; busa, pagbantay, kay wala kamo masayod kon unsa nga oras ang inyong Ginoo moabot."},{"verse":47,"text":"Apan hibaloi kini, kon ang maayong tawo sa balay nasayod pa kon unsa nga oras ang kawatan moabot, magbantay unta siya, ug dili motugot nga ang iyang balay lungkabon, apan nakapangandam unta."},{"verse":48,"text":"Busa pangandam usab kamo, kay sa oras nga dili ninyo damhon, moabot ang Anak sa Tawo."},{"verse":49,"text":"Busa, kinsa man ang matinud-anon ug maalamon nga sulugoon, nga gihimo sa iyang agalon nga magmando sa iyang panimalay, aron hatagan sila og pagkaon sa tukmang panahon?"},{"verse":50,"text":"Bulahan kanang sulugoon, nga makita sa iyang agalon, kon moabot na siya, nga nagbuhat sa ingon; ug sa pagkatinuod sultihan ko kamo, siya mohimo kaniya nga magmamando sa iyang tanan nga butang."},{"verse":51,"text":"Apan kon kanang daotan nga sulugoon moingon diha sa iyang kasingkasing: Ang akong ginoo naglangan sa iyang pag-abot,"},{"verse":52,"text":"Ug magsugod sa pagdagmal sa iyang isigka-sulugoon, ug mokaon ug moinom uban sa mga hubog,"},{"verse":53,"text":"Ang ginoo niana nga sulugoon moabot sa adlaw nga dili siya magbantay sa iyang pag-abot, ug sa takna nga dili siya masayod,"},{"verse":54,"text":"Ug mopahimulag kaniya, ug ihatag kaniya ang iyang bahin uban sa mga tigpakaaron-ingnon; adunay mga pagdanguyngoy ug pagpangagot sa ngipon."},{"verse":55,"text":"Ug sa ingon niana moabot ang kataposan sa mga daotan, sumala sa panagna ni Moises, nga nag-ingon: Ipahimulag sila gikan sa katawhan; apan ang kataposan sa yuta wala pa, apan sa dili madugay."}]}]},{"id":"joseph-smith-history","title":"Joseph Smith—Kasaysayan","englishTitle":"Joseph Smith-History","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Gumikan sa daghang taho nga gipakaylap pinaagi sa daotan ug malipoton nga mga tawo, kalabot sa pagtubo ug pag-uswag sa Ang Simbahan ni Jesukristo sa mga Santos sa Ulahing mga Adlaw, ang tanan gilaraw sa mga tigpasiugda niini aron sa pagbatok sa kinaiyahan niini isip usa ka Simbahan ug sa pag-uswag niini sa kalibotan—naaghat ko sa pagsulat niini nga kasaysayan, aron sa paghupay sa hunahuna sa katilingban, ug aron ang tanang magpakisayod mahitungod sa kamatuoran mahatagan og kahibalo sa tinuod nga mga hitabo, sumala sa pagkahitabo niini, kalabot sa akong kaugalingon ug sa Simbahan, kutob sa mga kamatuoran nga akong nahibaloan."},{"verse":2,"text":"Niini nga kasaysayan akong ipresentar ang lain-laing hitabo kalabot niini nga Simbahan, pinaagi sa kamatuoran ug katarong, sumala sa unsa gayod ang nahitabo, o unsa kini sa pagkakaron, ug niini karon [1838] ang ikawalo nga tuig sukad sa pagkatukod sa gihisgotan nga Simbahan."},{"verse":3,"text":"Natawo ko sa tuig sa atong Ginoo sa usa ka libo walo ka gatos ug lima, sa ika-baynte tres sa Disyembre, didto sa lungsod sa Sharon, lalawigan sa Windsor, Estado sa Vermont. … Ang akong Amahan, si Joseph Smith, Sen., mibiya sa Estado sa Vermont, ug mibalhin ngadto sa Palmyra, distrito sa Ontario (Wayne na karon), sa Estado sa New York, dihang nagpanuigon ko og diyes anyos, o mga ingon niana nga pangedaron. Mga upat ka tuig human sa pag-abot sa akong Amahan sa Palmyra, gibalhin niya ang iyang pamilya ngadto sa Manchester sa samang distrito sa Ontario—"},{"verse":4,"text":"Ang iyang pamilya naglangkob og napulog usa ka kalag, nga naglakip sa, akong amahan, si Joseph Smith; akong inahan, si Lucy Smith (kinsang ngalan, sa wala pa ang iyang kaminyoon, mao ang Mack, anak nga babaye ni Solomon Mack); akong mga igsoong lalaki, si Alvin (kinsa namatay sa ika-19 sa Nobyembre, 1823, sa ika-26 nga tuig sa iyang panuigon), si Hyrum, ako, si Samuel Harrison, si William, si Don Carlos; ug ang akong mga igsoong babaye, si Sophronia, si Catherine, ug si Lucy."},{"verse":5,"text":"Sulod sa ikaduhang tuig human sa among pagbalhin ngadto sa Manchester, didto sa dapit nga among gipuy-an may talagsaon nga kahinam mahitungod sa relihiyon. Nagsugod kini sa mga Methodist, apan sa wala madugay nahimo nga kasagaran sa tanang relihiyon niana nga rehiyon sa maong nasod. Sa pagkatinuod, ang tibuok nga distrito sa nasod mura og naapektohan niini, ug daghang pundok sa mga katawhan ang nakighiusa sa lainlaing pundok sa relihiyon, nga nakamugna og dili lang gamay nga pagkalibog ug pagkabahin sa mga katawhan, ang uban nagpanawag og, “Tan-aw diri!” ug ang uban, “Tan-aw, didto!” Ang uban nakiglantugi pabor sa Methodist nga tinuohan, ang uban pabor sa mga Presbyterian, ug ang uban pabor sa mga Baptist."},{"verse":6,"text":"Kay, bisan pa sa dako kaayong gugma nga gipahayag sa mga kinabig sa nagkalain-laing tinuohan sa panahon sa ilang pagkakabig, ug sa dako nga kainit nga gipakita sa matag kaparian, kinsa mga makugihon sa pagbarog ug pagdasig niining talagsaong pagpakita sa pagbati sa relihiyon, aron ang tanan makabig, sigon sa ilang kahimuot sa pagpanawagan niini, sa pag-awhag kanila sa pagpasakop sa bisan unsang tinuohan nga ilang gikahimut-an—gani sa diha nga ang mga kinabig misugod sa pagkabahin-bahin, ang uban ngadto sa usa ka pundok ug ang uban ngadto sa lain, nakita nga ang maayong pagbinatiay sa mga pari ug mga kinabig mga pagpakaaron-ingnon lamang ug dili tinud-anay; kay ang usa ka talan-awon sa dako nga kagubot ug mangil-ad nga pagbati ang mipuli—ang pari nakiglantugi batok sa pari, ug ang kinabig batok sa kinabig; mao nga ang tanan nila nga maayong pagbinatiay sa usag usa, kon aduna man gani, nawala sa hingpit diha sa kagubot sa mga pulong ug sa pagpalabwanay mahitungod sa mga opinyon."},{"verse":7,"text":"Niining panahona nagpanuigon ko og napulo ug lima ka tuig. Ang pamilya sa akong amahan nakabig ngadto sa tinuohan sa Presbyterian, ug upat kanila nagpasakop niana nga simbahan, si Lucy, ang akong inahan; akong mga igsoong lalaki nga si Hyrum ug si Samuel Harrison; ug ang akong igsoong babaye nga si Sophronia."},{"verse":8,"text":"Niining panahon sa dakong kasamok, ang akong hunahuna napukaw sa matinguhaon nga pamalandong ug dakong kabalisa; apan, bisan kon lawom ang akong mga pagbati ug sa kasagaran makusganon, sa gihapon gipalayo nako ang akong kaugalingon gikan niini nga mga pundok, bisan pa og mitambong ko sa ilang daghang tigom kutob sa itugot sa panahon. Sa pagdagan sa panahon ang akong hunahuna medyo nakadayeg sa tinuohan sa Methodist, ug mibati ko og gamay nga kadasig nga makighiusa nila; apan hilabihan ang kalibog ug kagubot taliwala sa nagkalain-laing tinuohan, nga imposible sa usa ka batan-on nga tawo nga sama nako, nga walay kasinatian sa katawhan ug sa mga butang, aron makakab-ot og piho nga paghukom kon kinsa ang tinuod ug kinsa ang sayop."},{"verse":9,"text":"Ang akong hunahuna usahay hilabihan ka mahinamon, ang singgit ug kabanha hilabihan ug walay paghunong. Ang mga Presbyterian makusganong nakigbatok sa mga Baptist ug sa mga Methodist, ug migamit sa tanang gahom sa rason ug pagpakiglalis aron pamatud-an ang ilang mga sayop, o, sa labing minos, aron lamang ang katawhan maghunahuna nga sila ang sayop. Sa laing bahin, ang mga Baptist ug ang mga Methodist sa ilang bahin parehong madasigon sa pagpaninguha nga mapalig-on ang ilang kaugalingong tinuohan ug mapamatud-ang sayop ang uban."},{"verse":10,"text":"Sa taliwala niini nga gubat sa mga pulong ug kagubot sa mga opinyon, sa kasagaran nakaingon ko sa akong kaugalingon: Unsa kaha ang buhaton? Kinsa sa tanan niining mga pundok ang tinuod; o, sila bang tanan mga sayop? Kon adunay usa kanila nga tinuod, hain niini, ug sa unsang paagi nga mahibaloan ko kini?"},{"verse":11,"text":"Samtang nanlimbasog ko ubos sa hilabihan nga kalisod tungod sa mga panagbangga niini nga nagkalain-laing pundok sa mga relihiyon, usa ka adlaw niana nagbasa ko sa Epistola ni Santiago, unang kapitulo ug ikalimang bersikulo, nga mabasa: Kon aduna man kaninyoy nakulangan ug kaalam, papangayoa siya sa Dios nga nagapanghatag ngadto sa tanang tawo sa madagayaon gayod ug sa walay pagpamoyboy, ug kini igahatag kaniya."},{"verse":12,"text":"Wala pay bisan unsang tudling sa kasulatan nga mas gamhanang nakatandog sa kasingkasing sa tawo kay sa nabuhat niini ngari kanako niining panahona. Ingon og misulod kini uban sa makusog nga gahom ngadto sa matag pagbati sa akong kasingkasing. Namalandong ako niini sa makadaghan, kay nasayod nga kon adunay tawo nga nagkinahanglan og kaalam gikan sa Dios, ako kana; kon unsay buhaton, wala ako masayod, ug gawas kon makaangkon ko og dugang pa nga kaalam nga labaw pa kay sa ako nang nahibaloan, dili gayod nako mahibaloan; kay ang mga magtutudlo sa relihiyon sa lain-laing pundok lahi-lahi ra kaayo og pagsabot sa samang mga pulong sa kasulatan nga nakawagtang sa tanang pagsalig nga matubag ang pangutana pinaagi sa pagdangop ngadto sa Biblia."},{"verse":13,"text":"Sa kadugayan nakahukom ko nga magpabilin lang ba gayod ako sa kangitngit ug sa kalibog, o buhaton gayod nako ang sama sa gisugo ni Santiago, nga mao, ang pagpangutana sa Dios. Ako sa kadugayan miabot sa hugot nga tinguha nga “mangutana sa Dios,” nagatuo nga kon mohatag siya og kaalam ngadto kanila nga nagkulang og kaalam, ug mohatag sa madagayaon gayod, ug sa walay pagpamoyboy, sulayan ko kini."},{"verse":14,"text":"Busa, pinasubay niini, sa akong hugot nga tinguha nga mangutana sa Dios, miadto ako sa kakahoyan aron mosulay. Usa kadto ka buntag sa matahom, maayo nga panahon, sa sayo nga bahin sa tingpamulak sa usa ka libo ug walo ka gatos ug kawhaan. Mao kadto ang unang higayon sa akong kinabuhi nga mihimo ako sa ingon nga pagsulay, kay taliwala sa akong tanang kabalaka wala pa gayod ako makasulay nga ilitok gayod ang pag-ampo."},{"verse":15,"text":"Human ako moabot sa dapit nga akong gilaraw nga adtoan, human makapaniid sa akong palibot, ug nakita ang akong kaugalingon nga nag-inusara, miluhod ko ug misugod sa pagtugyan sa mga tinguha sa akong kasingkasing ngadto sa Dios. Dili pa dugay akong nagsugod, sa dihang sa kalit lang gipugngan ko sa usa ka gahom nga hingpit nga mibuntog kanako, ug adunay dako nga kahibulongang gahom ibabaw kanako nga mipugong sa akong dila aron dili ko makasulti. Bagâ nga kangitngit ang mialirong kanako, ug gikaingon ko sa makadiyot nga ingon og gitulod ko ngadto sa kalit nga kalaglagan."},{"verse":16,"text":"Apan, sa pagpanlimbasog sa tibuok nakong gahom sa pagtawag sa Dios aron moluwas kanako gikan sa gahom niini nga kaaway nga mihakop kanako, ug niana nga higayon sa diha nga ako andam na nga maunlod ngadto sa pagkawalay paglaom ug pagtugyan sa akong kaugalingon ngadto sa kalaglagan—dili usa ka bunga sa hunahuna nga pagkapukan, apan gikan sa gahom sa usa ka tinuod nga binuhat gikan sa dili makita nga kalibotan, kinsa nagbaton og ingon ka dako nga kahibulongan nga gahom nga sukad wala pa gayod masinati gikan sa bisan unsang binuhat—ug dinhi niini nga higayon sa dako nga kahadlok, ako nakakita og dakong gilis sa kahayag ibabaw gayod sa akong ulo, labaw sa kahayag sa adlaw, nga nag-anam og paubos hangtod nga midapat kini kanako."},{"verse":17,"text":"Sa diha dayon nga kini mipakita, akong nakaplagan ang akong kaugalingon nga giluwas gikan sa kaaway nga migapos kanako. Sa dihang ang kahayag midapat kanako ako nakakita og duha ka Personahe, kansang kahayag ug himaya dili mahulagway, nagtindog ibabaw kanako diha sa kahanginan. Ang usa kanila misulti ngari kanako, nagtawag kanako sa akong ngalan, ug miingon, samtang nagtudlo sa lain—Kini ang Akong Hinigugmang Anak. Paminaw Kaniya!"},{"verse":18,"text":"Ang akong tuyo sa pagpangutana sa Ginoo mao ang pagpakisayod hain sa tanang tinuohan ang tinuod, nga akong masayran asa ako magpasakop. Busa, sa wala madugay, nabalik ko sa akong kaugalingon, nga andam na ko nga mosulti, nangutana dayon ko sa mga Personahe kinsa nagbarog ibabaw kanako diha sa kahayag, hain sa tanang tinuohan ang tinuod (kay niini nga higayon wala gayod sa akong kasingkasing nga ang tanan mga sayop)—ug asa ako kinahanglan magpasakop."},{"verse":19,"text":"Gitubag ko nga kinahanglan dili ko mopasakop sa bisan hain kanila, kay silang tanan mga sayop; ug ang Personahe nga nakigsulti kanako miingon nga ang ilang tanang tinuohan mga salawayon sa iyang panan-aw; nga kadtong tanang nangangkon nga mga magtutuo mga daotan; nga: “sila nagpaduol ngari kanako pinaagi sa ilang mga ngabil, apan ang ilang mga kasingkasing layo gikan kanako, nagtudlo sila og mga doktrina nga mga sugo sa mga tawo, nga may hulagway sa pagkadiosnon, apan gipanghimakak nila ang gahom niana.”"},{"verse":20,"text":"Gibalik na usab niya ang pagdili kanako nga magpasakop sa bisan hain kanila; ug daghan pa ang mga butang nga gisulti niya ngari kanako, nga dili nako masulat niining panahona. Sa diha nga ako nahibalik sa akong kaugalingon pag-usab, akong nakaplagan ang akong kaugalingon nga naghigda, nagtan-aw ngadto sa langit. Sa dihang nawala na ang kahayag, nawad-an ko og kusog; apan sa wala madugay naulian og gamay, mipauli ko. Ug samtang nagsandig ko sa may halingan sa kalayo, ang akong inahan nangutana unsa ang nahitabo. Mitubag ko, “Ayaw og kabalaka, maayo ra ang tanan—Maayo ra man ko.” Unya misulti dayon ko sa akong inahan, “nahibaloan nako sa akong kaugalingon nga ang Presbyterian dili tinuod.” Ingon og nakamatngon ang kaaway, sa sayo pa kaayo nga panahon sa akong kinabuhi, nga ako gitagana aron mahimong tigsamok ug tigpaisugda og kagubot sa iyang gingharian; kay kon dili pa ngano nga ang mga gahom sa kangitngit nagkahiusa man batok kanako? Ngano nga ang pagbatok ug pagpanggukod mitungha batok kanako, bisan sa akong pagkabatan-on?"},{"verse":21,"text":"Pipila ka adlaw human niini nga panan-awon, nakahigayon ko sa pagpakig-uban sa usa sa mga tigsangyaw sa Methodist, kinsa hilabihan ka madasigon sa nahisgotan nga relihiyoso nga kahinam; ug, nakigsulti kaniya mahitungod sa relihiyon, nakahigayon ko sa paghatag kaniya og asoy sa panan-awon nga akong nakita. Nahibulong kaayo ko sa iyang mga lihok; dili lamang nga wala niya hatagi og gibug-aton ang akong gipamulong, apan sa dakong pagtamay, nag-ingon nga kining tanan gikan sa yawa, nga wala na kuno kanang mga butang sama sa mga panan-awon o mga pagpadayag niini nga mga adlaw; nga kanang mga butanga nahunong na uban sa apostoles, ug nga wala nay bisan unsa nga madugang pa niana."},{"verse":22,"text":"Hinuon, sa wala madugay akong nakita nga ang akong pag-asoy sa sugilanon nakapaukay og hilabihan nga pagtamay batok kanako taliwala sa mga magtutudlo sa relihiyon, ug mao kini ang hinungdan sa hilabihang pagpanggukod, diin mipadayon sa pagdaghan; ug bisan ako usa ka bata nga wala mailhi, tali sa napulog upat ug napulog lima ka tuig lamang ang panuigon, ug ang akong mga sirkumstansiya sa kinabuhi ingon niadto nga nakapahimo sa usa bata nga dili inila dinhi sa kalibotan, apan ang mga tawo nga halangdon mihatag og igong pagtagad aron sa pag-ukay sa hunahuna sa katawhan batok kanako, ug pasiugdahan ang mapait nga pagpanggukod; ug mao kini ang nagpasulabi diha sa tanang tinuohan—ang tanan nagkahiusa sa paggukod kanako."},{"verse":23,"text":"Mao kini ang hinungdan sa akong lawom nga pagpamalandong kaniadto, ug sa kanunay sukad niadto, kahibulongan kaayo nga ang usa ka wala mailhi nga batang lalaki, nga labaw lamang og diyotay sa napulog upat ka tuig ang panuigon, ug usab, usa ka tawo nga gitakda sa kapalaran nga mabuhi pinaagi sa iyang uyamot nga inadlaw nga pagtrabaho, gihunahuna nga usa ka tawo nga may igong kadungganan sa pagdani sa pagtagad sa mga halangdon ug labing inila nga mga relihiyon niini nga panahon, ug sa paagi nga nakamugna diha kanila sa espiritu sa labing mapait nga pagpanggukod ug pagbiay-biay. Apan kahibulongan o dili, mao kini, ug kini kanunay ang naghatag og hilabihan nga kasubo sa akong kaugalingon."},{"verse":24,"text":"Hinuon, bisan pa niana tinuod gayod nga nakakita ako og panan-awon. Sukad niadto naghunahuna ko, nga akong gibati nga sama gayod ni Pablo, sa dihang iyang gihimo ang iyang pagpanalipod sa atubangan ni Hari Agripa, ug misaysay sa hitabo sa panan-awon nga iyang nakita sa diha nga siya nakakita og kahayag, ug nakadungog og usa ka tingog; apan sa gihapon dihay pipila lamang nga mituo kaniya; ang uban miingon nga bakakon siya, ang uban miingon nga nabuang siya; ug gitamay siya ug gibiay-biay. Apan kining tanan wala makaguba sa pagkatinuod sa iyang panan-awon. Nakakita siya og panan-awon, nasayod siya nga nakakita siya, ug ang tanang pagpanggukod ubos sa langit dili makapausab niini; ug bisan pa nga sila mogukod kaniya hangtod sa kamatayon, apan sa gihapon nasayod siya, ug masayod hangtod sa kataposan niya nga pagginhawa, nga nakakita siya og kahayag ug nakadungog og tingog nga nagsulti ngadto kaniya, ug ang tibuok kalibotan dili makapausab sa iyang hunahuna o gituohan."},{"verse":25,"text":"Ingon usab niana ang akong nasinati. Ako sa tinuod nakakita gayod og usa ka kahayag, ug sa taliwala niana nga kahayag nakakita ako og duha ka Personahe, ug sila tinuod gayod nga namulong ngari kanako; ug bisan kon gikasilagan ako ug gigukod sa pag-ingon nga nakakita ako og usa ka panan-awon, apan tinuod kini; ug samtang naggukod sila kanako, nagbiay-biay kanako, ug namulong sa tanang matang sa daotan batok kanako sa bakak nga paagi tungod sa akong pagsulti niini, gitultolan ako sa pag-ingon sa akong kasingkasing: Nganong gigukod man ako tungod sa pagsulti sa kamatuoran? Tinuod gayod nga nakakita ako og panan-awon; ug kinsa man ako nga makaharong sa Dios, o ngano nga ang kalibotan naglaraw man sa pagpalimod kanako kon unsa ang akong tinuod nga nakita? Kay nakakita ako og panan-awon; nasayod ako niini, ug nasayod ako nga ang Dios nasayod niini, ug dili ako makalimod niini, ni mangahas ako sa pagbuhat niini; gani nasayod ako nga sa pagbuhat sa ingon makasala ako sa Dios, ug mahimutang ubos sa panghimaraot."},{"verse":26,"text":"Nakab-ot ko na karon ang katagbawan sa akong hunahuna kon ang tinuohan sa kalibotan ang hisgotan—nga dili akong katungdanan ang pagpasakop sa bisan hain kanila, apan nga ako magpadayon sa mao nga butang hangtod ako pagamandoan. Nakaamgo ako nga ang pagpamatuod ni Santiago tinuod—nga ang tawo nga nagkulang og kaalam mahimong mangayo sa Dios, ug makaangkon, ug dili kasuk-an."},{"verse":27,"text":"Nagpadayon ako sa akong naandan nga kalihokan sa kinabuhi hangtod sa ikakawhaan ug usa sa Septyembre, usa ka libo walo ka gatos ug kawhaan ug tulo, sa tanang panahon nag-antos sa hilabihang pagpanggukod diha sa mga kamot sa tanang matang sa tawo, relihiyoso ug dili relihiyoso, tungod kay nagpadayon ako sa pagmatuod nga nakakita ako og panan-awon."},{"verse":28,"text":"Sa panahon nga milabay tali sa panahon nga akong nakita ang panan-awon ug sa tuig nga usa ka libo walo ka gatos ug kawhaan ug tulo—kay gipahimangnoan nang daan nga dili magpasakop sa bisan unsang pundok sa mga tinuohan niadtong panahona, ug tungod sa kabatan-on, ug gigukod niadtong unta akong mga higala ug unta angay mohatag kanako og mabinationg pagtagad, ug kon nagtuo sila nga nalingla ko, unta naninguha sila sa maayo ug mahigugmaong paagi sa pagbawi kanako—gipabantang ako sa tanang matang sa tentasyon; ug, nakig-uban sa tanang matang sa katilingban, nahulog ko ngadto sa daghang walay hinungdan nga kasaypanan, ug nagpakita sa kahuyang sa kabatan-on, ug ginagmayng sayop tungod sa tawhanong kinaiya; diin, ako masulub-ong moingon nga, mitukmod kanako ngadto sa nagkalain-laing pagsulay, nga makapahiubos sa panan-aw sa Dios. Sa paghimo niini nga pagkompisal, walay usa nga angay maghunahuna nga nakahimo ko og dagko o bug-at nga mga sala. Ang kabubut-on sa paghimo niana wala gayod sa akong kinaiya. Apan sad-an ako sa pagkasipat, ug usahay sa pagpakig-uban sa mahudyakaon nga mga pundok, ug uban pa, nga dili haom sa kinaiya nga angay huptan sa tawo nga gitawag sa Dios sama kanako. Apan dili kaayo kini kahibulongan ni bisan kinsa nga nahinumdom sa akong pagkabatan-on, ug nakasinati sa akong pagkamalipayon og buot."},{"verse":29,"text":"Agi og sangpotanan niining mga butanga, kanunay akong mibati nga gipanghimaraot tungod sa akong kahuyang ug kasaypanan; dihang, sa gabii sa gihisgotan nga ikakawhaan ug usa sa Septiyembre, human nga nakapahulay ako sa akong higdaanan nianang gabhiona, akong gihimo ang pag-ampo ug pagpangamuyo sa Makagagahom nga Dios alang sa kapasayloan sa akong tanan nga sala ug mga kabuang, ug usab alang sa usa ka pagpadayag ngari kanako, aron akong mahibaloan ang akong estado ug kahimtang diha sa iyang atubangan; kay puno ako sa pagsalig nga makabaton og balaan nga pagpadayag, kay nakasinati na man ako niini kaniadto."},{"verse":30,"text":"Samtang nagtawag ako sa Dios sa ingon niana nga paagi, nakakita ko og kahayag nga mitungha sa akong lawak, nga nag-anam pa gayod og kahayag hangtod nga ang lawak mas hayag pa kay sa udtong tutok, sa dihang kalit lang may personahe nga mitungha sa kiliran sa akong higdaanan, nagbarog sa hangin, kay ang iyang mga tiil wala magtugkad sa salog."},{"verse":31,"text":"Nagsul-ob siya og luag nga sapot nga may talagsaong pagkaputi. Pagkaputi kadto nga labaw pa sa bisan unsa nga akong nakita dinhi sa yuta; wala usab ako magtuo nga adunay bisan unsang butang dinhi sa yuta nga ikapakita sa ingon niadto ka hilabihan nga kaputi ug kasilaw. Dayag ang iyang mga kamot, ang iyang mga bukton usab, sa ibabaw og diyotay sa mga pulso; ingon, usab, ang iyang mga tiil dayag, sama sa iyang mga bitiis, ibabaw og diyotay sa mga tikod. Ang iyang ulo ug liog dayag usab. Nakamatikod ko nga wala siyay laing gisul-ob gawas sa kupo, kay bukas kadto, nga niana makita nako ang ibabaw nga bahin sa iyang dughan."},{"verse":32,"text":"Dili lamang ang iyang kupo maoy hilabihan ka puti, apan ang iyang tibuok nga pagkatawo mahimayaon nga lisod ihulagway, ug ang iyang pamayhon sa pagkatinuod sama sa kilat. Ang lawak hilabihan ka hayag, apan dili kaayo sama ka sanag diha sa nagliyok kaniya. Sa una nakong pagkakita kaniya, nahadlok ko; apan ang kahadlok dali ra nga nawala."},{"verse":33,"text":"Iya akong gitawag sa akong ngalan, ug miingon kanako nga sinugo siya nga gipadala gikan sa atubangan sa Dios ngari kanako, ug nga ang iyang ngalan mao si Moroni; nga ang Dios adunay ipabuhat kanako; ug nga ang akong ngalan gamiton alang sa maayo ug sa daotan taliwala sa tanang kanasoran, kaliwatan, ug pinulongan, o nga kini litokon sa maayo ug sa daotan taliwala sa tanang katawhan."},{"verse":34,"text":"Misulti siya nga adunay basahon nga gitagoan, gisulat sa bulawan nga mga palid, naghatag og asoy sa kaagi sa unang mga lumulupyo niining dako nga kayutaan, ug sa tinubdan sa ilang kagikan. Misulti usab siya nga ang kahingpitan sa walay kataposan nga Ebanghelyo anaa niini, sama sa gisulti sa Manluluwas ngadto sa karaang mga lumulupyo;"},{"verse":35,"text":"Usab, adunay duha ka bato nga anaa sa bayanan nga plata—ug kini nga mga bato, gipakapot og maayo sa usa ka panagang sa dughan, naglangkob sa gitawag nga Urim ug Tumim—gitagoan uban sa mga palid; ug ang pagbaton ug paggamit niini nga mga bato mao ang nagtino sa “pagkamanalagna” sa karaan o nangagi nga mga panahon; ug nga ang Dios ang miandam niini alang sa katuyoan sa paghubad sa basahon."},{"verse":36,"text":"Human nga gikasulti kanako kini nga mga butang, misugod siya sa pagkutlo sa mga panagna sa Daang Tugon. Una niyang gikutlo ang kabahin sa ikatulo nga kapitulo sa Malaquias; ug gikutlo usab niya ang ikaupat o kataposan nga kapitulo sa mao gihapon nga panagna, bisan tuod og adunay gamay nga kausaban kon kini basahon sa atong mga Biblia. Imbes nga mokutlo sa unang bersikulo sama sa mabasa sa atong mga basahon, ingon niini ang iyang pagkutlo:"},{"verse":37,"text":"Ug tan-awa, moabot ang adlaw nga magasunog sama sa usa ka hudno, ug ang tanang mapahitas-on, oo, ug ang tanang nagbuhat og daotan pagasunogon sama sa dagami; kay sila nga moabot mosunog kanila, miingon ang Ginoo sa mga Panon, nga walay ibilin kanila ni gamot o sanga."},{"verse":38,"text":"Ug usab, gikutlo niya ang ikalima nga bersikulo nga nag-ingon: Tan-awa, ipadayag ko kaninyo ang Pagkapari, pinaagi sa kamot ni Elijah ang propeta, sa dili pa moabot ang mahinungdanon ug makalilisang nga adlaw sa Ginoo."},{"verse":39,"text":"Gikutlo usab niya ang sunod nga bersikulo sa laing paagi: Ug itanom niya sa mga kasingkasing sa mga anak ang mga saad nga gihimo ngadto sa mga amahan, ug ang mga kasingkasing sa mga anak mobati sa ilang mga amahan. Kon dili pa ingon niini, ang tibuok kalibotan pagalaglagon sa hingpit sa iyang pag-abot."},{"verse":40,"text":"Dugang pa niini, gikutlo niya ang ikanapulog usa nga kapitulo sa Isaias, nag-ingon nga kini hapit na matuman. Gikutlo usab niya ang ikatulo nga kapitulo sa Mga Buhat, kawhaan ug duha ug kawhaan ug tulo nga mga bersikulo, tukma sa pagkahan-ay niini sa atong Bag-ong Tugon. Misulti siya nga ang propeta mao si Kristo; apan ang adlaw wala pa moabot nga “sila nga dili maminaw sa iyang tingog isalikway gikan sa taliwala sa mga katawhan,” apan sa dili madugay moabot."},{"verse":41,"text":"Gikutlo usab niya ang ikaduha nga kapitulo sa Joel, gikan sa ikakawhaan ug walo nga bersikulo ngadto sa kataposan. Misulti usab siya nga wala pa kini matuman, apan hapit na mahitabo. Ug midugang siya sa pagsulti nga ang kahingpitan sa mga Hentil hapit na moabot. Mikutlo og daghan pang uban nga mga tudling sa kasulatan, ug mihatag og daghang pagpasabot nga dili pa kahisgotan dinhi."},{"verse":42,"text":"Ug usab, misulti siya kanako, nga kon makuha na nako ang mga palid nga iyang gihisgotan—kay ang panahon nga pagakuhaon kini wala pa moabot—dili ko gayod kini ipakita ngadto ni bisan kinsa nga tawo, ni ang panagang sa dughan uban sa Urim ug Tumim; gawas lamang kanila kinsa ako pagamandoan sa pagpakita niini; kon ipakita ko man kini sa uban ako pagalaglagon. Samtang nakigsulti siya kanako mahitungod sa mga palid, ang panan-awon nabuksan sa akong hunahuna nga akong nakita ang dapit diin gitago ang mga palid, ug nga tin-aw ug tataw na usab kaayo nga akong nailhan ang dapit sa dihang giadto ko kini."},{"verse":43,"text":"Human niini nga pakigsulti, akong nakita ang kahayag sa akong lawak nga nagsugod dayon sa pagtigom libot sa lawas sa tawo nga nakigsulti kanako, ug nagpadayon kini hangtod ang lawak mibalik na usab og kangitngit, gawas lamang diha sa naglibot kaniya; sa diha nga, sa kalit akong nakita ang sama sa dako nga tubo nga nagbarog paingon sa langit, ug misaka siya hangtod nga nawala siya sa hingpit, ug ang lawak nahibalik sa unang kahimtang sa wala pa magpakita kining langitnong kahayag."},{"verse":44,"text":"Naghigda ako nga naghunahuna sa pagkatalagsaon sa talan-awon, ug natingala kaayo sa gisulti kanako sa dili ordinaryo nga sinugo; sa diha nga, taliwala sa akong pagpamalandong, sa kalit lamang akong namatikdan nga nagsugod na usab og kahayag ang akong lawak, ug sa kalit, sama sa gihapon, ang mao nga langitnong sinugo diha na usab sa kiliran sa akong higdaanan."},{"verse":45,"text":"Nagsugod siya, ug gisaysay pag-usab ang mao gihapon nga mga butang nga iyang gihimo sa iyang unang pagduaw, nga walay bisan gamay nga kausaban; nga sa pagkahuman, mipahibalo siya kanako mahitungod sa pintas nga mga paghukom nga moabot sa ibabaw sa yuta, uban sa dagkong katalagman pinaagi sa kagutom, espada, ug sakit; ug nga kining bangis nga mga paghukom moabot sa yuta niini nga kaliwatan. Human sa iyang pagsaysay niini nga mga butang, misaka na usab siya sama sa iyang unang gihimo."},{"verse":46,"text":"Niini nga higayon, lawom kaayo ang napatik sa akong kaisipan, nga nawala ang akong katulogon, ug mihigda ko kay gidaog sa katingala sa akong nakita ug nabati. Apan dako ang akong kahibulong sa dihang nagpakita na usab ang mao nga sinugo diha sa kiliran sa akong higdaanan, ug nakadungog kaniya nga misaysay o misubli na usab sa pagsaysay ngari kanako sa mao gihapon nga mga butang sama sa nangagi; ug midugang og pasidaan ngari kanako, nagsulti kanako nga si Satanas mosulay sa pagtental kanako (mahitungod sa kabos nga kahimtang sa pamilya sa akong amahan), sa pag-angkon sa mga palid sa tuyo nga magpadato. Gidid-an niya ako niini, nag-ingon nga kinahanglan gayod nga wala akoy laing tumong sa pagkuha sa mga palid gawas sa paghimaya sa Dios, ug kinahanglan dili gayod magpaimpluwensya sa bisan unsang tinguha gawas sa pagpalambo sa iyang gingharian; kay kon dili, dili ko kini makuha."},{"verse":47,"text":"Human niining ikatulo nga pagduaw, misaka na usab siya ngadto sa langit sama sa una, ug gibiyaan na usab ako aron mamalandong sa pagkakatingalahan sa unsay akong bag-ohay lamang nga nasinati; sa dihang sa kalit lamang human ang langitnong sinugo mibiya kanako sa ikatulo nga higayon, mituktugaok ang manok, ug nakamatikod ko nga ang kabuntagon nagsingabot na, sa ingon niana ang among pagsultihanay milungtad sa tibuok niana nga gabii."},{"verse":48,"text":"Sa wala madugay mibangon ko gikan sa akong higdaanan, ug, sama sa naandan, miadto sa kinahanglanon nga mga buluhaton nianang adlawa; apan, sa pagsulay sa pagtrabaho sama sa naandan, akong namatikdan nga nawad-an ko og kusog ug dili makahimo sa mga buluhaton. Ang akong amahan kinsa nagtrabaho uban kanako, nakamatikod nga ako adunay gipamati sa lawas ug misugo kanako sa pagpauli. Misugod ko sa sa tuyo nga mopauli sa balay; apan, sa pagsulay sa paglatas sa koral gikan sa umahan diin kami nahimutang, nawad-an ko sa kusog, ug natumba ko sa yuta nga walay umoy, ug sa mubo nga higayon hingpit nga nawad-an sa panimuot."},{"verse":49,"text":"Ang unang butang nga akong mahinumdoman mao ang tingog nga nakigsulti kanako, nagsangpit sa akong ngalan. Mihangad ko, ug nakita ang mao gihapon nga sinugo nga nagbarog dapit sa akong ulohan, giliyokan sa kahayag sama sa una. Iya dayon nga gisaysay pag-usab ang tanan nga iyang gisulti kanako sa miaging gabii, ug misugo kanako sa pag-adto sa akong amahan ug sultihan siya bahin sa panan-awon ug sa mga sugo nga akong nadawat."},{"verse":50,"text":"Mituman ko; mibalik ko ngadto sa akong amahan nga didto pa sa umahan, ug gisaysay ang tibuok nga nahitabo ngadto kaniya. Mitubag siya kanako nga gikan kadto sa Dios, ug misugo kanako sa pag-adto ug pagbuhat sumala sa gimando sa sinugo. Mibiya ko sa umahan, ug miadto sa dapit nga gisulti sa sinugo kanako kon diin gitagoan ang mga palid; ug tungod sa katin-aw sa panan-awon nga akong nakita mahitungod niini, nailhan nako ang dapit diha-diha dayon sa akong pag-abot didto."},{"verse":51,"text":"Duol sa balangay sa Manchester, distrito sa Ontario, New York, may nagbarog nga bungtod nga adunay igong gidak-on, ug mao ang kinatas-an sa kasilinganan. Sa kasadpan nga bahin niini nga bungtod, dili kaayo layo sa ibabaw, ilawom sa bato nga may igong gidak-on, nahiluna ang mga palid, nga gisulod og kahon nga bato. Kini nga bato bagâ ug naglingin sa taliwala sa may ibabaw nga bahin, ug nagkanipis paingon sa mga ngilit, nga sa ingon ang tungâ nga bahin makita sa ibabaw sa yuta, apan ang mga ngilit palibot niini natabonan sa yuta."},{"verse":52,"text":"Human makabkab ang yuta, mikuha ko og ikaligwat, nga akong gipahimutang sa ilawom sa kilid sa bato, ug sa gamay lamang nga kusog miligwat niini. Akong gitan-aw ang sulod, ug didto gayod akong nakita ang mga palid, ang Urim ug Tumim, ug ang panagang sa dughan, sama sa gipamulong sa sinugo. Ang kahon nga gisudlan niini gihimo sa tinumpi nga gagmayng mga bato ug gibulitan sa usa ka matang sa semento. Sa ilawom sa kahon didto gipahimutang ang duha ka bato nga gibabag sa kahon, ug sa ibabaw niining mga bato nahimutang ang mga palid ug ang ubang mga butang nga nag-uban niini."},{"verse":53,"text":"Gisulayan ko kini sa pagkuha, apan gidid-an sa sinugo, ug gipahibalo pag-usab nga ang panahon sa pagpagawas niini wala pa moabot, ug dili pa mahitabo, hangtod nga moabot ang upat ka tuig sukad niadtong panahona; apan misulti siya kanako nga kinahanglan kong moanhi sa mao nga dapit tukma sa usa ka tuig gikan niadtong panahona, ug nga makigkita siya kanako didto, ug nga angay akong magpadayon sa pagbuhat niini hangtod nga moabot ang higayon sa pagkuha sa mga palid."},{"verse":54,"text":"Tungod niana, sumala sa gisugo kanako, miadto ako sa matag kataposan sa tuig, ug sa matag higayon akong nakita ang mao gihapon nga sinugo didto, ug nakadawat ug pahimangno ug kaalam gikan kaniya sa matag higayon sa among panagsultihanay mahitungod sa pagabuhaton sa Ginoo, ug kon unsaon ug sa unsa nga paagi nga idumala ang iyang gingharian sa kataposang mga adlaw."},{"verse":55,"text":"Kay ang pagkabutang sa akong amahan kabahin sa kalibotanon nga mga panginahanglan kulang kaayo, napugos kami sa pagtrabaho, magpasuhol sa inadlaw nga buluhaton, kon aduna kami kahigayonan. Usahay kami anaa ra sa among dapit, usahay sa layo, ug pinaagi sa kanunay nga pagtrabaho nakabaton og hamugaway nga panginabuhi."},{"verse":56,"text":"Sa tuig 1823 ang pamilya sa akong amahan nakasugat og dako nga kasakit sa kamatayon sa akong magulang nga lalaki, si Alvin. Sa buwan sa Oktubre, 1825, gisuholan ko sa usa ka tigulang nga maayong tawo nga ginganlan og Josiah Stoal, kinsa nagpuyo sa distrito sa Chenango, Estado sa New York. Nakadungog siya mahitungod sa usa ka mina sa pilak nga giablihan sa mga Espanyol sa Harmony, lalawigan sa Susquehanna, Estado sa Pennsylvania; ug sa wala pa ako magpasuhol kaniya, dugay nang nagkalot, aron, kon mahimo, makakaplag sa mina. Human ako moadto aron mopuyo uban kaniya, gidala ko niya, uban sa iyang mga katabang, aron sa pagkalot sa mina sa pilak, diin ako mipadayon sa pagtrabaho sulod sa usa ka bulan, nga walay kalamposan sa among paningkamot, ug sa kataposan akong gisugyot sa tigulang nga maayong tawo nga hunongon ang pagkalot human niadto. Sukad niadto mitunga ang nagpasulabi nga sugilanon nga ako usa ka tigkalot og salapi."},{"verse":57,"text":"Niini nga panahon nga ako nagtrabaho, gipapuyo ko uban sa usa ka G. Isaac Hale, niadto nga dapit; didto una nakong nakita ang akong asawa (iyang anak nga babaye), si Emma Hale. Pagka dise-otso sa Enero, 1827, nagminyo mi, samtang nagtrabaho ko sa pagserbisyo ni G. Stoal."},{"verse":58,"text":"Tungod sa akong padayon nga pagpahayag nga nakakita ko og panan-awon, ang pagpanglutos padayon gihapon nga nagsunod kanako, ang pamilya sa amahan sa akong asawa dako kaayo og pagsupak sa among kaminyoon. Busa, na-obligar ko sa pagdala niya sa laing dapit; mao nga miadto mi ug nagminyo sa balay ni Squire Tarbill, sa South Bainbridge, distrito sa Chenango, New York. Human dayon sa among kaminyoon, mibiya ko kang G. Stoal, ug miadto sa panimalay sa akong amahan, ug nag-uma uban niya niana nga panahon."},{"verse":59,"text":"Sa kadugayan miabot na ang panahon sa pagkuha sa mga palid, sa Urim ug Tumim, ug sa panagang sa dughan. Sa ikakawhaan ug duha nga adlaw sa Septiyembre, usa ka libo ug walo ka gatos ug kawhaan ug pito, human makaadto sama sa naandan sa kataposan sa laing tuig sa dapit diin kini gitagoan, ang mao gihapon nga langitnong sinugo mitugyan niini kanako inubanan niini nga panugon: nga ako gayod ang manubag niini; nga kon tugotan ko kini nga mawala tungod sa kawalay pagtagad, o sa bisan unsang paagi nga pagpasagad sa akong bahin, ako pagalaglagon; apan kon akong gamiton ang akong tanang panlimbasog sa pagpanalipod niini, hangtod nga siya, ang sinugo, mokuha niini og balik, kini mapanalipdan."},{"verse":60,"text":"Sa wala madugay akong nahibaloan ang katarongan nganong nakadawat ko sa maong higpit nga mga pahimangno sa pag-amping niini, ug ngano nga miingon ang sinugo nga kon mahuman na nako ang gipabuhat kanako, iya kining kuhaon og balik. Kay sa wala madugay dihang nahibaloan nga anaa kini kanako, gigamit dayon ang labing makusganong panlimbasog sa pag-ilog niini gikan kanako. Ang tanang malipoton nga paagi nga mamugna, gigamit alang niana nga katuyoan. Ang pagpanglutos nagkapait ug nagkagrabe kay sa kaniadto, ug daghang pundok sa katawhan nagtukaw kanunay aron sa pagkuha niini gikan kanako kon mahimo. Apan pinaagi sa kaalam sa Dios, nagpabilin kini nga luwas sa akong mga kamot, hangtod nga akong natapos pinaagi niini ang gikinahanglan gikan sa akong mga kamot. Sa dihang, sumala sa gikasabotan, ang sinugo mikuha niini og balik gikan kanako, gitugyan ko kini ngadto kaniya; ug anaa na kini kaniya hangtod niining adlawa, sa ikaduha nga adlaw sa Mayo, usa ka libo ug walo ka gatos ug katloan ug walo."},{"verse":61,"text":"Ang kasamok, hinuon, nagpadayon pa, ug ang hungihong nga may liboan ka dila sa kanunay gigamit aron sa pagsabwag sa mga bakak kabahin sa pamilya sa akong amahan, ug mahitungod sa akong kaugalingon. Ug kon akong isaysay ang ika-liboan nga bahin niini, kini makapuno og daghang basahon. Ang pagpanglutos, hinuon, dili na gayod mabaliwala nga kinahanglan kong mobiya sa Manchester, ug kuyog sa akong asawa mipaingon ngadto sa distrito sa Susquehanna, sa Estado sa Pennsylvania. Samtang nangandam alang sa pagbiya—tungod sa kawad-on, ug sa pagpanglutos nga bug-at kaayo alang kanamo nga wala nay purohan nga mausab pa ang among kahimtang—sa taliwala sa among kalisdanan nakakita kami og maayong tawo nga ginganlan og Martin Harris, kinsa miduol ug mipahulam kanamo og kalim-an ka dolyar aron sa pagtabang kanamo sa among panaw. Si G. Harris usa ka lumulupyo sa lungsod sa Palmyra, distrito sa Wayne, sa Estado sa New York, ug usa ka dungganan nga mag-uuma."},{"verse":62,"text":"Pinaagi niining tukma sa panahon nga tabang nakaabot ko sa dapit nga akong adtoan sa Pennsylvania; ug diha-diha sa akong pag-abot misugod ko sa pagkopya sa mga titik gikan sa mga palid. Nakakopya ko og ubay-ubay nga gidaghanon niini, ug pinaagi sa Urim ug Tmim akong gihubad ang uban niini, nga akong gibuhat tali sa panahon sa akong pag-abot sa balay sa amahan sa akong asawa, sa bulan sa Disyembre, ug sa Pebrero nga misunod."},{"verse":63,"text":"Sulod sa bulan sa Pebrero, ang nahisgotan nga G. Martin Harris miabot sa among dapit, mikuha sa mga titik nga akong gikopya gikan sa mga palid, ug gidala kini ngadto sa siyudad sa New York. Kon unsay nahitabo mahitungod kaniya ug sa mga titik, akong ibase sa iyang kaugalingong asoy sa mga sirkumstansiya, nga iyang gisugilon ngari kanako human sa iyang pagbalik, nga mao kining mosunod:"},{"verse":64,"text":"“Miadto ko sa siyudad sa New York, ug gipresentar ang mga titik nga gihubad, uban sa hubad niini, ngadto ni Propesor Charles Anthon, usa ka tawo nga gipasidunggan sa iyang mga kalamposan sa edukasyon sa pagsulat. Mipahayag si Propesor Anthon nga husto ang pagkahubad, labaw pa kay sa iyang nakit-an nga mga paghubad gikan sa mga taga-Ehipto. Gipakita dayon nako niya kadtong wala pa mahubad, ug misulti siya nga kadto mga Ehiptohanon, Chaldaic, Assyriac, ug Arabic, ug misulti siya nga tinuod kadto nga mga titik. Mihatag siya nako og sertipiko, nagpamatuod sa katawhan sa Palymra nga kadto tinuod nga mga titik, ug ang hubad niadto sumala sa paghubad husto usab. Gikuha nako ang sertipiko ug gisulod sa akong bulsa, ug nangandam na sa pagbiya sa balay, dihang si G. Anthon mitawag nako nga pabalikon, ug nangutana kon giunsa sa batan-ong lalaki pagkahibalo nga adunay mga palid nga bulawan sa dapit diin iya kining nakaplagan. Mitubag ko nga ang usa ka anghel sa Dios mipadayag niini ngadto kaniya."},{"verse":65,"text":"“Dayon gisultihan ko niya, ‘Pakit-a ko niana nga sertipiko.’ Gikuha ko kini gikan sa akong bulsa ug gihatag kini kaniya, sa dihang gikuha niya kini ug gigisi-gisi, nag-ingon nga wala na kanang mga butanga karon sama sa pagpangalagad sa mga anghel, ug kon dad-on ko ang mga palid ngadto kaniya iya kining hubaron. Gisultihan nako siya nga adunay bahin sa mga palid nga nakaselyo, ug nga gidid-an ako sa pagdala niini. Mitubag siya, ‘Dili ako makabasa og sinelyohan nga basahon.’ Gibiyaan nako siya ug miadto kang Dr. Mitchell, kinsa mipamatuod sa gisulti ni Professor Anthon kabahin sa mga titik ug sa paghubad.”"},{"verse":66,"text":"Sa ika-5 nga adlaw sa Abril 1829, miabot si Oliver Cowdery sa akong balay, hangtod nianang panahona wala pa gayod ako makahimamat kaniya. Misulti siya kanako nga nagtudlo siya sa eskuwelahan sa kasilinganan diin ang akong amahan nagpuyo, ug ang akong amahan ingon nga usa sa mga nagpa-eskuwela og mga bata sa maong eskuwelahan, mipuyo siya sa mubong panahon sa iyang balay, ug samtang nagpuyo didto, ang pamilya miasoy ngadto kaniya sa mga hitabo sa akong pagkadawat sa mga palid, ug tungod niana mianhi siya aron magpakisayod bahin kanako."},{"verse":67,"text":"Duha ka adlaw human sa pag-abot ni G. Cowdery (ang ika-7 nga adlaw sa Abril) gisugdan nako ang paghubad sa Basahon ni Mormon, ug misugod siya sa pagsulat alang kanako."},{"verse":68,"text":"Nagpadayon gihapon kami sa buhat sa paghubad, sa dihang, sa sunod nga bulan (Mayo 1829), kami usa ka adlaw niana miadto sa kakahoyan aron sa pag-ampo ug pagpangutana sa Ginoo kabahin sa bunyag alang sa kapasayloan sa mga sala, nga among nabasa sa paghubad sa mga palid. Samtang nagbuhat kami sa ingon, nag-ampo ug nagtawag ngadto sa Ginoo, usa ka sulugoon nga gikan sa langit mikunsad sa usa ka panganod sa kahayag, ug samtang nagpandong sa iyang mga kamot kanamo, siya miordina kanamo, nga nag-ingon:"},{"verse":69,"text":"Diha kaninyo akong kauban nga mga sulugoon, sa ngalan sa Mesiyas, akong itugyan ang Pagkapari ni Aaron, nga naghupot sa mga yawe sa pagpangalagad sa mga anghel, ug sa ebanghelyo sa paghinulsol, ug sa bunyag pinaagi sa pagpaunlod alang sa kapasayloan sa mga sala; ug kini dili na pagakuhaon pag-usab gikan sa yuta hangtod nga ang mga anak ni Levi maghalad pag-usab og halad ngadto sa Ginoo diha sa pagkamatarong."},{"verse":70,"text":"Miingon siya nga kining Aaronic nga Pagkapari walay gahom sa pagpandong sa mga kamot alang sa gasa sa Espiritu Santo, apan nga kini kinahanglan nga itugyan ngari kanamo sa umaabot; ug misugo siya kanamo sa paglakaw ug pagpabunyag, ug mihatag kanamo og mga pamaagi nga ako mobunyag kang Oliver Cowdery, ug nga inig kahuman siya mobunyag kanako."},{"verse":71,"text":"Sumala niana miadto kami ug gibunyagan. Ako ang unang mibunyag kaniya, ug pagkahuman siya mibunyag kanako—pagkahuman niadto akong gipandong ang akong mga kamot diha sa iyang ulo ug miordina kaniya sa Aaronic nga Pagkapari, ug human niana siya mipandong sa iyang mga kamot ngari kanako ug miordina kanako sa mao gihapon nga Pagkapari—kay sa ingon niana kami gisugo.*"},{"verse":72,"text":"Ang sulugoon nga miduaw kanamo niini nga higayon ug mitugyan niini nga Pagkapari ngari kanamo, misulti nga ang iyang ngalan mao si Juan, kadto gihapon nga gitawag og Juan Bautista sa Bag-ong Tugon, ug nga siya nagtuman sa panudlo ni Pedro, Santiago ug Juan, nga naghupot sa mga yawe sa Pagkapari ni Melchizedek, diin nga Pagkapari, siya miingon, sa angay nga panahon itugyan ngari kanamo, ug nga ako pagatawgon nga unang Elder sa Simbahan, ug siya (Oliver Cowdery) ang ikaduha. Sa ikanapulo ug lima nga adlaw kadto sa Mayo 1829, nga kami giordinahan ubos sa kamot niini nga sulugoon, ug gibunyagan."},{"verse":73,"text":"Dihadiha dayon sa among pagkawas gikan sa tubig human kami mabunyagi, nakasinati kami og mahinungdanon ug mahimayaon nga mga panalangin gikan sa atong Langitnong Amahan. Human dayon sa akong pagbunyag ni Oliver Cowdery ang Espiritu Santo mikunsad ngadto kaniya, ug mibarog siya ug nanagna sa daghang butang nga sa dili madugay mahitabo. Ug usab, sa wala madugay sa iyang pagbunyag kanako, nakaangkon usab ako sa espiritu sa pagpanagna, unya, samtang nagbarog, nanagna ko mahitungod sa pag-uswag niini nga Simbahan, ug daghan pang butang nga may kalabotan sa Simbahan, ug niini nga henerasyon sa katawhan. Napuno kami sa Espiritu Santo, ug nagmaya diha sa Dios sa among kaluwasan."},{"verse":74,"text":"Kay ang among mga hunahuna nadan-agan na karon, nagsugod kami sa pag-angkon og salabotan sa mga kasulatan, ug ang tinuod nga kahulogan ug katuyoan sa ilang labaw nga misteryoso nga mga panultihon gipadayag ngari kanamo sa paagi nga dili gayod unta namo mahibaloan, ni sukad mahunahuna. Niini nga higayon napugos kami sa pagtago sa mga hitabo nga may kalabotan sa pagdawat sa Pagkapari ug sa among pagbunyag, tungod sa tinguha sa pagpanglutos nga dayag na diha sa kasilinganan."},{"verse":75,"text":"Gihulga kami nga gubton, matag karon ug unya, ug kini, usab, pinaagi sa mga magtutudlo sa relihiyon. Ug ang ilang mga katuyoan sa paggubot kanamo napugngan lamang pinaagi sa gahom sa pamilya sa amahan sa akong asawa (ubos sa Balaanon nga pagbantay), kinsa nakigsuod kaayo kanako, ug kinsa supak kaayo sa mga kagubot ug andam nga ako magpadayon sa buhat sa paghubad nga walay kasamok; ug busa mitanyag ug misaad kanamo og panalipod gikan sa mga pamaagi nga supak sa balaod, kutob sa ilang mahimo."},{"verse":76,"text":"Si Oliver Cowdery mihulagway niini nga mga hitabo sa ingon niini nga paagi: “Kini ang mga adlaw nga dili gayod angay makalimtan—nga maglingkod ubos sa tunog sa tingog nga gidiktahan sa inspirasyon sa langit, mipahigmata sa tumang pagpasalamat niini nga dughan! Adlaw-adlaw mipadayon ko, sa walay hunong, sa pagsulat gikan sa iyang ba-ba, samtang gihubad niya gamit ang Urim ug Tumim, o, sama sa giingon sa mga Nephita, mga ‘maghuhubad,’ ang kasaysayan o talaan nga gitawag og ‘Ang Basahon ni Mormon.’"},{"verse":77,"text":"“Ang pagkamatikod, bisan sa pipila ka pulong, sa makapaikag nga asoy nga gihatag ni Mormon ug sa iyang matinud-anong anak, nga si Moroni, mahitungod sa katawhan nga kanhi gihigugma ug gipalabi sa langit, molabaw pa kay sa akong gilaraw karon; busa sa umaabot nga panahon ko na lamang kini buhaton, ug, sama sa akong gisulti sa pasiuna, molaktod ngadto sa pipila ka hitabo nga sumpay sa pagtubo niini nga Simbahan, nga tingali makapahimuot sa pipila ka kaliboan kinsa miabante, taliwala sa mga pagsaway sa mga panatiko ug pasangil sa mga maot, ug midawat sa Ebanghelyo ni Kristo."},{"verse":78,"text":"“Walay tawo, nga anaa sa ilang matarong nga kabuot, nga makahubad ug makasulat sa mga pagtudlo nga gihatag ngadto sa mga Nephita gikan sa ba-ba sa Manluluwas, mahitungod sa tukmang paagi kon unsaon pagtukod sa mga tawo ang Iyang Simbahan, ug ilabi na kon ang korapsiyon nakasabwag og pagduhaduha sa tanang matang ug paagi nga gisunod sa mga tawo, nga dili magtinguha og kahigayonan sa pagpakita sa pagkamatinguhaon sa kasingkasing pinaagi sa pagpalubong diha sa tubigon nga lubnganan, aron makatubag sa maayong tanlag pinaagi sa pagkabanhaw ni Jesukristo.’"},{"verse":79,"text":"“Human magsulat sa asoy nga gihatag mahitungod sa pagpangalagad sa Manluluwas ngadto sa salin sa binhi ni Jacob, dinhi niining dakong kayutaan, sayon kaayong makita, sama sa gisulti sa propeta nga maoy mahitabo, nga ang kangitngit motabon sa yuta ug tumang kangitngit sa mga hunahuna sa katawhan. Sa dugang pagpamalandong sayon kaayong makita nga taliwala sa dakong kagubot ug kaguliyang mahitungod sa relihiyon, walay bisan usa nga adunay pagtugot gikan sa Dios sa pagpangalagad sa mga ordinansa sa Ebanghelyo. Kay tingali ikapangutana, ang mga tawo ba adunay pagtugot sa pagpangalagad sa ngalan ni Kristo, nga naglimod sa mga pagpadayag, samtang ang pagpamatuod mahitungod Kaniya walay lain kon dili ang espiritu sa panagna, ug ang Iyang relihiyon gipasikad, ug gitukod, ug gipaluyohan sa direkta nga mga pagpadayag, sa tanang panahon sa kalibotan sa dihang may katawhan Siya sa yuta? Kon kini nga mga kamatuoran gilubong, ug mabinantayong gitago sa mga tawo kansang malimbongong patigayon mabutang unta sa kakuyaw sa higayon nga matugotan sa pagdan-ag diha sa mga nawong sa tawo, wala na kini matago gikan kanato; ug naghulat na lamang kita sa sugo nga ihatag ‘Barog ug pagpabunyag.’"},{"verse":80,"text":"“Dili pa lamang kini dugay nga gitinguha sa wala pa kini matuman. Ang Ginoo, nga buhong sa kaluoy, ug kanunay nga matinguhaong motubag sa makanunayong pag-ampo sa mapaubsanon, human kami mitawag Kaniya sa tim-os nga paagi, layo sa mga puluy-anan sa katawhan, mikunsad aron sa pagpadayag kanamo sa Iyang kabubut-on. Sa kalit lang, ingon nga gikan sa taliwala sa kahangtoran, ang tingog sa Manunubos namulong og kalinaw ngari kanamo, samtang giwaling ang tabil ug nanaog ang anghel sa Dios nga sinul-oban og himaya, ug mihatag sa mahingawaong gipaabot nga mensahe, ug sa mga yawe sa Ebanghelyo sa paghinulsol. Pagkamalipayon! pagkaanindot! pagkatalagsaon! Samtang ang kalibotan giuyog ug nalinga—samtang minilyon ang nagpangapa sama sa buta nga nagpangapa sa bungbong, ug samtang ang tanang katawhan anaa sa pagduhaduha, isip kinatibuk-an, ang among mga mata nakakita, ang among mga dalunggan nakadungog, sama sa kahayag sa adlaw; oo, labaw pa—ibabaw sa silaw sa Mayo nga bidlisiw sa adlaw, nga diha dayon misabwag sa iyang kahayag sa nawong sa kinaiyahan! Dayon ang iyang tingog, bisan hinay, midulot sa kinauyokan, ug ang iyang mga pulong, ‘Ako ang inyong isigka sulugoon,’ mitunaw sa tanang kahadlok. Naminaw kami, mitutok kami, midayeg kami! ‘Tingog kadto sa usa ka anghel gikan sa himaya, ‘mensahe kadto gikan sa Labing Halangdon! Ug samtang nadungog namo nagmaya kami, samtang ang Iyang gugma mipainit sa among kalag, ug gipandongan kami sa panan-awon sa Labawng Makagagahom! Hain ang luna sa pagduhaduha? Wala; ang pagduhaduha nahanaw, ang pagduda naunlod nga dili na gayod molutaw, samtang ang binuhat-buhat nga mga istorya ug pagpangilad nawala sa hangtod!"},{"verse":81,"text":"“Apan, mahal nga igsoon, hunahunaa, hunahunaa og dugang sa makadiyot, unsa nga kalipay ang mipuno sa among mga kasingkasing, ug sa unsa nga katingala kami miyukbo, (kay kinsa ang dili moluhod sa sama nga panalangin?) sa diha nga kami nakadawat ubos sa iyang kamot sa Balaang Pagkapari ingon sa iyang gipamulong, ‘Diha kaninyo akong kauban nga mga sulugoon, sa ngalan sa Mesiyas, ako motugyan niining Pagkapari ug niining pagtugot, nga magpabilin diha sa yuta, nga ang mga Anak ni Levi mohalad pa og usa ka halad ngadto sa Ginoo diha sa pagkamatarong!’"},{"verse":82,"text":"“Dili ako mosulay sa paghulagway diha kaninyo sa mga gibati niini nga kasingkasing, ni sa harianong katahom ug himaya nga mialirong kanamo niini nga higayon; apan kamo motuo kanako kon ako moingon, nga ang yuta, ni ang mga tawo, uban sa kahanas sa panahon, dili makahimo sa pagpahayag og pinulongan sama ka makapahinam ug hamili nga paagi sama niining balaan nga personahe. Dili; ni kini nga yuta adunay gahom sa paghatag sa hingpit nga kalipay, sa pagtugyan sa kalinaw, o pagtugkad sa kaalam nga gilangkob sa matag han-ay samtang gihatag kini pinaagi sa Balaang Espiritu! Ang tawo mahimong molingla sa iyang isigkatawo, ang pagpanglingla mahimong mosunod sa pagpanglingla, ug ang mga anak sa usa nga daotan mahimong adunay gahom sa pagtental sa mga buang ug sa walay kinaadman, hangtod ang kawang apan binuhat-buhat nga istorya molibog sa daghan, ug ang bunga sa bakak modala sa iyang sulog sa mga taphaw og hunahuna ngadto sa lubnganan; apan ang usa ka paghikap sa tudlo sa iyang gugma, oo, usa ka silaw sa himaya gikan sa ibabaw nga kalibotan, o usa ka pulong gikan sa ba-ba sa Manluluwas, gikan sa sabakan sa kahangtoran, mohampak sa tanan niini ngadto sa pagkawalay hinungdan, ug mopapas niini sa hunahuna hangtod sa hangtod. Ang kaseguroan nga kami anaa sa atubangan sa usa ka anghel, ang pagkatinuod nga kami nakadungog sa tingog ni Jesus, ug ang kamatuoran nga walay buling samtang kini misanap gikan sa usa ka putli nga personahe, gidiktahan pinaagi sa kabubut-on sa Dios, alang kanako dili mahulagway, ug isipon ko sa kanunay kining pagpakita sa kaayo sa Manluluwas uban sa katingala ug pagpasalamat samtang tugotan ako sa paghulat; ug diha niana nga mga mansyon diin ang kahingpitan nagpuyo ug ang sala dili gayod moabot, manghinaot ko nga makasimba nianang adlaw diin dili gayod matapos.”—Messenger and Advocate,. vol. 1 (Oktubre 1834), pp. 14–16."}]}]},{"id":"articles-of-faith","title":"Mga Artikulo sa Pagtuo","englishTitle":"Articles of Faith","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Nagatuo kami sa Dios, ang Amahan sa Kahangtoran, ug sa Iyang Anak, si Jesukristo, ug sa Espiritu Santo."},{"verse":2,"text":"Nagatuo kami nga ang mga tawo pagasilotan sa ilang kaugalingong mga sala, ug dili tungod sa mga kalapasan ni Adan."},{"verse":3,"text":"Nagatuo kami nga pinaagi sa Pag-ula ni Kristo, ang tanang tawo maluwas, pinaagi sa pagkamasulundon sa mga balaod ug sa mga ordinansa sa Ebanghelyo."},{"verse":4,"text":"Nagatuo kami nga ang unang mga baroganan ug mga ordinansa sa Ebanghelyo mao ang: una, Pagtuo ni Ginoong Jesukristo; ikaduha, Paghinulsol; ikatulo, Bunyag pinaagi sa pagpaunlod alang sa kapasayloan sa mga sala; ikaupat, Pagpandong sa mga kamot alang sa gasa sa Espiritu Santo."},{"verse":5,"text":"Nagatuo kami nga ang tawo kinahanglan gayod nga tawagon sa Dios, pinaagi sa propesiya, ug pinaagi sa pagpandong sa mga kamot niadtong adunay awtoridad, sa pagsangyaw sa Ebanghelyo ug sa pagpangalagad sa mga ordinansa niini."},{"verse":6,"text":"Nagatuo kami sa samang kapunongan nga anaa sa Karaang Simbahan, nga mao ang mga apostoles, mga propeta, mga pastor, mga magtutudlo, mga ebanghelista, ug uban pa."},{"verse":7,"text":"Nagatuo kami sa gasa sa mga pinulongan, propesiya, pagpadayag, mga panan-awon, pagpang-ayo, paghubad sa mga pinulongan, ug uban pa."},{"verse":8,"text":"Nagatuo kami nga ang Biblia pulong sa Dios kon gihubad kini sa husto nga paagi; nagatuo usab kami nga ang Basahon ni Mormon pulong sa Dios."},{"verse":9,"text":"Nagatuo kami sa tanang gipadayag sa Dios, sa tanang gipadayag Niya karon, ug kami nagatuo nga mopadayag pa siya og daghang dagko ug mahinungdanong mga butang kalabot sa Gingharian sa Dios."},{"verse":10,"text":"Nagatuo kami sa tinuod gayod nga pagpundok sa Israel ug sa pagpahiuli sa Napulo ka Tribo; nga ang Zion (ang Bag-ong Jerusalem) pagatukoron sa kayutaan sa Amerika; nga si Kristo maghari sa personal mismo dinhi sa yuta; ug, nga ang yuta mabag-o ug makadawat sa iyang paraisohanon nga himaya."},{"verse":11,"text":"Giangkon namo ang kahigayonan sa pagsimba sa Labing Makagagahom nga Dios sumala sa mga pagdiktar sa among kaugalingong tanlag, ug nagatugot sa tanang tawo sa samang kahigayonan, tugotan sila nga mosimba sa bisan unsang paagi, asa, kinsa ang gusto nila."},{"verse":12,"text":"Nagatuo kami sa kamandoan ubos sa mga hari, mga presidente, mga magmamando, ug sa mga maghuhukom, sa pagsunod, pagtahod, ug sa pagpaluyo sa balaod."},{"verse":13,"text":"Nagatuo kami sa pagkamatinuoron, pagkamatinud-anon, pagkaputli, pagkamanggiluy-on, pagka mahiyason, ug sa pagbuhat og maayo ngadto sa tanang katawhan; sa pagkatinuod, makasulti kami nga gisunod namo ang pagpahimatngon ni Pablo—Nagatuo kami sa tanang butang, kami nagalaom sa tanang butang, nakalahutay kami sa daghang butang, ug naglaom nga makahimo sa paglahutay sa tanang butang. Kon adunay mga butang nga mahiyason, matahom, o maayo og dungog o dalaygon, nagtinguha kami sa pagpangita niining mga butanga."},{"verse":14,"text":"Joseph Smith."}]}]}]'),g={language:"ceb",sourceLanguage:"ceb",sourcePage:a,books:n};export{g as r};
